(window.GIM_TUR_P=window.GIM_TUR_P||{})["SEH.2"]={"from":141,"s":[["הָאִשָּׁה יְכוֹלָה לַעֲשׂוֹת שָׁלִיחַ לְקַבֵּל גִּטָּהּ מִיַּד שְׁלִיחַ בַּעְלָהּ. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁעָשְׂתָה שָׁלִיחַ אַחֵר לְקַבֵּל מִמֶּנּוּ. אֲבָל אִם אָמְרָה לִשְׁלִיחַ הַבַּעַל: יִהְיֶה גֵּט זֶה פִּקָּדוֹן אֶצְלְךָ, אוֹ שֶׁאָמְרָה לוֹ: הֲרֵי אַתָּה שָׁלִיחַ לְקַבְּלוֹ לִי, \u0005 וְיֵשׁ אוֹמְרִים אֲפִלּוּ לֹא אָמְרָה לוֹ רַק: תִּתְקַּבֵּל \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן וְהָרַשְׁבָּ\"א)\u0006, \u0010c0\u0011 הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת, עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ, \u0010c1\u0011 וּמִשֶּׁיַּגִּיעַ לְיָדָהּ תִּתְגָּרֵשׁ וַדַּאי. \u0005 הַגָּה: אָמְרָה הָאִשָּׁה לִשְׁלוּחָהּ לְקַבֵּל הַגֵּט \u0010c2\u0011 \u0006 \u0005 מִיַּד בַּעְלָהּ, אֵין לְקַבְּלוֹ מִיַּד שְׁלוּחוֹ. אֲבָל אָמְרָה: קַבֵּל גֵּט מִבַּעְלִי, יָכוֹל לְקַבְּלוֹ מִיַּד שְׁלוּחוֹ \u0006 \u0005(תְּשׁוּבַת רַשְׁבָּ\"א אֶלֶף \u0010c3\u0011 ר\"נ)\u0006. וְיֵשׁ אוֹמְרִים שֶׁאֵין הָאִשָּׁה יְכוֹלָה לַעֲשׂוֹת שָׁלִיחַ לְקַבֵּל מִיַּד שְׁלִיחַ בַּעְלָהּ:\nנַעֲרָה הַמְאֹרָסָה, אַף עַל פִּי שֶׁמִּתְגָּרֶשֶׁת בְּקַבָּלַת גִּטָּהּ בְּיָדָהּ כְּמוֹ קַבָּלַת אָבִיהָ, אָבִיהָ יָכוֹל לַעֲשׂוֹת שְׁלִיחַ קַבָּלָה; אֲבָל הִיא אֵינָהּ יְכוֹלָה לַעֲשׂוֹת שְׁלִיחַ קַבָּלָה, אֶלָּא אִם כֵּן אֵין לָהּ אָב, אוֹ שֶׁנִּשֵּׂאת:\nקְטַנָּה, אֲפִלּוּ אֵין לָהּ אָב, אוֹ שֶׁנִּשֵּׂאת, אֵינָהּ יְכוֹלָה לַעֲשׂוֹת שְׁלִיחַ קַבָּלָה; אֲבָל אָבִיהָ יָכוֹל לַעֲשׂוֹתוֹ, אִם הִיא אֲרוּסָה:\nהַמְקַדֵּשׁ קְטַנָּה עַל יְדֵי אָבִיהָ, וְגֵרְשָׁה כְּשֶׁהִיא קְטַנָּה \u0005 בְּעוֹדָהּ אֲרוּסָה וְאָבִיהָ חַי \u0006 \u0005(טוּר)\u0006, אָבִיהָ מְקַבֵּל גִּטָּהּ, וְלֹא הִיא \u0010c4\u0011 שֶׁלֹּא מִדַּעְתּוֹ. \u0010c5\u0011 וְיֵשׁ אוֹמְרִים שֶׁהִיא יְכוֹלָה לְקַבֵּל גִּטָּהּ:\nנִשֵּׂאת, אֵין אָבִיהָ יָכוֹל לְקַבֵּל גִּטָּהּ.\nקִדְּשָׁהּ אָבִיהָ כְּשֶׁהִיא קְטַנָּה, וּמֵת, אוֹ שֶׁנִּשֵּׂאת, אִם מַבְחֶנֶת בֵּין גִּטָּהּ לְדָבָר אַחֵר, דְּהַיְנוּ שֶׁנּוֹתְנִים לָהּ צְרוֹר וּזְרַקְתּוֹ, אֱגוֹז וְנוֹטַלְתּוֹ, \u0010c6\u0011 וְיֵשׁ אוֹמְרִים דְּהַיְנוּ מִשֶּׁתַּגִּיעַ לְעוֹנַת הַפָּעוֹטוֹת, \u0005 דְּהַיְנוּ בַּת שִׁית אוֹ בַּת שֶׁבַע, כָּל חַד וְחַד לְפוּם חֻרְפֵהּ \u0006 \u0005(טוּר)\u0006, מִתְגָּרֶשֶׁת עַל יְדֵי עַצְמָהּ. וְאִם אֵינָהּ מַבְחֶנֶת, וְגֵרְשָׁהּ עַל יְדֵי עַצְמָהּ, אֵינָהּ מְגֹרֶשֶׁת. אֲבָל \u0010c7\u0011 עַל יְדֵי אָבִיהָ מִתְגָּרֶשֶׁת, \u0010c8\u0011 אֲפִלּוּ אֵינָהּ מַבְחֶנֶת. וְיֵשׁ מִי שֶׁחוֹלֵק וְאוֹמֵר שֶׁכָּל שֶׁאֵינָהּ מַבְחֶנֶת אֵינָהּ מִתְגָּרֶשֶׁת אֲפִלּוּ עַל יְדֵי אָבִיהָ. \u0005 הַגָּה: וְעַיֵּן לְקַמָּן בְּסֵדֶר הַגֵּט סָעִיף צ\"ו כֵּיצַד כּוֹתְבִין לִקְטַנָּה הַמִּתְגָּרֶשֶׁת עַל יְדֵי אָבִיהָ: \u0006\nכָּל הֵיכָא שֶׁיֵּשׁ לִקְטַנָּה יָד לְקַבֵּל גִּטָּהּ, יֵשׁ לָהּ תּוֹרַת חָצֵר \u0005 אוֹ ד' אַמּוֹת \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ה)\u0006 לְקַבְּלוֹ, כְּשֵׁם שֶׁיֵּשׁ לִגְדוֹלָה:\nכְּשֶׁהִיא עוֹשָׂה שָׁלִיחַ לְקַבָּלָה, צְרִיכָה לַעֲשׂוֹתוֹ בִּפְנֵי שְׁנֵי עֵדִים. וְצָרִיךְ לְקַבֵּל הַגֵּט בִּפְנֵי שְׁנַיִם, אֲפִלּוּ אִם הַשְּׁנַיִם הַמְּעִידִים עַל הַשְּׁלִיחוּת הֵם מְעִידִים עַל קַבָּלַת גִּטָּהּ, אוֹ אֶחָד מֵעִיד עַל הַשְּׁלִיחוּת וְאֶחָד עַל הַקַּבָּלָה וְאֶחָד מִצְטָרֵף עִם כָּל אֶחָד לִהְיוֹת מֵעִיד עַל זֶה וְעַל זֶה. \u0005 הַגָּה: \u0010c9\u0011 וּלְכַתְּחִלָּה לֹא יִמְסֹר הַבַּעַל הַגֵּט לְיַד הַשָּׁלִיחַ, עַד שֶׁיְּבָרֵר תְּחִלָּה שֶׁנַּעֲשָׂה שְׁלִיחַ קַבָּלָה בְּעֵדִים \u0006 \u0005(מָרְדְּכַי רֵישׁ הִתְקַבֵּל בְּשֵׁם מוהר\"ם)\u0006:\nמַה שֶּׁצָּרִיךְ שְׁנֵי עֵדִים עַל הַקַּבָּלָה, דַּוְקָא כְּשֶׁאֵין הַשָּׁלִיחַ כָּשֵׁר; אֲבָל אִם הוּא כָּשֵׁר, \u0010c10\u0011 מִצְטָרֵף עִם עֵד אֶחָד. וְיֵשׁ מִי שֶׁנִּרְאֶה מִדְּבָרָיו שֶׁחוֹלֵק עַל זֶה. \u0005 וְהוּא הַדִּין לִשְׁלִיחוּת לְהוֹלָכָה: \u0006\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶּׁצָּרִיךְ עֵדֵי קַבָּלָה, כְּשֶׁאָבַד הַגֵּט אוֹ נִקְרַע. אֲבָל אִם הָיָה הַגֵּט יוֹצֵא מִתַּחַת יַד שְׁלִיחַ קַבָּלָה, \u0010c11\u0011 אֵינוֹ צָרִיךְ עֵדֵי קַבָּלָה. \u0005 וְעַיֵּן לְקַמַּן סִימָן זֶה סָעִיף י\"ג: \u0010c12\u0011 \u0006\nאֵין שְׁלִיחַ לְהוֹלָכָה צָרִיךְ עֵדִים, אִם הוֹדוּ הַשָּׁלִיחַ וְהַמְשַׁלֵּחַ. \u0010c13\u0011 וְאִם הַמְשַׁלֵּחַ כּוֹפֵר, הֲרֵי זֶה סָפֵק. וְיֵשׁ אוֹמְרִים שֶׁשְּׁלִיחַ הוֹלָכָה צָרִיךְ לְמַנּוֹתוֹ בְּעֵדִים. \u0005 הַגָּה: \u0010c14\u0011 מִיהוּ, הַשָּׁלִיחַ נֶאֱמָן לוֹמַר שֶׁעֲשָׂאוֹ \u0006 \u0005 בְּעֵדִים, וְאֵין צָרִיךְ עֵדוּת עַל כָּךְ \u0006 \u0005(רַבִּי יְרֻחָם ח\"ג \u0010c15\u0011 נכ\"ד)\u0006. \u0005 וְנוֹהֲגִים לְהַצְרִיךְ הַרְשָׁאָה וְעֵדִים עַל הַרְשָׁאָה שֶׁנַּעֲשָׂה שָׁלִיחַ. וְעַיֵּן לְקַמָּן סָעִיף כ\"ד: \u0006\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵין שְׁלִיחַ הָאִישׁ צָרִיךְ עֵדִים, כְּשֶׁמָּסַר לָהּ גֵּט שֶׁחֲתוּמִים בּוֹ עֵדִים. אֲבָל אִם אֵין עֵדִים חֲתוּמִים בּוֹ, וְהָלַךְ הַשָּׁלִיחַ וּמְסָרוֹ לָהּ בִּפְנֵי עֵדִים, \u0010c16\u0011 הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁשְּׁלִיחַ הוֹלָכָה וּשְׁלִיחַ הוֹבָאָה אֵין צָרִיךְ לַעֲשׂוֹתוֹ בְּעֵדִים, וְיֵשׁ מִי שֶׁחוֹלֵק. \u0005 הַגָּה: כֶּפֶל דְּבָרִים הֵן בְּכָאן, כִּי בָּבָא זוֹ נִתְבָּאֵר סָעִיף י\"א. וְיֵשׁ מַחֲלֹקֶת בְּדִין זֶה בְּדֶרֶךְ אַחֵר, דְּיֵשׁ אוֹמְרִים דִּשְׁלִיחַ הוֹלָכָה אִם מָסַר לָהּ הַגֵּט בֵּינוֹ לְבֵינָהּ, \u0010c17\u0011 וְאִי אֶפְשָׁר לַחֲזֹר וְלִתְּנוֹ לָהּ בִּפְנֵי שְׁנַיִם, דִּמְגֹרֶשֶׁת מֵאַחַר שֶׁהַגֵּט יוֹצֵא מִתַּחַת יָדָהּ בְּחוֹתְמָיו \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּפָסוּל \u0006 \u0005(טוּר בְּשֵׁם הַגְּאוֹנִים)\u0006. \u0005 מִיהוּ, אִם הַגֵּט מְקֻיָּם בְּחוֹתְמָיו, מִתַּחַת יָדָהּ, אֵינָהּ צְרִיכָה שֶׁתָּבִיא עֵדֵי מְסִירָה בְּפָנֵינוּ, רַק שֶׁאוֹמֶרֶת שֶׁקִּבְּלָה אוֹתוֹ בִּפְנֵי שְׁנַיִם כָּרָאוּי \u0006 \u0005(טוּר)\u0006. \u0005 וְהוּא הַדִּין בִּשְׁלִיחַ קַבָּלָה מִן הַבַּעַל: \u0006\nבֵּין שְׁלִיחַ קַבָּלָה בֵּין שְׁלִיחַ הוֹלָכָה \u0010c18\u0011 אֵין צָרִיךְ שֶׁיִּשְׁמַע מִפִּיהֶם שֶׁמְּמַנִּים אוֹתוֹ שָׁלִיחַ. לְפִיכָךְ, בֵּין הָאִישׁ בֵּין הָאִשָּׁה יְכוֹלִים לַעֲשׂוֹת בִּפְנֵי עֵדִים שָׁלִיחַ הָעוֹמֵד בְּמָקוֹם אַחֵר, וְהָעֵדִים כּוֹתְבִים וְחוֹתְמִים שֶׁמִּנָּה לִפְלוֹנִי שָׁלִיחַ. \u0005 וְעַיֵּן לְקַמָּן סָעִיף ל\"ה: \u0006\nבַּעַל שֶׁעָשָׂה שָׁלִיחַ לְהוֹלָכָה, צָרִיךְ שֶׁיֹּאמַר לוֹ: תֵּן גֵּט זֶה לְאִשְׁתִּי, אוֹ שֶׁיֹּאמַר לַסוֹפֵר וְלָעֵדִים שֶׁיִּכְתְּבוּ וְיַחְתְּמוּ גֵּט וְיִתְּנוּ לְאִשְׁתּוֹ, אוֹ לָשׁוֹן שֶׁמַּשְׁמָעוֹ שֶׁיְּגָרְשׁוּהָ, \u0010c19\u0011 כְּמוֹ: גָּרְשׁוּהָ אוֹ שַׁלְּחוּהָ אוֹ שִׁבְקוּהָ אוֹ תִּרְכוּהָ אוֹ כִּתְבוּ אִגֶּרֶת וּתְנוּ לָהּ; אֲבָל אִם אָמַר: פַּטְּרוּהָ, פַּרְנְסוּהָ, עֲשׂוּ לָהּ כַּדָּת, עֲשׂוּ לָהּ כַּנִּמּוּס, עֲשׂוּ לָהּ כָּרָאוּי, \u0010c20\u0011 לֹא אָמַר כְּלוּם. אָמַר לָהֶם: עִזְבוּהָ, הוֹצִיאוּהָ, הַתִּירוּהָ, הַנִּיחוּהָ, הוֹעִילוּ לָהּ, הֲרֵי זֶה סָפֵק:\nהָאוֹמֵר: כִּתְבוּ גֵּט לְאִשְׁתִּי, הֲרֵי אֵלּוּ כּוֹתְבִין וְנוֹתְנִין לַבַּעַל בְּיָדוֹ, וְאֵין נוֹתְנִין לְאִשְׁתּוֹ עַד שֶׁיֹּאמַר לָהֶם לִתֵּן לָהּ. וְאִם נָתְנוּ לָהּ, אֵינוֹ גֵּט. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּבָרִיא. אֲבָל \u0010c21\u0011 בִּמְסֻכָּן, וְהוּא אָדָם שֶׁקָּפַץ עָלָיו הַחֹלִי בִּמְהֵרָה וְהִכְבִּיד עָלָיו חָלְיוֹ מִיָּד, וְהַיּוֹצֵא בְּקוֹלָר, אֲפִלּוּ עַל עִסְקֵי מָמוֹן, וְהַמְפָרֵשׂ בַּיָּם \u0010c22\u0011 וְהַיּוֹצֵא בְּשַׁיָּרָא, וְאָמַר: כִּתְבוּ גֵּט לְאִשְׁתִּי, הֲרֵי אֵלּוּ יִכְתְּבוּ וְיִתְּנוּ לָהּ, שֶׁהַדָּבָר יָדוּעַ שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא לִכְתֹּב וְלִתֵּן לָהּ:\nבָּרִיא שֶׁאָמַר: כִּתְבוּ גֵּט לְאִשְׁתִּי, וְכָתְבוּ וְנָתְנוּ לָהּ, וְהָרַג עַצְמוֹ \u0010c23\u0011 מִיָּד, כְּגוֹן שֶׁהִשְׁלִיךְ עַצְמוֹ מִן הַגַּג, אוֹ הִפִּיל עַצְמוֹ לַיָּם, הֲרֵי זֶה גֵּט כָּשֵׁר. וְאִם לֹא כְּתָבוּהוּ, כּוֹתְבִין וְנוֹתְנִין לָהּ \u0010c24\u0011 כָּל זְמַן שֶׁיֵּשׁ בּוֹ נְשָׁמָה. עָלָה לַגַּג וּדְחָפַתּוּ הָרוּחַ וְנָפַל וָמֵת, אֵינוֹ גֵּט:\nסָפֵק מֵעַצְמוֹ נָפַל סָפֵק הָרוּחַ דְּחָפַתּוּ; \u0010c25\u0011 אִם לְאַלְתָּר נָפַל, הֲרֵי זֶה גֵּט; וְאִם לֹא נָפַל לְאַלְתָּר, הֲרֵי זֶה סָפֵק:\nוְכֵן מִי שֶׁהָיָה מֻשְׁלָךְ לַבּוֹר וְאָמַר: \u0010c26\u0011 כָּל הַשּׁוֹמֵעַ קוֹלִי יִכְתֹּב גֵּט לְאִשְׁתִּי, וּפֵרַשׁ שְׁמוֹ וְשֵׁם אִשְׁתּוֹ, שֵׁם עִירוֹ וְשֵׁם עִירָהּ, הֲרֵי אֵלּוּ יִכְתְּבוּ [וְיִתְּנוּ] לָהּ. \u0010c27\u0011 וְאַף עַל פִּי שֶׁהֶעֱלוּהוּ וְלֹא הִכִּירוּהוּ, הֲרֵי זֶה כָּשֵׁר, שֶׁזֶּה כִּשְׁעַת הַסַכָּנָה הוּא, שֶׁכּוֹתְבִין וְנוֹתְנִין אַף עַל פִּי שֶׁאֵין מַכִּירִין. \u0010c28\u0011 וְיֵשׁ אוֹמְרִים דְּהָנֵי מִלֵּי שֶׁרָאוּ לוֹ דְּמוּת אָדָם וְחָזוּ לֵהּ נַמֵּי בָּבוּאָה דְּבָבוּאָה, הָא לָאו הָכִי חָיְשִׁינָן שֶׁמָּא שֵׁד הוּא, שֶׁדֶּרֶךְ הַשֵּׁדִים לִמָּצֵא בְּבוֹרוֹת וְכֵן בַּשָּׂדוֹת:\nאִם הָיוּ שָׁם שְׁלשָׁה, וְאָמַר: כָּל הַשּׁוֹמֵעַ קוֹלִי יִכְתֹּב גֵּט לְאִשְׁתִּי, אֶחָד כּוֹתֵב וּשְׁנַיִם חוֹתְמִים, וְאֵין צָרִיךְ מַעֲמַד כֻּלָּם, דְּאַף עַל גַּב דְּאָמַר: כָּל, לֹא הֲוֵי כְּאוֹמֵר: כֻּלְּכֶם כְּתֹבוּ:\nהָיוּ רַבִּים עוֹמְדִים בְּיַחַד, וְאָמַר: הוֹלִיכוּ גֵּט לְאִשְׁתִּי, אֵיזֶה מֵהֶם שֶׁיִּרְצֶה יוֹלִיךְ אוֹתוֹ בִּשְׁבִיל כֻּלָּם \u0005 וְעַיֵּן בְּסָמוּךְ סוֹף סָעִיף כ\"ג. \u0006 וְאִם אָמַר: שְׁנַיִם מִכֶּם יוֹלִיכוּהוּ, יוֹלִיכוּ שְׁנַיִם. אֲפִלּוּ הָיָה בִּכְלָלָם אָב וּבְנוֹ, דַּעְתּוֹ גַּם עַל הַבֵּן, \u0010c29\u0011 וְנַעֲשָׂה הַבֵּן שָׁלִיחַ בִּמְקוֹם הָאָב:\nוְהוּא הַדִּין לָאוֹמֵר לִשְׁלֹשָׁה: שְׁנַיִם מִכֶּם יִכְתְּבוּ גֵּט לְאִשְׁתִּי וְיַחְתְּמוּ וְיִתְּנוּ לָהּ, וְהָיָה בָּהֶם אָב וּבְנוֹ, בֵּין שֶׁחָתַם הַבֵּן עִם הָאַחֵר, בֵּין שֶׁחָתַם הָאָב עִם הָאַחֵר, הֲרֵי זֶה גֵּט כָּשֵׁר:\nאָמַר לַחֲבוּרָה: כֻּלְּכֶם הוֹלִיכוּהוּ, אֵינוֹ גֵּט עַד שֶׁיּוֹלִיכוּהוּ כֻּלָּם. וְהָאִדָּנָא תִּקְּנוּ חֲכָמִים שֶׁהָאוֹמֵר לְרַבִּים לְהוֹלִיךְ גֵּט לְאִשְׁתּוֹ, יֹאמַר: כָּל אֶחָד מִכֶּם יוֹלִיךְ גֵּט לְאִשְׁתִּי:\nמַה שֶּׁכָּתוּב בְּתִקּוּן שְׁטָרוֹת שְׁטַר הַרְשָׁאָה בְּשׁוֹלֵחַ גֵּט \u0010c30\u0011 מִמָּקוֹם לְמָקוֹם, \u0010c31\u0011 אֵין צָרִיךְ, אֶלָּא לְפִי שֶׁכָּתוּב בָּהּ שֶׁנּוֹתֵן הַבַּעַל רְשׁוּת לַעֲשׂוֹת כַּמָּה שְׁלוּחִים אֲפִלּוּ לֹא יֶחֱלֶה וְלֹא יֵאָנֵס. \u0005 הַגָּה: וְלָכֵן אִם נֶאֱבַד שְׁטָר הַרְשָׁאָה אוֹ נִפְסַל, וְהוּא שְׁעַת הַדְּחָק, נוֹתְנִין הַגֵּט בְּלֹא הַרְשָׁאָה \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ כ\"ו)\u0006. \u0005 וְהַשָּׁלִיחַ נֶאֱמָן עַל הַשְּׁלִיחוּת וְלוֹמַר שֶׁעֲשָׂאוֹ שָׁלִיחַ בְּעֵדִים, כְּמוֹ שֶׁנֶּאֱמָן לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם וְעַיֵּן לְקַמָּן סִימָן קמ\"ב סָעִיף ג'. אֲבָל לְכַתְּחִלָּה כּוֹתְבִין הַהַרְשָׁאָה בְּדִקְדּוּק, וְנִזְהָרִין שֶׁלֹּא לִכְתֹּב \u0006 \u0005 בָּהּ רָאשֵׁי תֵּיבוֹת \u0006 \u0005(בְּתִקוּן מהר\"י מִינְץ בְּשֵׁם מהרא\"י)\u0006. \u0010c32\u0011 \u0005 גַּם שֶׁלֹּא לְשַׁנּוֹת בָּהּ בִּדְבָרִים הַכְּתוּבִים בַּגֵּט, כְּגוֹן אִם כָּתוּב בַּגֵּט שֵׁם זַנְבִיל בְּב', לֹא יִכְתֹּב בַּהַרְשָׁאָה בְּוָי\"ו \u0006 \u0005(ג\"ז שָׁם)\u0006, \u0005 וְכָל כַּיּוֹצֵא בָּזֶה. וְנֻסַּח הַרְשָׁאָה, עַיֵּן בא\"ה סִימָן קמ\"א וּלְמַטָּה סָעִיף ל'. וּשְׁאָר דִּינִים וְסֵדֶר הַשְּׁלִיחוּת, עַיֵּן לְקַמָּן בְּסֵדֶר הַגֵּט. עֵדֵי הַרְשָׁאָה לֹא יִהְיוּ קְרוֹבִים זֶה לָזֶה, וְלֹא לָאִישׁ וְלֹא לָאִשָּׁה, \u0010c33\u0011 וְלֹא לְעֵדֵי \u0006 \u0005 הַגֵּט \u0006 \u0005(סֵדֶר גִּטִּין סי' ע\"ג)\u0006. \u0005 וְאִם נִמְצְאוּ עֵדֵי הַרְשָׁאָה פְּסוּלִים, \u0010c34\u0011 נִתְבַּטֵּל כָּל \u0006 \u0005 הַשְּׁלִיחוּת, שֶׁהֲרֵי הֵם מְעִידִים עַל עִקַּר הַשְּׁלִיחוּת וְשֶׁבִּפְנֵיהֶם עָשָׂה הַבַּעַל לַשָּׁלִיחַ, וְלֹא דָּמֵי לִשְׁאָר פְּסוּלֵי הַרְשָׁאָה, כֵּן נִרְאֶה לִי. וְנָהֲגוּ שֶׁהָרַב הַמְסַדֵּר הַגֵּט מְקַיֵּם הַהַרְשָׁאָה. וְיֵשׁ אוֹמְרִים דְּיֵשׁ לְקַיְּמָהּ בִּשְׁלֹשָה; מִיהוּ, אִם אֵינוֹ \u0010c35\u0011 נִכָּר רַק חֲתִימָה אַחַת, \u0006 \u0005 סָגֵי \u0006 \u0005(גַּם זֶה בַּסֵדֶר)\u0006. \u0005 וְיֵשׁ נוֹהֲגִין לִכְתֹּב כְּתָב (שֶׁל)\u0006 [אֶל] מְקוֹם הַנְּתִינָה, לְהוֹדִיעַ אִם יֵשׁ שִׁנּוּי בְּאֵיזֶה דָּבָר בַּהַרְשָׁאָה \u0005(שָׁם בְּשֵׁם מהר\"ר ז\"ךְ)\u0006:\nאִם הַבַּעַל אוֹ הַשָּׁלִיחַ רַךְ בַּשָּׁנִים, \u0010c36\u0011 טוֹב לְהַצְרִיךְ לְדַקְדֵּק אַחֲרָיו אִם הֵבִיא סִימָנִים כְּשֶׁעוֹשֶׂה שָׁלִיחַ, \u0010y0\u0011 שֶׁאֵין קָטָן עוֹשֶׂה שָׁלִיחַ וְלֹא נַעֲשֶׂה שָׁלִיחַ; וְאִם יֵשׁ לוֹ זָקָן בְּפָנָיו, אֵין לָחוּשׁ. \u0005 הַגָּה: אֲבָל אֵין צָרִיךְ לְדַקְדֵּק כָּל כָּךְ בְּעֵדֵי חֲתִימָה, דְּעֵדֵי מְסִירָה כַּרְתֵּי, וּרְגִילִים לִהְיוֹת הַרְבֵּה גְּדוֹלִים אֵצֶל נְתִינַת הַגֵּט \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם א\"ח)\u0006. \u0005 וּלְפִי מַה שֶּׁנּוֹהֲגִין לְיַחֵד עֵדֵי מְסִירָה, יְדַקְדֵּק בָּהֶם שֶׁיִּהְיוּ גְּדוֹלִים: \u0006\nנָהֲגוּ לְהַקְנוֹת לְעוֹשֵׂה שָׁלִיחַ, לְהוֹדִיעַ שֶׁגָּמַר בְּלִבּוֹ. וְאִם אָמַר: בְּלֵב שָׁלֵם אָמַרְתִּי וְגָמַרְתִּי לַעֲשׂוֹת דָּבָר זֶה, אֵין צָרִיךְ קִנְיָן:\nעַל שְׁטַר שְׁלִיחוּת קַבָּלָה יַחְתְּמוּ שְׁנֵי עֵדִים כְּשֵׁרִים. וְצָרִיךְ שֶׁיִּהְיוּ בְּנֵי אָדָם יְדוּעִים שֶׁתִּהְיֶה חֲתִימָתָן נִכֶּרֶת בִּמְקוֹם הַנְּתִינָה, וְאַף אִם יְקַיְּמוּהָ בְּהֶנְפֵּק, צָרִיךְ \u0010c37\u0011 שֶׁיִּהְיוּ חֲתִימוֹת הַדַּיָּנִים נִכָּרוֹת וִידוּעוֹת לִבְנֵי מְקוֹם הַנְּתִינָה. \u0005 וְעַיֵּן בְּטוּר אֶבֶן הָעֶזְר סִימָן קמ\"א נֻסַּח שְׁטַר שְׁלִיחוּת הַקַּבָּלָה: \u0006\nצָרִיךְ לִזָּהֵר וּלְדַקְדֵּק, שֶׁתִּהְיֶה הָאִשָּׁה שֶׁעוֹשָׂה שְׁלִיחַ קַבָּלָה גְּדוֹלָה בְּשָׁנִים וּבְסִימָנִים. וְאִם אֵין \u0005(הַנָּשִׁים יוֹדְעוֹת)\u0006 [הַשָׁנִים יְדוּעוֹת] כִּי עִם עַל פִּי הָאָב, צָרִיךְ רִבּוּי שְׂעָרוֹת שְׁחוֹרוֹת וּגְדוֹלוֹת כְּדֵי לָכֹף רֹאשָׁן לְעִקָּרָן:\nבִּשְׁעַת נְתִינַת הַגֵּט בְּיַד שְׁלִיחַ קַבָּלָה, יֵשְׁבוּ בֵּית דִּין כְּשֵׁרִים שֶׁאֵינָם קְרוֹבִים זֶה לָזֶה וְלֹא לַבַּעַל וְלֹא לָאִשָּׁה, וְנָהֲגוּ לִזָּהֵר גַּם כֵּן שֶׁלֹּא יִהְיֶה קָרוֹב לַשָּׁלִיחַ, וְיַכִּירוּ חֲתִימוֹת הַהַרְשָׁאָה, וְאַחַר כָּךְ יָבִיא הַבַּעַל הַגֵּט, וְיִקְרְאוּהוּ וְיַחְזִירוּהוּ לוֹ, וִיבַטֵּל כָּל מוֹדָעוֹת וְיִפְסֹל עֵדִים שֶׁיָּעִידוּ דָּבָר שֶׁגּוֹרֵם בִּטּוּל הַגֵּט, וְיִתְּנֵהוּ לְיַד הַשָּׁלִיחַ וְיֹאמַר לוֹ: הִתְקַבֵּל גֵּט זֶה לִפְלוֹנִית אִשְׁתִּי וַהֲרֵי הִיא מְגֹרֶשֶׁת מִמֶּנִּי \u0005(מְעַכְשָיו)\u0006 וּמֻתֶּרֶת לְכָל אָדָם. וְיֵשׁ מִי שֶׁאוֹמֵר, \u0010c38\u0011 שֶׁלֹּא יַטִּיל בּוֹ שׁוּם תְּנַאי. וְיַחְזְרוּ לִקְרוֹתוֹ אַחַר הַנְּתִינָה, וְהַדַּיָּנִים יִכְתְּבוּ עֵדוּתָם \u0005 וְיִהְיוּ הַחֲתִימוֹת נִכָּרוֹת וִידוּעוֹת \u0006 \u0005(טוּר)\u0006, וְיִתְּנֶנּוּ לְיַד הַשָּׁלִיחַ. \u0005 הַגָּה: וְנֻסַּח (הַגֵּט)\u0006 [הַשְּׁטָר] שֶׁנּוֹתְנִים לוֹ, עַיֵּן בְּטוּר סִימָן זֶה. וְכָל זֶה הוּא מִדִּינָא, \u0010c39\u0011 אֲבָל יֵשׁ אוֹמְרִים שֶׁנָּכוֹן לְהַחֲמִיר שֶׁלֹּא \u0005 לְגָרֵשׁ עַל יְדֵי שְׁלִיחַ קַבָּלָה כְּלָל \u0006 \u0005(טוּר בְּשֵׁם הָר\"פ)\u0006, \u0005 וְכֵן נוֹהֲגִין: \u0010c40\u0011 \u0006\nבְּנֻסַח הַרְשָׁאַת שְׁלִיחַ הוֹלָכָה, צָרִיךְ לְהוֹסִיף עַל הַנֻּסָח שֶׁכָּתוּב בְּטוּר אֶבֶן הָעֵזֶר: בְּפָנֵינוּ עֵדִים חֲתוּמֵי מַטָּה מָסַר פְּלוֹנִי בֶּן פְּלוֹנִי גֵּט כְּרִיתֻת בְּיַד פְּלוֹנִי בֶּן פְּלוֹנִי לְהוֹלִיכוֹ לְאִשְׁתּוֹ פְּלוֹנִית בַּת פְּלוֹנִי וְלִתֵּן אוֹתוֹ בְּיָדָהּ. וְכָךְ אָמַר בְּפָנֵינוּ פְּלוֹנִי בֶּן פְּלוֹנִי הַבַּעַל לִשְׁלוּחוֹ פְּלוֹנִי בֶּן פְּלוֹנִי: הוֹלֵךְ גֵּט זֶה לְאִשְׁתִּי פְּלוֹנִית בַּת פְּלוֹנִי בְּכָל מָקוֹם שֶׁתִּמְצָאֶנָּהּ וְתֵן אוֹתוֹ בְּיָדָהּ אוֹ בְּיַד שְׁלוּחָהּ אוֹ בְּיַד שְׁלִיחַ שְׁלוּחָהּ וּתְהֵא יָדְךָ כְּיָדִי וּפִיךָ כְּפִי \u0005 וְדִבּוּרְךְ כְּדִבּוּרִי \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דְּגִטִּין)\u0006 \u0005 הַגָּה: וְאִם יֵשׁ תְּנַאי בַּגֵּט, מַזְכִּירוֹ כָּאן וְכוֹתְבִין: עַל תְּנַאי כָּךְ וְכָךְ, וְכֵן חוֹזֵר וּמַזְכִּירוֹ בַּסוֹף אַחַר שֶׁכָּתַב וּמֻתֶּרֶת לְכָל אָדָם \u0006 \u0005(גַּם זֶה בַּהַגָּ\"ה הַנַּ\"ל)\u0006 וַעֲשִׂיָּתְךָ כַּעֲשִׂיָּתִי וְנוֹתֵן אֲנִי לְךָ רְשׁוּת לַעֲשׂוֹת שָׁלִיחַ וּשְׁלִיחַ שָׁלִיחַ עַד מֵאָה שְׁלוּחִים אֲפִלּוּ בְּלֹא אֹנֶס וְתֵכֶף שֶׁיַּגִּיעַ גֵּט זֶה לְיַד אִשְׁתִּי הַנִּזְכֶּרֶת אוֹ לְיַד שְׁלוּחָהּ אוֹ לְיַד שְׁלִיחַ שְׁלוּחָהּ מִיָּדְךָ אוֹ מִיַּד שְׁלוּחֲךָ אוֹ מִיַּד שְׁלִיחַ שְׁלוּחֲךָ תְּהֵא מְגֹרֶשֶׁת מִמֶּנּוּ וּמֻתֶּרֶת לְכָל אָדָם וְנוֹתֵן אֲנִי לְךָ רְשׁוּת לְמַנּוֹת שָׁלִיחַ וּשְׁלִיחַ שָׁלִיחַ עַד מֵאָה אֲפִלּוּ בְּלֹא אֹנֶס עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ וְתֵכֶף שֶׁיַּגִּיעַ גֵּט זֶה לְיַד אִשְׁתִּי הַנִּזְכֶּרֶת אוֹ לְיַד שְׁלוּחָהּ אוֹ לְיַד שְׁלִיחַ שְׁלוּחָהּ מִיָּדְךָ אוֹ מִיַּד שְׁלוּחֲךָ אוֹ מִיַּד שְׁלִיחַ שְׁלוּחֲךָ תְּהֵא מְגֹרֶשֶׁת מִמֶּנִּי וּמֻתֶּרֶת לְכָל אָדָם. \u0005 הַגָּה: וְכוֹתְבִין גַּם כֵּן בַּהַרְשָׁאָה שֵׁם הָעִיר עִם הַנְּהָרוֹת שֶׁלָּהּ, כְּמוֹ בַּגֵּט \u0006 \u0005(בְּסֵדֶר גִּטִּין)\u0006. \u0005 וְכֵן כּוֹתְבִין כָּל כִּנּוּי הָאִישׁ וְהָאִשָּׁה, כְּמוֹ בַּגֵּט \u0006 \u0005(מהרא\"י סִימָן ט\"ז וְי\"ז)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּכוֹתְבִים אַף כִּנּוּי הַשָּׁלִיחַ \u0006 \u0005(בְּסֵדֶר בְּשֵׁם מהר\"ר ז\"ךְ)\u0006. \u0005 וְיֵשׁ אוֹמְרִים שֶׁאֵין לְהַאֲרִיךְ בַּהַרְשָׁאָה בִּדְבָרִים שֶׁאֵינָם צְרִיכִין \u0006 \u0005(פִּסְקֵי מהרא\"י סִימָן ט\"ו)\u0006. \u0005 וְיֵשׁ אוֹמְרִים שֶׁאֵין לָחוּשׁ לְהַאֲרִיךְ בְּדָבָר שֶׁעִקַּר הַשְּׁלִיחוּת תָּלוּי בּוֹ, מֵאַחַר שֶׁכָּל אֶחָד יָכוֹל לִכְתֹּב כְּפִי צַחוּת לְשׁוֹנוֹ וְאֵינוֹ תִּקּוּן חֲכָמִים \u0006 \u0005(ב\"י)\u0006. \u0005 וְעַיֵּן לְקַמָּן בְּסֵדֶר הַגֵּט סָעִיף כ\"ו כֵּיצַד כּוֹתְבִין בְּהַרְשָׁאַת מוּמָר. \u0010c41\u0011 שְׁלִיחַ הוֹלָכָה שֶׁמֵּבִיא הַרְשָׁאָה וְכָתַב בָּהּ שֶׁהוּא שְׁלִיחַ קַבָּלָה, אִם הַשָּׁלִיחַ אֵינוֹ מַכְחִישׁ הַהַרְשָׁאָה רַק שֶׁאוֹמֵר שֶׁנַּעֲשָׂה שְׁלִיחַ הוֹלָכָה וְקַבָּלָה, אָז הַשְּׁלִיחוּת כָּשֵׁר וְנַעֲשָׂה שְׁלִיחַ הוֹלָכָה וְנוֹתֵן הַגֵּט לָאִשָּׁה. אֲבָל אִם הַשָּׁלִיחַ אוֹמֵר שֶׁלֹּא נַעֲשָׂה שְׁלִיחַ קַבָּלָה מֵעוֹלָם, הֲרֵי הַהַרְשָׁאָה מַכְחֶשֶׁת אוֹתוֹ וְנִתְבַּטֵּל כָּל הַשְּׁלִיחוּת, גַּם הַגֵּט עַצְמוֹ פָּסוּל מֵאַחַר שֶׁמּוּכַח שֶׁמְּסַדְּרֵי הַגֵּט הָיוּ עַמֵּי הָאָרֶץ וְלֹא יָדְעוּ שֶׁאֵין הַבַּעַל עוֹשֶׂה שְׁלִיחַ קַבָּלָה, יֵשׁ לָחוּשׁ לְכַמָּה מִינֵי פְּסוּלִין \u0006 \u0005(ב\"י מ\"כ מַעֲשֶׂה בכה\"ג נַעֲשָׂה בִּפְנֵי ר\"א מִזְרָחִי)\u0006, \u0005 וְכֵן כַּיּוֹצֵא בָּזֶה שֶׁנִּכָּר שֶׁאוֹתָן שֶׁסִּדְּרוּ הַגֵּט הָיוּ הֶדְיוֹטוֹת \u0006 \u0005(רִיבָ\"שׁ)\u0006:\nהַכֹּל כְּשֵׁרִים לִשְׁלִיחוּת הַגֵּט, בֵּין לְקַבָּלָה בֵּין לְהוֹלָכָה, אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה, \u0010c42\u0011 חוּץ מֵחֵרֵשׁ שׁוֹטֶה וְקָטָן, עֶבֶד וְנָכְרִי. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם הָעֶבֶד הוּא שְׁלִיחַ הוֹלָכָה, הָוֵי סָפֵק:\nהָיָה הַשָּׁלִיחַ קָטָן כְּשֶׁנָּתְנוּ לוֹ הַגֵּט, וְהִגְדִּיל וְהֵבִיאוֹ; אוֹ חֵרֵשׁ וְנִתְפַּקֵּחַ, שׁוֹטֶה וְנִשְׁתַּפֶּה, עֶבֶד וְנִשְׁתַּחְרֵר, נָכְרִי וְנִתְגַּיֵּר, פָּסוּל. אֲבָל אִם נָתַן לוֹ הַגֵּט כְּשֶׁהוּא פִּקֵּחַ, וְנִתְחָרֵשׁ וְחָזַר וְנִתְפַּקֵּחַ, שָׁפוּי וְנִשְׁתַּטֶּה וְחָזַר וְנִשְׁתַּפֶּה, כָּשֵׁר, כֵּיוָן שֶׁתְּחִלָּתוֹ וְסוֹפוֹ בְּכַשְׁרוּת:\nהַנָּשִׁים וְהַקְּרוֹבִים, כְּשֵׁרִים לִשְׁלִיחוּת הַגֵּט. \u0005 הַגָּה: וְיֵשׁ מִי שֶׁכָּתַב, דִּבְמָקוֹם שֶׁאֶפְשָׁר, לְכַתְּחִלָּה לֹא יְהֵא הַשָּׁלִיחַ קָרוֹב לָאִישׁ וְלֹא לָאִשָּׁה וְלֹא לַדַּיָּנִים שֶׁנּוֹתְנִים הַגֵּט לִפְנֵיהֶם \u0006 \u0005(בְּסֵדֶר גִּטִּין)\u0006. וַאֲפִלּוּ הַפְּסוּלִים מִדִּבְרֵי סוֹפְרִים, בַּעֲבֵרָה, כְּשֵׁרִים לִשְׁלִיחוּת הַגֵּט. אֲבָל הַפְּסוּלִים בַּעֲבֵרָה מִדִּבְרֵי תּוֹרָה, פְּסוּלִים \u0010c43\u0011 לַהֲבָאַת הַגֵּט \u0010c44\u0011 אֶלָּא אִם כֵּן נִתְקַיֵּם הַגֵּט בְּחוֹתְמָיו. \u0010c45\u0011 וְיֵשׁ פּוֹסְלִים אַף בְּנִתְקַיֵּם בְּחוֹתְמָיו. \u0010c46\u0011 \u0005 וְדִין \u0006 \u0005 מוּמָר, כְּדִין פְּסוּלֵי עֵדוּת מִדְּאוֹרָיְתָא כֵּן מַשְׁמַע בְּהַגָּהוֹת אַלְפָסִי דְּגִטִּין: \u0006\nהָיוּ פְּסוּלִים כְּשֶׁנִּתְמַנּוּ שְׁלוּחִים, וְחָזְרוּ בִּתְשׁוּבָה קֹדֶם שֶׁנְּתָנוּהוּ לָאִשָּׁה, \u0010c47\u0011 כְּשֵׁרִים:\nהַשּׁוֹלֵחַ הַגֵּט בְּיַד גּוֹי שֶׁיִּתְּנֶנּוּ לִפְלוֹנִי, וּמִנָּה הַבַּעַל בִּכְתָבוֹ לְאוֹתוֹ פְּלוֹנִי שָׁלִיחַ לְהוֹלִיךְ הַגֵּט לְאִשְׁתּוֹ, כָּשֵׁר, מִפְּנֵי שֶׁהַגּוֹי אֵינוֹ עוֹשֶׂה אֶלָּא מַעֲשֵׂה קוֹף בְּעָלְמָא. \u0005 הַגָּה: מִיהוּ, יֵשׁ חוֹלְקִין וּסְבִירָא לְהוּ דְּאֵין לְמַנּוֹת שְׁלִיחַ הוֹלָכָה עַל יְדֵי כְּתָב, גַּם לֹא רָאִיתִי נוֹהֲגִין כֵּן: \u0006\nנָתַן הַגֵּט לַשָּׁלִיחַ וְאָמַר לוֹ: הוֹלֵךְ גֵּט זֶה לְאִשְׁתִּי, אָמַר לוֹ הַשָּׁלִיחַ: \u0010c48\u0011 אֵינִי מַכִּירָהּ, אָמַר לוֹ הַבַּעַל: תְּנֵהוּ לִפְלוֹנִי שֶׁהוּא מַכִּירָהּ וְיִתְּנֵהוּ לָהּ; הָרִאשׁוֹן לֹא נַעֲשָׂה שָׁלִיחַ לְגֵרוּשִׁין רַק לְהוֹלִיךְ הַגֵּט לְאוֹתוֹ פְּלוֹנִי, \u0005 וְלֹא יָכוֹל לְשַׁלְּחוֹ לוֹ עַל יְדֵי שָׁלִיחַ \u0006 \u0005(טוּר)\u0006, וְאוֹתוֹ פְּלוֹנִי הוּא שָׁלִיחַ לְגֵרוּשִׁין וְנוֹתְנוֹ לָהּ, אוֹ מְשַׁלְּחוֹ בְּיַד אַחֵר אִם חָלָה אוֹ נֶאֱנַס. וְאִם נָתַן לָהּ הַגֵּט, הָרִאשׁוֹן אוֹ שְׁלוּחוֹ, הֲרֵי זֶה סְפֵק מְגֹרֶשֶׁת. \u0005 הַגָּה: הַשּׁוֹלֵחַ גֵּט לְאִשְׁתּוֹ וְאֵין הַשָּׁלִיחַ מַכִּירָהּ, \u0010c49\u0011 יִתְּנֵהוּ לָהּ עַל פִּי שְׁנַיִם \u0006 \u0005 שֶׁזֹּאת אִשְׁתּוֹ \u0006 \u0005(טוּר)\u0006:\nנָתַן הַגֵּט לְשָׁלִיחַ וְאָמַר לוֹ: לֹא תִּתְּנֵהוּ לָהּ עַד שְׁלֹשִׁים יוֹם, אִם \u0010c50\u0011 חָלָה אוֹ נֶאֱנַס בְּתוֹךְ שְׁלשִׁים, יָכוֹל לַעֲשׂוֹת שָׁלִיחַ שֶׁיִּתְּנֵהוּ לָהּ לְאַחַר שְׁלֹשִׁים יוֹם, אַף עַל פִּי שֶׁאֵינוֹ עַכְשָׁו שָׁלִיחַ לְגֵרוּשִׁין, הוֹאִיל וּלְאַחַר שְׁלֹשִׁים יִהְיֶה שָׁלִיחַ \u0010c51\u0011 לְגֵרוּשִׁין, וּבִלְבַד שֶׁיֹּאמַר הַבַּעַל: נֶאֱמֶנֶת עָלַי שֶׁלֹּא פִּיַּסְתִּי, אִם הִיא נְשׂוּאָה. \u0010c52\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁלֹּא יִמְסֹר מִיָּד לְשָׁלִיחַ שֵׁנִי, אֶלָּא יִמְסֹר שְׁלִיחוּתוֹ לְבֵית דִּין, וְהֵם לֹא יַעֲשׂוּ לַשֵּׁנִי שָׁלִיחַ עַד אַחַר שְׁלֹשִׁים יוֹם:\nהַשּׁוֹלֵחַ גֵּט לְאִשְׁתּוֹ, וְאָמַר לוֹ: הוֹלֵךְ גֵּט זֶה לְאִשְׁתִּי, אוֹ שֶׁאָמַר לֵיה: אַתָּה הוֹלֵךְ, \u0010c53\u0011 לֹא יִשְׁלְחֶנּוּ בְּיַד אַחֵר, אֶלָּא אִם כֵּן חָלָה אוֹ נֶאֱנַס, אוֹ שֶׁפֵּרַשׁ לוֹ שֶׁיּוּכַל לְמַנּוֹת שָׁלִיחַ וּשְׁלִיחַ שָׁלִיחַ עַד כַּמָּה שְׁלוּחִים. \u0010c54\u0011 \u0005 פֵּרַשׁ לוֹ שֶׁלֹּא יִשְׁלְחֶנּוּ בְּיַד \u0006 \u0005 אַחֵר, לֹא יוּכַל לַעֲשׂוֹת שָׁלִיחַ, אֲפִלּוּ חָלָה אוֹ נֶאֱנַס \u0006 \u0005(כֵּן מַשְׁמַע בְּטוּר)\u0006. וְיֵשׁ מִי שֶׁחוֹלֵק וְאָמַר דִּבְהוֹלֵךְ סְתָם יָכוֹל לְשָׁלְחוֹ עַל יְדֵי אַחֵר, אַף עַל פִּי שֶׁלֹּא חָלָה. וּבְאַתָּה הוֹלֵךְ, לֹא יִשְׁלְחֶנּוּ עַל יְדֵי אַחֵר, אֶלָּא אִם כֵּן חָלָה אוֹ שֶׁפֵּרַשׁ לוֹ שֶׁיּוּכַל לְמַנּוֹת שָׁלִיחַ:\nדִּין שָׁלִיחַ שֵׁנִי כְּדִין שָׁלִיחַ רִאשׁוֹן, שֶׁאֵינוֹ יָכוֹל לְמַנּוֹת שָׁלִיחַ אֶלָּא אִם כֵּן נֶאֱנַס אוֹ שֶׁפֵּרַשׁ לוֹ:\nכְּשֶׁמְּמַנֶּה הַשָּׁלִיחַ שָׁלִיחַ אַחֵר, אִם הוּא צָרִיךְ לוֹמַר \"בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם\", צָרִיךְ לְמַנּוֹתוֹ בִּפְנֵי בֵּית דִּין. וְאִם אֵינוֹ צָרִיךְ לוֹמַר: \"בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם\", \u0010c55\u0011 אֵין צָרִיךְ לְמַנּוֹתוֹ בִּפְנֵי \u0010c56\u0011 בֵּית דִּין, אֲבָל צָרִיךְ לְמַנּוֹתוֹ בִּפְנֵי עֵדִים. \u0005 וְעַיֵּן לְקַמָּן סִימָן קמ\"ב סָעִיף ט': \u0006\nשָׁלִיחַ שֶׁעָשָׂה שֵׁנִי, וְשֵׁנִי שְׁלִישִׁי, אִם מֵת הַבַּעַל נִתְבַּטְּלוּ כֻּלָּם. אֲבָל אִם הַבַּעַל קַיָּם, אַף עַל פִּי שֶׁמֵּת הַשָּׁלִיחַ הָרִאשׁוֹן, לֹא נִתְבַּטֵּל שְׁלִיחוּת הַשְּׁאָר, מֵאַחַר שֶׁהַבַּעַל קַיָּם:\nאִם מֵת שָׁלִיחַ שֵׁנִי, \u0010c57\u0011 יָכוֹל שָׁלִיחַ רִאשׁוֹן לִטְּלוֹ מִיּוֹרְשָׁיו שֶׁל שֵׁנִי, וְיוֹלִיכֶנּוּ אוֹ יִשְׁלְחֶנּוּ בְּיַד אַחֵר:\nשְׁלִיחַ קַבָּלָה אֵינוֹ יָכוֹל לְמַנּוֹת שָׁלִיחַ, וַאֲפִלּוּ נֶאֱנַס, וַאֲפִלּוּ נָתְנָה לוֹ רְשׁוּת לְמַנּוֹת שָׁלִיחַ, \u0010c58\u0011 מִשּׁוּם דַּהֲוָה לֵיהּ מִלֵּי, וּמִלֵּי לֹא מִמְסְרָן לְשָׁלִיחַ. וְיֵשׁ מַתִּירִין אִם נָתְנָה לוֹ רְשׁוּת לְמַנּוֹת שָׁלִיחַ. \u0010c59\u0011 \u0005 וְאָז יוּכַל לְמַנּוֹת אַחֵר בְּלֹא \u0006 \u0005 בֵּית דִּין, רַק לִפְנֵי שְׁנַיִם \u0006 \u0005(ב\"י בְּשֵׁם הָרַשְׁבַּ\"ץ)\u0006:\nאִם עָשְׂתָה שְׁלִיחַ קַבָּלָה, וְחָזְרָה וְעָשְׂתָה שָׁלִיחַ, אֲפִלּוּ עֲשָׂרָה זֶה אַחַר זֶה, אוֹ שֶׁעָשְׂתָה עֲשָׂרָה בְּבַת אַחַת, \u0010c60\u0011 כָּל שֶׁהִגִּיעַ הַגֵּט לְיַד אֶחָד מֵהֶן, מְגֹרֶשֶׁת. \u0005 וַאֲפִלּוּ נָתַן בְּיַד אֶחָד מֵהֶם גֵּט פָּסוּל, וְלַשֵּׁנִי גֵּט כָּשֵׁר, מְגֹרֶשֶׁת \u0006 \u0005(מָרְדְּכַי רֵישׁ הַשּׁוֹלֵחַ)\u0006:\nהַשָּׁלִיחַ שֶׁשִּׁנָּה בִּשְׁלִיחוּתוֹ מִמָה שֶׁאָמַר לוֹ הוּא אוֹ הִיא, לֹא עָשָׂה כְּלוּם. כֵּיצַד, אָמַר לֵיהּ: \u0010c61\u0011 תְּנֵהוּ לָהּ בְּמָקוֹם פְּלוֹנִי, וּנְתָנוֹ לָהּ בְּמָקוֹם אַחֵר; אַל תִּתְּנֵהוּ לָהּ אֶלָּא בַּעֲלִיָּה, וּנְתָנוֹ לָהּ בַּבַּיִת, אוֹ אִפְּכָא; אוֹ אַל תִּתְּנֵהוּ לָהּ אֶלָּא בְּיָמִין, וּנְתָנוֹ לָהּ בִּשְׂמֹאל, אוֹ אִפְּכָא; לֹא עָשָׂה כְּלוּם:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אָמַר לוֹ: אַל תְּגָרְשֶׁנָּה אֶלָּא בִּימִינְךָ, אֵינוֹ יָכוֹל לְשָׁלְחוֹ בְּיַד אַחֵר, אֲפִלּוּ אִם חָלָה, דַּהֲוָה לֵהּ כְּאִלּוּ פֵּרַשׁ: לֹא יְגָרְשֶׁנָּה אַחֵר אֶלָּא אַתָּה:\nאָמַר לֵהּ: תֵּן גֵּט זֶה לְאִשְׁתִּי, הֲרֵי הִיא בְּמָקוֹם פְּלוֹנִי, וּנְתָנוֹ לָהּ בְּמָקוֹם אַחֵר, הֲרֵי זֶה גֵּט, שֶׁאֵין זֶה קְפֵידָא אֶלָּא מַרְאֶה מָקוֹם:\nאָמַר לוֹ: תְּנֵהוּ לָהּ בְּיוֹם פְּלוֹנִי, וּנְתָנָהּ לָהּ \u0010c62\u0011 בְּתוֹךְ הַזְּמַן, אֵינוֹ גֵּט. אַל תִּתְּנֵהוּ לָהּ אֶלָּא בְּיוֹם פְּלוֹנִי, וּנְתָנוֹ לָהּ בֵּין מִלְּפָנָיו בֵּין מִלְּאַחֲרָיו, אֵינוֹ גֵּט:\nהָאִשָּׁה שֶׁאָמְרָה לִשְׁלוּחָהּ: קַבֵּל לִי גִּטִּי בְּמָקוֹם פְּלוֹנִי, וְקִבְּלוֹ בְּמָקוֹם אַחֵר, אֵינוֹ גֵּט. אֲבָל אִם אָמְרָה: הָבֵא לִי גִּטִּי בְּמָקוֹם פְּלוֹנִי, וְהֵבִיאוֹ לָהּ בְּמָקוֹם אַחֵר, כָּשֵׁר:\nאָמְרָה לוֹ: הִתְקַבֵּל לִי גִּטִּי בְּבָבֶל וּפְעָמִים תִּמְצְאֶנּוּ בְּדַמֶּשֶׂק, \u0010c63\u0011 בְּכָל מָקוֹם שֶׁיְּקַבְּלֶנּוּ הָוֵי גֵּט, וּבִלְבַד לִכְשֶׁיַּגִּיעַ לְבָבֶל לַמָּקוֹם שֶׁאָמְרָה הִיא:\nאָמַר הַבַּעַל לְשָׁלִיחַ: טֹל מִמֶּנָּה חֵפֶץ פְּלוֹנִי וְתֵן לָהּ גֵּט זֶה, הֲרֵי זֶה \u0010c64\u0011 לֹא יְשַׁלְּחֶנּוּ בְּיַד אַחֵר. וְאִם שְׁלָחוֹ בְּיַד אַחֵר וְנָתְנָה הָאִשָּׁה לַשָּׁלִיחַ הַחֵפֶץ תְּחִלָּה וְאַחַר כָּךְ נָתַן הַגֵּט, הֲרֵי זוֹ מְגֹרֶשֶׁת. וְאִם נָתַן לָהּ הַגֵּט תְּחִלָּה וְאַחַר כָּךְ נָתְנָה הַחֵפֶץ, אֲפִלּוּ בְּיַד שָׁלִיחַ רִאשׁוֹן \u0010c65\u0011 אֵינוֹ גֵּט. אָמַר לוֹ: תֵּן לָהּ הַגֵּט וְטֹל מִמֶּנָּה חֵפֶץ פְּלוֹנִי, הֲרֵי זֶה לֹא יְשַׁלְּחֶנּוּ בְּיַד אַחֵר, שֶׁאֵין רְצוֹנוֹ שֶׁיִּהְיֶה פִּקְדוֹנוֹ בְּיַד אַחֵר. וְאִם שְׁלָחוֹ בְּיַד אַחֵר, הֲרֵי זֶה גֵּט, בֵּין שֶׁנָּתְנָה תְּחִלָּה בֵּין שֶׁלֹּא נָתְנָה אֶלָּא בַּסוֹף. וְיֵשׁ אוֹמְרִים שֶׁכְּשֶׁאָמַר לוֹ: טֹל מִמֶּנָּה חֵפֶץ פְּלוֹנִי וְתֵן לָהּ הַגֵּט, אִם שְׁלָחוֹ בְּיַד אַחֵר, אֲפִלּוּ נָתְנָה לוֹ הַחֵפֶץ תְּחִלָּה וְאַחַר כָּךְ נָתַן לָהּ הַגֵּט, מֵאַחַר שֶׁלֹּא נָתְנָה הַחֵפֶץ בְּיַד שָׁלִיחַ רִאשׁוֹן קֹדֶם שֶׁתְּקַבֵּל הַגֵּט מִשָּׁלִיחַ שֵׁנִי, אֵינָהּ מְגֹרֶשֶׁת. כֵּיצַד יַעֲשֶׂה, יִטְּלֶנּוּ הָרִאשׁוֹן מִיָּדָהּ, וְיַחֲזֹר וְיִתְּנֶנּוּ לָהּ בְּתוֹרַת גֵּרוּשִׁין, אַחַר שֶׁהִגִּיעַ לְיָדוֹ הַחֵפֶץ:\nכָּל תְּנַאי שֶׁהִתְנָה הַבַּעַל עִם הַשָּׁלִיחַ, כְּגוֹן אַל תְּגָרְשֶׁנָּה אֶלָּא בַּבַּיִת אוֹ בָּעֲלִיָּה וְכַיּוֹצֵא בָּזֶה, אִם לֹא הִרְשָׁהוּ הַבַּעַל לְמַנּוֹת שָׁלִיחַ אֵינוֹ יָכוֹל לְשַׁלְּחוֹ בְּיַד אַחֵר לְכַתְּחִלָּה, שֶׁמָּא לֹא יְדַקְדֵּק הַשֵּׁנִי בִּשְׁלִיחוּתוֹ וְיִתְבַּטֵּל הַגֵּט. \u0005 הַגָּה: מִיהוּ, אִם עָשָׂה שָׁלִיחַ שֵׁנִי, אֲפִלּוּ לֹא הִגִּיד לוֹ הַתְּנַאי אוֹ הֶחֱלִיף לוֹ, אִם נִתְקַיֵּם הַתְּנַאי הָוֵי גֵּט \u0006 \u0005(רִיבָ\"שׁ סִימָן שי\"ו)\u0006. \u0005 אִם הִתְנָה שֶׁתִּמְחוֹל לוֹ כָּל זְכוּת שֶׁיֵּשׁ לָהּ עָלָיו, אַף עַל גַּב דִּלְעִנְיַן דִּינָא יֵשׁ לָדוּן מַהוּ בִּכְלַל \"כָּל זְכוּת\", מִכָּל מָקוֹם יֵשׁ לְהַחֲמִיר לְעִנְיַן גֵּט שֶׁתִּמְחוֹל כָּל זְכוּת שֶׁיֵּשׁ לָהּ עָלָיו וְאַחַר כָּךְ תָּדוּן עִמּוֹ מַהוּ בִּכְלָל, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה \u0006 \u0005(שָׁם סִימָן שי\"ז)\u0006:\nשָׁלִיחַ הַמֵּבִיא גֵּט \u0010c66\u0011 בְּמָקוֹם שֶׁאֵינוֹ צָרִיךְ לוֹמַר \"בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם\", נוֹתְנוֹ לָהּ וּמִתְגָּרֶשֶׁת בּוֹ וְנִשֵּׂאת אַף עַל פִּי שֶׁאֵין מַכִּירִין חֲתִימוֹת הָעֵדִים, וְגוֹבָה \u0010c67\u0011 כְּתֻבָּתָהּ מִבְּנֵי חָרֵי. וְאִם בָּא עֵד אֶחָד וְעִרְעֵר לוֹמַר שֶׁהוּא מְזֻיָּף, אֵין שׁוֹמְעִין לוֹ. בָּאוּ שְׁנַיִם וְעִרְעֲרוּ, אֲפִלּוּ נִשֵּׂאת כְּבָר, \u0010c68\u0011 תֵּצֵא. וְאִם בָּא הַבַּעַל וְעִרְעֵר וְאָמַר: לֹא גֵּרַשְׁתִּי מֵעוֹלָם, וְגֵט שֶׁהוּבָא לָהּ מְזֻיָּף הוּא, יִתְקַיֵּם בְּחוֹתְמָיו; וְאִם לֹא נִתְקַיֵּם וְלֹא נוֹדְעוּ עֵדָיו כְּלָל, תֵּצֵא \u0010c69\u0011 וְהַוָּלָד מַמְזֵר, \u0010c70\u0011 שֶׁהֲרֵי אֵינָהּ מְגֹרֶשֶׁת. אָבַד הַגֵּט, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:\nחֲמוֹתָהּ וּבַת חֲמוֹתָהּ וְצָרָתָהּ אֲפִלּוּ הָיְתָה נְשׂוּאָה לְאַחֵר, וִיבִמְתָּהּ \u0010c71\u0011 אֲפִלּוּ הִיא אֲחוֹתָהּ, וּבַת בַּעְלָהּ, אֵינָן נֶאֱמָנוֹת לְהָבִיא אֶת גִּטָּהּ בְּמָקוֹם שֶׁאֵין צָרִיךְ לוֹמַר: \"בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם\", דְּשֶׁמָּא מְזֻיָּף הוּא וְהֵם מְכַוְּנוֹת לְקַלְקְלָהּ. וְאִם הוּא בְּמָקוֹם שֶׁצָּרִיךְ לוֹמַר: \"בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם\", וַאֲמָרוּהוּ, נֶאֱמָנוֹת, וְאִם הוּא בְּמָקוֹם שְׁאֵין צָרִיךְ לוֹמַר וְאֲמָרוּהוּ, יֵשׁ אוֹמְרִים שֶׁנֶּאֱמָנוֹת, \u0010c72\u0011 וְיֵשׁ אוֹמְרִים שֶׁאֵינָן נֶאֱמָנוֹת: \u0010c73\u0011\nעָשְׂתָה שָׁלִיחַ לְקַבָּלָה בְּעֵדִים, וְהַגֵּט יוֹצֵא מִתַּחַת יָדוֹ, וְהַבַּעַל אוֹמֵר: מְזֻיָּף הוּא, אִם נִתְקַיֵּם בְּחוֹתְמָיו אוֹ בְּעֵדֵי מְסִירָה, הֲרֵי זוֹ מְגֹרֶשֶׁת. וְאִם הוּא מוֹדֶה שֶׁכְּתָבוֹ, אֶלָּא שֶׁאוֹמֵר שֶׁלֹּא נְתָנוֹ בְּתוֹרַת גֵּרוּשִׁין אֶלָּא בְּתוֹרַת פִּקָּדוֹן, וְהַשָּׁלִיחַ אוֹמֵר שֶׁקִּבְּלוֹ \u0005(בִּשְׁבִילָה)\u0006 שֶׁתִּתְגָּרֵשׁ בּוֹ, \u0010c74\u0011 הַשָּׁלִיחַ נֶאֱמָן, אֲפִלּוּ אִם שְׁלָשְׁתָּם בְּעִיר אַחַת. וְיֵשׁ אוֹמְרִים שֶׁאִם שְׁלָשְׁתָּם \u0010c75\u0011 בְּעִיר אַחַת, הַבַּעַל נֶאֱמָן, דְּאִם אִיתָא דִּבְתוֹרַת גֵּרוּשִׁין יַהֲבֵהּ, לְדִידָהּ הֲוָה יָהֵיב לָהּ. וְדַוְקָא כְּשֶׁטּוֹעֵן שֶׁלְּפִקָּדוֹן נְתָנוֹ לוֹ, \u0010c76\u0011 אֲבָל אִם טוֹעֵן שֶׁעֲשָׂאוֹ שָׁלִיחַ לְהוֹלָכָה, וְרוֹצֶה לַחֲזֹר בּוֹ קֹדֶם שֶׁיַּגִּיעַ לְיָדָהּ, אֵינוֹ נֶאֱמָן. וְאִם אֵינָם בְּעִיר אַחַת, הַשָּׁלִיחַ נֶאֱמָן, \u0010c77\u0011 וְהוּא שֶׁבָּאִים בְּפָנֵינוּ עֵדִים שֶׁעֲשָׂאַתּוּ שָׁלִיחַ קַבָּלָה, וְהַשָּׁלִיחַ אוֹמֵר שֶׁמְּסָרוֹ \u0005 לוֹ \u0006 בִּפְנֵי עֵדִים. \u0005 הַגָּה: \u0010c78\u0011 יֵשׁ אוֹמְרִים דַּוְקָא שֶׁהַגֵּט יוֹצֵא מִתַּחַת יָדוֹ, אֲבָל אֵין הַגֵּט בְּיָדוֹ אֵינוֹ נֶאֱמָן, אֲפִלּוּ הָיָה לוֹ עֵדִים שֶׁרָאוּהוּ תַּחַת יָדוֹ \u0006 \u0005(כֵּן מַשְׁמַע מֵהַטּוּר לְדַעַת הָרֹא\"שׁ)\u0006. וְלִסְבָרָא זוֹ טוֹב לִזָּהֵר שֶׁלֹּא לְגָרֵשׁ עַל יְדֵי שָׁלִיחַ כְּשֶׁהַבַּעַל וְהָאִשָּׁה בְּעִיר אַחַת, מִשּׁוּם דְּמָצֵי מִפָּק מִנֵּיהּ חֻרְבָה, שֶׁאִם יִטְעַן שֶׁלֹּא נְתָנוֹ לוֹ לְגֵרוּשִׁין, שֶׁהוּא נֶאֱמָן. \u0005 הַגָּה: \u0010c79\u0011 וְאֵין חִלּוּק בָּזֶה בֵּין שְׁלִיחַ הוֹלָכָה לִשְׁלִיחַ קַבָּלָה \u0006 \u0005(כ\"כ הָרִי\"ף)\u0006. \u0005 מִיהוּ, בִּזְמַן שֶׁהַרְשָׁאָה בְּיָדוֹ שֶׁנַּעֲשָׂה שָׁלִיחַ לְגָרֵשׁ, אֵין חִלּוּק בֵּין אִם הַבַּעַל בָּעִיר אוֹ לֹא \u0006 \u0005(מהר\"ם פַּדָּוואָה סִימָן ג')\u0006. וְאִם הָאִשָּׁה אוֹמֶרֶת: בְּפָנַי קִבְּלוֹ שָׁלִיחַ \u0010c80\u0011 לְגֵרוּשִׁין, נֶאֱמֶנֶת. \u0010c81\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא כְּשֶׁהַגֵּט בְּיַד הָאִשָּׁה: \u0010c82\u0011\nהָיָה הַגֵּט יוֹצֵא מִיַּד הָאִשָּׁה וְהִיא אוֹמֶרֶת: שָׁלִיחַ זֶה נְתָנוֹ לִי לְגֵרוּשִׁין, וְהַשָּׁלִיחַ אוֹמֵר: כֵּן נְתַתִּיו לָהּ וּלְגֵרוּשִׁין, וְהַבַּעַל אוֹמֵר: לֹא נְתַתִּיו לוֹ אֶלָּא לְפִקָּדוֹן, הַשָּׁלִיחַ נֶאֱמָן וְהִיא מְגֹרֶשֶׁת. וְאִם אָבַד הַגֵּט וְאֵין עֵדִים שֶׁרָאוּ אוֹתוֹ בְּיָדָהּ, \u0010c83\u0011 אַף עַל פִּי שֶׁהַבַּעַל אוֹמֵר: לְגֵרוּשִׁין נְתַתִּיו לַשָּׁלִיחַ, וְהַשָּׁלִיחַ אוֹמֵר: נְתַתִּיו לָהּ, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת; שֶׁהֲרֵי הֻחְזְקָה אֵשֶׁת אִישׁ, וְאֵין כָּאן אֶלָּא עֵד אֶחָד וּבַעַל. וַאֲפִלּוּ אָמְרָה הָאִשָּׁה: בְּפָנַי נְתָנוֹ לוֹ לְגֵרוּשִׁין וּנְתָנוֹ הַשָּׁלִיחַ לִי, \u0010c84\u0011 הוֹאִיל וְהַבַּעַל וְהַשָּׁלִיחַ מְסַיְּעִים אוֹתָהּ אֶפְשָׁר שֶׁתָּעִיז פָּנֶיהָ, וְשֶׁמָּא לֹא נִתְגָּרְשָׁה:\nשְׁלִיחַ קַבָּלָה שֶׁקִּבֵּל הַגֵּט לְאִשָּׁה, וּשְׁלָחוֹ לָהּ בִּפְנֵי שְׁנֵי עֵדִים, וְהִגִּיעַ הַגֵּט לְיָדָהּ וּנְטָלַתּוּ, וַהֲרֵי הַגֵּט יוֹצֵא מִתַּחַת יָדָהּ, וְהִיא אֵינָהּ יוֹדַעַת אִם בַּעְלָהּ שְׁלָחוֹ לָהּ אוֹ שְׁלִיחַ קַבָּלָה שֶׁלָּהּ אוֹ שְׁלוּחוֹ שֶׁל בַּעַל, הֲרֵי זוֹ מְגֹרֶשֶׁת. וְאִם בָּא הַבַּעַל \u0010c85\u0011 וְעִרְעֵר שֶׁלֹּא כְּתָבוֹ, אוֹ שֶׁהוּא גֵּט בָּטֵל, יִתְקַיֵּם בְּחוֹתְמָיו, \u0010c86\u0011 שֶׁהֲרֵי עֵדִים מְעִידִים שֶׁהַגֵּט שֶׁנָּתְנוּ לָהּ יָצָא מִתַּחַת יַד שְׁלוּחָהּ שֶׁיָּדוֹ כְּיָדָהּ, וְאַף עַל פִּי שֶׁהִיא אֵינָהּ יוֹדַעַת הֲרֵי הָעֵדִים יָדְעוּ. וְאִם לֹא נִתְקַיֵּם, אֵינָהּ \u0010c87\u0011 מְגֹרֶשֶׁת. וְיֵשׁ אוֹמְרִים שֶׁאִם שְׁלָשְׁתָּם בְּעִיר אַחַת, אִכָּא לְמֵיחַשׁ שֶׁמָּא יֹאמַר הַבַּעַל: לְפִקָּדוֹן נְתַתִּיו. \u0010c88\u0011 \u0005 וַאֲפִלּוּ אֵינָן בְּעִיר אַחַת, יֵשׁ אוֹמְרִים דְּאֵין הַשָּׁלִיחַ נֶאֱמָן רַק כְּשֶׁהַגֵּט בְּיָדוֹ \u0006 \u0005(כֵּן מַשְׁמַע מֵהַטּוּר לְדַעַת הָרֹא\"שׁ)\u0006 \u0005 דְּהָוֵי כְּשָׁלִישׁ שֶׁיִּתְבָּאֵר בְּחֹשֶׁן הַמִּשְׁפָּט סִימָן נ\"ו: \u0006\nכֵּיוָן שֶׁהַשּׁוֹלֵחַ גֵּט לְאִשְׁתּוֹ אֵינוֹ גֵּט עַד שֶׁיַּגִּיעַ לְיָדָהּ, הוּא חַיָּב בִּמְזוֹנוֹתֶיהָ וּבְכָל תְּנָאֵי כְּתֻבָּה עַד שֶׁיַּגִּיעַ לְיָדָהּ אוֹ לְיַד שְׁלִיחַ קַבָּלָה. וְאִם מֵת קֹדֶם שֶׁיַּגִּיעַ, אֵין גֵּט לְאַחַר מִיתָה:\nהַשּׁוֹלֵחַ גֵּט לְאִשְׁתּוֹ, וּבִטְּלוֹ קֹדֶם שֶׁיַּגִּיעַ לְיָדָהּ, הֲרֵי זֶה בָּטֵל. וְאִם הִגִּיעַ לְיָדָהּ, אֵינוֹ יָכוֹל לְבַטְּלוֹ, אֲפִלּוּ בְּתוֹךְ כְּדֵי דִּבּוּר. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּמוּמָר אֵינוֹ יָכוֹל לַעֲשׂוֹת שָׁלִיחַ לְהוֹלִיךְ גֵּט לְאִשְׁתּוֹ, דְּחַיְשִׁינָן שֶׁמָּא יְבַטְּלֶנּוּ \u0006 \u0005(מהרי\"ו סִי' קכ\"ו)\u0006. \u0005 וְאַף אִם מְקַבֵּל עָלָיו בְּחֵרֶם וּבִשְׁבוּעָה שֶׁלֹּא לְבַטְּלוֹ, לָא מְהַנֵּי, דְּחָיְשִׁינָן שֶׁמָּא יַעֲבֹר עַל שְׁבוּעָתוֹ. וְיֵשׁ אוֹמְרִים דְּהַמוּמָר עוֹשֶׂה הַשָּׁלִיחַ תְּחִלָּה שָׁלִיחַ לְקַבָּלָה וְאוֹמֵר לַשָּׁלִיחַ: זְכֵה בְּגֵט זֶה לְאִשְׁתִּי פְּלוֹנִית וּבוֹ תְּהֵא מְגֹרֶשֶׁת וְכוּ', וְנוֹתְנוֹ לַשָּׁלִיחַ, וְאַחַר כָּךְ חוֹזֵר וְלָקְחוֹ מִן הַשָּׁלִיחַ וְעוֹשֶׁה אוֹתוֹ שָׁלִיחַ לְהוֹלָכָה, וְאוֹמֵר: הוֹלֵךְ גֵּט לְאִשְׁתִּי וְכוּ' \u0006 \u0005(ת\"ה סִימָן רל\"ז וּבִפְסָקָיו סִימָן מ\"ב)\u0006, \u0005 וְכֵן נוֹהֲגִין. אֲבָל לֹא יַעֲשֶׂה הַשָּׁלִיחַ תְּחִלָּה שָׁלִיחַ לְהוֹלָכָה וְאַחַר כָּךְ שָׁלִיחַ לְקַבָּלָה. וּכְבָר נִתְבָּרֵר כָּל זֶה לְעֵיל סִימָן ק\"מ סָעִיף י\"א: \u0006\nלְכַתְּחִלָּה אֵין לוֹ לְבַטְּלוֹ אֶלָּא בִּפְנֵי הַשָּׁלִיחַ עַצְמוֹ אוֹ בְּפָנֶיהָ, אֲבָל בְּדִיעֲבַד אֲפִלּוּ בִּטְּלוֹ שֶׁלֹּא בִּפְנֵיהֶם, מְבֻטָּל, וְהוּא שֶׁיְּבַטְּלֶנּוּ \u0010c89\u0011 בִּפְנֵי שְׁנַיִם. \u0005 הַגָּה: \u0010c90\u0011 וְאֵין הַבַּעַל נֶאֱמָן לוֹמַר שֶׁבִּטְּלוֹ, אֶלָּא אִם כֵּן הַשָּׁלִיחַ \u0010c91\u0011 אוֹ הָאִשָּׁה מוֹדִים \u0006 \u0005 בַּדָּבָר אוֹ שֶׁיֵּשׁ לוֹ עֵדִים שֶׁבִּטְּלוֹ \u0006 \u0005(ב\"י וְכֵן הוּא בְּהַגָּהוֹת אֲשֵׁרִ\"י בְּפֶּרֶק הַשּׁוֹלֵחַ)\u0006. \u0010c92\u0011 \u0005 יֵשׁ אוֹמְרִים דְּאֵלּוּ הַשְּׁנַיִם שֶׁמְּבַטֵּל לִפְנֵיהֶם הַשָּׁלִיחַ צְרִיכִים לִהְיוֹת \u0010c93\u0011 בְּיַחַד, אֲבָל זֶה שֶׁלֹּא בִּפְנֵי זֶה, לֹא. אֲבָל אִם מְבַטֵּל הַגֵּט עַצְמוֹ, אֲפִלּוּ לְאַחַר שֶׁנִּכְתַּב, מְהַנֵּי אֲפִלּוּ זֶה שֶׁלֹּא בִּפְנֵי זֶה \u0006 \u0005(רִיבָ\"שׁ סִי' רל\"ב)\u0006:\nשְׁלָחוֹ עַל יְדֵי שְׁנַיִם אוֹ \u0010c94\u0011 עַל יְדֵי עֲשָׂרָה, יָכוֹל לְכַתְּחִלָּה לְבַטֵּל זֶה שֶׁלֹּא בִּפְנֵי זֶה, וְאוֹתָם שֶׁבִּטֵּל שְׁלִיחוּתָם בָּטֵל, וְאֵינָם יְכוֹלִין לְעַשׂוֹת שְׁלוּחִים אֶלָּא אִם כֵּן יִתְמַנּוּ פַּעַם אַחֶרֶת. וּבַעֲשָׂרָה שֶׁעֲשָׂאוּם שְׁלוּחִים, \u0005(בֵּין)\u0006 לִכְתֹּב וְלִתֵּן גֵּט בֵּין שֶׁעֲשָׂאָם שְׁלוּחִים לְהוֹלָכָה, אִם בִּטֵּל מִקְצָתָם לֹא נִתְבַּטְּלוּ \u0010c95\u0011 כֻּלָּם. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּבִשְׁלִיחוּת, אִם בִּטֵּל אֶחָד מֵהֶם נִתְבַּטְּלוּ כֻּלָּם:\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא בָּטֵל, כְּשֶׁבִּטְּלוֹ בְּפֵרוּשׁ. אֲבָל אִם לֹא בִּטְּלוֹ בְּפֵרוּשׁ, אַף עַל פִּי שֶׁגִּלָּה דַּעְתּוֹ שֶׁחָפֵץ בְּבִטּוּלוֹ, כְּגוֹן שֶׁאָמַר לוֹ הַשָּׁלִיחַ: לֹא נְתַתִּיו לָהּ עֲדַיִן, וְאָמַר: בָּרוּךְ הַטּוֹב וְהַמֵּטִיב, וְכַיּוֹצֵא בָּזֶה, אֵינוֹ בָּטֵל. וְלֹא עוֹד, אֶלָּא \u0010c96\u0011 אֲפִלּוּ הָיָה מְחַזֵּר לָרוּץ אַחַר הַשָּׁלִיחַ לְבַטְּלוֹ, וְלֹא הִסְפִּיק לְהַגִּיעַ אֵלָיו עַד שֶׁהִגִּיעַ לְיָדָהּ, אֵינוֹ בָּטֵל. \u0005 הַגָּה: וְכֵן אִם אוֹמֵר לַשָּׁלִיחַ: הַחֲזֵר לִי גֵּט זֶה וַאֲנִי נוֹתֵן לְךְ גֵּט אַחֵר, אֵינוֹ אֶלָּא גִּלּוּי דַּעַת וְאֵינוֹ בָּטֵל \u0006 \u0005(מָרְדְּכַי רֵישׁ הִתְקַבֵּל)\u0006. \u0005 כָּתַב כְּתָב אַחַר הַשָּׁלִיחַ שֶׁלֹּא לִתֵּן הַגֵּט, הָוֵי בִּטּוּל, דְּיָכוֹל לְבַטֵּל עַל יְדֵי כְּתִיבָה \u0006 \u0005(תְּשׁוּבַת הָרַ\"ן בַּבֵּית יוֹסֵף)\u0006. \u0005 הַשּׁוֹלֵחַ גֵּט לְאִשְׁתּוֹ וְאָמַר לַשָּׁלִיחַ: אִם תִּרְצֶה הָאִשָּׁה \u0010c97\u0011 לָבֹא אֵלַי \u0006 \u0005 אֲקַיְּמֶנָּה, וְאִם לֹא פְּטֹר אוֹתָה בַּגֵּט, וְהָלַךְ הַבַּעַל מִן הָעִיר הַהִיא, וְאַחַר כָּךְ בָּאתָה הָאִשָּׁה עִם הַשָּׁלִיחַ לְאוֹתָהּ הָעִיר, יָכוֹל הַשָּׁלִיחַ לִתֵּן הַגֵּט, דְּהָא לֹא בָּאתָה הָאִשָּׁה אֶל הַבַּעַל, כִּי יָצָא מִן הָעִיר קֹדֶם בּוֹאָהּ. וַאֲפִלּוּ הָיָה הַבַּעַל בָּעִיר, אִם לֹא יוּכַל לְהִתְפַּיֵּס עִמָּהּ יוּכַל הַשָּׁלִיחַ לִתֵּן הַגֵּט, דְּמַה שֶּׁאָמַר תְּחִלָּה: אִם תָּבֹא אֵלַי אֲקַיְּמֶנָּה, אֵינוֹ אֶלָּא דְּבָרִים בְּעָלְמָא, וְלֹא הָוֵי אֶלָּא גִּלּוּי דַּעַת, שֶׁאֵינוֹ כְּלוּם \u0006 \u0005(טוּר בְּשֵׁם תְּשׁוּבַת הָרֹא\"שׁ)\u0006:\nבְּאֵיזֶה לְשׁוֹנוֹת מְבַטֵּל גֵּט, \u0010c98\u0011 אָמַר: בָּטֵל הוּא, אִי אֵיפְשִׁי בּוֹ, גֵּט זֶה לֹא יוֹעִיל, לֹא יַתִּיר, לֹא יַעֲזֹב, לֹא יְשַׁלַּח, לֹא יְגָרֵשׁ, יְהֵא כַּחֶרֶס, הֲרֵי הוּא כַּחֶרֶס; אִם אָמַר אֶחָד מִלְּשׁוֹנוֹת אֵלּוּ וְכַיּוֹצֵא בָּהֶם, הֲרֵי זֶה בִּטְּלוֹ. אֲבָל אִם אָמַר: גֵּט זֶה אֵינוֹ גֵּט, פָּסוּל הוּא, אֵינוֹ מוֹעִיל, אֵינוֹ מַתִּיר, אֵינוֹ מְשַׁלֵּחַ, אֵינוֹ מְגָרֵשׁ, חֶרֶס הוּא; לֹא אָמַר כְּלוּם. אָמַר: גֵּט זֶה בָּטֵל, וְלֹא אָמַר: הוּא, אוֹ שֶּׁאָמַר: גֵּט זֶה בָּטַל, שֶׁמַּשְׁמָעוֹ \u0010c99\u0011 פֹּעַל עָבַר, כְּמוֹ \"חָמַק עָבַר\" \u0005(שִׁיר הַשִּׁירִים ה, ו)\u0006 הֲרֵי זֶה סָפֵק:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אָמַר: \u0010c100\u0011 יְהֵא פָּסוּל, בִּטְּלוֹ. \u0005 אָמַר: לֹא תֵצֵא לִצְמִיתוּת, הָוֵי בָּטֵל, וּכְאִלּוּ אָמַר: הַיּוֹם אֵין אַתְּ אִשְׁתִּי וּלְמָחָר אַתְּ אִשְׁתִּי \u0006 \u0005(ב\"י בְּשֵׁם תְּשׁוּבַת הָרַ\"ן \u0010c101\u0011 סִימָן מ\"ג)\u0006:\nאִם לֹא גִּלָּה דַּעְתּוֹ מִתְּחִלָּה שֶׁרוֹצֶה לְבַטְּלוֹ, וְאָמַר אֶחָד מִלְּשׁוֹנוֹת שֶׁאֵינָם מוֹעִילִים לְבַטֵּל הַגֵּט, מִכָּל מָקוֹם עִרְעוּר הוּא, לְפוֹסְלוֹ, וְצָרִיךְ שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו:\nהַשּׁוֹלֵחַ גֵּט בְּיַד שָׁלִיחַ וּבִטֵּל הַגֵּט, הֲרֵי זֶה חוֹזֵר וּמְגָרֵשׁ בּוֹ כְּשֶׁיִּרְצֶה, שֶׁלֹּא בִּטֵּל מִתּוֹרַת גֵּט אֶלָּא מִתּוֹרַת שְׁלִיחוּת. לְפִיכָךְ, אִם הָיָה הַגֵּט בְּיַד הַבַּעַל וּבִטְּלוֹ, כְּגוֹן שֶּׁאָמַר: גֵּט זֶה בָּטֵל הוּא, \u0010c102\u0011 אֵינוֹ מְגָרֵשׁ בּוֹ לְעוֹלָם. וְכֵן אִם פֵּרַשׁ בְּעֵת שֶׁבִּטְּלוֹ, וְהוּא בְּיַד הַשָּׁלִיחַ, וְאָמַר: גֵּט שֶׁשָּׁלַחְתִּי הֲרֵי הוּא בָּטֵל מִלִּהְיוֹת גֵּט, אֵינוֹ מְגָרֵשׁ בּוֹ; וְאִם גֵּרַשׁ, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:\nמִי שֶׁשָּׁלַח גֵּט לְאִשְׁתּוֹ, וְחָזַר וּבִטְּלוֹ בִּפְנֵי שְׁנַיִם אֲחֵרִים; וְכֵן מִי שֶׁמָּסַר מוֹדָעָא עַל הַגֵּט, \u0010c103\u0011 מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת, מִפְּנֵי שֶׁגּוֹרֵם לִהְיוֹת מַמְזֵרִים:\nשָׁלִיחַ שֶׁהֵבִיא גֵּט, אֵין חוֹשְׁשִׁין שֶׁמָּא בִּטְּלוֹ הַבַּעַל אוֹ שֶׁמָּא מָסַר מוֹדָעָא, וְנוֹתְנוֹ לָאִשָּׁה בְחֶזְקָת שֶׁהוּא חַי, אֲפִלּוּ הִנִּיחוֹ זָקֵן אוֹ חוֹלֶה. \u0005 וְיֵשׁ אוֹמְרִים דַּוְקָא חוֹלֶה בִּידֵי \u0006 \u0005 שָׁמַיִם, אֲבָל הֻכָּה וְנַעֲשָׂה טְרֵפָה, דִּינוֹ כְּגוֹסֵס \u0006 \u0005(הַגָּהוֹת אַלְפָסִי)\u0006. אֲבָל אִם הִנִּיחוֹ \u0010c104\u0011 גּוֹסֵס, \u0010c105\u0011 לֹא יִתְּנֶנּוּ לָהּ, שֶׁרֹב גּוֹסְסִים לְמִיתָה; וְאִם נְתָנוֹ לָהּ, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָא דְּאָמְרִינָן בְּזָקֵן, דַּוְקָא בְּפָחוֹת מִבֶּן \u0010c106\u0011 שְׁמוֹנִים אוֹ מִבֶּן מֵאָה וָמַעְלָה, אֲבָל מִבֶּן שְׁמוֹנִים \u0005(טוּר בְּשֵׁם הָרְמַ\"ה)\u0006 עַד בֶּן מֵאָה, דִּינוֹ כְּגוֹסֵס:\nעִיר שֶׁהִקִּיפוּהָ חַיִל מֵאוֹתוֹ מַלְכוּת, וְהָיוּ בְּמָצוֹר, וּסְפִינָה הַמְטֹרֶפֶת בַּיָּם, וְהַיּוֹצֵא לִדּוֹן בְּדִינֵי נְפָשׁוֹת, הֲרֵי אֵלּוּ בְּחֶזְקַת חַיִּים; וְאִם הָיָה גֵּט אֶחָד מֵהֶם בְּיַד שָׁלִיחַ, נוֹתְנוֹ לְאִשְׁתּוֹ וְתִהְיֶה בְּחֶזְקַת מְגֹרֶשֶׁת. אֲבָל עִיר שֶׁכְּבָשׁוּהָ כְּבָר, אוֹ עִיר שֶׁהִקִּיפוּהָ חַיִל מִמַּלְכוּת אַחֶרֶת, וּסְפִינָה \u0010c107\u0011 שֶׁאָבְדָה בַּיָּם, וְהַיּוֹצֵא \u0010c108\u0011 לֵהָרֵג בְּדִינֵי כּוּתִים, וּמִי שֶׁגּוֹרָרְתוֹ חַיָּה אוֹ שְׁטָפוֹ נָהָר אוֹ נָפְלָה עָלָיו מַפֹּלֶת, נוֹתְנִים עֲלֵיהֶם חָמְרֵי חַיִּים וְחָמְרֵי מֵתִים, וְאִם הָיָה גֵּט אֶחָד מֵהֶם בְּיַד הַשָּׁלִיחַ אֵינוֹ נוֹתְנוֹ לְאִשְׁתּוֹ, וְאִם נְתָנוֹ לָהּ, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. וְאִם נוֹדַע שֶׁמֵּת הַבַּעַל קֹדֶם שֶׁיַּגִּיעַ גֵּט לְיָדָהּ, אֵינוֹ גֵּט:",["\u0003שאין קטן עושה שליח.\u0004 מ\"כ בכת\"י הרב הגדול אמ\"ו זקני מהרר\"י הנ\"ל על גליון סדר גיטין וז\"ל והסכמנו דאינו טוב רק לרוחא דמלתא דממ\"נ אם הוא קטן א\"כ לא היו קידושיו קידושין וגם נ\"ל עוד לומר דוקא אם הוא רך בשנים אבל לא בעינן רוב שנותיו ואינו רק משום מראית עין כשהוא רך בשנים ונראה כקטן עכ\"ל:"],["\u0003ה\"ז ספק מגורשת\u0004. להמגיד הספק היא אם יכול זה האיש להיות נעתק משליחות הולכה שמנהו הבעל לשליחות קבלת האשה כיון שעדיין לא נגמר שליחות הבעל משמע דס\"ל הא דאמר שם הא לא חזרה השליחות אצל הבעל כלומר עדיין לא נגמר ולפרש\"י הספק הוא כיון דאין שהות להשיב להבעל דעשה שליחתו, וא\"ל למה כאן היא ספק מגורשת ובסי' קמ\"ב סעיף י\"ג אינו גט לגמרי משום כאן בתחילה היה שליחות הראוי לחזור לבעלה אבל שם לא היה כלל שליחות הראוי להשיב שליחתו:","\u0003ומשיגיע לידה וכו'\u0004. כ\"כ הרמב\"ם ולא אמרי' כשאמרה לו שיהיה ש\"ק שלה מיד חזר משליחות הבעל ואינו שליח הבעל:","\u0003מיד בעלה\u0004. וכן אם הוא צוה ליתן ליד אשתו יש קפידא ליתן דוק' לידה אלא אם אמר ליתן לאשתו אז יכולה לעשות שליח לשיטה זו:","\u0003וי\"א שאין האשה יכולה וכו'\u0004. בש\"ס מבואר ב' טעמים טעם א' משום בזיון הבעל אם היא בעצמה אינה מקבלת הגט ואז יש חשש דאורייתא, ובתשו' רשב\"א שהביא הב\"י סס\"ז מבואר ה\"ה דאין הבעל עושה שליח ליתן ליד ש\"ק של האשה משום בזיון דהאשה כשהוא בעצמו אינו רוצה ליתן ליד שלוחה ומ\"ש הרב בהג\"ה כשהיא אמרה לקבל מיד בעלה אין לקבלו מיד שלוחו צ\"ל כשהיא אמרה לקבל מיד בעלה איכא קפידא אליבא דכ\"ע אפי' למאן דלא חייש משום בזיון אבל אליבא דרב דחייש משום בזיון אפילו לא אמרה לקבל מיד בעלה אין לקבלו מיד שלוחו כ\"כ בט\"ז, טעם שני משום דדומה לחציר' הבאה אח\"כ כלומר כאלו מניח בחצר של אחר והיא קנתה אותו החצר ולפ\"ז ליכא אלא חשש דרבנן, גם נ\"מ אם אין הבעל מקפיד אז להאי טעמא משום בזיון ליכא קפידא, ואם היא עשתה שלוחה בתחילה אז משום חצירה הבאה אח\"כ ליכא ומשום בזיון איכא אף על גב דהיא עשתה שלוח' קודם לכן ואם היא היתה טרודה בעת שהביא לה גט ומחמת טרדה עשתה שליח לקבלה י\"א בכה\"ג ליכא משום בזיון דהבעל והר\"ן כת' אף בכה\"ג איכא משום בזיון דהבעל וכתב בתשוב' ריב\"ש סי' נ\"ה דהעיקר הוא דהאשה יכולה לעשות שליח לכן היכא דאיכ' שום חשש איסור אם ישלח ע\"י שליח לידה עדיף טפי שתעשה היא ש\"ק לקבל מיד שלוחו:","\u0003שלא מדעתו\u0004. כ\"כ הרשב\"א בתשובה אבל בבדק הבית הביא תשו' הר\"ל בן חביב דיש להחמיר שלא לגרש ע\"י הסכמת אביה וכ\"כ הנ\"י בשם כמה פוסקים:","\u0003וי\"א שהיא יכולה לקבל גיטה\u0004. בדין זה פליגי הפוסקים הרי\"ף והרמב\"ם וכמה פוסקים ס\"ל דוקא אביה מקבל ולא היא ותוס' וכמה פוסקים ס\"ל דהיא יכולה לקבל וכתב הרא\"ש דראוי להחמיר שלא תקבל ע\"י עצמה ומ\"ש המחבר בספרו ב\"י להגיה בטור חזר בבדק הבית וצוה למחוק ולא כפרי' שהביא הג\"ה של הב\"י ושם בספרו פסק כהרי\"ף והרמב\"ם דוקא אביה מקבל ולא היא וכן משמע דהמחבר ס\"ל כן שהביא דעת החולקים בלשון וי\"א ונ\"מ מזה דלא קנתה מתנה הבאה לחצרה כיון דאין לה יד אין לה חצר וכ\"כ הנ\"י כמ\"ש בח\"ה סי' רמ\"ג ובסדר הגט משמע דס\"ל עיקר כהני פוסקים דס\"ל דאית לה יד לקבל הגט:","\u0003וי\"א דהיינו משתגיע לעונת הפעוטות\u0004. ופלוגתא זו תליא בגירסא ולי\"א אלו דוקא כשהגיע' לעונת הפעוטו' יכולה לקבל הגט אבל צרור וזרקו לא מהני לקבלת הגט אלא לענין קידושין דצריכ' מיאון ולדיע' קמייתא לענין גט מהני צרור וזרקו ומכ\"ש עונת פעוטו' ולענין מיאון א\"צ מיאון אא\"כ כשהגיע לעונ' פעוטו' משום בקדושין איכא קדושי כסף דצריך שמירה מעולה כ\"כ הר\"ן ובסי' קנ\"ה לא הביא דעת הי\"א:","\u0003ע\"י אביה מתגרשת\u0004. בש\"ס איתא תרי טעמים למה שוטה אינה מתגרשת טעם א' משום דכתיב ושלחה מביתו ושוטה חוזרת לביתו, טעם שני משום חשש זנות ובקטנה ליכא חשש זנות גם אין חשש דחוזרת לביתו כיון דאביה חי:","\u0003אפי' וכו'\u0004. אף על גב דנראה דעדיף טפי כשהכל כת אחת ולא הוי חצי דבר מ\"מ כתב בלשון אפילו וכו' משום די\"ל דנראה כשקר שכת זו היו אצל האמירה ואצל הקבלה קמ\"ל כ\"כ תוס':","\u0003ולכתחלה וכו'\u0004. אפילו בדיעבד שמסר לידו ג\"כ אינו נאמן לומר שהוא ש\"ק אם ליכא עדים וצ\"ל דה\"ק כיון דצריך לברר אפי' אחר הנתינה לכן לכתחלה אל ימסור לידו עד שיברר קודם הנתינה:","\u0003מצטרף עם ע\"א\u0004. הן לענין הקבלה מצטרף הוא ודי אם קיבל הגט לפני ע\"א והוי כאלו קיבל בפני שנים והן להעיד על שליחתו שהוא ש\"ק די אם ע\"א מעיד על שליחתו כ\"כ בדרישה וב\"ח וכן בש\"ה דאי אם ממנה אותו לפני ע\"א כי מצטרפים השליח ג\"כ עם העד וכן בשעה שמוסר הגט ליד האשה די אם מוסר הגט לפני ע\"א והחולקים הוא הרא\"ש וס\"ל השליח הוא במקום הבעל והאשה לכן אין מצטרפים אותו כלל לא להעיד על שליחתו ולא בעת שמוסר לה הגט וצריכים שני עדים בעת כשממנה אותו וכן בעת המסירה אבל מ\"מ נאמן הוא לומר שעשה אותו לשליח בפני עדים כמ\"ש בסמוך ואם שנים הם שלוחים לכ\"ע נעשו עדים והיינו דתניא הן הן שלוחין והן הן עדים דרישה וב\"ח:","\u0003א\"צ עידי קבלה\u0004. כלומר א\"צ עדים שקיבל בפניהם הגט אבל צריך עידי אמירה שעשא' אותו לש\"ק כ\"כ הב\"י ובכ\"מ אף על גב דהוא שליש דהא הגט בידו מ\"מ לענין שתתגרש מיד בעת קבלתו בעינן עדים דהוא ש\"ק כמ\"ש לקמן ואם איכא עדים שהוא ש\"ק אפילו אם הבעל לא היה ידע שהוא ש\"ק אמרי' מסתמא מוסר לידו שתתגרש מיד אם הוא ש\"ק כ\"כ הר\"ן וכשאין עדים שהוא ש\"ק לא אמרי' עכ\"פ תתגרש מיום שבא עם הגט לכאן במיגו דהיה יכול ליתן לידה הגט די\"ל דאין רצונו לקבל הגט כשא\"י דבעלה נתן לידו ליתן לה כן משמע בהרא\"ש ולקמן הבאתי מ\"ש תוספות בזה ואם אין הגט עכשיו ביד השליח רק עדים ראו בידו יתבאר לקמן ועיין בטור שכתב דאיירי כאן בגט חתום וניכר החתימות אז אמרי' מסתמא נמסר ליד ש\"ק כדינו לפני ע\"מ מיהו קשה לקמן הביא המחבר פלוגתת הפוסקים כשהבעל מכחיש אותו אם יכול להכחישו וכאן כתב דא\"צ עידי קבלה משמע דהבעל א\"י להכחישו ולכאורה היה נראה לומר דס\"ל כהרא\"ש דוקא כשהבעל מכחישו בזה פליגי הפוסקים אבל כשהבעל אינו בפנינו לא חיישינן שמא יבוא ויכחישו אלא קשה דהא בסעיף נ\"ז איירי דאין הבעל כאן ופליגי אם יכול להכחישו ושם סתם דחיישינן שמא יבוא הבעל ויכחישו ונראה דמוכח כן מדברי הרי\"ף דפוסק כרב חסדא נגד רב הונא וראיה שלו מדהקשה בש\"ס וליהמניה לשליש שאומר שנתן הגט לגרש אותו וס\"ל דאתיא כרב חסדא דהא לרב הונא אין השליש נאמן ואם איתא דיש חילוק בין אם הבעל בפנינו ומכחיש לבין דאין הבעל בפנינו א\"כ מנ\"ל להביא ראיה מזה דאתיא כר\"ח דהא אף לר\"ה בכה\"ג דאיירי מתני' דאין הבעל כאן ומכחיש אותו א\"כ אף לר\"ה השליש נאמן א\"כ אתיא שפיר כר\"ה אלא וודאי דאין חילוק בדבר ואפי' אין הבעל בפנינו חיישינן שמא יבוא הבעל ויכחיש ולא כב\"י וכ\"מ גם א\"ל משום דאיירי דיש בידו שטר שליחות אז אמרינן מסתמא מסר לידו לשם גירושין דהא לקמן איירי נמי דהוא ש\"ק משמע בידוע שהוא ש\"ק ומ\"מ חיישינן שמא יבוא הבעל ויכחיש אותו וצ\"ל דאיירי כאן בשליח המביא גט ממקום למקום אז לכ\"ע השליח נאמן אבל אם היה במקום א' אפילו אין הבעל כאן חיישינן שמא יבא הבעל ויכחישו אף על פי שדבריו סתומים הם מ\"מ נ\"ל כן:","\u0003אין שליח הולכה וכו'\u0004. כן ס\"ל לרמב\"ם דא\"צ לעשותו בפני עדים אם הודו דהוי כשליח להפריש תרומה וכיוצא בזה:","\u0003ואם המשלח כופר וכו'\u0004. ע\"כ צ\"ל דהמשלח כופר ואומר לפקדון נתתי לך והשליח אומר לגירושין דאם אומר ממני נפל ואתה מצאת כתב המגיד בשם הרשב\"א דאינו נאמן א\"כ קשה כשאינם בעיר א' למה יכול להכחישו דהא לשיטות הרי\"ף כמ\"ש בתשו' והרשב\"א איירי הסוגיא בש\"ה ולכ\"ע כשאינם בעיר א' השליח נאמן וכאן כתב בסתם דיכול להכחישו, וא\"ל דאיירי כאן דאין הגט ביד השליח מ\"ה יכול להכחישו דהא קשה היכא הוא הגט אם בידה הגט הא כתב המחבר לקמן כשהגט ביד האשה הוי כאלו היה ביד השליח ואם נקרע הגט א\"כ אפילו אם המשלח מודה דנתן לגרושין ה\"ז ספק כמ\"ש לקמן, וא\"ל הסוגיא איירי בידוע שהוא ש\"ה שלה וכן איירי לקמן בזה אמרי' דא\"י להכחישו אא\"כ כשמסייע ליה הסברא אי לגרושין נתה היה לו ליתן לידה לכן כשאינם בעיר א' א\"י להכחישו אבל אם א\"י כלל אם הוא שלוחו יכול להכחישו, דהא מ\"מ שליש הוא א\"כ למה יכול להכחישו שלא נתן לגירושין, גם א\"ל דאיירי באומ' ממני נפל ואתה מצאת ואינו שליש כלל אף על גב הרשב\"א ס\"ל דאינו נאמן לומר ממני נפל מ\"מ הגמיי' לא ס\"ל כן אלא ס\"ל כהרא\"ש דס\"ל די\"ל ממני נפל כמ\"ש בתשו' הביא' הב\"י בח\"ה סי' נ\"ה, והא שכתב הטור לקמן סימן קנ\"ב כשהגט ביד האשה אינו יכול לומר הבעל ממני נפל י\"ל כשהגט ביד האשה שאני, והא שכתב הטור בח\"ה שם אם אמר להשליש ממני גזלת אינו נאמן י\"ל טענות גזילה שאני אבל ממני נפל נאמן לומר דהא דין זה כתב הגמיי' וכתב שם הבעל יכול להכחישו כשאין הגט ביד השליח כמ\"ש בסמוך ואי ס\"ל כהרא\"ש א\"ש אפילו כשהגט ביד השליח נמי יכול להכחישו ולומר ממני נפל אלא ע\"כ לא ס\"ל כהרא\"ש גם כתבתי בסמוך דמוכח לא כהרא\"ש דחייש לנפילה גם לא כהפוסקים דס\"ל דנאמן לומר לשאלה נתתי ואפשר דאיירי דאין הגט ביד השליח ולא ביד האשה אלא השליח מסר לידה הגט בפני ע\"מ והעדים בפנינו והגט נקרע מ\"ה אם הבעל מודה דהוא שלוחו ה\"ז מגורשת ואם הוא מכחישו אף על גב דראו בידו הגט לא מהני והיינו כמ\"ש לקמן בהג\"ה דלא מהני מה שראו הגט ביד השליח וע\"כ צ\"ל בעת שמסר הגט לידה לא אמר שהוא שליח הבעל דאם אמר באותו פעם כשהיה הגט בידו אז היה השליחות בידו והיה נאמן מה שאמר שהוא ש\"ה תו א\"י הבעל להכחישו כמ\"ש בח\"ה שם, וכתב בהגמיי' הא דהבעל יכול להכחישו משום דיצא השלישות מידו משמע אם הגט ביד השליח א\"י להכחישו ולכאורה קשה אם הגט ביד השליח למה א\"י להכחישו הלא יש להבעל מיגו דיכול למחות לו שאל ימסור הגט לידה א\"כ למה אינו נאמן לומר שנתן לפקדון במיגו דיכול למחות וצ\"ל דהשליש נאמן אפילו אם יש מיגו לבטל הדבר וכן משמע ממ\"ש בח\"ה דהשליש נאמן כתרי עדים א\"כ הוי כמיגו במקום עדים:","\u0003מיהו השליח נאמן וכו'\u0004. כ\"כ רי\"ו והרא\"ש כתב ג\"כ ריש גיטין וכתב אפי' אם הבעל מכחישו נאמן וע\"כ צ\"ל דלא איירי במכחישו ואומר ממנו נפל דהא הרא\"ש ס\"ל דיכול לומר ממנו נפל כמ\"ש בסמוך אלא איירי לפקדון נתן לו, וכתב בד\"מ דאיירי כשהגט ביד השליח מ\"ה נאמן השליח ומ\"ש בסמוך דאיירי כאן דאין הגט ביד השליח ואם רמ\"א איירי נמי דאין הגט ביד השליח קשה למה הוא נאמן וא\"ל בד\"מ איירי כשהבעל מכחישו אז אינו נאמן אא\"כ הגט בידו וכאן איירי דאין הבעל כאן מ\"ה הוא נאמן אפילו אין הגט בידו דהא אכתי קשה למה לא חיישינן שמא יבוא הבעל ויכחישו כמ\"ש לקמן סעיף נ\"ז, וע\"כ צ\"ל דברי רמ\"א דאיירי כשהגט ביד השליח כמ\"ש בד\"מ אף על גב דהמחבר איירי כשאין הגט ביד השליח, גם צ\"ל דאיירי בש\"ה ממקום למקום ואז א\"י הבעל להכחישו דאל\"כ היה יכול להכחישו כמ\"ש בסוגי' דאיירי לשיטות הרי\"ף והרשב\"א בש\"ה וכ\"כ הרב רמ\"א לקמן אף בש\"ה יכול להכחישו במקום א' מיהו נראה דהרא\"ש ורי\"ו ס\"ל בש\"ה א\"י להכחישו אפילו בעיר משום כיון דהוא נאמן לומר ב\"נ וב\"נ נאמן ג\"כ לומר דהוא ש\"ה וכן כתבתי בסי' קמ\"ב אבל בטור סעיף כ\"ב לא משמע כן וכן משמע שם בב\"י לכן כתב דא\"צ הרשאה ע\"פ הדין כשמביא גט ממקום למקום משמע במקום א' צריך הרשאה ע\"פ הדין משום דהבעל יכול להכחישו, ומשמע מהרא\"ש הא דנאמן לומר ש\"ה אני ועשאו בעדים היינו דוק' כשצריך לומר ב\"נ וב\"נ אז הואיל הוא נאמן ע\"ז נאמן הוא ג\"כ לומר שהוא ש\"ה אבל בא\"י דא\"צ לומר ב\"נ וב\"נ אינו נאמן לומר דעשאו לש\"ה וכ\"כ הב\"י בתירוץ א\"נ אבל הרמ\"ה ס\"ל אפילו בא\"י נאמן, ונראה דהרמב\"ם ג\"כ ס\"ל כשיטות הרמ\"ה מ\"ה כתב כשהגט מקוים יכול לעשות שליח הראשון שליח אחר בינו לבין עצמו וכתב הריב\"ש בתשו' סי' נ\"ג דא\"צ שטר שליחות משום השליח נאמן לומר שהוא שלוחו אף על גב דא\"צ לומר ב\"נ דהא הגט מקוים הוא מ\"מ נאמן לומר דהוא שלוחו והיינו כהרמ\"ה והרב רמ\"א בסי' קמ\"ב הביא דברי הריב\"ש משמע דס\"ל כרמב\"ם והרמ\"ה דנאמן לומר דעשאו לשליח אפי' בא\"י או הגט מקוים אף על גב דאינו אומר ב\"נ וב\"נ, ולהרמב\"ם אפילו לא עשאו לשליח בעדים הוא שלוחו ולהרא\"ש צ\"ל דעשאו בעדים כמ\"ש לעיל, וכל זה איירי בש\"ה אבל ש\"ק אינו נאמן לומר דעשאו לש\"ק כיון דהגט אינו בידו כמ\"ש לעיל:","\u0003ונוהגין להצריך וכו'\u0004. כלומר כשמביא גט ממקום למקום לא היה צריך הרשאה ע\"פ הדין כי הוא נאמן לומר דעשאו בעדי' אלא נוהגין כן אבל בעיר אחת צריך הרשאה על פי הדין לדעת הפוסקים דפסקו כרב הונא כמ\"ש בהג\"ה סעיף נ\"ה, מיהו קשה אפי' ממקום למקום נמי יש לחוש שמא יאמר ממני נפל ואתה מצאת, גם יש לחוש שמא יאמר לשאלה נתתי אם כן לאו שליח הוא וע\"כ ל\"פ ר\"ה ור\"ח אלא כשאומר לפקדון נתתי דהימנוה והוא שליח לו אבל אם אומר ממני נפל או נתתי לשאלה אינו נאמן כמ\"ש בתוספת וכמה פוסקים ס\"ל כן ועיין בש\"ך בח\"ה סימן צ\"ו, וע\"כ מוכח דסותם כאן כדעת בעל התרומה דס\"ל אפילו אם אמר לשאלה נתתי מכל מקום דינו כשליש ולא כתוספ' הנ\"ל ומכ\"ש דאינו נאמן לומר ממני נפל ואתה מצאת:","\u0003הרי זו ספק מגורשת\u0004. כן כתב הרמב\"ם פרק ט' הלכות גיטין דין ל\"ב ולכאורה קשה מ\"ש מכסף קידושין שנותן לשליח דמהני הודאתו ולמה לא מהני כאן וצ\"ל כאן איכא ריעותא לפנינו דלא חתמו עליו עדים אף על גב הרמב\"ם ס\"ל בע\"מ לבד כשר מכל מקום לכתחלה צריכין להיות עידי חתימה גם כן כמ\"ש בסימן קל\"ג ועיין פרק ג' ה\"א מ\"ש בכ\"מ בשם רמ\"ח:","\u0003וא\"א לחזור וכו'\u0004. כן כתב הרמב\"ם אף על גב בעלמא ס\"ל ע\"ח כרתי ואין צריך ליטול ממנה וליתן לה מכל מקום כשניתן על ידי שליח ס\"ל דצריך ליטול ממנה אם אפשר ועיין במגיד פ\"ו ועיין סימן קל\"ג:","\u0003אין צריך שישמעו מפיהם\u0004. והא דאינו יכול לומר על ידי שלוחו להסופר שיכתוב כתבתי לעיל סימן ק\"כ:","\u0003כמו גרשוה או שלחוה וכו'\u0004. המגיד כת' בשם הראב\"ד בכולם בעינן שהיה מדבר עמהם מעסקי גיטין דאל\"כ מהיכא יודעין הם שהוא נותן לגירושין ואפילו אם אמר גרשוה יש לפרש כמו גרש את האמה:","\u0003לא אמר כלום\u0004. משמע מרש\"י והר\"ן דספק גט הוא כי י\"ל הני לשונות נמי לשון גט הם:","\u0003והוא אדם וכו'\u0004. ה\"ה שאר חולה אחר ג' ימים טור וכן מצוה מחמת מיתה דינו כמסוכן ד\"מ בשם הר\"ן:","\u0003והיוצא בשיירא\u0004. פרש\"י היוצא למדברות משמע ההולך מעיר לעיר שלא דרך מדבר לא טריד ב\"י:","\u0003מיד וכו'\u0004. לכאורה משמע כשם דלא בעינן לאלתר כשידוע שהמית את עצמו וכן משמע מהתוספת' דאית' שם בספק אם הרג את עצמו אם לאלתר נפל אומר אני מעצמו נפל ואם לאחר זמן נפל אין כותבים שמא רוח דחפתו מכלל אם ידוע שמעצמו נפל לא חיישינן שמא באותו זמן לא היה בדעתו להמית את עצמו ואפשר לומר התוספת' קמ\"ל אפילו בספק מ\"מ אם לאלתר נפל הוי גט וכן נשמע מן התוספת' אפילו בספק ולא נפל מיד מ\"מ הוי ספק גט כמ\"ש שם אין כותבין שם רוח דחפתו משמע מידי ספק לא נפיק ולא אמרי' דהוי ס\"ס שמא רוח דחפתו ואת\"ל הוא המית את עצמו שמא באותו זמן לא היה בדעתו להמית את עצמו מ\"ה פסק המחבר בסעיף אח\"ז בספק ולא נפל לאלתר ה\"ז ספק:","\u0003כל זמן שיש בו נשמה\u0004. עיין סי' קכ\"ב דצריך בדיקה אף על גב דאמר ליתן גט קודם לכן מ\"מ צריך בדיקה אם הוא שפוי בדעתו וכתב הר\"ן דצריך בדיקה ג\"פ שמא נטרפה דעתו:","\u0003אם לאלתר וכו'\u0004. אז אמרי' הוכיח סופו על תחלתו דהיה בדעתו להמית את עצמו וליתן גט אף על גב בעלמ' לא אמרי' הוכיח סופו על תחלתו וכמ\"ש בח\"ה סי' רמ\"ה ש\"ה דאמר כתבו ש\"ס פ\"ב דחולין וכ\"כ הר\"ן:","\u0003כל השומע קולי\u0004. אז מייחד למי השומע קולו הוא נעשה שלוחו ואם אמר כל הרוצה לכתוב יכתוב כתבו תוס' כמ\"ש דף ס\"ו בתירוץ א' דלא מהני וכ\"כ המ' והר\"ן בשם הרמב\"ן ובחד תירוץ כתבו דמהני אף על גב אם מודר הנאה מחבירו מותר לומר כל הרוצה לתרום ולא חשיב שלוחו לענין הנאה שאני ולא חשיב כמהנ' כיון דלא צוה לו לעשות וכן הסכים הר\"ן ואפי' להפוסקים דס\"ל דא\"צ שליחות בכתיבת הגט כמ\"ש בסי' קכ\"ג מ\"מ צריך הוא לצוות לו ועל חילוק של תוס' הנ\"ל קשה דהא ריש פ' המדיר הקשה בהא כל השומע קולי יכתוב דנעשה שלוחו ולמה במדיר יכול לומר כל הזן לא יפסד ולפי חילוק הנ\"ל לק\"מ דהא אף על פי דנעשה שלוחו מ\"מ לא הוי הנאה כיון דלא אמר לו דיהיה שלוחו ונ\"מ מהני שני תרוצים מ\"ש בסי' ע' בשם בעה\"ת וע\"ש:","\u0003ואף על פי שהעלוהו ולא הכירוהו\u0004. וכ\"כ הרמב\"ם ומ\"ש הרמב\"ם והוא שידעו אותו פי' היינו דפי' שמו ושם עירו בחדושי רש\"ך הביא יש מפרשים מ\"ש והוא שידעו היינו שידעו שהוא אדם ולא שד:","\u0003וי\"א דהני מילי וכו'\u0004. עיין סי' י\"ז סעיף י' כתב בזה\"ז לא סמכי' על ראיות בואה דבואה וע\"ש מ\"ש:","\u0003ונעשה הבן שליח וכו'\u0004. וס\"ל להב\"י דנעש' הבן ואביו שלוחין בהולכה אלא דא\"י לחתום האב ובנו אלא האב או הבנו עם אחר אבל מהרש\"ל ס\"ל אפילו שליח להולכה לא נעשו שניהם יחדיו שלוחין האב והבנו ולא היה דעתו אלא על א' מהם כיון דיש אחרים:","\u0003ממקום למקום\u0004. כבר כתבתי דוקא ממקום למקום א\"צ הרשאה ע\"פ הדין אבל בעיר אחר צריך הרשאה ע\"פ הדין ועיין בתשובת רש\"ך פ\"א סי' קמ\"ב:","\u0003א\"צ\u0004. אבל בש\"ק צריך ומחמירים בקיום דידי' כמ\"ש בסמוך משום ש\"ה שאני הואיל האמינוהו חז\"ל לומר ב\"נ וב\"נ נאמן לומר שעשאו לש\"ה משא\"כ ש\"ק:","\u0003גם שלא לשנות\u0004. משמע אם שינה דינו כמו בר\"ת וכשר:","\u0003ולא לעידי הגט\u0004. כתב בתשובת מהר\"מ מינץ סי' כ\"א בדיעבד אין לפסול אם עידי הרשאה קרובים לעידי הגט משום עידי הגט מעידים על הגט ועידי הרשאה מעידים על שליחות של זה:","\u0003נתבטל כל השליחות\u0004. אף על גב כשאין בידו הרשאה נאמן לומר שהוא ש\"ה מ\"מ בכה\"ג שנעשה לפני פסולים גרע טפי והוי כאלו מכחישים אותו כי כל דבר הנעשה לפני פסולים נתבטל אותו דבר, ולכאורה נראה דלא נתבטל אלא השליחות ואם חזר והביא הרשאה אחרת כשר הגט, אלא בד\"מ כתב בשם סדר הגט דהגט פסול ואפשר משום דמוכח דמסדרי גט היו ע\"ה מ\"ה פוסל הגט כמ\"ש לקמן:","\u0003רק חתימה אחד\u0004. כשר ועיין בטור שם משמע מדברי הרי\"ף אפי' אינן מכירים שום חתימה כשר ובתשובת רש\"ך הקשה בממ\"נ אם צריך קיום א\"כ צריכין לקיים כל החתימות ואם א\"צ קיום למה לי הרשאה ובדרישה וב\"ח בק\"א כתבו באמת ע\"פ הדין א\"צ הרשאה כי הוא נאמן לומר דהוא ש\"ה אלא הואיל בכל שליחות צריך הרשאה צריך כאן ג\"כ הרשאה מיהו אפי' אין מכירים החתימות סמכינן אהא דקי\"ל עידי החתומים הוי כאלו נחקרו עידותן בב\"ד, נשמע מכל זה אפילו אם אין ניכר שום חתימה או אפילו אין מקוים כשר:","\u0003טוב להצריך לדקדק\u0004. כלומר באמת אין קפידא ממ\"נ אם הוא גדול יכול לעשות שליח ואם הוא קטן אין קידושין קידושין וא\"צ גט כמ\"ש בסי' מ\"ג, ובד\"מ כתב דיש חשש שמא יתעכב הדבר ויתגדל בינו לבינו ויתייחד עמה קודם הגט:","\u0003שיהיו חתימות הדיינים נכרת\u0004. ול\"ד להרשאה של ש\"ה דא\"צ להכיר החתימות שם מקילין משום הגט בידו משא\"כ בש\"ק, וכתב בלבוש ובדרישה וב\"ח אף על גב בעלמא די אם מכירים ב' חתימות מדייני הקיום מ\"מ כאן בגט מחמירים וצריכים להכיר כל ג' דייני הקיום הרשאת ש\"ק מיהו הרשב\"ץ כתב כל זה איירי לכתחלה צריכים להכיר כל ג' חתימות אבל במקום עגון מקילין אפי' בש\"ק אם הביא שטר חתום מכ\"ש אם יש עליו מעשה ב\"ד אף על גב דא\"י לקיים החתימות דקי\"ל קיום שטרות מדרבנן כתב הבית יוסף בשם א\"ח כשרוצי' לקיים החתימות צריך להושיב ג' שיכירו חתימות העדי' החתומי' בשטר קבלה וכתב וכן נראה דהא קיום שטרות שלשה וכו' נשמע מזה אם הם בעצמם מכירי' החתימות מ\"מ צריך להיות הקיום בשלשה ולא כסמ\"ע בסימן מ\"ו סק\"ז שכתב כשהם בעצמם מכירין החתימות יכולי' שנים לקיים וליתא אלא לעולם צריך להיות קיום שטרות בשלשה:","\u0003שלא יטיל בו שום תנאי\u0004. כתב הב\"י הטעם אפשר שידעו העדי' בקבלת הגט ולא ידעו מהתנאי ואזלו ומסהדי שיגיע הגט ליד שלוחה ונמצא הגט בטל, והב\"ח כתב הטעם משום האשה יכולה לומר לא מניתי השליח אא\"כ שיקבל בלי שום תנאי לפיכך אם אמרה שיקבל הגט אפילו על תנאי יכול להתנות תנאי וכן הסכים בט\"ז:","\u0003אבל י\"א שנכון להחמיר וכו'\u0004. כתב בט\"ז אם אי אפשר בלא ש\"ק יכולה לעשות ש\"ק אם יש עדות ברורה שמכירים חתימות השלשה דייני', וב\"ח ג\"כ התיר לעשות ש\"ק ומעשה היה בא' שהיה עתי' שוטה ועתי' חלי' וחלימתו היה מעט והתיר שהאשה תעשה ש\"ק במקו' שהוא בעת חלימתו והיא תחזור למקומה ובעת חלימתו ימסור הגט ליד ש\"ק שלה:","\u0003בנוסח הרשאת\u0004. כתב בד\"מ בתחלה ממני' השליח קודם שמצוה לכתוב, ואחר הנתינה ליד השליח אז יכתבו הרשאה, דאם יכתוב קודם מחזי כשקרא, וכותבים פיך כפי ואם לא כתב הכי לא יתן לו כי שמא הוא שליח רק על הנתינה אף על גב השליח נאמן לומר דעשאו לשליח מ\"מ כאן הכתב מכחישו ועיין תשו' מהר\"ם מינץ סימן קי\"ד, וכותבי' ושליח שליח עד מאה אבל אם כותב סתם ואני נותן לך רשות לעשות שלוחי' עד מאה י\"ל דקאי הכל על הראשון דהוא יכול לעשות שלוחי' עד מאה אבל השני א\"י לעשות שליח אחר לכן כותבין ושליח שליח וכו', וכותבי' אפי' בלא אונס ואם לא כתב כן בפירוש מ\"מ יכול לעשות שליח בלא אונס דהא א\"צ הרשאה אלא משום עשיות השלוחי' בלא אונס כמ\"ש בתשו' ריב\"ש וכינוי שליח אין כותבי' משום את\"ל דהוא איש אחר מ\"מ הוא כשר לשליחות פסקי מהרא\"י וא\"ל למה לא חיישינן שמא אין זה שלוחו אלא איש אחר שלוחו נמצא דזה הנותן הגט אינו שלוחו וי\"ל דלא חיישינן כיון שהגט ביד זה אמרי' בוודאי זה הוא שלוחו ואם מגרש את ארוסתו יכתוב בהרשאה שהבעל שולח הגט והרב המסדר כששואל לשליח ישאלנו בשם ארוס שם בשם תיקון ישן:","\u0003שליח הולכה וכו'\u0004. עיין בגוף התשובה בב\"י ס\"ס זה, וא\"ל אף על פי שתאמר שהוא ש\"ה וש\"ק אכתי פסול הגט מחמת דמוכח דהמסדרי' הגט היו ע\"ה וסברו דהבעל יכול לעשות ש\"ק, וי\"ל דאפשר לומר דלא היו ע\"ה אלא מה שכתבו דהוא ש\"ק לא כתבו אלא ליפוי כח ובאמת הוא ש\"ה אבל אם לא אמר דהוא ש\"ה מוכח דהוא ש\"ק והבעל א\"י לעשות ש\"ק מוכח דהם ע\"ה, וא\"ת אם יכולים לתרץ שהוא ש\"ה ומה שכתבו שהוא ש\"ק אינו אלא ליפוי כח א\"כ איך יכול השליח להכחיש וכן הקשה בד\"מ, וי\"ל תירוץ זה לא טענינן אנחנו אא\"כ כששליח אומר כן שומעים ולא נתבטל הגט אבל אנן לא טענינן כן ובגוף התשובה יש שם איזה דברים להתיישב:","\u0003חוץ מחש\"ו\u0004. אלו חמשה פסולים אפי' בא\"י דא\"צ לומר ב\"נ מ\"מ הם פסולים לשליחות ואם נתנו הגט אינו גט והא דמגורשת אם נתן הגט ליד עבדה דשם היא מתגרשת מתורת חצר, תוס', אבל רשעים כשירים לשליחות אלא דאין לסמוך על דיבורם מה שאומרים ב\"נ לכן בא\"י כשירים לשליחות וכן כשגט מקוים דא\"צ לומר ב\"נ כשר לשליחות, כתב הריב\"ש סי' ש\"צ העדים שנמסר הגט בפניהם יכולי' להיות דייני' ולא אמרינן בכה\"ג אין עד נעשה דיין:","\u0003להבאת הגט\u0004. אא\"כ נתקיים הגט וצ\"ל דליכא בידו שטר הרשאה דהא הרשאה הוי קיום כמ\"ש במרד' ובתשובת רשב\"א וכמ\"ש בסי' קמ\"ב סוף סעיף א' והריב\"ש דמחמיר שם אינו אלא חומרא בעלמא קשה למה הוא נאמן לומר דהוא ש\"ה דהא כתב הרא\"ש ש\"ה נאמן לומר דעשאו לשליח הואיל האמינוהו חז\"ל לומ' ב\"נ וב\"נ וכאן אינו נאמן לומר ב\"נ וב\"נ ולמ\"ש דהמחבר פוסק כרמב\"ם והרמ\"ה דס\"ל הא דנאמן לומר דעשאו לשליח לא תליא באמירת ב\"נ וב\"נ אפילו בא\"י או בגט מקוים נאמן לומר דעשאו ש\"ה כן י\"ל ברשע כשהגט מקוים אז נאמן לומר דעשאו לש\"ה כיון דגט כשר בידו אלא להרא\"ש קשה ואפשר דס\"ל דאיירי דיש הרשאה בידו מ\"מ חיישינן שמא לא זהו הגט דמסר הבעל בידו אף על גב בעלמא לא חיישינן מ\"מ כשהגט ביד הרשע חיישינן שמא זייף זה לכן צריך להתקיים הגט:","\u0003אא\"כ נתקיים\u0004. משמע אפי' בא\"י דאין צריך לומר ב\"נ וב\"נ מ\"מ פסול להביא אם אינו מקוים וב\"ח מפרש דברי הטור בזה פליגי הרא\"ש והרמ\"ה, הרא\"ש ס\"ל בא\"י יכול להביא אפי' אינו מקוים כיון דא\"צ לומר ב\"נ וב\"נ והרמ\"ה ס\"ל אפילו בא\"י א\"י להביא הגט כשאינו מקוים מיהו למ\"ש בסמוך אפילו אם יש הרשאה חיישינן שמא מזויף הוא צריך ישוב למה יכול להביא בא\"י כשאינו מקוים ולמה לא חיישי' שמא מזויף הוא:","\u0003ויש פוסלין\u0004. כן הוא דעת הרמב\"ם וכתב כשהגט אינו מקוים אינו גט נשמע דס\"ל דהגט בטל ואין קידושין של אחר תופסין בה ולא ככ\"מ שכתב דספק גט הוא, והראב\"ד הקשה למה הגט בטל ולא חיישינן שמא יתקיים הגט והמגיד תירץ דאיירי שחקרו אחר עידי קיום ולא נמצאו אז הגט בטל ואין קידושין של אחר תופסי' בה, מיהו קשה דהא אם שליח מביא גט או האשה מביאה קי\"ל דמותרת לישא ע\"פ הדין אפילו לא ניכרת לנו חתימות העדים ולמה כאן הגט בטל אף על גב הכא גרע טפי כיון השליח הוא רשע מ\"מ למה הגט בטל לגמרי ואין קידושין של אחר תופסים בה הא ליכא אלא חשש זיוף, ואפשר לומר הרמב\"ם לטעמו דס\"ל עדים החתומים מדאורייתא הוי מפי כתבם אלא חז\"ל תקנו דמקבלין עדותן אפילו בגיטין הבאים לכן כל שאינו כתקנות חז\"ל הגט בטל גם י\"ל למ\"ש לעיל דהרמב\"ם ס\"ל כשא' טוען מזויף צריך קיום מדאורייתא וס\"ל כל כה\"ג שהוא ביד רשע טענינן אנן מזויף הוא וצריך קיום מדאורייתא:","\u0003ודין מומר וכו'\u0004. כ\"כ הש\"ג וטעמו משום נכרי ממועט מטעם שהוא אינו בן ברית או מטעם שאינו בתורת גיטין ומומר בן ברית הוא והוא בתורת גיטין וקדושין לכן ס\"ל דהוא כשר לשליחות, והא דהוא פסול לכתוב גט משום דאינו כותב לשמה, מיהו בתוס' סנהדרין דף ע\"ב משמע דדין מומר כדין נכרי דכתבו שם מומר לאו בן ברית הוא וכן משמע מהרמב\"ם פ\"ג לכן כתב דין מומר כדין נכרי ומיום שנעשה מומר הוי כאלו אינו בתורת גיטין וקדושין ועיין סי' קכ\"ג:","\u0003כשרים\u0004. כאן א\"צ תחלה וסוף בכשרות דהא הם כשרים לשליחות אלא הטעם הוא משום דחיישינן שמא הוא משקר כיון שהוא רשע לכן כשעשה תשובה תו ליכא חשש דמשקר הוא כשר לשליחות:","\u0003איני מכירה\u0004. ואם אמר לשנים כתבו הגט ותנו לפלוני שלוחי או שאמר להם כתבו גט ותנו לפלוני שלוחי ויוליך לה מבעיי' בש\"ס ופי' הרי\"ף הסוגי' איירי לענין אם שנים אלו יכולים להיות שלוחים למסור הגט לידה, ושאר מפרשים פירשו לענין אם נאבד הגט מיד השליח יכולים לכתוב גט אחר כמ\"ש בסי' קכ\"ג וא\"ל לשיטות הרי\"ף דס\"ל לענין אם שנים אלו יכולים למסור לה הגט דלא אפשט בעיי' זו וכאן פליגי בש\"ס אם הראשון יכול למסור הגט, וי\"ל שאני הכא דאמר בפי' דאין מכיר אות', והרמב\"ם כתב פ\"ט דין ל\"א אם אמר תן לפלוני והוא יוליך לה אם הוליך בעצמו אינו גט וכתב עוד שם דין ל\"ט הדין דכאן אם אמר הראשון איני מכיר' ופי' המגיד מ\"ש הרמב\"ם אם אמר תן לפלוני ויוליך לה אינו גט למד מדין דכאן וצ\"ל דלא ס\"ל החילוק זה ולרמב\"ם גם כאן אם הראשון מסר הגט לה אינו גט ומ\"ש ואם נתן הראשון ה\"ז ספק מגורשת כ\"כ הרשב\"א אבל הרמב\"ם ס\"ל שני דינים הללו שוין ובשניהם אם מסר הראשון אינו גט אבל הבעיי' בש\"ס אם אמר תן לשלוחי ויוליך לה ס\"ל דאיירי לענין אם נאבד הגט כדעת כל המפרשים לא כשיטות הרי\"ף כמ\"ש בסי' קכ\"ו:","\u0003יתנהו לה ע\"פ שנים\u0004. אף על גב סומא א\"י ליתן ע\"פ שנים שאני סומא דא\"י לראות, תוספות:","\u0003חלה או נאנס\u0004. ואם יש בידו הרשאה דיכול לעשות שליח אף על גב דלא כתב דיכול לעשות בלא אונס דרשינן לישנא יתירא דרשות בידו לעשות שליח בלא אונס דהא באונס יכול לעשות שליח אחר בלא רשות שלו ול\"ל הרשות אלא ע\"כ דנתן לו רשות לעשות שליח אפי' בלא אונס ב\"י וד\"מ:","\u0003ובלבד שיאמר הבעל וכו'\u0004. וכן אם נותן בעצמו הגט לידה ומתנה שאל תהא מגורשת עד זמן פלוני צריך להתנות שתהי' נאמנת ש\"ג ספ\"ג:","\u0003ויש מי שאומר וכו'\u0004. הטעם משום דיש לחוש שמא ישנה ויתן לה תוך ל' יום ועיין סעיף נ\"ח:","\u0003לא ישלחנו\u0004. והא דכתיב ושלח ושלחה ולמדו מזה דשליח עושה שליח ומשמע אפי' בלא אונס י\"ל הקרא איירי כשגילה דעתו דאינו מקפיד כ\"כ תוס' והר\"ן ומזה נשמע אפי' לא התנה בפי' דיכול לעשות שליח רק גילה דעתו דאינו מקפיד יכול לעשות שליח:","\u0003פי' לו שלא ישלחנו\u0004. ק\"ק בעובדא דרבא דמסר השליח לשליח אחר ואמר רבא מ\"ט משום אנוס האי נמי אנוס ולא שאל שמא פי' לו המשלח שלא ישלחנו ע\"י אחר וכעין זה הקשה הר\"ן על הראב\"ד דס\"ל אם אמר הולך סתם יכול לשלוח ע\"י אחר אפי' אם לא חלה והקשה מסוגיא דרבא למה אמר רבא האי נמי אנוס ולא שאל לשליח שמא אמר הולך סתם ויכול לעשות שליח בלא אונס ומכ\"ש דקשה למה לא חייש שמא אסור לשלוח ע\"י אחר ותירוץ של הר\"ן לא שייך כאן:","\u0003אין צריך למנותו בפני ב\"ד\u0004. כי מה שאומר ב\"נ הוא הקיום לכן צריך ב\"ד אפי' אם הבעל נתן לו רשות לעשות שליח אחר, ואם ממנה שליח אחר בפני שנים מצטרפים השליח ג\"כ והוי ג' כ\"כ בתשובת ריב\"ש ולקמן סי' קמ\"ב סעיף ט' ומשמע אפי' מאן דמחמיר שלא להצטרף השליח כשנותן הגט לאשה מ\"מ כאן מקילין וכ\"כ בפריש' סי' קמ\"ב:","\u0003אבל צריך למנותו בפני עדי'\u0004. כ\"כ הרא\"ש ולטעמו אזיל דס\"ל ש\"ה צריך למנותו בפני עדים אבל רמב\"ם ס\"ל דא\"צ עדים כמ\"ש בפ\"ז דין כ\"א והמחבר בסעיף י\"א הביא דעת הרא\"ש בלשון י\"א משמע דס\"ל עיקר כהרמב\"ם ומ\"ש כאן צריך למנותו אלא בפני עדים צ\"ל דחושש לחומר' מלצאת כל הדיעות אבל אין לומר מ\"ש דצריך למנותו בפני עדים משום דצריך להביא כתב בעדים דעשאו לשליח דלמה לא מהני כתב שליח הראשון גם כתבתי לקמן דהמחבר פוסק כהרמב\"ם והרמ\"ה דשליח נאמן לומר דהוא שליח אפי' היכא דאין צריך לומר ב\"נ וב\"נ אלא ע\"כ דחושש לחומרא כדעת הרא\"ש:","\u0003יכול שליח וכו'\u0004. מזה נמי משמע אפי' אם כבר נתן השליח הראשון את הגט לשליח השני עדיין לא נגמר שליחתו דאל\"כ איך יכול הוא להיות שליח אלא ע\"כ דעדיין הוא שליח ולא כח\"ר שהבאתי בסי' קמ\"ב סעיף י\"ג, ובט\"ז כתב אפילו אם השני חי יכול הראשון ליקח ממנו הגט:","\u0003משום דה\"ל מילי\u0004. כיון דאינו מוסר לו שום דבר מ\"ה הוי מילין אבל ש\"ה מוסר לו הגט ושליח הבאה שלה לא הוי מילין כיון דעיקר שליחות נגמר בעת שנותן הגט ליד השליח, ובבדק הבית הקשה על הטור בסי' זה משמע אומר אמרו לא הוי מילין ויכול לעשותו ובסי' ק\"כ פוסל אומר אמרו ותירץ בד\"מ מ\"ש הטור דלא הוי מילין לאו כוונתו דמכשיר אומר אמרו אלא כוונתו משום מילין ליכא פסול אבל אומר אמרו אסור משאר טעמים כמ\"ש בסי' ק' ועיין דרישה וב\"ח:","\u0003ואז יכול למנות אחר בלא בית דין\u0004. דהא השליח אין צריך לומר ב\"נ וב\"נ וכן יכול לעשות שליח בלא אונס ועיין בתשובת רשב\"ץ שהביא הב\"י שם מבואר כמה חלוקי דינים:","\u0003כל שהגיע הגט ליד א'\u0004. כתב הרשב\"א אם אמרה כל מי מכם שירצה הבעל ליתנו לו יהא שלוחי לקבלה אפשר נאמר בזה אין ברירה ועיין סי' ל\"ז סעיף י' מ\"ש:","\u0003תנהו לה במקום פלוני וכו'\u0004. דיש לומר דאין רצונו שיתן לה במקום אחר דשם יעליזו לכן יש קפידא אפילו לא אמר אל תתנהו אלא במקום פלוני, אבל אם אמר שיתן בעליה או באיזה יד מסתמא ליכא קפידא אא\"כ שאמר אל תנהו אלא כך וכך:","\u0003בתוך הזמן וכו'\u0004. כי מסתמא יש קפידא שלא יקדים לגרש כמו שכתב בש\"ס לא מקדים אניש פרעניות לגרש את אשתו לכן יכול לאחר ולא להקדים:","\u0003בכל מקום שיקבלנו הוי גט\u0004. וא\"ל אפילו כשיגיע לאותו מקום למה היא מגורשת הא הוי כאומר טלי גיטך מע\"ג קרקע דאינה מגורשת משום שלא בא לידה מידו וה\"נ לא בא הגט מיד הבעל כיון דאינה מגורשת נמי תירצו תוס' בתירוץ א' דאמר לש\"ק שלה שהוא יהיה ש\"ה עד לשם ושם יעשה ש\"ה אחר ויקבל ממנו הגט ונ\"מ למ\"ש לעיל רס\"ז ועוד תרצו דהוי כאלו קבלה מידו והא דאינ' מגורשת מיד משום דהוי כאלו התנה שאל תהי' מגורשת עד שיבוא לשם והוי כאלו מתנה עמו שאל תגרש עד אחר ל' יום ולכאורה היה נראה דצריך ליתן לה נאמנות שתהיה נאמנת לומר שלא פייס אותה כמ\"ש לקמן מיהו דלא מצינו בשום פוסק דכתב כן י\"ל דוקא כשהוא מתנה שאל יהי' גט עד אותו זמן אז יש לחוש שיערער ויאמר שקבע הזמן בכיון שיכול לפייס אותה תוך הזמן אבל כשהי' קובע /קובעת/ זמן אין חוששין:","\u0003לא ישלחנו ביד אחר\u0004. הנה לשיטות הרמב\"ם הטעם הוא דלא ישלחנו ביד אחר משום אין רצונו שיהיה פקדונו ביד אחר לפ\"ז דבר שאין קפידא כגון שצוה שתמחול לא זכות שלה קודם נתינות הגט יכול לשלוח ע\"י אחר ולא חיישינן שמא ישנה השליח השני וכ\"כ תוס' שם אבל לשיטות רש\"י חיישינן שמא ישנה השליח השני ואסור לשלוח ע\"י שליח אחר אפילו בדבר שאין קפידא מיהו למסור הפקדון ליד אחר אף לרש\"י אסור אלא אפי' דבר שאין פקדון אלא בכה\"ג שתמחול הזכות מ\"מ אסור לשלוח ע\"י אחר מטעם הנ\"ל ודברי הטור תמוה מ\"ש דיכול לשלוח ע\"י אחר גם דברי השואל בתשו' הריב\"ש לשיטות רש\"י תמוה וקי\"ל כחומרת תרי טעמים ואסור לשלוח ע\"י אחר אפילו אם חלה הראשון לא מבעיא לפירוש תוס' לא ישלחנו ע\"י אחר דהא הוי שינוי אלא אפילו לשיטות הרמ\"ה ורש\"י נראה דלא ישלחנו ע\"י אחר דהא חיישינן שמא ישנה לפ\"ז אפילו אם נתן לו רשות לשלוח ע\"י אחר ולא כתב אפילו בלא אונס א\"י לשלוח בלא אונס אף על גב דכתבתי לעיל אם נותן לו רשות סתם לשלוח ע\"י אחר יכול לשלוח אפילו בלא אונס דשם הטעם משום דדרשינן לישנא יתיר' למה נתן לו רשות לשלוח דהא ע\"י אונס רשאי לשלוח בלא רשות אלא ע\"כ דנתן לו רשות לשלוח בלא אונס אבל כאן א\"י לשלוח אפילו אם יש לו רשות י\"ל נתינות רשות הוא אם יהיה לו אונס מיהו בתשובת ריב\"ש לא משמע כן:","\u0003אינו גט\u0004. לדעת הרמב\"ם אפילו אם אמר סתם טול חפץ ותן לה הגט אמרינן דהוא מקפיד שאל יתן לה הגט עד שתתן החפץ כיון דהזכיר לקיחות החפץ קודם נתינות הגט אבל אם מזכיר נתינות הגט קודם לקיחות החפץ לא אמרינן דמקפיד שיתן הגט קודם הלקיחות החפץ דאין זה סברא שיקפיד בזה מיהו אם אמר תן גט ואחר כך טול החפץ י\"ל דהוי קפידא, והרמ\"ה ס\"ל אם אמר סתם טול החפץ ותן לה הגט ליכא קפידא שיעכב הגט עד אחר נתינות החפץ אלא א\"כ שאמר טול החפץ ואח\"כ תן הגט אז הוא מקפיד שאל יתן הגט עד שתתן החפץ והרמב\"ן ס\"ל אפי' אם אמר תן הגט וטול החפץ מ\"מ הוא מקפיד שאל יתן הגט עד שיטול החפץ כיון דזכר הלקיחות החפץ כמ\"ש בח\"ה סי' נ\"ח:","\u0003במקום שא\"צ לומר ב\"נ\u0004. אבל היכא דצ\"ל ב\"נ אם לא אמר הגט פסול אפי' בלא ערעור כמ\"ש לקמן סי' קמ\"ב, אף על גב בעלמא טענינן בשביל יתומים שמא מזויף הוא מ\"מ כאן מקילין משום תקנות עגונות או משום חומרא שהחמירו בסוף כ\"כ תוס' ב\"מ דף י\"ג ובריש גיטין ובכתובו' פ' הנושא דטועני' בעלמא מזויף בשביל יתומים וכאן משמע אם השליח מביא הגט מותרת לישא אפי' אין מכירי' החתימו' אפי' מאן דמחמיר לקמן בסי' קמ\"ב כשהיא בעצמה מביאה גט שאין מקוים מ\"מ כשהשליח מביא מודה דמותרת להנשא:","\u0003מבני חרי\u0004. אבל אין מוציאין מלקוחות ומיתומי' משום דטוענין שמא מזויף הוא אבל מב\"ח גובה דמספר כתובה נלמד שכותבי' כשתנש' לאחר תגבה כתובתך כ\"כ הרא\"ש פ\"ק דגיטין, אף על גב ר\"י ס\"ל דאין טוענין מזויף בשביל יתומים ולקוחות לא קי\"ל כר\"י וכ\"כ הר\"ן דאין גובה מלקוחות משום דטוענין שמא מזויף הגט ועיין בש\"ך בח\"ה סי' ק\"ו וא\"י למה לא הביא הדין מה דמפורש כאן דטוענים מזויף ומשמע מהרא\"ש אפי' אם הלקוחות טוענין ברי דמזויף הגט מותרת להנשא ואמרי' דאומרי' כן כדי שלא תטרוף מהם:","\u0003תצא ואם בא הבעל וכו'\u0004. משמע אם ערערו העדים לא מהני הקיום ועיין בטור ס\"ס קנ\"ב:","\u0003הולד ממזר וכולי אבד הגט ה\"ז ספק מגורשת\u0004. כ\"כ הרמב\"ם וכ' המגיד הטעם הואיל הבעל טוען ברי מזויף והיא א\"י אמרינן העמד אשה על חזקתה דהיא א\"א לכן הולד ממזר ודאי ושאר פוסקים ס\"ל דהיא ספק מגורשת והולד ספק ממזר ולכאורה קשה למה הולד ממזר ודאי לדעת הרמב\"ם או ספק ממזר לדעת שאר פוסקים דהא קי\"ל כריש לקיש דאמר עדים החתומים על השטר הוי כמו שנחקרו עדותן בב\"ד והקיום אינו אלא מדרבנן א\"כ כאן ליכא ספק דאורייתא אלא ספק דרבנן ולמה כתב דהגט בטל ולשאר פוסקים ספק מגורשת הא ליכא כאן אלא ספק דרבנן וכן הקשה ברש\"ך ונ\"ל מכאן מוכח דס\"ל להרמב\"ם ולפוסקים אלו כהגמ' דקדושין דכתב כשאיש טוען מזויף בעינן קיום מדאורייתא ור\"ל לא איירי בטוען מזויף ועיין בסימן מ\"ב מ\"ש ובמוהרי\"ק שורש ס\"ו ובתשובת מהרשד\"מ סי' א' וכן מוכח מרמב\"ם רפי\"ב והטור בסי' קנ\"ב ובש\"ע שם דכתבו כשהי' מביאה את הגט והבעל טוען מזויף אינה מגורשת ושם טוענת היא ברי ומ\"מ מדאורייתא בטל ע\"כ דסבירא ליה כהג\"מ גם בל\"ז אין סברא לומר כשהלוה טוען מזויף והמלוה טוען ברי עדיף מה לנו בברי שלו פשיטא כשרוצה לגבות יאמר דשטרו טוב אלא ודאי אם בעינן קיום ומדאורייתא כשמלוה א\"י והלוה טוען מזויף ולא אמרי' עדים שנחתמו כמו שנחקרו עדותן כן הוא אפילו כשמלוה טוען ברי דשטרו טוב הוא והלוה טוען ברי בעינן קיום מדאוריי' ועיין בח\"ה סי' כ\"ח שם מבואר דהרמב\"ם ס\"ל עדים החתומים על השטר מדאורייתא הוי עדות מכתב אלא חז\"ל תקנו דפוסקים ע\"פ שטר וכבר השיגו עליו הרמב\"ן ושאר פוסקים מסוגיא זו דאמר ר\"ל עדים החתומים כמו שנחקרו עדותן בב\"ד גם קשה לדידיה א\"כ הגט הבא ממה\"י מדאורייתא לא מהני דהא הוי עדות החתומים המעידים על הגט כעדות ע\"פ כתבם ואי אמרת באמת ס\"ל להרמב\"ם אף בזה מכאן דמקדש ע\"ד דרבנן וחז\"ל תקנו גט כזה כשר א\"כ לא צריך המגיד ליתן טעם לדין זה דהא מדאורייתא לא מהני אלא מתיקון חז\"ל אם כן אם אינו מקוים אז הוא בטל מדאורייתא:","\u0003שהרי אינה מגורשת\u0004. כ\"כ הרמב\"ם משמע דאינה מגורשת כלל ואין קידושין של אחר תופסים לפי הכלל מ\"ש בפ\"י ולא כהב\"י שכתב קידושי' של אחר תופסים בה מיהו לדינא בודאי יש לחוש לקדושין של אחר דהא לשאר פוסקים אינה אלא ספק מגורשת ואם אין צריך קיום מדאורייתא אף בכה\"ג אינו אלא ספק מדרבנן:","\u0003אפילו היא אחותה\u0004. הנה רש\"י פי' בש\"ס הטעם דיבמה אסורה להביא גט משום דחיישינן לאתי לקלקלה משום דיראה שמא סופה להיות צרתה לפ\"ז באחותה דלא שייך טעם זה י\"ל דמותר' להביא גט מיהו המגיד כתב לא פלוג חז\"ל כיון יבמה שאינה אחותה אסורה להביא גיטה ה\"ה אחותה ה\"ה אין הכלה נאמנת לחמותה ולא אשת האב לבת בעלה ונראה ה\"ה אם יבמה א\"י להביא הגט ה\"ה להעיד על בעלה כמ\"ש בסימן י\"ז אפילו היכא דהיא אסור' לבנה א\"י להעיד דלא פלוג חכמי' ועיין סי' י\"ז:","\u0003וי\"א שאינן נאמנות\u0004. דנשים לאו דינא גמירי וסברה אפילו כשאמרה ב\"נ וב\"נ אין בכך כלום ובעל יכול לערער:","\u0003אם נתקיים בחותמיו\u0004. דש\"ק הוא כאשה עצמה וכיון שהבעל אומר מזויף צריך קיום ובלאו הכי אינה נאמנת כך דין השליח כ\"כ המגיד אפי' להפוסקים דס\"ל השליש נאמן אפי' אם הבעל דבר אומר דלא נתן לידו בתורת שלישית כמ\"ש בח\"ה סימן נ\"ו ש\"ה כשאינו מקוים הוי כאלו אין בידו כלום:","\u0003השליח נאמן\u0004. אפי' בלא מיגו אפילו אם אמר דמסר לידו בעדים מ\"מ הימני' דזמנין ימותו העדי', תוס' והרא\"ש:","\u0003בעיר אחת וכו'\u0004. כן ס\"ל כמה פוסקים דפסקו כרב הונא דבעל נאמן דוקא בעיר אח' ולכאורה נראה דהרי\"ף והרמב\"ם לא ס\"ל חילוק זה אליבא דר\"ה דהא הם פסקו כר\"ח שהוא תלמיד משום דהביאו ראיה מהסוגיא דאתי' כר\"ח משום דהקשה שם ולהימני' לשליש וכו' ש\"מ דהלכה כר\"ח דס\"ל דהשליש נאמן ואי הוי ס\"ל לר\"ה ג\"כ השליש נאמן כשאינה בעיר א' א\"כ שפיר אתי' אף אליבא דר\"ה היינו כשאינה בעיר א' אלא ודאי דלא ס\"ל חילוק זה:","\u0003אבל אם טוען שעשאו ש\"ה וכו'\u0004. והשליח טוען שהוא ש\"ק אז לא אמרי' אם איתא בתורת גירושין לדידה יהיב הלא לפי דבריו נמי לגירושין נתן ומ\"מ לא יהיב לדידה ולא אמרי' דלא יהיב לדידה כי היכא דלא תתגרש מיד, ולפי שיטה זו אם הבעל אומר לפקדון נתתי והשליח אומר להולכ' הבעל נאמן מטעם אם איתא דלגירושין יהב לדידה הוי יהיב ולא אמרי' דלא נתן לידה כי היכא דלא תתגרש מיד וכן מוכח מתוס' שהבאתי לעיל דהא הקשו מה הועילו חז\"ל בתקנתן שיאמר ב\"נ וב\"נ אכתי יאמר הבעל לפקדון נתתי ש\"מ אפי' בש\"ה נמי הבעל נאמן לומר לפקדון נתתי וכן כתב הר\"ן בשם תשו' הרי\"ף והרשב\"א דהסוגי' איירי בזה דהבעל אומר לפקדון נתתי והשליח אומר להולכ' ונתן ליד' ופליגי בזה ר\"ה ור\"ח ולא כהר\"ן שכתב בתירוץ א' בכה\"ג לא אמרי' למה לא יהיב לדידה די\"ל דלא יהיב לה כי היכא דלא תתגרש מיד, והרא\"ש פוסק כרב הונא דבעל נאמן וס\"ל אם הבעל אומר לפקדון והשליח אומ' להולכ' נאמן השליח כמ\"ש ריש גיטין וכבר כתבתי דמשמעות הוא אפילו כשהם בעיר א' והטור לא כ\"כ:","\u0003והוא שבאים וכו'\u0004. כלומר הא דשליח נאמן ותתגרש בקבלתו דוקא כשיש עדים שהוא ש\"ק אבל בש\"ה אפילו ליכא עדים נאמן הוא ותתגרש כשמגיע הגט לידה כמ\"ש לעיל ומשמע אפילו אם הבעל א\"י שהוא ש\"ק מ\"מ הוא נותן ליד השליח הגט שתתגרש מיד אם הוא ש\"ק, ולהפוסקים דס\"ל בעיר א' הבעל נאמן משמע אפילו אם יודע שהוא ש\"ק ועיין לקמן:","\u0003וי\"א דוקא וכו'\u0004. לא מצינו דיעה זו מפורש אלא בד\"מ מדייק כן מדברי הטור שכתב הרמב\"ם כתב השליח נאמן בכל ענין אפילו אם אין הגט בידו רק ראו הגט בידו וא\"א כתב כסברא הראשונה פי' הוא להרא\"ש אין השליח נאמן אא\"כ הגט בידו ולא מהני מה שראו העדים בידו ולא כהרמב\"ם, ואין מוכרח די\"ל כוונת הטור דהרא\"ש פוסק כסברא הראשונה היינו בפלוגתת ר\"ה ור\"ח פוסק כר\"ה דהבעל נאמן בעיר א' אבל כשאינו בעיר א' השליח נאמן יש לומר דנאמן אפי' אם הגט אין בידו אלא ראו בידו, ואין להוכיח מדברי הרא\"ש דראו לא מהני דהא הרא\"ש פי' הסוגיא דהגט ביד השליח ומחמת זה הוכרח לדחוק במימרא שם מודה ר\"ה אם היא אמרה בפני נתת לגירושין נאמנת איירי נמי דהגט ביד השליח נאמנת היא לומר בפני נתת ליד השליח במיגו גרשתני כמ\"ש בסמוך ואם איתא דסבירא ליה ראו ביד השליח מהני למה ליה לדחוק ולמה לא מפרש דאיירי דהעדים ראו הגט שלה ביד השליח והיום הגט ביד האשה מ\"ה נאמנת היא לומר בפני נתת לגירושין במיגו לידי נתת לגירושי' אלא ע\"כ ראו לא מהני דיש לדחות דלמא ס\"ל כסבר' הר\"ן אם הגט ביד האשה עדיף טפי ומודה ר\"ה דהשליח נאמן ופלוגתת ר\"ה ור\"ח היא כשהגט ביד השליח בזה ס\"ל ר\"ה הבעל נאמן כיון דלא מסר לה להתגרש בו ומתוס' משמע ראו מהני דהא פירשו להמקשן דהקשה קיבל למה לי היינו דסגי אם ראו בידו הגט, וי\"ל דס\"ל לרמ\"א תוספת כ\"כ אליב' דמתני' דלא בא הבעל ומכחיש אותו אז מהני אם ראו בידו הגט משא\"כ כשהבעל מכחישו ועיין לקמן, ובד\"מ הבי' ראיה לזה ממ\"ש בח\"ה סי' נ\"ו השליש קודם שנותן השלישית מידו צריך שיאמר אופן שלישתו לפני הב\"ד או לפני עדים משמע אם ראו בידו לא מהני ויש לדחות בוודאי לענין אופן שלישית לא מהני ראו בידו אבל לענין זה מהני אם ראו בידו גט והוא ש\"ק אמרי' בוודאי נמסר לידו לגירושין ולא לפקדון ועיין מ\"ש בסעיף י\"א:","\u0003ואין חילוק בזה וכו'\u0004. היינו אם הבעל אומר לפקדון נתתי והשליח אומר להולכה נתן לידי לר\"ה בעיר אחת הבעל נאמן ולא כסברת הר\"ן דכתב בזה לכ\"ע השליח נאמן כמ\"ש לעיל, וע\"כ בש\"ה צריך לומר דליכא עדים דהבעל עשאו לש\"ה דאם לא כן איך י\"ל לפקדון נתתי אלא דליכא עדים ומ\"מ נאמן כמו שליש בעלמא דנאמן אלא בש\"ק בעינן עדים כי היכא דתתגרש בקבלת השליח, ולהרי\"ף בתשו' איירי הסוגיא כשהבעל אמר לפקדון והשליח אומר ש\"ה אני ופוסק ר\"ח השליח נאמן, ולתוס' נאמן הבעל לומר לפקדון נתתי כשהם בעיר א' וכן הוא לשיטות הרשב\"א, ולכאורה קשה על הרב רמ\"א כאן כתב ואין חילוק וכו' משמע בעיר א' יכול הבעל להכחישו ובסי' קמ\"ב פסק כשם שנאמן לומר בפני נכתב ובפני נחתם כן הוא נאמן שהוא שלוחו, ואין לומר כאן איירי כשאין צריך לומר בפני נכתב ובפני נחתם אז יכול להבעל להכחישו ובסי' קמ\"ב איירי כשהשליח אומר בפני נכתב ובפני נחתם דהא שם סעיף ו' לא משמע כן גם לפ\"ז דבריו סתומים ואפשר אף על גב הבעל יכול להכחישו מ\"מ לא חיישינן שמא יבוא ויכחיש ואיירי שם כל זמן דלא בא ומכחיש נאמן הוא לומר בפני נכתב ובפני נחתם מיהו הלשון שכתב שם כשם שנאמן לומר בפני נכתב ובפני נחתם וכו' משמע אפילו אם מכחיש הבעל וע\"כ צ\"ל מ\"ש שם כשם שנאמן לומר איירי כשאינן בעיר א' אף על גב לענין בפני נכתב ובפני נחתם נאמן אפי' בעיר אחת מ\"מ לענין נאמנות שהוא ש\"ה אינו נאמן בעיר אחת:","\u0003נאמנת\u0004. במיגו אפילו אם הגט ביד השליח ואפילו בעיר אחת נאמנת במיגו די\"ל לידי נתת והפקדתיו ליד השליח ואז היא נאמנת דהאשה אומרת גרשתני נאמנת אף על גב השליח מסייעה לא אמרינן דמעיזה כל שאין שני עדים דמסייעין לה כ\"כ הרא\"ש ועיין ר\"ס י\"ז שם כתב הטור אפילו אם איכ' א' דמסייעה מעיזה ולא כהרא\"ש וצריך ישוב, אבל אם אינה אומרת בפני נתת ליד השליח לגירושין והם בעיר אחת אינו נאמן השליח להני פוסקים ולא אמרינן מיגו דיהיב השליח הגט לידה די\"ל דאין רצונה לקבל הגט כל שא\"י בודאי דהבעל נתן ליד השליח לגרושין כן משמע מהרא\"ש לפ\"ז אפילו אם היא א\"י דהבעל מערער מ\"מ כל שא\"י שנתן לגירושי' אין רצונה ליטול הגט, ובתוס' לא משמע כן דהא כתבו דאין רצונה לקבל הגט כיון דשמעה דהבעל מערער משמע כשהי' א\"י דהבעל מערער מקבל הגט ואף לדעת תוספות נראה אם עדיין הגט ביד השליח ועכשיו מערער הבעל תו לא אמרינן מיגו דהיה נתן קודם הערעור של הבעל הגט ליד האשה דאז הוי מיגו למפרע ולא אמרינן מיגו למפרע כמ\"ש בהרא\"ש סוף כתובות ועיין בסמ\"ע ובש\"ך בח\"ה סי' פ\"ב:","\u0003וי\"א דוקא וכו'\u0004. וכן הוא לשיטת הרי\"ף שהבאתי לעיל דכל הסוגיא איירי כשהגט ביד האשה ובזה נאמנת לומר בפני ניתן לגירושין וכן הוא לפי מ\"ש בתשובת הרשב\"א ובח\"ר:","\u0003היה הגט יוצא מיד האשה\u0004. כ\"כ הרמב\"ם וס\"ל כשהגט ביד האשה הוי כאלו היה ביד השליח אפילו לא ראו הגט ביד השליח אלא כיון דיכולה ליתן לידו הוי כאלו הגט בידו ועיי' בתשובת רשב\"א ובח\"ר מיהו צ\"ל דאיירי כאן כשהם בשני מקומות דהא בעיר אחת יכול הבעל לומר לפקדון נתתיו אבל אין לומר כשהגט ביד האשה עדיף טפי כמ\"ש בהר\"ן והבאתיו לעיל דהא בסעיף נ\"ז איירי נמי שהגט ביד האשה ומ\"מ יכול הבעל להכחישו בעיר אחת:","\u0003אעפ\"י שהבעל אומר לגירושין נתתי וכו'\u0004. הנה לפי הסוגיא פי\"נ אם אומר גרשתי אינו נאמן והיא ספק מגורשת כמ\"ש לקמן סי' קנ\"ב אם כן אפילו אם הבעל אומר נתתי ליד השליח והוא ש\"ק הוי ספק דהא לא עדיף מאומר גרשתי ונתתי לידה הגט השליח אינו אלא ע\"א והא דאיתא בסוגיא זו דהיא ספק מגורשת משום לקולא לא אמרי' שליח עושה שליחותו משמע אם אמר נתתי לש\"ק מגורשת בודאי יש לומר דסוגי' זו אתיא אליבא המ\"ד בעל שאמר גרשתי נאמן אבל להמסקנא פי\"נ אפילו אם אמר נתתי ליד ש\"ק היא ספק מגורשת ובזה מיושב שפיר דברי רי\"ו שהבי' הב\"י וע\"ש ומ\"ש הטור דספק הוא אם שליח עושה שליחותו יש לומר כוונתו אפילו בש\"ה ספק הוא:","\u0003הואיל והבעל והשליח מסייעים\u0004. ואם השליח לבד מסייע היינו פלוגתא כמ\"ש בהרא\"ש וכמ\"ש בסמוך:","\u0003וערער שלא כתבן\u0004. ואם ערער ואומר לפקדון נתתי אז תליא בפלוגתא הנ\"ל ואם אמר ממני נפל כתבתי לעיל דפליגי בזה הפוסקים:","\u0003שהרי עדים מעידים\u0004. ואם ע\"א הביא לה נאמן אם היה אצל הכתיבה והחתימה במיגו די\"ל הוא ש\"ה כ\"כ הרשב\"א בתשו' סי' אלף רנ\"ח:","\u0003וי\"א שאם שלשתם וכו'\u0004. לדעת הרא\"ש כל זמן שלא בא הבעל ומכחיש לא חיישינן שמא בא ויכחיש ומותרת אפילו לר\"ה אלא המגיד כתב לשיטות הפוסקים דפסקו כר\"ה אפילו לא בא הבעל חיישינן שמא יבוא ויכחיש, וכ\"כ הרשב\"א וכן הוכחתי לעיל לשיטות הרי\"ף ורמב\"ם לר\"ה חיישינן שמא יבוא ויכחיש:","\u0003ואפילו אינן בעיר א'\u0004. הג\"ה זו תמוה כי בד\"מ מדייק זאת מהטור ואין שום משמעות בטור כמ\"ש לעיל גם הבאתי דברי תוס' דכתבו אם ראו עדים הגט בידו מהני מיהת כשלא בא הבעל ומכחיש והיינו קושית המקשן קיבל למה לי וכאן נמי מיירי דאין הבעל מכחיש ועדים אלו ראו בידו הגט מנ\"ל דלא מהני, אבל אין להקשות עליו ממ\"ש הרי\"ף והרשב\"א דסוגיא איירי כשהגט ביד האשה ומ\"מ לר\"ח השליח דינו כשליש ונאמן, די\"ל דס\"ל לר\"ח השליח נאמן טפי אבל לר\"ה הבעל נאמן אא\"כ כשהשליח שליש בודאי והגט בידו לכן לא הביא י\"א אלו בסעיף נ\"ו דס\"ל שם אייתי כשיטות הרמב\"ם דפוסק כר\"ח וכאן דאייתי כשיטו' הפוסקים דפסקו כר\"ה מביא י\"א אלו גם בל\"ז שפיר להרי\"ף ורשב\"א הטעם דאי בעי מהדר לה בידיה וכ\"כ בח\"ר משא\"כ דשליח קבלה שלה אינו בכאן ובזה ניחא נמי דלא הביא י\"א אלו בסעיף נ\"ו:","\u0003בפני שנים\u0004. אבל כשמבטל בפני השליח א\"צ שנים כן הוא דעת הרמב\"ם והטור אבל תוס' ר\"פ השולח מסופקים בזה:","\u0003ואין הבעל נאמן\u0004. כשאין עדים דביטל כ\"כ הב\"י ועיין בח\"ר שכתב הבעל נאמן לומר דביטל כבר במיגו דאי בעי יכול עדיין לבטל ובחדושי רש\"ך הביא דבריו לפ\"ז מ\"ש הב\"י ובהג\"ה דאין הבעל נאמן וכו' לכאורה תמוה למה אינו נאמן דהא איירי בש\"ה אם כן יש לו מיגו כהנ\"ל וא\"ל דאיירי דכבר הגט ביד האשה אם כן קשה למה השליח נאמן דהא ע\"כ משקר דאם לא כן למה מסר ליד האשה וא\"ל דאיירי דשלח שליח אחר שליח הראשון שיבטל את שליחתו ושליח הראשון לא השגיח בו ומסר הגט ליד האשה ובזה אין הבעל נאמן אא\"כ שליח השני מעיד ע\"ז דהא כתבו במרדכי והג\"מ ר\"פ דשליח אינו נאמן ע\"ז אא\"כ עדים מעידים ע\"ז, ויש לומר דאיירי כאן דהגט הוא ביד השליח ואמר הבעל שביטל אף על גב דיש לו מיגו אינו נאמן כשהשליח אינו מודה כמ\"ש לעיל דהשליח נאמן אפילו אם יש לו מיגו וא\"ל למה אין הבעל מבטל עוד וי\"ל דאיירי דאינו בכאן אלא אמר כאן דביטל והלך ועכשיו בא השליח, ומ\"ש בח\"ר דהבעל נאמן במיגו יש לומר דאיירי באומר דביטל לפני עדים דהשליח א\"י להכחישו:","\u0003או האשה מודים\u0004. בודאי אם הגט כבר בידה וקידש אותה איש אחר אינה נאמנת לומר דביטל זה השליחות לאסור את עצמה על השני גם כשהמגרש כהן אינה נאמנת להתיר את עצמה לו, ואיירי דהגט בא לידה דאם לא בא לידה קשה כקושיא הנ\"ל למה הוא אינו נאמן בלי דיבורה, וכשמבטל השליח ע\"י שליח אחר כתב הב\"י בשם ירושלמי דשליח עול' א' משנים ועיין בהרא\"ש פ' השולח, ורי\"ו כתב דאינו עולה אפילו לא' כי הוא במקום הבעל וכתב הב\"י דנראה משמעות הירושלמי אפילו כשמבטל בפני השליח צריך שנים ולא כרמב\"ם דפוסק אם הוא מבטל בפני השליח א\"צ שנים, ולפי' הב\"י יש ליישב גם כן דרי\"ו ל\"פ על הירושלמי אלא רי\"ו איירי כשמבטל שלא בפני השליח הראשון צריך שנים בלי שליח השני כי שליח השני הוא במקום הבעל אבל שליח הראשון אינו במקום הבעל כיון דמבטל שליחתו לכן מצטרפים שליח הראשון כשמבטל בפניו וא\"ל עמ\"ש הב\"י הא ס\"ל לירושלמי דאין מצטרפים השליח כמ\"ש בר\"ס כי לענין ביטול שאני כמ\"ש בירושלמי להדיא:","\u0003י\"א דאלו השנים וכו'\u0004. מ\"ש בשם י\"א כאלו יש פלוגתא בדבר נראה דלא קאי על דין זה דצריכים אלו להיות ביחד כמ\"ש בתוס' שם ר\"פ השולח וכן משמע ממתני' היה עושה ב\"ד ומבטל ש\"מ דצריכים להיות יחד אלא קאי אהא אם מבטל ע\"ז כתב י\"א אפי' זה שלא בפני זה:","\u0003ביחד\u0004. הטעם כיון דרוצה לבטל מה שנעשה כבר צריכים להיות ביחד אף על גב דקי\"ל אפי' דבר אישות דומה לדיני ממונות ומצטרפים יחד מ\"מ בכה\"ג צריכים להיות ביחד אבל לבטל הגט הוי כאלו מוסר מודעא על להבא לכן א\"צ להיות ביחד:","\u0003יכול לכתחלה וכו'\u0004. זה שלא בפני זה כלומר שאומר לשנים שהם אל יהיו שלוחים אבל א\"י לבטל בפני שנים שליחתו של שנים אחרים ועיין ב\"ח ודרישה מפרשים דברי הטור לבטל כולם אפי' אם רוצה לבטל כל שנים ושנים בפניהם אסור לכתחלה:","\u0003ויש מ\"ש וכו'\u0004. לפי' המגיד והב\"י היינו דעת הרמב\"ם דס\"ל לחלק בין שליחות לבין עדים לכתוב ולא מצינו חילוק זה ובש\"ס משמע קצת להיפך ויש ליישב דברי הרמב\"ם בע\"א ועיין ברש\"ך:","\u0003היה מחזר\u0004. ה\"ה אם עשה שליח לבטל והשליח לא ביטל עד שבא לידה:","\u0003לבא אלי אקיימנה\u0004. כתב בט\"ז דאיירי בשלח שליח סתם להוליך גט לאשתו ואחר שעשה אותו לשליח אמר לו אם תרצה וכו' אז הוי כגילוי מלתא אבל אם בעת שעשה אותו לשליח אמר לו בעת שתרצה וכו' או תכ\"ד אז השליחות נעשה ע\"מ כן ואז אם ראובן בעיר ולא יכול להתפייס עמה א\"י ליתן לה הגט:","\u0003אמר בטל הוא\u0004. דרך כלל שצריך לומר לישנא דהוא מבטל עכשיו הגט ולא יאמר משמעות דהגט מעצמו בטול או פסול דהא ראינו דהגט כשר מעצמו והנה למ\"ש לעיל בשם ח\"ר אם אמר הבעל דכבר ביטל גט זה נאמן במיגו דהא יכול עוד לבטל וליישב הסוגיא עיין בחדושי רש\"ך מיהו מה דמבעיי' שם אם אמר בטל ולא אמר בטל הוא צ\"ל ה\"פ דאם לא אמר הוא משמע דהגט מעצמו בטל והיינו לשון עבר כלומר לעבר בטל הוא מעצמו ולא שהוא ביטל דאם היה פירושו דהוא ביטל כבר היה נאמן במיגו כהנ\"ל ואף למ\"ש לעיל דהשליח נאמן שלא ביטל היינו כשאומר שביטל בפניו אף על גב דאיתא להבעל מיגו מכל מקום השליח נאמן אבל אם אומר דביטל בפני שנים שלא בפניו מזה א\"י השליח וא\"י להכחישו יש לומר לכ\"ע הבעל נאמן במיגו, וא\"ל אם אמר פסול למה לא אמרינן דכוונתו דפסול מחמת שנכתב במחובר או מזויף ונאמן במיגו כהנ\"ל ויש לומר אם היה כוונתו לזה היה לו לפרש דבריו, ח\"ר:","\u0003פועל עבר\u0004. כלומר להרמב\"ם הבעיא בש\"ס היא אפילו אם אמר בטל בפתח תחת הטי\"ת משמע לשון עבר וציר\"י תחת הטית משמע להבא:","\u0003יהא פסול\u0004. דהוי כמו יהא כחרס ועיין בטור מ\"ש ע\"ז וי\"ל אף לדידיה מכל מקום ספק גט הוא וכך כתב ב\"ח:","\u0003אם לא גילה דעתו וכו'\u0004. אבל אם גילה דעתו לבטל אז לא הוי ביטול דקי\"ל גילוי דעת בגט לאו כלום הוא וערעור גם כן לא הוי דהא ראינו דכוונתו היה לבטל ולא לערער:","\u0003אינו מגרש בו לעולם\u0004. ואם גירש ה\"ז ספק כמ\"ש בסמוך משום דאפלגי בזה הפוסקים אם יכול לבטל הגט אחר שנכתב, ואם ביטל קודם שנכתב עיין סימן קל\"ד:","\u0003מכין אותו\u0004. עיין סימן קל\"ד מ\"ש ועיין בדרישה:","\u0003גוסס\u0004. עיין ס\"ס קכ\"א דוקא גוסס המדבר יכול לגרש ואיירי הכא כשהוא מדבר אבל אם הוא עכשיו אינו מדבר אפי' אם הוא חי עדיין ובעת שמסר הגט ליד השליח היה מדבר יש לחוש שמא עכשיו מטורף דעתו דהא גוסס צריך בדיקה מיהו י\"ל כיון בעת שמסר הגט היה מדבר והיה מיושב בדעתו אף על גב אח\"כ נעשה אלם ואינו מדבר א\"צ בדיקה כיון שהיה גוסס והיה מיושב, וב\"ח כתב אם מסר הגט קודם שהיה גוסס יכול השליח למסור הגט בעת שנעשה גוסס ואצ\"ל אם יש לחוש שתטרוף דעתו אחר שנעשה גוסס כגון שאינו מדבר ואם נתן הגט אחר שנעשה גוסס ואינו מדבר אז הוא ספק שמא תטרוף דעתו:","\u0003לא יתננו לה\u0004. דאין לו להחזיקה בספק גרושה כ\"כ המגיד והנה אם היא זקוקה ליבם שפיר טעם זה אבל כשאינה זקוקה ליבם ורוצה ליתן לה גט ותנשא לישראל י\"ל דאין שום חשש איסור ועיין בתשובת רש\"ך ס\"ב סי' צ\"ט:","\u0003או יותר מק'\u0004. כ\"כ הטור בשם הרמ\"ה ורש\"י פי' בש\"ס מבן תשעים ולמעלה הוא בחזקת חי כיון דאפלג ומה דאתמר שם בן מאה לרבותא קאמר אפי' בן מאה הוא בחזקת חי:","\u0003שאבדה בים\u0004. אבל אם נטבע בים אז קי\"ל דהם בחזקת מתים אלא מדרבנן מחמירים דהיא אסורה להנשא אם כן אם נתן לה גט אינו ספק גט מדאורייתא ועיין בש\"ג:","\u0003ובדיני עכו\"ם\u0004. כ\"כ הרמב\"ם ספ\"ו משמע דס\"ל בדיני ישראל הוא בחזקת מת כלישנא בתרא שם מיהו לכמה פוסקים קי\"ל כחומרי תרי לישנא ובין בד\"י ובין בד\"א הוי ספק וכן נראה דהרי\"ף ס\"ל כן מ\"ה הביא המשנה והשמיט כל הסוגיא, והרא\"ש כתב הרי\"ף ס\"ל בד\"י הוי ספק ולא בד\"א ועיין סימן י\"ז מ\"ש:"]],["שָׁלִיחַ שֶׁהֵבִיא גֵּט \u0010c0\u0011 מִמָּקוֹם לְמָקוֹם בְּחוּצָה לָאָרֶץ, אוֹ מֵאֶרֶץ יִשְׂרָאֵל לְחוּצָה לָאָרֶץ, אוֹ מִחוּצָה לָאָרֶץ לְאֶרֶץ יִשְׂרָאֵל, אִם הָיָה הַשָּׁלִיחַ עוֹמֵד בִּשְׁעַת כְּתִיבַת הַגֵּט וַחֲתִימָתוֹ, \u0010c1\u0011 הֲרֵי זֶה אוֹמֵר בִּפְנֵי שְׁנַיִם: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, וְאַחַר כָּךְ יִתֵּן לָהּ בִּפְנֵיהֶם וְתִתְגָּרֵשׁ בּוֹ; וְאַף עַל פִּי שֶׁאֵין עֵדָיו יְדוּעִים אֶצְלֵנוּ. וַאֲפִלּוּ הָיוּ שְׁמוֹת עֵדָיו כִּשְׁמוֹת הַכּוּתִים, אֵין חוֹשְׁשִׁין לָהֶם. וְאִם בָּא הַבַּעַל וְעָמַד וְעִרְעֵר, אֵין מַשְׁגִּיחִין בּוֹ. לְפִיכָךְ, אַף הַנָּשִׁים שֶׁאֵינָן נֶאֱמָנוֹת לוֹמַר: מֵת בַּעְלָהּ, נֶאֱמָנוֹת לְהָבִיא גֵּט זֶה וְלוֹמַר: \u0010c2\u0011 בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. וְכֵן שָׁלִיחַ שֶׁהֵבִיא גֵּט בֵאֶרֶץ יִשְׂרָאֵל וְאָמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ, אִם יָבֹא הַבַּעַל וִיעַרְעֵר, אֵין מַשְׁגִּיחִין בּוֹ. וְאִם אֵין הַשָּׁלִיחַ עוֹמֵד בִּשְׁעַת כְּתִיבָה וַחֲתִימָה, לֹא יִנָּתֵן לָהּ אֶלָּא אִם כֵּן נִתְקַיֵּם בְּחוֹתְמָיו. וְיֵשׁ לַשָּׁלִיחַ לִהְיוֹת מִכְּלַל הַשְּׁלֹשָׁה שֶׁקִּיְּמוּ אוֹתוֹ; וְאִם לֹא נִתְקַיֵּם, וְנָתַן לָהּ, \u0010c3\u0011 הֲרֵי זֶה פָּסוּל, עַד שֶׁיִּתְקַיֵּם. וְאִם בָּא הַבַּעַל וְעִרְעֵר, וְלֹא \u0010c4\u0011 נִתְקַיֵּם, אֵינָהּ מְגֹרֶשֶׁת. אָבַד הַגֵּט, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. וּמִפְּנֵי מָה הִצְרִיכוּ לוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, בְּחוּצָה לָאָרֶץ, כְּדֵי שֶׁלֹּא תִּהְיֶה הָאִשָּׁה צְרִיכָה לְקַיְּמוֹ אִם יָבֹא הַבַּעַל וִיעַרְעֵר, מִפְּנֵי שֶׁאֵין עֵדִים מְצוּיִים לְקַיְּמוֹ מִמָּקוֹם לְמָקוֹם בְּחוּצָה לָאָרֶץ. וְנִרְאֶה לִי, דְּהָאִדָּנָא, אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל צָרִיךְ לוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. \u0005 הַגָּה: וּבַזְּמַן הַזֶּה, הַמֵּבִיא גֵּט, אֲפִלּוּ מִבַּיִת לְבַיִת בְּעִיר אַחַת, צָרִיךְ לוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם \u0006 \u0005(תּוֹסָפוֹת רֵישׁ גִּטִּין)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן קמ\"א סָעִיף נ\"ה, \u0010c5\u0011 דְּאֵין לִתְּנוֹ בִּזְמַן שֶׁהַבַּעַל בָּעִיר. יֵשׁ אוֹמְרִים דְּאִם יֵשׁ לַשָּׁלִיחַ הַרְשָׁאָה וְכָתַב בָּהּ מִי הֵם עֵדֵי הַגֵּט, דְּזֶה מִקְּרֵי נִתְקַיֵּם בְּחוֹתְמָיו, וְאִם כֵּן אֵין הַשָּׁלִיחַ צָרִיךְ לוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם \u0006 \u0005(רַשְׁבָּ\"א סִימָן תקס\"א וּמָרְדְּכַי רֵישׁ הִתְקַבֵּל)\u0006. \u0005 וְיֵשׁ חוֹלְקִים וְאוֹמְרִים דְּהַרְשָׁאָה לֹא מִקְּרֵי קִיּוּם \u0006 \u0005(רִיבָ\"שׁ סִימָן שי\"ח וּבִסְדָרִים)\u0006. \u0005 וְכֵן נוֹהֲגִין דְּשָׁלִיחַ אוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, אַף כְּשֶׁיֵּשׁ לוֹ הַרְשָׁאָה, וְאֵין לְשַׁנּוֹת: \u0006\nבַּעַל שֶׁהֵבִיא רְאָיָה בְּרוּרָה בִּשְׁנֵי עֵדִים שֶׁגֵּט זֶה שֶׁנֶּאֱמַר בּוֹ: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, מְזֻיָּף הוּא, הֲרֵי זֶה בָּטֵל: \u0010c6\u0011\nכְּשֵׁם שֶׁאֵין צָרִיךְ לְקַיֵּם הַגֵּט כְּשֶׁאוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, כָּךְ אֵין צָרִיךְ לְקַיֵּם עֵדֵי הַשְּׁלִיחוּת, אֶלָּא נֶאֱמָן לוֹמַר שֶׁהַבַּעַל עֲשָׂאוֹ שָׁלִיחַ \u0005 בְּעֵדִים, \u0006 אַף עַל פִּי שֶׁאֵין מַכִּירִין חֲתִימַת עֵדֵי הַשְּׁלִיחוּת, אוֹ אֲפִלּוּ אֵין לוֹ שׁוּם עֵדוּת בַּשְּׁלִיחוּת אֶלָּא שֶׁאָמַר שֶׁהַבַּעַל עֲשָׂאוֹ שָׁלִיחַ כָּרָאוּי, נֶאֱמָן. \u0005 וְעַיֵּן לְעֵיל סִימָן קמ\"א סָעִיף י\"א וְסָעִיף כ\"ד כֵּיצַד נוֹהֲגִין לְכַתְּחִלָּה: \u0010c7\u0011 \u0006\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁנּוֹתְנוֹ לָהּ בִּפְנֵי שְׁנַיִם כְּשֶׁאֵין הַשָּׁלִיחַ קָרוֹב אוֹ פָּסוּל, אֲבָל אִם הוּא קָרוֹב אוֹ פָּסוּל, צָרִיךְ לִתְּנוֹ לָהּ בִּפְנֵי ג' זוּלָתוֹ. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּיֵשׁ לְהַחֲמִיר, אֲפִלּוּ אֵין הַשָּׁלִיחַ קָרוֹב אוֹ פָּסוּל, לִתְּנוֹ לָהּ לִפְנֵי שְׁלשָׁה, כְּדֵי שֶׁלֹּא יָבֹא לִתְּנוֹ לָהּ בִּפְנֵי שְׁנַיִם אַף כְּשֶׁהוּא קָרוֹב אוֹ פָּסוּל \u0006 \u0005(טוּר בְּשֵׁם הָרִי\"ף)\u0006, \u0005 וְכֵן נוֹהֲגִין. וְיֵשׁ מַחֲמִירִין עוֹד, לִטֹּל שְׁנַיִם אֲחֵרִים לְעֵדֵי מְסִירָה, וְלֹא יִהְיוּ קְרוֹבִים לַדַּיָּנִים וְלֹא לָאִישׁ וְלֹא לָאִשָּׁה, גַּם הַשְּׁלשָׁה שֶׁיּוֹשְׁבִים לֹא יִהְיוּ קְרוֹבִים לְעֵדֵי הַגֵּט, וְלֹא לַשָּׁלִיחַ, \u0006 \u0005(בְּסֵדֶר גִּטִּין)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן קמ\"א סָעִיף ל\"ג. יֵשׁ מַחֲמִירִים וְאוֹמְרִים דְּהָרַב הַנּוֹטֵל שָׂכָר מִסֵּדֶר נְתִינַת הַגֵּט לֹא יִהְיֶה אֶחָד מִשְּׁלשָׁה הַיּוֹשְׁבִים לְדַיָּנִים, אֶלָּא יוֹשִׁיב ג' אֲחֵרִים וְהָרַב שׁוֹאֵל כָּל הַשְּׁאֵלוֹת וּמְסַדֵּר הַנְּתִינָה \u0006 \u0005(בְּסֵדֶר גִּטִּין, כֵּן עָשָׂה מהרא\"י)\u0006:\nאוֹתָם שֶׁנָּתְנוֹ לָהּ בִּפְנֵיהֶם אֵין צְרִיכִין לֵישֵׁב. וּכְשֶׁאוֹמֵר הַשָּׁלִיחַ: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, צָרִיךְ לַעֲמֹד. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁלְּכַתְּחִלָּה צְרִיכִים לֵישֵׁב, אוֹתָם שֶׁאוֹמֵר בִּפְנֵיהֶם: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. \u0005 וּלְכַתְּחִלָּה יִתְּנוֹ לָהּ בַּיּוֹם וְלֹא בַּלַּיְלָה \u0006 \u0005(בִּנְיָמִין זְאֵב סִימָן קכ\"ב)\u0006:\nאוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, בְּשָׁעָה שֶׁנּוֹתְנוֹ לְיַד הָאִשָּׁה \u0010c8\u0011 אוֹ סָמוּךְ לוֹ מִיָּד תּוֹךְ כְּדֵי דִּבּוּר. לְפִיכָךְ, נְתָנוֹ לָהּ וְלֹא הִסְפִּיק לוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם עַד שֶׁנִּשְׁתַּתֵּק, פָּסוּל, עַד שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו:\nאִם אֵחַר מִלְּאוֹמְרוֹ יוֹתֵר מִתּוֹךְ כְּדֵי דִּבּוּר, אוֹ שֶׁלֹּא אֲמָרוֹ \u0005 בִּפְנֵי הָאִשָּׁה \u0006 \u0005(טוּר)\u0006, אוֹ שֶׁנְּתָנוֹ לָהּ בֵּינוֹ לְבֵינָהּ; אַף עַל פִּי שֶׁנִּשֵּׂאת, \u0010c9\u0011 נוֹטְלוֹ מִמֶּנָּה וְחוֹזֵר וְנוֹתְנוֹ לָהּ בִּפְנֵי שְׁנַיִם, וְאוֹמֵר בִּפְנֵיהֶם: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. וְאִם לֹא נְטָלוֹ מִמֶּנָּה, הֲרֵי זֶה פָּסוּל, עַד שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו. \u0005 הַגָּה: וְלָכֵן, אִלֵּם לֹא יוּכַל לְהָבִיא גֵּט, \u0010c10\u0011 אַף עַל פִּי שֶׁיּוּכַל לִכְתֹּב: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, דְּצָרִיךְ לוֹמַר בְּפִיו \u0006 \u0005(רִיבָ\"שׁ סִימָן ר\"מ)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לְאָמְרוֹ בִּלְשׁוֹן הַקֹּדֶשׁ, וְהַיְנוּ: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם \u0006 \u0005(כֵּן מַשְׁמַע מֵהָרֹא\"שׁ פ\"ק מִסֵדֶר גִּטִּין)\u0006. \u0005 וְאִם עַם הָאָרֶץ הוּא, מַקְרִין אוֹתוֹ מִלָּה בְּמִלָּה וּמוֹדִיעִים לוֹ בְּלַעַ\"ז הַפֵּרוּשׁ \u0006 \u0005(גַּם זֶה בִּסְדָרִים)\u0006. \u0005 מִיהוּ, בְּדִיעֲבַד אִם אֲמָרוֹ בִּלְשׁוֹן לַעַ\"ז, נִרְאֶה לִי דְּכָשֵׁר: \u0006\nוְאִם לֹא אָמַר הַשָּׁלִיחַ: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, וּמֵת הַבַּעַל, אֵין תַּקָּנָה לִטְּלוֹ מִמֶּנָּה וְלַחֲזֹר וְלִתְּנוֹ לָהּ וְלוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, וְאֵין לוֹ תַּקָּנָה אֶלָּא לְהִתְקַיֵּם בְּחוֹתְמָיו:\nשָׁלִיחַ שֶׁעוֹשֶׂה שָׁלִיחַ, יַעֲשֶׂנּוּ בִּפְנֵי \u0010c11\u0011 בֵּית דִּין, דְּהַיְנוּ שְׁנַיִם וְהוּא מִצְטָרֵף עִמָּהֶם אִם הוּא כָּשֵׁר לְדִין, וְאוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם בְּשָׁעָה שֶׁנּוֹתְנוֹ לַשָּׁלִיחַ, וְכֵן אַחֵר לְאַחֵר, עַד מֵאָה. וְכָל אֶחָד אוֹמֵר בִּפְנֵי בֵּית דִּין \u0005 בִּשְׁעַת נְתִינָה אוֹ תּוֹךְ כְּדֵי דִּבּוּר \u0006 \u0005(בְּסֵדֶר גִּטִּין)\u0006: שְׁלִיחַ בֵּית דִּין אֲנִי. וְכֵן יֹאמַר הָאַחֲרוֹן כְּשֶׁנּוֹתְנוֹ לְיָדָהּ. \u0005 הַגָּה: וְלָאו דַּוְקָא הַאי לִשָּׁנָא, אֶלָּא הוּא הַדִּין אִם אוֹמֵר: אֲנִי הַשָּׁלִיחַ נַעֲשֵׂיתִי לִפְנֵי בֵּית דִּין, סָגֵי \u0006 \u0005(מ\"כ תִּקוּן יָשָׁן)\u0006. \u0005 וַאֲפִלּוּ לֹא אָמַר כְּלוּם, אִם \u0010c12\u0011 יֵשׁ לוֹ הַרְשָׁאָה, וְהוּא בִּמְקוֹם \u0006 \u0005 עִגּוּן, יֵשׁ לְהָקֵל \u0006 \u0005(רִיבָ\"שׁ סִימָן שי\"ח)\u0006. \u0005 וְכֵן יֹאמַר כָּל אֶחָד לַחֲבֵרוֹ: הִנְנִי פְּלוֹנִי בַּר פְּלוֹנִי מְמַנֶּה אוֹתְךְ פְּלוֹנִי בַּר פְּלוֹנִי לִהְיוֹת שָׁלִיחַ בִּמְקוֹמִי וּבַחֲרִיקַאי וְיִהְיֶה יָדְךְ כְּיָדִי כוּ' לְגָרֵשׁ פְּלוֹנִית בַּת פְּלוֹנִי אִשְׁתּוֹ שֶׁל פְּלוֹנִי בַּר פְּלוֹנִי בְּכָל מָקוֹם שֶׁתִּמְצְאֶנָּה וְהִנְנִי נוֹתֵן לְךְ רְשׁוּת לַעֲשׂוֹת שָׁלִיחַ וּשְׁלִיחַ שָׁלִיחַ וְכוּ' וּמִיָּד שֶׁיַּגִּיעַ הַגֵּט לְיַד פְּלוֹנִית בַּת פְּלוֹנִי אֵשֶׁת פְּלוֹנִי בַּר פְּלוֹנִי תְּהֵא מְגֹרֶשֶׁת כוּ' \u0006 \u0005(הַכֹּל בְּסֵדֶר גִּטִּין)\u0006, \u0005 כְּדֶרֶךְ שֶׁנִּתְבָּאֵר לְקַמַּן בְּסֵדֶר הַגֵּט סָעִיף ל'. וְאֵין שְׁלִיחַ בֵּית דִּין צָרִיךְ הַרְשָׁאָה כְּמוֹ שָׁלִיחַ הָרִאשׁוֹן, אֲבָל נוֹהֲגִין בְּהַרְשָׁאָה כְּמוֹ בַּשָּׁלִיחַ הָרִאשׁוֹן \u0006 \u0005(רִיבָ\"שׁ סִימָן נ\"ג)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן קמ\"א סָעִיף כ\"ד. וַאֲפִלּוּ לֹא הָיוּ חֲתוּמִים עַל הַהַרְשָׁאָה רַק שְׁנַיִם, וְכָּתְבוּ בִּלְשׁוֹן עֵדוּת וְלֹא בִּלְשׁוֹן דַּיָּנוּת, נֶאֱמָן הַשָּׁלִיחַ הַשֵּׁנִי לוֹמַר שֶׁהָיוּ ג' אוֹ שֶׁהוּא הָיָה עִמָּהֶם, וְלֹא שַׁיָּךְ בָּזֶה אֵין עֵד נַעֲשָׂה דַּיָּן \u0006 \u0005(רִיבָ\"שׁ סִימָן שי\"ח)\u0006. \u0005 וְלֹא חַיְשִׁינַן לְבֵית דִּין טוֹעִין, אֶלָּא אִם כֵּן אָנוּ מַכִּירִין בְּאוֹתָן שֶׁסִּדְּרוּ הַגֵּט שֶׁאֵין בְּקִיאִין, שֶׁאָז אֲפִלּוּ כָּתוּב כַּהֹגֶן חוֹשְׁשִים לָהֶם \u0006 \u0005(גַּם זֶה שָׁם)\u0006:\nכְּשֶׁבָּא לַעֲשׂוֹת שָׁלִיחַ אַחֵר, אֵין צָרִיךְ שֶׁיִּהְיֶה בְּפָנָיו, אֶלָּא אוֹמֵר בְּבֵית דִּין: הֲרֵי פְּלוֹנִי שְׁלוּחִי, אֲפִלּוּ שֶׁלֹּא בְּפָנָיו. וְכֵן יָכוֹל לִמְסֹר שְׁלִיחוּת לְבֵית דִּין שֶׁהֵם יַעֲשׂוּ שְׁלוּחִים אֲחֵרִים, וִיכוֹלִים לַעֲשׂוֹת שָׁלִיחַ שֶׁלֹּא בִּפְנֵי שָׁלִיחַ רִאשׁוֹן. \u0005 הַגָּה: \u0010c13\u0011 וְיֵשׁ אוֹמְרִים דְּלֹא מְהַנֵּי שֶׁיֹּאמַר: שְׁלִיחַ בֵּית דִּין אֲנִי, מֵאַחַר שֶׁלֹּא שָׁמַע שֶׁהַשָּׁלִיחַ אוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, אֶלָּא צָרִיךְ שֶׁיִּהְיֶה לוֹ \u0010c14\u0011 הַרְשָׁאָה אוֹ שֶׁיִּתְקַיֵּם הַגֵּט בְּחוֹתְמָיו \u0006 \u0005(רִיבָ\"שׁ סִי' נ\"ג)\u0006:\nהַסוּמָא בִּשְׁנֵי \u0005 עֵינָיו, \u0006 אֵינוֹ יָכוֹל לְהָבִיא גֵּט שֶׁל חוּצָה לָאָרֶץ, מִפְּנֵי \u0010c15\u0011 שֶׁאֵינוֹ יָכוֹל לוֹמַר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. לְפִיכָךְ, אִם נִכְתַּב וְנֶחְתַּם בְּפָנָיו כְּשֶׁהוּא פָּתוּחַ, וְנִסְתָּמֵא, \u0010c16\u0011 הֲרֵי זֶה אוֹמֵר: [בִּפְנֵי שְׁלשָׁה] בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, וְנוֹתְנוֹ לָהּ. וְהוּא שֶׁמַּכִּיר הָאִשָּׁה בִּטְבִיעוּת קוֹל. וְאִם אֵינוֹ מַכִּירָהּ \u0010c17\u0011 בִּטְבִיעוּת קוֹל, לֹא מְהַנֵּי מַה שֶּׁאֲחֵרִים אוֹמְרִים לוֹ שֶׁהִיא זֹאת, אַף עַל גַּב דִּמְהַנֵּי בְּפִקֵּחַ. \u0005 וּבָעֵינָן גַּבֵּי פִּקֵּחַ \u0010c18\u0011 שְׁנֵי עֵדִים כְּשֵׁרִים שֶׁאֵינָן \u0006 \u0005 קְרוֹבִים וְלֹא פְּסוּלִים \u0006 \u0005(ת\"ה סִימָן רל\"ח)\u0006:\nאִם יֵשׁ עֵדִים שֶׁהַבַּעַל מָסַר לְסוּמָא זֶה גֵּט זֶה לְגֵרוּשִׁין, כָּשֵׁר, שֶׁהֲרֵי \u0010c19\u0011 כֵּיוָן שֶׁיֵּשׁ עֵדִים אֵינוֹ צָרִיךְ לוֹמַר: בְּפָנַי נִכְתַּב \u0010c20\u0011 וּבְפָנַי נֶחְתַּם, וְיָהִיב לַהּ בְּאַפֵּי הַנְהוּ סַהֲדֵי גּוּפַיְהוּ. וְאִם נִתְקַיֵּם בְּחוֹתְמָיו, \u0010c21\u0011 כָּשֵׁר בְּכָל גַּוְנָא:\nהָאִישׁ שֶׁנָּתַן גֵּט לְאִשְׁתּוֹ, וְנִכְתַּב וְנֶחְתַּם בְּפָנֶיהָ, וְאָמַר לָהּ: \u0010c22\u0011 הֲרֵי אַתְּ שָׁלִיחַ לְהוֹלָכָה \u0010c23\u0011 עַד בֵּית דִּין פְּלוֹנִי וְהֵם יַעֲמִידוּ שָׁלִיחַ וְיִתְּנוּ לִיךְ גֵּט זֶה וְתִתְגָּרְשִׁי בּוֹ, הֲרֵי זוֹ נֶאֱמֶנֶת לוֹמַר בִּפְנֵיהֶם: בְּפָנַי נִכְתַּב \u0010c24\u0011 וּבְפָנַי נֶחְתַּם. \u0005 וּצְרִיכָה לְאָמְרוֹ בְּשָׁעָה שֶׁהַגֵּט יוֹצֵא מִתַּחַת יָדָהּ \u0006 \u0005(טוּר וְהָרֹא\"שׁ)\u0006. וְהֵם נוֹטְלִים אוֹתוֹ וְנוֹתְנִים לְשָׁלִיחַ לִתְּנוֹ לָהּ כְּמַאֲמַר הַבַּעַל. וְאִם לֹא הִתְנָה עָלֶיהָ הַבַּעַל תְּנַאי זֶה, וַהֲרֵי הַגֵּט יוֹצֵא מִתַּחַת יָדָהּ, אֵינָהּ צְרִיכָה לוֹמַר כְּלוּם, וַהֲרֵי הִיא בְּחֶזְקַת מְגֹרֶשֶׁת, וְאַף עַל פִּי שֶׁלֹּא נִתְקַיְּמָה חֲתִימַת יְדֵי הָעֵדִים; שֶׁעֵדִים הַחֲתוּמִים עַל הַגֵּט, כְּמִי שֶׁנֶּחְקְרָה עֵדוּתָן בְּבֵית דִּין דָּמֵי, כָּל זְמַן שֶׁאֵין מְעַרְעֵר. וַאֲפִלּוּ אָמַר לָהּ: אַל תִּתְגָּרְשִׁי בּוֹ אֶלָּא בְּבֵית דִּין פְּלוֹנִי, תְּנָאָה בְּעָלְמָא הוּא; וּכְשֶׁתָּבֹא לְאוֹתוֹ בֵּית דִּין וְהַגֵּט בִּרְשׁוּתָהּ, מִתְגָּרֶשֶׁת בְּקַבָּלָתָה רִאשׁוֹנָה, וְאֵינָהּ צְרִיכָה לוֹמַר \u0010c25\u0011 בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם:\nוְיֵשׁ חוֹלְקִים וְאוֹמְרִים שֶׁאֵין לְהַתִּירָהּ לִנָּשֵׂא עַל יְדֵי גֵּט שֶׁיּוֹצֵא מִתַּחַת יָדָהּ, אִם לֹא נִתְקַיֵּם בְּחוֹתְמָיו, אַף עַל פִּי שֶׁאֵין עָלָיו עוֹרְרִים, שֶׁמֵּעוֹלָם לֹא שָׁמְעוּ מִי שֶׁנָּהַג קֻלָּא כָּזוֹ. \u0005 הַגָּה: \u0010c26\u0011 בַּעַל שֶׁמֵּבִיא גֵּט לְאִשְׁתּוֹ, וְהוּא בְּעַצְמוֹ הוֹלִיכוֹ מִמָּקוֹם שֶׁכָּתְבוּ אוֹתוֹ עַד מְקוֹם הַנְּתִינָה, צָרִיךְ לְמָסְרוֹ לָהּ כְּשָׁלִיחַ, וְצָרִיךְ לוֹמַר: בְּפָנַי נִכְתַּב \u0006 \u0005 וּבְפָנַי נֶחְתַּם, כְּמוֹ הַשָּׁלִיחַ, כְּדֵי שֶׁלֹּא לָבֹא לִטְעוֹת גַּם בְּשָׁלִיחַ אַחֵר, מֵאַחַר שֶׁעַכְשָׁיו אֵינָן בְּנֵי תּוֹרָה \u0006 \u0005(ב\"י בְּשֵׁם א\"ח)\u0006:\nנִכְתַּב מִקְצָת הַגֵּט בְּפָנָיו, וְנֶחְתַּם כֻּלּוֹ בְּפָנָיו, \u0010c27\u0011 אִם מִקְצָתוֹ הָרִאשׁוֹן הוּא, הֲרֵי זֶה אוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם, אֲפִלּוּ לֹא נִכְתַּב בּוֹ אֶלָּא שִׁיטָה אַחַת בְּפָנָיו, וַאֲפִלּוּ שָׁמַע \u0010c28\u0011 קוֹל קוּלְמוּס כּוֹתֵב, \u0010c29\u0011 וְחָתְמוּ הָעֵדִים בְּפָנָיו, הֲרֵי זֶה אוֹמֵר: בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. וְכֵן אִם יָצָא הַסוֹפֵר לַשּׁוּק, וְחָזַר וְהִשְׁלִים הַגֵּט, אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא אַחֵר מְצָאוֹ וְאָמַר לוֹ וּלְשֵׁם אִשָּׁה אַחֶרֶת כְּתָבוֹ. וְאִם בָּא לְהַחֲמִיר וְלַעֲמֹד עַל כְּתִיבַת כֻּלּוֹ אֵין שׁוֹמְעִין לוֹ, שֶׁלֹּא לְהוֹצִיא לַעַז עַל גִּטִּין הָרִאשׁוֹנִים. וְכָל זֶה בִּכְתִיבָתוֹ, אֲבָל בַּחֲתִימָתוֹ צָרִיךְ לַעֲמֹד עֲלֵיהֶם מִתְּחִלָּה וְעַד סוֹף:\nאָמַר: בְּפָנַי נִכְתַּב, וְלֹא אָמַר: וּבְפָנַי נֶחְתַּם, אוֹ אָמַר: בְּפָנַי נֶחְתַּם, וְלֹא אָמַר: וּבְפָנַי נִכְתַּב, אוֹ שֶׁאָמַר: בְּפָנַי נִכְתַּב חֶצְיוֹ הָאַחֲרוֹן וְנֶחְתַּם כֻּלּוֹ, אוֹ שֶׁאָמַר: בְּפָנַי נִכְתַּב כֻּלּוֹ \u0010c30\u0011 וְנֶחְתַּם עֵד אֶחָד אֲבָל לֹא הָעֵד הַשֵּׁנִי, אֵינוֹ כְּלוּם. \u0010c31\u0011 אֲפִלּוּ אִם הוּא אֶחָד מֵעֵדֵי הַגֵּט, וְאָמַר: הָעֵד הָאֶחָד חָתַם בְּפָנַי, וְזֹאת הִיא חֲתִימָתִי, יִתְקַיֵּם בְּחוֹתְמָיו. וְאִם הֵעִיד \u0010c32\u0011 הוּא וְאַחֵר עִמּוֹ עַל חֲתִימַת הָעֵד הַשֵּׁנִי שֶׁלֹּא חָתַם בְּפָנָיו, שַׁפִּיר דָּמֵי. וְאֵין צָרִיךְ לוֹמַר אִם הֵעִידוּ שְׁנַיִם אֲחֵרִים עַל חֲתִימַת אוֹתוֹ הָעֵד שֶׁלֹּא חָתַם בְּפָנָיו:\nהָיוּ שְׁלשָׁה עֵדִים חֲתוּמִים בּוֹ, וְהַשְּׁנַיִם חָתְמוּ בְּפָנָיו, אַף עַל פִּי שֶׁהָאֶחָד חָתַם שֶׁלֹּא בְּפָנָיו \u0010c33\u0011 אֵין בְּכָךְ כְּלוּם: \u0010c34\u0011\nעָשָׂה הַבַּעַל שְׁנַיִם שְׁלוּחִים לְהוֹלִיךְ גֵּט לְאִשְׁתּוֹ, אַף עַל פִּי שֶׁלֹּא נִכְתַּב וְנֶחְתַּם בִּפְנֵיהֶם, נוֹתְנִים אוֹתוֹ לָהּ וְתִהְיֶה מְגֹרֶשֶׁת; וְהוּא שֶׁהָיוּ כְּשֵׁרִים לְהָעִיד, שֶׁהֲרֵי אֵין הַבַּעַל יָכוֹל לְעַרְעֵר בְּגֵט זֶה אַף עַל פִּי שֶׁאֵינוֹ \u0010c35\u0011 מְקֻיָּם שֶׁהֲרֵי שְׁלוּחָיו הֵם עֵדָיו. \u0005 וְיֵשׁ אוֹמְרִים דְּאִם בָּא הַבַּעַל \u0010c36\u0011 \u0006 \u0005 וְעִרְעֵר, צָרִיךְ לְהִתְקַיֵּם בְּחוֹתְמָיו \u0006 \u0005(טוּר, וְכֵן מַשְׁמַע מֵהָרַ\"ן לְדַעַת ב\"י)\u0006. \u0010c37\u0011 וְיֵשׁ אוֹמְרִים שֶׁאֲפִלּוּ לֹא עָשָׂה שָׁלִיחַ אֶלָּא אֶחָד, וְהַשֵּׁנִי מֵעִיד שֶׁבְּפָנָיו נָתַן הַבַּעַל לְזֶה הַגֵּט לְהוֹלִיךְ לְאִשְׁתּוֹ, אֵין צָרִיךְ לוֹמַר: בְּפָנַי נִכְתַּב \u0010c38\u0011 וּבְפָנַי נֶחְתַּם. וְיֵשׁ מִי שֶׁמַּצְרִיךְ בָּזֶה שֶׁיִּמְסְרֶנּוּ בִּפְנֵי עֵידֵי שְׁלִיחוּת עַצְמָם:\nשְׁנַיִם שֶׁמְּבִיאִים גֵּט, וְאֶחָד אוֹמֵר: בְּפָנַי נִכְתַּב, וְאֶחָד אוֹמֵר: \u0010c39\u0011 וּבְפָנַי נֶחְתַּם, אִם אֵין שָׁלִיחַ \u0010c40\u0011 אֶלָּא אֶחָד מֵהֶם, לֹא יִנָּתֵן לָהּ עַד שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו. וְכֵן אִם שְׁנַיִם אוֹמְרִים: בְּפָנֵנוּ נִכְתַּב, וְאֶחָד שְׁלִישִׁי אוֹמֵר: בְּפָנַי נֶחְתַּם, אִם אֵין שָׁלִיחַ אֶלָּא אֶחָד, לֹא יִנָּתֵן לָהּ עַד שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו. אָמַר אֶחָד: בְּפָנַי נִכְתַּב, וּשְׁנַיִם אוֹמְרִים: בְּפָנֵנוּ נֶחְתַּם, אַף עַל פִּי שֶׁאֵינוֹ יוֹצֵא מִתַּחַת יָדָם, כָּשֵׁר, שֶׁהֲרֵי נִתְקַיֵּם בְּחוֹתְמָיו. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּאִם הֵבִיא הַשָּׁלִיחַ הַגֵּט מְקֻיָּם בְּחוֹתְמָיו, אַף עַל פִּי שֶׁאֵין מַכִּירִין חֲתִימוֹת דַּיָּנֵי הַקִּיּוּם, מִכָּל מָקוֹם בִּמְקוֹם דְּחָק וְעִגּוּן יֵשׁ לְהָקֵל וְלִסְמֹךְ עָלָיו, אַף עַל פִּי שֶׁלֹּא אָמַר הַשָּׁלִיחַ: בִּפְנֵי נִכְתַּב וּבְפָנַי נֶחְתַּם, הוֹאִיל וְאִי אֶפְשָׁר לְהַחֲזִיר וְלוֹמַר, יֵשׁ לִסְמֹךְ עַל הַחֲתִימוֹת, \u0010c41\u0011 דְּמִן הַתּוֹרָה עֵדִים הַחֲתוּמִים עַל הַשְּׁטָר כְּמוֹ שֶׁנֶּחְקְרָה עֵדוּתָן בְּבֵית דִּין דָּמֵי \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם רַשְׁבַּ\"ץ)\u0006:",[],["\u0003ממקום למקום\u0004. הנה בש\"ס מבואר אליבא דרבא דקי\"ל כוותי' הא דצ\"ל בפני נכתב ובפני נחתם משום עדים אינן מצוים לקיים וכשאומר בפני נכתב ובפני נחתם נתקיים הגט ובמדינה א' מצוים לקיים ואצ\"ל בפני נכתב ובפני נחתם ורמב\"ם פוסק ממקום למקום צ\"ל בפני נכתב ובפני נחתם אפילו במדינה א' ובמקום א' אצ\"ל ב\"נ ס\"ל לפי המסקנא דתירץ שאני בני מחוזא דניידי יליף ממקום למקום דומה לבני מחוזא אבל בחד מקום אצ\"ל ב\"נ וכ\"כ המגיד פ\"ז ותוס' למדו מזה אפילו בחד מקום דינו כבני מחוזא:","\u0003הרי זה אומר בפני נכתב ובפני נחתם\u0004. הטעם כמ\"ש בסמוך ואז נתקיים הגט על פיו אף על גב בעלמא קי\"ל קיום צריך ב' עדים כאן משום תקנות עגונות הקילו חז\"ל הואיל וקיום שטרות דרבנן הוא דקי\"ל עדים החתומים כמה שנחקרו עדותן בב\"ד דמי כמ\"ש בש\"ס אז מ\"ש בפני נכתב ובפני נחתם אפי' אם אתא הבעל ומערער לא משגיחין בו ולהני פוסקים דס\"ל כשטוען מזויף צריך קיום מדאורייתא ובסי' הקודם כתבתי דכן ס\"ל להמחבר לפ\"ז לכאורה קשה כשאתא הבעל ומערער שהגט מזויף למה מהני קיום של ע\"א כיון שצריך קיום מדאורייתא ואפשר אם אתא הבעל מיד ומערער לא מהני העדות של ע\"א אלא כשאינו מערער מיד בעת שאומר בפני נכתב ובפני נחתם ואז הוי כאלו נתקיים ע\"פ ב' עדות תו אפילו אם מערער לא משגיחין ביה כיון דכבר נתקיים, ולהרמב\"ם דס\"ל כל עדות בשטר מדאוריית' אין עדות קשה ליישב סוגי' זו ועיין תשו' מהרשד\"ם סי' א' ב' וכשנתקיים הגט ע\"פ השליח גובה הכתוב' מן הלקוחות דנלמד מספר כתובה כשתנשא לאחר תטלי וכו' ול\"ד למ\"ש בסימן קמ\"א סעיף נ\"ג דאינה גובה מלקוחות דשם אין היתר גמור דהא יש לחוש שמא יבוא עוד ויערער לכן אינה גובה מלקוחות אבל כאן מותרת לגמרי ואין מועיל ערעור הבעל לכן גובה מן הלקוחות מיהו תוספ' כתובה כתב הר\"ן והמגיד פ\"ז בשם הרמב\"ן דאינה גובה דאין מדרש כתובה אלא לעיקר כתובה ולא לתוספ' וכיון ממדרש כתובה אין לה לית לה מדינא דקי\"ל אין קיום שטרות אלא בתרי עדים לענין ממון, ולכאורה נראה גם מן הבעל אינה גובה ת\"כ דהא לענין ממון לא מהני קיום ע\"א ומדרש כתובה לא אמרינן לת\"כ מכ\"ש כשמביא גט בא\"י דאינה גובה ת\"כ מבעלה מחמת ספר כתובה גובה מב\"ח ות\"כ לא מהני מדרש כתובה מיהו יש לומר לענין זה מהני הרשאה דהוי כאלו נתקיים הגט בשני עדים ותגבה ת\"כ:","\u0003וכן שליח שהביא גט מא\"י וכו'\u0004. אבל נשים השונאים זא\"ז יש פוסלין להביא גט בא\"י אפילו אם אומרות בפני נכתב ובפני נחתם כמ\"ש בסימן קמ\"א משום בנשי חיישינן טפי דלאו דיני גמירי והן סברי דבעל יכול לערער אפי' כשאומרת בפני נכתב וב\"נ כיון בעלמא בא\"י יכול לערער אפשר דטעה בזה ומעידים מחמת שנאה וסברוהו דבעל יכול לערער אבל בח\"ל דא\"י לערער לא אמרינן דסברא דבעל יכול לערער:","\u0003הרי זה פסול\u0004. כ\"כ הרמב\"ם ולפי הכלל שכתב בפ\"י אם נשאת לא תצא אף על גב לרמב\"ם כל עדות בשטר אינו אלא מדרבנן מ\"מ כל שאין ערעור עליו אינו פסול אלא מדרבנן ועיין בכ\"מ, אבל אם הבעל מערער וא\"י לקיים ס\"ל דלא נעשה כתיקון חז\"ל שתקנו אם מערער הבעל צריך קיום מ\"ה הגט בטל ועיין במגיד פ\"ז אבל לדעת תוס' והרא\"ש והטור אם לא אמר בפני נכתב ובפני נחתם תצא וכ\"פ בש\"ג והיינו כשא\"י ליטול ממנה וליתן ולומר ב\"נ כמ\"ש בסעיף ז':","\u0003אינה מגורשת\u0004. כך כתב הרמב\"ם לפ\"ז הגט בטל ואם נשאת תצא והולד ממזר ודאי והרא\"ש כתב בשם הרמב\"ם ספק ממזר הוא וכ\"כ בטור ולכאורה תמוה הא רפ\"ז מבואר דממזר ודאי הוא וב\"ח כתב מ\"ש הרא\"ש ספק ממזר היינו היכא דהבעל מערער אחר שנאבד הגט אבל אם מערער כשהגט עדיין בעין וא\"י לקיים הוי ממזר ודאי ואנ\"ל דאיך כתב הרא\"ש בשם הרמב\"ם מה שהוא אינו כותב ובודאי ט\"ס בהרא\"ש ומ\"ש הטור ספק ממזר הוא משום דס\"ל כהני פוסקים שהביא המגיד שם דס\"ל ספק ממזר הוא כי שמא יתקיים עוד ומ\"ש באבד הגט ספק מגורשת לאו לענין ממזר כ\"כ דהא כתב בערעור הבעל ספק ממזר ש\"מ באבד הגט לאו ספק ממזר אלא ספק מגורשת לענין קידושין של אחר וכ\"כ בדרישה וכאן נמי מוכח דס\"ל להרא\"ש והטור אם טוען מזויף צריך קיום מדאורייתא דאל\"כ אינו ממזר ולא ספק ממזר דהא העדים החתומי' הם כאלו נחקרה עדותן בב\"ד ואינו אלא פסול דרבנן אלא ודאי ס\"ל דצריך קיום מדאורייתא וכבר הוכחתי כן בסי' הקוד' מן הפוסקים שהביא המגיד ועיין תשו' מהרי\"ק שורש ע\"ז ובש\"ך בח\"ה סי' מ\"ו וא\"י איך לא הזכירו מכל הני פוסקים וש\"ך דלא הזכיר מה שמבואר בסי' זה ובסי' הקודם, ועיין תשו' מהרשד\"מ סי' א' ב':","\u0003דאין ליתנו בזמן שהבעל בעיר\u0004. אף על גב דאיירי כאן באומר ב\"נ וב\"נ ש\"מ דס\"ל לעולם יכול להכחישו ולומר דהוא אינו שלוחו ועיין מ\"ש בסי' הקודם ע\"ז:","\u0003כשם שא\"צ לקיים הגט וכו'\u0004. כ\"כ הרא\"ש ריש גיטין ושאר פוסקים לכאורה נראה לדייק כמה דיוקי' מזה א' דוקא ש\"ה נאמן משום דהוא נאמן לומר ב\"נ נתנו חז\"ל ליה נאמנות ג\"כ לומר דהוא שלוחו אבל ש\"ק אינו נאמן גם משמע דוקא בח\"ל דאומר ב\"נ וב\"נ נאמן ולא בא\"י ולא כהרמ\"ה ובסעיף י' בהג\"ה לא משמע כן גם משמע אפילו בעיר א' נאמן ואפילו אם הבעל מכחישו ובסמוך גם בסי' קמ\"א לא משמע כן וכתב בט\"ז אשה שנתגרשה צריכה כתב מב\"ד שנתגרשה ואין הרב נאמן להעיד ע\"ז יחידי ול\"ד לקיום שטרות דכאן מוציא אותה מחזקתה לכן צריכה היא מעשה ב\"ד ואז יכולה להראות בכל מקום אשר תבוא דהיא מגורשת:","\u0003בד\"א שנתנו לה בפני ב'\u0004. הא דמצטרפים השליח היינו דוקא להיות א' מדייני קיום כשהוא אינו קרוב ופסול אבל לענין ע\"מ אפי' בגט מקוים צריך למסור דוקא בפני שנים בזה איתא פלוגתא אם מצטרפים השליח כמ\"ש בסי' קמ\"א:","\u0003או סמוך לו\u0004. פי' הן שנתן הגט שסמוך לו אמר אחר הנתינה או קודם הנתינה ועיין בתוס' והר\"ן נסתפקו אם מהני כשאומר ב\"נ וב\"נ קודם הנתינ' ואפשר שם איירי אחר כ\"ד, וכן מ\"ש בסעיף א' אומר ב\"נ וב\"נ ואח\"כ יתן היינו תכ\"ד:","\u0003נוטלו ממנה וכו'\u0004. כבר כתבתי בשם המגיד אפי' היכא דאצ\"ל ב\"נ אם נתן בינו לבינו בלא ע\"מ אפי' לשיטות הרי\"ף והרמב\"ם ע\"ח כרתי ולא ע\"מ שהבעל נותן הגט לאש' בלא ע\"מ א\"צ ליטול ממנה מ\"מ כשנותן ע\"י שליח ס\"ל דנוטל ממנה, ולכאורה סותר למ\"ש בסעיף י\"ג בשם ח\"ר וע\"ש:","\u0003אף על פי שיוכל לכתוב\u0004. אף על גב לענין עדות מיתת בעלה מהני ע\"פ כתב כמ\"ש בסי' י\"ז שם משום תקנות עגונות הקילו אף על גב לענין נשים השונאי' זא\"ז מקילין טפי בגט התם הטעם משום נאמנות מקילין טפי בגט משום הגט מסייע ובמיתת בעלה דליכא שום סיוע לא מהני אבל לענין עדות ע\"פ כתב דלאו משום נאמנות אלא שלא לחלק בין עדות לעידות לכן אף על פי שמקילין בעדות שמת בעלה מטעם הנ\"ל מ\"מ אין מקילין בגט כ\"כ הב\"י וא\"ל לרמב\"ם למה בנשתתק אם כותב לגרש את אשתו הולכים אחר כתיבתו משום שם אין עדות אלא מגלה דעתו, ולמ\"ש הב\"י נראה אפי' אם יכול לדבר וכותב ב\"נ וב\"נ לא מהני כדי שלא לחלק בין עדות לעדות ועיין תשו' ריב\"ש סי' תי\"ג דמכשיר לקיים ע\"פ כתב וכ\"כ בהג\"ה ש\"ע בח\"ה סי' מ\"ו סעיף ז' לפ\"ז ג\"כ כשר לכתוב ב\"נ וב\"נ דהיינו קיום וע\"כ מ\"ש הריב\"ש בסי' ק\"מ דלא מהני ע\"פ כתב היינו דוקא באלם דא\"י לדבר אז לא מהני כתיבה משא\"כ כשיכול לדבר וכן מדיוק שם בתשוב' אף על גב דקי\"ל בשאר עדות דא\"י להעיד בכתב אפי' אם יכול לדבר היינו דוקא עדות ממש אז צריכים להגיד בפיהם ולא מהני כתב כלל אפי' אם יכול לדבר אבל קיום מקילין להעיד ע\"פ כתב כשיכול לדבר דוקא בזה צדקו יחדיו מה שפסק בהג\"ה שם סעיף ז' וסעיף ל\"ו ולא כש\"ך שם, ובתשו' ריב\"ש סי' ר\"מ תירץ בע\"א לעולם בעידי מיתה מקילין טפי והא דנשים השונאות זא\"ז מעידים בגט ולא במיתה משום בגט אומר' ב\"נ וב\"נ והבעל תו א\"י לערער ליכא חשד עליה ולא משום קולא:","\u0003שנים\u0004. והוא כבר כתבתי בסי' הקודם דמשמע דמקילין בזה טפי אפי' לדעת המחמירין בסעיף ד' דאין מצטרפין השליח כלל כשמוסר ליד האשה מ\"מ כשמוסר ליד השליח מקילין וכ\"כ בפרישה סקנ\"א:","\u0003יש לו הרשאה\u0004. אף על גב דכתב בסעיף א' הרשאה לא מקרי קיום משום דחיישינן שמא אבד גט הראשון וזה גט אחר מ\"מ לענין זה מהני הרשאה כמ\"ש בתשו' ריב\"ש שם:","\u0003וי\"א דלא מהני וכו'\u0004. הב\"י מדייק כן מדברי הריב\"ש ובסי' קמ\"א כתבתי באריכות:","\u0003הרשאה\u0004. משום בהרשאה מבואר שאמר השליח הראשון ב\"נ וב\"נ ממילא מקוים הגט או אם נתקיים הגט א\"צ שטר הרשאה ונאמן לומר שעשאו לש\"ה אף על גב דאצ\"ל ב\"נ וב\"נ מזה משמע לא כתירוץ א\"נ שכתב הב\"י בסי' קמ\"א סעיף כ\"ב:","\u0003שאי\"ל ב\"נ וב\"נ\u0004. וקל קולמוס לא מהני בסומא משום אם יאמר ב\"נ וב\"נ מחזי כשקרא ואם יאמר שמעתי קל קולמוס לא יאמר כתיקון חז\"ל כ\"כ הרא\"ש ועיין תוס' והר\"ן:","\u0003ה\"ז אומר ב\"נ וב\"נ\u0004. היינו בפני ג' דוקא כמ\"ש הרמב\"ם דהא הוא פסול לדיין דהוא סומא משא\"כ העדות מה שאומר ב\"נ וב\"נ כשר דהא אשה וקרוב כשירים לעדות זה:","\u0003בטביעו' קול\u0004. עיין סי' קל\"ב מ\"ש בשם המגיד בזה\"ז שום אדם אינו נאמן בטביעות עין אפי' צורבא דרבנן ואין לחלק בין טביעות עין לטביעות קלא דהא לפי סוגי' בפ' גיד הנשה מוכח דשוין הם ולכאורה קשה למה פסק כאן דמהני טביעות קלא, וא\"ל דאפשר לנסות אותו אם מכיר אותה אם כן גם שם אפשר לנסות וליתן לפניו שאר גיטין הנכתבין כזה ואפשר כיון דידוע לנו דזאת אשת המשלח הגט סמכי' ע\"ז דהוא גם כן מכיר אותה כיון דנותן לאשה זו ולא לאשה אחרת לפ\"ז אם א\"י לנו אם זו אשת המשלח לא סמכינן על הסומא אף על גב הוא אומר דמכיר אות' בטביעות קלא, והנה כשם שצריך להכיר את האשה כן צריך להכיר את האיש בט\"ק כמ\"ש בש\"ס דא\"י ממי נוטלה בסעי' זה איירי בהי' פתוח מעיקר' ואז מסר לידו והיה יודע ממי קיבל הגט ובסעיף אח\"ז שכתב שמסר לסומא צריך להכיר בט\"ק האיש והאשה:","\u0003שני עידים כשירים שאינן קרובים\u0004. עיין סימן קמ\"א סעיף ל\"ו שם לא כתב דצריך ליתן לפני עדים כשירים ש\"מ מ\"ש כאן אינה אלא לכתחלה וכ\"כ בט\"ז וראיה של הת\"ה שם אין מוכרח, לכן מהני בדיעבד אם נשאת אפי' קרוב ואשה כמו בהכרת החלוץ:","\u0003כיון שיש עדים אצ\"ל ב\"נ\u0004. כתב ב\"ח אפי' אם העדים אין מכירים החתימות מ\"מ כיון שמעידים דהבעל מסר גט זה ליד הסומא אצ\"ל ב\"נ וב\"נ דלא עביד לקלקל אותה במזיד ואם אתא הבעל ומערער צריך לקיים ועיין בסמוך:","\u0003ויהיב לה באפי הנהו סהדי\u0004. כי היכא דלהוי דבר שלם ולא חצי דבר, מיהו בדין זה פליגי הרי\"ף ותוס' כמ\"ש בתוס' מרובה דף פ' להרי\"ף כל שאינו מהני הראיי' של כת זו בלי כת השניה הוי חצי דבר לכן אם כת א' אומרת דראו שערה א' וכת שניה מעידים על שערה אחר הוי חצי דבר אבל כשמעידים ג' כיתות עדים על חזקת ג' שנים כל כת מעיד שאכל שנה א' הוי דבר שלם משום כל כת מהני להוציא ממנה פירות שנה זו ולתוס' תליא הדבר אם היו יכולים לראות יותר כמו בשערות דהיו יכולים לראות שתי שערות ולא ראו הוי חצי דבר אבל בחזקה בשנה זו לא היו יכולים לראות יותר, לפ\"ז דין דכאן תליא בפלוגתא זו והרמ\"ה דס\"ל כאן דהוי חצי דבר ס\"ל כהרי\"ף דהא לתוס' שראו המסירה לא היו יכולים לראות יותר אבל להרי\"ף כיון דלא מהני המסירה לבד הוי חצי דבר, ובזה מיושב מה שהקשה בד\"מ ע\"ש, וכל זה ראיתי ג\"כ בט\"ז והא דמהני כשהיא עושה ש\"ק וכת א' מעידים דעשתה אותו לש\"ק וכת א' מעידים דקיבל הגט לתוס' שפיר דלא היו יכולים לראות יותר ולהרי\"ף צ\"ל משום דעידי אמירה א\"צ לעידי קבלה כיון הגט בידו והאי תירוץ דחו תוס' שם וכ\"כ הריב\"ש סימן שי\"ח אליבא הרמ\"ה ומזה מוכח נמי דהרמ\"ה ס\"ל כהרי\"ף:","\u0003כשר בכל גוונא\u0004. כלומר אפי' בח\"ל אפי' היה סומא מעיקרו אפילו אין כאן עדים שמסר לו הגט אבל מ\"מ צריך להכיר את האיש והאשה בט\"ק:","\u0003הרי את שליח להולכה וכו'\u0004. ואם אמר הרי את ש\"ה עד לשם ושם הוי את ש\"ק לא הוי גט כלל משום דלא חזרה השליחות לבעל וגרע טפי ממ\"ש ר\"ס קמ\"א דשם היה ראוי השליח להשיב לבעל את שליחתו בתחלת שליחתו אבל כאן לא היה ראוי מיד להשיב את שליחתו, ואם א\"ל שם תעשה את ש\"ק אז דומה לחצירו הבא אח\"כ ותליא בפלוגתא ר\"ס קמ\"א:","\u0003עד ב\"ד פלוני\u0004. עיין ב\"י מ\"ש בשם הרשב\"ץ אם שולח ע\"י א' ליתן הגט לשלוחו אז הראשן לא הוי שליח לגירוש כלל דאינו עושה אלא מעש' קוף ואינו נאמן בדיבורו ב\"נ וב\"נ אא\"כ באומר שהוא יעשה איזה שליח שירצה למסור לו הגט לפ\"ז נ\"ל גם כשאמר לה שתמסו' לב\"ד דוקא אם אמר לה שתמסור לאיז' ב\"ד שתרצ' מהני מה שאמ' הב\"נ וב\"נ אבל אם מייחד הב\"ד ואומר לב\"ד פלוני תמסו' אז הוא לא נעש' לשליח כלל ולא מהני ב\"נ וב\"נ מה שהיא תאמר ויש לחלק כיון הבעל לא עשה הב\"ד לשלוחו אלא על ידה הוא מצוה:","\u0003וצריכה לאמרו וכו'\u0004. אף על גב אם אמרה סתם נתגרשתי נאמנת כשהגט בידה כמ\"ש במסוך מ\"מ כשאומרת שהיא שליח צריכה לאמר ב\"נ וב\"נ כשאר שליח ואינה נאמנת מכח מיגו כ\"כ הר\"ן ואם מסרה ליד ש\"ה ולא אמרה ב\"נ וב\"נ לא מהני כי כבר עשתה שליחות שלה כ\"כ בת\"ה מיהו בתשו' ריב\"ש סימן שי\"ח כתב בענין אם עשה שליח הראשון שליח אחר יש תקנה שיחזיר הגט ליד שליח הראשון ויעשה אותו בפני ב\"ד וכן משמע בסעיף ז' וכמ\"ש בש\"ס המביא גט ממה\"י ולא אמר ב\"נ יחזור ויטלנו ממנה מה לי שנתן לידה ומה לי אם נתן ליד השליח, וא\"ל שם איירי כשהבעל נותן לו רשות הא הבעל אינו שם דהא תנן המביא גט ממ\"י גם רשות של הבעל לא מהני לענין זה, ואיתא בש\"ס עוד אוקימתא בסוגיא זו האמר לה הוי ש\"ה עד לשם וכי מטי התם שוי' ש\"ה וכתבו תוס' דאז אצ\"ל ב\"נ וב\"נ בעת שמסרה הגט ליד השליח אלא בשעה שתקבל הגט מיד השליח והרשב\"א והטור חולקים על תוס' וס\"ל דצריכה לומר ב\"נ בעת שמסרה הגט ליד השליח:","\u0003ויש חולקין\u0004. עיין תשו' הריב\"ש סימן שפ\"ה היש חולקי' הוא הראב\"ד פי\"ב וס\"ל האשה דומה לשליח בשעה שמסר הגט נאמן לומר ב\"נ וב\"נ אבל אחר שמסר תו לא מהני דיבורו כן ה\"נ האשה כשהיא מביאה הגט בתורת שליח ועדיין לא נתגרשה מהני דיבורה כמ\"ש בש\"ס ובדין לפני זה אבל אם באתה והביאה גט בידה ואומרת כבר נתגרשה תו לא מהני דיבורה כמו בשליח אחר שמוסר הגט וצריכה עדים וע\"ש איך מיישב הסוגיא פ\"ב לכן בדין קמייתא כשהיא מביא הגט בתורת שליח נאמנת וכן אם הביא השליח הגט בא\"י ואינו אומר ב\"נ נאמן כיון דאתא בתורת שליחות שאני:","\u0003בעל שמביא גט בעצמו וכו'\u0004. דין זה כתב א\"ח והביאו הב\"י בסי' קמ\"א ולכאורה דין זה תמוה דהא בברייתא איתא בעל שהביא גט אצ\"ל ב\"נ וב\"נ כמ\"ש ריש גיטין דף ה' ובא\"ח כתב בזה הלשון כדי שיוכל הבעל לומר ב\"נ וב\"נ כיון שהבעל עצמו מביא כדאמרינן ריש גיטין הבעל עצמו וכו' כי בעונותינו אין אנו בני תורה כמו הראשונים וכו' ונ\"ל דא\"ח ס\"ל כראב\"ד דס\"ל הלכה כרבה דאמר הטעם שצ\"ל השליח ב\"נ וב\"נ משום דאין בקיאין לשמה ומשום דאין עדים מצוין לקיימו ס\"ל כל הסוגיא שם איירי אחר שלמדו אז אצ\"ל ב\"נ וב\"נ וכן הא דתניא שנים שהביאו גט וכן חרש ונתפקח דא\"צ ב\"נ וב\"נ איירי אחר שלמדו אז אצ\"ל ב\"נ וכן הבעל דוק' אחר שלמדו אצ\"ל א\"כ השתא בעונתינו אין אנו בני תורה כמו הראשונים מ\"ה צ\"ל אפי' הבעל ב\"נ דהוי כמו קודם שלמדו אבל לדידן דקי\"ל כרבא דאמר הטעם משום קיום אם כן הבעל אצ\"ל ב\"נ כיון הוא בעצמו הביא הגט לא מהני עירעור שלו וגם הוא אינו חשוד להכשילה במזיד כמ\"ש בתוס' ורמ\"א הוסיף מדלי' דצ\"ל ב\"נ כדי שלא לטעות בשליח אחר כיון אנן אינן בני תורה ס\"ל מ\"ש הטעם דאנן אינן בני תורה היינו מ\"ה ראוי לגזור אטו שליח אחר ואנ\"ל דא\"כ בשנים המביאים גט יש לחוש אטו שליח אחר דהא בש\"ס איתא אחר שלמדו מ\"מ חד ואשה צ\"ל ב\"נ שמא יחזור דבר לקלקולו וכדי שלא תחלוק בשליחות ומ\"מ כשמביא הבעל הגט או שנים לא אמרינן לא תחלוק בשליחות ואצ\"ל ב\"נ, ולא גזרינן אטו שליח אחר:","\u0003אם מקצתו הראשון\u0004. הטעם שאומר השליח ב\"נ משום קיום כמ\"ש לעיל ואצ\"ל בפני נכתב אלא כדי שלא אתא לאחלופי בשאר קיום שטרות מ\"ה אומר בפני נכתב להיכר לכן די אם נכתב לפניו מקצת הראשון ולדעת רש\"י ותוס' צריך להיות נכתב בפניו השיטה שיש בה שם האיש והאשה ולדעת הר\"ן גם היא מותרת צריך לכתוב בפניו ומדברי הרמב\"ם והרא\"ש והטור משמע אפי' לא נכתב שם איש וכו' יש לומר ב\"נ וכן סתם המחבר כרמב\"ם מיהו יש להחמיר כדעת רש\"י ותוס' משמע דוקא כשאמר ששמע תיקון הקלף צ\"ל שהיתה התיקון לשמה אבל אם נכתב בפניו אמרינן מסתמא היה כותבין לשמו ולשמה:","\u0003קול קולמוס\u0004. יש בזה כמה פרושי' ועיין ברש\"י ותוס' והג\"א ומלשון הרמב\"ם דהיינו לשון המחבר משמע דשמע הקול כשכותבין על הקלף כפי' השני של רש\"י ואפי' קול מקצת הכתיבה היינו מקצת הראשון ולפי' הראשון של רש\"י פירושו שראה חיתוך הקולמוס והקלף לכתוב הגט לשמה וכ\"כ הטור אבל אם לא ראה החיתוך אלא א\"ל בפניו לכתוב הגט לא מהני ובהג\"א כ' אם שמע שאמר הבעל כתוב הגט לאשתי והסופר לקח הקלף והקולמוס מהני:","\u0003וחתמו העדים בפניו\u0004. משמע בחתימת העדים לא מהני קול הקולמוס וכן משמע בטור אפי' אם נשמע קול מכל החתימה ולכאורה תמוה דהא כתבו תו' והרא\"ש דאין להכשי' סומא ע\"י קול קולמוס משום דנראה כשקר אם יאמר ב\"נ וב\"נ כמ\"ש לעיל וכ\"כ הר\"ן ואי ס\"ל בחתימה לא מהני קול קולמוס אפי' מי שאינו סומא מה הקשו בסומא וצ\"ע, שוב ראיתי בחדושי רש\"ך הרגיש ג\"כ בזה:","\u0003ונחתם ע\"א\u0004. אף על גב דקי\"ל אין עידי הגט חותמים אלא זה בפני זה מ\"מ לא הוי קיום לשני כמ\"ש בתשו' רשב\"א:","\u0003אפי' אם הוא א' מעידי הגט\u0004. משום דבעינן או כולו בקיום הגט שכ\"א יאמר זה כת\"י או כולו בתקנות חז\"ל שהשליח יאמר שניהם חתמו בפני ש\"ס אף על גב אם אומר בפני חתם מהני א\"כ למה לא מהני אם אומר אני הוא העד השני תירצו תוס' משום דהוה כנוגע בעדות דמעיד על חבירו משום שחתום עמו וע\"ש:","\u0003הוא ואחר\u0004. אבל הוא לבדו אם מעיד דיודע חתימת השני שלא חתם בפניו לא מהני משום דוקא כשחותם בפניו אז מדייק שפיר ולא מרע לנפשו לומר שנעש' בפניו והוא לא ראה אבל כשאומר ידעתי מצי לאשתמוטי לומר סבור הייתי שאני מכירה כ\"כ תוס' והרא\"ש והר\"ן ולא כרש\"י:","\u0003אין בכך כלום\u0004. הנה בירושלמי מדמי דין זה לפלוגתא ר\"י ור\"ל באומר לעשרה חתמו אם כולם משום עדים או שנים משום עדים והשאר משום תנאי כמ\"ש בסי' ק\"כ ולר\"י דפסק המחבר שם כוותיה שפיר דשלישי משום תנאי היא אין קפידא אם יחתום שלא בפניו מיהו אם הוא חתום בתחלה פסול כדלעיל לענין קרוב או פסול וכ\"כ ב\"ח אבל ר\"ל דס\"ל כולם משום עדים אז אם השלישי חתום שלא בפניו פסול ורמ\"א פסק שם דיש להחמיר כר\"ל וכאן לא הגיה כלום קשה ליישב וצ\"ל דס\"ל אף על גב דמחמירים שם כר\"ל מ\"מ כאן דליכא פסול די\"ל השלישי ג\"כ שפיר חתם אין להחמיר בזה:","\u0003עשה הבעל כו'\u0004. לרמב\"ם אין הבעל יכול לערער וכ\"כ הרא\"ש ריש גיטין מתוך שהוא יודע שאם בא לערער ערעורו בטל אז הוא מחתים עדים כשרים וכן משמע בתשו' ריב\"ש סי' שי\"ח וע\"ש בדרישה וב\"ח כתב שם הרא\"ש להיפוך תמוה בעיני ומ\"ש הטור דהבעל יכול לערער והיינו הי\"א שהביא בהג\"ה אפשר שכ\"כ לחוש לדעת רש\"י שפי' שם ריש גיטין דאתיא תרי ואם יבא הבעל לערער יכולים הם לקיים וכ\"כ בפ\"ב שנים שהביאו אצ\"ל ב\"נ משום דהם עידי קיום ש\"מ דוקא כשהם יכולים להעיד על חתימתו מהני חושש הטור לדעת רש\"י:","\u0003שהרי שלוחיו הם עדיו\u0004. ולא יהא שיאמרו בפנינו נתגרשה דנאמנים מ\"ה בעינן שיהיו כשירים להעיד ואז שייך מיגו זה:","\u0003וערער\u0004. היינו שמערער שנתן לה גט מזויף אף על גב דלא עביד לקלקל אותה במתכוין היינו דאין חוששים לזה אבל אם מערער וטוען כך טענתו טענ' משא\"כ כשטוען מכחיש אותם שלא שלח אותם אינו נאמן לכ\"ע:","\u0003וי\"א אפי' לא עשה וכו'\u0004. כ\"כ תוס' והרא\"ש והר\"ן והרשב\"א וכתבו אפשר גם הרמב\"ם מודה לזה הואיל יש שני עדים שמסר הגט מידו לידם ואין נמצא שום חולק ע\"ז ומ\"ש הב\"י דהרמ\"ה חולק ע\"ז תמוה דהא הטור כתב בזה וכ\"כ הרמ\"ה אלא ס\"ל להרמ\"ה דצריך למסור הגט לפני אלו שנים יחדיו כמ\"ש בסמוך אבל גוף הדין לא מצינו חולק ואפשר דהבין מלשון הרמב\"ם דכתב עשה שנים שלוחים משמע דוקא כשהשנים שלוחים הם ובתשובת ריב\"ש כתב ג\"כ בשם וי\"א:","\u0003ויש מי שמצריך\u0004. היינו סברות הרמ\"ה בין אם שניהם מעידים שמסר לידו ובין אם א' מעיד צריכים עדים אלו להיות בעת מסירת הגט לידה ומכל שכן כששניהם שלוחים כי צריכים להיות בעת המסירה דהא צריכים לקיים שליחותם ועיין בב\"ה והטעם דצריכים המעידים להיות בעת המסירה כי היכא דלא הוי חצי דבר כיון השליח לא יאמר ב\"נ והעיקר הגט ע\"י עדות אלו האומרים שמסר הגט לידו צריכים להיות שם, ובסעיף י\"ב פסק בפשיטות כדעת הרמ\"ה וכאן כתב ויש מי שמצריך וראיתי בבדק הבית שהקשה כאן על הרמ\"ה למה הוי חצי דבר הרי עידי שליחות לחוד ועידי מסירה לחוד מ\"ה כתב כאן ויש מי שמצריך והא דלא הקשה כן לעיל בסומא אפשר שאני סומא שאינו ראוי כלל לשליחות בלא עדים מודה הב\"י דהוי חצי דבר אבל שליח כשר ושני מעיד בפניו מסר לידו כי היכא דאצ\"ל ב\"נ ס\"ל דהוי דבר שלם, ומה שאחד העיד בפניו מסר הגט ליד השליח היינו שאומר שעשאו לשליח בפני שנים ומסר בפניו הגט כמ\"ש ר\"ס קמ\"א דאין מצרפין השליח:","\u0003אם אין שליח אלא אחד\u0004. והשני לא ידע דנמסר לזה דאל\"כ כשר לי\"א שהביא בסעיף הקודם:","\u0003אלא א' מהם\u0004. אף על גב דהוה כשנים ושנים מעידים על הכתיבה מכל מקום לא מהני כיון שהוא א' ואינו מעיד על הכתיבה אתא לאחלופי בשאר שטרות משא\"כ בשנים מעידים על החתימה ואפילו אם אחד מאותן שנים המעידים על החתימות הוא השליח לבדו מכל מקום כשר דהא עכ\"פ מעידים שנים על החתימות והמחבר סתם ופסק כרמב\"ם והשמיט דעת הטור ועיין ב\"י וב\"ח ובתשובות בן לב דף ל\"ח:","\u0003דמן התורה וכו'\u0004. אף על גב בלא קיום נמי מן התורה כשר דקי\"ל העדים החתומים על השטר כמו שנחקרה עדותן בב\"ד דמי מ\"מ לא מקיל בזה אלא בקיום בזה דס\"ל לכמה פוסקים קיום ב\"ד א\"צ קיום בזה הוא מקיל ועיין בב\"י סי' מ\"א שם הביא תשובת ר\"ש בן רשב\"ץ:"]],["הַמְגָרֵשׁ עַל תְּנַאי, אִם נִתְקַיֵּם הַתְּנַאי הֲרֵי זוֹ מְגֹרֶשֶׁת; וְאִם לֹא נִתְקַיֵּם הַתְּנַאי, אֵינָהּ מְגֹרֶשֶׁת; וַאֲפִלּוּ הוּא כֹּהֵן, מֻתֶּרֶת לוֹ. וּכְבָר נִתְבָּאֲרוּ מִשְׁפְּטֵי הַתְּנָאִים בְּסִימָן ל\"ח:\nהַמְגָרֵשׁ עַל \u0010c0\u0011 הַתְּנַאי, כְּשֶׁיִּתְקַיֵּם הַתְּנַאי תִּהְיֶה מְגֹרֶשֶׁת; בְּשָׁעָה שֶׁיִּתְקַיֵּם, לֹא בִּשְׁעַת נְתִינַת הַגֵּט לְיָדָהּ. לְפִיכָךְ, יֵשׁ לַבַּעַל לְבַטֵּל הַגֵּט, אוֹ לְהוֹסִיף עַל תְּנָאוֹ, אוֹ לְהַתְנוֹת תְּנַאי אַחֵר, כָּל זְמַן שֶׁלֹּא נִתְקַיֵּם הַתְּנַאי הָרִאשׁוֹן, אַף עַל פִּי שֶׁהִגִּיעַ לְיָדָהּ. וְאִם מֵת הַבַּעַל, אוֹ אָבַד הַגֵּט, אוֹ נִשְׂרַף, קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי, אֵינָהּ \u0010c1\u0011 מְגֹרֶשֶׁת; וְאִם נִשֵּׂאת, תֵּצֵא. וְאִם אָמַר לָהּ: \u0010c2\u0011 הֲרֵי אַתְּ מְגֹרֶשֶׁת מֵעַכְשָׁו, אוֹ מֵהַיּוֹם, עַל תְּנַאי כָּךְ וְכָךְ, אוֹ שֶׁאָמַר לָהּ: הֲרֵי אַתְּ מְגֹרֶשֶׁת עַל מְנָת כָּךְ וְכָךְ \u0005 וְעַיֵּן לְקַמָּן סִי' קמ\"ד סָעִיף ד' דְּיֵשׁ אוֹמְרִים דְּעַל מְנָת לָאו כְּמֵעַכְשָׁו דָּמֵי, \u0006 כְּשֶׁיִּתְקַיֵּם הַתְּנַאי, תִּהְיֶה מְגֹרֶשֶׁת מִשְּׁעַת נְתִינַת הַגֵּט לְיָדָהּ; לְפִיכָךְ, אֵינוֹ יָכוֹל לְבַטֵּל הַגֵּט וְלֹא לְהוֹסִיף עַל תְּנָאוֹ מִשֶּׁהִגִּיעַ לְיָדָהּ; וְאִם אָבַד אוֹ נִשְׂרַף, \u0005(וַאֲפִלּוּ מֵת הַבַּעַל)\u0006 קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי, הֲרֵי זוֹ מְקַיֶּמֶת הַתְּנַאי אַחַר מוֹתוֹ, וּכְבָר נִתְגָּרְשָׁה מִשְּׁעַת נְתִינַת הַגֵּט לְיָדָהּ. וּלְכַתְּחִלָּה לֹא תִּנָּשֵׂא קֹדֶם קִיּוּם הַתְּנַאי, וְאִם נִשֵּׂאת, יִפְרשׁ מִמֶּנָּה עַד שֶׁיִּתְקַיֵּם הַתְּנַאי. וּמִיהוּ, בִּתְנַאי שֶׁהוּא \u0010c3\u0011 בְּיָדָהּ, וְהוּא בְּשֵׁב וְאַל תַּעֲשֶׂה, לֹא חַיְשִׁינָן שֶׁמָּא תַּעֲבֹר עָלָיו, וּלְפִיכָךְ מֻתֶּרֶת לִנָּשֵׂא מִיָּד, בִּתְנַאי דְּעַל מְנָת אוֹ מֵעַכְשָׁו. וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ לֹא אָמַר: מֵעַכְשָׁו וְלֹא מֵהַיּוֹם וְלֹא עַל מְנָת, דִּינוֹ כְּאוֹמֵר: מֵהַיּוֹם, מִשּׁוּם דִּזְמַנּוֹ שֶׁל גֵּט מוֹכִיחַ עָלָיו, הִלְכָּךְ, אָזְלִינָן בָּהּ לְחֻמְרָא. \u0005 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ בִּתְנַאי דְּמֵעַכְשָׁו יָכוֹל לְבַטְּלוֹ, וְיֵשׁ לְהַחֲמִיר \u0006 \u0005(עִטּוּר, וְכֵן מַשְׁמָע בְּהָרֹא\"שׁ)\u0006:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז מִכָּאן וְעַד שְׁלשִׁים יוֹם, וּמֵת בְּתוֹךְ הַשְּׁלשִׁים יוֹם, קֹדֶם שֶׁנְּתָנָתַם לוֹ, אֵינָהּ יְכוֹלָה לְקַיֵּם הַתְּנַאי, שֶׁאִם תִּתֵּן לְיוֹרְשָׁיו אֵינוֹ כְּלוּם, וְכֵיוָן שֶׁכֵּן, כֵּיוָן שֶׁשָּׁלְמוּ שְׁלשִׁים יוֹם וְלֹא נָתְנָה לוֹ, \u0010c4\u0011 בָּטְלוּ הַגֵּרוּשִׁין וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. וְאִם אָמַר לָהּ: עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז, וְלֹא קָבַע לָהּ זְמַן, וּמֵת קֹדֶם שֶׁתִּתֵּן לוֹ, אַף עַל פִּי שֶׁאָבַד הַגֵּט אוֹ נִקְרַע קֹדֶם שֶׁיָּמוּת, הֲרֵי זוֹ לֹא תִּנָּשֵׂא לְזָר \u0010c5\u0011 עַד שֶׁתַּחֲלֹץ:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז מִכָּאן וְעַד שְׁלשִׁים יוֹם, וְנָתְנָה לוֹ בְּתוֹךְ שְׁלשִׁים יוֹם בְּעַל כָּרְחוֹ, וְהוּא אֵינוֹ רוֹצֶה לְקַבֵּל, \u0010c6\u0011 הֲרֵי זֶה גֵּט פָּסוּל, עַד שֶׁתִּתֵּן מִדַּעְתּוֹ:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז מִכָּאן וְעַד שְׁלשִׁים יוֹם, וְחָזַר וְאָמַר לָהּ בְּתוֹךְ הַשְּׁלשִׁים יוֹם; הֲרֵי הֵם \u0010c7\u0011 מְחוּלִים לָךְ, אֵינָהּ מְגֹרֶשֶׁת, שֶׁהֲרֵי לֹא נַעֲשָׂה הַתְּנַאי. \u0010c8\u0011 וְיֵשׁ אוֹמְרִים דְּהָנֵי מִלֵּי כְּשֶׁלֹּא אָמַר לָהּ אֶלָּא: הֲרֵי הֵם מְחוּלִים לָךְ לְבַד, אֲבָל אִם אָמַר לָהּ: לֶהֱוֵי גִּטָּא בְּלֹא שׁוּם תְּנַאי, הֲרֵי זוֹ מְגֹרֶשֶׁת וְאֵין צָרִיךְ לִטְּלוֹ מִמֶּנָּה:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּתְּנִי לִי כְּלִי פְּלוֹנִי אוֹ בֶּגֶד פְּלוֹנִי, וְאָבַד אוֹתוֹ כְּלִי אוֹ אוֹתוֹ בֶּגֶד, אוֹ נִגְנַב, אַף עַל פִּי שֶׁנָּתְנָה לוֹ אֶלֶף זוּז בְּדָמָיו, אֵינוֹ גֵּט עַד שֶׁתִּתֵּן אוֹתוֹ כְּלִי אוֹ אוֹתוֹ בֶּגֶד עַצְמוֹ, אוֹ שֶׁיֹּאמַר לָהּ: לֶהֱוֵי גִּטָּא בְּלֹא שׁוּם תְּנַאי. \u0010c9\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם הוּא מִתְרַצֶּה בְּקַבָּלַת הַדָּמִים, הָוֵי גֵּט:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּתְּנִי לִי מָאתַיִם זוּז מִכָּאן עַד שְׁלשִׁים יוֹם, אֲפִלּוּ לֹא נָתְנָה לוֹ עַד יוֹם שְׁלשִׁים בְּסוֹפוֹ, מְגֹרֶשֶׁת. וְאִם אָמַר לָהּ בִּתְחִלָּה יוֹם רִאשׁוֹן לַחֹדֶשׁ, וְנָתְנָה לוֹ בְּסוֹף לֵיל רִאשׁוֹן לַחֹדֶשׁ הַשֵּׁנִי, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:\nהִתְנָה עָלֶיהָ שֶׁתַּעֲשֶׂה דָּבָר זֶה, סְתָם, \u0010c10\u0011 הֲרֵי זֶה כִּמְפָרֵשׁ יוֹם אֶחָד, הוֹאִיל וְלֹא פֵּרַשׁ כַּמָּה זְמַן תַּעֲשֶׂה. כֵּיצַד, אָמַר לָהּ: הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתַּעֲשִׂי עִמִּי מְלָאכָה, עַל מְנָת שֶׁתְּשַׁמְּשִׁי אֶת אַבָּא, עַל מְנָת שֶׁתֵּנִיקִי אֶת בְּנִי, אִם עָשְׂתָה עִמּוֹ מְלָאכָה אוֹ אִם שִׁמְּשָׁה אֶת אָבִיו יוֹם אֶחָד, אוֹ שֶׁהֵנִיקָה בְּנוֹ יוֹם אֶחָד בְּתוֹךְ הַזְּמַן שֶׁהַבֵּן יוֹנֵק בּוֹ וְהוּא בְּתוֹךְ כ\"ד חֹדֶשׁ, הֲרֵי זֶה גֵּט. \u0005 הַגָּה: \u0010c11\u0011 וְיֵשׁ אוֹמְרִים דְּצְרִיכָה לְשַׁמֵּשׁ הָאָב כָּל יְמֵי \u0006 \u0005 חַיָּיו, וּצְרִיכָה לְהֵנִיק הַתִּינוֹק עַד סוֹף כ\"ד חֹדֶשׁ \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010c12\u0011 \u0005 וְאִם מֵתוּ לְאַחַר שֶׁהִתְחִילָה לְקַיֵּם הַתְּנַאי רַק יוֹם \u0006 \u0005 אֶחָד, הָוֵי גֵּט \u0006 \u0005(טוּר)\u0006. מֵת הַבֵּן \u0010c13\u0011 אוֹ מֵת אָבִיו קֹדֶם שֶׁתֵּנִיק אוֹ שֶׁתְּשַׁמֵּשׁ, \u0010c14\u0011 אֵינוֹ גֵּט. אָמַר לָהּ: עַל מְנָת שֶׁתֵּנִיקִי אֶת בְּנִי אוֹ שֶׁתְּשַׁמְּשִׁי אֶת אָבִי שְׁתֵּי שָׁנִים, הֲרֵי זוֹ מַשְׁלֶמֶת הַזְּמַן שֶׁפֵּרַשׁ. מֵת הַבֵּן אוֹ הָאָב בְּתוֹךְ הַזְּמַן \u0010c15\u0011 שֶׁפֵּרַשׁ, אוֹ שֶׁאָמַר הָאָב: אֵין רְצוֹנִי שֶׁתְּשַׁמְּשֵׁנִי, אֵינוֹ גֵּט, שֶׁהֲרֵי לֹא נִתְקַיֵּם הַתְּנַאי, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010c16\u0011 \u0005 וְיֵשׁ אוֹמְרִים דְּכָל שֶׁאֵין הָעִכּוּב מִמֶּנָּה, הָוֵי גֵּט \u0006 \u0005(טוּר בְּשֵׁם ר\"י)\u0006, \u0005 וְנִרְאֶה לִי, דְּאָזְלִינָן בְּכָל זֶה לְחֻמְרָא: \u0006\nיֵשׁ אוֹמְרִים דְּכִי אָמְרִינָן דְּהֵנִיקָה אוֹ שִׁמְּשָׁה יוֹם אֶחָד הָוֵי גֵּט, לָאו דַּוְקָא יוֹם אֶחָד, דַּאֲפִלּוּ בְּשָׁעָה אַחַת סָגֵי. \u0010c17\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, דְּיוֹם אֶחָד דַּוְקָא, כְּלֵיל שַׁבָּת וְיוֹמוֹ:\nהַנּוֹתֵן גֵּט לְאִשְׁתּוֹ עַל מְנָת שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז, \u0010c18\u0011 וְחָזַר וְהִתְנָה עָלֶיהָ תְּנַאי אַחֵר בִּפְנֵי עֵדִים שֶׁתְּשַׁמֵּשׁ אָבִיו שְׁתֵּי שָׁנִים, לֹא בִּטְּלוּ דְּבָרָיו הָאַחֲרוֹנִים אֶת הָרִאשׁוֹנִים, אֶלָּא הֲרֵי זֶה כְּאוֹמֵר לָהּ: עֲשִׂי אֶחָד מִשְּׁנֵי תְּנָאִים, רָצָת מְשַׁמֶּשֶׁת, רָצָת נוֹתֶנֶת; \u0010c19\u0011 וְאֵין אֶחָד מֵהָרִאשׁוֹנִים וְאֶחָד מֵהָאַחֲרוֹנִים מִצְטָרְפִים. אֲבָל אִם הִתְנָה עָלֶיהָ שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז, וְחָזַר וְהִתְנָה בִּפְנֵי שְׁנַיִם שֶׁתִּתֵּן לוֹ שְׁלשׁ מֵאוֹת זוּז, כְּבָר בִּטֵּל הַתְּנַאי שֶׁל מָאתַיִם זוּז, וּצְרִיכָה לִתֵּן שְׁלשׁ מֵאוֹת זוּז. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005 הַגָּה: וְי\"א דְּכָל זֶה דַּוְקָא בְּשֶׁלֹּא מָסַר לָהּ הַגֵּט לֹא בִּתְנַאי רִאשׁוֹן וְלֹא בִּתְנַאי שֵׁנִי, אֶלָּא אַחַר שְׁנֵי הַתְּנָאִים מָסַר לָהּ הַגֵּט בִּפְנֵי עֵדִים הָרִאשׁוֹנִים וְהָאַחֲרוֹנִים. אֲבָל מָסַר לָהּ הַגֵּט בִּשְׁעַת תְּנַאי הָרִאשׁוֹן אוֹ הַשֵּׁנִי, אוֹתוֹ תְּנַאי דַּוְקָא \u0006 \u0005(הָרַ\"ן פֶּרֶק מִי שֶׁאֲחָזוֹ)\u0006:\nהֲרֵי זֶה גִּטֵּךְ וְהַנְּיָר שֶׁלִּי, אֵינָהּ \u0010c20\u0011 מְגֹרֶשֶׁת, שֶׁאֵין זֶה כְּרִיתֻת. עַל מְנָת שֶׁתִּתְּנִי לִי אֶת הַנְּיָר, הֲרֵי זוֹ \u0010c21\u0011 מְגֹרֶשֶׁת, וְתִתֵּן:\nהִתְנָה עַל דָּבָר שֶׁאִי אֶפְשָׁר לְקַיְּמוֹ, כְּגוֹן: עַל מְנָת שֶׁתַּעֲלִי לָרָקִיעַ, אוֹ שֶׁתֵּרְדִי לַתְּהוֹם, אוֹ שֶׁתִּבְלְעִי קָנֶה שֶׁל אַרְבַּע אַמּוֹת, אֵינוֹ תְּנַאי, וְהַגֵּט גֵּט. אֲבָל אִם הִתְנָה בְּדָבָר שֶׁאֶפְשָׁר לְקַיְּמוֹ, אֲפִלּוּ בְּאִסוּר, כְּגוֹן עַל מְנָת שֶׁתֹּאכְלִי בְּשַׂר חֲזִיר, הָוֵי תְּנַאי, שֶׁאֶפְשָׁר שֶׁתֹּאכְלֶנּוּ וְתִלְקֶה; וְאֵין זֶה מַתְנֶה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה, שֶׁאֵינוֹ מַתְנֶה שֶׁתֹּאכְלֶנּוּ עַל כָּל פָּנִים, שֶׁאִם לֹא תֹּאכְלֶנּוּ לֹא תִּתְגָּרֵשׁ. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָאִסוּר תָּלוּי בָּהּ לַעֲבֹר עָלָיו. אֲבָל אִם תָּלוּי בַּאֲחֵרִים, שֶׁאָמַר לָהּ: עַל מְנָת שֶׁתִּבָּעֲלִי לְאַבָּא, לֹא הָוֵי תְּנַאי, שֶׁאָבִיו לֹא יִשְׁמַע לָהּ לַעֲשׂוֹת אִסוּר:\nאָמַר לָהּ: עַל מְנָת שֶׁלֹּא תִּבָּעֲלִי לְאַבָּא, וְנִבְעֲלָה לוֹ, אֵינוֹ גֵּט. אֲבָל כָּל זְמַן שֶׁאֵין עֵדִים שֶׁנִּבְעֲלָה לוֹ, \u0010c22\u0011 אֵין חוֹשְׁשִׁין שֶׁמָּא נִבְעֲלָה לוֹ. \u0005 וּמֻתֶּרֶת לְהִנָּשֵׂא, וְאֵין חוֹשְׁשִׁין שֶׁמָּא תִּבָּעֵל לוֹ \u0006 \u0005(טוּר)\u0006:\nאָמַר לָהּ: עַל מְנָת שֶׁלֹּא תִּנָּשֵׂא לְאַבָּא, וְנִשֵּׂאת לוֹ, הָוֵי גֵּט, שֶׁאֵין לוֹ בָּהּ נִשּׂוּאִין:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּנָּשְׂאִי לִפְלוֹנִי, אִם נִשֵּׂאת לוֹ, הֲרֵי זוֹ מְגֹרֶשֶׁת. אֲבָל אָמְרוּ חֲכָמִים: לֹא תִּנָּשֵׂא לוֹ, \u0010c23\u0011 שֶׁלֹּא יֹאמְרוּ נְשׁוֹתֵיהֶם נוֹתְנִים בְּמַתָּנָה זֶה לְזֶה. \u0005 הַגָּה: וַאֲפִלּוּ לֹא הִתְנָה עִמָּהּ בְּפֵרוּשׁ שֶׁתִּנָּשֵׂא לִפְלוֹנִי, אֶלָּא שֶׁנִּכָּר שֶׁגֵּרְשָׁהּ מִשּׁוּם זֶה, כְּגוֹן שֶׁאוֹתוֹ פְּלוֹנִי נָתַן לוֹ מָמוֹן כְּדֵי לְגָרְשָׁהּ וְהוּא מַעֲלֶה לָהּ מְזוֹנוֹת כְּדֵי שֶׁיִּקָּחֶנָּה, וְכָל כַּיּוֹצֵא בָּזֶה \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי בְּקִדּוּשִׁין)\u0006. וְאִם נִשֵּׂאת, לֹא תֵּצֵא. וְאִם נִשֵּׂאת לוֹ תְּחִלָּה, וְגֵרְשָׁהּ, מֻתֶּרֶת לַכֹּל, שֶׁהֲרֵי נִתְקַיֵּם הַתְּנַאי, \u0010c24\u0011 נִשֵּׂאת לְאַחֵר קֹדֶם שֶׁתִּנָּשֵׂא לְאוֹתוֹ פְּלוֹנִי, תֵּצֵא מִמֶּנּוּ, וְלֹא יַחֲזֹר עוֹלָמִית, וּצְרִיכָה מִמֶּנּוּ גֵּט. וְהַוָּלָד מִמֶּנּוּ מַמְזֵר. \u0005 הַגָּה: \u0010c25\u0011 נִשֵּׂאת אַחַר כָּךְ לְאוֹתוֹ פְּלוֹנִי שֶׁהִתְנָה עִמָּהּ הַבַּעַל, הָוֵי גֵּט לְמַפְרֵעַ וְאֵין הַבָּנִים מַמְזֵרִים \u0006 \u0005(טוּר)\u0006, \u0005 אֲבָל לֹא יַחֲזִירָהּ עוֹלָמִית מִשּׁוּם דְּהָוֵי כְּמַחֲזִיר גְּרוּשָׁתוֹ \u0006 \u0005(טוּר בְּשֵׁם הָרְמַ\"ה)\u0006. \u0010c26\u0011 \u0005 נִתְקַדְּשָׁה לְאַחֵר, תֵּצֵא וְלֹא תַּחֲזֹר לוֹ אֶלָּא אַחַר מִיתַת הַבַּעַל, אוֹ שֶׁיִּתֵּן לָהּ גֵּט אַחֵר בְּלֹא תְּנַאי \u0006 \u0005(ג\"ז שָׁם)\u0006:\nאָמַר לָהּ: עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לִפְלוֹנִי \u0010c27\u0011 עַד זְמַן פְּלוֹנִי, הֲרֵי זֶה גֵּט. וְיֵשׁ מִי שֶׁאוֹמֵר, \u0010c28\u0011 שֶׁלֹּא תִּנָּשֵׂא עַד שֶׁיָּמוּת אוֹתוֹ פְּלוֹנִי. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁמֻּתֶּרֶת לִנָּשֵׂא מִיָּד, כֵּיוָן שֶׁבְּיָדָהּ לְקַיְּמוֹ, שֶׁאִי אֶפְשָׁר לִנָּשֵׂא לוֹ אֶלָּא מִדַּעְתָּהּ. \u0010c29\u0011 וְאֵין תַּקָּנָה לְהַתִּירָהּ \u0005 לְאוֹתוֹ פְּלוֹנִי \u0006 אֶלָּא אִם כֵּן יְקַדְּשֶׁנָּהּ הַמְגָרֵשׁ וְיַחֲזֹר וִיגָּרְשֶׁנָּהּ סְתָם, \u0005 אוֹ שֶׁמֵּת הַבַּעַל קֹדֶם שֶׁנִּשֵּׂאת לְשׁוּם אָדָם \u0006 \u0005(בַּב\"י בְּשֵׁם הָרַשְׁבַּ\"ץ)\u0006. וְאִם נִשֵּׂאת לְאַחֵר, וְגֵרְשָׁהּ אוֹתוֹ הָאַחֵר, סְתָם, עֲדַיִן לֹא הֻתְּרָה לְאוֹתוֹ פְּלוֹנִי. \u0010c30\u0011 וְאִם נִשֵּׂאת לוֹ, נִתְבַּטֵּל הַגֵּט, וּבָנֶיהָ אַף מֵהַשֵּׁנִי מַמְזֵרִים:\nזִנְּתָה עִם אוֹתוֹ פְּלוֹנִי, הַוָּלָד כָּשֵׁר וְהַגֵּט כָּשֵׁר; שֶׁלֹּא הִתְנָה אֶלָּא עַל נִשּׂוּאִין:\nאָמַר לָהּ: עַל מְנָת שֶׁתִּבָּעֲלִי לִפְלוֹנִי, נִתְקַיֵּם הַתְּנַאי, שֶׁנִּבְעֲלָה לוֹ, בֵּין בִּזְנוּת בֵּין בְּנִשּׂוּאִין, הֲרֵי זֶה גֵּט. \u0010c31\u0011 וּלְכַתְּחִלָּה לֹא תִּבָּעֵל לוֹ, דְּהָא אֵינָהּ מְגֹרֶשֶׁת עַד שֶׁתִּבָּעֵל לוֹ, נִמְצֵאת תְּחִלַּת בִּיאָה בְּאִסוּר:\nעַל מְנָת שֶׁלֹּא תִּבָּעֲלִי לִפְלוֹנִי, הָוֵי גֵּט, וְלֹא תִּנָּשֵׂא עַד שֶׁיָּמוּת אוֹתוֹ פְּלוֹנִי, \u0010c32\u0011 דְּחַיְשִׁינָן שֶׁמָּא תִּבָּעֵל לוֹ בְּאֹנֶס:\nצָרִיךְ שֶׁלֹּא יַתְנֶה עָלֶיהָ תְּנַאי שֶׁעוֹמֶדֶת בּוֹ כָּל יָמֶיהָ, כְּגוֹן עַל מְנָת שֶׁלֹּא תֹּאכְלִי בָּשָׂר אוֹ שֶׁלֹּא תִּשְׁתִּי יַיִן לְעוֹלָם, אוֹ כָּל יְמֵי חַיַּיְכִי, שֶׁאִם הִתְנָה כָּךְ אֵין זֶה כְּרִיתֻת. אֲבָל אִם אָמַר לָהּ: כָּל יְמֵי חַיַּי, אוֹ כָּל יְמֵי חַיֵּי פְּלוֹנִי, אוֹ עַד חֲמִישִׁים שָׁנָה, הֲרֵי זֶה גֵּט. וְיֵשׁ מִי שֶׁכָּתַב, שֶׁאֲפִלּוּ הִרְחִיב הַזְּמַן יוֹתֵר מִכְּדֵי חַיֵּי הָאָדָם, כֵּיוָן שֶׁהוּא דָּבָר פָּסוּק, הֲרֵי זֶה גֵּט:\nאָמַר לָהּ: עַל מְנָת שֶׁלֹּא תֵּלְכִי לְבֵית אָבִיךְ \u0010c33\u0011 עַד זְמַן פְּלוֹנִי, אַף עַל פִּי שֶׁהַגֵּט כָּשֵׁר וְהַתְּנַאי קַיָּם, אֵין לְשׁוּם אָדָם לְהִשְׁתַּדֵּל בַּגֵּט שֶׁיִּנָּתֵן בִּתְנַאי זֶה, כִּי אִי אֶפְשָׁר לַעֲמֹד עַל נַפְשָׁהּ מִלֶּכֶת לְבֵית אָבִיהָ, וְנִמְצָא גֵּט בָּטֵל וּבָנֶיהָ מַמְזֵרִים. וְאִם הַמְגָרֵשׁ הוּא מֵאוֹתָם שֶׁכּוֹפִין לְהוֹצִיא, וְלֹא רָצָה לְגָרֵשׁ אֶלָּא בִּתְנַאי זֶה, כּוֹפִין אוֹתוֹ לְגָרֵשׁ בְּלֹא תְּנַאי זֶה:\nאָמַר לָהּ: עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לִפְלוֹנִי, וְלֹא קָבַע זְמַן, אֵינוֹ גֵּט, שֶׁאֵין זֶה כְּרִיתֻת; דּוֹמֶה לָאוֹמֵר: עַל מְנָת שֶׁלֹּא תִּשְׁתִּי יַיִן לְעוֹלָם, אוֹ כָּל יְמֵי חַיַּיְכִי. וְיֵשׁ אוֹמְרִים שֶׁכֵּיוָן שֶׁאֵין הַתְּנַאי נִמְשָׁךְ אֶלָּא כָּל יְמֵי חַיָּיו, הָוֵי לֵהּ כְּאוֹמֵר: עַל מְנָת שֶׁלֹּא תִּשְׁתִּי יַיִן כָּל יְמֵי חַיֵּי פְּלוֹנִי, שֶׁהִיא מְגֹרֶשֶׁת. וְנָקְטִינָן כְּדִבְרֵי שְׁנֵיהֶם, לְהַחֲמִיר:\nאָמַר לָהּ: עַל מְנָת שֶׁלֹּא תִּשְׁתִּי יַיִן זֶה לְעוֹלָם, אוֹ שֶׁלֹּא תַּעֲלִי בְּאִילָן זֶה אוֹ בְּכֹתֶל זֶה לְעוֹלָם, וְנִשְׁפַּךְ הַיַּיִן וְנִקְצַץ הָאִילָן וְנָפַל הַכֹּתֶל, אֵין זֶה כְּרִיתֻת, מֵאַחַר שֶׁלֹּא הֻתְּרָה לְעוֹלָם בַּמֶּה שֶׁנֶּאֱסֶרֶת. וְי\" א שֶׁכֵּיוָן שֶׁאֵין הַתְּנַאי נִמְשָׁךְ אֶלָּא כָּל זְמַן שֶׁהַיַּיִן קַיָּם אוֹ הָאִילָן אוֹ הַכֹּתֶל קַיָּמִים, הֲרֵי זֶה כְּרִיתֻת, וְנָקְטִינָן כְּדִבְרֵי שְׁנֵיהֶם, לְהַחֲמִיר:",[],["\u0003כשיתקיים התנאי תהיה מגורשת\u0004. ונראה בתנאי על מנת ג\"כ יכול לבטל התנאי שיחול הגט מיד וא\"צ ליטול הגט ממנה ובזה אין חילוק בין תנאי ע\"מ לתנאי אם אלא לענין אם רוצה לבטל הגט או להתנות תנאי אחר אז בע\"מ דהגט חל מיד א\"י ובתנאי אם דעדיין לא חל יכול לבטל אבל לבטל התנאי יכול לבטל בשניהם וא\"צ ליטול הגט ממנה ולא כב\"ח בסעיף כ\"ב שכתב בתנאי אם א\"י לבטל התנאי אא\"כ נוטל הגט ממנה וליתא ועיין ס\"ס קמ\"ד, ועיין ס\"ס קמ\"ב שם מבואר דין זה בתנאי באם אם יכול לבטל:","\u0003ואם נשאת תצא\u0004. הנה לדעת הר\"ן והמגיד והרשב\"ץ והב\"י כל זמן שלא נתקיים התנאי הוי כאלו אינה מגורשת לכן אם נשאת לאחר תצא אפילו אם הגט עדיין בעין והבעל קיים אפי' אם נתקיים התנאי אחר שנשאת מ\"מ הואיל ונשאת קודם הקיום הוי כזנת' ואסור' לבעל ולבועל אבל לדעת הרמב\"ם פ\"ח אם נשאת לא תצא אלא תתקיים התנאי אח\"כ אא\"כ אם מת הבעל או אבד הגט וכן משמע מטור דהביא דברי הרמב\"ם בסתם ולא השיג עליו וכן נראה שהיא דעת המחבר אף על גב בספרו הב\"י כתב כהר\"ן והמגיד מ\"מ כאן בש\"ע נוט' אחר דעת הרמב\"ם ולא כתב אם נשאת תצא אלא אחר הבבא אם מת הבעל או אבד ובזה דוקא תצא כמ\"ש ברמב\"ם משא\"כ אם הגט קיים והבעל קיים וכן מוכח בסי' קמ\"ח דפוסק כרמב\"ם ע\"ש וכן הוא דעת רמ\"א כמ\"ש בסי' ק\"כ בתנאי שיחתמו כולם והיינו נמי תנאי באם ולא תנאי ע\"מ ובחנם השיג שם הח\"מ על הרב רמ\"א כי כן ס\"ל להרמב\"ם והטור והמחבר:","\u0003ה\"א מגורשת מעכשיו או מהיום וכו'\u0004. עיין סי' ל\"ח להפוסקים דס\"ל בע\"מ צריך נמי להיות התנאי קודם למעשה צריך לומר התנאי בראשון קודם שיאמר ה\"א מגורשת:","\u0003בידה הוא בשב וא\"ת\u0004. הנה המבחר סתם ופסק כדעת הרמב\"ן והרשב\"א והר\"ן דאסורה להנשא שמא לא תתקיים התנאי אא\"כ תנאי שבידה והוא שב וא\"ת אבל לדעת הרמב\"ם כל שבידה הוא אפילו הוא בקום ועשה לא חיישינן שתעבור ומותרת להנשא והא דתניא בברייתא כמ\"ש ע\"מ שתתני לי מאתיים זוז וכו' לאחר לא תנשא כתב המגיד הרמב\"ם ס\"ל דנדחה ברייתא זו כי משמע בסוגי' פ' המגרש דמותרת להנשא, מיהו דבר שביד אחרים לא תנשא לפ\"ז לא היה צריך לומר דנדחה הברייתא אלא תנאי שתתן הוי כתנאי שאינו בידה שמא תפסיד כל אשר לה כמ\"ש ברש\"י ובתוס' ובטור או י\"ל מבריית' זו יליף נתינה בע\"כ פסול לא תנשא לכתחלה והיינו לפי לישנ' בתרא דרבא נתינה בע\"כ הוי נתינה וקשה למה תני' בברייתא ולאחר לא תנשא וא\"א לומר משום שמא לא תקיים התנאי הא מסוגי' פ' המגרש מוכח כל שבידה לקיים מותרת להנשא אלא נתינה בע\"כ הגט פסול מ\"ה אין בידה שהוא יקבל ברצון ועיין סוף סי' ל\"ח:","\u0003בטלו הגירושין\u0004. כל זה שפיר לשיטות הפוסקים דפסקו כרבנן בסעיף ח' אבל לי\"א שהביא בהג\"ה שם דפסקו כרשב\"ג אז הוי בכה\"ג נתקיים התנאי וע\"ש מ\"ש:","\u0003עד שתחלוץ\u0004. מלשון הרמב\"ם פ\"ח מ\"ש בדין זה ולא בטל הגט שהרי לא קבע זמן משמע לעול' הוי ספק גט וכ\"כ בטור בסעיף י\"ב וכ\"כ ב\"ח ולא כמשמעות בב\"י בסעיף ד' והמחב' השמיט דעת הטור דס\"ל אפי' לא קבע זמן כיון דא\"א לקיים התנאי הגט בטל אף על גב באומר ה\"ז גיטך אם לא באתי עד יב\"ח ומת תוך הזמן צריכה להמתין עד יב\"ח שם קבע זמן שאני והטור סעיף ד' כ' בשם הרמב\"ם באומר ע\"מ שתתן לאחר ל' יום ומת שתחלוץ ע\"כ ס\"ל כשאומר שתתן לאחר ל' יום לא הוי קבע זמן כי לאחר ל' יום אין זמן קבוע אימת שיתן רק שיתן אחר ל' יום, ול\"ד לאומר שהוא חייב לשלם אחר פסח אמרינן דחייב לשלם אחר פסח הראשון כמ\"ש בח\"ה סי' מ\"ב שם ע\"כ כוונתו לפסח הראשון דאל\"כ בטל השטר כמ\"ש שם להדיא אף על גב הרשב\"א ס\"ל שם לעולם אמרינן פסח ראשון קאמר אפי' היכ' דלא שייך לומר דיתבטל הדבר מ\"מ י\"ל הטור לא ס\"ל כן מ\"ה הבי' הטור דברי הרמב\"ם דס\"ל כשלא קבע זמן דחולצת על דין זה כשאומר שתתן אחר ל' יום משום דזהו ג\"כ טעם דלא קבע זמן ובזה ניחא קושי' ב\"ח על הטור ומ\"ש בדרישה דאיירי כשמת תוך ל' יום ע\"ז כתב הטור בשם הרמב\"ם דחולצת היינו אם רצונה להנש' תוך ל' יום צריכה חליצה הואיל עדיין לא נשלם הזמן ודבריו אינם מובנים לי חדא הלא גם הטור ס\"ל כשמת תוך יב\"ח צריכה להמתין עד אחר יב\"ח כיון דלא שלם לה הזמן עדיין גם איך אפשר להתייבם אותה תוך ל' יום הלא בל\"ז אסורה עד צ' יום והטור ס\"ל צ' יום מתחילין מיום הנתינה כמ\"ש בסי' י\"ג:","\u0003ה\"ז גט פסול\u0004. כ\"פ הרמב\"ם וס\"ל נתינה בע\"כ הוי נתינה ע\"פ הדין אלא בגט פסול ואם נשאת לא תצא ואפי' אם הוא אינו רוצה לקבל כלל כמ\"ש בב\"י בשם תשובת מורו וכן מדוייק הלשון והוא אינו רוצה לקבל עוד כתב בתשובה זו אם קיבל המעות אפילו בע\"כ לכ\"ע הוי נתינה ואין מוכרח וראיה שלו מתוספות שפיר דוחה המשיג עליו עיין שם, מיהו לדעת הרא\"ש ורשב\"א הוי ספק מגורשת וכל זה כשהיא נתנה המעות בפניו אבל שלא בפניו לא הוי נתינה כלל כמבואר בש\"ס וכשהוא אינו בכאן ונתנה ליד הב\"ד עיין בתשובת רשב\"א בב\"י בח\"ה ר\"ס ע\"ג ועיין בסמוך:","\u0003מחולים ליך\u0004. אפי' אם מת אחר כך ולא כהראב\"ד שם, ומשמע מכל הפוסקים דאין כאן ספק גט אלא הגט בטל בוודאי ולא מהני מחילה, ומה שכתב ב\"ח בשם רש\"י דהיא ספק מגורשת אין מוכרח די\"ל דכוונתו מספיקא דא\"י כוונתו אמרינן מסתמא כוונתו לצעורי והגט בטל בודאי:","\u0003ויש אומרים דה\"מ בשלא אמר וכו'\u0004. הנה בסמוך כ\"כ בפשיטות דמהני אם אומר דליהוי גט בלי שום תנאי ואפשר דס\"ל אבד שאני מיהו א\"י מי הוא החולק גם המגיד כתב בדין זה ובאבד מהני אם אמר ליהוי גט בלי תנאי וא\"צ ליטול הגט ממנה וליתן לה ולומר ליהוי גט בלי תנאי ול\"ד לאומר חוץ מפלו' כמ\"ש לעיל סי' קל\"ז ש\"ה הואיל וקנאתו לפסול מן הכהונה אף על גב בתנאי ע\"מ א\"י לבטל הגט או להוסיף על תנאי מ\"מ יכול לבטל התנאי כדי שיחול הגט כמ\"ש:","\u0003ויש מ\"ש\u0004. כ\"כ הרא\"ש אם הוא מרוצה לקבל המעות הוי גט וע\"כ צ\"ל רבנן ורשב\"ג פליגי כשאינו מרוצה א\"כ קשה הא מוכח נתינה בע\"כ לא הוי נתינה לרבנן דקי\"ל כוותיי' וכן הקשה בדרישה וב\"ח בשם מהרש\"ל ולא תירצו, וי\"ל נתינה בע\"כ היינו אם היה התנאי ליתן מעות ונתנה בע\"כ אבל ליתן מעות בעד הכלי וניתן בע\"כ לא אמרינן נתינה בע\"כ הוי נתינה לכן כתבתי בה' קידושין ר\"ס כ\"ז בשם מהרש\"ל וא\"ל מדאמרי רבנן איצטליתא דוקא קאמר ת\"ל אפילו אם לא היה אמרי' דוקא קאמר לא הוי נתינה בע\"כ אלא ודאי במעות הוי נתינה וקשה על הרא\"ש דס\"ל נתינה בע\"כ הוי ספק ודוחק לומר דה\"ק איצטלית' דוקא קאמר מ\"ה לא הוי נתינה כלל אבל אם היה מתנה על מעות הוי ספק ואפשר דס\"ל להרא\"ש נתינה ליד הב\"ד שלא בפניו הוי נתינה כשא\"י לנו דלא ניחא ליה ומותרת להנשא ולא כתשובות רשב\"א שהביא הב\"י בח\"ה ר\"ס ע\"ג לכן קאמרי רבנן איצטלית' דוקא קאמר מ\"ה לא הוי נתינה אפי' ליד הב\"ד שלא בפניו, ובתשו' רש\"ך ס\"ב סי' צ\"ט פסק ג\"כ בנתינה ביד הב\"ד הוי נתינה, ובאמת ראי' של הרשב\"א לכאורה תמוה דהבי' ראיה מדהלל תיקן ליתן המעות ללשכה ש\"מ בעלמא לא הוי נתינה ליד הב\"ד דשם גילה דעתו דלא ניחא ליה שאני אבל אם א\"י דעתו י\"ל דהוי נתינה, מיהו קשה לרבה דאמר שם הא לא אצטרך וקאמר דאתי' כרבנן אף על גב לרבנן דוקא איצטלית' קאמר משום לצעורי קמכוון ואיירי להרא\"ש בנתינה בע\"כ אם כן נשמע אפילו לא נתן אותו דבר שהתנה ונותן בע\"כ מכל מקום הוי נתינה לאו משום לצעורי קמכוון וכן קשה על דברי מהרי\"ט שהבאתי רסכ\"ז:","\u0003כמפרש יום א'\u0004. היינו בגיטין מסתמא לצעורי מכוון מ\"ה אמרי' דכוונתו רק יום א' אבל בעלמא אמרי' אם התנה ליתן מזונות או כיוצא בזה להנאתו מכוון כל ימי חייו קאמר כ\"כ הרשב\"א ועיין בר\"ן והמגיד ובח\"ה סי' ס':","\u0003וי\"א דצריכה לשמש וכו'\u0004. כתב הרא\"ש ראוי לפסוק כרבא דאמר דצריכה לשמש כל ימי חייו וכו' לחומרא ואם שמשה יום א' וקידש אחר חוששין לקידושיו ואם אמר ע\"מ שתשלם שכר הנקה לכ\"ע שכר ב' שנים קאמר:","\u0003ואם מתו לאחר שהתחילה לקיים\u0004. יום א' ל\"ד אפילו שעה א' ומתו די כמ\"ש בתו' ובר\"ן ובהמגיד ועיין בסמוך:","\u0003או מת אביו וכו'\u0004. לכאורה קשה הא הוי כדבר שאינו קובע זמן דהא בכל ימי חיי האב יכולה לשמשו יום א' א\"כ במת האב עדיין לא נשלם הזמן והוי כתנאי שתתן לו ר' זוז ומת דצריכה חליצה וכאן כתב אינו גט והיינו הגט בטל ומותרת ליבם וכן הקשה בדרישה ואפשר כיון שהוא התנה עמה תנאי זה א\"כ אחר שמת האב יכול לתובעה לקיים התנאי ואימת שתבעה מחויב' היא לקיים התנאי כמו הקובע ז\"פ לשלם אחר הפסח וכשתובעה והיא א\"י לקיים התנאי מיד הגט בטל אבל כשמתנה ע\"מ שתתן לו אין שום אדם יכול לתובעה דהא התנאי היה שתתן לו א\"כ א\"א שיבטל התנאי בפועל, לפ\"ז מ\"ש אינו גט היינו כשתובעה הוא אבל אם מת או חי ולא תבעה לא נתבטל בפועל וצריכה חליצה:","\u0003אינו גט\u0004. כן הוא דעת הרמב\"ם והרא\"ש אבל תוס' והרשב\"א ס\"ל אפילו אם מת קודם השימוש או קודם שתניק הוי גט ונראה דאזלינן לחומר':","\u0003או שאמר האב אין רצוני וכו'\u0004. כתב הרשב\"א אם לא קבע זמן לשמש את האב אלא אמר סתם שתשמש את אבי י\"ל בכה\"ג אפילו לרבנן דפליגי ארשב\"ג הוי גט כיון שאין העיכוב ממנה דהא לא נתן זמן להשימוש ש\"מ כוונתו להרווחת אביו ויש מחלוקת בזה בתוספת' ומשמע מרשב\"א אפי' לא שמשה לאביו כלל ואמר אין רצוני שתשמשני הוי גט והיינו לשיטתו דס\"ל כתוס' אם מת האב קודם שתשמש הוי גט י\"ל גם כאן אם אמר א\"א שתשמשני הוי גט אף על גב דלא נתקיים התנאי כלל אף על גב שם כתב בפשיטות דהוי גט וכאן כתב צ\"ע משום הכא הוא בחייו ועדיין יכולה לשמשו שם ג\"כ גרע טפי אבל לשיטות הפוסקים דקי\"ל כוותייהו אם מת האב ולא נתקיים התנאי לא הוי גט ולהרא\"ש צריכה לשמש כל ימי חייו והיינו והרווחת האב ומ\"מ ס\"ל אם מת לא הוי גט מוכח לרבנן אפי' אם אמר אי אפשי שתשמשני לא הוי גט דהא לא קבע זמן והעיכוב לא ממנה ומ\"מ הגט בטל א\"כ אפי' אם אמר א\"א מ\"מ לא נתקיים התנאי כלל, ואם שמשה יום א' ואמר א\"א י\"ל אף להרא\"ש מהני די\"ל בזה לא פליגו רבנן אלא מה דמשמע מרשב\"א באמר א\"א אפי' לא שמשה כלל הוי גט ול\"פ רבנן בזה מוכרח לשיטות הרא\"ש דלית':","\u0003וי\"א דכל שאין העיכוב וכו'\u0004. היינו בין אם אמר א\"א שתשמשני ובין אם מת כמ\"ש בתוס' ובטור אבל קודם שתניק לא הוי גט משום דלא נתקיים התנאי כלל גרע טפי כן הוא מדוייק בטור ע\"ש וי\"א אלו לא קאי על מ\"ש המחבר בסמוך מת הבן קודם שהניקו, והיינו לשיטת הפוסקים דס\"ל לרבנן אם התנה סתם הוי תנאי להרווחה מ\"מ אם מת קודם שתניק לא הוי גט כן הוא לרשב\"ג דס\"ל אפי' במפרש אמרי' להרווח' התנה א\"כ אם מת קודם שתניק או קודם שתשמש לאביו לא הוי גט אבל לשיטות שאר הפוסקים שהבאתי והרשב\"א בסמוך דס\"ל לרבנן בהתנה סתם אפי' אם מת קודם שתניק כלל הוי גט נראה לרשב\"ג אם מת או אמר א\"א שתשמשני וקודם שתניק הוי גט והקשה תוס' בתנאי אם תתן לי למה לא מהני מחילה או נתינה בע\"כ הא עכבה אינה ממנה ותירצו הכא ס\"ל רשב\"ג להרווחה התנה כיון שמת לא אצטרך הוי כאלו נתקיים התנאי אבל התם שתתני לי בדעתו שיקבלם ולבסוף כשאינו רוצה לקבלם לא נתקיים התנאי לפ\"ז צ\"ל הא דפליגי רבנן ורשב\"ג דף ע\"ג בתנאי אם תתני לי וס\"ל לרשב\"ג שתתן לאביו או לאחיו ולת\"ק א\"י לקיים התנאי משום רשב\"ג ס\"ל לי היינו לי או ליורשי א\"כ עדיין יכולה לקיים אף על גב הוא לא אצטרך מ\"מ התנאי היה ליתן לו או ליורשיו והת\"ק ס\"ל אף על גב דעכבה אינה ממנה מ\"מ לא הוי גט וקושי' של תו' זו ל\"ק אלא לשיטת' דס\"ל כל תנאי שהוא להרווח' כגון אם התנה סתם להניק אם מת קודם שתניק הוי גט כן הוא דרשב\"ג אפי' במפרש על ב' שנים ס\"ל להרווחה התנה ואם מת קודם שתניק הוי גט מ\"ה קשה ממחולי' לך או מנתינה בע\"כ אבל לשיטות שאר פוסקים י\"ל עד כאן לא קאמר רשב\"ג דהוי גט אלא בהתחילה לקיים ושם במחולי' לך לא נתקיים כלל והוי כמו מת קודם שתניק, מיהו נשמע מזה אם התנה ליתן לו מאה זוז ונתנה לו קצת והשאר אינו רוצה לא הוי גט לכ\"ע אף על גב במת הוי גט, גם נשמע מתוס' אם התנה ליתן לידו דוקא ולא ליורשיו ומת לשיטות תוס' לרשב\"ג הוי נתקיים התנאי כמו במת קודם שתניק, ולשאר פוסקים אפילו לרשב\"ג אם מת קודם שתניק לא הוי גט אא\"כ התחילה להניק כך הוא בתנאי שתתן לידו אם נתנה קצת מעות ומת הוי גט ולרבנן לא הוי גט דמסתמא לרבנן הוי תנאי ליתן מאה זוז כמו תנאי לשמש את אביו שתי שנים דאמרי' לצעורי קמכוון, ועיין סעיף ג':","\u0003ויש מי שאומר וכו'\u0004. משמע שחולק על מ\"ש אפי' שעה אחת ובאמת לא מצינו חולק בזה כמ\"ש בתוספות ובהר\"ן ובמגיד ומ\"ש הרמ\"ה דווקא כליל שבת ויומו היינו דוק' כשאומר לה שתשמש יום א' אבל אם אומר סתם מודה הרמ\"ה דסגי אפילו שעה א':","\u0003וחזר והתנה תנאי אחר\u0004. בר\"ס מבואר בתנאי באם יכול להתנות תנאי אחר אבל אם התנה תנאי ע\"מ א\"י להתנות תנאי אחר וצ\"ל דאיירי בתנאי באם וכ\"כ המגיד פ\"ח בתירוץ א' לפ\"ז לכאורה קשה מנ\"ל לרמ\"א די\"א היינו הר\"ן ס\"ל אפילו בתנאי באם מ\"מ התנאי שמתנה בשעה שנותן הגט הוא קיים מאחר דקי\"ל אפי' אחר נתינת הגט יכול להתנות תנאי אחר א\"כ לעולם תנאי האחרון קיים אפי' אם התנה אחר הנתינות הגט אלא הר\"ן איירי בתנאי ע\"מ אז א\"י להתנות תנאי אחר אם כבר נתן הגט לידה בתנאי ראשון ואפשר דס\"ל לרמ\"א לרמב\"ם מדכתב סתם איירי אפי' בתנאי ע\"מ ויכול להתנות תנאי אחר היינו כשנתרצו שניהם לתנאי אחר כמ\"ש במגיד שם לתירוץ השני ובפ\"ט דין ט' לרמב\"ם ולרמב\"ן כששניהם מתרצי' לבטל תנאי הראשון ולהתנות תנאי שני יכולים להתנות ובר\"ס איירי דבעל לבדו א\"י להתנות תנאי בתנאי ע\"מ וע\"ז כתב רמ\"א אפי' בריצון שניהם לא מהני אחר שנתן הגט לידה כמ\"ש בר\"ן בסוגיא וליחוש שמא פייס דכתב תנאי שאין לטובתה א\"י שניהם לבטל אפי' התרצו שניהם אלא אכתי קשה ממ\"ש בס\"ס ל\"ח בתנאי מעכשיו וכבר מסר הקידושין ומ\"מ פסק שם דיכולין להוסיף או לגרוע ודוחק לומר שאני להוסיף באותו תנאי היינו להאריך זמן כמ\"ש שם משא\"כ להתנות תנאי אחר לגמרי ועיין תשובות הרא\"ש כלל ל\"ה ואין לומר תנאי שבידה לקיים א\"י להתנות תנאי אחר כתנאי' שבכאן שהכל בידה משא\"כ התנאי' בסי' ל\"ח אין ביד' לקיים אז הקידושי' תלוים ועומדים אז יש בידו להוסיף או לגרוע וכן יש לדייק ממ\"ש בתשובות הרא\"ש שם וממ\"ש בכלל מ\"ו דף ע\"ח ע\"א דהא למ\"ש בשם תוס' אין בידה שמא תפסיד כל אשר לה גם הר\"ן כ\"כ על הסוגי' ושם תנאי הראשון הוא שתשמשי לאבא והוא תנאי שאין בידה ואפשר הטעם משום תנאי' לצעורי הוא כמ\"ש לקמן ועיין דינים אלו במגיד פ\"ט דין ט' ובסי' קמ\"ד יתבאר בס\"ד:","\u0003ואין א' מהראשונים וכו'\u0004. עיין מ\"ש בסי' קל\"ג בכל אסורים מצטרפין העדות אפילו בדיני אישות ושאני הכא דכל תנאי תנאי אחר הוא ופשוט בעיני וא\"י מ\"ש הרב רמ\"א בח\"ה סי' ל' עיין סי' קמ\"ג סעיף י' מה ענין דין זה לדינים דשם:","\u0003שאין זה כריתות\u0004. מאחר הנייר אין שלה נמצא האותיות פורחו' באויר ואם אמר הנייר בין שיטה לשיטה שלי והנייר מ\"מ מעורה דהוי ספר א' עלתה בתיקו והוי ספק גט והטור כתב אינה מגורשת ל\"ד בלישנא ואינו אלא ספק וכ\"כ בבדק הבית:","\u0003ותתן\u0004. והיינו להפוסקים דס\"ל בתנאי ע\"מ א\"צ ת\"כ ושאר דברים אז צריכה לקיים התנאי ותחזור לו הנייר אח\"כ אבל להפוסקים דס\"ל אפי' בעל מנת צריכים להיות כל התנאים שיהיה ת\"כ ושאר דברים צריך כאן ג\"כ להתנות בכל התנאים מיהו קשה הא הוי תנאי ומעשה בד\"א למה שהוכחתי בסי' ל\"ח אפי' כשאינו סותר התנאי למעשה מ\"מ הוי תנאי ומעשה בד\"א וע\"ש:","\u0003אין חוששין שמא נבעל' לו אפי' נתיחדה עמו\u0004. רשב\"א אף על גב דאין בידה כי יש לחוש שמא יבוא עליה באונס לא חיישינן שיעשה איסור גדול כזה והא דחיישינן בסעי' י\"ט שמא תבעל לאותו פלוני באונס אף על גב דאסורה לו משום א\"א צ\"ל שם חיישינן שמא יבוא עליה אחר מיתת המגרש ואז למפרע הגט בטל או שמא לא ידע אותו פלוני מתנאי כצ\"ל לדעת הפוסקים דהחשש הוא שם שמא יבוא עליה אותו פלוני אבל מדברי הר\"ן בשם הרמב\"ם נראה דס\"ל דלא חיישינן שמא יבו' עליה באונס דהא כתב דהיא נאמנת לומר שלא בא עליה אביו כיון שהתנאי בידי' הוא ובתנאי שלא נבעלה לפלוני כתב משום דהוי שיור בגט מ\"ה לא תנשא ולא משום חשש שיבוא עליה באונס:","\u0003שלא יאמרו וכו'\u0004. אבל מטעם דאסורה עליו משום א\"א עד שנתקיים התנאי כמ\"ש בסעיף י\"ח בע\"מ שתבעלי לפלוני דהא יכול' להנשא בחופה וקידושין ונתקיים התנאי וליכ' ביאת איסור ח\"ר ונשמע מזה אם גירש אחר החופה וקידושין קודם הביא' מותרת לכל דהא נתקיים התנאי:","\u0003נשאת לאחר וכו'\u0004. אף על גב בתנאי ע\"מ מותרת להנש' קודם קיום התנאי לדעת הרמב\"ם היינו בתנאי שבידה משא\"כ בתנאי כזה לכן הוי כזינתה ואסורה לזה:","\u0003נשאת אח\"כ לאותו פלו'\u0004. בתוס' מבואר אם נשא' לאחר מותרת לאותו פלו' אפי' לכתחילה ולא שייך לומר נשותיה' נותנים במתנה כיון דנשאת לאחר בינתים והטור כתב כל' הג\"ה נשאת אח\"כ היינו בדיעבד י\"ל דס\"ל תוס' כתבו כן למה דס\"ד דמותר' להנשא לאחר אז שפיר הטעם של תוס' שלא יאמרו נשותיה' נותנים במתנה אבל למה דקי\"ל אסורה לאחר ואם נשאת תצא אכתי שייך לומר נשותיה' נותנים במתנה לאחר מאחר דאסורה לכל חוץ מזה מיהו מראב\"ד יש לדייק דמותרת להנשא לזה כדי לתקן שאל יהיו הבנים מראשון ממזרים וכן שאל יהיו הנשואין של איסור וכל זה לשיטות תוס' ושאר פוסקים אבל לשיטות הרמב\"ם אין תקנה לדבר אפי' אם נשאת לאותו פלוני כי כוונת המגרש שתנשא לאותו פלוני קודם שתנשא לאחר לכן השמיט המחבר דין זה לחייש לדעת הרמב\"ם מיהו דעת הראב\"ד ושאר פוסקים ס\"ל דיש תקנה אם נשאת אח\"כ לאותו פלוני:","\u0003נתקדשה לאחר וכו'\u0004. דאז אין כאן איסור ביאה אלא דאסורה לו הואיל לא נתקיים התנאי מ\"ה אם מת הבעל או אם נותן גט אחר מותרת לו:","\u0003עד זמן פלוני\u0004. עיין סי' קל\"ז באומר על מנת שלא תנש' לפלוני לי\"א הוי שיור וליכא למימר בקוצב זמן ואומר שלא תנשא עד זמן פלוני לא הוי שיור ודין זה אתיא לכ\"ע דהא לשיטות הרמב\"ם איירי הסוגיא בקוצב זמן מטעם שאכתוב בסמוך מ\"מ אם אמר חוץ לפלוני הוי שיור ש\"מ אפי' בקוצב זמן הוי שיור לדידיה בחוץ כן הוא לשאר פוסקים באומר ע\"מ אפילו בקוצב זמן הוי שיור ודין דכאן לא אתיא אליבא די\"א שם והא דצריך לקצוב זמן היינו מטעם שכתב הרמב\"ם פ\"ח דאם לא נתן זמן הוי כאומר כל ימי חייכי דאין לדמות לאומר כל ימי חיי פלוני דשם עכ\"פ אחר מות פלוני היא מותרת באותו דבר משא\"כ כאן דאין מותרת בדבר זה ובסעיף כ\"ב הביא פלוגת' בזה:","\u0003שלא תנשא עד שימות\u0004. א\"כ לכאורה ר\"ל ר\"ת שכתב הרשב\"א בשמו כן ס\"ל שכל התנאי' אפילו מה שהוא בידה והוא שב וא\"ת אסורה להנשא עד שתתקיים התנאי כמ\"ש בר\"ן וכמ\"ש במגיד פ\"א שהביא די\"א כן, אבל לדעת הפוסקים שהכריע רס\"ז כמותם דבר שהוא בידה והוא שב וא\"ת מותרת להנש' אין חילוק בין שאר תנאים לתנאי זה לפ\"ז לא היה להמחבר להבי' דעת ר\"ת כאן וא\"י לחלק בין תנאי לשאר תנאי':","\u0003ואין תקנה להתירה\u0004. כיון שנתן לה גט כשר אין בידו להתירה אא\"כ יקדשנה כ\"כ הטור מזה נשמע דא\"י לבטל התנאי כלל אפילו כשנתרצו שניהם אלא קשה ממ\"ש הטור ס\"ס ל\"ח ולקמן בסי' זה, בשם תשובת הרא\"ש דיוכל לבטל התנאי ונראה דל\"ד למ\"ש ס\"ס ל\"ח דשם התנאי הוא אם יבוא תוך יב\"ח אינו בידו לקיים ועדיין לא חלו הקידושין, ומ\"ש סס\"ז התנאי היא אם לא יבוא המגרש תוך יב\"ח אף על גב התנאי הוא בשב וא\"ת ויש ביד המגרש לקיים מ\"מ היא אסורה להנשא כיון דאין בידה אלא ביד המגרש אז כל כה\"ג יש בידם לבטל אבל כאן גט גמור הוא ומותרת להנש' מיד כי התנאי בידה לקיים בשב וא\"ת לכן א\"י לבטל התנאי מיהו י\"ל הטור לטעמו דס\"ל בתנאי ע\"מ שתתן לי ר' זוז לא מהני מחילה אפילו באומר ליהוי גט בלי תנאי מ\"ה אפי' בתנאי זה אין תקנה שיאמר ליהוי גט בלא תנאי אבל לדעת הפוסקי' שהבי' בסי' ה' דמהני אם אמר ליהוי גט בלא תנאי י\"ל אף כאן מהני מיהו למ\"ש תנאי שתתן לא הוי בידה לקיים כי שמא תפסיד כל אשר לה י\"ל שם התנאי אין בידה מ\"ה יכול לבטל והא דלא מהני כשאומר מחולי' לך משום לצעורי קמכוון אבל כאן התנאי בידה והגט חל מיד אין בידה לבטל אפי' אם אומר ליהוי בידך בלא תנאי לפ\"ז י\"ל הטור ס\"ל בתנאי שתתן דמהני אם אומר ליהוי בידך בלא תנאי מיהו קשה למה כתב הטור בתנאי ע\"מ שתשמשי לאבא ב' שנים וחזר והתנ' ע\"מ שתתן ר' זוז דלא מסר הגט בתנאי הראשון דאל\"כ א\"י להתנות תנאי אחר למה א\"י להתנות תנאי אחר הא תנאי הראשון הוא תנאי דא\"י להנשא דהא קום ועשה הוא גם אין בידה ואפשר שם תנאי לצעורי הוא א\"י למחול התנאי ולהתנות תנאי אחר, והכלל הוא תנאי לצעורי א\"י למחול התנאי ותנאי שאינו לצעורי אם הוא תנאי שבידה ושב וא\"ת מותרת לישא לאחר וא\"י לבטל התנאי, וב\"ח מתרץ דתלי' הכל אם תנאי לצעורי הוא או לאו לצעורי ובס\"ס ל\"ח וסס\"ז הוא תנאי דלאו לצעורי הוא יכול לבטל אבל תנאי שלא תנש' לזה הוא תנאי לצעורי וכן תנאי שתשמשי לאבא הוא תנאי לצעורי לפ\"ז הטור שכתב כאן אין תקנה לדבר מוכח דס\"ל דלא מהני אם התנה שתתן ר' זוז אם אומר ליהוי בידך בלי תנאי דאל\"כ הא יש תקנה לומר ליהוי בידה וכו' אלא לשון הטור מ\"ש כאן לא משמע כדבריו:","\u0003ואם נשאת לו נתבטל הגט\u0004. משמע אפי' אם נשאת לו בחיי המגרש קאמר וקשה דהא לפי תנאי שלו נמצ' שהיא א\"א ולא הוי הנישואין נישואין א\"כ לא עברה על התנאי שלו שלא תנש' לפלוני וכתב המגיד טעם א' בשם הרמב\"ם דכוונתו שלא תנשא כדרך נישואין אלא לפ\"ז י\"ל בתנאי שלא תנש' לאבא ונשאת לו נמי הגט בטל והמחבר פסק בסעיף י\"ד דהוי גט משום דאין בה נישואין והיינו כשיטות תוספות שכתבו שם דאין נישואין בה ותוספות ס\"ל בתנאי ע\"מ שלא תנש' לפלוני נמי אין נישואין בה אלא דוק' כשנשאת לו אחר מיתת המגרש והרמב\"ם דפוסק כאן דנתבטל הגט ומשמע אפי' בחיי המגרש ס\"ל שם נמי נתבטל הגט כי דין הנ\"ל ע\"מ שלא תנש' לאבא ליתא מפורש בש\"ס ומ\"ש הב\"י דכן אית' בתוספתא ליתא כי מ\"ש בתוספתא ע\"מ שלא תנש' לאביך ה\"ז גט איירי שלא נשאת לו אלא דלא חיישינן שמא ישא אותה משא\"כ בתנאי שלא תבעל לאבא חיישינן שמא יבעל אותה אלא תוס' דייקא דין זה וע\"ש, והמחבר פסק כאן נתבטל הגט ומשמע אפי' בחיי המגרש ובסעיף י\"ד פסק אם נשאת לאב הוי גט צ\"ל דס\"ל כאן י\"ל ממ\"נ אם לא הוי נישואין ע\"כ צ\"ל הגט בטל והיא א\"א דאל\"כ הא הוי נשואין ועברה התנאי א\"כ לעולם אתה מוכרח לומר הגט בטל משא\"כ בנישואי אבי' אין שייך נישואי' מצד האיסור ולא מחמת התנאי ומכל הני פוסקים מבואר דס\"ל אם עברה התנאי אפילו אחר מיתת המגרש הגט בטל ולא כדעת ה\"ג דס\"ל אחר מיתת המגרש אין הגט בטל:","\u0003ולכתחלה לא תבעל וכו'\u0004. אף כאן שייך הטעם שלא יאמרו נשותיהם נותנים במתנה וכ\"כ המגיד בשם הירושלמי ואפשר משום חשש איסור שכתב המחבר הוא יותר חמור שהוא איסור א\"א לכן כתב טעם זה ובתנאי שתנש' לפלוני לא שייך זה כמ\"ש שם:","\u0003דחיישינן שמא תבעל באונס\u0004. כבר כתבתי החשש הוא שמא תבעל אחר מיתת המגרש לכן חיישינן כאן טפי מחשש שמא יבוא עליה אביה באונס:","\u0003עד זמן פלוני\u0004. כן הוא לדעת הרמב\"ם ולדעת שאר פוסקים אלא לדעת הרמב\"ם אם לא קצב זמן לא הוי תנאי אף על גב אם ימות האב מותרת לילך לאותו בית מ\"מ אין היתר לבית אביה דתו לא נקרא בית אביה נמצא אין היתר לאותו דבר שאסר עליה וכ\"כ לעיל בתנאי שלא תנשא לפלוני וכן ס\"ל בכל אלו תנאים ולשיטות תוספות והרא\"ש אם לא קצב זמן הוי תנאי לעולם משום אפילו אחר מיתת אביה לא הותר ועיין בי\"ד סי' רט\"ז ותוס' גיטין ובערובין דף ט\"ו כתבו יוצאי יריכו בכלל בית אב והוי כאלו אמר לעולם:"]],["\u0010y0\u0011 אָמַר לָהּ: \u0010c0\u0011 הֲרֵי זֶה גִּטֵּךְ אִם לֹא אָבֹא בְּתוֹךְ שְׁלשִׁים יוֹם, אוֹ שֶׁאָמַר: עַל מְנָת שֶׁלֹּא אָבֹא בְּתוֹךְ ל' יוֹם, וְהָיָה בָּא בַּדֶּרֶךְ בְּתוֹךְ ל' יוֹם, וְחָלָה אוֹ עִכְּבוֹ נָהָר וְלֹא בָּא עַד אַחַר ל' יוֹם, הֲרֵי זֶה גֵּט, אֲפִלּוּ עוֹמֵד וְצוֹוֵחַ: הֲרֵינִי אָנוּס, שֶׁאֵין אֹנֶס בְּגִטִּין. וְאַף עַל פִּי שֶׁגִּלָּה דַּעְתּוֹ שֶׁאֵין רְצוֹנוֹ לְגָרֵשׁ, כֵּיוָן שֶׁלֹּא הִתְנָה חוּץ מֵאִם יִקְרָאֶנִי אֹנֶס. אֲבָל \u0010c1\u0011 אֹנֶס דְּלָא שָׁכִיחַ כְּלָל, כְּגוֹן אֲכָלוֹ אֲרִי אוֹ הִכִּישׁוֹ נָחָשׁ אוֹ נָפַל הַבַּיִת עָלָיו, לֹא אַסִיק אַדַּעְתֵּהּ לְהַתְנוֹת עָלָיו, וּמְבַטֵּל הַגֵּט וְהִיא זְקוּקָה לְיָבָם. \u0010c2\u0011 \u0005 וְשִׁבְיָה, הֲוֵי אֹנֶס \u0006 \u0005 דְּשָׁכִיחַ, וְאֵינוֹ מְבַטֵּל הַגֵּט מִדְּלֹא הִתְנָה \u0006 \u0005(מָרְדְּכַי פֶּרֶק מִי שֶׁאֲחָזוֹ)\u0006:\nהֲרֵי זֶה גִּטֵּךְ אִם לֹא בָּאתִי מִכָּאן עַד שְׁנֵים עָשָׂר חֹדֶשׁ, וְלֹא אָמַר: מֵעַכְשָׁו וְלֹא עַל מְנָת, וּמֵת בְּתוֹךְ שְׁנֵים עָשָׂר חֹדֶשׁ, \u0010c3\u0011 הֲרֵי זֶה סָפֵק, וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nהֲרֵי זֶה גִּטֵּךְ מֵעַכְשָׁו, אִם לֹא בָּאתִי מִכָּאן עַד שְׁנֵים עָשָׂר חֹדֶשׁ, וּמֵת בְּתוֹךְ שְׁנֵים עָשָׂר חֹדֶשׁ הֲרֵי זוֹ מְגֹרֶשֶׁת. אֲבָל אִם יֵשׁ לָהּ יָבָם, \u0010c4\u0011 לֹא תִּנָּשֵׂא בְּלֹא חֲלִיצָה עַד שֶׁיַּעַבְרוּ שְׁנֵים עָשָׂר חֹדֶשׁ; וְאִם נִשֵּׂאת, לֹא תֵּצֵא:\nנָתַן לָהּ גֵּט בַּלַּיְלָה וְאָמַר לָהּ: הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁתֵּצֵא חַמָּה מִנַּרְתֵּקָהּ, וּמֵת בַּלַּיְלָה, הֲרֵי זֶה גֵּט. אֲבָל אִם אָמַר לָה אִם תֵּצֵא מִנַרְתֵּקָה אוֹ שֶׁאָמַר לִכְשְׁתֵּצֵא חֲמָה מִנַרְתֵּקָה וּמֵת בַּלֵילָה \u0010c5\u0011 הֲרֵי זֶה סָפֵק. \u0010c6\u0011 וְי\" א דְּאַף בְּעַל מְנָת נָקְטִינָן לְחֻמְרָא, אֶלָּא אִם כֵּן אָמַר: מֵעַכְשָׁו, בְּהֶדְיָא:\nאָמַר: אִם לֹא בָּאתִי עַד שְׁנֵים עָשָׂר חֹדֶשׁ כִּתְבוּ גֵּט וּתְנוּ לְאִשְׁתִּי, אוֹ שֶׁאָמַר: כִּתְבוּ גֵּט וּתְנוּ לְאִשְׁתִּי אִם לֹא בָּאתִי עַד י\"ב חֹדֶשׁ, אֵין כּוֹתְבִין תּוֹךְ י\"ב חֹדֶשׁ, אֲפִלּוּ אִם לֹא יִרְצוּ לִתְּנוֹ עַד אַחַר י\"ב חֹדֶשׁ. וְאִם כְּתָבוּהוּ בְּתוֹךְ י\"ב חֹדֶשׁ, אַף עַל פִּי שֶׁנְּתָנוּהוּ לָהּ לְאַחַר י\"ב חֹדֶשׁ, אֵינוֹ גֵּט. כָּתְבוּ וְנָתְנוּ לָהּ לְאַחַר י\"ב חֹדֶשׁ, וּמֵת, אִם מִיתָה קָדְמָה לִנְתִינַת הַגֵּט, \u0010c7\u0011 אֵינוֹ גֵּט. \u0005 וְאִם גֵּט קוֹדֵם לַמִּיתָה, הָוֵי גֵּט \u0006 \u0005(טוּר)\u0006. וְאִם הוּא סָפֵק אֵיזֶה מֵהֶם קוֹדֵם, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. \u0005 הַגָּה: לֹא נָתְנוּ לָהּ מִיָּד אַחַר י\"ב חֹדֶשׁ, אֶלָּא זְמַן רַב אַחַר כָּךְ, אַף עַל פִּי שֶׁהָעִכּוּב הָיָה מִצַּד הָאִשָּׁה שֶׁלֹּא רָצְתָה לְקַבְּלוֹ מִיָּד, \u0010c8\u0011 אֲפִלּוּ הָכִי הָוֵי גֵּט, וּבִלְבַד שֶׁיִּהְיֶה הַבַּעַל חַי \u0006 \u0005(עַיֵּן בְּב\"י)\u0006:\nאָמַר: כִּתְבוּ וּתְנוּ גֵּט לְאִשְׁתִּי אַחַר הַשָּׁבוּעַ, אֵין \u0010c9\u0011 כּוֹתְבִין אֶלָּא עַד שָׁנָה מֵאַחַר הַשָּׁבוּעַ. אָמַר: לְאַחַר שָׁנָה, כּוֹתְבִין עַד לְאַחַר חֹדֶשׁ מִשָּׁנָה שְׁנִיָּה. אָמַר: לְאַחַר הַחֹדֶשׁ, כּוֹתְבִין עַד לְאַחַר שַׁבָּת מֵחֹדֶשׁ שֵׁנִי. אָמַר: לְאַחַר שַׁבָּת, כּוֹתְבִין עַד סוֹף יוֹם שְׁלִישִׁי. אָמַר: כִּתְבוּ וּתְנוּ לָהּ קֹדֶם הַשַּׁבָּת, כּוֹתְבִין מִיּוֹם רְבִיעִי עַד סוֹף יוֹם שִׁשִּׁי, וְנוֹתְנִים לָהּ. הֲרֵי שֶׁאֵחֲרוּ אַחַר הַזְּמַן שֶׁאָמַר, וְאַחַר כָּךְ כָּתְבוּ וְנָתְנוּ לָהּ, הֲרֵי זוֹ \u0010c10\u0011 סְפֵק מְגֹרֶשֶׁת. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּאִם אָמַר: אַחַר י\"ב חֹדֶשׁ, כְּאִלּוּ אָמַר: אַחַר שָׁנָה. אָמַר: לְאַחַר שְׁלשִׁים יוֹם, כּוֹתְבִין יוֹם אֶחָד אַחַר שְׁלשִׁים יוֹם \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פ' מִי שֶׁאָחֲזוֹ)\u0006:\nהִתְנָה עָלֶיהָ שֶׁתִּתְגָּרֵשׁ \u0010c11\u0011 כְּשֶׁיַּעֲבֹר מִנֶּגֶד פָּנֶיהָ ל' יוֹם, וְהָיָה הוֹלֵךְ וּבָא הוֹלֵךְ וּבָא, וְלֹא נִתְיַחֵד עִמָּהּ, כְּשֶׁיֵּלֵךְ וְיִשְׁהֶה ל' יוֹם, תִּהְיֶה מְגֹרֶשֶׁת; וְאַף עַל פִּי שֶׁהָיָה הוֹלֵךְ וּבָא בְּתוֹךְ ל' יוֹם, \u0010c12\u0011 הוֹאִיל וְלֹא נִתְיַחֵד עִמָּהּ, הֲרֵי זֶה גֵּט כָּשֵׁר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהִתְנָה וְאָמַר: \u0010c13\u0011 הֲרֵי הִיא נֶאֱמֶנֶת עָלַי שֶׁלֹּא פִּיַּסְתִּיהָ. אֲבָל אִם לֹא הֶאֱמִינָהּ, חוֹשְׁשִׁין שֶׁמָּא פִּיְּסָהּ כְּשֶׁהָיָה הוֹלֵךְ וּבָא, וּמָחֲלָה לוֹ, \u0010c14\u0011 וְחָזַר וּבִטֵּל הַגֵּט כְּשֶׁפִּיְּסָהּ, וּמִפְּנֵי חֲשָׁשׁ זֶה יִהְיֶה הַגֵּט פָּסוּל. וְכֵן הָאוֹמֵר לְאִשָּׁה: הֲרֵי זֶה גִּטֵּךְ לְאַחַר י\"ב חֹדֶשׁ, וְהָיָה עִמָּהּ בַּמְּדִינָה, דְחוֹשְׁשִׁין שֶׁמָּא פִּיְּסָהּ, עַד שֶׁיֹאמַר: נֶאֱמֶנֶת עָלַי שֶׁלֹּא פִּיַּסְתִּיהָ. וְכֵן כָּל הַתְּנָאִים שֶׁהֵם תְּלוּיִם בִּרְצוֹנָהּ. וְאִם רָצְתָה וּמָחֲלָה אוֹתָן לְבַעְלָהּ בָּטֵל הַגֵּט, דְּחוֹשְׁשִׁין לָהּ שֶׁמָּא פִּיֵּס, עַד שֶׁיֹּאמַר: נֶאֱמֶנֶת עָלַי. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמִתְגָּרֶשֶׁת מִן הַנִּשּׂוּאִין, שֶׁלִּבּוֹ גַּס בָּהּ. אֲבָל בְּמִתְגָּרֶשֶׁת מִן הָאֵרוּסִין, אֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא פִּיֵּס. הֲרֵי זֶה גִּטֵּךְ מֵעַכְשָׁו, אִם לֹא בָּאתִי מִכָּאן וְעַד י\"ב חֹדֶשׁ, אֵין חוֹשְׁשִׁין שֶׁמָּא בַּסֵתֶר בָּא, שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לָבֹא בְּצִנְעָא. וְאִם תַּם הַזְּמַן שֶׁקָּבַע, וְלֹא בָּא, הֲרֵי זוֹ מְגֹרֶשֶׁת. וְיֵשׁ אוֹמְרִים שֶׁאַף בְּזוֹ חוֹשְׁשִׁין שֶׁמָּא בַּסֵתֶר בָּא, אֶלָּא אִם כֵּן הִתְנָה בִּתְחִלָּה וְאָמַר: נֶאֱמֶנֶת עָלַי לוֹמַר שֶׁלֹּא בָּאתִי. וְרָאוּי לָחוּשׁ לְדִבְרֵיהֶם לְכַתְּחִלָּה, וְכֵן הַמִּנְהָג לְהַתְנוֹת בִּתְחִלָּה שֶׁתְּהֵא נֶאֱמֶנֶת לוֹמַר שֶׁלֹּא פִּיֵּס. וְאִם כְּשֶׁהִתְנָה תָּלָה בִּיאָתוֹ בְּעֵדִים, שֶׁלֹּא יִתְבַּטֵּל הַגֵּט בְּבוֹאוֹ אֶלָּא אִם כֵּן יָעִידוּ עָלָיו עֵדִים שֶׁבָּא, וְעָבַר הַזְּמַן וְאֵין מְעִידִים שֶׁבָּא, לְדִבְרֵי הַכֹּל אֵין חוֹשְׁשִׁין שֶׁמָּא בָּא, אַף עַל פִּי שֶׁלֹּא הֶאֱמִינָהּ:",["\u0003תשובה מן הרב המחבר א\"א מ\"ו ז\"ל להאלוף המרומם התורני הרב המופל' מהר\"ר הירש סג\"ל נקרא בשם טוב ר' הירש ר' מאירש מק\"ק ווילנא\u0004. על קושייתו שהקשה לו וזה לשונו מה שהקשה מעלתך לשאול מה שפסק הרב מהרמ\"א בא\"ע סי' קמ\"ד שביה הוי אונס דשכיח נ\"ב שהועתק מדברי המרדכי פ' מי שאחזו ולא די שדבריו סותרין דברי המרדכי ששם כתוב בדף תרי\"ג ע\"א דהוי אונס' דלא שכיח וראיה ברורה מר\"פ השואל דף צ\"ד תאמר בשבוי' דאונסא דלא סליק אדעת' הוא אלא שדברי הרב סותרים זה את זה דהא בח\"מ סי' קט\"ו סעיף מ\"ח בהג\"ה מי שנתפס בדרך אונס דלא שכיח והוא מועתק מדברי אגודה פ' מי שאחזו הנה אהו' נראה שדברי הרב מהרמ\"א כנים הם באשר ידוע למעלתך שפסקו הפוסקים כלישנ' קמא דכתובות דף ב' ע\"ב דאע\"פ שבממון יש טענת אונס דלא שכיח אבל בגיטין אין אונס אפי' לא שכיח אם לא שאינו שכיח כלל כגון אכלו ארי או נשכו נחש אבל אונס דשביה ותפיסה ודאי אף שאינו שכיח מ\"מ שכיח קצת ואיכא למיחש ביה משום צניעות ופריצות כדאית' שם בגמר' וכן ראיתי בהג\"ה אלפסי לשון ריא\"ז בין שחלה בין שנחבש בבית האסורין וכו' אינו יכול לבטל גטו משום טענת אונס וא\"כ יפה פסק הרב בממון דתפיסה ושביה לא שכיח כפשט הגמר' דר\"פ השואל אבל בגיטין אין אונס אף דלא שכיח כל זמן שאינו דומה לאכלו ארי וכמו שפסק בהגהות אלפסי ומכ\"ש למאן דמחלק דאכלו ארי הוי בידי שמים ע\"כ יש אונס ושביה הוי בידי אדם ע\"כ אין אונס ודי בזה לחכם כמעלתך ע\"כ:"],["\u0003ה\"ז גיטיך\u0004. אף על גב אונס מהני בכל התורה כאן בגט תקנו חז\"ל דאין אונס בגיטין משום צניעות ומשום פריצות וכל המקדש ע\"ד דרבנן הוא מקדש ואפקוה חז\"ל הקידושין כן איתא בש\"ס ותנאי שמתנ' הוא לטובתו מה שהיא תעשה לא מהני טענות אונס כי הוא לא התרצ' ליתן הגט כי אם בתנאי שתעשה את זאת, ונראה אחר תקנות ר\"ג דאין מגרשי' בעל כרחה והיא התנה מה שהוא יעשה לא מהני טענות אונס אפי' אונס דלא שכיח כלל מטעם הנ\"ל ועיין תשו' הרא\"ש כלל מ\"ה ועיין ב\"ח ועיין סי' מ\"ב:","\u0003דלא שכיח כלל\u0004. משמע דאין חילוק בין אונס בידי שמים לבין אונס בידי אדם וכל שהוא אונס דלא שכיח בטל הגט ולא כדע' המקצעות דמחלק בין אונסי' הנ\"ל:","\u0003ושביה הוי אונס דשכיח\u0004. כלומר אונס דשכיח ולא שכיח הוא לכן בגיטין לא הוי אונס אבל בממון הוי אונס כמ\"ש בח\"ה סי' קע\"ו וכ\"כ ב\"מ:","\u0003ה\"ז ספק\u0004. אם אמרינן זמן של שטר מוכיח והוי כאלו אמר מעכשיו ורבו בזה הדיעות כמ\"ש בטור ובהר\"ן ובמגיד וק\"ל בגט הוי ספק בין אם התנאי נכתב בגט ובין בתנאי בע\"פ אף על גב דקי\"ל בממון זמן של שטר מוכיח מ\"מ בגיטין אזלינן לחומרא ועיין בח\"ה סי' רנ\"ח בטור ובהג\"ה ש\"ע שכתב שם בשם הרמ\"ה אם כתב לו לאחר ל' יום לא אמרי' זמן של שטר מוכיח דהא צריך לכתוב הזמן כדי שיודעים אימת כלין ל' יום לפ\"ז לכאור' קשה למה פסק כאן הרמ\"ה דהיא ספק גט דהא ע\"כ צריך לכתוב הזמן לידע אימת כלין יב\"ח גם קשה מהא דאיתא ס\"פ מ\"ש רבותינו התירו באומ' אם לא באתי עד יב\"ח ומת תוך יב\"ח ואוקמי שם משום דס\"ל כר\"י דאמ' זמן של שטר מוכיח ש\"מ דס\"ל אפי' בקוצב זמן אמרי' זמן של שטר מוכיח וצ\"ל ר' יוסי ע\"כ ס\"ל אם קוצב זמן לא אמרי' זמן של שטר מוכיח דהא לא פליג אלא באומר מהיום ולאחר מיתה אבל לא פליג באומר אם לא באתי מכאן עד יב\"ח ש\"מ דס\"ל קוצב זמן לא אמרי' זמן של שטר מוכיח, אבל רבותינו ס\"ל כר' יוסי והתירו אפי' בקוצב זמן וכעין זה כתב המגיד ספ\"א ואנן קי\"ל כר\"י משום רב פסק כוותי' והיינו באומר מהיום ולאחר מיתה אבל בקוצב זמן ס\"ל לר\"י דלא אמרי' זמן של שטר מוכיח ולרבותינו אמרי' אפי' בקוצב זמן זמן של שטר מוכיח ואיתא שם ר\"א הורה ולא הורה כל שעתו /ולא הודו כל סיעתו/ לכן פסק הרמ\"ה במתנה אוקמי ממון בחזקת הנותן ובניו וכאן בגיטין פסק לחומרא ולכאורה קשה ממ\"ש בפ' המגרש (גיטין דף פ\"ה) מיומא דנן לאפוקי דר' יוסי דאמר זמן ש\"ש מוכיח ותקנו לכתוב בפירוש מיומא דנן ולא לסמוך על זמן שטר מבואר מ\"ש מיומא הוי כאלו נכתב מעכשיו א\"כ בגיטין שלנו אין ספק כלל דהא כותבי' מיומא דנן ובמגיד פ\"ט דין ה' ובב\"י סי' קמ\"ה כתבו בשם העיטור יומא דנן להוי כאלו היה נכתב מעכשיו א\"כ תימא על הפוסקים שלא כתבו חילוק זה וכן המחבר כתב בסי' קמ\"ג בשם י\"א אפי' לא אמר מעכשיו דינו כאומר מהיום מחמת זמן השטר ולא כתב הטעם מדכותבים מיומא דנן שוב ראיתי בחדושי רש\"ל שהקשה ג\"כ כהנ\"ל:","\u0003לא תנשא\u0004. היינו הבעי' בש\"ס ולא אפשט ולדעת תוס' והרא\"ש הטעם משום דגזרי' מת אטו לא מת והרמב\"ם למד מכאן כל זמן שלא נתבטל התנאי בפועל צריכה חליצה כמ\"ש בסי' קמ\"ג בתנאי אם תתן לי ולא קבע זמן וי\"ל גם להרמב\"ם אם נשאת לא תצא אלא ממ\"ש הטור בסי' קמ\"ג סעיף י\"ב שם בדין הנ\"ל בשם הרמב\"ם דס\"ל דהיא ספק מגורשת משמע אם נשאת תצא וכן י\"ל להטעם שכתב הר\"ן דבעי' זו דהא לא חייש אלא לגרש דוקא אחר יב\"ח נראה אם נשאת תצא דהוי ספק א\"ד משא\"כ לטעם שכתבו תוס' והרא\"ש משום גזירה דרבנן מת אטו לא מת מ\"ה לא תצא:","\u0003ה\"ז ספק\u0004. כלומר באומר אם תצא הספק הוא שמא הלכה כר\"י דאמר זמן ש\"ש מוכיח והוי גט מעלי' או שמא אין הלכה כר\"י וכשאומר לכשתצא אז אם הלכה כר\"י הוי ספק כמו אם אמר מהיום ולאחר מיתה ולמ\"ש ר\"ס קמ\"ה באומר היום ומת בו ביום יש לספק שמא סוף היום קאמר א\"כ יש כאן ג' ספיקות שמא הלכה כר\"י והוי כאומר מהיום ולאחר מיתה וי\"ל שמא תנאי הוא ושמא מעכשיו קאמר וע\"מ עדיף מאומר היום כי ע\"מ הוי כאומר מעכשיו מיהו הר\"ן כתב בכה\"ג עדיף כשאומר מהיום כיון שאמר אם תצא או לכשתצא ע\"כ לאו לסוף היום מתכוון אז אמרי' מעכשיו קאמר כיון דליכא למימר סוף יום א\"כ אין זמן מוגבל אלא מעכשיו קאמר:","\u0003וי\"א וכו'\u0004. כ\"כ בבדק הבית להפוסקים דלא ס\"ל ע\"מ כמעכשיו דמי אף בע\"מ יש להחמיר וא\"י למה השמיט דיעה זו בר\"ס קמ\"ג ולא בשום מקום הביא המחבר דיעה זו אלא כאן:","\u0003אינו גט\u0004. כלומר הגט בטל הואיל שעברו על תנאי שלו שלא יכתבו תוך יב\"ח אף על גב דלא התנה בדין תנאי מ\"מ כל מה שצו' לשלוחו א\"י לעבור אפי' שלא התנה כדין תנאי כ\"כ ב\"ח בשם הרשב\"א והר\"ן אבל משום העכוב בין הכתיבה להנתינ' אינו אלא פסול כמ\"ש בסי' קכ\"ז א\"נ דאיירי דכתבו הזמן אחר יב\"ח ונתנו באותו פעם אז אם לא היו עברו התנאי היה הגט כשר אלא מחמת שעברו על תנאי שלו הגט בטל:","\u0003אפ\"ה הוי גט\u0004. אף על גב בסמוך כתב הרי שאחרו זמן הרי זו ספק מגורשת ש\"ה דהגביל זמן אימת שיכתבו בגט אבל כאן לא היה כוונתו אלא שלא יכתב קודם יב\"ח ואחר יב\"ח אין זמן לדבר:","\u0003שנה מאחר השבוע\u0004. כלומר כותבים כל השנה אחר השבוע ולא אחר כך וכן אחר השנה כותבין כל החודש אחר השנה וכן בכלם כ\"כ הטור והר\"ן והמגיד אליבא דהרמב\"ם ואם אמר אם לא באתי לאחר השבוע כתבו ותנו לא יכתבו עד שיעבור השבוע ושנה הראשונה של שמיטה אחרת וכן בכולם ואם אחרוהו יותר אין קפידא כמ\"ש בסמוך כן הוא לשיטות הרא\"ש וגם הרמב\"ם ל\"פ ע\"ז דהא ס\"ל שנה של שמטה אחרת נכלל בכלל אחר השבוע ולר\"ת אם אמר זה גיטך אחר השבוע אינו גט עד שיעבור שנה הראשונה שבשמינית וחדש הראשון של שנה שניה וכן בכולם ואפשר דס\"ל אחר השבוע הוא שנה הראשונה אמרי' שמא לסוף השנה קאמר, ואם אמר אחר הרגל עיין בר\"ן שרבו בזה הדיעות ועיין בח\"ג ועיין בת\"ה ס\"ס מ\"ד ואם אמר לפני שנה וחדש לא אתפרש דינו ע\"ש בר\"ן:","\u0003ספק מגורשת\u0004. הרמב\"ם כתב הרי זה פסול אלא הר\"ן הקשה עליו למה פסול ואם נשאת לא תצא כמ\"ש בפ\"י הרי מידי ספקא לא נפיק ואם נשאת תצא לכן כ' הרי זו ספק מגורשת ובכ\"מ תירץ קושיא שלו וכ' טעמא של הרמב\"ם אף על גב דאיחר מ\"מ אחר שבוע הוא וכן כולם וכאן לא סמך על תירוצו ומ\"ש הרמב\"ם שם פ\"ט דין ל\"ג ואיתא בסי' קמ\"א סעיף מ\"ח באומר תנהו לה ביום פלוני אם הקדים אינו גט צ\"ל דוקא בהקדים אינו גט אבל אם איחר אינו בטל הגט אלא פסול ולהמחבר ספק הוא ולא כב\"ח שכתב שם דיכול לאחר:","\u0003כשיעבור מנגד פניה\u0004. רבי יוחנן דתניא כוותי' התנאי הוא כשלא יראה אותה שלשים יום אף על גב אחר נתינות הגט הלך ובא וראה אותה מ\"מ אם הלך אחר כך ולא חזר שלשים יום נתקיים התנאי וע\"כ מ\"ש הרמב\"ם היינו לשון המחבר אף על פי שהיה הולך ובא תוך שלשים יום וכו' היינו תוך ל' יום מנתינת הגט אבל תוך שלשים יום שהתנה לא בא:","\u0003הואיל ולא נתייחד עמה ה\"ז גט כשר\u0004. משמע אם היה נתייחד עמה אף על פי שנתן לה נאמנות כשתאמר שלא בא עליה ואינו גט ישן לא מהני נאמנות והוי גט ישן ועיין סי' קמ\"ט ואפי' אם נתייחד עמה ואח\"כ הלך ועבר ל' יום הגט כשר אם נשאת דאין חשש אלא משום גט ישן אלא כשלא נתייחד ה\"ז גט כשר אפי' לכתחלה:","\u0003הרי היא נאמנת\u0004. לפרש\"י איירי הסוגיא כשא\"י אם נתייחד עמה ומ\"מ אנן לא חיישי' שמא נתייחד עמה אלא החשש הוא שמא יבוא הבעל ויאמר פייסתי ונתיחדתי עמה והוי גט ישן ואינו אלא לעז שיאמר נתיחדתי ועל זה צריך ליתן לה נאמנות והא דלא חיישינן שמא יאמר הבעל תוך ל' יום ראה אותה ולא עבר מנגד פניה כלל ל' יום כתב ב\"ח כיון דמסר הגט על תנאי זה לא מהני נאמנות על זה אלא צריך לברר ע\"פ עדים שעבר מנגד פניה ל' יום ואנ\"ל אלא גם ע\"ז מהני נאמנות כמ\"ש בסמוך בתנאי אם לא באתי עד יב\"ח, כל זה הוא לשיטות רש\"י אבל הרמב\"ם ס\"ל הסוגיא איירי בידוע שלא נתייחד עמה ומ\"מ הקשה המקשן וליחוש שמא פייס היינו למה לא חיישינן אנן שמא בשעה שהיה כאן אף על גב שלא נתייחד עמה ולא בא עליה וליכא חשש משום גט ישן מ\"מ ליחוש שמא פייס ובטלו שניהם הגט ואוקמי דנתן לה נאמנות מיהו אף לשיטות הרמב\"ם י\"ל אם נתייחד עמה מהני ג\"כ נאמנות אלא הסוגיא איירי בידוע שלא נתייחד עמה וא\"ל לשיטות הרמב\"ם למה לא חיישינן אתנאי אם תעשה כך וכך דקי\"ל הוא לבדו יכול לבטל התנאי ליחוש שמא ביטל הוא הגט ואפשר לומר דאין חוששין לזה אלא בכה\"ג שבא אצלה אז חיישינן שמא ביטל הגט אבל כשלא בא לא חיישינן שמא ביטל, ואם בא אצלה והתנה תנאי אם תעשה כך וכך צריך ליתן לה נאמנות וא\"ל מה מהני נאמנות הא יש לחוש שמא ביטל הוא בלא דעתה די\"ל כיון דאינו מבטל אלא מחמת חובתה אז מסתמא מודיע לה שביטל הגט ולהני פוסקים דחיישינן שמא בא בסתר א\"ל למה לא חיישינן שמא ביטל הגט הוא לבדו דאין דומ' חשש זה לחשש זה דשם התנאי היה אם העביר מפניך חיישינן שמא בא דהא התנאי קאי ע\"ז אבל לחוש שמא ביטל הגט לא חיישינן, ולשיטות הפוסקים דס\"ל תנאי שהוא בקום ועשה אינו נאמן לומר שקיים התנאי כמ\"ש בסי' ל\"ח א\"ל למה חיישינן כאן שבא תוך יב\"ח י\"ל לאו קום ועשה הוא כי לפעמים בא לשם מפני איזה עסק, וסתם נאמנות שנותן לה היינו לנגדו ולא נגד שני עדים, ונגד ע\"א תליא בדין סתם נאמנו' אם מהני נגד ע\"א כמ\"ש בח\"ה סי' ע\"א ואם אמר נאמנת עלי לומר שלא באתי אפילו באמת אבוא עיין תשוב' ריב\"ש סי' שנ\"ח משמע דאז אפי' בא לפני שני עדים נאמנת:","\u0003וחזר וביטל הגט\u0004. הנה ר\"ס קמ\"ג מבואר בתנאי מעכשיו או ע\"מ א\"י לבטל הגט וכאן איירי אפילו בע\"מ או מעכשיו וכתב המגיד בשם הרמב\"ן אף על גב הבעל לבדו א\"י לבטל הגט מ\"מ כשנתרצו שניהם לבטל יכולים לבטל מ\"ה חיישינן שמא בטלו מיהו דוקא שהתנאי הוא דבר שיש בידם לקיים אבל תנאי שאין בידם כגון בתנאי אם ימות א\"י לבטל אפילו שניהם, והא דהוא בעצמו א\"י לבטל נראה דוקא לבטל הגט או להתנות תנאי אחר א\"י כיון התנאי ע\"מ או דמעכשיו הוא והגט חל מיד א\"י לבטל אבל לבטל התנאי להחזיק הגט שיחול מיד יכול לבטל וכן משמע בתשובת הרא\"ש והטור הביא ס\"ס קמ\"ג לפ\"ז י\"ל הרא\"ש לא פליג על הרמ\"ה שהבאתי בסמוך דס\"ל אפי' בריצוי שניהם א\"י לבטל דהרא\"ש לא איירי אלא לבטל התנאי יכול לבטל אבל לבטל הגט י\"ל דס\"ל ג\"כ כהרמ\"ה ואין מוכרח מ\"ש הטור בסימן זה דהרא\"ש חולק על הרמ\"ה ולמ\"ש י\"ל דל\"פ וכ\"כ הרשב\"ץ בשם הרא\"ש דא\"י לבטל הגט ועיין ב\"י ס\"ס קמ\"ג והיינו מ\"ש הרא\"ש בתשו' כלל מ\"ו דיכול לבטל התנאי ויחול הגט מיד אבל אין יכול לבטל הגט ולדעת העיטור יכול לבטל הגט וכן להתנו' תנאי אפי' הוא לבדו והיינו הי\"א שהביא בהג\"ה ר\"ס קמ\"ג ולשיטות תוספות דף י\"ח והרמ\"ה שהביא הטור והר\"ן ס\"ל אפילו כשנתרצו שניהם א\"י לבטל הגט בתנאי מעכשיו וכן א\"י להתנות תנאי אחר, וכל הסוגיא דהקשה וליחוש שמא פייס איירי בתנאי באם ולא במעכשיו והקשה שמא פייס ומחלה התנאי ובטלו הגט נשמע מזה לשטה זו אפי' תנאי באם א\"י הוא לבטל אלא בריצוי שלה ולא כדעת הרמב\"ם דס\"ל תנאי אם יכול הוא לבדו לבטל כמ\"ש רס\"ז, נמצא דיש בזה ג' שיטות לרמב\"ם ורמב\"ן תנאי אם יכול הוא לבדו לבטל והסוגיא דהקשה וליחוש שמא פייס איירי בתנאי ע\"מ אז א\"י הוא לבדו לבטל אלא עם ריצוי דידה, ולהרי\"ף והרמ\"ה ותוספת איירי הסוגיא בתנאי אם ואז צריך ריצוי דידה, אבל תנאי מעכשיו אפילו ריצוי שניהם א\"י לבטלו, ולהעיטור אפילו הוא לבדו יכול לבטל הגט אפילו תנאי מעכשיו, ולכאורה קשה מ\"ש הרא\"ש בתשובה כלל ל\"ה דין ח' דיכול להוסיף על התנאי או לגרוע וכ\"כ רמ\"א ס\"ס ל\"ח ובכלל מ\"ו כתב דא\"י להתנות תנאי אחר אלא יכול לבטל התנאי שיחול הגט מיד בשלמא להוסיף על התנאי שכתב שם שפיר דאז מחזיק הגט כי איירי שם בתחילה התנה ע\"מ שאבוא בתוך יב\"ח א\"כ אם לא בא מבטל הקידושין ואח\"כ כשמרחיב הזמן אז מחזיק הקידושין אבל מ\"ש לגרוע א\"כ מבטל המעשה והנה רמ\"א הביא ג' שיטות הללו היינו בסימן ל\"ח הביא דברי הרא\"ש הנ\"ל ובר\"ס קמ\"ג הביא דברי העיטור ובסעיף ו' הביא שיטות הר\"ן כמ\"ש שם דס\"ל אפילו בריצוי שניהם א\"י להתנות תנאי אחר לאחר שנתן הגט והנה מ\"ש בסימן קמ\"ג שיטות העיטור ושיטות הר\"ן יש לתרץ וכוונתו להחמי' אפילו אם ביטל הבעל לבדו הגט יש להחמיר וכן להיפוך אפילו נתרצו שניהם לבטל או להתנות תנאי אחר חיישינן לשיטות הר\"ן ואם נתקיים תנאי הראשון י\"ל כבר נתקיים התנאי והיא מגורשת וקידושין תופסין בה אלא מ\"ש בסימן ל\"ח בפשיטות דיכול להוסיף או לגרוע נ\"ל כמ\"ש לעיל תנאי שאין בידה לקיים שאני ומ\"מ לא משמע משאר פוסקים חילוק זה:"]],["הֲרֵי זֶה גִּטֵּךְ אִם מַתִּי, אוֹ הֲרֵי זֶה גִּטֵּךְ אִם מַתִּי מֵחֹלִי זֶה, אוֹ הֲרֵי זֶה גִּטֵּךְ לְאַחַר מִיתָה, \u0010c0\u0011 אֵינוֹ גֵּט; \u0010c1\u0011 וְיֵשׁ אוֹמְרִים שֶׁהוּא סָפֵק. \u0010c2\u0011\nהֲרֵי זֶה גִּטֵּךְ מֵהַיּוֹם אִם מַתִּי, אוֹ מֵעַכְשָׁו אִם מַתִּי, הֲרֵי זֶה גֵּט, \u0010c3\u0011 וּכְשֶׁיָּמוּת תִּהְיֶה מְגֹרֶשֶׁת. וְיוֹתֵר טוֹב שֶׁיֹּאמַר: מֵעַכְשָׁו, מִשֶּׁיֹּאמַר: מֵהַיּוֹם, שֶׁאִם אָמַר: מֵהַיּוֹם, וּמֵת בְּתוֹךְ הַיּוֹם, \u0010c4\u0011 יֵשׁ לְהִסְתַּפֵּק שֶׁמָּא אֵין דַּעְתּוֹ \u0010c5\u0011 אֶלָּא מִסוֹף הַיּוֹם, וְאֵין גֵּט לְאַחַר מִיתָה.\nהֲרֵי זוֹ גִּטֵּךְ מֵעַכְשָׁו, אוֹ מֵהַיּוֹם, וּלְאַחַר מִיתָה, וּמֵת, הֲרֵי זֶה סְפֵק מְגֹרֶשֶׁת, שֶׁמָּא אַחַר שֶׁאָמַר: מֵעַכְשָׁו, חָזַר בּוֹ מִלְּשׁוֹן מֵעַכְשָׁו, וְסָמְכָה דַּעְתּוֹ עַל לְאַחַר מִיתָה.\nשְׁכִיב מְרַע שֶׁגֵּרַשׁ סְתָם, בְּלֹא תְּנַאי דְּמֵהַיּוֹם אִם מַתִּי, אֵין אוֹמְרִים סְתָמוֹ כְּפֵרוּשׁוֹ, כְּמוֹ שֶׁאָנוּ אוֹמְרִים בְּמַתָּנָה, דְּגֵט שָׁאנֵי; \u0010c6\u0011 וְאִם עָמַד, אֵינוֹ חוֹזֵר.\nשְׁכִיב מְרַע שֶׁרוֹצֶה לְגָרֵשׁ עַל תְּנַאי אִם יָמוּת, כְּדֵי שֶׁלֹּא תִּפֹּל לִפְנֵי יָבָם, וְאִם עָמַד לֹא תִּהְיֶה מְגֹרֶשֶׁת, אוֹמֵר לָהּ כְּשֶׁנּוֹתֵן לָהּ הַגֵּט: \u0010c7\u0011 אִם לֹא מַתִּי לֹא יִהְיֶה גֵּט וְאִם מַתִּי יְהֵא גֵּט מֵעַכְשָׁו וְאִם לֹא מַתִּי לֹא יְהֵא גֵּט, כְּדֵי שֶׁיְּהֵא הַתְּנַאי כָּפוּל וְהֵן קוֹדֵם לְלָאו, וְלֹא יִפְתַּח פִּיו תְּחִלָּה לְפֻרְעָנוּת, וְאָז יִהְיֶה בָּטֵל מִיָּד כְּשֶׁיַּעֲמֹד, אַף עַל פִּי שֶׁלֹּא יֹאמַר: חוֹזְרַנִי בִּי. וְאִם יִרְצֶה שֶׁלֹּא יִתְבַּטֵּל מִיָּד כְּשֶׁיַּעֲמֹד, אֶלָּא עַד זְמַן פְּלוֹנִי, יֹאמַר: אִם לֹא מַתִּי עַד זְמַן פְּלוֹנִי לֹא יִהְיֶה גֵּט וְאִם מַתִּי עַד זְמַן פְּלוֹנִי יְהֵא גֵּט מֵעַכְשָׁו וְאִם לֹא מַתִּי עַד זְמַן פְּלוֹנִי לֹא יְהֵא גֵּט. \u0005 הַגָּה: וְיֹאמַר לָשׁוֹן זֶה דַּוְקָא: אִם מַתִּי אִם לֹא מַתִּי וְכוּ', וְלֹא יֹאמַר: אִם אָמוּת אִם לֹא אָמוּת, מֵאַחַר שֶׁהוּא לְשׁוֹן חֲכָמִים. וְעַיֵּן לְעֵיל סִימָן קנ\"ד סָעִיף ק' לֹא מַשְׁמָע כָּךְ: \u0006\nהֲרֵי זֶה גִּטֵּךְ מֵהַיּוֹם אִם מַתִּי מֵחֹלִי זֶה, \u0010c8\u0011 וְנָפַל עָלָיו בַּיִת אוֹ נְשָׁכוֹ נָחָשׁ אוֹ טְרָפוֹ אֲרִי וְכַיּוֹצֵא בָּזֶה, וּמֵת, אֵינוֹ גֵּט. אֲבָל אִם אָמַר: אִם לֹא יַעֲמֹד מֵחֹלִי זֶה, וְנָפַל עָלָיו בַּיִת אוֹ נְשָׁכוֹ נָחָשׁ אוֹ טְרָפוֹ אֲרִי, \u0010c9\u0011 הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:\nהֲרֵי זֶה \u0010c10\u0011 גִּטֵּךְ מֵעַכְשָׁו אִם מַתִּי \u0010c11\u0011 מֵחֹלִי זֶה, וְעָמַד וְהָלַךְ בַּשּׁוּק, וְחָלָה וָמֵת; אוֹמְדִין אוֹתוֹ, אִם מֵחֲמַת חֹלִי הָרִאשׁוֹן מֵת, הֲרֵי זֶה גֵּט, אֲפִלּוּ הָלַךְ \u0010c12\u0011 בְּלֹא מִשְׁעֶנֶת; וְאִם לָאו, אֵינוֹ גֵּט. \u0010c13\u0011 וְאִם נִתַּק מֵחֹלִי לְחֹלִי וְלֹא עָמַד בַּשּׁוּק, הֲרֵי זֶה גֵּט וְאֵינוֹ צָרִיךְ אֹמֶד:\nשְׁכִיב מְרַע שֶׁנָּתַן גֵּט וְאָמַר: מֵהַיּוֹם אִם מַתִּי, סְתָם, וְהִבְרִיא, בָּטֵל גִּטּוֹ; וְלֹא אָמְרִינָן לְעוֹלָם קֹדֶם שֶׁיָּמוּת קָאָמַר, אֶלָּא אִם מַתִּי מֵחֹלִי זֶה קָאָמַר, אֲבָל אִם מִתּוֹךְ בֻּרְיוֹ הִתְנָה בְּמֵהַיּוֹם אִם מַתִּי, וַדַּאי כָּל שֶׁמֵּת בְּחַיֶּיהָ קָאָמַר, וְכָל אֵימַת דְּמָאִית הֲרֵי זוֹ מְגֹרֶשֶׁת:\nעֵצָה טוֹבָה עַל פִּי גְּדוֹלֵי עוֹלָם לָחוּשׁ לְרַמָּאִין בְּגֵט שְׁכִיב מְרַע, שֶׁיֹּאמַר: אִם מַתִּי מֵעַכְשָׁו וְעַד יוֹם פְּלוֹנִי וְהוּא בִּכְלָל, יְהֵא גֵּט; וְלֹא יֹאמַר: אִם אָמוּת מֵחֹלִי זֶה, שֶׁיְּהֵא הַתְּנַאי תָּלוּי בַּחֹלִי, שֶׁמָּא יָבֹא אָדָם שֶׁאֵינוֹ הָגוּן וְיִשְׁתַּדֵּל עִם הָרוֹפֵא שֶׁיֹּאמַר שֶׁלֹּא מֵת מֵאוֹתוֹ חֹלִי אֶלָּא מֵחֹלִי אַחֵר \u0010c14\u0011 שֶׁנֶּעְתַּק אֵלָיו, וְיוֹצִיא לַעַז עַל הַגֵּט. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין אָנוּ בְּקִיאִין בַּזְּמַן הַזֶּה, וְלָכֵן אֵין לִסְמֹךְ בַּזְּמַן הַזֶּה מֵאֻמְדָּנוֹת הָרוֹפְאִים. וְיֵשׁ אוֹמְרִים דִּלְכַתְּחִלָּה אֵין לְגָרֵשׁ עַל יְדֵי תְּנַאי, רַק יְגָרֵשׁ סְתָם, וּלְקַבֵּל בְּחֵרֶם הַקְּהִלּוֹת אוֹ לִתֵּן מַשְׁכְּנוֹת \u0010c15\u0011 שֶׁכְּשֶׁיַּעֲמֹד יַחְזְרוּ וְיִשְּׂאוּ זֶה אֶת \u0006 \u0005 זֶה \u0006 \u0005(מָרְדְּכַי פֶּרֶק מִי שֶׁאֲחָזוֹ)\u0006. \u0005 וּבְכֹהֵן הַמְגָרֵשׁ, שֶׁצָּרִיךְ לְהַתְנוֹת, שֶׁלֹּא תְּהֵא אֲסוּרָה לַחֲזֹר לוֹ, כְּדִלְעֵיל רֵישׁ סִימָן קמ\"ג, אוֹ שֶׁיֵּשׁ לָחוּשׁ לְטֵרוּף דַּעַת הַחוֹלֶה, יֵשׁ לְגָרֵשׁ בִּתְנַאי כְּדֶרֶךְ שֶׁנִּתְבָּאֵר \u0006 \u0005(סֵדֶר גִּטִּין)\u0006. \u0005 אִשָּׁה שֶׁנִּתְגָּרְשָׁה עַל תְּנַאי, וּמֵת הַבַּעַל, אֵינָהּ צְרִיכָה לְהִתְאַבֵּל עָלָיו \u0006 \u0005(שָׁם בְּמָרְדְּכַי)\u0006; \u0010c16\u0011 \u0005 אֲבָל אֵין אִסוּר בַּדָּבָר אִם רְצוֹנָהּ לְהַחֲמִיר עַל עַצְמָהּ לִבְכּוֹת עָלָיו וְלָצֵאת אַחַר מִטָּתוֹ: \u0006\nשְׁכִיב מְרַע שֶׁנָּתַן גֵּט לְאֶחָד וְאָמַר לוֹ: זְכֵה בְּגֵט זֶה לְאִשְׁתִּי, כְּדֵי שֶׁלֹּא תִּפֹּל לִפְנֵי יָבָם, וּמֵת קֹדֶם שֶׁיַּגִּיעַ לְיָדָהּ, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת, וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:",[],["\u0003אינו גט\u0004. וא\"ל למה לא אמרינן התנאי בטל והגט חל מיד דהא לא כפל התנאי אם כן המעשה קיים והתנאי בטל ויש לומר אם מתי הוי כאומר לאחר מיתה והוי כאלו קובע זמן כמ\"ש בסימן אח\"ז דאין צריך ת\"כ והא דהתקין שמואל באם מתי תנאי כפול היינו כמ\"ש המגיד כשכפל התנאי אז ניכר דאין כוונתו לגרש אחר המיתה אלא מגרש מיד ואינו אלא תנאי אם ימות משא\"כ באומר סתם אם מתי אמרי' דכוונתו לגרש לאחר מותו והוי קובע זמן ואין צריך ת\"כ:","\u0003וי\"א שהוא ספק\u0004. היינו הספק הוא אם הלכה כרבי יוסי דאמר זמן של שטר מוכיח והוי כאלו אמר מהיום:","\u0003מהיום אם מתי\u0004. משום אם מתי תרי לשונות משמע מעכשיו ומשמע לאחר מיתה מ\"ה אם אמר מהיום כמאן דאמר מעכשיו דמי לא אמר מהיום כמאן דאמר לאחר מיתה דמי, והנה בסימן קמ\"ח מבואר הפלוגתא אם דעתו שיחול הגט מיד ואז אפי' אין הגט קיים בעת המיתה מגורשת דגרושין חלין מיד וכן הוא דעת הרי\"ף ורמב\"ם פ\"ט דין י\"ט אבל לדעת הרא\"ש והטור והמ' פמ\"ש לרבי יוסי מסופק דדעתו לאחר הגט כל מה שיכול וכוונתו שיתחיל מעכשיו התנאי ויחול הגט שעה אחת קוד' מיתתו וצריך להיות הגט קיים באותו שעה, ואם אינו קיים פסק המ' שם דתצא, והד\"מ רס\"ז הביא בקיצור דעת המרדכי וכתב עליו עיין סימן קמ\"ג דהרבה פוסקים חולקים וס\"ל דכל האומר מעכשיו אפי' נאבד או נשרף הגט כשר ולכאורה נראה דל\"ד בוודאי בריא המגרש בתנאי מעכשיו לכ\"ע מתחילים הגירושין מיד אלא בשכ\"מ ס\"ל כוונתו לאחר הגט כל מה שיכול ולענין יחדו עמה לשיטו' הרי\"ף אם מייחד לפני עדים יש חשש קידושין שמא ימות ויחול הגט למפרע מיד ואפשר שקידש אותה באותו פעם ובלא עדים איכא איסור יחוד אבל גט ישן לא שייך כאן ממ\"נ דהא הגט חל מיד כשימות ואם לא ימות אז היא אשתו ולשיטות הרא\"ש יש חשש ג\"י דהא הגט עדיין לא חל וכבר כתבתי בסימן הקודם דלא חיישינן בזה שמא יתרצו שניהם לבטל הגט כיון התנאי בעל כרחם נתקיים ואין בידם לא שייך לומר כאלו לא נתקיים ועיין במגיד פ\"ט דין ט':","\u0003וכשימות תהיה מגורשת\u0004. משמע אם לא ימות אינה מגורשת היינו לשיטות הרמב\"ם דס\"ל במעכשיו א\"צ ת\"כ אבל לשאר פוסקים אם לא כפל התנאי אז בטל התנאי והגט חל:","\u0003יש להסתפק שמא וכו'\u0004. אלא מסוף היום לכאור' קשה למה אמרינן אם אמר כתבו לאחר שבוע דכותבים מיד אחר השבוע כיון שכל השנה שאחר השבוע בכלל לאחר השבוע שמא כוונתו על סוף השנה:","\u0003אלא מסוף היום\u0004. לכן כשאומר מהיום או מעכשיו ומת בו ביום צריכים ע\"מ להיות לפנינו שיעידו שבא הגט לידה בחייו מאחר ע\"פ ע\"ח אין מוכח אימת תתגרש ועיין בפרישה וב\"ח:","\u0003ואם עמד אינו חוזר\u0004. דאם יחזור יאמרו יש גט לאחר מיתה ואף לר\"י דס\"ל זמן של שטר מוכיח והוי כאלו אמר מהיום מחמת זמן של שטר מ\"מ יאמרו מהיום ולאחר מיתה גט:","\u0003אם לא מתי\u0004. כדי שאל יפתח פיו לרעה ומ\"מ הוי הן קודם ללאו מאחר שאמר אח\"כ הן קודם לאו ולרמב\"ם דס\"ל תנאי מעכשיו א\"צ ת\"כ והן קודם לאו צ\"ל דאיירי בתנאי אם ולא מעכשיו וקשה איך תתגרש בתנאי אם דהא קי\"ל האומר הרי זה גיטך אם מתי לא הוי גט ולמ\"ש לעיל מה שכותבים מיומא דנן הוי כאלו אומר מעכשיו יש ליישב קצת מיהו הרמב\"ם לא ס\"ל כן וראיתי במגיד פ\"ט מאריך בזה ועולה מדבריו מה שכופל התנאי מוכח דכוונתו שיחול הגט מיד ובדרישה הקשה קושי' זו ולא תירץ כלום:","\u0003ונפל עליו בית\u0004. הנה האומר אם מתי מחולי זה פליגי בזה הפוסקים לרמב\"ן ורשב\"א והר\"ן דוקא אם מת מחולי זה הוי גט אבל אם מת מחמת סיבה אחרת דלאו מחולי זה אף על גב דמת תוך חולי זה לאו גט הוא אפילו סיבה דשכיח מ\"מ לאו מחולי זה מת ולרש\"י והרא\"ש אם סיבה דשכיח היא מגורשת אבל סיבה דלא שכיח אינה מגורשת והא דצריך אומדנא כשאומר אם מתי מחולי זה ועמד והלך בשוק משום כשמת מחולי אחר לא הוי תוך חולי הראשון דהא הלך בשוק אבל אם מת מחולי הראשון הוי מחולי זה אף על גב אם נתרפא לגמרי וחלה אח\"כ ומת מחמת חולי הראשון הגט בטל מ\"מ בכה\"ג דלא נתרפא לגמרי ומת מחמת חולי הראשון נתקיים התנאי מחולי זה והמחב' כתב כלשון הרמב\"ם באומר אם מתי מחולי זה אינו גט ובסיפא ספק גט משום די\"ל דמסי' דעתו על סיבה זו ש\"מ דסביר' ליה כרמב\"ן לכן ברישא אינו גט אפילו היה אונס שכיח מ\"מ לא מת מחולי זה:","\u0003ה\"ז ספק מגורשת\u0004. עיין מה שפסק המחב' ר\"ס קמ\"ד כדעת שאר פוסקים אונס דלא שכיח כלל מבטל הגט א\"כ קשה אם אמר אם לא יעמוד ובא לו אונס דלא שכיח למה הוי ספק גט ותוס' פמ\"ש וריש כתובות למדו דין זה אונס דלא שכיח דמבטל הגט מסוגיא דכאן ולדברי המחבר כאן הוי ספק גט א\"כ בשאר אונס דלא שכיח למה הגט בטל בודאי מ\"ש אם לא אבא ואכלו ארי ומ\"ש אם התנה אם לא אעמוד ואכלו ארי, ולשיטו' רש\"י גם כן אם התנה אם לא אעמוד ואכלו ארי הגט בטל וצל\"ע:","\u0003מעכשיו אם מתי\u0004. היינו לשיטו' הרמב\"ם דס\"ל אם אמר מעכשיו וקיים אפי' לא כפל אז בעינן אומדנא אם נתקיים התנאי אבל לשאר פוסקים דס\"ל אפי' אם אמר מעכשיו בעינן ת\"כ ואם לא כפל התנאי בטל והמעשה קיים אם כן אפי' אם לא מת מחולי הראשון הגט קיים, ועיין ב\"י סס\"ז אם העדים החתומים נאמנים לומר שנתן הגט על תנאי:","\u0003מחולי זה\u0004. משמע לכאורה אם אמר סתם אם מתי אין צריך אומדנא וכ\"כ הרמב\"ן ורי\"ו וכתבו אפילו אם מת מחולי אחר מגורשת כיון שלא הבריא לגמרי כאשר היה קודם שחלה אף על פי שהלך בלא משענת הוי גט ואם הבריא מחולי לגמרי כמו שהיה קודם שחלה בטל הגט אף על גב שחלה אחר כך ומת, ובסעיף אח\"ז הביא דברי הרשב\"א והר\"ן ש\"מ שאמר אם מתי מחולי זה קאמר לכן אם הבריא וחלה אח\"כ ומת אינו גט נראה דל\"פ על הרמב\"ן אלא אם הבריא כמו שהיה קודם שחלה אז הגט בטל אף על גב שחלה אחר כך ומת ואמרי' מ\"ש אם מתי היינו מחולי זה קאמר אבל אם לא הבריא כמו שהיה קודם שחלה אף על גב דהלך בשוק בלא משענת וחלה מחולי אחר מגורשת אא\"כ שהתנה בפירוש אם מתי מחולי זה ואז אפילו לא הבריא כמו שהיה קודם שחלה בעינן אומדנא אם מת מחולי הראשון אבל מדברי המגיד ספ\"ח ה\"ז מבואר דהרי\"ף והרמב\"ם לא ס\"ל כן אלא אפילו אם אמר סתם אם מתי צריך אומדנא אם מת מחולי הראשון וסוגיא קאי אפי' אם אמר סתם אם מתי, ולכאורה קשה לפ\"ז על מ\"ש המחבר בסעיף ט' עצה טובה וכו' אכתי החשש במקומו עומד דהא ס\"ל אפי' באומר סתם אם מתי בעינן אומדנא אם מת מאותו חולי:","\u0003בלא משענת\u0004. היינו דלא נתרפא לגמרי ולא חזר לאיתנו הראשון כ\"כ הר\"ן ואם אמר אם מתי ולא אמר מחולי זה כתבתי בסמוך לדעת המחבר אפי' אם מת מחולי אחר הוי גט ומ\"ש בסעיף ח' מחולי זה קאמר היינו לענין אם הבריא לגמרי:","\u0003ואם ניתק מחולי לחולי וכו'\u0004. ולא כרשב\"א דסבירא ליה אפילו בניתק צריך אומדנא ובטור כתב אפילו הולך בביתו בלא משענת א\"צ אומד כיון שלא הלך בשוק ובח\"ה סימן ר\"ן כתב בהג\"ה כשהולך בביתו על משענת אין צריך אומד ולמד מדברי המרדכי ובאמת י\"ל שם מעשה שהיה כך היה שהלך על המשענת אבל באמת ל\"פ על הטור וס\"ל נמי אם הולך בביתו בלא משענת א\"צ אומד ואם הלך בשוק על משענתו צריך אומדנא ולדעת הפוסקים שהבאתי דס\"ל כשאומר אם מתי מחולי זה היינו מחמת חולי זה ולא מתוך חולי זה וכתבתי גם הרמב\"ם ס\"ל כן לכן ס\"ל אם אמר מחולי זה ונפל עליו בית אינו גט אף על גב דמת תוך החולי מ\"מ כיון שלא מת מחמת חולי ההוא אינו גט צ\"ל בניתק מחולי לחולי אמרי' עדיין חולי הראשון בו וחולי הראשון ג\"כ גורם המיתה:","\u0003שנעתק כו'\u0004. כ\"כ הרשב\"א והוא לטעמו דס\"ל ניתק מחולי לחולי צריך אומדנא מ\"ה יש לחוש שמא יאמרו דמת מחולי אחר ולרמב\"ם ושאר פוסקים ס\"ל ניתק מחולי לחולי א\"צ אומד היינו משום דאמרי' מסתמא יש בו מחולי הראשון מ\"ה יש לחוש שמא יאמרו דלא נשאר מחולי הראשון:","\u0003שכשיעמוד יחזרו וישאו זא\"ז\u0004. ואם היא אינה רוצה לישא אותו אין שום חשש איסור כיון שמגרש בלי תנאי לכן מקרעים הגט ועיין דין זה בתשובת מהר\"מ מלובלין סימן קכ\"ב וכל חכמי הדור חולקים עליו ועיין ב\"ח סימן קמ\"ח ובתשובת מ\"ב סימן ע\"ה:","\u0003אבל אין איסור בדבר\u0004. ולא חיישינן שיאמרו דהיא אלמנה ולא גרושה ועיין בסי' י\"ז מ\"ש שם דיש למחות בנשים שאל יתאבלו כשא\"י בוודאי שהוא מת:"]],["הַמְגָרֵשׁ אֶת אִשְׁתּוֹ לְאַחַר זְמַן קָבוּעַ, הֲרֵי זוֹ מְגֹרֶשֶׁת כְּשֶׁיַּגִּיעַ הַזְּמַן שֶׁקָּבַע. וַהֲרֵי זֶה דּוֹמֶה לִתְנַאי, וְאֵינוֹ תְּנַאי. דּוֹמֶה לִתְנַאי, שֶׁהִיא מִתְגָּרֶשֶׁת כְּשֶׁיַּגִּיעַ הַזְּמַן שֶׁקָּבַע; וְאֵינוֹ תְּנַאי, שֶׁהַמְגָרֵשׁ עַל תְּנַאי הֲרֵי גֵּרַשׁ, וְזֶה עֲדַיִן לֹא גֵּרַשׁ עַד שֶׁיַּגִּיעַ אוֹתוֹ זְמַן. לְפִיכָךְ, הַמְגָרֵשׁ עַל תְּנַאי צָרִיךְ לִכְפֹּל תְּנָאוֹ, וְזֶה אֵינוֹ צָרִיךְ לִכְפֹּל דְּבָרָיו וְלֹא לִשְׁאָר מִשְׁפְּטֵי הַתְּנָאִים. כֵּיצַד, הָאוֹמֵר לְאִשְׁתּוֹ: הֲרֵי זֶה גִּטֵּךְ וְלֹא תִּתְגָּרְשִׁי בּוֹ אֶלָּא לְאַחַר שְׁלשִׁים יוֹם, אֵינָהּ מְגֹרֶשֶׁת אֶלָּא לְאַחַר שְׁלשִׁים יוֹם. וְאִם מֵת הַבַּעַל אוֹ אָבַד הַגֵּט אוֹ נִשְׂרַף בְּתוֹךְ שְׁלשִׁים יוֹם, אֵינָהּ מְגֹרֶשֶׁת:\nהָלְכָה וְהִנִּיחַתּוּ \u0010c0\u0011 בְּצִדֵּי רְשׁוּת הָרַבִּים, וְנִגְנַב אוֹ אָבַד לְאַחַר שְׁלשִׁים יוֹם, הֲרֵי זוֹ מְגֹרֶשֶׁת, הוֹאִיל וְהָיָה הַגֵּט קַיָּם בַּיּוֹם שֶׁמִּתְגָּרֶשֶׁת בּוֹ, וְיִחֲדָה אוֹתוֹ בְּמָקוֹם שֶׁאֵינוֹ רְשׁוּת הָרַבִּים, שֶׁצִּדֵּי רְשׁוּת הָרַבִּים אֵינָם כִּרְשׁוּת הָרַבִּים. וְכֵן אִם תָּלָה הַגֵּרוּשִׁין בְּמַעֲשֶׂה, דִּינוֹ כְּדִין מְגָרֵשׁ אַחַר זְמַן. כֵּיצַד, כְּגוֹן שֶׁאָמַר לָאִשָּׁה: הֲרֵי זֶה גִּטֵּךְ וְלֹא תִּתְגָּרְשִׁי בּוֹ עַד שֶׁתִּתְּנִי לִי מָאתַיִם זוּז, הֲרֵי זוֹ מִתְגָּרֶשֶׁת אַחַר שֶׁתִּתֵּן, וְאֵינוֹ צָרִיךְ לִכְפֹּל הַתְּנַאי וְלֹא לִשְׁאָר מִשְׁפְּטֵי הַתְּנָאִים, שֶׁהֲרֵי לֹא גֵּרַשׁ עַל תְּנַאי, אֶלָּא עֲדַיִן לֹא גֵּרַשׁ זֶה, אֶלָּא תָּלָה הַגֵּרוּשִׁין בַּעֲשִׂיַּה כָּךְ וְכָךְ וְאַחַר כָּךְ תִּתְגָּרֵשׁ. וּמַה בֵּין מְגָרֵשׁ עַל תְּנַאי, לְזֶה שֶׁקָּבַע זְמַן לְגֵרוּשִׁין אוֹ תְּלָאָן בְּמַעֲשֶׂה, שֶׁהַמְגָרֵשׁ עַל תְּנַאי יֵשׁ שָׁם גֵּרוּשִׁין, וְאֵינָם גּוֹמְרִים עַד שֶׁיִּתְקַיֵּם הַתְּנַאי; לְפִיכָךְ, כְּשֶׁיִּתְקַיֵּם הַתְּנַאי, נִתְגָּרְשָׁה, \u0010c1\u0011 אִם הָיָה הַגֵּט קַיָּם, אַף עַל פִּי שֶׁאֵינָה בִּרְשׁוּתָהּ, וְאֵינָהּ צְרִיכָה לַחֲזֹר וְלִטְּלוֹ אוֹ לִהְיוֹתָה בִּרְשׁוּתָהּ אַחַר שֶׁנִּתְקַיֵּם הַתְּנַאי, שֶׁהֲרֵי הִגִּיעַ לְיָדָהּ תְּחִלָּה בְּתוֹרַת גֵּרוּשִׁין. אֲבָל הַתּוֹלֶה הַגֵּרוּשִׁין בִּזְמַן אוֹ בְּמַעֲשֶׂה, לֹא הִגִּיעַ לְיָדָהּ בְּתוֹרַת גֵּרוּשִׁין אֶלָּא בְּתוֹרַת פִּקָּדוֹן עַד הַזְּמַן שֶׁקָּבַע אוֹ עַד שֶׁתַּעֲשֶׂה הַמַּעֲשֶׂה; לְפִיכָךְ, כְּשֶׁהִגִּיעַ הַזְּמַן \u0010c2\u0011 צָרִיךְ לִהְיוֹת הַגֵּט בִּרְשׁוּתָהּ, אוֹ תַּחֲזֹר וְתִטְּלֶנּוּ, אוֹ יִהְיֶה בְּמָקוֹם שֶׁיִּחֲדָה אוֹתוֹ בּוֹ אַף עַל פִּי שֶׁאֵינוֹ רְשׁוּתָהּ, כְּמוֹ שֶׁבֵּאַרְנוּ, וְאַחַר כָּךְ תִּתְגָּרֵשׁ בּוֹ. וְאִם נִשֵּׂאת קֹדֶם הַזְּמַן שֶׁקָּבַע, אוֹ קֹדֶם שֶׁתַּעֲשֶׂה הַמַּעֲשֶׂה שֶׁתָּלָה בּוֹ הַגֵּרוּשִׁין, תֵּצֵא וְהַוָּלָד מִמֶּנּוּ מַמְזֵר, שֶׁעֲדַיִן הִיא אֵשֶׁת אִישׁ גְּמוּרָה וְאֵין כָּאן שֵׁם גֵּרוּשִׁין:\nהַנּוֹתֵן גֵּט בְּיַד אִשְׁתּוֹ וְאָמַר לָהּ: אִם לֹא תִּתְּנִי מָאתַיִם זוּז \u0010c3\u0011 אֵין זֶה גֵּט, אוֹ אֵין אַתְּ מְגֹרֶשֶׁת, הֲרֵי זֶה לֹא גֵּרַשׁ כְּלָל, וְאֵין כָּאן גֵּט לֹא עַל תְּנַאי וְלֹא תָּלוּי בְּמַעֲשֶׂה, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם אָמַר לָהּ: הֲרֵי אַתְּ מְגֹרֶשֶׁת, וְאִם לֹא תִּתְּנִי לִי מָאתַיִם זוּז לֹא תִּהְיִי מְגֹרֶשֶׁת, הֲרֵי זוֹ מְגֹרֶשֶׁת אַף עַל פִּי שֶׁלֹּא נָתְנָה, מִפְּנֵי שֶׁלֹּא כָּפַל תְּנָאוֹ:\nמִי שֶׁנִּתְגָּרְשָׁה עַל תְּנַאי, וְקִדְּשָׁהּ אַחֵר קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי; \u0010c4\u0011 אִם נִתְקַיֵּם הַתְּנַאי, הֲרֵי זוֹ מְקֻדֶּשֶׁת; וְאִם לֹא נִתְקַיֵּם הַתְּנַאי וּבָטֵל הַגֵּט, \u0010c5\u0011 אֵינָהּ צְרִיכָה גֵּט מִשֵּׁנִי, שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ. אֲבָל אִם נִשֵּׂאת וְלֹא נִתְקַיֵּם הַתְּנַאי וּבָטֵל הַגֵּט, צְרִיכָה גֵּט מִשֵּׁנִי:\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאִם קִדְּשָׁהּ אַחֵר וְלֹא נִתְקַיֵּם הַתְּנַאי שֶׁהַגֵּט בָּטֵל, בִּתְנַאי שֶׁהוּא בְּלָאו, וְעָשְׂתָה מַעֲשֶׂה בְּבִטּוּלוֹ, אוֹ בִּתְנַאי שֶׁהוּא בְּמַעֲשֶׂה תּוֹךְ זְמַן קָצוּב וְעָבַר הַזְּמַן וְלֹא נַעֲשָׂה, אוֹ בְּאֵיזֶה דֶּרֶךְ שֶׁהָיָה הַתְּנַאי מְבֻטָּל בְּפֹעַל, הַגֵּט בָּטֵל. אֲבָל בִּתְנַאי שֶׁבְּיָדָהּ לְקַיְּמוֹ וּבָהּ הַדָּבָר תָּלוּי וְאִם נִתְקַיֵּם הַתְּנַאי \u0010c6\u0011 מְגֹרֶשֶׁת, \u0005 חַיְשִׁינָן שֶׁמָּא קִיְּמָה הַתְּנַאי \u0006 \u0005(הַמ\"מ)\u0006 וְחָלוּ קִדּוּשֵׁי שֵׁנִי:",[],["\u0003בצידי ר\"ה או באגם או בסימטא\u0004. כמ\"ש בסוגיא פרק הכותב ובתוספות שם אף על גב בעת הנתינה לא היתה מגורשת לא הוי כטלי גיטך מעל גבי קרקע כיון שנתן לה בתורת גירושין אלא שמגביל זמן אימת תתגרש הוי נתינה גמורה אף על גב האומר משוך בהמה זו וקני לאחר ל' יום צ\"ל קני מעכשיו כמ\"ש ברמב\"ם פ\"ב דמכירה ובח\"ה ס\"ס קצ\"ז ש\"ה דקונה במשיכה ולאחר ל' יום כבר כלתה המשיכה אבל כאן הגט עדיין קיים ומונח במקום דראוי לקנין כ\"כ המגיד והר\"ן לדעת הרמב\"ם דהיא מגורשת אפילו אם לא אמר מעכשיו אבל תוס' והרשב\"א סבירא להו אם לא אמר מעכשיו אינה מגורשת ואם אמר מעכשיו הוי ספק גט דקי\"ל כרב דמספקא שמא תנאי הוא אז אפילו אם מונח בר\"ה מגורשת או שמא חזרה הוא והוי כאלו אמר לאחר ל' יום בלא מעכשיו ואינה מגורשת כי צידי ר\"ה לאו מקום שלה הוא ומבואר בתוס' פ' האשה שנפלו ובר\"ן כשהוא תנאי אז אפי' עומדת בר\"ה או ברשות המוכר קונה לכן יפה כתב המגיד ס\"ב דמכירה לדעת הרמב\"ם דס\"ל מעכשיו ולאחר ל' יום תנאי הוא כמ\"ש שם א\"כ מ\"ש הרמב\"ם שם דעומדת הבהמה באגם ל\"ד דהא אפילו בר\"ה נמי קונ' כיון דתנאי הוא והב\"י השיג עליו ס\"ס קצ\"ז וכתב אגם דוקא ולא ר\"ה והביא ראיה מתוס' הנ\"ל וליתא כי תוס' כ\"כ לרבי יוחנן דס\"ל דלאו תנאי הוא אלא המשיכה מתחיל היום ונגמר לאחר ל' יום אז בעינן דמונח במקום הראוי לקני אבל הרמב\"ם דס\"ל תנאי הוא א\"כ אפילו בר\"ה נמי והסמ\"ע הביא דברי הב\"י ול\"ד, וא\"ל דלרמב\"ם דס\"ל תנאי הוא הלא אם אמר התקדש לי מעכשיו ולאחר ל' יום פסק כרב דמספקא ליה אם תנאי הוא אי חזרה וי\"ל דוקא משום חשש א\"א פוסק לחומר' כרב אבל בממון ס\"ל תנאי הוא וכן מוכרח לרמב\"ם ורשב\"א דס\"ל בקנין בהמה אם אמר מעכשיו ולאחר ל' יום קונה ובגט הוי ספק ש\"מ דפסקו כשמואל אלא בגט חיישינן להא דרב, אלא צריך ישוב מנ\"ל לרמב\"ם לחלק כן כי שם בקידושין פליגי רב ור' יוחנן ושמואל לרב ספק הוא כהנ\"ל לרבי יוחנן מתחילין מיד וגומרים לאחר ל' יום, לשמואל תנאי הוא מנ\"ל לפסוק בממון כשמואל נגד ר' יוחנן:","\u0003אם היה הגט קיים\u0004. ע\"כ בתנאי אם איירי כי בתנאי ע\"מ א\"צ להיות קיים כמ\"ש בסי' קמ\"ג ומ\"מ א\"צ להיות ברשותה וצריך טעם כיון דאין גירושין עד אותו שעה מה מהני אם מונח באותו שעה בר\"ה גם נשמע מכאן דהמחבר ס\"ל כרמב\"ם בתנאי אם ונשאת קודם שנתקיים התנאי לא תצא מדכתב בסמוך ואם נשאת קודם הזמן תצא ש\"מ דוקא שם דקודם לכן אין שם גירושים כלל אבל אם נשאת קודם שנתקיים התנאי לא תצא עיין ר\"ס קמ\"ג ועיין סי' קמ\"ח:","\u0003צריך להיות הגט ברשותה\u0004. ואם ליתא ברשותה הוי ספק גט להני פוסקים דפסקו כר\"י זמן ש\"ש מוכיח והוי כאלו אמר מעכשיו ולאחר ל' יום המגיד ועיין ר\"ס קמ\"ד:","\u0003אין זה גט\u0004. אף על גב מכלל לאו נשמע הן מ\"מ כיון שלא הזכיר גירושין בפירוש אינה מגורשת, המגיד:","\u0003אם נתקיים התנאי וכו'\u0004. היינו בתנאי ע\"מ דאז אם נתקיים התנאי חל הגט למפרע נמצא בעת שקידש היתה פנוייה אבל תנאי אם דגט חל בעת שנתקיים ובאותו פעם היתה א\"א נראה דקידושין לא הוי קידושין מיהו לדעת הרמב\"ם דס\"ל אם נשאת קודם שנתקיים התנאי לא תצא י\"ל גם הקידושין חלין וכ\"כ בסימן קמ\"ח ע\"ש וקצת ראי' דאיירי בתנאי אם דהא בסמוך מוכח דאיירי בתנאי אם וה\"ל לפרש דאיירי כאן בתנאי ע\"מ וכן הוא בפרישה:","\u0003א\"צ גט משני\u0004. הנה לדעת הראב\"ד אסורה לראשון ופי' בדרישה טעמא משום דחיישינן שמא יאמרו בודאי קיימה התנאי כיון התנאי בידה לקיים והיא מגורשת מזה והוא מחזיר גרושתו משנתארסה ול\"ד למי שהלך למ\"י והיא נתקדשה לאחר ובא בעל' מותר' לראשון דשם באמת לא היה גירושין לא יאמרו דגירש אלא יאמרו טעות היה דסברה דמת בעלה אבל כאן הי' גט ותנאי הוא בידה לקיים יאמרו בודאי מקוים התנאי עוד כתב שם דרמב\"ם נמי ס\"ל דאסורה לראשון וזה ליתא כמה דהשיג עליו בט\"ז דהרי הרמב\"ם מסיים שם וכתב כמו שביארנו והיינו בדין שהלך בעלה למ\"י ושם מבואר בנתקדשה מותר' לראשון וליישב קושית הראב\"ד י\"ל דס\"ל להרמב\"ם לעולם לא חיישינן שיאמרו דזה עביד איסור' כל זמן שאין מוכרח א\"כ כיון די\"ל דלא נתקיים התנאי אף על גב התנאי בידה לקיים לא חיישינן שיאמרו דנתקיים התנאי והוי מחזיר גרושתו משנתארסה ול\"ד למ\"ש סי' ל\"א וסי' מ\"ו שם כששניהם מקדשים ממ\"נ אי עביד איסור' אז חיישינן שמא יאמרו אבל כאן די\"ל דלא עביד איסור' לא חיישינן שמא יאמרו דעביד איסור':","\u0003שמא קיימה התנאי\u0004. הט\"ז מאריך בזה ובוודאי ט\"ס וצ\"ל שמא תתקיים התנאי דחילוק הוא אם כבר בטלה התנאי אז בטל הגט אבל אם לא נתבטל יש לחוש שמא תתקיים עוד ועדיין לא נתבטלו וחלו קידושי שני:"]],["כֵּיצַד מְגָרֵשׁ אָדָם עַל תְּנַאי, לֹא שֶׁיֹּאמַר: כִּתְבוּ גֵּט לְאִשְׁתִּי עַל תְּנַאי זֶה, אוֹ כִּתְבוּ וּתְנוּ לָהּ עַל תְּנַאי זֶה, וְאֵין צָרִיךְ לוֹמַר שֶׁלֹּא יִכְתֹּב בְּתוֹךְ הַגֵּט: עַל תְּנַאי זֶה גֵּרַשׁ פְּלוֹנִי אֶת פְּלוֹנִית, אֶלָּא כֵּיצַד עוֹשֶׂה, אוֹמֵר לַסוֹפֵר לִכְתֹּב, וְלָעֵדִים לַחְתֹּם, וְכוֹתְבִין גֵּט כָּשֵׁר בְּלֹא שׁוּם תְּנַאי בָּעוֹלָם, וְאַחַר כָּךְ נוֹתֵן לָהּ הַגֵּט וְאוֹמֵר לָהּ: הֲרֵי זֶה גִּטֵּךְ אוֹ הֲרֵי אַתְּ מְגֹרֶשֶׁת מִמֶּנִּי עַל מְנָת כָּךְ וְכָךְ, \u0010c0\u0011 אוֹ יֹאמַר [לָהֶם אוֹ] לְשָׁלִיחַ: תְּנוּ לָהּ גֵּט זֶה עַל מְנָת כָּךְ וְכָךְ:\nכָּתַב הַתְּנַאי בַּגֵּט \u0010c1\u0011 אַחַר שֶׁגָּמַר לִכְתֹּב תֹּרֶף הַגֵּט, הֲרֵי זֶה כָּשֵׁר, בֵּין שֶׁכָּתְבוֹ קֹדֶם חֲתִימַת הָעֵדִים בֵּין שֶׁכָּתְבוֹ אַחַר חֲתִימַת הָעֵדִים. אֲבָל אִם כָּתְבוֹ קֹדֶם תֹּרֶף הַגֵּט, אֲפִלּוּ כָּתַב עַל מְנָת כָּךְ וְכָךְ, הֲרֵי זֶה סְפֵק גֵּרוּשִׁין, שֶׁהֲרֵי נִשְׁאָר לוֹ זְכוּת בְּגוּפוֹ שֶׁל גֵּט. וְכֵן אִם הִתְנָה עַל פֶּה קֹדֶם כְּתִיבַת \u0010c2\u0011 הַתֹּרֶף, הֲרֵי זֶה סְפֵק גֵּרוּשִׁין:\nכָּל מְגָרֵשׁ עַל תְּנַאי שֶׁמְּבַטֵּל הַגֵּט, \u0010c3\u0011 כְּגוֹן שֶׁהִתְנָה לָהּ שֶׁלֹּא תֹּאכַל בָּשָׂר וְלֹא תִּשְׁתֶּה יַיִן כָּל יְמֵי חַיֶּיהָ, אוֹ שֶׁתִּהְיֶה מֻתֶּרֶת לְכָל אָדָם חוּץ מִפְּלוֹנִי, אוֹ שֶׁהִתְנָה עָלֶיהָ שְׁאָר תְּנָאִים קֹדֶם כְּתִיבַת הַתֹּרֶף, אִם הָיָה הַתְּנַאי כָּתוּב בַּגֵּט וְחָזַר וּמְחָקוֹ וּנְתָנוֹ לָהּ, הֲרֵי זֶה סְפֵק \u0010c4\u0011 מְגֹרֶשֶׁת; וְאִם הָיָה הַתְּנַאי עַל פֶּה, \u0010c5\u0011 הֲרֵי זֶה נוֹטֵל הַגֵּט מִמֶּנָּה וְחוֹזֵר וְנוֹתְנוֹ לָהּ בְּלֹא תְּנַאי כְּלָל, אוֹ בִּתְנַאי כָּשֵׁר:",[],["\u0003או יאמר לשליח\u0004. ואם הוא ירט לדרכו ומוכרח לילך קודם כתיבת הגט ורוצה לצוות שיכתבו גט וליתן לשליח על התנאי אז יצוה שיכתבו ויתנו ליד השליח זה ולא יזכיר שום תנאי ואחר כך יאמר לשליח זה לפני עדים אחרי' אותו גט שצוויתי ליתן לידך ואתה תתן לה לאשתי ע\"מ כך וכך והסופר והעדי' לא ידעו מזה כלל כן כתב בחדושי רש\"ך בשם מהריב\"ל:","\u0003אחר שגמר לכתוב תורף\u0004. היינו תנאי ע\"מ כשר אבל תנאי המבטל הגט כגון חוץ או תנאי שלא תשת' יין כל ימי חייה פסול ותנאי ע\"מ דכשר היינו כשנתקיים התנאי או חזר ומחקו מיהו מחק קי\"ל דפסול כמ\"ש בסי' קכ\"ה:","\u0003הרי זה ספק גירושין\u0004. כן כתב הרמב\"ם בתנאי ע\"מ קודם התורף בין בכתב ובין בע\"פ אפי' אם נתקיים מ\"מ בעת הכתיבה א\"י אם יתקיים לא הוי ספר כריתות ואין אומרי' יש ברירה ועיין ביש\"ש פ' מרובה וא\"י איך מישב דין זה דע\"כ טעמו של הרמב\"ם משום ברירה דאין אומרי' יש ברירה, מיהו רוב פוסקי' חולקי' על הרמב\"ם וס\"ל תנאי ע\"מ וכתב לפני התורף פסול מדרבנן דגזרי' אטו תנאי חוץ ולדעת הר\"ן ובעל המאור וכמה פוסקי' תנאי ע\"מ בע\"פ קודם התורף כשר דס\"ל אפי' חוץ בע\"פ קודם התורף אינו פסול אלא מדרבנן דגזרי' אטו אם כותב חוץ מ\"ה תנאי ע\"מ בע\"פ כשר, מיהו לרש\"י ותוספת התנאי ע\"מ פסול אם התנה קודם התורף דס\"ל חוץ פוסל על פי הדין קודם התורף אפי' בע\"פ לכן גזרינן ע\"מ אטו חוץ, מיהו לתוספת ע\"מ ונתקיים כשר אפי' בכתב, נמצא תנאי ע\"מ ונתקיים כשר לכל הפוסקי' רק לרש\"י ורמב\"ם פסול ונ\"מ במקום עיגון יש לסמוך על רוב הפוסקי' וכ\"פ הבית יוסף, וחוץ בכתב אפי' אחר התורף לדעת הרמב\"ם הגט בטל כמ\"ש פ\"ח, ותוספ' והר\"ן כתבו דאינו אלא פסול מדרבנן והא שכתב הרמב\"ם ס\"פ הנ\"ל חוץ וכתב אחר התורף שהוא ספק הגט היינו בחזר ומחקו אז הוי ספק דא\"י בתחלה אם ימחקו אבל כשעדיין כתב בגט ס\"ל הגט בטל כמ\"ש שם דין ה' והיינו לשיטות הרמב\"ם בכל הסוגי' לאו משום גזירה פסול אלא מה שפסול הוא פסול על פי הדין כגון ע\"מ קודם התורף בין בכתב בין בע\"פ, לכן ע\"מ אחר התורף אפילו בכתב כשר ולא גזרינן אטו חוץ אבל לשיטות הר\"ן ושאר פוסקי' גזרי' זה אטו זה אם כן ע\"כ חוץ אחר התורף בכתב אינו אלא מדרבנן מ\"ה לא גזרי' ע\"מ אטו חוץ לפ\"ז אפי' לא מחקו וביטלו התנאי מ\"מ כשר הגט מדאוריית' אף על גב אם אומר לה בעת הנתינה חוץ לפלוני הגט בטל כמ\"ש בסי' קל\"ז ואפילו תנאי חוץ בכתב לפני התורף וחזר ומחקו לרמב\"ם נראה שהוא ספק גט משום אין ברירה ולשיטות שאר פוסקי' פסול דאוריית' הוא דלא כתב לשם כריתות וכן מדויק בתוספת ולכאורה י\"ל כשם דלרמב\"ם לא אמרי' שום גזיר' לרבנן אלא הכל פסול ע\"פ הדין אף על גב לרבי גזרי' זה אטו זה מ\"מ רבנן לא גזרו כן י\"ל אליבא תו' לרבי גזרי' אחר התורף אטו לפני התורף אבל רבנן לא גזרו אחר התורף אטו לפני התורף אלא אם הכל לפני תורף אז גזרי' זה אטו זה וחוץ אחר התורף לאו משום גזירה אטו לפני התורף פסול אלא רבנן ס\"ל כיון שנכתב בגט הוי כאלו אמר בעת הנתינה חוץ לפלוני ופסול ובזה מיושב מה שהקשה הר\"ן על תוס' דס\"ל חוץ בע\"פ לפני התורף פסול ע\"פ הדין למה לא גזרי' חוץ אחר התורף בע\"פ אטו חוץ לפני התורף בע\"פ ולמ\"ש ניחא:","\u0003כגון שהתנה לה וכו'\u0004. היינו אלו תנאים אפי' אחר התורף או שהתנה שאר תנאים ע\"מ קודם התורף וחזר ומחקו ס\"ל לרמב\"ם ספק גט הוא כ\"כ המגיד אבל חוץ ולא נמחק הגט בטל ותנאי ע\"מ אחר התורף כשר אפי' לא נמחק כמ\"ש בש\"ס הטעם הוא משום בעת הכתיבה נכתב שפיר וגם ליכא שיור אלא תנאי אבל חוץ אפי' אחר התורף איכ' שיור אף על גב דנכתב שפיר מ\"מ איכ' שיור אף על גב חזר ומחק מ\"מ בעת הכתיבה היה שיור והוה ספק אם ימחק כל זה הוא לשיטות הרמב\"ם ושיטות שאר הפוסקי' כתבתי בסמוך ואם היה התנאי ע\"פ היינו תנאי חוץ, אף על גב דמבואר בש\"ס לכולי עלמא חוץ לאחר התורף אינו פוסל בע\"פ היינו דוק' בע\"פ לא בעת נתינת הגט:","\u0003אבל אם התנה\u0004. בעת הנתינה אז הגט בטל כמ\"ש בסי' קל\"ז אלא אם כן יחזור ויקח ממנה ותנאי דא\"א לקיים אינו פוסל אפי' בכתב קודם התורף כ\"כ הרשב\"א והמגיד:","\u0003הרי זה נוטל הגט ממנה\u0004. היינו דוקא בתנאי חוץ דפוסל לכהונה מהני נתינת הגט מ\"ה צריך ליקח ממנה הגט אבל תנאי כל ימי חייה דאינו פוסל לכהונה כמה שכתב ברמב\"ם דכתב ביה אינו גט והיינו דאינו פוסל לכהונה כמ\"ש פי' אז א\"צ ליקח ממנה ולא כב\"י שכתב אפילו בתנאי כזה צריך ליקח ממנה ובזה מדויק ברמב\"ם שכתב אחר דין זה כיצד אמר לה חוץ לפלוני וכו' כוונתו לבאר דין זה לא קאי אלא על תנאי חוץ, ובשאר תנאים שמתנה עמה ע\"מ כך וכך כשחוזר ומבטל בטל התנאי ואין צריך ליקח ממנה הגט כמ\"ש בסי' קמ\"ג במחילת התנאי ליתן ר' זוז או בגד וכלי וכן בתנאי אם אין צריך ליקח ממנה הגט כשמבטל התנאי ולא כב\"ח בסימן קמ\"ג סעיף כ\"ב ע\"ש והא דמהני כשחוזר ונוטל ממנה הגט היינו דוק' כשנכתב שפיר אלא בעת המסירה לידה התנה תנאי כהנ\"ל אבל אם התנה תנאי קודם כתיבת התורף אפילו תנאי ע\"מ דפוסל לרמב\"ם לא מהני כשחוזר ונוטל ממנה דהא עכ\"פ לא נכתב הגט בכשרות ומכ\"ש כשנכתב התנאי בגט אפילו אם חזר ומחק לא מהני ועיין במגיד ובב\"י, ותנאי מעכשיו אם מתי עי' בטור סס\"ז ויתבאר בסי' אח\"ז בס\"ד:"]],["מִי שֶׁכָּתַב לְגָרֵשׁ אֶת אִשְׁתּוֹ, וְנִמְלַךְ וְלֹא גֵּרְשָׁהּ, וְנִתְיַחֵד עִמָּהּ אַחַר שֶׁכְּתָבוֹ, \u0010c0\u0011 לֹא יְגָרְשֶׁנָּהּ בְּאוֹתוֹ הַגֵּט פַּעַם אַחֶרֶת כְּשֶׁיִּרְצֶה לְגָרְשָׁהּ. \u0010c1\u0011 וְאִם גֵּרְשָׁהּ בְּאוֹתוֹ הַגֵּט הַיָּשָׁן, \u0010c2\u0011 הֲרֵי זוֹ מְגֹרֶשֶׁת וְתִנָּשֵׂא בּוֹ לְכַתְּחִלָּה, שֶׁהֲרֵי נִכְתַּב לִשְׁמָהּ וַהֲרֵי נָתַן לָהּ עַתָּה בְּעֵדִים כְּהִלְכָתוֹ. וְלָמָּה לֹא יְגָרְשֶׁנָּה בּוֹ \u0010c3\u0011 לְכַתְּחִלָּה, גְּזֵרָה שֶׁמָּא יֹאמְרוּ גִּטָּהּ קוֹדֵם לִבְנָהּ. \u0010c4\u0011 וְיֵשׁ אוֹמְרִים דְּהָנֵי מִלֵּי כְּשֶׁהַגֵּט בְּיַד הַבַּעַל וּמְסָרוֹ מִיָּדוֹ לְיָדָהּ, אֲבָל אִם שְׁלָחוֹ לָהּ עַל יְדֵי שָׁלִיחַ, וְנִתְיַחֵד עִמָּהּ אַחַר שֶׁנְּתָנוֹ לְיַד הַשָּׁלִיחַ, וּנְתָנוֹ לָהּ הַשָּׁלִיחַ, לֹא תִּנָּשֵׂא בּוֹ, וְאִם נִשֵּׂאת, לֹא תֵּצֵא:\nכָּל הַמְגָרֵשׁ עַל תְּנַאי, בֵּין שֶׁאָמַר: מֵעַכְשָׁו, בֵּין שֶׁאָמַר: אִם יִהְיֶה וְאִם לֹא יִהְיֶה, הֲרֵי זֶה \u0010c5\u0011 לֹא יִתְיַחֵד עִמָּהּ כָּל זְמַן שֶׁלֹּא נִתְקַיֵּם הַתְּנַאי, אֶלָּא בִּפְנֵי עֵד, אֲפִלּוּ עֶבֶד וַאֲפִלּוּ שִׁפְחָה, \u0005 וּבְיוֹצֵא וְנִכְנָס סָגֵי, \u0006 חוּץ מִשִּׁפְחָתָהּ אוֹ בְּנָהּ הַקָּטָן, מִפְּנֵי שֶׁאֵינָהּ בּוֹשָׁה לְשַׁמֵּשׁ בִּפְנֵיהֶם. וְהַדָּבָר יָדוּעַ שֶׁאִם נִתְיַחֵד עִמָּהּ בִּפְנֵי שְׁנֵי עֵדִים כְּאֶחָד, \u0010c6\u0011 וְרָאָה הוּא וְהִיא אוֹתָם, אֲפִלּוּ נִתְקַיֵּם הַתְּנַאי אַחַר כָּךְ, הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת, שֶׁמָּא בְּעָלָהּ וּבִטֵּל הַגֵּט, וְיִתְבָּאֵר בְּסִימָן שֶׁאַחַר זֶה:",[],["\u0003לא יגרשנה\u0004. אפילו אם ליכא החשש משום דנתאחר אחר הכתיבה כגון דשולח ע\"י שליח וברמב\"ם שכתב דין זה אין צריך לומר דשולח ע\"י שליח כי הוא ס\"ל נתאחר כשר למ\"ש בסי' קכ\"ז מיהו קשה על הרמב\"ם למה ליה הטעם משום גיטה קודם לבנה ת\"ל שמא ביטל הגט כמ\"ש ס\"ס קמ\"ד ואז הוי ספק גט ותצא וכן הוא משמעות במגיד פ\"ט דין כ\"ה וכאן לא איירי שנתן נאמנות לאשתו וכן בש\"ס לא איירי דנתן נאמנות לאשתו דהיא נאמנת לומר שלא פייסה וא\"ל הרמב\"ם איירי דנותן הגט מידו לידה אז אמרי' דאלו פייסה וביטל הגט לא היה נותן הגט אבל בסי' קמ\"ד הגט כבר בידה א\"כ קשה היינו דעת הי\"א שהביא כאן ואפשר לומר לדעת הרמב\"ם אפילו אם הגט ביד השליח אמרינן אלו ביטל הגט היה משלח לשליח שאל ימסור הגט ובסי' קמ\"ד איירי כשהגט ביד האשה אם כן אם פייסה כבר אמר להאשה ויודעת דהגט בטל ומה לו לעשות יותר וי\"א שהב\"י ס\"ל כיון שהגט לאו בידו חיישינן יותר ולא תנשא בו מיהו פ\"ט דין כ\"ה לא משמע כן דאל\"כ למה לא אמרי' שם ג\"כ דאלו בטלו השליחות סופר והעדי' למה לא אמר להם וצ\"ע:","\u0003ואם גירש' וכו'\u0004. ה\"ה אם הלך הבעל מ\"י תנשא כמ\"ש בהג\"מ ובד\"מ סי' קמ\"ט הביא דבריו וע\"ש:","\u0003ותנשא בו לכתחלה\u0004. כ\"כ הרמב\"ם משמע אפי' אם הבעל בכאן אין צריך גט אחר וכן מוכח מהרא\"ש פ' הזורק מה שהקשה ממשליש גט לאשתו מיהו רש\"י והר\"ן כתבו דוק' כשהלך הבעל למ\"י אז תנשא בו לכתחלה, ואם בוודאי בא עליה עיין סי' קמ\"ט:","\u0003גזירה שמא יאמרו וכו'\u0004. כלומר שיאמרו נתן הגט באותו יום שנכתב ואחר כך נתעברה ממנו ואיכ' פגם לולד ולא אמרינן דליכ' פגם לולד משום אם בא עליה בוודאי בועל לשם קידושין כמ\"ש בסימן אח\"ז כי לפעמים תנשא היא לאחר א\"כ ע\"כ לא קידש אותה, פרישה ולירושלמי שהביאו תוס' והר\"ן פ' הזורק מבואר אם גרשה מחמת ערות דבר לא חיישינן שמא בא עליה דמאוסה היא בעיניו, ובזה יש לתרץ קושית תוס' דף פ\"א דס\"ל לב\"ש המגרש לאשתו ולן עמה בפונדק לא חיישין לקידושין משום ב\"ש ס\"ל אדם עושה בעילתו ביאת זנות וביבמות ס\"ל לב\"ש אין אדם עושה בעילתו ביאת זנות ולמ\"ש י\"ל ב\"ש לטעמי' דס\"ל אין אדם מגרש את אשתו אא\"כ מצא בה ערות דבר מ\"ה ס\"ל ע\"כ עשה בעילת זנות, מיהו י\"ל מדויק הלשון מ\"ש אדם עושה בעילתו משמע לעולם קאמר וכתבו בח\"ר אף בארוסה חיישינן לג\"י ול\"ד למ\"ש בסי' קמ\"ט שם כבר גירש אותה אבל אם כתב גט ולא נתן חיישינן שמא בא עליה כיון דעדיין לא גירש:","\u0003וי\"א דה\"מ וכו'\u0004. כ\"כ הרא\"ש בשם הרמ\"ה ובזה מיושב הסוגי' כמ\"ש בתנאי אם אעבור נגד פניך ל' יום וכמ\"ש בסי' קמ\"ד דאית' שם בש\"ס לגט ישן לא חיישינן שהרי לא נתייחד עמה מבואר אם נתייחד עמה חיישינן לג\"י אף על גב דכבר נתן הגט ליד' ע\"כ צ\"ל הא דכשר הגט כשכבר נתן לידה היינו דוק' אם הגט היה בידו בעת היחוד אבל אם שולח הגט ע\"י שליח או אם הגט כבר בידה גרע טפי, ומ\"ש המחבר ומסרו מידו לידה ל\"ד אפילו אם שלח אח\"כ ע\"י שליח נמי הגט כשר כיון שהיה בידו בעת היחוד בזה תליא הכל ובחדושי רש\"ך הקשה איך אפשר לומר דמסר הגט מידו לידה הא קי\"ל כשנתאחר הגט אחר הכתיבה אין תקנה לדבר אלא לשלוח ע\"י שליח כמ\"ש בסי' קכ\"ז ובדרישה וב\"ח בק\"א הביאו קושיא זו ותירץ ב\"ח דאיירי כאן בנתייחד עמה באותו יום אף על גב באותו יום לא שייך לומר גיטה קודם לבנה גזרינן אטו אם יתאחר יותר ואנ\"ל איך שייך לגזור בכה\"ג כיון דאם יתאחר ונותן לידה פסול בלא זה ולמה יש לגזור אטו יתאחר ולמ\"ש על הסוגי' דאמר הטעם משום ג\"י ולא אמר הטעם משום גט מאוחר דנ\"מ מטעם שאמר שם אין תקנה לכתחלה אפילו אם רוצה לשלוח כי אפי' אם שולח ע\"י שליח נמי איכא החשש גט קודם לבנה כי לפעמי' יתעכב הדבר ב' ג' שנים כמ\"ש ברש\"י וכ\"כ בדרישה סימן קל\"ב וכן מוכח בהרא\"ש פ\"ב דגיטין דף י\"ז לתירץ הראשון דכתב כל הגיטין אשר לא נמסרו ביום הכתיבה יש לו קול וליכ' חשש משום זנות ומשום פירות א\"כ קשה איך תמצא החשש גיטה קודם לבנה אלא ודאי אף על גב דיש לו קול וליכ' חשש משום בת אחותו ופירות מכל מקום איכא חשש משום גיטה קודם לבנה כן יש לתרץ קושיא זו בש\"ס מיהו הרמ\"ה והרא\"ש פ' הזורק והטור סימן קמ\"א כתבו הלשון דמוסר הגט מידו לידה דמשמע דאינו נותן ע\"י שליח קשה קושיא הנ\"ל איך אפשר דנותן מידו ליד' כיון דנתאחר בשלמא הרמ\"ה שכתב דין זה י\"ל משום דס\"ל נתאחר כשר כמ\"ש בסימן קכ\"ז אלא על הרא\"ש והטור קשה כהנ\"ל וצ\"ל הם כתבו לענין אם כבר נתן מידו לידה תנשא אבל לכתחלה לא יתן מידו לידה אלא בדיעבד אם כבר נתן תנשא אף על גב דנתאחר דלא גרע מאם נתעכב אחר הכתיבה קודם החתימה דסבירא ליה להרא\"ש דכשר בעת הדחק ונתאחר אחר הכתיבה והחתימה עדיף טפי דהא הרמב\"ם ס\"ל נתאחר כשר ונתעכב בין כתיבה לחתימה פסול ועת הדחק בנתעכב היינו אם כבר ניתן הגט כמ\"ש כמה פעמי' אם ניתן הגט דומה לעת הדחק ולא ניתן אבל אם הגט כבר ביד השליח לא מהני עת הדחק ולא תנשא:","\u0003לא יתייחד עמה\u0004. אפילו שכ\"מ נוט' למות וגוסס אסור להתייחד בלא עד תשובת רשב\"א ד\"א ועיין סדר הגט סעיף ק':","\u0003וראה הוא והיא וכו'\u0004. היינו הטעם אם נתייחד עמה חיישינן לקדושין שמקדש אותה מחדש מ\"ה בעינן שראו העדי' כמ\"ש בסי' מ\"ב וכ\"פ בספרו ב\"י הטעם משום קידושין, אף על גב בתנאי אם עדיין לא נתקיים התנאי והיא עדיין אשתו מ\"מ כיון לרמב\"ם אם נשאת לאחר קודם שנתקיים התנאי לא תצא אם נתקיים התנאי אחר כך י\"ל גם כן דשייך בה קידושין דמקדש אותה ואם נתקיים התנאי אחר כך נתקדשה היא לו למפרע מזה מוכח ג\"כ דהמחבר ס\"ל כרמב\"ם בענין אם נשאת קודם קיום התנאי לא תצא כמ\"ש בסי' קמ\"ג ובסי' קמ\"ו וא\"ל למה לי הטעם משום קדושין וצריך עדים ת\"ל שמא ביטלו הגט וי\"ל דנ\"מ אם נתן לה נאמנות כמ\"ש בסמוך גם נ\"מ אם התנה תנאי שאין ביד' לקיים אז אין חשש שביטלו כמ\"ש בסי' קמ\"ד ולדעת הטור אף על גב דמשמע דס\"ל כרמב\"ם דלא תצא אם נשאת קודם קיום התנאי כמ\"ש בסי' קמ\"ג ובסימן קמ\"ו מ\"מ ס\"ל דאין חשש קידושין בזה כיון דעדיין לא נתקיים התנאי אלא אם התנה תנאי אם יש חשש ג\"י ובחידושי רש\"ך כתב מ\"ש הדבר ידוע וכו' לא קאי על תנאי אם אלא על תנאי ע\"מ מיהו הב\"י בספרו לא כ\"כ, אבל זאת תימא על הטור מ\"ש בתנאי אם ונתייחד עמה קודם שנתקיים התנאי לא תתגרש בו לכתחלה אבל אם נתגרשה בו תנשא אפי' לכתחלה וזה סותר למ\"ש בתחילת הסימן ומ\"ש בסימן קמ\"א בשם הרמ\"ה אם אין הגט בידה לא תנשא ואין לחלק בין אם הגט ביד השליח לבין אם הגט בידה דהא הרא\"ש כתב בפרק הזורק דין ד' דקושי' הרמ\"ה על הסוגי' אם אעבור נגד פניך ל' יום דאית' שם לג\"י לא חיישינן כיון דלא נתייחד עמה כמ\"ש בש\"ס והקשה הא אפי' אם נתייחד עמה כשר כיון דכבר נתן לה וקי\"ל בג\"י אם נתן לה תנשא ומתוך כך תירץ ומחלק בין אם הגט בידו ונותן אחר כך אז כשר ותנשא ובין כשאין הגט בידו ש\"מ אם הגט בידה לא תנשא, ובזה נדחה נמי מ\"ש הב\"י על דברי הטור שכתב לא תתגרש בו אף על גב הגט בידה שייך לומר לא תתגרש בו כיון דלא חל הגט עד שעת קיום התנאי דא\"כ מה קושית הרא\"ש על הש\"ס הא שפיר קאמר לג\"י לא חיישינן הרי לא נתייחד עמה אבל אם היה חשש ג\"י אפילו אם הגט בידה לא תתגרש לכתחלה גם לשון הטור מ\"ש אבל נתגרשה בו תנשא תמוה לפי פירושו ובט\"ז פי' דאיירי שנתן הגט ליד השליח ליתן לה בזה מיושב לשון הטור גם י\"ל קושיא זו דאיירי הגט עדיין ביד השליח והשליח עדיין כאן אחר היחוד והיה יכול לומר לו שאל יתן הגט להאשה לכן אם נתן השליח אחר כך הגט לידה תתגרש ושכ\"מ המגרש על תנאי עיין סי' קמ\"ה:"]],["הַמְגָרֵשׁ אֶת אִשְׁתּוֹ, וְחָזַר וּבְעָלָהּ בִּפְנֵי עֵדִים, \u0005 אוֹ שֶׁגָּלוּי לַכֹּל שֶׁבָּא עָלֶיהָ, \u0010c0\u0011 כְּגוֹן שֶׁנְשָׂאָהּ \u0006 \u0005(הָרַ\"ן פֶּרֶק כָּל הַגֵּט)\u0006, \u0010c1\u0011 קֹדֶם שֶׁתִּנָּשֵׂא לְאַחֵר, בֵּין שֶׁגֵּרְשָׁהּ מִן הַנִּשּׂוּאִין בֵּין מִן הָאֵרוּסִין, הוֹאִיל וְאִשְׁתּוֹ הָיְתָה, הֲרֵי זוֹ בְּחֶזְקַת שֶׁהֶחֱזִירָהּ וּלְשֵׁם קִדּוּשִׁין בָּעַל וְלֹא לְשֵׁם זְנוּת. וַאֲפִלּוּ רָאוּ שֶׁנָּתַן לָהּ מָעוֹת, שֶׁחֲזָקָה הִיא שֶׁאֵין אָדָם עוֹשֶׂה בְּעִילָתוֹ בְּעִילַת זְנוּת וַהֲרֵי בְּיָדוֹ לַעֲשׂוֹתָהּ בְּעִילַת מִצְוָה. לְפִיכָךְ, \u0010c2\u0011 הֲרֵי זוֹ מְקֻדֶּשֶׁת קִדּוּשֵׁי וַדַּאי, וּצְרִיכָה מִמֶּנּוּ גֵּט שֵׁנִי:\nנִתְיַחֵד עִמָּהּ בִּפְנֵי שְׁנֵי עֵדִים, וְהָיוּ שְׁנֵי עֵדִים כְּאֶחָד, וְרָאוּ הוּא וְהִיא אֶת הָעֵדִים, אִם הָיְתָה מְגֹרֶשֶׁת מִן הַנִּשּׂוּאִין, חוֹשְׁשִׁין לָהּ שֶׁמָּא נִבְעֲלָה, וְהֵן הֵן עֵדֵי יִחוּד הֵן הֵן עֵדֵי בִּיאָה. לְפִיכָךְ, הִיא \u0010c3\u0011 סָפֵק מְקֻדֶּשֶׁת, וּצְרִיכָה גֵּט מִסָפֵק. וְאִם הָיְתָה \u0010c4\u0011 מְגֹרֶשֶׁת מִן הָאֵרוּסִין, אֵין חוֹשְׁשִׁין לָהּ, שֶׁהֲרֵי אֵין לִבּוֹ גַּס בָּהּ. וְאִי חָזֵינָן לְהוּ דְּגַיְסֵי אַהֲדָדֵי, חוֹשְׁשִׁין לָהּ. \u0005 הַגָּה: אֲבָל אִם נִתְיַחֵד עִם מְשֻׁדֶּכֶת שֶׁלּוֹ, אַף עַל גַּב דְּגָס בָּהּ, לֹא \u0010c5\u0011 חַיְשִׁינָן, אֶלָּא אִם כֵּן בָּא עָלֶיהָ בִּפְנֵי \u0006 \u0005 עֵדִים \u0006 \u0005(תְּשׁוּבַת הָרַמְבַּן סִימָן קל\"ה)\u0006:\nמִי שֶׁשָּׁלַח גֵּט לְאִשְׁתּוֹ, וְאַחַר כָּךְ בִּטְּלוֹ, וְהָלַךְ וְנִתְיַחֵד עִמָּהּ, וְאַחַר כָּךְ נִתְבָּרֵר שֶׁכְּבָר הִגִּיעַ הַגֵּט לְיָדָהּ קֹדֶם בִּטּוּלוֹ, אֵינָהּ צְרִיכָה מִמֶּנּוּ גֵּט שֵׁנִי, דְּוַדַּאי לֹא בָּעַל לְשֵׁם קִדּוּשִׁין, כִּי הָיָה סָבוּר שֶׁהַגֵּט הָיָה בָּטֵל, וְלֹא בָּעַל אֶלָּא עַל דַּעַת קִדּוּשִׁין הָרִאשׁוֹנִים:\nמִי שֶׁגֵּרַשׁ אֶת אִשְׁתּוֹ, וְנִתְיַחֵד עִמָּהּ, וְקֹדֶם שֶׁגֵּרְשָׁהּ שֵׁנִית לְקָחָהּ אֶחָד לְשֵׁם פִּילֶגֶשׁ, אֲסוּרָה לִשְׁנֵיהֶם וּצְרִיכָה גֵּט מִשְּׁנֵיהֶם:\nלֹא אָמְרוּ חֲזָקָה זוֹ דְּאֵין אָדָם עוֹשֶׂה בְּעִילָתוֹ בְּעִילַת זְנוּת, אֶלָּא בְּאִשְׁתּוֹ שֶׁגֵּרְשָׁהּ אוֹ בִּמְקַדֵּשׁ עַל תְּנַאי וּבָעַל סְתָם, שֶׁהֲרֵי אִשְׁתּוֹ הִיא וּבְאִשְׁתּוֹ הוּא שֶׁחֶזְקָתוֹ שֶׁאֵינוֹ עוֹשֶׂה בְּעִילַת זְנוּת עַד שֶׁיְּפָרֵשׁ שֶׁהִיא בְּעִילַת זְנוּת אוֹ יְפָרֵשׁ שֶׁעַל תְּנַאי הוּא בּוֹעֵל; אֲבָל שְׁאָר כָּל הַנָּשִׁים בַּחֲזָקָה שֶׁבָּעַל לְשֵׁם זְנוּת, עַד שֶׁיְּפָרֵשׁ שֶׁבָּעַל לְשֵׁם קִדּוּשִׁין:\nוְכֵן אִישׁ וְאִשָּׁה שֶׁהֵמִירוּ בְּאֹנֶס הַגְּזֵרוֹת, וְנִשְּׂאוּ זֶה לָזֶה בְּחֻקּוֹת הַכּוּתִים, אַף עַל פִּי שֶׁמִּתְיַחֲדִים זֶה עִם זֶה בְּכָל יוֹם לְעֵינֵי הַכֹּל, אֵין חוֹשְׁשִׁין לָהֶם מִשּׁוּם קִדּוּשִׁין \u0005 וְעַיֵּן לְעֵיל סִימָן כ\"ו: \u0006\nנִתְיַחֵד עִם אִשְׁתּוֹ אַחַר שֶׁאָמַר לִכְתֹּב וְלַחְתֹּם גֵּט וְלִתְּנוֹ לָהּ, הֲרֵי אֵלּוּ לֹא יִכְתְּבוּ. וְאִם כָּתְבוּ וְנָתְנוּ לָהּ אַחַר שֶׁנִּתְיַחֵד עִמָּהּ, \u0010c6\u0011 הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת:",[],["\u0003כגון שנשאה\u0004. כ\"כ תוספות ביבמות דף נ\"ב והר\"ן פרק כל הגט עיין סי' י\"ט מ\"ש ועיין תשובת ריב\"ש סימן ל\"א פסק כן ועיין סי' קכ\"א מיהו א\"י לענין מה כתב כאן דברי הר\"ן דהא כאן איירי לענין חשש קידושין א\"כ ממ\"נ אם נשאה כדין נשואין ת\"ל היה קידושין ואם לא נשאה כדין נישואין א\"כ מהיכ' תיתי לומר דבועל לשם קידושין, ודין של תוספות והר\"ן איירי בארוסה שכתב לה גט ולא נתן לה ונשאה אמרינן בוודאי בעיל וביטל הגט וגרע מגט ישן:","\u0003קודם שתנשא לאחר\u0004. כ\"כ הרמב\"ם והטור וא\"א לומר לאפוקי שתנשא לאחר ולא גירשה פשיט' דהא היא א\"א אלא אם נשאה וגרשה לא חיישינן לקידושין כיון דמחייב מלקות אם קדשה ובעל אף על גב בביאה נמי הוא עושה איסור מ\"מ בקדשה חייב מלקות לא חיישי' לקדושין וכ\"כ בש\"ג פ' מ\"ש דף תקפ\"ט:","\u0003קידושי ודאי\u0004. כ\"כ הרמב\"ם ומשמע דאז אין תופסין בה קידושין של אחר דוק' ביחוד תופסין קדושין של שני ולא בבעיל וכ\"כ ב\"ח:","\u0003ספק מקודשת\u0004. ואם נשאת לאחר תצא ומכ\"ש אם הבעל הלך למ\"י וא\"א ליתן לה גט אחר דלא תנשא ולא כהגמיי' דף תרי\"ז עיין בד\"מ, וכבר כתבתי אם גירש מחמת זנות לא חיישינן שמא בא עליה ואם שניהם מודים שלא בא עליה כתב בש\"ג שם דלא חיישינן שמא בא עליה וא\"צ גט שני ממנו וצל\"ע מנ\"ל דין זה כיון דקי\"ל הן הן עידי יחוד הן הן עידי ביאה הוי כאלו עדים מעידי' ע\"ז עיין ס\"ס קס\"ז:","\u0003מן האירוסין וכו'\u0004. דוק' בכה\"ג שכבר גרשה אבל אם כתב לה גט ועדיין לא נתן לה הגט ונתייחד עמה חוששין שמא בא עליה ופסול משום גט ישן ח\"ר:","\u0003אא\"כ בא עליה\u0004. לכאורה נראה מתשובת רמב\"ן אפי' בא עליה נמי אין חוששין לקדושין כיון שאין עסק קידושין ביניהם דוק' באשתו או בארוסה שהיה קדושין ביניהם חיישינן לקדושין אבל משודכת דמיא לאשה דעלמ':","\u0003הרי זו ספק מגורשת\u0004. וכאן ליכ' החשש שמא בא עליה ומקדש אותה דהא עדיין לא נכתב הגט וא\"ל החשש הוא שמא ביטל הגט אם כן קשה למה לא מהני נאמנות אלא הטעם הוא כשנתייחד עמה ס\"ל הרמב\"ם בוודאי ביטל שליחתו אף על גב גילוי דעת לא מהני מ\"מ כאן עשה מעשה ונתייחד עמה הוי כמעשה וגרע טפי מג\"י ולרמב\"ם הגט בטל, מיהו רבים חולקים עליו לכן פסק דהוי ספק מגורשת עיין ברמב\"ם פ\"ט דין כ\"ה ועיין בר\"ן ס\"פ הזורק:"]],["כָּל גֵּט שֶׁהוּא בָּטֵל מִן הַתּוֹרָה, אִם נִתְגָּרְשָׁה בּוֹ עֲדַיִן הִיא אֵשֶׁת אִישׁ גְּמוּרָה. וְאִם נִשֵּׂאת בּוֹ, תֵּצֵא וְהַוָּלָד מַמְזֵר, וּצְרִיכָה גֵּט מִשֵּׁנִי מִדִּבְרֵיהֶם, וּמֵהָרִאשׁוֹן מִן הַתּוֹרָה, לְהַתִּירָהּ לְעָלְמָא. וַאֲסוּרָה לִשְׁנֵיהֶם לְעוֹלָם. וְכָל י\"ג דְּרָכִים שֶׁנּוֹהֲגִין בְּאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם וְנִשֵּׂאת וְאַחַר כָּךְ בָּא בַּעְלָהּ, שֶׁנִּתְבָּאֲרוּ בְּסִימָן י\"ז, נוֹהֲגִים בָּהּ. \u0010c0\u0011 \u0005 וְיֵשׁ אוֹמְרִים דְּבַעְלָהּ הָרִאשׁוֹן יוֹרְשָׁהּ \u0006 \u0005(המ\"מ פֶּרֶק י' דְּגֵרוּשִׁין)\u0006. אֲבָל אִם לֹא נִשֵּׂאת עֲדַיִן, אֶלָּא נִתְקַדְּשָׁה, מֻתֶּרֶת לְבַעְלָהּ וְאֵינָהּ צְרִיכָה גֵּט מִשֵּׁנִי. וְכָל גֵּט שֶׁאֵינוֹ פָּסוּל אֶלָּא מִדִּבְרֵיהֶם לְהִנָּשֵׂא בּוֹ, לֹא תִּנָּשֵׂא בּוֹ לְכַתְּחִלָּה, וְאִם נִשֵּׂאת, אֲפִלּוּ לֹא נִבְעֲלָה, \u0010c1\u0011 לֹא תֵּצֵא, וְהַוָּלָד כָּשֵׁר; וְכוֹתְבִין לָהּ גֵּט אַחֵר, וְהִיא יוֹשֶׁבֶת תַּחַת בַּעְלָהּ. וְאִם אִי אֶפְשָׁר לִכְתֹּב לָהּ גֵּט, וְהָיָה הַבַּעַל וָתִיק וְגֵרַשׁ מֵעַצְמוֹ, הֲרֵי זֶה מְשֻׁבָּח. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאֵין לוֹ בָּנִים מִמֶּנָּה. אֲבָל אִם יֵשׁ לוֹ בָּנִים מִמֶּנָּה, לֹא יוֹצִיא, מִפְּנֵי שֶׁמּוֹצִיא לַעַז עַל הַבָּנִים. \u0005 מִיהוּ, נוֹתְנִין גֵּט אַחֵר כָּשֵׁר, \u0010c2\u0011 וְאֵין בָּזֶה מִשּׁוּם הוֹצָאַת לַעַז עַל הַבָּנִים \u0006 \u0005(פִּסְקֵי מהרא\"י סִימָן כ\"א)\u0006. \u0005 כָּל דָּבָר שֶׁאָנוּ מַחֲמִירִין בְּגִטִּין, וְהַגֵּט בְּלָאו הָכִי כָּשֵׁר אֶלָּא שֶׁמַחֲמִירִין לְכָתְבוֹ \u0010c3\u0011 לְכַתְּחִלָּה, אִם לֹא נִכְתַּב, הַגֵּט כָּשֵׁר \u0006 \u0005(מהרי\"ו סִימָן כ\"ג)\u0006:\nכָּל שֶׁהִיא סְפֵק מְגֹרֶשֶׁת, לֹא תִּנָּשֵׂא, וְאִם נִשֵּׂאת, תֵּצֵא, וְהַוָּלָד סְפֵק מַמְזֵר:\nכָּל גֵּט שֶׁהוּא בָּטֵל מִן הַתּוֹרָה, אִם הָיָה בַּעְלָהּ כֹּהֵן לֹא נֶאֶסְרָה עָלָיו מִשּׁוּם גְּרוּשָׁה, \u0010c4\u0011 חוּץ מֵהַמְגָרֵשׁ וְאָמַר לָהּ: הֲרֵי אַתְּ מְגֹרֶשֶׁת מִמֶּנִּי וְאֵין אַתְּ מֻתֶּרֶת לְכָל אָדָם, שֶׁאַף עַל פִּי שֶׁאֵין כָּאן גֵּט כְּלָל, פְּסוּלָה לִכְהֻנָּה:\nמִי שֶׁגֵּרַשׁ אֶת אִשְׁתּוֹ בְּגֵט שֶׁיֵּשׁ בּוֹ פִּסוּל מִדִּבְרֵיהֶם, אוֹ שֶׁהָיְתָה סְפֵק מְגֹרֶשֶׁת וְרָצָה לְהַחֲזִירָהּ, צָרִיךְ לְקַדְּשָׁהּ, \u0010c5\u0011 אֲבָל אֵינוֹ צָרִיךְ לְבָרֵךְ שֶׁבַע בְּרָכוֹת וְלֹא לִכְתֹּב לָהּ כְּתֻבָּה אַחֶרֶת:",[],["\u0003דבעלה הראשון יורשה\u0004. דהא הוא לא עביד איסור וכ\"פ ססי\"ו:","\u0003לא תצא\u0004. משמע אפילו גט מוקדם דפסול נמי רק מדרבנן לא תצא והר\"ן כתב בפ' המגרש בגט מוקדם תצא אם אין לה בנים ועיין סי' קכ\"ז:","\u0003ואין בזה משום לעז\u0004. דוק' כשתצא ממנו אז יש חשש לעז אבל ליתן גט אחר יאמרו לרווח' דמלת' עבדי רבנן כן, ובכל גיטין פסולין הדין כן חוץ כשהו' אינו נאמן כמ\"ש בסי' אח\"ז:","\u0003אם לא נכתב הגט כשר\u0004. דלא גרע מגט ישן דקי\"ל אם ניתן תנשא שם ברי\"ו ועיין במרדכי ר\"פ מ\"ש אם אמרי' בכל פיסולי דרבנן בשעת הדחק כשר ועיין תשובת מהר\"מ מינץ סי' ט' ועיין מ\"ש בסי' קכ\"ז:","\u0003חוץ מהמגרש וכו'\u0004. וה\"ה אם אמר חוץ לפלו' ואם התנה תנאי שעומדת בתנאי כל ימי חייה אין פוסל לכהונה כמ\"ש בסי' קמ\"ו ולרמב\"ם משמע דהא דאסורה לכהן כשאמר הרי את מגורשת ממני אינה אסורה אלא מדרבנן כי הדרוש שדרשו בש\"ס מקרא אשה גרושה מאישה אינו אלא אסמכת' ומשמע אפילו אם מגרש לכל אדם חוץ לפלוני נמי אין פוסל אלא מדרבנן מדלא כתב הרמב\"ם אין בתנאי חוץ דפוסל מדאוריית' אלא ודאי דנכלל הכל בדין א' ולשניהם דין א' ואין פוסל אלא מדרבנן ועיין במגיד שם ובש\"ג שם משמע דפוסל מדאוריית', וגט שחתומים עדים ולא נמסר לפני עדים פוסל לכהונה כ\"כ בד\"מ בשם ה\"ג דף תר\"ג מיהו למ\"ש בסי' קל\"ג לדעת הרבה פוסקים כשר הוא מדאוריית' לכן ספק גט הוא וגיטין הללו אינן פוסלים ליבם כמ\"ש בש\"ג שם:","\u0003אבל אין צריך לברך\u0004. גם יש איסור לברך בספק מגורשת דהא אין מברכין על הספק ואפילו בגט שהוא כשר מדאוריית' מ\"מ כיון שהו' פסול מדרבנן ואינה פנויה לגמרי אין מברכין, המגיד ועיין סי' ס\"א וסי' קמ\"ב:"]],["כָּתַב הַסוֹפֵר הַשּׁוֹבָר וְהַגֵּט, \u0010c0\u0011 וְטָעָה וְנָתַן הַשּׁוֹבָר לָאִישׁ, וְהַגֵּט לָאִשָּׁה, וְנָתְנוּם זֶה לָזֶה וְכִמְדֻמֶּה לָהֶם שֶׁנִּתְגָּרְשָׁה, וּלְאַחַר זְמַן עִרְעֵר הַבַּעַל לוֹמַר שֶׁלֹּא נִתְגָּרְשָׁה, שֶׁלֹּא נָתַן לָהּ אֶלָּא הַשּׁוֹבָר וַהֲרֵי הַגֵּט עֲדַיִן בְּיָדוֹ, \u0010c1\u0011 אִם לֹא נִשֵּׂאת עֲדַיִן, נֶאֱמָן, וִיגָּרְשֶׁנָּה עַכְשָׁו וּתְהֵא מֻתֶּרֶת מֵעַתָּה. וְאִם לֹא גֵּרְשָׁהּ, וְעָמְדָה וְנִשֵּׂאת, תֵּצֵא מִזֶּה וּמִזֶּה, וְכָל הַי\"ג דְּרָכִים בָּהּ. וְאִם לֹא עִרְעֵר הַבַּעַל עַד אַחַר שֶׁנִּשֵּׂאת, אֵינוֹ נֶאֱמָן לְאָסְרָהּ, וַהֲרֵי הִיא בְּחֶזְקַת גְּרוּשָׁה, שֶׁאָנוּ תּוֹלִין שֶׁנָּפַל מִמֶּנָּה וְהוּא מְצָאוֹ:",[],["\u0003וטעה ונתן\u0004. עיין סי' קל\"ה דקי\"ל כל גט צריכים לקרותו ואם לא קראוהו הגט פסול ואם נשאת תצא א\"כ ע\"כ איירי בקראוהו ועייל לידו והחליף אף על גב דלכתחלה צריכים לקרותו אחר שעייל לידו מ\"מ בדיעבד הגט כשר אא\"כ שמראה הגט קודם שנשאת כ\"כ תוס' ושאר פוסקים:","\u0003אם לא נשאת עדיין\u0004. ה\"ה נתארסה אינו נאמן לאבד זכות של שני כ\"כ ב\"ח בשם ח\"ר ומשמע בכל זה אין צריך גט מבעל הראשון אם נשאת או נתארסה לאחר, ואף למ\"ש בפסקי מהרא\"י דאין חשש לעז מה שהראשון נותן גט אחר כמ\"ש בסי' הקודם היינו בספק גט או בפסול מחמת הדין אבל בכה\"ג דהוא אינו נאמן לומר שלא גירש וא\"י לאבד הזכות של השני תו אינו נאמן ולא פלגינן דיבורו בכה\"ג:"]],["הַבַּעַל שֶׁאָמַר: גֵּרַשְׁתִּי אֶת אִשְׁתִּי, \u0010c0\u0011 אֵינוֹ נֶאֱמָן, וְחוֹשְׁשִׁין לִדְבָרָיו וְתִהְיֶה \u0010c1\u0011 סְפֵק \u0010c2\u0011 מְגֹרֶשֶׁת. וַאֲפִלּוּ הוֹדֵית לוֹ שֶׁגֵּרְשָׁהּ, אֵינָם נֶאֱמָנִים:\nהָאוֹמֶרֶת לְבַעְלָהּ: גֵּרַשְׁתַּנִי, וְהוּא מַכְחִישָׁהּ, נִתְבָּאֵר סִימָן י\"ז:\nשְׁנַיִם אוֹמְרִים: נִתְגָּרְשָׁה, וּשְׁנַיִם אוֹמְרִים: לֹא נִתְגָּרְשָׁה, אֲפִלּוּ הַבַּעַל עוֹמֵד וְהִיא אוֹמֶרֶת לוֹ גֵּרַשְׁתַּנִי, הֲרֵי זוֹ בְּחֶזְקַת אֵשֶׁת אִישׁ גְּמוּרָה, מִפְּנֵי שֶׁהָעֵדִים סוֹמְכִים אוֹתָהּ וְאֶפְשָׁר שֶׁתָּעִיז פָּנֶיהָ. לְפִיכָךְ, אִם נִשֵּׂאת, תֵּצֵא וְהַוָּלָד מַמְזֵר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁאָמְרוּ: עַכְשָׁו נִתְגָּרְשָׁה, שֶׁהֲרֵי אוֹמְרִים לָהּ: אִם אֱמֶת הַדָּבָר הוֹצִיאִי גִּטֵּךְ, אֲבָל אִם אָמְרוּ הָעֵדִים: מִכַּמָּה יָמִים נִתְגָּרְשָׁה, יֵשׁ לוֹמַר אָבַד הַגֵּט, וְהוֹאִיל וְהִיא אוֹמֶרֶת: גְּרוּשָׁה אֲנִי בְּוַדַּאי, וּשְׁנַיִם עֵדִים מְעִידִים לָהּ, אַף עַל פִּי שֶׁהַשְּׁנַיִם מַכְחִישִׁין אוֹתָם, אִם נִשֵּׂאת \u0010c3\u0011 לְאֶחָד מֵעֵדֶיהָ, לֹא תֵּצֵא, שֶׁהֲרֵי הִיא וּבַעְלָהּ יוֹדְעִים בְּוַדַּאי שֶׁהִיא \u0010c4\u0011 מֻתֶּרֶת, וַחֲזָקָה הִיא שֶׁאֵין מְקַלְקְלִים עַצְמָם. אֲבָל אִם נִשֵּׂאת לְאַחֵר, הוֹאִיל וְהַדָּבָר אֶצְלוֹ סָפֵק, וְכֵן אִם אָמְרָה: אֵינִי יוֹדַעַת, תֵּצֵא, וְהַוָּלָד סְפֵק מַמְזֵר. אֲבָל כָּל הֵיכָא דְּלֵיכָּא הַכְחָשָׁה, אֶלָּא שְׁנַיִם אוֹמְרִים: נִתְגָּרְשָׁה עַכְשָׁו, וְאָמְרִינָן לָהּ: אַחְזִינָן גִּטֵּךְ, וְאָמְרָה: נֶאֱבַד אוֹ נִקְרַע, לֹא חַיְשִׁינָן לָהּ:\nאָמְרוּ שְׁנַיִם: רְאִינוּהָ שֶׁנִּתְגָּרְשָׁה, וּשְׁנַיִם אוֹמְרִים: לֹא רְאִינוּהָ, \u0010c5\u0011 אֲפִלּוּ אִם הָיוּ כֻּלָּם שְׁרוּיִים בְּחָצֵר אַחַת, הֲרֵי זוֹ לֹא תִּנָּשֵׂא, וְאִם נִשֵּׂאת, \u0010c6\u0011 לֹא תֵּצֵא, וְהַוָּלָד כָּשֵׁר, שֶׁבְּנֵי אָדָם עֲשׂוּיִים לְגָרֵשׁ בְּצִנְעָא. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם אָמְרוּ שֶׁהָיוּ כֻּלָּם בְּמַעֲמָד אֶחָד, וּשְׁנַיִם אוֹמְרִים: לֹא רָאִינוּ, הָוֵי הַכְחָשָׁה, דְּכֻלֵּי הַאי לֹא עָבְדִי בְּצִנְעָא \u0006 \u0005(תא\"ו נכ\"ג ח\"ג)\u0006:\nאֶחָד אוֹמֵר: נִתְגָּרְשָׁה, וְאֶחָד אוֹמֵר: לֹא נִתְגָּרְשָׁה, לֹא תִּנָּשֵׂא, וְאִם נִשֵּׂאת, אִם הָיְתָה בְּחֶזְקַת אֵשֶׁת אִישׁ, תֵּצֵא בְּכָל עִנְיָן. וְאִם לֹא הָיְתָה בְּחֶזְקַת אֵשֶׁת אִישׁ, אֶלָּא עַל פִּיהֶם, אִם יֵשׁ הַכְחָשָׁה בְּעֵדוּתָן, כְּגוֹן שֶׁאֶחָד אוֹמֵר: \u0010c7\u0011 נִתְגָּרְשָׁה, וְאֶחָד אוֹמֵר: מֵעוֹלָם לֹא הָיוּ בָּהּ סְפֵק \u0010c8\u0011 גֵּרוּשִׁין, תִּנָּשֵׂא לְכַתְּחִלָּה. וְאִם שְׁנֵיהֶם מְעִידִים שֶׁהִיא אֵשֶׁת אִישׁ, אֶלָּא שֶׁזָּרַק לָהּ גֵּט, אֶחָד אוֹמֵר: קָרוֹב לוֹ, וְאֶחָד אוֹמֵר: קָרוֹב לָהּ, \u0005(אֲפִלּוּ)\u0006 אִם נִשֵּׂאת, תֵּצֵא:\nהָאִשָּׁה שֶׁבָּאָה וְאָמְרָה: \u0010c9\u0011 אֵשֶׁת אִישׁ הָיִיתִי וּגְרוּשָׁה אֲנִי, נֶאֱמֶנֶת, שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר. וְיֵשׁ אוֹמְרִים דַּוְקָא כְּשֶׁאָמְרָה כָּךְ בְּתוֹךְ כְּדֵי דִּבּוּר, אֶלָּא אִם כֵּן נָתְנָה אֲמַתְלָא לִדְבָרֶיהָ: \u0010c10\u0011\nאִם יֵשׁ עֵדִים שֶׁהָיְתָה אֵשֶׁת אִישׁ, אֵינָהּ נֶאֱמֶנֶת לוֹמַר: גְּרוּשָׁה אֲנִי, וְאִם נִשֵּׂאת, תֵּצֵא. וַאֲפִלּוּ אִם נִשֵּׂאת קֹדֶם שֶׁבָּאוּ הָעֵדִים שֶׁהֵעִידוּ שֶׁהָיְתָה אֵשֶׁת אִישׁ. \u0010c11\u0011 אֲבָל חוֹשְׁשִׁין לִדְבָרֶיהָ וּפְסוּלָה לִכְהֻנָּה לְעוֹלָם; וְאִם מֵת, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. \u0005 הַגָּה: בָּאוּ עֵדִים וְאָמְרוּ: שָׁמַעְנוּ שֶׁהִיא מְגֹרֶשֶׁת, אֵין זֶה עֵדוּת לְהוֹצִיא מֵחֶזְקָתָהּ, עַד שֶׁיָּעִידוּ שֶׁהִיא גְּרוּשָׁה \u0006 \u0005(רִיבָ\"שׁ סִימָן תק\"ד)\u0006. \u0005 אֲבָל אִם אֵין עֵדִים שֶׁהִיא אֵשֶׁת אִישׁ, רַק אוֹמְרִים: שָׁמַעְנוּ שֶׁנִתְקַדְּשָׁה וְנִתְגָּרְשָׁה, דִּינוֹ כְּקוֹל בְּעָלְמָא, וּכְדֶרֶךְ שֶׁנִתְבָּאֵר לְעֵיל סִי' מ\"ו: \u0006\nהָיוּ לָהּ שְׁנֵי עֵדִים שֶׁהִיא גְּרוּשָׁה, אַף עַל פִּי שֶׁאֵין שָׁם גֵּט, הֲרֵי זוֹ תִּנָּשֵׂא לְכַתְּחִלָּה:\nהוֹצִיאָה גֵּט מִתַּחַת יָדָהּ וְאָמְרָה: גֵּרְשַׁנִי בַּעְלִי בְּזֶה, הֲרֵי זוֹ נֶאֱמֶנֶת, וְתִנָּשֵׂא בּוֹ אַף עַל פִּי שֶׁאֵינוֹ מְקֻיָּם, כְּמוֹ שֶׁנִּתְבָּאֵר \u0005 בְּסִימָן קמ\"א וְקמ\"ב: \u0006\nבָּא הַבַּעַל וְעִרְעֵר, אִם אָמַר: מִמֶּנִּי נָפַל וּמָצְאָה אוֹתוֹ, אֵינוֹ נֶאֱמָן, שֶׁהֲרֵי הוֹדָה שֶׁכְּתָבוֹ לָהּ, וַהֲרֵי הוּא יוֹצֵא מִתַּחַת יָדָהּ. אֲבָל אִם אָמַר הַבַּעַל: עַל תְּנַאי הָיָה וַעֲדַיִן לֹא נִתְקַיֵּם הַתְּנַאי, \u0005(אוֹ)\u0006 פִּקָּדוֹן הָיָה, אוֹ מֵעוֹלָם לֹא כְּתַבְתִּיו, \u0005(אוֹ)\u0006 מְזֻיָּף הוּא, \u0010c12\u0011 יִתְקַיֵּם בְּחוֹתְמָיו אוֹ בְּעֵדֵי מְסִירָה, כְּמוֹ שֶׁנִּתְבָּאֵר \u0005 בְּסִימָן קמ\"א וְקמ\"ב \u0006 \u0005(סָעִיף י\"ג וְי\"ד)\u0006:\nוְאִם לֹא נִתְקַיֵּם, אֵינָהּ מְגֹרֶשֶׁת לִהְיוֹת מֻתֶּרֶת לַאֲחֵרִים, אֲבָל פָּסְלָה עַצְמָהּ מִכְּהֻנָּה:\nאִשָּׁה שֶׁיֵּשׁ בְּיָדָהּ מַעֲשֵׂה בֵּית דִּין, אֵינָהּ יְכוֹלָה לִנָּשֵׂא בּוֹ עַד שֶׁיֻּכְּרוּ חֲתִימוֹת יְדֵי הַבֵּית דִּין. \u0005(וְעַיֵן בְּסוֹף סִימָן קמ\"ב בַּהַגָּה)\u0006:",[],["\u0003אינו נאמן\u0004. אף על גב דיש לו מיגו דאי בעי יכול לגרש אותה השתא מ\"מ אינו נאמן דכל המגרש יש לו קול כ\"כ רש\"י והר\"ן ומסוגי' דש\"ס נראה הא דחוששין לדבריו והיא ספק מגורשת דוק' כשיש לו מיגו היינו כשאומר גרשתי היום אבל אם אומר גרשתי מאז ומקדם אינו נאמן כלל ומלשון הרמב\"ם והטור לא משמע כן אלא לעול' חוששין לדבריו וצ\"ל דס\"ל אפי' אם אמר גרשתי כבר פלגינן דבריו וחוששין לדבריו מכאן ולהבא ופסקו כמ\"ד שם דפלגינן דבריו:","\u0003ספק מגורשת\u0004. היינו לאחר מותו חולצת ולא מתייבמת גם אם זנתה אחר שאמר גרשתי הבנים ספק ממזרי' אבל א\"י לאסור עליו אם הוא כהן:","\u0003אפילו הודית לו\u0004. אף על גב האשה שאמרה לבעל' גרשתני נאמנת כמ\"ש בסימן י\"ז מ\"מ היכ' דהוא מסייעה אינה נאמנת עוד כתב הרמב\"ם שמא גירש אותה בגט פסול לפ\"ז אם קבלה קידושין אז /או/ אם אמרה גרשתני לא מהני אא\"כ אם הוא אומר לא גרשתי אבל אם הוא אומר גרשתי אף על גב היא התחילה לומר גרשתני לא מהני כי יש לחוש שמא בגט פסול גירש:","\u0003לאחר מעדיה\u0004. ומשום חשד ליכ' למיחש כי בשנים ליכא חשד כמ\"ש לעיל סי' י\"ב:","\u0003וחזקה הוא שאין מקלקלי'\u0004. כ\"כ הרמב\"ם ואפשר ליתן טעם למה כתב את זאת חזקה היא וכו' משום דקשה לי' קושית תוס' דהא היא קיימ' בחזקת א\"א והעד חייב חנק ותרצו תוס' דחזק' שלה מרעי חזקה זו כן הרמב\"ם מתרץ קושי' זו אלא לכאורה נראה מתוס' היכ' דהיא א\"י בוודאי שגרשה תו לא שייך חזקה הנ\"ל והולד ממזר ודאי דאוקמי אות' בחזקת א\"א ולא כרמב\"ם שכתב הולד ספק ממזר ואפשר אף על גב דאמרה א\"י הואיל ונשאת אח\"כ הוי כוודאי מדנשאת אח\"כ אמרי' אי לאו דיודעת לא היה נישאת לבעל:","\u0003אפילו אם היו כולם שרוים בחצר וכו'\u0004. רבות' זו קאי לענין אם נשאת לא תצא ומשמע מרמב\"ן דוק' אם אלו שאמרו לא ראינו שרוים בחצר זו אז לא תנשא דאי לאו הכי תנשא אפי' לכתחלה ועיין דרישה:","\u0003לא תצא\u0004. דעבדי אינשי דמגרשי בצנע' ש\"ס אף על גב דקי\"ל בעל שאמר גרשתי אינו נאמן אפילו כשיש לו מיגו הטעם משום מאן דמגרש יש לו קול כמ\"ש רס\"ז בשם רש\"י והר\"ן מ\"מ להכחיש עדים האומרי' דגירש אמרי' שמא גירש בצנע' ואפילו נשאת לאחר לא תצא הר\"ן:","\u0003נתגרשה\u0004. היינו מכמה ימים ואם נשאת לעד האומר מת עיין סי' י\"ז סעי' ל\"ז:","\u0003תנשא לכתחלה\u0004. אף על גב דתרווייהו אומרי' שהיתה א\"א מ\"מ הואיל אחד מהם עכ\"פ שקרן הוא דהא מכחישין זא\"ז א\"א להחזיקה לא\"א על פיהם והוי כאלו היה רק ע\"א שהיא א\"א אבל כשכ\"א אומר קרוב לי י\"ל דא' טועה ותרווייהו מעידים שהיא א\"א, ועיין ברמב\"ם פי\"ב ה\"ג משמע אפילו אם מכחישין זא\"ז תצא ועיין תשו' מהרשד\"מ סי' ס\"א ועיין סי' מ\"ז כתבתי לדעת תוס' לא אמרי' דטועה מיהו יש לחלק בין האי דהתם לדין דכאן, ואין לדמות לש\"ח וע\"א אומר תנאי היה וע\"א אומר דלא היה תנאי לא אמרינן תרוויי' מעידי' שהיה שטר טוב אלא אמרי' זה שאומר תנאי היה כוונתו בתחילת עדותו לסיים שהיה תנאי א\"כ קשה ה\"נ יש לומר דהיה כוונתו לסיים שהיה קרוב לה ואין כאן אלא ע\"א וי\"ל מ\"ש נתגרשה דומה לאומר נפרע השטר ולא כאומר תנאי היה וכשע\"א אומר נפרע השטר וע\"א אומר לא נפרע לא אתרע השטר ועיין כל זה בהר\"ן בסוגי' זו, ועיין בח\"ה סי' פ\"ב, ומשמע מר\"ן ומטור אפי' שאומרי' סתם שזרק לה הגט אמרי' דעבידי דטעו ולא הוי הכחשה אפי' לא אמר כמדומה לי ועיין פרישה:","\u0003אשת איש הייתי\u0004. נראה לי\"א קמיית' נאמנת אפילו אחר כ\"ד דהוי כמפרש דבריה מה שאמרה בתחלה א\"א הייתי היינו הייתי כבר ועכשיו גרושה אני אבל אם אמרה א\"א אני לכ\"ע אינה נאמנת אחר כ\"ד לומר גרושה אני דהא מכחשת דבריה אלא תכ\"ד נאמנת אפילו להכחיש דבריה וכמ\"ש בש\"ס בענין אם אמרה א\"א אני ואח\"כ אמרה פנויה אני דאינה נאמנת לאחר כ\"ד כמ\"ש בסי' מ\"ז אפילו דעת הרמ\"ה שהבי' הטור כל זמן שעסוקים באותו ענין נאמנת היינו דוק' באומרת א\"א הייתי ולא כב\"ח:","\u0003אם יש עדים\u0004. עיין סימן ז' שם איתא מ\"ש הרמב\"ם אם יש ע\"א דנשבית מותרת וכתב הב\"י שם דלמד מדתנא במתני' אם יש עדים משמע דוק' עדי' ולא ע\"א מזה נשמע כאן ג\"כ לא מהני ע\"א דהא תנא כאן ג\"כ עדים ואם קול יצא שיש עדים שהיא א\"א יש לדייק ממ\"ש שם ס\"ז דאסורה כי דוק' בשבוי' הקילו בה:","\u0003אבל חוששין לדבריה\u0004. הטור כתב בס\"ז כשאמרה שלא בפניו גרשני אינה נאמנת אפילו אם נשאת תצא משני בלא גט אף על גב דבא בעלה אחר הנשואין ואומרת בפניו גרשתני והקשה ב\"ח למה אין חוששין לדברי' לחומר' להצריכה גט משני כמה דחוששין כאן לדבריה לחומר' ותירץ התם אם היתה צריכה גט משני היתה אסורה על בעלה הראשון משום מחזיר גרושתו ולאו כל כמיניה לאוסרה עליו ואם מת בעלה קודם שהחזירה אסורה להנשא עד שתגרש זה המקדש משום דשויא נפשה חתיכ' דאיסור' לכל אדם ואכתי אין מיושב למה בנשאת תצא בלא גט דהא אסורה לבעלה בל\"ז היה לנו לחוש לדבריה לחומר' לכן נראה דהיא אינה נאמנת בשום דבר אלא היא יכולה לעשות את נפשה חתיכ' דאיסור' כגון הכא היא חתיכא דאסור' לכהן וליבם אבל להצריכה גט אין שייך לומר חתיכ' דאסור' אלא אם היתה נאמנת היתה צריכה גט ובאמת היא אינה נאמנת, לכן אפילו אם נתקדשה שלא בפניו ומת הבעל א\"צ גט לדעת הטור וכ\"כ בט\"ז וכל זה לדעת הטור אבל הר\"ן כתב בשם הרמב\"ן והרשב\"א בתשובה סי' תקס\"ח ואלף ת\"ג כתבו גם שם צריכה גט כי לקצת אמוראים בש\"ס אפילו שלא בפניו אינה מעיזה חיישינן לחומר' וצריכה גט משני:","\u0003יתקיים בחותמיו\u0004. ואז אין לו מיגו אינו נאמן אבל טענות אבד ונפל ממני אינו נאמן אפילו במקום מיגו ואם שנים מערערי' ואומרי' מזויף סביר' ליה הטור דמהני הקיום וכן כתב הבית יוסף בפשיטו' ועיין סי' קמ\"א סעי' נ\"ג ועיין דרישה סס\"ז ועיין תשו' הרא\"ש כלל מ\"ה ובטור סס\"ז אם העד אומר הבעל לא צוה לו לחתום נאמן ואפי' אם כ\"י יוצא ממקום אחר כי שכיח בעון הדור שרבים מתעסקי' בגיטין אף על פי שודעי' בו מעט וסבר כשבעל אומר כתבו דכוונתו שיחתום לפ\"ז ממשע אפילו שני עדים אומרי' כן ואין הסופר מסייע להם נאמנת ולא כב\"ה שכתב הטעם הואיל והסופר מסייע אף על גב דאין העדי' נאמני' לומר שטעו בשנת המלך כמ\"ש בח\"ה סי' מ\"ג ש\"ה דהא שמואל מספק' אם כתבו היינו חתמו והוי טעות שדרך לטעות בו, ומזה נשמע מ\"ש בח\"ה בהג\"ה ש\"ע סי' ח' בשם הרא\"ש דאין העדי' נאמני' לומר שטעו לא קאי על טעות שדרך לטעות והש\"ך שם מאריך בזה ואישתמט' תשובה זו וא\"ל כאן הטעם משום הסופר מסייע כי בוודאי אם אין העדי' נאמני' לא מהני מה שהסופר מסייע וב\"ח כתב הא דהעד נאמן לומר דבעל לא צוה לחתום משום דלא נעשה רשע אלא כשהוא רשע דחמס ותמוה דבריו דהא איכ' איסור דאוריית' וא\"צ רשע דחמס ואפשר כיון דאיכ' ע\"מ הוי חתימות רק איסור דרבנן מיהו קשה אפילו אם לא נעשה רשע מ\"מ כיון שהגיד אינו חוזר ומגיד דקי\"ל העדי' החתומי' נעשה כמו שנחקרה עדותן בב\"ד לכן אין העדי' נאמנים לומר דהיו אנוסי' מחמת נפשות כמ\"ש בש\"ס ובפוסקי' ובוודאי ל\"ד ועיקר הטעם כמ\"ש:"]],["הַמּוֹצֵא גֵּט אִשָּׁה בַּשּׁוּק, אִם הָאִשָּׁה נוֹתֶנֶת סִימָן, שֶׁאוֹמֶרֶת: נֶקֶב יֵשׁ בְּצַד אוֹת פְּלוֹנִי, וְאוֹמֶרֶת שֶׁכְּבָר נִתְגָּרְשָׁה בּוֹ וּמִמֶּנָּה נָפַל, יַחֲזִירוּהוּ לָהּ, אֲפִלּוּ אִם הַבַּעַל מַכְחִישָׁהּ וְאוֹמֵר שֶׁמִּמֶּנּוּ נָפַל וְלֹא גֵּרְשָׁהּ מֵעוֹלָם אֶלָּא שֶׁצִּוָּה לְכָתְבוֹ וַעֲדַיִן לֹא נְתָנוֹ; אֲפִלּוּ אִם גַּם הוּא נוֹתֵן בּוֹ סִימָן. וְאִם אֵינָה נוֹתֶנֶת בּוֹ סִימָן, וְהַבַּעַל מַכְחִישָׁהּ, לֹא יִתְּנוּהוּ \u0010c0\u0011 לֹא לוֹ וְלֹא לָהּ. וְאִם הַבַּעַל מוֹדֶה שֶׁכְּתָבוֹ, וְאוֹמֵר שֶׁיִּתְּנוּהוּ לָהּ לְהִתְגָּרֵשׁ, בְּמָקוֹם וּבְשָׁעָה שֶׁרָאוּי לְהַחֲזִיר, דְּלֵיכָּא לְמֵיחַשׁ שֶׁמֵּאַחֵר נָפַל עַל פִּי מַה שֶּׁנִּתְבָּאֵר בְּסִימָן קל\"ב, יִתְּנוּהוּ לָהּ \u0010c1\u0011 וְתִתְגָּרֵשׁ בּוֹ מֵעַתָּה; וְאִם לָאו, לֹא יִתְּנוּהוּ לָהּ. וְאִם הוּא מוֹדֶה שֶׁנִּתְגָּרְשָׁה בּוֹ, וְהִיא שׁוֹאֶלֶת אוֹתוֹ לִגְבּוֹת בּוֹ \u0010c2\u0011 כְּתֻבָּתָהּ, וְהוּא אוֹמֵר שֶׁכְּבָר פְּרָעָהּ וְהֶחֱזִירַתּוּ לוֹ וּמִמֶּנּוּ נָפַל, \u0010c3\u0011 מַחֲזִירוֹ לָהּ, \u0010c4\u0011 אֲפִלּוּ אֵינָהּ אוֹמֶרֶת: נֶקֶב יֵשׁ בְּצַד אוֹת פְּלוֹנִית, רַק בִּשְׁאָר סִימָן \u0005(שֶׁאֵינוֹ כָּל כָּךְ)\u0006 מֻבְהָק, כְּגוֹן שֶׁאוֹמֶרֶת: כָּךְ וְכָךְ אֶצְבָּעוֹת בְּאֹרֶךְ הַגֵּט אוֹ בְּרָחְבּוֹ, אוֹ שֶׁאוֹמֶרֶת מִדַּת הַחוּט הַקָּשׁוּר בּוֹ. אֲבָל אִם אָמְרָה: הַגֵּט הָיָה אָרֹךְ אוֹ קָצָר, וְאֵינָהּ מְכַוֶּנֶת מִדָּתוֹ, אוֹ הַחוּט לָבָן אוֹ שָׁחֹר, אוֹ שֶׁאָמְרָה שֶׁהוּא מֻנָּח בַּחֲפִיסָה אוֹ בִּדְלוֹסְקְמָא, אֵינוֹ סִימָן לְהַחֲזִירוֹ לָהּ עַל יָדוֹ:",[],["\u0003לא לו ולא לה\u0004. ע\"כ איירי הכא דנמצ' הגט במקום דליכ' למיחש דנפל מאחר כמ\"ש בסמוך ולא כב\"ח שכתב הטעם דחיישינן שמא מאחר נפל אלא הטעם הוא דחיישינן שמא גרשה ותביא ראיה וכשתבא לגבות הכתובה יאמר פרעתי והא ראיה דהגט בידי והיינו במקום שאין כותבין כתובה וגובאת בגט וכשהגט בידו יאמר פרעתי כמ\"ש בסי' ק\"י אבל כשהגט ביד הב\"ד אז כשתביא היא ראיה שגירשה א\"י לומר פרעתי וממני נפל דהא השתא הוא טוען שלא גירש הוי כאלו אמר לא פרעתי ובוודאי אין חשש שמא ישכחו הב\"ד מה שטוען השתא ובזה נדחה דברי הב\"ח שהבי' ראיה מזה לדברי הטור לענין כתובה היא נאמנת שממנה נפל דאפילו אם הוא נאמן היינו כשיאמר מיד ממני נפל ופרעתי אבל כאן איירי שאומר לא גרשתיך תו אינו נאמן לומר פרעתי, ולה אין מחזירין משום י\"ל דלא גירש אותה ומחמת הגט תנשא וכן פרש\"י אף על גב האשה האומרת גרשתני נאמנת הכא הגט מסייע לה מעיזה ועיין בסמוך:","\u0003ותתגרש בו מעתה\u0004. אפי' אם אמר הבעל שנתגרשה כבר בו ביום הכתיבה אינו נאמן על העבר אלא תתגרש מעתה כמ\"ש בתוספות פ\"ק דב\"ק דף י\"ח ודף י\"ט והיינו פירוש תוספות גיטין דף כ\"ד מ\"ש דאינו נאמן שתטרוף פירות מכאן ולהבא היינו מחמת דיבורו גרשתי אבל ליתן לה הגט היום נאמן כשאין חשש שנפל מאחר אף על פי שאומר שגירש כבר ונפל ממנו ומ\"ש הטור והמחבר אם הבעל מודה ואומר שיתנהו לה להתגרש נראה בוודאי לא פליג על תוס' אלא כוונתו דהשת' מרוצה ליתן לה בתורת גירושין אבל אם אומר שגרש' כבר ועכשו אינו רוצה שיתנהו לה א\"י ליתן לה בתורת גירושין ובב\"ח משמע אם אמר גירש כבר לא מהני כלל אפילו ליתן לה היום להתגרש ולית' ועיקר כמ\"ש וכל זה איירי כשאינה נותנת סי' אבל אם היא נותנת סי' מגורשת מיום הכתיבה, ולכאור' נראה דאין נותן לה הבעל אלא נותן לה ע\"י שליח וכיון דנתאחר בין הכתיבה לנתינה ואפשר הואיל לפ\"ד גירש כבר אף על גב דהוא אינו נאמן על העבר מ\"מ לא חיישינן בכה\"ג משום האיחור דאפשר דגירש אותה באותו יום:","\u0003והוא אומר שכבר פרעה\u0004. ואיירי נמי כשאין חשש שנפל מאחר דאל\"כ אפילו אם שניהם אומרי' דגרש' אינם נאמני' כיון דידוע דהיא היתה אשתו כמ\"ש בסי' קע\"א אף על גב שם איירי כשאומר שנתן לש\"ה הא כתבתי שם אפילו כשאומר גרשתי ג\"כ אינו נאמן למאי דקי\"ל בעל שאמר גרשתי אינו נאמן:","\u0003מחזירו לה בלא סי'\u0004. דכאן לא שייך סי' כיון דהגט היה ביד שניהם אלא הם מחולקי' בפרעון והא דמחזירי' לידה אף על גב דיש לו מיגו ממני נפל ולא גרשתי כדלעיל סי' ק' תירץ רש\"ל דלא שכיח שתחזור הגט משום דצריכה לראייה והיה לו לכתוב שובר או לקרוע ולכתוב על הגט גיטא דלא קרענוהו וכו' כמ\"ש בש\"ס:","\u0003אפילו אינה אומרת\u0004. על ר\"ס קאי דא\"צ לומר ס\"מ כי דווק' בחשש שמא נפל מאחר צריך ס\"מ כיון דאיכ' א\"ד אבל כאן דליכ' חשש שנפל מאחר אלא דא\"י אם ממנו נפל או ממנה והיא אומרת גרשתני והסימני' מסייעי' לה נאמנת אף על גב דאינה אומרת ס\"מ ואפשר אפי' לדעת המחמיר בסי' י\"ז כשאומרת גרשתני אינה נאמנת בזה\"ז מ\"מ כיון הסימני' מסייעי' לה נאמנת וכ\"כ בדרישה וב\"ח בשם רש\"ל דקאי על ר\"ס:"]],["אֵלּוּ שֶׁכּוֹפִין אוֹתָם \u0010c0\u0011 לְהוֹצִיא וְלִתֵּן כְּתֻבָּה: מִי שֶׁנּוֹלַד לוֹ רֵיחַ הַפֶּה אוֹ רֵיחַ הַחֹטֶם, אוֹ שֶׁחָזַר לִהְיוֹת מְקַבֵּץ צוֹאַת כְּלָבִים אוֹ בּוּרְסְקִי, אוֹ לִהְיוֹת מְחַתֵּךְ נְחשֶׁת מֵעִקָּרוֹ. וְאִם רָצְתָה תֵּשֵׁב עִם בַּעְלָהּ. \u0010c1\u0011 \u0005 וְאִם יָדְעָה \u0006 \u0005 בָּהֶן קֹדֶם שֶׁנִשֵּׂאת, אֵין כּוֹפִין לְהוֹצִיא, דְּסָבְרָה וְקִבְּלָה \u0006 \u0005(טוּר בְּשֵׁם הָרְמַ\"ה)\u0006. \u0010c2\u0011 נַעֲשָׂה הָאִישׁ מֻכֶּה שְׁחִין, כּוֹפִין אוֹתוֹ לְהוֹצִיא וְלִתֵּן כְּתֻבָּה; וְאַף עַל פִּי שֶׁהִיא רוֹצָה לֵישֵׁב עִמּוֹ, \u0005 אוֹ שֶׁהִתְנָה עִמוֹ קֹדֶם שֶׁנְשָׂאָהּ, \u0006 אֵין שׁוֹמְעִין לָהּ, אֶלָּא מַפְרִישִׁין אוֹתָם בְּעַל כָּרְחָם, מִפְּנֵי שֶׁהִיא מְמִיקַתּוּ. וְאִם אָמְרָה: אֵשֵׁב עִמּוֹ בְּעֵדִים, כְּדֵי שֶׁלֹּא יָבֹא עָלַי, שׁוֹמְעִין לָהּ. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּמוּמָר כּוֹפִין אוֹתוֹ עַל יְדֵי כּוּתִים לְהוֹצִיא \u0006 \u0005(ב\"י סִימָן קל\"ד בְּשֵׁם א\"ח וּבְמָרְדְּכַי פֶּרֶק הַמְגָרֵשׁ)\u0006, \u0005 וּבִלְבַד שֶׁיְּבַטֵּל בִּשְׁעַת הַגֵּט \u0006 \u0005(שָׁם בְּמָרְדְּכַי)\u0006. \u0005 וְיֵשׁ חוֹלְקִים וְאוֹמְרִים דְּאֵין כּוֹפִין לְמוּמָר אוֹ שְׁאָר עוֹבֵר עַל דָּת \u0006 \u0005(תְּשׁוּבַת מור\"ם)\u0006, \u0005 אֶלָּא אִם כֵּן פּוֹשֵׁעַ לָהּ, כְּגוֹן שֶׁמַאֲכִילָהּ דְּבַר אִסוּר \u0006 \u0005(מהרי\"ו סִימָן כ\"ב)\u0006, \u0005 אוֹ שֶׁעָבַר עַל חֵרֶם שֶׁשִּׁעְבֵּד עַצְמוֹ נֶגְדָּהּ שֶׁלֹּא לְהַקְנִיטָהּ וְשֶׁלֹּא לְהַכּוֹתָהּ, אוֹ שֶׁנוֹדֵר וְאֵינוֹ מְקַיֵּם שֶׁבָּנָיו מֵתִים בַּעֲוֹן נְדָרִים \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי סוֹף אִשּׁוּת)\u0006. \u0005 מִי שֶׁהוּא רוֹעֶה \u0006 \u0005 זוֹנוֹת וְאִשְׁתּוֹ קוֹבֶלֶת עָלָיו, \u0010c3\u0011 אִם יֵשׁ עֵדוּת \u0006 \u0005 בַּדָּבָר, שֶׁרָאוּ אוֹתוֹ עִם מְנָאֲפִים אוֹ שֶׁהוֹדָה, יֵשׁ אוֹמְרִים שֶׁכּוֹפִין אוֹתוֹ לְהוֹצִיא, אֲבָל מִשּׁוּם שֶׁמְבִיאִין לוֹ יְלָדִים כּוּתִים אֵין לָחוּשׁ, דִּלְמָא מְשַׁקְרִים עָלָיו \u0006 \u0005(חִדּוּשֵׁי אֲגֻדָּה דִּיבָמוֹת)\u0006:\nמִי שֶׁהָיָה בַּעְלָהּ בַּעַל רֵיחַ הַפֶּה אוֹ רֵיחַ הַחֹטֶם, אוֹ מְלַקֵּט צוֹאַת כְּלָבִים וְכַיּוֹצֵא בָּהּ, וּמֵת וְנָפְלָה לִפְנֵי אָחִיו וְיֵשׁ בּוֹ אוֹתוֹ מוּם שֶׁהָיָה בְּבַעְלָהּ, יְכוֹלָה הִיא לוֹמַר: לְאָחִיךְ הָיִיתִי יְכוֹלָה לְקַבֵּל וּלְךְ אֵינִי יְכוֹלָה לְקַבֵּל, וְיַחֲלֹץ וְיִתֵּן לָהּ כְּתֻבָּה:\nהָאוֹמֵר: אֵינִי זָן וְאֵינִי מְפַרְנֵס, \u0010c4\u0011 כּוֹפִין אוֹתוֹ לָזוּן. וְאִם אֵין בֵּית דִּין יְכוֹלִים לְכוֹפוֹ לָזוּן, כְּגוֹן שֶׁאֵין לוֹ בַּמֶּה לְפַרְנֵס וְאֵינוֹ רוֹצֶה לְהִשְׂתַּכֵּר לְהַרְוִיחַ וְלָזוּן, אִם תִּרְצֶה הִיא, \u0010c5\u0011 כּוֹפִין אוֹתוֹ לְהוֹצִיא מִיָּד \u0010c6\u0011 וְלִתֵּן כְּתֻבָּה. וְכֵן הַדִּין לְמִי שֶׁאֵינוֹ רוֹצֶה לְשַׁמֵּשׁ. \u0005 הַגָּה: וְכֵן אִישׁ שֶׁרָגִיל לִכְעֹס וּלְהוֹצִיא אִשְׁתּוֹ מִבֵּיתוֹ תָּמִיד, כּוֹפִין אוֹתוֹ לְהוֹצִיא, כִּי עַל יְדֵי זֶה אֵינוֹ זָנָהּ לִפְעָמִים וּפוֹרֵשׁ מִמֶנָה בְּתַשְׁמִישׁ יוֹתֵר מֵעוֹנָתָהּ וְהָוֵי כְּמוֹרֵד מִמְזוֹנוֹת וְתַשְׁמִישׁ \u0006 \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן תרצ\"ג)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן ע' וְסִימָן ע\"ז. אִישׁ הַמַכֶּה אִשְׁתּוֹ, עֲבֵרָה הִיא בְּיָדוֹ כְּמַכֶּה חֲבֵרוֹ. וְאִם רָגִיל הוּא בְּכָךְ, יֵשׁ בְּיַד בֵּית דִּין לְיַסְּרוֹ וּלְהַחֲרִימוֹ וּלְהַלְקוֹתוֹ בְּכָל מִינֵי רִדּוּי וּכְפִיָּה, וּלְהַשְׁבִּיעוֹ שֶׁלֹּא יַעֲשֶׂה עוֹד, וְאִם אֵינוֹ צַיִּת לְדִבְרֵי הַבֵּית דִּין יֵשׁ אוֹמְרִים שֶׁכּוֹפִין אוֹתוֹ לְהוֹצִיא, וּבִלְבַד שֶׁמַתְרִין בּוֹ תְּחִלָּה פַּעַם אַחַת אוֹ שְׁתַּיִם כִּי אֵינוֹ מִדֶּרֶךְ בְּנֵי יִשְׂרָאֵל לְהַכּוֹת נְשׁוֹתֵיהֶם, וּמַעֲשֵׂה כּוּתִים הוּא. וְכָל זֶה כְּשֶׁהוּא מַתְחִיל, אֲבָל אִם מְקַלַּלְתּוֹ בְּחִנָם אוֹ מְזַלְזֶלֶת אָבִיו וְאִמוֹ, וְהוֹכִיחָהּ בִּדְבָרִים וְאֵינָהּ מַשְׁגַּחַת עָלָיו, יֵשׁ אוֹמְרִים דְּמֻתָּר לְהַכּוֹתָהּ, וְיֵשׁ אוֹמְרִים דַּאֲפִלּו אִשָּׁה רָעָה אָסוּר לְהַכּוֹתָהּ. וְהַסְּבָרָא רִאשׁוֹנָה הִיא עִקָר. וְאִם אֵינוֹ יָדוּעַ מִי הַגּוֹרֵם, אֵין הַבַּעַל נֶאֱמָן לוֹמַר שֶׁהִיא הַמַתְחֶלֶת, שֶׁכָּל הַנָשִׁים בְּחֶזְקַת כְּשֵׁרוֹת, וּמוֹשִׁיבִין בֵּינֵיהֶן אֲחֵרוֹת לִרְאוֹת בְּשֶׁל מִי הָרָעָה הַזֹאת, וְאִם הִיא מְקַלַּלְתּוֹ חִנָם, יוֹצֵאת בְּלֹא כְּתֻבָּה. וְנִרְאֶה לִי, דַּוְקָא בִּרְגִילָה בְּכָךְ, וְאַחַר הַהַתְרָאָה, וּכְמוֹ שֶׁנִתְבָּאֵר לְעֵיל סִימָן קט\"ו. וְאִם הָלְכָה מִבֵּיתוֹ וְלָוְתָה וְאָכְלָה, אִם יָצְתָה מִכֹּחַ שֶׁהִכָּה אוֹתָהּ תָּמִיד, חַיָּב לְשַׁלֵּם \u0006 \u0005(כָּל דִּבְרֵי הַגָּ\"ה זוֹ תִּמְצָא בְּמָרְדְּכַי פֶּרֶק נַעֲרָה בְּשֵׁם מוהר\"ם וב\"ז סִימָן פ\"ח)\u0006, \u0005 וּכְמוֹ שֶׁנִתְבָּאֵר לְעֵיל סִימָן ע': \u0006\nהָאִישׁ שֶׁנּוֹלְדוּ בּוֹ מוּמִין אַחַר שֶׁנָּשָׂא, אֲפִלּוּ נִקְטַעַת יָדוֹ אוֹ רַגְלוֹ, אוֹ נִסְמֵת עֵינוֹ, וְלֹא רָצְתָה אִשְׁתּוֹ לֵישֵׁב עִמּוֹ, אֵין כּוֹפִין אוֹתוֹ לְהוֹצִיא וְלִתֵּן כְּתֻבָּה; אֶלָּא אִם רָצְתָה תֵּשֵׁב, וְאִם לֹא רָצְתָה, דִּינָהּ כְּדִין מוֹרֶדֶת. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּכָל זֶה בְּיָדוֹ אוֹ רַגְלוֹ אוֹ עֵינוֹ אַחַת, \u0010c7\u0011 אֲבָל בְּב' \u0006 \u0005 יָדָיו וּב' עֵינָיו וּב' רַגְלָיו, כּוֹפִין אוֹתוֹ לְהוֹצִיא \u0006 \u0005(טוּר וְהָרֹא\"שׁ)\u0006:\nאִישׁ הַמִּשְׁתַּטֶּה מִידֵי יוֹם יוֹם, וְאוֹמֶרֶת אִשְׁתּוֹ: אָבִי מֵחֲמַת דָּחֲקוֹ הִשִּׂיאַנִי לוֹ וּסְבוּרָה הָיִיתִי לְקַבֵּל וְאִי אֶפְשִׁי כִּי הוּא מְטֹרָף וִירֵאָה אֲנִי פֶּן יַהַרְגֵנִי בְּכַעֲסוֹ, אֵין כּוֹפִין אוֹתוֹ לְגָרֵשׁ, שֶׁאֵין כּוֹפִין אֶלָּא בְּאוֹתָם שֶׁאָמְרוּ חֲכָמִים. \u0005 הַגָּה: מִי שֶׁהוּא נִכְפֶּה, \u0010c8\u0011 יֵשׁ אוֹמְרִים שֶׁאֵינוֹ \u0006 \u0005 מוּם וְאֵין כּוֹפִין עַל זֶה לְגָרֵשׁ. וּמִכָּל מָקוֹם אֵין כּוֹפִין אוֹתָהּ שֶׁתִּהְיֶה עִמוֹ, הוֹאִיל וּבָאתָה מֵחֲמַת טַעֲנָה \u0006 \u0005(מָרְדְּכַי פֶּרֶק הַמֵדִיר בְּשֵׁם ראבי\"ה)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּהָוֵי מוּם \u0006 \u0005 בָּאִישׁ, וְכוֹפִין לְגָרֵשׁ \u0006 \u0005(הָרֹא\"שׁ כְּלָל מ\"ב)\u0006:\nהָאִשָּׁה שֶׁתּוֹבַעַת גֵּט בְּטַעֲנָה שֶׁאֵינָהּ רְאוּיָה לִבָּנוֹת מִמֶּנּוּ, אֵין שׁוֹמְעִין לָהּ. וְאִם טָעֲנָה שֶׁחֲפֵצָה לֵילֵד כְּדֵי שֶׁיִּהְיֶה לָהּ בֵּן שֶׁתִּשָּׁעֵן עָלָיו, \u0010c9\u0011 \u0005 וְאֵין לָהּ כְּבָר \u0006 \u0005 שׁוּם בֵּן, \u0010c10\u0011 \u0006 וְאוֹמֶרֶת שֶׁהוּא גּוֹרֵם שֶׁאֵינוֹ יוֹרֶה כַּחֵץ, \u0010c11\u0011 אִם שָׁהֲתָה עִמּוֹ עֶשֶׂר שָׁנִים וְלֹא נִתְעַבְּרָה, וְאֵינָהּ תּוֹבַעַת כְּתֻבָּתָהּ כְּדֵי שֶׁנָּחוּשׁ שֶׁתּוֹבַעַת גֵּט כְּדֵי לִגְבּוֹת כְּתֻבָּתָהּ, וְגַם אֵין לִתְלוֹת תְּבִיעַת הַגֵּט בְּשׁוּם דָּבָר אַחֵר, שׁוֹמְעִין לָהּ, אֲפִלּוּ יֵשׁ לוֹ בָּנִים מֵאִשָּׁה אַחֶרֶת, דְּשֶׁמָּא נִתְקַלְקֵל אַחַר כָּךְ, וְכוֹפִין אוֹתוֹ לְהוֹצִיא, וְיִתֵּן מָנֶה מָאתַיִם, אֲבָל לֹא תּוֹסֶפֶת, וְיִתֵּן נְדוּנְיָתָא מַה שֶּׁהִכְנִיסָה לוֹ. \u0010c12\u0011 וְיֵשׁ לוֹ לְהַחֲרִים סְתָם עַל מַה שֶּׁטּוֹעֶנֶת דָּבָר שֶׁאֵינָהּ יוֹדַעַת בּוֹ בְּוַדַּאי, וְאַחַר כָּךְ יִתֵּן כְּתֻבָּה. וְאִם אָמַר אֶשָּׂא אִשָּׁה אַחֶרֶת עָלֶיהָ וְאֶבְדֹק עַצְמִי, שׁוֹמְעִין לוֹ. וְאִם יָלְדָה הַשְּׁנִיָּה, \u0010c13\u0011 תֵּצֵא הָרִאשׁוֹנָה בְּלֹא כְּתֻבָּה, וְאִם לָאו יוֹצִיא שְׁתֵּיהֶן וְיִתֵּן כְּתֻבָּה, אוֹ יִשָּׂא שְׁלִישִׁית, אִם אֶפְשָׁר לֵהּ לְמֵיקַם בְּסִפּוּקַיְהוּ. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אָמְרָה גַּם הַשְּׁנִיָּה שֶׁאֵינוֹ יוֹרֶה כַּחֵץ, \u0010c14\u0011 יוֹצִיא שְׁתֵּיהֶן וְיִתֵּן כְּתֻבָּה. וּבְכָל גַּוְנָא, אִם יָדוּעַ שֶׁהוּא עָקָר, וְהִיא בָּאָה מֵחֲמַת טַעֲנָה, \u0010c15\u0011 יוֹצִיא מִיָּד. \u0005 הַגָּה: \u0010c16\u0011 וְהוּא הַדִּין אִם שָׁהָה \u0006 \u0005 י' שָׁנִים וְלֹא יָלְדָה, וּבָאָה מֵחֲמַת טַעֲנָה, שֶׁכּוֹפִין אוֹתוֹ לְהוֹצִיא וְלִתֵּן כְּתֻבָּה, וְהָתָם לֹא מְהַנֵי מַה שֶּׁאוֹמֵר: אֶבְדֹּק עַצְמִי וְאֶשָּׂא אַחֶרֶת, דְּמִכָּל מָקוֹם לֹא אִבְּדָה הָרִאשׁוֹנָה כְּתֻבָּתָהּ, הוֹאִיל וְלֹא הֻחְזְקָה בְּג' אֲנָשִׁים. וְהָא דִּצְרִיכָה לִטְעֹן שֶׁאֵינוֹ יוֹרֶה כַּחֵץ, הַיְנוּ שֶׁיָּדוּעַ שֶׁהָיוּ לוֹ כְּבָר בָּנִים, אָז תָּלִינָן בְּדִידַהּ אִם לֹא שֶׁטּוֹעֶנֶת שֶׁאֵינוֹ יוֹרֶה כַּחֵץ, אוֹ בַּבַּעַל הַשְּׁלִישִׁי שֶׁכְּבָר הֻחְזְקָה כָּךְ נִרְאֶה סְבָרַת הַטּוּר וְהוּא מַסְקָנַת הַתוס' וְהָאֲשֵׁרִ\"י: \u0006\nאִם טוֹעֶנֶת: אֵין לוֹ גְּבוּרַת אֲנָשִׁים לָבֹא עָלֶיהָ, וְשׁוֹאֶלֶת גֵּט, וְהוּא מַכְחִישָׁהּ, \u0010c17\u0011 יֵשׁ אוֹמְרִים שֶׁהִיא נֶאֱמֶנֶת \u0005 ואֲפִלּוּ לֹא שָׁהֲתָה י' שָׁנִים \u0006 \u0005(טוּר)\u0006, וְכוֹפִין אוֹתוֹ לְהוֹצִיא מִיָּד, \u0010c18\u0011 וְלֹא יִתֵּן לָהּ \u0010c19\u0011 כְּתֻבָּה. וְאִם מְגָרְשָׁהּ מֵעַצְמוֹ בְּלֹא כְּפִיָּה, יִתֵּן לָהּ כְּתֻבָּה. \u0005 וְיֵשׁ אוֹמְרִים דְּאַף עַל פִּי שֶׁיָּכוֹל לִבְעֹל אַחֶרֶת, צָרִיךְ לִתֵּן לָזֹאת הַכְּתוּבָה; הוֹאִיל וְלֹא יָכוֹל לָבֹא עָלֶיהָ, יְכוֹלָה לוֹמַר: מָסַרְתִּי עַצְמִי לְךְ, וּמָה אֶעֱשֶׂה לְךְ יוֹתֵר \u0006 \u0005(ב\"י בְּשֵׁם א\"ח)\u0006. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁאֵינָהּ תּוֹבַעַת כְּתֻבָּתָהּ. אֲבָל אִם תּוֹבַעַת כְּתֻבָּתָהּ, אֵינָהּ נֶאֱמֶנֶת, וְאַף לְהוֹצִיא אֵין כּוֹפִין. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּבַזְמַן הַזֶה שֶׁיֵּשׁ נָשִׁים חֲצוּפוֹת, אֵינָהּ נֶאֱמֶנֶת \u0006 \u0005(מָרְדְּכַי פֶּרֶק עֲשָׂרָה יוֹחֲסִין)\u0006. \u0005 וּמִכָּל מָקוֹם, בְּמָקוֹם שֶׁיֵּשׁ אֲמַתְלָאוֹת וְאֻמְדָּנוּת שֶׁאוֹמֶרֶת אֱמֶת, נֶאֱמֶנֶת \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ ע\"ב)\u0006. \u0005 וְאִם יֵשׁ לִתְלוֹת שֶׁלֹּא יוּכַל לָבֹא עָלֶיהָ מִשּׁוּם שֶׁרַחְמָהּ צָר וְהִיא בְּתוּלָה, שֶׁלֹּא יוּכַל לָבֹא עָלֶיהָ מִכֹּחַ רַכּוּת שָׁנָיו וְחֻלְשָׁתוֹ, תּוֹלִין בָּזֶה וְאֵין כּוֹפִין לְהוֹצִיא \u0006 \u0005(תְּשׁוּבַת הָריצְבָ\"א סוֹף אִשּׁוּת)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דַּאֲפִלּוּ בְּמָקוֹם שֶׁאֵין כּוֹפִין אוֹתוֹ, מִכָּל מָקוֹם אֵין כּוֹפִין אוֹתָהּ לְהִתְפַּיֵּס עִמוֹ, וְאֵין דָּנִין אוֹתָהּ כְּדִין מוֹרֶדֶת, אֶלָּא מַאֲרִיכִין הַדָּבָר עַד שֶׁיִּתְפַּשְּׁרוּ אוֹ עַד שֶׁיִּשְׁהֶה עֶשֶׂר שָׁנִים וְלֹא תֵּלֵד \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קל\"ה בְּב\"י בְּשֵׁם הָרַשְׁבָּ\"א)\u0006. \u0005 וְהוּא הַדִּין אִם קִדֵּשׁ אִשָּׁה \u0010c20\u0011 וַאֲסוּרָה לְהִנָשֵׂא לוֹ וּלְאַחֵר, כּוֹפִין אוֹתוֹ לְהוֹצִיא \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל מ\"ג)\u0006. \u0005 אִם טוֹעֶנֶת שֶׁבַּעְלָהּ אֵינוֹ שׁוֹכֵב עִמָהּ וְאֵינוֹ בָּא עָלֶיהָ, דִּינָהּ כְּדִין טוֹעֶנֶת שֶׁאֵין לוֹ גְּבוּרַת אֲנָשִׁים: \u0006\nאִם יָדוּעַ שֶׁהָאִישׁ רוֹצֶה לֵילֵךְ לְאֶרֶץ אַחֶרֶת, יַשְׁבִּיעוּהוּ שֶׁלֹּא יֵלֵךְ אוֹ יִכְפּוּהוּ שֶׁקֹּדֶם שֶׁיֵּלֵךְ יְגָרֵשׁ אוֹתָהּ לִזְמַן:\nאִם הַדָּבָר יָדוּעַ שֶׁאֵינוֹ רַשַּׁאי לַעֲמֹד בְּמָקוֹם שֶׁנְשָּׂאָה, מִפְּנֵי סַכָּנַת נְפָשׁוֹת, כּוֹפִין אוֹתוֹ לְגָרְשָׁהּ, \u0005 כִּי הִיא אֵינָהּ צְרִיכָה לָלֶכֶת אַחֲרָיו: \u0006\nנָשָׂא אִשָּׁה וְשָׁהֲתָה עִמּוֹ עֶשֶׂר שָׁנִים וְלֹא יָלְדָה, \u0010c21\u0011 יוֹצִיא וְיִתֵּן \u0010c22\u0011 כְּתֻבָּה אוֹ יִשָּׂא אִשָּׁה הָרְאוּיָה לֵילֵד. וְאִם לֹא רָצָה, כּוֹפִין אוֹתוֹ עַד שֶׁיּוֹצִיא. וְאִם אָמַר: אֵינִי בּוֹעֲלָהּ וַהֲרֵינִי שׁוֹכֵן עִמָּהּ בִּפְנֵי עֵדִים כְּדֵי שֶׁלֹּא אֶתְיַחֵד עִמָּהּ, בֵּין שֶׁאָמְרָה הִיא בֵּין שֶׁאָמַר הוּא, אֵין שׁוֹמְעִין לוֹ, אֶלָּא יוֹצִיא וְיִשָּׂא אִשָּׁה הָרְאוּיָה לָלֶדֶת. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּכָל זֶה דְּלֹא הוֹלִיד כְּלָל, אֲבָל אִם הוֹלִיד זֶרַע קַיָּמָא, אַף עַל פִּי שֶׁלֹּא קִיֵּם עֲדַיִן פְּרִיָּה וּרְבִיָּה, \u0010c23\u0011 אֵין כּוֹפִין \u0006 \u0005 לְהוֹצִיא \u0006 \u0005(רִיבָ\"שׁ סִימָן ט\"ו)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן א' דְּבַזְמַן הַזֶה אֵין נוֹהֲגִין לָכֹף כְּלָל. \u0010c24\u0011 וְנֶאֱמָן הָאִישׁ לוֹמַר שֶׁיּוֹדֵעַ בְּעַצְמוֹ שֶׁאֵינוֹ מוֹלִיד, וְאֵין כּוֹפִין אוֹתוֹ לִשָּׂא אִשָּׁה \u0006 \u0005(נ\"י פֶּרֶק הַבָּא עַל יְבִמְתּוֹ)\u0006: \u0010c25\u0011\nהָלַךְ בִּסְחוֹרָה בְּתוֹךְ י' שָׁנִים, אוֹ שֶׁהָיָה הַבַּעַל חוֹלֶה, אוֹ שֶׁהָיְתָה הִיא חוֹלָה, \u0005 אַף עַל פִּי שֶׁמְשַׁמְשִׁים יַחַד, \u0006 אוֹ שֶׁהָיוּ חֲבוּשִׁים בְּבֵית הָאֲסוּרִים, אֵין עוֹלִים לָהֶם אוֹתוֹ זְמַן מֵהַמִּנְיָן:\nהִפִּילָה, מוֹנֶה מִיּוֹם שֶׁהִפִּילָהּ. אִם הִפִּילָה וְחָזְרָה וְהִפִּילָה \u0010c26\u0011 שָׁלשׁ פְּעָמִים, \u0010c27\u0011 הֻחְזְקָה לִנְפָלִים, וְיוֹצִיא וְיִתֵּן כְּתֻבָּה; וּמִכָּל מָקוֹם מֻתֶּרֶת לִנָּשֵׂא לְאַחֵר:\nהוּא אוֹמֵר: הִפִּילָה בְּתוֹךְ עֶשֶׂר, כְּדֵי שֶׁתֵּשֵׁב עִמּוֹ; וְהִיא אוֹמֶרֶת: לֹא הִפַּלְתִּי, \u0010c28\u0011 הִיא נֶאֱמֶנֶת:\nהוּא אוֹמֵר: הִפִּילָה שְׁנַיִם, וְהִיא אוֹמֶרֶת: הִפַּלְתִּי ג', הִיא \u0010c29\u0011 נֶאֻמֶנֶת:\nבְּכָל זֶה \u0010c30\u0011 מַשְׁבִּיעָהּ \u0005(שְׁבוּעַת)\u0006 הֶסֵת שֶׁלֹּא הִפִּילָה, אוֹ שֶׁהִפִּילָה ג', שֶׁבְּטַעֲנָה זוֹ יִתְחַיֵּב לִתֵּן לָהּ כְּתֻבָּה:\nשָׁהָה עִם אִשְׁתּוֹ עֶשֶׂר שָׁנִים וְלֹא יָלְדָה, וְהוֹצִיאָהּ, מֻתֶּרֶת לְהִנָּשֵׂא עִם הַשֵּׁנִי. שָׁהֲתָה עִם הַשֵּׁנִי עֶשֶׂר שָׁנִים וְלֹא יָלְדָה, דִּינָהּ עִמּוֹ כְּדִינָהּ עִם הָרִאשׁוֹן: \u0010c31\u0011\nגֵּרְשָׁהּ, לֹא תִּנָּשֵׂא לִשְׁלִישִׁי. וְאִם נִשֵּׂאת לִשְׁלִישִׁי, \u0010c32\u0011 תֵּצֵא שֶׁלֹּא בִּכְתֻבָּה; אֶלָּא אִם כֵּן יֵשׁ לוֹ אִשָּׁה אַחֶרֶת, אוֹ שֶׁקִּיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה. וְאִם הִכִּיר בָּהּ, יֵשׁ לָהּ כְּתֻבָּה:\nשָׁהֲתָה עִם הַשְּׁלִישִׁי עֶשֶׂר שָׁנִים וְלֹא יָלְדָה, אִם לֹא גָּבְתָה כְּתֻבָּה מֵהָרִאשׁוֹנִים, לֹא תִּגְבֶּה. וְאִם גָּבְתָה, \u0010c33\u0011 לֹא תַּחֲזִיר:\nהוֹצִיאָהּ הַשְּׁלִישִׁי בְּלֹא כְּתֻבָּה, וְנִשֵּׂאת לִרְבִיעִי וְיָלְדָה, אֵינָהּ יְכוֹלָה לִגְבּוֹת כְּתֻבָּה מֵהַשְּׁלִישִׁי, דְּשֶׁמָּא עַתָּה נִתְרַפְּאָה:\nכָּל הַנּוֹשֵׂא אִשָּׁה בַּעֲבֵרָה, אֲפִלּוּ בְּאִסוּר דְּרַבָּנָן כְּגוֹן שְׁנִיּוֹת, כּוֹפִין אוֹתוֹ לְהוֹצִיא:\nכָּל אֵלּוּ שֶׁאָמְרוּ לְהוֹצִיא, כּוֹפִין אֲפִלּוּ בְּשׁוֹטִים. וְיֵשׁ אוֹמְרִים שֶׁכָּל מִי שֶׁלֹּא נֶאֱמַר בּוֹ בַּתַּלְמוּד בְּפֵרוּשׁ כּוֹפִין לְהוֹצִיא, אֶלָּא יוֹצִיא בִּלְבַד, אֵין כּוֹפִין בְּשׁוֹטִים אֶלָּא אוֹמְרִים לוֹ: חֲכָמִים חִיְּבוּךְ לְהוֹצִיא, וְאִם לֹא תּוֹצִיא מֻתָּר לִקְרוֹתְךְ עֲבַרְיָן. \u0005 הַגָּה: וְכֵיוָן דְּאִכָּא פְּלוּגְתָא \u0010c34\u0011 דְּרַבְּוָתָא, רָאוּי לְהַחֲמִיר שֶׁלֹּא לָכוֹף \u0006 \u0005 בְּשׁוֹטִים, שֶׁלֹּא יְהֵא הַגֵּט מְעֻשֶּׂה \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0005 אֲבָל אִם יֵשׁ לוֹ אִשָּׁה בַּעֲבֵרָה, לְכֻלֵּי עָלְמָא כּוֹפִין בְּשׁוֹטִים. וְכָל מָקוֹם שֶׁאֵין כּוֹפִין בְּשׁוֹטִים, אֵין מְנַדִּין אוֹתוֹ גַּם כֵּן \u0006 \u0005(מָרְדְּכַי רֵישׁ הַמֵדִיר)\u0006. \u0005 וּמִכָּל מָקוֹם יְכוֹלִין לִגְזֹר עַל כָּל יִשְׂרָאֵל שֶׁלֹּא לַעֲשׂוֹת לוֹ שׁוּם טוֹבָה אוֹ לִשָּׂא וְלִתֵּן עִמוֹ \u0006 \u0005(שם בְּשֵׁם ר\"ת וּבַמַהֲרִי\"ק קל\"ה)\u0006, \u0005 אוֹ לָמוּל בָּנָיו אוֹ לְקָבְרָם, עַד שֶׁיְּגָרֵשׁ\u0006 \u0005(בִּנְיָמִן זְאֵב פ\"ח)\u0006. \u0005 וּבְכָל חֻמְרָא שֶׁיִּרְצוּ בֵּית דִּין יְכוֹלִין לְהַחֲמִיר בִּכְהַאי גַּוְנָא, וּמִלְּבַד שֶׁלֹּא יְנַדּוּ אוֹתוֹ. אֲבָל מִי שֶׁאֵינוֹ מְקַיֵּם עוֹנָה, יְכוֹלִין לְנַדּוֹתוֹ וּלְהַחֲרִימוֹ שֶׁיְּקַיֵּם עוֹנָה אוֹ שֶׁיְּגָרֵשׁ, כִּי אֵין זֶה כְּפִיָּה רַק לְקַיֵּם עוֹנָתוֹ, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה \u0006 \u0005(רִיבָ\"שׁ סִימָן קכ\"ז)\u0006. \u0005 וְכֵן מִי שֶׁגֵּרַשׁ אִשְׁתּוֹ בְּגֵט כָּשֵׁר, וְיָצָא קְצָת לַעַז עַל הַגֵּט, מֻתָּר לְכוֹפוֹ לָתֵת גֵּט אַחֵר. וּבְכָל מָקוֹם דְּאִכָּא פְּלוּגְתָא אִם כּוֹפִין אוֹ לֹא, אַף עַל גַּב דְּאֵין כּוֹפִין לְגָרֵשׁ, מִכָּל מָקוֹם כּוֹפִין אוֹתוֹ לִתֵּן כְּתֻבָּה מִיָּד, וְכֵן הַנְדוּנְיָא דְּאַנְעַלַת לֵהּ \u0006 \u0005(מָרְדְּכַי רֵישׁ הַמֵדִיר)\u0006:\nצָרִיךְ לְהָטִיל חֵרֶם עַל כָּל הָעוֹמְדִים בִּשְׁעַת נְתִינַת הַגֵּט, שֶׁלֹּא לְהוֹצִיא לַעַז עַל הַגֵּט. \u0005 וּמַזְכִּירִין שֶׁרַבֵּנוּ תָּם גָּזַר בִּכְנוּפְיָא עִם תַּלְמִידָיו עַל מִי שֶׁמוֹצִיא לַעַז עַל הַגֵּט הַנִתַּן: \u0006\nאִם נִשְׁבַּע הַבַּעַל לִתֵּן גֵּט, טוֹב שֶׁיַּתִּירוּ לוֹ קֹדֶם, שֶׁלֹּא יְהֵא דּוֹמֶה לְאֹנֶס; אַךְ עֵרָבוֹן יִתֵּן, אִם יִרְצֶה. \u0005 הַגָּה: וְעַיֵּן לְעֵיל סִימָן קל\"ד סָעִיף ד'. וּבְגֵט מוּמָר אֵין צְרִיכִין לִשְׁאֹל אִם נִשְׁבַּע אוֹ נָדַר, מֵאַחַר דְּצָרִיךְ לְגָרֵשׁ מִדִּינָא; אַךְ שׁוֹאֲלִין אוֹתוֹ אִם מְגָרֵשׁ בְּרָצוֹן, וְכֵן שׁוֹאֲלִין לְאִשְׁתּוֹ: \u0006\nמִי שֶׁקִּבֵּל עָלָיו נְזִירוּת שִׁמְשׁוֹן לְגָרֵשׁ אֶת אִשְׁתּוֹ, מֻתָּר לְגָרֵשׁ, וְאֵין בּוֹ מִשּׁוּם מְגָרֵשׁ בְּאֹנֶס. וְטוֹב לְגָרְשָׁהּ בִּשְׁנֵי גִּטִּין, וְיִתְּנֵם לָהּ זֶה אַחַר זֶה:",[],["\u0003להוצי' וליתן כתובה\u0004. ולענין תוספ' כתובה עיין סעיף ז' כשבאה בטענה חוטר' לידה אין לה תוס' כי למשקל ולמיפק לא הקנה לה כן הדין בכל הני אין לה תוס' אפילו במוכה שחין דצריך לגרשה לטובתו מ\"מ נראה דאין לה תוס' מיהו אם היה מוכה שחין קודם הנישואין י\"ל גרע טפי כמ\"ש בהרי\"ף ס\"פ הע\"י ממאנת צריך ליתן תוס' הטעם מכדי דידע דהיא קטנה ולמה כתב לה ולא חשש דלמא תתחרט ונפק' אלא רצה לזלזל כן י\"ל כאן כיון דהיה מ\"ש למה כתב לה ת\"כ, ובד\"מ כתב נמי למ\"ש הטור בבאה בטענה דאין לה ת\"כ אפשר ה\"ה הכא אלא כתב בשם הר\"ן דצריך ליתן ת\"כ וא\"י איך כ\"כ בשם הר\"ן וממ\"ש הר\"ן בפ' אלמנה ניזונת משמע דס\"ל דאין לה ולא ראיתי דהר\"ן כתב דיש לה ת\"כ וכן אית' בתו' ובמ' שם ובהג\"א ריש המדיר בשם ר\"ח דאין לה אלא ר\"ת ס\"ל דיש להן ואין ראי' מדבריו דהא ס\"ל הבאה מחמת טענה נמי יש לה ולא קי\"ל כוותי':","\u0003ואם ידעה בהם\u0004. היינו דעת הרמ\"ה לפ\"ז בריח פה ושאר דברי' אם ידעה בהן אין כופין א\"כ למאן דתנא במתני' הראשונה האיש שנולדו בו מומין וכו' אין כופין קאמר בש\"ס נולדו מכ\"ש היו משום דסברה וקבלה ה\"ק מכ\"ש היו דאז אפי' בריח פה וכו' אין כופין ולמ\"ד היו קשה היו אפילו ריח פה נמי אין כופין ואפשר למ\"ד זה באמת פי' במתני' שניה אלו שכופין וכו' ריח פה איירי אפי' אם היו מ\"מ כופין ור\"מ ורבנן פליגי אם התנה בפירוש אלא אנן קי\"ל כמ\"ד נולדו מכ\"ש היו אז אמרינן דפליגי בהיו והא דתנא במתני' אלו כופין בין שהיו עד שלא נשאת פי' ב\"ח היינו שהיו והיא לא היתה יודעת מיהו במתני' קמיית' במומין י\"ל בהיו ולא היתה יודעת כופין ג\"כ אלא החילוק בין תרי משניו' הללו בנולדו אז בריח פה כופין ובשאר מומין אין כופין אבל אם לא יודעת הוי מקח טעות וכופין להוצי' כמ\"ש בסי' ל\"ט וקי\"ז אם נמצ' בה מומין, וא\"ל למה לא אוקמי הפלוגת' בענין זה למ\"ד היו היינו היו ולא היתה יודעת מכ\"ש נולדו ומ\"ד נולדו ס\"ל היו הוי מקח טעות וי\"ל דס\"ל לכ\"ע בכה\"ג הוי מקח טעות וב\"ח מפרש בע\"א ולדיד' אליב' דהרמ\"ה אין כופין על מומין אפילו היו ולא היתה יודעת ומכ\"ש לשיטות שאר פוסקים איירי הכל היו יודעת ולא נשמע כלל הדין היו ולא היתה יודעת וי\"ל לכ\"ע כופין אפילו במומין, והנה לכמה פוסקים אפי' ידעה בהן י\"ל סבורה הייתי שאני יכול לקבל ועכשיו א\"י לקבל לכן נראה אפי' לרמ\"א שכתב אין כופין להוצי' מ\"מ אין דינה כמורדת אם אין רצונה לדור עמו וי\"ל קים לי כהני פוסקי' והא שפסק כהרמ\"ה ולא כהני פוסקי' משום המגיד והב\"י כתבו דהרמב\"ם ס\"ל דוק' נולד בו כופין אותו אבל אם היו בו אין כופין אותו אבל אין מוכרח לומר כן וי\"ל דוק' לענין כתובה כ\"כ אם נולד בו צריך ליתן לה הכתובה אבל אם היה בו מעיקר' א\"צ ליתן לה הכתוב' דאל\"כ כל אשה תערים ותנשא לזה כמ\"ש בתוס' יבמות דף ס\"ד ובפ' המדיר ובמ' ובאגודה וראיה לדבר דהא במוכה שחין כתב נמי נעשה מוכה שחין אף על גב לכ\"ע אפי' בהתנה והיה בו מעיקר' כופין אותו לגרש אלא ודאי משום הכתובה כתב כן:","\u0003נעשה האיש מוכה שחין\u0004. בסמוך כתבתי די\"א אם היה מ\"ש מעיקר' אין לה כתובה כדי שלא תערים, ובמרדכי פ' המדיר כתב דיש לה כתובה כיון דיכול להתנות אם תצא ממנו דאין לה כתובה ואם לא התנה פסידה דידיה הוא ותוס' כתבו במקום דיש חשש ערמה אין לה כתובה ופרישה הקשה אם התנה עמה למה צריך ליתן לה כתובה ותירץ כיון דהיא היתה רוצה לישב עמו מ\"ה צריך ליתן לה הכתובה נשמע אם היא רוצה לגרשו אין לה כתובה וא\"ל כשנעשה כן אחר הנישואין לימא נסתחפה שדה של אשה תירצו תוס' האשה שדה של האיש ואין איש שדה של אשה:","\u0003אם יש עדות בדבר\u0004. ואין להחרי' אחר עדות זה דכל ישראל בחזקת כשרות הם חדושי אגודה:","\u0003כופין אותו לזון\u0004. לדעת כמה פוסקים הלכתא כרב דכופין אותו לגרש וי\"ל אם היא אינה רוצה לדור עמו אין נעשית מורדת וי\"ל קים לי כהני פוסקים כמ\"ש בסמוך:","\u0003כופין אותו להוציאו\u0004. אפי' קבלה עליה ב\"ז:","\u0003וכן הדין וכו'\u0004. כלומר בענין הכפיה שוין הדיני' אבל לענין מורד להוסיף על הכתובה אינן שוין דאם אינו רוצה לשמש קי\"ל דהוי מורד ומוסיפין על הכתובה ובאם אינו רוצה לזון אין מוסיפים למאי דקי\"ל מורד מתשמיש נקרא מורד ולא מורד ממלאכה, ועיין ר\"ס ע\"ז:","\u0003אבל בב' ידיו וכו'\u0004. היינו שנולדו בו אבל אם היו בו תלי' בפלוגת' שהבאתי סק\"ב ב\"ח ושם כתבתי עכ\"פ אף היא לא נעשית מורדת כשאינה רוצה לדור עמו:","\u0003י\"א שאינו מום\u0004. באיש אף על גב באשה הי' מום כמ\"ש בש\"ס ובסי' קט\"ו מ\"מ אשה ניח' לה בכל דהוא אף על גב בריח חוטם באיש מום ובאש' י\"א שאינו מום כמ\"ש בסימן ל\"ט שם תלי' בכח מי שנתחזק יכול לסבול יותר כמ\"ש במ' ובהג\"א אבל בשאר מומין אמרי' אשה ניחא לה בכל דהוא, משמע דאין סכנה בדבר אם משמש' עם בעלה נכפה דאם היה סכנה בדבר מהיכא תיתי לומר דאין כופין לפ\"ז אם היה תנאי בדבר א\"י לגרש אבל בתשו' הרא\"ש כלל מ\"ב מבואר דיש סכנה בדבר לכן אפי' תנאי לא מהני:","\u0003ואין לה כבר שום בן\u0004. ב\"י כתב אפי' בת אם יש לה לא כייפינן ליה:","\u0003ואומרת שהוא גורם וכו'\u0004. לשיטו' תוס' והרא\"ש הא דצריכ' לומר שאינו י\"כ משום דע\"כ איירי בשהה עמה י\"ש דאל\"כ ליחוש שמא עיני' נתנה באחר כיון שהיא תובע' גט אלא איירי בשהה עמה י\"ש ע\"כ אם עדיין לא קיים פו\"ר ת\"ל דכופין אותו לגרשה מדינא דש\"ס כדי שיקיים פו\"ר אלא ע\"כ איירי דהוא כבר קיים פו\"ר מ\"ה לא כייפינן ליה אלא מחמת טענות דידה מ\"ה צריכה לומר שאינו יורה כחץ כיון שכבר הוליד מסתבר' דהיא הגרם שאינו מוליד לכן צ\"ל שאינו י\"כ אבל לדידן דאין כופין על ביטול פו\"ר אפי' בשהתה י\"ש א\"כ אפי' אם הוא י\"כ מ\"מ כשבאת' בטענה בעינן חוטרא לידי ושהתה י\"ש ועדיין לא הוליד כופין אותו לגרש ונותן לה הכתובה ולפי תירוץ של הר\"ש בתו' אז בבעל שלישי צריכ' לטעון שאינו י\"כ כיון שהוא מוחזקת בשלשה אנשים והיינו מ\"ש בסמוך בהג\"ה מיהו הנ\"י כתב בשם כמה פוסקים דחולקים ע\"ז וס\"ל בבעל השלישי אינה נאמנ' אפי' כשאמר' שאינו י\"כ לשיטות הרי\"ף לפי' הרמב\"ן והרא\"ש כל שהוא טוען ברי מינה הוא כגון האומר שפולטת הזרע אפי' אם היא מכחש' אותו אין לה כתובה והוא ישבע ע\"ז אא\"כ שהיא אומרת שאינו י\"כ וזאת הוא א\"י אז היא נאמנת ודוקא אחר י\"ש וגם הוא א\"י לגרשה תוך י\"ש דאל\"כ מה הועילו חז\"ל בתקנת' כי כ\"א יאמר מינה הוא כדי להפסיד לה הכתוב' ועיין במלחמות ה', ולהרא\"ש גם תוך י\"ש יכול לגרשה כשאומר מינה הוא ותפסיד הכתובה אא\"כ שתאמר שאינו י\"כ וברמב\"ם פט\"ו ה\"א נראה דס\"ל לעולם צריכה היא לומר שהוא אינו י\"כ אפי' בבעל הראשון ולא הוליד עדיין והוא אינו טוען ברי כדמשמע שם דין י' וכל שאינה טוענת ברי שאינו י\"כ מפסדת הכתובה דאוקמי' ממון בחזק' בעלי' ודוחק לומר דהרמב\"ם סומך את עצמו דמוכרח הוא דאיירי בהוליד הוא דאל\"כ למה לא כפינן ליה לקיים פו\"ר ובדין ט' איירי באומר ברי מינה הוא כל זה דוחק הוא לפ\"ז מ\"ש לדעת הרמב\"ם צ\"ל מ\"ש בש\"ס שמא לא זכה להבנות ממנו והיינו שמא לא זכה שיורה כחץ וי\"כ תליא בזכות כי מחמת שאינו י\"כ אינו מוליד ובזה מיושב קושי' התו' שם בד\"ה שבינו לבינה כתבו תימא במאי איירי אי בשהת' י\"ש ל\"ל י\"כ ת\"ל לפי שלא זכה לבנות ממנה וכו' ע\"ש ולדעת הרמב\"ם לק\"מ ולכאורה היה נראה גם המחבר חושש לדעת הרמב\"ם מ\"ה סתם וכתב בדין שאומר' שאינו י\"כ אפילו דאינו אומר ברי ומכחיש אותה גם משמע דאיירי אפילו בבעל הראשון ואפילו אם אין לו בנים מדכתב אפי' יש לו בנים ש\"מ דין זה איירי אפי' אין לו בנים צריכה לומר שאינו י\"כ ולא כהגה' רמ\"א שהביא דעת תוס' על דברי המחבר כאלו לא היה חילוק ביניהם:","\u0003אם שהתה עמו י\"ש\u0004. נראה אף לשיטות הרי\"ף אחר עשר שנים כשהיא באה לגרשו לא חיישינן שמא עיניה נתנה באחר אף על גב על סוגיא זו דאיירי אחר י\"ש כתב הא דלא חיישינן שמא עיני' נתנה באחר משום אנן מפקינן בע\"כ משמע לכאורה אפי' אחר י' שנים אם היא מבקשת לגרשו חיישינן שמא עיניה נתנה באחר א\"א לומר כן דהא הסוגיא ההיא דאתי' לקמי' ר\"א וכו' דאיירי דהיא היתה תובעת הגט ומ\"מ לא חיישינן שמא נתנה עיני' באחר גם בהרי\"ף מ\"ש על הסוגיא דנדרים מבואר אחר י\"ש לא חיישינן שמא עיני' נתנה באחר וע\"כ הרי\"ף לדיוקא קאמר אף שאיירי דהוא רוצה לגרשה מ\"מ דוקא אחר י\"ש איירי ובתוך י\"ש א\"י לגרשה להפסיד לה הכתוב' כמ\"ש בסמוך:","\u0003ויש לו להחרים\u0004. כיון דאין לו טענות ברי להכחישה א\"י להשביעה:","\u0003תצא הראשונה\u0004. כיון שמבורר דהוא יורה כחץ תלינן המניעה בה ולא אמרי' שלא זכה להבנו' ממנו אפי' לרמב\"ם שכתבתי הזכות מונע שאינו י\"כ מ\"מ כל שראינו שהוא י\"כ לא אמרי' שהוא לא זכה אלא אמרי' היא גרמה וכן ס\"ל לתו' לשיטת' אם ילד כבר תלינן הקלקול בה ולא אמרי' שלא זכה להבנות ממנה:","\u0003יוציא שתיהם\u0004. כן הוא דעת הטור כלומר יוציא מיד וא\"צ להמתין י\"ש בשניה וכ\"כ בלבוש כיון דשהה עם הראשונ' י\"ש ואם הראשונה באה תוך י\"ש לגרשו ובדק נפשי' תוך י\"ש ושניה אומרת שאינו י\"כ מ\"מ א\"י הראשונה לגרשו תוך י\"ש דאכתי חיישינן שמא עיני' נתנה באחר כיון שהוא תוך עשר שנים והיא רצונה לגרש ועיין בטור:","\u0003יוציא מיד\u0004. כ\"כ תוס' ד\"ה שבינו לבינה וכ\"כ הטור ומהרא\"ש לא משמע כן ונראה דס\"ל אפי' אם הוא עקר חיישינן שמא עיני' נתנה באחר כיון שהיא תוך י\"ש וכן הוא להדיא בהרא\"ש ס\"פ הע\"י בעובדא האי דאתי' קמי' דר\"א ע\"ש:","\u0003וה\"ה אם שהה י\"ש וכו'\u0004. בש\"ס איתא הוא אומר מינה והי' אומרת מיניה נאמנת אמר איזיל ואבדוק נפשאי רשאי, וכבר כתבתי השיטות ולכ\"א לפי שטתו ברישא הוא אמר מינה כן הוא בסיפא אם אמר איזיל ואשא אשה אחרת ולשיטות הרמב\"ם שכתבתי כל אשה צריכה לומר שאינו י\"כ והיינו מ\"ש בש\"ס שמא לא זכה להבנות ממנה ואם אמר אשא אשה אחרת אז אם ילדה מבורר דמניעה ממנה ולא אמרי' שמא לא זכה להבנות ממנה, והטור הביא תשובת הרא\"ש שכתב אם נשא אשה שניה וילדה לא הפסידה הראשונה ואמרי' שמא לא זכה להבנות ממנה עד שהיא מוחזקת לא ילדה לג' אנשים ואח\"כ כתב הטור דין זה אם אמר אשא אחרת ואם ילדה תצא הראשונה בלא כתובה ובד\"מ מחלק בין שני דינים הללו וכתב דאיירי כאן דהיא לא ילדה לב' אנשים ונשאת לג' ולא ילדה ואומר' דהוא אינו י\"כ נאמנת ויש לה כתובה ואם נשא אחרת וילדה אז לא אמרי' דלא זכה להבנות אלא היא מוחזקת דלא ילדה והיינו כתירץ הר\"ש בתוס' שהבאתי לעיל דסוגיא הוא אמר מינה וכו' איירי בבעל ג' אז מ\"ש שם בסוגיא ע\"ז אמר איזיל ואבדוק לנפשי' ע\"כ קאי על בעל ג' אבל לשיטו' הרי\"ף דס\"ל הסוגיא איירי אף בבעל הראשון והשני והוא טוען ברי ע\"כ מ\"ש איזיל ואבדוק לנפשי' איירי נמי בטוען ברי אז אם ילדה השני' תצא הראשונה בלא הכתובה אבל בשלא טוען ברי אפילו אם ילדה השני' אמרי' שמא לא זכה להבנות מהראשונ' אבל אם טוען ברי מינה היינו שפולט' ש\"ז והוא נאמן בטענתו אלא היא טוענת אף הוא אינו ראוי להוליד משום דאינו י\"כ א\"כ כשילד' השני' מוכחש טענת' הראשונ' וברי שלו קיים בזה מתורץ שפיר דברי הטור ולא כד\"מ שדוחה חילוק זה ומה שהקשה שם אנ\"ל וכן מהרש\"ל וב\"ח פירשו דטור איירי כשטוען ברי וכן לתירץ של תוס' כשהיה לו כבר בנים צריכה לומר שאינו י\"כ דאל\"כ לא תלינן הזכות גורם שלא זכה להבנות ממנה אלא תולין הקלקול בה איירי נמי מ\"ש איזיל ואבדוק לנפשי' בכה\"ג להכחיש טענתה שהיא אומר' שאינו י\"כ כלומר השתא תש כחו ואם ילדה השני' הוברר דלא תש כחו, מיהו לתירוץ זה של התוס' אם ילד כבר לא תלינן בזכות לכן צריכה לומר שאינו י\"כ ע\"כ אף אם לא ילד ומוליד השתא מן השני' תצא הראשונה בלא כתוב' דהא תש כחו א\"י לומר וכיון שהוא מוליד לא תלינן שלא זכה להבנות ממנה ומה שפסק בתשו' הרא\"ש אף שילדה השני' לא תפסיד הראשונה משום שדוחה שם בתשוב' תירץ זה וכן בפסקיו משמע דלא ס\"ל תירוץ זה ותפס' בתשובה לעיקר תירוץ של הר\"ש הנ\"ל כל שלא הוחזק' בג' אנשים אמרינן שהוא לא זכה להבנות ממנה אף על פי שמוליד מנשים אחרים לפ\"ז דברי רמ\"א בהג\"ה תמוהים בעיני שכתב בסמוך כתירוץ של תוס' כשהיה לו בנים צ\"ל שאינו י\"כ דאל\"כ לא תלינן שזכות גורם אלא אמרינן שהיא עקרה א\"כ איך אפשר לומר בשהה י\"ש דאי\"ל איזיל ואבדוק לנפשי' דהא אם יוליד מאחר' אז לא תלי' תו בזכו' אלא היא גרמ' ואין נראה לומר דס\"ל אפילו לדברי תוס' אם ילד כבר תלי' הקלקול בה אבל אם לא ילד כבר לא אמרינן שיבדוק לנפשי' חדא מלשונו משמע אפילו אם הלך ובדק נפשו וילדה שני' לא תפסיד הראשונ' ולתוס' בוודאי אם ילד' השני' תלי' הקלקול בראשונ' כדמשמע בתשובת הרא\"ש שם גם מנ\"ל לחלק בזה וצ\"ע ודברי הטור ג\"כ לכאורה תמו' מ\"ש בדין כשהיא באה בטענת בעינן חוטר' לידי ואומר' שאינו י\"כ קשה דהא איירי דהוא אינו טוען נגד' כלום גם לא איירי בבעל ג' דהא לא אידכר מזה א\"כ לשיטות הרי\"ף גם לתירוץ הר\"ש בתוס' אצ\"ל שאינו י\"כ ואי ס\"ל לתירוץ של תוס' ביש לו בנים צ\"ל שאינו י\"כ קשה חדא הרא\"ש בתשובה הנ\"ל דוחה תירוץ זה עוד קשה איך כתב אפילו יש לו בנים הא איירי דוקא כשיש לו בנים גם קשה קושי' הנ\"ל דא\"כ איך הביא תשובת הרא\"ש כשמוליד מן השני' דתולין דלא זכה להבנות ממנה ואם ס\"ל כהרמב\"ם כמ\"ש לעיל סק\"ט ג\"כ קשה איך הביא תשובת הרא\"ש דהא אם היא צריכ' לטעון ברי דהמניע' ממנה א\"כ ע\"כ הסוגיא איזיל ואבדוק לנפשי' איירי נמי בכה\"ג ואם בדק נפשיה וילדה השניה תו לא תלינן בזכות, מיהו בטור יש לומר דפוסק בתוספו' היינו כשהיא באה לגרשו אז אמרינן כיון שילד כבר י\"ל הקלקול באה ממנה והיא א\"י לגרשו ובתשו' הרא\"ש איירי כשהו' בא לגרשה ולפחות לה הכתובה אז י\"ל להיפוך אפי' שמוליד מנשים אחרות שמא לא זכה להבנות ממנה והא שכתב בסעיף ל' דהיא טוענת שהוא אינו י\"כ ושם איירי דהוא רוצה לגרשה י\"ל משום דהוא טוען ברי מינה הוא המניעה מ\"ה צריכה לטעון ברי שהוא אינו י\"כ ובזה י\"ל דברי הטור אבל רמ\"א קשה דא\"א ליישב כהנ\"ל דהא הוא כתב דיני' הללו אהא שהיא רוצה לגרשו:","\u0003י\"א שהיא נאמנת\u0004. הטעם כל שהבעל יודע אם היא משקרת אין מעיזה להכחישו מ\"ה אפילו תוך י\"ש נאמנת ודוקא שאמרה כן בפניו כמ\"ש בסי' י\"ז באמרה גרשתני ואפי' בלא טענה בעינן חוטרא לידי מהני כאן כיון דא\"י לקיים העונה:","\u0003ולא יתן לה כתובה\u0004. כיון דהוא מכחיש' ואם הוא מודה צריך ליתן לה הכתובה ות\"כ, /ולענין תוספת כתובה/ כתב הרא\"ש בתשו' שהביא הטור והרשב\"א בתשו' דא\"צ ליתן ת\"כ כי למשקל ולמיפק לא הוסיף לה ואפי' אם תפסה מוציאים ממנה מיהו בתו' מבואר הטעם דלא יתן תוספ' משום דהוי ככנסה לחופה ולא נבעלה ועלתה בתיקו כמ\"ש בסי' ס' לפ\"ז מהני תפיסה אבל הטעם דלא הוסיף לה למעל ולמיפק לא שייך דידע דנשאת לו מתחלה לכך ועיין בסעיף אח\"ז ועיין תשובת רשב\"א סי' תרכ\"ח אפי' נדוניא אינה נאמנת להוציא ממנו כשהו' מכחיש' ועיין סימן י\"ז שם הביא הפלוגתא כשאומרת גרשתני אם היא נאמנת להוציא הכתובה וכאן סתם ופסק דלא יתן הכתובה ובאמת דיני' הללו שוים ועיין תוספות סוף נדרים:","\u0003ואם מגרשה מעצמו וכו'\u0004. יתן לה כתובה ולענין ת\"כ משמע מתשובת הרא\"ש שהביא הטור דצריך ליתן לה כיון דמגרש מעצמו כי דוקא כשכופין אותו לגרש כתב דא\"צ ליתן ת\"כ דאדעתי' למשקל ולמיפק לא אוסיף לה כמ\"ש בכלל מ\"ג סימן ג' ד' מיהו למ\"ש תוס' ס\"פ הע\"י ובסוף נדרי' א\"צ ליתן לה ת\"כ כיון דא\"י לבא עליה הוי כנכנסה לחופ' ולא נבעלה דלית לה כתובה כמ\"ש בסי' ס' ואם יכול להתקשו' ויכול להכניס עטרה ואין לו כח למרק כתבו תוס' ס\"פ הע\"י דיש לה ת\"כ דיש כאן חיבת ביאה ותוס' סוף נדרים כתבו אף על גב העראה כגמר ביאה מכל מקום לענין חיבת ביאה לא הוי ביאה ואין לה ת\"כ:","\u0003ואסורה להנשא לו\u0004. אז כופין אותו אפילו בלא טענה בעינן חוטרא לידי כמו אם אין לו גבורת אנשים כיון דאסורה להנשא מחמתו:","\u0003יוציא ויתן כתובה\u0004. למ\"ש לעיל לרוב הפוסקים אם לא אמרה שהוא אינו י\"כ מ\"מ חייב ליתן לה הכתובה אבל אם הוא טוען ברי דהיא פולט' הזרע או כיוצא בזה דהמניע' ממנה והיא א\"י אם הוא י\"כ אין לה כתובה ודינה כאיילנות כמ\"ש ברמב\"ם שם אפילו אם הוא רוצה לגרשה וכן הוא לשיטות הרי\"ף הוא אמר מינה קאי על מתני' דב\"ד כופין אותו לגרש ומ\"מ אם אמר מינה נאמן אא\"כ דהיא אומרת דהוא אינו י\"כ וכן הוא בהרא\"ש ולא כפרישה סי' קמ\"א, ולפי משמעות דברי המחבר מ\"ש בסעיף ו' פוסק כרמב\"ם קשה איך כתב כאן סתם דיוציא ויתן כתובה דהא לרמב\"ם כל שהי' אינו אומר' ברי דהמניע' ממנו אין לה כתובה:","\u0003או ישא אשה וכו'\u0004. היינו הברירה בידו אבל היא א\"י לומר שישא אחרת ולא יגרש אותה כי לפעמים לא יהבא ליה אתתא כל היכא דאגיד' בה נ\"י ומשמע אפי' היכא דהיא אמרה דהוא אינו י\"כ מ\"מ כופין אותו לגרש זאת וישא אחרת אף על גב שהיא נאמנת לענין כתובה ולדעת הרמב\"ם מבואר כן במתני' דהא מתני' נשא אשה ושהה עמה י\"ש יוציא ויתן כתובה איירי דהיא טוענת ברי דהוא אינו י\"כ כמ\"ש בסמוך ותנא אינו רשאי לבטל, ואם הוליד ומתו בניה עיין תשובת הרשב\"א שהביא הב\"י ובנ\"י ובש\"ג:","\u0003אין כופין להוציא\u0004. היינו כשהיא ראוי' עוד להוליד אבל כשהיא זקנה כופין להוציא:","\u0003ונאמן האיש לומר וכו'\u0004. משום בכל מצות כאלו שאין הוכחה שעושה דרך מרד נאמן על עצמו שם בנ\"י:","\u0003הלך בסחורה\u0004. ואם הלך מח\"ל לא\"י מונין י\"ש מיום ביאתו לא\"י, טור:","\u0003שלשה פעמים\u0004. כאן בעינן ג\"פ משום הרבה נשים מפילי' בתחלת עיבור' נ\"י ועיין תוס' ובהרא\"ש מ\"ש בשם הר\"ש לרבי אפי' בהפילה מוחזקת בתרי זימנא מיהו לא קי\"ל כר\"ש בזה:","\u0003ויוציא ויתן כתובה\u0004. משום דאמרינן שמא לא זכה להבנות ממנה ולרמב\"ם דס\"ל דהיא צריכ' לטעון ברי שהוא /אינו/ י\"כ דאל\"כ אוקמ' הממון בחזקת הבעל וכשאומרת שהוא אינו י\"כ אז אמרינן הוא לא זכה להבנות כן ה\"נ אמרינן הוא לא זכה להבנות:","\u0003היא נאמנת\u0004. היינו כשאין חשש דעיני' נתנה באחר כגון שהב\"ד כפו אותו לגרש רק הוא אמר שהפילה תוך י\"ש כ\"כ הנ\"י וא\"י מה חשש איכא הכא דהא אחר י\"ש הוא ואפשר דס\"ל אפי' אחר י\"ש אכתי איכא חשש שמא נתנה עיניה באחר אא\"כ דאיכא עשרה מיום שהיה בו חסרון זה ושתקה י\"ש אבל בכה\"ג אפשר דהפילה תוך י\"ש א\"כ נתעבר' ממנו תוך י\"ש מ\"ה כתב דהב\"ד כפו אותו והיא לא תבעה הגט גם י\"ל כיון דהיא מחזקת לנפשה לעקרה י\"ל יותר שמא עיני' נתנה באחר אפי' אם הוא אחר י\"ש:","\u0003נאמנת\u0004. וא\"ל למה הוא אינו נאמן הא יש לו מיגו די\"ל דמכיר בעצמו שאינו מוליד וי\"ל כיון שכבר הוליד אלא שהפיל' ריע טענתו לבטל החזקה דלא מחזקת נפשה בעקרה נ\"י ולכאור' קשה הא היא אומרת דלא הפילה א\"כ לא הוליד כלל ואכתי יש לו מיגו בשלמא כשהפילה בוודאי אלא הם מחולקים כמה פעמים הפיל' שפיר תירצו אבל בדין זה כשהיא אומרת לא הפלתי קשה הא יש לו מיגו ואפשר דסבירא ליה הסוגיא איירי דהוליד פ\"א ומת הולד ואח\"כ הם מחלוקים כמה שנים לא הוליד' מ\"ה ריע טענתו והא דנאמן לומר דמכיר בעצמו שא\"י להוליד איירי כשלא הוליד עדיין ולרש\"י דפירש דהיא אומר' לא הפלתי ועקרה אני צ\"ל דס\"ל דאין אומרי' מיגו די\"ל עקר אני דהוא ג\"כ אינו רוצה להחזיק לנפשו לעקר בוודאי כשאומ' עקר אני נאמן אבל מיגו כזה לא אמרינן וא\"ל למה היא נאמנת להוציא ממון ממנו וכשהיא אומר' דאין לו גבורת אנשי' והוא מכחיש אינה נאמנת להוציא ממון כי ש\"ה דיש חזקה דאינה מעיזה וחזקה דלא היתה מחזק' נפשה לעקרה ולהפיל אף על גב לדברי' היא מותר' לאחר מ\"מ לא קפצי עליה כ\"כ:","\u0003משביעה שבועת היסת\u0004. כיון דיש כאן טענות ברי מה שהוא טוען מכחיש אותה אף על גב דאין טענתה על הכתובה מ\"מ לפ\"ד אין הזמן הפרעון השתא דעדיין לא עברו י\"ש שלא הולידה והוי כלוה הטוען דעדיין לא הגיע הז\"פ כמ\"ש בח\"ה סימן ע\"ג ועיין במגיד ובכ\"מ אף על גב חז\"ל האמינו אותה מטעם דלא מחזיק' לנפשה לעקרה מ\"מ צריכה לישבע היסת:","\u0003לא תנשא לשלישי\u0004. דקי\"ל בנישואין כרבי שני פעמים הוי חזקה אבל לענין ממון הלכה כרשב\"ג דלא הוי חזקה עד ג\"פ מ\"ה אית לה כתובה מן השני כ\"כ תוספות והא דבעינן ג\"פ בהפילה כתבתי בסמוך:","\u0003תצא שלא בכתובה\u0004. היינו תצא מיד אפילו הכיר בה דהא אסורה לו כשלא קיים פו\"ר ואין לו אשה אחרת אלא לענין ממון יש לחלק כמ\"ש תוס' אם הכיר בה צריך ליתן לה הכתובה ואם לא הכיר בה הוי כמקח טעות מ\"ה אין לה כתובה אפילו דלא שהה עם הג' י\"ש ואכתי לא הוחזק ג\"פ ואם נשאת למי שקיים פ\"ו או שיש לו אשה אחרת משמע דצריך ליתן לה הכתובה אפי' לא הכיר ולא אמר מ\"ט הוא:","\u0003לא תחזיר\u0004. משום דאמרי השתא היא כחשי מיהו טענה זו לא מהני להוציא ממון אלא מחמת טענה זו לא תחזור מה שגבתה מראשון ומשני כ\"כ תוס' והרא\"ש והטור, מיהו הנ\"י כתב בשם כמה פוסקים אפי' לא גבתה עדיין גובה מהם וכן משמע במרדכי דהא כתב אלו דברי' עשאו חז\"ל בבירור הדעת ולא מטעם ספק אף על גב מ\"ש שם דקי\"ל שטר העומד לגבות כגבוי דמי לא קי\"ל כוותי' מ\"מ דינו שפיר דלאו ספק הוא ונראה לדעת הרא\"ש דוק' אם גבתה מראשון ומשני לא תחזיר אבל תפיסה שלה לא מהני כיון דאין לה טענות ברי דהשתא כחשה:","\u0003ראוי להחמיר\u0004. עיין דינים אלו בתו' ובהרא\"ש ס\"פ הע\"י ובמ' ר\"פ המדיר וכללא הוא הנושא אשה בעבירה כופין אפילו בשוטי' כמ\"ש ס\"פ המדיר וכן אם נשא שני' וכן כל הני דאיתא רס\"ז לכ\"ע כופין בשוטים משום דמפורש בש\"ס דכופין אותם וכל הני דכופין מחמתם אין נותנים להם תוספות כתובה אבל כשהב\"ד כופין לגרשה כשלא ילדה י\"ש יש לה ת\"כ דלאו מחמתה הוא כמ\"ש בתוס' ס\"פ הע\"י, וכשבאה מחמת טענה איתא בש\"ס ס\"פ הנ\"ל דכופין אותו והיינו בשוטים וכ\"כ תוספות אלא הרשב\"א כתב בתשובה אלף קצ\"ב דלא כפינן ליה בשוטים אלא מוסיפי' על הכתובה כדין מורד, ומי ששהה עם אשתו י\"ש לדעת הרי\"ף כופין בשוטי' וכ\"כ הרמב\"ם פט\"ו ה\"א ועיין בדרישה, ובהג\"מ פ' הע\"י כתב בתחלה צ\"ע בזמן הזה אם יכול לגרשה בע\"כ כיון שגזר ר\"ג שלא לגרש אשה בע\"כ ואחר כך הביא תשובת ר\"ג דפסק דיכול לגרשה בע\"כ, ודוחק לומר תשובה זו כתב קודם התקנה, ובתשובת ריב\"ש סימן ט\"ו כתב דהעלימו חכמי דורות את עיניהם בענייני הזיווג משום דהיה צריך לכפות את כולם וא\"א לכן כל שאינו איסור מצד הנישואים העלימו עיניהם גם נתן טעם לפי מנהג ארצו דאפשר לו לישא עוד אחרת אף על גב זו אינה יולדה יכול לישא אחרת מ\"ה העלימו עיניהם נשמע מזה לפי מנהג שלנו אז טעם השני לא שייך כלל ואף לטעם הראשון מ\"מ האיסור במקומו עומד אלא חכמי הדור אין כופין מ\"מ האיסור חל ע\"כ אדם לכן נראה אפילו בזמן הזה דאיכא חר\"ג מ\"מ אם לא ילדה י\"ש יכול לגרשה בע\"כ ובכל אלו נראה אפי' הורה חכם להיתר ונשאת כופין להוציא ול\"ד למ\"ש בסי' י\"ז סעיף ל\"ד בשם תשובת הרא\"ש במים שאל\"ס והור' חכם להיתר לא תצא משום שם קי\"ל רוב' למית' לכן מקילין שם אבל באיסורים אלו אין היתר כלל:"]],["\u0003הלכות מיאון\u0004\nקְטַנָּה שֶׁאֵין לָהּ אָב, אוֹ שֶׁיֵּשׁ לָהּ אָב וְהִשִּׂיאָהּ אָבִיהָ וְנִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה כְּשֶׁהִיא קְטַנָּה, שֶׁהִיא כִּיתוֹמָה בְּחַיֵּי הָאָב, שֶׁהֲרֵי אֵין לוֹ עוֹד רְשׁוּת בָּהּ, \u0010c0\u0011 וְהִשִּׂיאוּהָ לְדַעְתָּהּ, כֵּיוָן שֶׁאֵין קִדּוּשֶׁיהָ אֶלָּא מִדְּרַבָּנָן, אִם אֵינָהּ חֲפֵצָה בְּבַעְלָהּ אֵינָהּ צְרִיכָה מִמֶּנּוּ גֵּט, אֶלָּא יוֹצֵאת מִמֶּנּוּ בְּמֵאוּן. אֲבָל אִם הִשִּׂיאוּהָ שֶׁלֹּא לְדַעְתָּהּ, אוֹ אֲפִלּוּ לְדַעְתָּהּ, וְאֵינָהּ יוֹדַעַת לִשְׁמֹר קִדּוּשֶׁיהָ, \u0010c1\u0011 אֲפִלּוּ מֵאוּן אֵינָהּ צְרִיכָה. \u0005 הַגָּה: וּלְכַתְּחִלָּה יֵשׁ לְבֵית דִּין לִזָהֵר שֶׁלֹּא לְהַשִּׂיא יְתוֹמָה קְטַנָּה בְּמָקוֹם שֶׁנִּרְאֶה לָהֶם שֶׁיָּבֹא לִידֵי מֵאוּן. וְאֵין לַדַּיָּן בְּזֶה אֶלָּא מַה שֶּׁעֵינָיו רוֹאוֹת \u0006 \u0005(הַגִּהוֹת מַיְמוֹנִי פֶּרֶק י\"א בְּשֵׁם ר\"י)\u0006:\nאֵיזוֹ הִיא קְטַנָּה שֶׁצְּרִיכָה לְמָאֵן, \u0010c2\u0011 מִבַּת שֵׁשׁ שָׁנִים עַד בַּת עֶשֶׂר בּוֹדְקִין אוֹתָהּ לְפִי יֹפִי דַּעְתָּהּ אִם יוֹדַעַת לִשְׁמֹר קִדּוּשֶׁיהָ, וְשֶׁהֵם קִדּוּשִׁין, לֹא שֶׁתִּשְׁמֹר אוֹתָם כְּדֶרֶךְ שֶׁמְּשַׁמֶּרֶת הָאֱגוֹז וְהַתְּמָרָה וְכַיּוֹצֵא בָּהֶם, הֲרֵי זוֹ צְרִיכָה מֵאוּן. וְאִם אֵינָהּ יוֹדַעַת לִשְׁמֹר קִדּוּשֶׁיהָ, אֵינָהּ צְרִיכָה לְמָאֵן, אֶלָּא הוֹלֶכֶת לְבֵית אִמָּהּ כְּאִלּוּ לֹא נִתְקַדְּשָׁה מֵעוֹלָם. וּפְחוּתָה מִבַּת שֵׁשׁ, אֲפִלּוּ הִיא נְבוֹנָת לַחַשׁ בְּיוֹתֵר וְיוֹדַעַת לִשְׁמֹר, אֵינָהּ צְרִיכָה מֵאוּן. וִיתֵרָה עַל בַּת עֶשֶׂר, \u0010c3\u0011 אֲפִלּוּ סְכָלָה בְּיוֹתֵר, צְרִיכָה מֵאוּן. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּכָל זֶה כְּשֶׁנִּשֵּׂאת לְדַעַת אַחֶיהָ \u0010c4\u0011 וְאִמָהּ, אֲבָל אִם נִשֵּׂאת שֶׁלֹּא לְדַעְתָּן, אֵינָהּ צְרִיכָה לְמָאֵן \u0006 \u0005(הַגָהוֹת אַלְפִסִי פֶּרֶק \u0010c5\u0011 בֵּית שַׁמַאי)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּאִם הִגִּיעָה לְפָעוֹטוֹת, צְרִיכָה לְמָאֵן \u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הִרִיטְבָ\"א)\u0006:\nהַמֵּאוּן הוּא שֶׁתֹּאמַר: אִי אֶפְשִׁי בִּפְלוֹנִי בַּעְלִי אוֹ אִי אֶפְשִׁי בַּקִּדּוּשִׁין שֶׁקִּדְּשׁוּנִי אִמִּי וְאַחַי. וַאֲפִלּוּ לֹא אָמְרָה דָּבָר, אֶלָּא הָלְכָה וְנִתְקַדְּשָׁה לְאַחֵר כְּשֶׁהִיא קְטַנָּה, אַף עַל פִּי שֶׁהָיְתָה נְשׂוּאָה, קִדּוּשֶׁיהָ הֵם הֵם מֵאוּנֶיהָ:\nמְמָאֶנֶת, בֵּין \u0010c6\u0011 מִן הָאֵרוּסִין בֵּין מִן הַנִּשּׂוּאִין, אֲפִלּוּ שֶׁלֹּא בִּפְנֵי הַבַּעַל וְשֶׁלֹּא בִּפְנֵי בֵּית דִּין, רַק שֶׁיִּהְיֶה \u0010c7\u0011 בִּפְנֵי שְׁנַיִם שֶׁיָּעִידוּ עַל הַדָּבָר. \u0010c8\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, דִּלְכַתְּחִלָּה בָּעֵינָן ג':\nכְּשֵׁם שֶׁמְּמָאֶנֶת בַּבַּעַל כָּךְ מְמָאֶנֶת בַּיָּבָם, אִם לֹא מֵאֲנָה בַּבַּעַל:\nמֵאֲנָה בַּבַּעַל וְנִשֵּׂאת לְאַחֵר, מְמָאֶנֶת בּוֹ. וְכֵן בַּשְּׁלִישִׁי וּבָרְבִיעִי, אֲפִלּוּ כַּמָּה פְּעָמִים, כָּל זְמַן שֶׁהִיא קְטַנָּה:\nהַשְּׁנַיִם שֶׁמֵּאֲנָה בִּפְנֵיהֶם כּוֹתְבִין לָהּ גֵּט מֵאוּן וְחוֹתְמִין בּוֹ וְנוֹתְנִים לָהּ. וְאֵינוֹ כְּגֵט גֵּרוּשִׁין לִהְיוֹת נְתִינָתוֹ מְגָרֵשׁ, לְפִיכָךְ, אֵינוֹ צָרִיךְ כְּתִיבָה לִשְׁמָהּ, וְלֹא מְסִירָה, וְלֹא דָּבָר מִמִּשְׁפְּטֵי גֵּט הַגֵּרוּשִׁין. וְאֵין כּוֹתְבִין בּוֹ טֹפֶס הַגֵּט, לְפִי שֶׁאֵינוֹ אֶלָּא כְּמַעֲשֵׂה בֵּית דִּין:\nאֵלּוּ שֶׁמְּמָאֶנֶת בִּפְנֵיהֶם \u0010c9\u0011 צָרִיךְ שֶׁיַּכִּירוּ אוֹתָהּ וְאֶת בַּעְלָהּ. לְפִיכָךְ, כָּל מִי שֶׁיִּרְאֶה \u0010c10\u0011 שֶׁמֵּאֲנָה בִּפְנֵי שְׁנַיִם יָכוֹל לִכְתֹּב לָהּ גֵּט מֵאוּן, אַף עַל פִּי שֶׁאֵינוֹ מַכִּירָהּ, שֶׁוַּדַּאי הִכִּירוּהָ אוֹתָם שֶׁמֵּאֲנָה בִּפְנֵיהֶם. \u0005 וְדַוְקָא לְכַתְּחִלָּה, אֲבָל בְּדִיעֲבַד אֲפִלּוּ שֶׁאֵינָם מַכִּירִים הַבַּעַל רַק הָאִשָּׁה, סָגֵי \u0006 \u0005(כ\"כ הַב\"י)\u0006:\nאוֹתָם שֶׁמְּמָאֶנֶת בִּפְנֵיהֶם צָרִיךְ שֶׁיִּתְבָּרֵר לָהֶם שֶׁהִיא קְטַנָּה:\nקְטַנָּה הַמְמָאֶנֶת אֵין לָהּ כְּתֻבָּה מָנָה וּמָאתַיִם, אֲבָל \u0010c11\u0011 יֵשׁ לָהּ תּוֹסֶפֶת. וְכָל זְמַן שֶׁלֹּא מֵאֲנָה, בַּעְלָהּ זַכַּאי בְּמַעֲשֵׂה יָדֶיהָ וּבִמְצִיאָתָהּ, וְחַיָּב בִּמְזוֹנוֹתֶיהָ וּפִדְיוֹנָהּ כָּל זְמַן שֶׁהִיא תַּחְתָּיו, אֲבָל אִם הָלַךְ לִמְדִינַת הַיָּם, וְלָוְתָה וְאָכְלָה אוֹ לְצֹרֶךְ פִּדְיוֹנָהּ, וְעָמְדָה וּמֵאֲנָה, אֵינוֹ חַיָּב לְשַׁלֵּם, אַף עַל פִּי שֶׁאָכַל פֵּרוֹתֶיהָ, וַאֲפִלּוּ הֵם בָּעַיִן עֲדַיִן, שֶׁלִּקְּטָן וּמֻנָּחִין בִּרְשׁוּתוֹ, אֵינוֹ מַחֲזִירָן. וּנְכָסִין שֶׁל צֹאן בַּרְזֶל וְשֶׁל מְלוֹג, אִם הֵם בָּעַיִן, נוֹטַלְתָּן; וּמַה שֶּׁאָבַד מֵהֶם \u0010c12\u0011 מִנִּכְסֵי צֹאן בַּרְזֶל, חַיָּב לְשַׁלֵּם; וּמִנִּכְסֵי מְלוֹג, פָּטוּר. וְהוּא מֻתָּר בִּקְרוֹבוֹתֶיהָ, וְהִיא מֻתֶּרֶת בִּקְרוֹבָיו, וּכְשֵׁרָה לִכְהֻנָּה, וְאֵינָהּ צְרִיכָה לְהַמְתִּין ג' חֳדָשִׁים מִלְּהִנָּשֵׂא; וְאִם נִשֵּׂאת לְאַחֵר וְגֵרְשָׁהּ אוֹ מֵת, מֻתֶּרֶת לַחֲזֹר לָרִאשׁוֹן. וְלֹא עוֹד, אֶלָּא אֲפִלּוּ גֵּרְשָׁהּ הָרִאשׁוֹן, וְהֶחֱזִירָהּ, וּמֵאֲנָה בּוֹ, וְנִשֵּׂאת לְאַחֵר אַחַר שֶׁמֵּאֲנָה בּוֹ, וְגֵרְשָׁהּ הָאַחֵר, מֻתֶּרֶת לַחֲזֹר לָרִאשׁוֹן. שֶׁכָּל הַיּוֹצֵאת בְּמֵאוּן, אַף עַל פִּי שֶׁקָּדְמוֹ גֵּט, הֲרֵי זוֹ כְּמִי שֶׁלֹּא נִתְגָּרְשָׁה מִמֶּנּוּ בְּגֵט מֵעוֹלָם, וּמֻתֶּרֶת לַחֲזֹר לוֹ. אֲבָל הַמְגָרֵשׁ אֶת הַקְּטַנָּה בְּגֵט, יֵשׁ לָהּ כְּתֻבָּה, וְאָסוּר בִּקְרוֹבוֹתֶיהָ, וַאֲסוּרָה בִּקְרוֹבָיו, וַאֲסוּרָה לִכְהֻנָּה, וּצְרִיכָה לְהַמְתִּין שְׁלשָׁה חֳדָשִׁים; וְאִם נִשֵּׂאת לְאַחֵר וּמֵאֲנָה בּוֹ, \u0010c13\u0011 אֲסוּרָה לַחֲזֹר לָרִאשׁוֹן, מִפְּנֵי שֶׁיָּצְאָה מִמֶּנּוּ בְּגֵט, אַף עַל פִּי שֶׁיָּצְאָה מִן הָאַחֲרוֹן בְּמֵאוּן, וְאֵין צָרִיךְ לוֹמַר אִם גֵּרְשָׁהּ הָאַחֲרוֹן אוֹ מֵת. וְכֵן אֲסוּרָה \u0010c14\u0011 לַאֲבִי הָרִאשׁוֹן, וְלִבְנוֹ, וּלְאֶחָיו, כִּשְׁאָר הַגְּרוּשׁוֹת, אַף עַל פִּי שֶׁיָּצָת מִן הָאַחֲרוֹן בְּמֵאוּן. וְאִם מֵאֲנָה בָּרִאשׁוֹן, וְהֶחֱזִירָהּ וְגֵרְשָׁהּ וְנִשֵּׂאת לְאַחֵר וְנִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה אוֹ מֵאֲנָה בּוֹ, אֲסוּרָה לַחֲזֹר לָרִאשׁוֹן וְלִקְרוֹבָיו. שֶׁכָּל שֶׁיָּצָת מִמֶּנּוּ בְּמֵאוּן לְבַסוֹף, דִּינָהּ כִּמְמָאֶנֶת; וְכֹל שֶׁיָּצָת מִמֶּנּוּ בְּגֵט לְבַסוֹף, דִּינָהּ כִּמְגֹרֶשֶׁת:\nהַמְמָאֶנֶת בַּיָבָם, \u0010c15\u0011 אֲסוּרָה בְּאָבִיו, מִפְּנֵי שֶׁנִּרְאֵית כְּכַלָּתוֹ בְּעֵת שֶׁמֵּת בְּנוֹ וְנָפְלָה לְיִבּוּם. אֲבָל לִשְׁאָר קְרוֹבִים, מֻתֶּרֶת. וְיֵשׁ אוֹמְרִים גַּם בִּשְׁאָר קְרוֹבִים. \u0005 וְדַוְקָא בִּקְרוֹבֵי הַמֵת, אֲבָל בִּקְרוֹבֵי הַיָּבָם שֶׁמֵאֲנָה בּוֹ מֻתֶּרֶת \u0006 \u0005(כ\"כ הב\"י)\u0006. \u0010c16\u0011 וּמִכָּל מָקוֹם אִם מֵאֲנָה בְּאֶחָד מֵהַיְבָמִים, מֻתֶּרֶת לִשְׁאָר אַחִין:\nעַד מָתַי הַקְּטַנָּה מְמָאֶנֶת, עַד שֶׁתָּבִיא ב' שְׂעָרוֹת אַחַר י\"ב שָׁנָה, \u0010c17\u0011 אוֹ עַד שֶׁתֵּלֵד. \u0005 וּמִשְּׁעַת הֵרָיוֹן הָוֵי כִּגְדוֹלָה \u0006 \u0005(א\"ז)\u0006. וְכָל זְמַן שֶׁלֹּא הֵבִיאָה ב' שְׂעָרוֹת וְלֹא יָלְדָה, חֲשׁוּבָה כִּקְטַנָּה, אֲפִלּוּ נוֹלְדוּ לָהּ סִימָנֵי אַיְלוֹנִית. אֲבָל אִם הִיא בַּת עֶשְׂרִים, וְנוֹלְדוּ בָּהּ סִימָנֵי אַיְלוֹנִית, חֲשׁוּבָה כִּגְדוֹלָה \u0010c18\u0011 \u0005 לְמַפְרֵעַ, מִזְמַן שֶׁהָיְתָה בַּת י\"ב, אַף עַל גַּב שֶׁהֵבִיאָה אַחַר כָּךְ שְׁתֵּי שְׂעָרוֹת \u0006 \u0005(בְּחֹשֶן הַמִשְׁפָּט סִי' רל\"ה)\u0006, וְאֵינָהּ יְכוֹלָה לְמָאֵן. וּבַת י\"ט שָׁנָה וּשְׁלשִׁים יוֹם, דִּינָהּ כְּבַת כ', דְּל' יוֹם בַּשָּׁנָה חָשׁוּב שָׁנָה. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֵינָהּ חֲשׁוּבָה בַּת כ' שָׁנָה עַד שֶׁתִּהְיֶה בַּת כ' שָׁנָה פָּחוֹת ל' יוֹם:\nאִם הִיא בַּת כ', וְלֹא נוֹלְדוּ בָּהּ סִימָנֵי אַיְלוֹנִית וְלֹא הֵבִיאָה שְׁתֵּי שְׂעָרוֹת, חֲשׁוּבָה כִּקְטַנָּה עַד שֶׁתָּבִיא ב' שְׂעָרוֹת אוֹ שֶׁתַּגִּיעַ לְרֹב שְׁנוֹתֶיהָ שֶׁהֵם ל\"ה שָׁנָה וְיוֹם אֶחָד, שֶׁאָז הֲרֵי הִיא אַיְלוֹנִית אַף עַל פִּי שֶׁלֹּא נִרְאוּ בָּהּ סִימָנֵי אַיְלוֹנִית, וַחֲשׁוּבָה כִּגְדוֹלָה וְאֵינָהּ יְכוֹלָה לְמָאֵן. \u0005וְע\"ל סִי' קע\"ב סִימָנֵי אַיְלוֹנִית מַה הֵם: \u0006\nאֵין שְׁתֵּי שְׂעָרוֹת סִימָן גַּדְלוּת אֶלָּא אִם כֵּן בָּאוּ מִי\"ב שָׁנָה וְאֵילָךְ, אֲבָל אִם בָּאוּ קֹדֶם לָכֵן, אֲפִלּוּ תּוֹךְ שְׁנַת שְׁנֵים עָשָׂר, חֲשִׁיבִי כְּשׁוּמָא, וְאֵינָהּ נֶחֱשֶׁבֶת גְּדוֹלָה עַל יָדָם, אֶלָּא אִם כֵּן הֵבִיאָה אֲחֵרוֹת אַחַר שְׁנֵים עָשָׂר שָׁנָה. \u0005 וְיֵשׁ אוֹמְרִים שֶׁאִם הֵבִיאָה שְׂעָרוֹת \u0010c19\u0011 בְּיוֹם אַחֲרוֹן שֶׁל שְׁנַת שְׁנֵים עָשָׂר חֲשׁוּבָה גְּדוֹלָה \u0006 \u0005(טוּר בְּשֵׁם ר\"ת וְכ\"כ הָרֹא\"שׁ)\u0006. וּמִיהוּ, כְּשֶׁמּוֹצְאִים לָהּ שְׂעָרוֹת אַחַר הַזְּמַן, מַחֲזִיקִין אוֹתָהּ כִּגְדוֹלָה אֲפִלּוּ לַחֲלִיצָה, וְלֹא חַיְשִׁינָן שֶׁמָּא בָּאוּ קֹדֶם הַזְּמַן. \u0010c20\u0011 וְיֵשׁ אוֹמְרִים שֶׁאִם נִרְאוּ בָּהּ ב' שְׂעָרוֹת קֹדֶם שְׁתֵּים עֶשְׂרֵה שָׁנָה, וְעוֹדָם עָלֶיהָ אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה, אַף עַל פִּי שֶׁלֹּא הֵבִיאָה שְׂעָרוֹת אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה, חֲשׁוּבָה כִּגְדוֹלָה לְמֵאוּן, וְאַף עַל פִּי כֵן חֲשׁוּבָה כִּקְטַנָּה לַחֲלִיצָה. \u0005 סָפֵק אִם הִגִּיעָה לִשְׁנֵים עָשָׂר שָׁנִים \u0010c21\u0011 אוֹ לֹא, אָזְלִינַן לְחֻמְרָא \u0006 \u0005(בִּתְשׁוּבַת רַשְׁבִּ\"א אִלֶף רי\"ו)\u0006:\nכְּשֶׁבּוֹדְקִין אוֹתָהּ, בּוֹדְקִין עַל יְדֵי נָשִׁים כְּשֵׁרוֹת וְנֶאֱמָנוֹת. וַאֲפִלּוּ אִשָּׁה אַחַת בּוֹדְקָהּ, וְשׁוֹמְעִין לָהּ \u0010c22\u0011 אִם הֵבִיאָה וְאִם לֹא הֵבִיאָה, וַאֲפִלּוּ הִיא קְרוֹבָה. \u0005 וְעַיֵן לְקַמָן סִימָן קס\"ט, אִם נָשִׁים נֶאֱמָנוֹת עַל שְׁנוֹתֶיהָ: \u0006\nשְׁתֵּי שְׂעָרוֹת צָרִיךְ שֶׁיִּהְיֶה בְּעִקָּרָן גֻּמּוֹת. וַאֲפִלּוּ שְׁתֵּיהֶן בְּגֻמָּא אַחַת הֲרֵי אֵלּוּ סִימָן. נִמְצְאוּ שְׁתֵּי גֻּמּוֹת זוֹ בְּצַד זוֹ וְאֵין בָּהֶן שֵׂעָר, הֲרֵי אֵלּוּ סִימָן, חֲזָקָה אֵין גֻּמָּא בְּלֹא שֵׂעָר, וּשְׂעָרוֹת הָיוּ בָהֶם וְנָשְׁרוּ:\nב' שְׂעָרוֹת צְרִיכוֹת שֶׁיִּהְיוּ \u0010c23\u0011 בִּמְקוֹם הָעֶרְוָה. וּבֵית הָעֶרְוָה כֻּלּוֹ מְקוֹם סִימָנִים, בֵּין לְמַעְלָה בֵּין לְמַטָּה, בֵּין עַל אֶבְרֵי הַזֶּרַע עַצְמָן. וְיֵשׁ מִי שֶׁאוֹמֵר, \u0010c24\u0011 שֶׁאֲפִלּוּ אַחַת בְּגַבָּהּ וְאַחַת בִּכְרֵסָהּ, אוֹ אַחַת בְּקִשְׁרֵי אֶצְבְּעוֹתֶיהָ שֶׁל יָד וְאַחַת בְּקִשְׁרֵי אֶצְבְּעוֹתֶיהָ שֶׁל רֶגֶל, חֲשׁוּבָה גְּדוֹלָה לְמֵאוּן אֲבָל לֹא לַחֲלִיצָה: \u0010c25\u0011\nשִׁעוּר אֹרֶךְ הַשְּׁתֵּי שְׂעָרוֹת, מִשֶּׁיִּצְמְחוּ וְיִהְיוּ רְאוּיִים לְהִנָּטֵל \u0010c26\u0011 בְּפִי הַזּוּג \u0005(פי', מִסְפִּרַיִם)\u0006 אוֹ לִקְרֹץ בַּצִּפֹּרֶן, חֲשׁוּבָה גְּדוֹלָה לְמֵאוּן. אֲבָל אֵינָהּ חֲשׁוּבָה גְּדוֹלָה לַחֲלִיצָה עַד שֶׁיִּהְיֶה בָּהֶן כְּדֵי לָכֹף רֹאשָׁן \u0010c27\u0011 לְעִקָּרָן. \u0005וְעַיֵן לְקַמָן בְּפֵרוּשׁ סֵדֶר הַחֲלִיצָה סִימָן כ\"ז: \u0006\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיְּכוֹלָה לְמָאֵן אַחַר י\"ב שָׁנָה, כְּשֶׁבָּדְקוּ אוֹתָהּ וְלֹא הֵבִיאָה שְׁתֵּי שְׂעָרוֹת. אֲבָל סְתָמָא, מִשֶּׁיֵּשׁ לָהּ י\"ב שָׁנָה אֵינֶנָּה יְכוֹלָה לְמָאֵן, חֲזָקָה שֶׁהֵבִיאָה שְׁתֵּי שְׂעָרוֹת. וּמִכָּל מָקוֹם לֹא תַּחֲלֹץ עַד שֶׁיִּבְדְּקוּ אוֹתָהּ וְיִמְצְאוּ שְׁתֵּי שְׂעָרוֹת:\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיְּכוֹלָה לְמָאֵן כְּשֶׁבּוֹדְקִים אוֹתָהּ וְלֹא הֵבִיאָה, \u0010c28\u0011 כְּשֶׁלֹא בָּעַל אַחַר הֱיוֹת לָהּ שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד. אֲבָל אִם בָּא עָלֶיהָ אַחַר כָּךְ, אֵינָהּ יְכוֹלָה לְמָאֵן, שֶׁאַף עַל פִּי שֶׁאֵין מוֹצְאִין לָהּ סִימָנִין חוֹשְׁשִׁין שֶׁמָּא נָשְׁרוּ; שֶׁהוּא סָפֵק דְּאוֹרָיְתָא, שֶׁאִם הָיָה יָדוּעַ שֶׁהָיוּ לָהּ שְׁתֵּי שְׂעָרוֹת קֹדֶם שֶׁבָּא עָלֶיהָ הֲווֹ קִדּוּשִׁין גְּמוּרִים, שֶׁוַּדַּאי בָּעַל לְשֵׁם קִדּוּשִׁין, וְאִם קִדְּשָׁהּ אַחֵר לֹא הָיְתָה צְרִיכָה מִמֶּנּוּ גֵּט; וְכֵיוָן שֶׁהוּא סָפֵק דְּאוֹרָיְתָא חַיְשִׁינָן שֶׁמָּא הֵבִיאָה סִימָנִין קֹדֶם שֶׁבָּעַל, וּצְרִיכָה גֵּט מִסָפֵק. וְאִם מֵאֲנָה בּוֹ אַחַר שֶׁנִּבְעֲלָה, וְנִבְדְּקָה וְלֹא נִמְצְאוּ לָהּ שְׂעָרוֹת, וְנִתְקַדְּשָׁה לְאַחֵר, \u0010c29\u0011 צְרִיכָה מִמֶּנּוּ גֵּט, מִסָפֵק, וַאֲסוּרָה לַחֲזֹר לוֹ, וְאִם נִשֵּׂאת תֵּצֵא מִזֶּה וּמִזֶּה; \u0010c30\u0011 וְהַוָּלָד, סְפֵק מַמְזֵר מִשְּׁנֵיהֶם:\nהֵבִיאָה שְׁתֵּי שְׂעָרוֹת אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה, וְלֹא בָּעַל אַחַר כָּךְ, הֲווֹ סְפֵק קִדּוּשִׁין. וְאִם בָּא לְהוֹצִיאָהּ \u0010c31\u0011 צְרִיכָה גֵּט, מִדְּרַבָּנָן. וְאִם לֹא גֵּרְשָׁהּ, וְעָמְדָה וְנִתְקַדְּשָׁה לְאַחֵר, צְרִיכָה גֵּט מִשְּׁנֵיהֶם. וְאִם יִרְצוּ, מְגָרֵשׁ רִאשׁוֹן וְנוֹשֵׂא שֵׁנִי. אֲבָל אִם גֵּרַשׁ שֵׁנִי, \u0010c32\u0011 לֹא יְקַיֵּם רִאשׁוֹן, שֶׁמָּא יֹאמְרוּ: הֶחֱזִיר גְּרוּשָׁתוֹ אַחַר שֶׁנִּתְאָרְסָה. וְאִם בָּא עָלֶיהָ שֵׁנִי קֹדֶם שֶׁגֵּרַשׁ רִאשׁוֹן, תֵּצֵא מִזֶּה וּמִזֶּה, וְאֵין הַוָּלָד מִן הַשֵּׁנִי מַמְזֵר. וְאִם בָּא עָלֶיהָ רִאשׁוֹן קֹדֶם \u0005(גֵּרוּשֵׁי)\u0006 שֵׁנִי, הַוָּלָד מַמְזֵר:\nיֵשׁ אוֹמְרִים דְּהָאִדָּנָא יֵשׁ לְהַחֲמִיר שֶׁלֹּא תְּמָאֵן \u0010c33\u0011 אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה, אַף עַל פִּי שֶׁנִּבְדְּקָה וְלֹא נִמְצְאוּ לָהּ שְׁתֵּי שְׂעָרוֹת וְגַם לֹא בָּעַל אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה. \u0005 הַגָּה: וּלְכֻלֵּי עָלְמָא אִם הִיא פְּחוּתָה מִבַּת שְׁתֵּים עֶשְׂרֵה שָׁנָה מְמָאֶנֶת, אֲפִלּוּ בַּזְמַן הַזֶה. וְכֵן עָשָׂה מהר\"ר יַעֲקֹב פּוֹלַק זַ\"ל מַעֲשֶׂה בְּיָמָיו. וּדְלֹא כְּיֵשׁ מַחֲמִירִין וְאָמְרוּ שֶׁאֵין בַּת מְמָאֶנֶת בַּזְמַן הַזֶה כְּלָל \u0006 \u0005(מהר\"ם מֵרִיזְבּוּרְק וְר\"י מִינְץ סִימָן י\"ג)\u0006:",[],["\u0003והשיאו'\u0004. כתב הנ\"י בשם הרמב\"ן וכמה פוסקים דווקא אם השיא' צריכה מיאון אבל נתקדשה ע\"י אמה ואחי' מדעת' והיא לא קבלה הקדושי' א\"צ מיאון שלא מצינו שליחות לקטן וכן דייק מהרש\"ל מסמ\"ג עיין בטור סי' מ\"ג ועיין בדרישה שם ושם כתבתי בס\"ק ה' בשם רש\"י והר\"ן אף אחר שנעשה כיתומה בחיי האב לא גרע מיהא כח האב מכח אמה ואחי' ועיין במגיד שכתב בשם ירושלמי מדעת' היינו עבדינן לה גננא ומלבושין ומדכרי לה גבר שלא מדעתה דלא מדכרן לה גבר:","\u0003אפי' מיאון אין צריכה\u0004. כתב הנ\"י בשם ר\"ח דפנויה היא אפי' גדלה תחתיו ולא בעיל אותה אין צריכה מיאון ומותרת לאחר ורשב\"א כתב דאסורה לאחר אלא אם מתה אין יורשה ואין מזכה במציאתה משא\"כ אם השיאוה לדעתה כל זמן שלא מיאנה זוכה בכל הדברים שבעל זוכה כמ\"ש בסעיף י':","\u0003מבת שש שנים וכו'\u0004. היינו לפי גירסת הרי\"ף והרמב\"ם פ' התקבל הפעוטות מקחן מקח וכנגדן קטנה מתקדשת למיאון ובפ' ב\"ש אר\"ח כל שיכולה לשמור קדושיה צריכה מיאון ופירש רמב\"ם דר\"ח קאי על פעוטות היינו מבת ו' ועד בת י' כ\"א לפי חורפיה והיינו חורפיה שיודעת לשמור קידושין, אבל פחות מבת ו' בזה לא דיבר ר\"ח ואפי' יודעת לשמור קידושין א\"צ מיאון, ולענין גט אפי' פחות מו' מקבלת הגט היינו צרור וזרקתו מתגרשת בקדושי אביה לפי גירסת הרמב\"ם והטעם מבואר בר\"ן פ' התקבל קידושין שהם כסף וצריכה שמירה מ\"ה לענין קידושין צריכה להיות עכ\"פ שיעור פעוטות ומ\"ש בכ\"מ פ\"ד מה\"א לרמב\"ם אף פחות מו' ויודעת לשמור קידושין צריכה מיאון, תמוה בעיני דהא כתב פי\"א מה\"ג להדיא אפי' אם יודעת לשמור קידושין א\"צ מיאון כמ\"ש המחבר כאן לשונו מיהו לדעת הרמ\"ך שהביא הכ\"מ פ\"ד מה\"א ס\"ל אף פחות מו' כל שיודעת לשמור קידושיה צריכה מיאון וס\"ל כל חד שיעור בפני עצמה הפעוטות מסתמא צריכה מיאון, ואם יודעת לשמור קידושי' אפי' פחות מו' צריכה מיאון וכן לגירסת רש\"י ותוס' והרא\"ש שם צרור וזרקתו שיעור למיאון והיינו מ\"ש ר\"ח אם יודעת לשמור קידושי' והיא פחות מו' כמ\"ש הר\"ן פ' המקבל במיאון שהוא קידושין דרבנן א\"צ שיעור פעוטות ולעיל סימן קמ\"א הביא המחבר דעתם לפי גירסתם ממילא במיאון אפילו פחותה מו' צריכה מיאון וכאן השמיט דעתם אפשר דס\"ל כיון שהיא רק קידושין דרבנן מקיל וגם לשיטות הריטב\"א שהביא בסמוך בהג\"ה והיינו שיטת הראב\"ד כמ\"ש פ\"ד מה\"א ופ\"א מה\"ג ובעל המאור דף תמ\"ב ס\"ל תרי שיעור הן נינהו ור\"ח איירי אפילו פחות מו' צריכה מיאון כשנתקדשו ע\"י אחיה לכן נראה להחמיר בזה דצריכה מיאון אף בפחות מו':","\u0003אפילו סכלה ביותר\u0004. לאו למימרא דעושה מעשה שטות אלא דאינה חריפה כלל מ\"מ כיון שהיא בת י' חזקה על הרוב שיודעת לשמור קידושי' כ\"מ פ\"ד מה\"א:","\u0003אבל אם נשאת שלא לדעתן וכו'\u0004. דאז הוי כפיתוי בעלמא ופיתוי קטנה הוי כאונס שם בש\"ג וברמב\"ם פ\"ד מה\"א כתב אפילו נתקדשה מדעתה בלא דעת אמה ואחיה צריכה מיאון, ואפשר לטעמיה אזיל דס\"ל אף פיתוי קטנה לא הוי כאונס וכן יש לדייק מרש\"י פ' התקבל (גיטין דף ס\"ה) ד\"ה כנגדן דס\"ל דקידושין ע\"י עצמה מהני ויש ליישב גם משמע שם דרש\"י שם לא ס\"ל כרמב\"ן שהבאתי בס\"ק א', ועיין בת\"ה סי' ר\"ח דפוסק בהלך למ\"י ונתקדשה בעצמה הוי קידושין:","\u0003וי\"א דאם הגיע וכו'\u0004. ס\"ל שיעור ר\"ח ושיעור הפעוטות תרי שיעורים הם שיעור ר\"ח איירי כשנתקדשה ע\"י אחיה והפעוטות איירי כשנתקדשה ע\"י עצמה וכו':","\u0003מן האירוסין\u0004. היינו כשקבלה היא הקדושין לדעת הרמב\"ן כמ\"ש רס\"ז ומדעת אמה או אחיה:","\u0003בפני שנים\u0004. כלומר חד נמי סגי אלא שצריך עדות שמיאנה אף על גב קידושין או נישואין הם המיאון ואם נתקדשה הרי ראינו דמיאנ' וי\"א דנ\"מ אם גדלה ולא נתקדש' אח\"כ דמותרת לאחר:","\u0003ויש מי שאומר וכו'\u0004. אם נשאת או נתקדשה בפרהסיא הוי כאלו מיאנה בפני ג', וכשנתקדשה בצנעה צריכה עכ\"פ לפני ג':","\u0003צריך שיכירו אותה ואת בעלה\u0004. אותה צריכים להכיר מחמ' החשש שמא יש עוד קטנה שהשיאו אחיה ורמאי זה פתה קטנה שאין אנו מכירין ויחליף את שמה בשם קטנה הנ\"ל ויפת' קטנ' הנ\"ל אחר שתגדיל אצל הראשון שתאמר שמיאנה בקטנות וגט מיאון יתן לידה ובעלה צריכין להכיר כתב המגיד בקטנים דלא נפיק שמם חיישינן שמא איכא קטנה דשמה כשמה ואיהי מסקא שם בעלה כשם בעלה של אותה קטנה אבל לחוש שמא שמות קטנו' ושמות בעליהן שוים לא חיישינן:","\u0003שמיאנה בפני שנים\u0004. בש\"ס איתא ב' גירס' בפ' מצות חליצה (יבמות דף ק\"ו) לרבא דאמר כותבין גט מיאון אף על פי שאין מכירין לגירס' דידן איתא ולא חיישינן לב\"ד טועין כלומר לא חיישינן שמא הב\"ד אשר מיאנ' בפניהם טעו ולא היו מכירין ולגירס' התו' אית' חיישינן לב\"ד טועין כלומר אלו אשר מיאנו בפניהם צריכים שיהי' מכירין אותה דאם לא יהיה מכירין אותה חיישינן לב\"ד טועין אשר ישמעו המיאון יסמכו עליה' ובפ' י\"נ דף קל\"ח איתא שכ\"מ שאמר מנה יש לו אצל פלוני העדים כותבי' אף על פי שאין מכירין ולא חיישינן לב\"ד טועין שמא יסמכו על העדות כי ב\"ד בתר ב\"ד לא דייקו ויבוא לסמוך במיאון על הב\"ד אשר מיאנו בפניה' אבל לא חיישינן שיסמכו על העדים אשר יכתבו דברי השכ\"מ כי עדים דייקו, לפ\"ז אליבא דהלכתא דמיאון סגי בפני שנים והיינו עדים תו לא חיישינן דהב\"ד יסמכו עליהם למה אמר רבא אין מאינין אא\"כ מכירין מ\"ש מיאון ומ\"ש צוואת שכ\"מ ואפש' רבא ס\"ל לכתחלה בעינן ג' במיאון ולזה אמר חיישינן לב\"ד טועין מ\"מ נשמע אם המיאון בפני ב' יש לחוש שמא לא היה מכירין א\"כ קשה איך פסקו בפשיטות כל מי שיראה שמיאנה בפני ב' יכול לכתוב הא בפני שנים יש לחוש שמא לא היה מכירין וא\"י איך כל האחרונים לא שתו לבם לזה:","\u0003יש לה תוס'\u0004. עיין סימן קט\"ז שם כתבתי הטעם:","\u0003מנצ\"ב חייב לשלם\u0004. הנה בש\"ס מבואר בליתנהו אידי ואידי בין נ\"מ בין נצ\"ב לא שקלה וכ\"כ הרמב\"ם פכ\"ד ה\"א ופרש\"י הטעם די\"ל אם תשאר תחתיו שמא תמות היא בחייו וירשנה וכ\"כ הרא\"ש לפ\"ז אפי' אם הוציא נ\"מ שלא היה לו להוציא כגון שמכרום א\"צ להחזיר, וכ\"כ התו' להדיא והר\"ן כתב דוקא כשנשתמש כדין ובלה אז הוא פטור לשלם וכן משמע מרמב\"ם שם וה\"ה אם נאבד או נגנב פטור לשלם אבל אם הוציא שלא כדין חייב לשלם ולמעש' צ\"ע בנ\"מ כי י\"ל קום לי כתוס' וכן ברש\"י משמע נמי דס\"ל אפי' הוציא שלא כדין פטור ע\"ש ומ\"ש מנצ\"ב חייב לשלם ט\"ס הוא דהא נצ\"ב הוצי' כדין ואפשר דצ\"ל נ\"מ חייב והיינו אם נשתמש שלא כדין וכן משמע בב\"י דהי' גירס' שלו כך בטור מיהו בטו' א\"א לומר כן דהא הרא\"ש ס\"ל אפי' נשתמש שלא כדין פטור ודברי ב\"י תמוהים:","\u0003אסורה לחזור לראשון\u0004. הטעם כל שנשאת לאחר אחר הגט יש לחוש שמא יפייס אותה עד שתאמר אני מתחרט בגירושין והיא אוהבו שהרי על כרחו יצאה ממנו, אבל כל היוצאת במיאון ונשאת לאחר לא חיישינן שהראשון פייס אותה למאן בשני דמסתמא כבר פייסה כשהייתה עמו שלא תמאן ולא איפייס, רש\"י, ולענין איסור כהונה אתי מיאון דידיה ומבטל גיטא דיד' ומותרת לכהן ומיאון דחברי' איכא פלוגתא אם מותרת לכהן כמ\"ש בסימן ו' ע\"ש:","\u0003לאבי הראשון וכו'\u0004. אף על גב בקרובים לא שייך הטעם דאזיל ומשבח לה ומפייס מ\"מ גזרי' קרובים אטו הוא ש\"ס:","\u0003אסור' באביו\u0004. אף על גב דקי\"ל אתי מיאון ועוקר הזיק' מ\"ה א\"צ חליצה מיבם מ\"מ אסורה לאביו מפני מראית עין ולענין קרובים איתא פלוגתא ועיין ס\"ס קע\"ג ועיין ב\"ח לכ\"ע אם לא נשאר שם יבם אחר מיתת הבעל א\"י למאן שאין לה במי למאן לכן הרי היא אסורה לקרובי הבעל לכ\"ע המגיד:","\u0003ומ\"מ אם מיאנה בא' וכו'\u0004. אף על גב דאסורה לשאר קרובי המת מ\"מ לאחי' מותרת משום מצות יבום:","\u0003או עד שתלד\u0004. פ\"ק דיבמות איכא פלוגתא לרב ספרא בנים הרי הן כסימני' ולר' זביד אין בנים בלא סימנים כתבו התו' והרא\"ש ברוב פעמים כשתלד אית לה סימנים ולא בעי למימר אין בנים בלא סימנים אלא אין בנים מצוי בלא סימנים ואפי' אם בדקוה ול\"ל סימני' חיישינן שמא נשרו משמא אפילו ליכא ספק דאורייתא היינו שלא בעל אחר שגדלה מ\"מ בבנים חיישינן שמא נשרו ולהרי\"ף ותוס' והרא\"ש לרב ספרא אפי' כשתלד בעת קטנות' הרי הם כסימנים אחר שגדל' וכן משמע הריון בעת קטנות' ה\"ה כסימנים אחר הזמן ולא ה\"ל להרב רמ\"א לכתוב דין בזה בשם א\"ז כי מבואר כן בתו' וכן לר\"ז אין בנים בלא סי' ומהני אף בקטנות' והרי\"ף והרא\"ש הביאו דברי ר\"ז משמע דס\"ל דהלכתא כוותיה לפ\"ז אפילו אם ילדה אחר יב\"ש ולא הביאה סימנים אינו אלא ספק שמא נשרו כי לר\"ז בנים לאו סימנים אלא דחיישינן שמא נשרו א\"כ לענין חליצה לאו גדולה היא אף על גב מרמב\"ם וסמ\"ג משמע דס\"ל בנים ה\"ה כסימנים מ\"מ מהרי\"ף והרא\"ש לא משמע כן עיין סי' קס\"ט ולשיטת הרמב\"ם אינה גדולה לענין חליצה אלא כשילדה אחר יב\"ש כמ\"ש פ\"ב ה\"א אז הוי בנים כסימנים ולענין מיאון כתב המגיד שם דס\"ל כשילדה אף בעת קטנותה א\"י למאן דאל\"כ תמצא חמות' דממאן אז ודאי בעת קטנותה ג\"כ א\"י למאן אחר שילדה ומיהו בעת הריון יכול' למאן והיינו מ\"ש פי\"ט בת ממאנ' היינו שנתעברה ממנה ולכן צ\"ל מ\"ש ומשעת הריון הוי כגדולה היינו לענין מיאון דוקא ולא לענין חליצה ולענין מיאון יש להחמיר דאין ממאנת משעת הריון אפי' בעת קטנותה מיהו מבואר בתוס' דוקא כשהוא בן קיימא אבל אם הפילה ממאנת ולענין חליצה אם ילדה בעת קטנותה אפילו בעת גדלותה לא הביא' סימנים אין חולצת דאינו אלא ספק שמא נשרו לר\"ז ואין מהני אלא לענין מיאון דחיישינן שמא נשרו אף על גב בעלמא כי ליכא ספק דאוריית' לא חיישינן שמא נשרו משא\"כ בבנים חיישינן שמא נשרו ועיין תשו' מ\"ב:","\u0003למפרע\u0004. לכאורה תמוה א\"כ איך ממאנת ומותרת לאחר ליחוש שמא ימצא בה סימני אילונית והרי היא גדולה למפרע אף על גב דלא חיישינן למיעוטא שמא אילונית היא כמ\"ש בש\"ס בכמה מקומות דקי\"ל כחכמי' ולא כר\"מ מ\"מ הכא דליכא /דאיכא/ ריעות' דלא הביאו ב' שערות ומכ\"ש כשנולדו בה סימני איילונית למה תמאן וראיתי בדרישה שתירץ דמיירי דלא בא עליה הראשון אחר יב\"ש אז לא הוי קידושין דאורייתא מ\"ה לא חיישינן שמא ימצא בה סימני איילונית כמו דלא חיישינן שמא נשרו הסימנים ועיין ס\"ג כ' א\"נ י\"ל למ\"ש בסימן מ\"ד איילונית לכמה פוסקים א\"צ גט אלא מדרבנן ולתוספות ולהרא\"ש ודאי איילונית א\"צ גט כלל אלא ספק איילונית היינו שאין ניכר הסימנים בה היטב אז צריכה גט נמצא להפוסקים הנ\"ל אף בבא עליה אחר יב\"ש אינו אלא ספק דרבנן דהא אם נמצא שהיא איילונית א\"צ גט אלא מדרבנן לכן לא חיישינן שמא ימצא בה סימני איילונית, ולתוס' והרא\"ש אין חשש כלל דאם נמצא בה סימני איילונית אם כן א\"צ גט ואם לא ימצא בה ס\"א א\"כ היא קטנה ולדעת הרמב\"ם שכתב פ\"ד ה\"א איילונית שנתקדשה הרי זו קידושין גמורים משמע קידושין דאוריית' הי' מקום להקשות עליו קושיא הנ\"ל אם היא איילונית למפרע למה לא חיישינן שמא ימצא שהיא איילונית מאחר דהוא ספק דאורייתא, מיהו בסימן הנ\"ל כתבתי ע\"כ לא כתבה רמב\"ם דהוי קידושין אלא בהכיר בה אבל אם לא הכיר בה לא לכן לא חיישינן כאן דהא אם ימצא בה ס\"א אחר כך הוי לא הכיר בה אלא לפי לשון המחבר שם דמשמע אפילו לא הכיר בה איירי קשה כהנ\"ל:","\u0003ביום אחרון\u0004. בתו' מבואר דוקא כשהוא יום אחרון יב\"ש ויום א' אז באותו יום אחר יב\"ש שלימות בתחלת היום חשובה גדולה ומ\"ש בהג\"ה יום אחרון של יב\"ש כ' לא כתוספות אלא כדעת הרא\"ש והטור שכתבו כן וצריך ישוב דהא יב\"ש היא קטנה למה מהני ביום אחרון וכל היכא דתני ויום א' היינו מ\"ע ל\"ע היינו יום אחר השנים כגון הכא יום שאחר יב\"ש, ובאותו יום אין נשים נאמנות לבדוק ולומר שהיא גדולה לענין חליצה, והיינו תוך הפרק שאמר ר' יהודה שאין השנים בודקת /הנשים בודקות/ והלכתא כר\"י בזה לפר\"ת דאיירי ביום אחרון כמ\"ש בתוספות והרא\"ש:","\u0003וי\"א שאם נראו בה וכו'\u0004. עיין שכ\"כ הב\"י וכן בד\"מ בשם רש\"י ותוספות על הסוגי' שם דאי משתכחי לאחר הפרק שומא נינהו ופירש\"י ולא תחלוץ וכתב תוספות הדין עמו דליכ' לפרושי שומא נינהו ותמאן דהא קתני סיפא דאינם נאמנות לומר קטנה היא ותמאן, והבין הב\"י אפילו אם נודע ע\"פ עדים כשרים דהני שערות הם מ\"מ לא תמאן וחיישי' לחומר' ואנ\"ל כיון דקי\"ל שומא נינהו למה לא תמאן כשלא בעיל אחר יב\"ש אלא כוונת תוספות דאם נשים בדקו אותה קודם הפרק ואמרו דיש לה שערות ואחר הפרק נמצא בה שערות לא סמכינן על הנשי' דהני שערות היו בה קודם הפרק ושומא נינהו דא\"כ אתי' קולא מהן ואינם נאמנות לקולא אלא אין ממאנת ואין חולצת מאחר נשים אומרי' דהיו בה שערות קודם הפקר והיינו לחומר' נאמנין ולא לקול' וכן כתב בש\"ג עיין דף תמ\"א עמוד א' אבל בוודאי נבדקת על פי אנשי' וראו בה שערות קודם הפרק ואחר הפרק נמצ' בה הני שערות יכולה למאן דאינו אלא שומא כמ\"ש ברמב\"ם וטור וליכ' פלוגת' בזה:","\u0003אזלינן לחומר'\u0004. משמע אפילו לא בעיל השת' אזלינן לחומר' אף על גב בספק אם נשרו ולא בעיל אחר יב\"ש אזלינן לקול' הטעם בשלמ' בספק הנ\"ל אם נשרו מאחר דליכ' שערות יותר מסתב' דלא היו כלל שערות מדהשת' ליכ' שערות אף על גב בבעיל מחמירינן מחמת שהוא ספק א\"ד מ\"מ בספק דרבנן הסבר' מסייע לקולא משא\"כ בספק אם הוא יב\"ש ליכ' סברא לסייע ומה שמציין על דין זה תשו' רשב\"א טעות הוא אלא המגיד כ\"כ ובתשובת רשב\"א סימן אלף רי\"ו כתב אפילו אם יש ס\"ס שמא לא הגיע ליב\"ש ושמא לא נשרו יש להחמיר וי\"ל המגיד לא פליג ארשב\"א אלא המגיד איירי אפילו שלא בעיל השת' כמ\"ש והרשב\"א איירי כשבעיל והא דמחמיר הרשב\"א אף על גב בס\"ס מקילין אפילו באיסור דאוריי' צ\"ל משום דהוי הכל ספק א' אם היא גדולה או קטנה וכן ראיתי בתשו' הרב ר' בצלאל סי' כ' בתשו' רש\"ך ס\"א סי' כ\"ג פסק בזה להקל ועיין תשו' מהרי\"ט ועיין תשו' שער אפרים סי' קי\"ב:","\u0003אם הביאה ואם לא הביאה\u0004. המחבר סתם ופסק כלשון הרמב\"ם פ\"ב ה\"א ומשמ' דרמב\"ם פוסק כת\"ק דנשים נאמנות אפילו להקל וכ\"כ המגיד ומ\"ש בתשו' מהר\"מ מלובלין דרמב\"ם איירי דוקא לחומר' נאמנות אנ\"ל כי אין דרכן לסתום דבריו כ\"כ אלא ודאי פוסק כת\"ק וס\"ל מ\"ש הת\"ק נבדקת ע\"פ הנשים היינו אפילו לקולא מיהו מ\"ש המגיד גם הרי\"ף פוסק כן לכאורה אנ\"ל ויותר מסתבר דפוסק דוק' לחומר' נאמנין לא לקול' דהא כתב שם הסתם מדת\"ק ור\"א ור' ישמעאל כולהו בחדא שיטת' קיימ' לאחר הפרק נשים בודקת דאיכ' חזקה דרבא ש\"מ היכ' דליכ' חזקה דרבא ס\"ל אין הנשים נאמנות לא כב\"י שכתב הרא\"ש פוסק דנאמני' אפילו להקל אלא אף להרא\"ש דוק' לחומר' נאמנים וכן משמע מסמ\"ג שהבי' דברי התוספו' לאחר הפרק נשים בודקות וכ\"כ הטור וכללא הוא לפי דעת הפוסקי' דנשים אינן נאמנות אלא לחומר' ולא לקול' היינו אם בדקו לפני הפרק או בתוך הפרק נאמנות לומר שיש לה שערות לענין אם נמצא בה אחר הפרק אותם שערות אין חולצת עד שיביאו שערו' אחרות אבל לענין מיאון אינן נאמנות לתלות לקולא שהן אותם שערות שתמאן ובתוס' איתא טוב לבדוק קודם הפרק לידע אם אותם שערות הם ואם בדקו אחר יב\"ש ויום א' ואמרו שיש לה שערות סומכין עליה' ותחלוץ כיון חזקה דרב' מסייע דחזקה היא אחר יב\"ש שיש לה שערות, ואם אמרו דאין לה שערות מ\"מ אסורה למאן דחיישינן שמא נשרו ועיין לקמן עוד מזה ס\"ק כ\"ט ואם אמרו שיש לה שערות ואח\"כ בדקו אנשים ואמרו דאין לה או אפילו לא בעיל אחר יב\"ש חוששין שמא נשרו כיון דנשים אמרו דיש לה כן נשמע מתוספות, מיהו נראה דוק' לענין מיאון חיישינן שמא נשרו אפילו לא בעיל דלא חיישינן בעלמ' וכאן חיישינן אבל לחלוץ אין חולצין ולא אמרו הואיל חזקה דרבא מסייע לה אמרינן בודאי נשרו כנ\"ל, וביום אחרון של יב\"ש אין נאמנות לומר דיש לה שערות כדי לחלוץ דאז ליכ' חזקה דרבא:","\u0003במקום הערוה וכו'\u0004. ברמב\"ם אית' במקום ערוה ובמקום אחד משמע במקום ערוה עצמו צריכים להיות במקום א' וכ\"כ הטור בשם הרמב\"ם וכ\"כ בסמ\"ג כאן שהשמיט בש\"ע שיהא במקום א' כי בכ\"מ תמה עליו מנ\"ל שצריך להיות במקום א', ויש ליישב דלמד מסוגי' מר\"א ושמואל וס\"ל דל\"פ ע\"ש:","\u0003א' בגבה וכו'\u0004. המגיד כתב בשם הרמב\"ן ורשב\"א גבה וכריסה ממש לא מהני ומשמע אפילו למ\"ד דלא בעינן ב' שערו' במקום א' מ\"מ גבה וכריסה ממש לא מהני אלא גבה היא במקום תפוח שעל ערוה וכריסה שפת ערוה, ועיין בד\"מ שכתב מדברי הב\"ח שהבי' הטור ותוספות וסמ\"ג כמ\"ש בס\"ס ק\"נ לא משמע כן דהא כתבו על זה דאין אנו בקיאין לבדוק כל הגוף ש\"מ גבה וכריסה ממש הוא:","\u0003שיעור אורך\u0004. עיין בדרישה מ\"ש בשם מהרש\"ל וב\"ח מאריכו בענין השערות לענין חליצה:","\u0003בפי הזוג\u0004. לרמב\"ם להינטל בפי הזוג היא שיעור המיעוט ולהטור כדי לקרוץ בציפורן ונ\"מ אם בדק בזוג ואינו כדי להנטל בו אז לרמב\"ם יכולה למאן וא\"צ תו בדיקה אם לקרוץ בציפורן ולהטור הוא ליהפך ט\"ז:","\u0003סדר החליצה סימן כ\"ז\u0004. שם פסק כרוחב אצבע וכתב בט\"ז דאין סותר למ\"ש כאן כדי לכוף דשם איירי שהוא כרוחב אצבע אז א\"צ ידיעה כמה שנים הם וא\"צ בדיקת גומות:","\u0003שלא בעיל אחר היות לה י\"ב שנה ויום אחד\u0004. ואז אף אם היא גדולה ליכ' קידושין דאוריית' משום הכי לא חיישינן שמא נשרו וכתבו במ' ובהגמיי' דאז נשים נאמנות דאין לה שערו' ותמאן כיון דאיכ' /דליכא/ חשש דאוריית' כמ\"ש לעיל וכן כשלא בעיל ונשים מעידות על שנים שהיא עדיין אינה בת יב\"ש ויום א' נאמנות, וכן יש לדייק מרש\"י פ' בא סימן (נדה ד' מ\"ח ע\"ב) שכתב אי אמרו ליתנהו לא ממאנת דחיישינן שמא נשרו, ש\"מ דוק' היכ' דאמרינן שמא נשרו אז לא ממאנת משא\"כ כשלא בעיל ממאנת ומתוספות אין ראיה דפליגי ע\"ז ממ\"ש שם ד\"ה בשלמ' וכו' דליכ' לפרש שומא נינהו ותמאן דהא קתני סיפ' דאינה נאמנת למאן וע\"כ צ\"ל דאיירי בלא בעיל דאל\"כ איך ס\"ד שתמאן דהא אף על גב שנאמנת דהני שערות נינהו מ\"מ חיישינן שמא נשרו השערות לא יהא שלא היו שערות כלל א\"י למאן אלא ודאי איירי שלא בעיל ומ\"מ כתבו שהיא אינה נאמנ' שתמאן וי\"ל באמת ה\"פ דהא קתני בסיפ' דאינה נאמנת שתמאן אם כן סותר לריש' הן אם איירי כל הבריי' בבעיל הן אם איירי דלא בעיל אלא איירי הריש' לענין חליצה ובאמת איירי בבעיל, גם י\"ל אם נשארו הני שערות ולא נשרו תו לא חיישינן שמא הביאה שאר שערות ונשרו מאחר ראינו הני שערות שהיה בה ולא נשרו מהיכי תיתי לומר שהביאה אחרות והם נשרו, לפי זה איירי תוספות בבעיל ומ\"מ י\"ל דנאמנת לומר שלא הביאה ותמאן ולא חיישינן שמא נשרו שערות החדשות מ\"ה צריכי' להבי' ראיי' מסיפ', ונ\"מ מזה אם נבדקת ע\"י אנשים קודם הפרק וראו שערות ואלו שערות נשארו בה אחר יב\"ש תו לא חיישינן שמא הביאה שערות אחרות חדשו' ונשרו מאחר דהישנו' לא נשרו ואז אפילו בבעיל אחר יב\"ש ממאנת ולכאורה נ\"ל כל ספיקו' כאן יש תקנה בקטנה שהשיאוה אמה ואחי' ונפלה לפני יבם שתמאן בפני ב' ותחלוץ אח\"כ אז מותרת לאחר ממ\"נ אי גדולה היא נפק' בחליצה ואי קטנה היא נפק' במיאון כאשר מצינו בכמה דינים שצריכה מיאון וחליצה כן ה\"נ במיאון וחליצה א\"צ בדיקה ואין ספק כלל:","\u0003צריכה ממנו גט\u0004. עיין פרישה שפי' דקאי על השני דצריכה משני גט ואסורה לחזור לו היינו לראשון ולכאורה תמוה ל\"ל גט משני ממ\"נ אי גדולה היא אין קדושי שני כלום ואם קטנה הוא תצא במיאון משני ומותרת לראשון ממ\"נ וי\"ל הספק הוא שמא תחת הראשון לא היה לה סימנים ותחת השני היה לה ונשרו אבל אם מעת שמיאנה עד הקידושין של השני לא היה סימני' באמת מותרת לראשון ממ\"נ הנ\"ל והא דחיישינן כאן שמא קדשה בביאה נראה מדויק לשון הרמב\"ם והמחבר דוק' אם בעיל ואח\"כ נבדקה אבל אחר בדיקה אין חשש שמקדש אותה פן נשרו הסימנים:","\u0003והולד ספק ממזר משניה'\u0004. היינו השני ספק ממזר מדאוריית' שמא גדולה היא מאז ומקדם וכן מראשון ספק ממזר דאוריי' למ\"ש שמא תחת השני נעשה גדולה ועיין פ\"ד מהל' אישות במגיד וכ\"מ שהבי' פלוגת' בזה הא דקי\"ל בבעיל אחר שנתגדלה הוי קידושין דאוריית' וא\"צ גט משני אם הטעם הוה מסתמ' בעיל לשם קידושין לפ\"ז אם אמר בפירוש דאין בעיל לשם קידושין לא הוי קידושין דאוריית', או הטעם בעת הביאה נגמרין קדושין הראשוני', והסכימו דעיקר הוא דבועל לשם קידושין וכן הוא לשון המחבר ובכל אלו דהיא מקודשת לראשון מספק אז אם נתקדשה לשני אפילו בפניו לא הוי כאלו אמר גרשתני לכ\"ע משום דהיא סבר' דלאו קידושין הם עיין בנ\"י פ' ב\"ש:","\u0003צריכה גט מדרבנן\u0004. הנה מקור דין זה נובע מדלא אפשט' הבעי' פ' ב\"ש אם הקידושין גדלו בהדה אף שלא בעיל נגמרו הקידושין אחר שגדלה ומוכח שם אי נגמרו הקידושין משגדלה הם הקידושין דאוריית' דהא אר\"ג אחותה שנפלה ליבם תצא בלא חליצה ויבום א\"כ ע\"כ מדאוריית' הוא וכ\"כ הנ\"י ולא כב\"ח שכתב הבעי' בש\"ס אם הקידושין נגמרין מדרבנן וא\"א לומר כן כנ\"ל, לפ\"ז לכאורה תימה על הפוסקים שכתבו דאינו אלא קידושין מדרבנן אלא נ\"ל אף דבעי' זו מדאוריית' הוא מ\"מ מוכח מדאמר רב זביד בלא בעיל אחר שגדלה לא חיישינן שמא נשרו ע\"כ לאו דאוריית' הוא דאל\"כ למה לא חיישינן שמא נשרו וגדלו קידושין בהדה וא\"ל שם הטעם משום דהוי ס\"ס שמא גדלו הקידושין עמה ושמא נשרו דהא בכה\"ג לאו ס\"ס הוא כיון דספק א' מחמת הבעי' דלא אפשט' ועיין בי\"ד סי' ק\"י אלא ע\"כ לר\"ז אינו אלא קידושי דרבנן ובכל זה איירי בידוע בודאי דלא בעיל אבל מסתמ' כל שדר עמה כדרך איש עם אשתו אמרינן שבעיל אף על גב דליכ' עידי יחוד כמ\"ש ר\"ס קמ\"ט:","\u0003לא יקיים ראשון שמא יאמרו וכו'\u0004. ול\"ד למ\"ש ס\"ס קמ\"ו דכאן אם לא גירש הראשון עשה השני איסור שקידש אותה דהא ספק הוא שמא גדלו הקידושין בהדה וכן בדין ראשון ספק שמא נשרו הסימנים וכל היכ' דלא עשה א' הקידושין של היתר חיישינן שמא יאמרו משא\"כ שם מאחר דגירש זה ע\"ת ותנאי בידה אין איסור לקדשה ועיין בש\"ג דף תמ\"ד דפוסק לא כפוסקי' הללו אלא כופין השני לגרשה כדי שלא יהא חוטא נשכר ומותר' לראשון ולהפוסקי' דס\"ל כמ\"ש המחבר דמותרת לשני א\"ל מ\"ש ממקדש ליבמה דאסורה למקדש כמ\"ש בסימן קנ\"ט דשם עבר אדאוריית' דהיא חייבי לאוין לאחר:","\u0003אחר יב\"ש\u0004. משום דקי\"ל גומות אף על פי שאין שערו' ואין אנו בקיאין בזה, גם ס\"ל א' בגבה וא' בכריסה היינו גבה וכריסה ממש ואין אנו בקיאין לבדוק כל הגוף אף על גב אם לא בעיל אינו אלא מדרבנן מ\"מ לא הוי כספק דרבנן כיון שהוא חסרון ידיעה דאין אנו בקיאין ועיין בג\"ר סי' צ\"ח ומכאן מבואר אפי' חסרון ידיעה לכל העולם לא הוי כספק דרבנן גם מוכח מכאן אפי' ספק שאין תקנה לדבר כי הכא אם היתה ממאנת היתה מותרת לקרוביו והשתא אין היתר לקרוביו מ\"מ אין מקילין ועיין בט\"ז שם מיהו יש לחלק:"]],["\u0003הלכות יבום\u0004\nמִי שֶׁמֵּת אָחִיו מֵאָבִיו וְלֹא הִנִּיחַ זֶרַע, מִצְוָה לְיַבֵּם אֶת אִשְׁתּוֹ, בֵּין שֶׁהִיא אִשְׁתּוֹ מִן הַנִּשּׂוּאִין בֵּין שֶׁהִיא אִשְׁתּוֹ מֵהָאֵרוּסִין, דִּכְתִיב: \"כִּי יֵשְׁבוּ אַחִים יַחְדָּו וּמֵת אֶחָד מֵהֶם וּבֵן אֵין לוֹ יְבָמָהּ יָבֹא עָלֶיהָ\" \u0005(דְּבָרִים כה, ה)\u0006:\nזֶה שֶׁנֶּאֱמַר בַּתּוֹרָה: \"וּבֵן אֵין לוֹ\" \u0005(דְּבָרִים כה, ה)\u0006, אֶחָד הַבֵּן וְאֶחָד הַבַּת, אוֹ זֶרַע הַבֵּן אוֹ זֶרַע הַבַּת, עַד סוֹף כָּל הַדּוֹרוֹת, בֵּין מֵאִשָּׁה זוֹ בֵּין מֵאִשָּׁה אַחֶרֶת, אֲפִלּוּ הָיָה לוֹ \u0010c0\u0011 זֶרַע מַמְזֵר אוֹ ע\" א, הֲרֵי זֶה פּוֹטֵר אֶת נָשָׁיו מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. אֲבָל \u0010c1\u0011 בְּנוֹ מֵהַשִּׁפְחָה אוֹ מֵהַנָכְרִית, אֵינוֹ פּוֹטֵר \u0005 אֲפִלּוּ נִתְגַּיֵּר אוֹ נִשְׁתַּחְרֵר הַבֵּן \u0006 \u0005(הָרַמְבַּ\"ם פ\"א מֵהִלְכוֹת יִבּוּם וַחֲלִיצָה)\u0006. וְיֵשׁ אוֹמְרִים דְּהָנֵי מִלֵּי בְּנוֹ מִשִּׁפְחָה אַחֶרֶת, אֲבָל בְּנוֹ מִשִּׁפְחָתוֹ, פּוֹטֵר:\nאֲפִלּוּ הָיָה הַזֶּרַע גּוֹסֵס אוֹ פָּצוּעַ מִמַּכּוֹת שֶׁאִי אֶפְשָׁר לוֹ לִחְיוֹת, פּוֹטֵר:\nמִי שֶׁמֵּת וְהִנִּיחַ אִשְׁתּוֹ מְעֻבֶּרֶת, אִם הִפִּילָה, הֲרֵי זוֹ תִּתְיַבֵּם. וְאִם יָלְדָה וְיָצָא הַוָּלָד חַי לַאֲוִיר הָעוֹלָם, אֲפִלּוּ מֵת בְּשָׁעָה שֶׁנּוֹלַד, הֲרֵי אִמּוֹ פְּטוּרָה מֵהַחֲלִיצָה וּמִן \u0010c2\u0011 הַיִּבּוּם. אֲבָל מִדִּבְרֵי סוֹפְרִים, \u0010c3\u0011 עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁכָּלוּ לוֹ חֳדָשָׁיו וְנוֹלַד לְתִשְׁעָה חֳדָשִׁים \u0010c4\u0011 גְּמוּרִים. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה אֲפִלּוּ לֹא נִכְנְסָה בַּחֹדֶשׁ הַתְּשִׁיעִי רַק \u0006 \u0005 יוֹם אֶחָד מִלְּבַד יוֹם שֶׁנִּתְעַבְּרָה בּוֹ, הָוֵי וְלַד קְיָמָא. וְאַף עַל גַּב דְּאָמְרִינָן בַּגְמָרָא יוֹלֶדֶת לְתִשְׁעָה אֵינָהּ יוֹלֶדֶת לִמְקֻטָּעִין, כְּבָר תָּמְהוּ עַל זֶה רַבִּים שֶׁהַחוּשׁ מַכְחִישׁ זֶה, אֶלָּא שֶׁאָנוּ צְרִיכִין לוֹמַר שֶׁעַכְשָׁיו נִשְׁתַּנָּה הָעִנְיָן, וְכֵן הוּא בְּכַמָּה דְּבָרִים \u0006 \u0005(ב\"י בְּשֵׁם הַרשב\"ץ)\u0006. \u0005 מִיהוּ, חָדְשֵׁי הָעִבּוּר כָּל אֶחָד שְׁלשִׁים יוֹם, וְלֹא חַשְׁבִינָן לְהוּ כְּסֵדֶר הַשָּׁנִים \u0006 \u0005(כֵּן מַשְׁמָע שָׁם)\u0006. אֲבָל אִם לֹא נוֹדַע לְכַמָּה נוֹלַד, אִם חָיָה ל' יוֹם, הֲרֵי זֶה וְלַד קְיָמָא וּפוֹטֵר נְשֵׁי אָבִיו מֵהַחֲלִיצָה \u0010c5\u0011 וּמֵהַיִּבּוּם. \u0005 וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁגָּמְרוּ שְׂעָרָיו \u0006 \u0005 וְצִפָּרְנָיו \u0006 \u0005(טוּר)\u0006, \u0005 וְכֵן נִרְאֶה לִי. \u0006 וְאִם מֵת בְּתוֹךְ שְׁלשִׁים, אֲפִלּוּ בַּיּוֹם הַשְּׁלשִׁים, בֵּין שֶׁמֵּת מֵחֹלִי בֵּין שֶׁנָּפַל מֵהַגַּג אוֹ אֲכָלוֹ אֲרִי, הֲרֵי זוֹ סְפֵק נֵפֶל סָפֵק בֶּן קְיָמָא, וּצְרִיכָה חֲלִיצָה מִדִּבְרֵי סוֹפְרִים, אֲבָל לֹא \u0010c6\u0011 תִּתְיַבֵּם. \u0005 וְיֵשׁ אוֹמְרִים \u0006 \u0005 דַּאֲפִלּוּ אִם נוֹלַד מֵת, וַאֲפִלּוּ אִם יֵשׁ לְהִסְתַּפֵּק שֶׁכָּלוּ חֳדָשָׁיו, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת \u0006 \u0005(טוּר בְּשֵׁם הָר\"פ)\u0006:\nאִם אֵין יָדוּעַ שֶׁכָּלוּ לוֹ חֳדָשָׁיו אֶלָּא עַל פִּיהָ, \u0010c7\u0011 אֵינָהּ נֶאֱמֶנֶת. יְבָמָה שֶׁנִּשֵּׂאת לַשּׁוּק, וְעֵדִים מְעִידִים שֶׁהַוָּלָד שֶׁיָּלְדָה אַחַר מוֹת בַּעְלָהּ חָיָה שְׁלשִׁים יוֹם, וְעֵדִים אֲחֵרִים מַכְחִישִׁין וְאוֹמְרִים שֶׁלֹּא חָיָה שְׁלשִׁים יוֹם, \u0010c8\u0011 מֻתֶּרֶת לְבַעְלָהּ וְאֵינָה צְרִיכָה חֲלִיצָה. וְאִם אֵין עֵדִים מְעִידִים שֶׁחָיָה ל' יוֹם, וְגַם אֵין עֵדוּת בְּרוּרָה שֶׁלֹּא חָיָה ל' יוֹם, אֶלָּא קוֹל לַעַז, לֹא אָסְרִינָן לַהּ בְּקָלָא דְּבָתַר נִשּׂוּאִין:\nהָאוֹמֵר: זֶה בְּנִי אוֹ יֵשׁ לִי בָּנִים, \u0010c9\u0011 נֶאֱמָן לִפְטֹר אֶת אִשְׁתּוֹ, אֲפִלּוּ הֻחְזַק בְּאַחִים. \u0010c10\u0011 וְיֵשׁ אוֹמְרִים שֶׁאִם יֵשׁ עֵדִים שֶׁיֵּשׁ לוֹ אַחִים, \u0010c11\u0011 אֵינוֹ נֶאֱמָן אַחַר כָּךְ לוֹמַר שֶׁיֵּשׁ לוֹ בָּנִים: \u0010c12\u0011\nאָמַר בִּשְׁעַת קִדּוּשִׁין \u0005 אוֹ אַחַר כָּךְ, \u0006 \u0005(כֵּן מַשְׁמַע מֵהָרַ\"ן)\u0006, יֵשׁ לִי בָּנִים וּבִשְׁעַת מִיתָה אָמַר: אֵין לִי בָּנִים, אֵינוֹ נֶאֱמָן לְאָסְרָהּ. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nנֶאֱמָן עֵד אֶחָד לְהָעִיד שֶׁנִּתַּן לְבַעְלָהּ בֵּן, לְהַתִּירָהּ לְזָר. \u0010c13\u0011 \u0005 וְיֵשׁ חוֹלְקִין \u0006 \u0005(בַּב\"י מִשֵּׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006:\nמִי שֶׁזִּנָּה עִם אִשָּׁה, בֵּין פְּנוּיָה בֵּין אֵשֶׁת אִישׁ, וְנִתְעַבְּרָה, וְאָמַר: \u0010c14\u0011 זֶה הָעֻבָּר מִמֶּנִּי הוּא, וַאֲפִלּוּ הִיא מוֹדָה לוֹ, הֲרֵי זֶה סָפֵק, וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. \u0005 וְאִם הָיוּ חֲבוּשִׁין בְּבֵית הָאֲסוּרִים, שֶׁוַּדַּאי הוּא מִמֶּנּוּ, פּוֹטֵר \u0006 \u0005(מָרְדְּכַי פֶּרֶק כֵּיצַד)\u0006. \u0005 וְיֵשׁ אוֹמְרִים אֲפִלּוּ בְּזוֹנָה אַחֶרֶת הַמְיֻחֶדֶת לוֹ \u0006 \u0005(הַמ\"מ פ\"ג)\u0006:\nהָאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ וּבְנָהּ לִמְדִינַת הַיָּם, וּבָאוּ וְאָמְרוּ לָהּ: מֵת בַּעְלֵךְ, מֻתֶּרֶת לִנָּשֵׂא לַשּׁוּק:\nהָלְכָה הִיא וּבַעְלָהּ וּבְנָהּ לִמְדִינַת הַיָּם, וּבָאָה וְאָמְרָה: מֵת בַּעְלִי וְאַחַר כָּךְ מֵת בְּנִי, נֶאֱמֶנֶת. אֲבָל אִם אָמְרָה: מֵת בְּנִי וְאַחַר כָּךְ מֵת בַּעְלִי, אֵינָהּ נֶאֱמֶנֶת \u0010c15\u0011 לְהִתְיַבֵּם, אֶלָּא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nהָלְכָה הִיא וּבַעְלָהּ בִּלְבַד, וּבָאָה וְאָמְרָה: נִתַּן לִי בֵּן בִּמְדִינַת הַיָּם, וּמֵת, וְאַחַר כָּךְ מֵת בַּעְלִי, נֶאֱמֶנֶת. אֲבָל אִם אָמְרָה: מֵת בַּעְלִי וְאַחַר כָּךְ מֵת אוֹתוֹ הַבֵּן, אֵינָהּ נֶאֱמֶנֶת, וְחוֹלֶצֶת וְלֹא \u0010c16\u0011 מִתְיַבֶּמֶת. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיְתָה פְּסוּלָה לִכְהֻנָּה, אוֹ שֶׁאָמְרָה: בַּמְּעָרָה הָיִינוּ כְּשֶׁמֵת וְלֹא הָיָה שָׁם אָדָם שֶׁיָּעִיד. אֲבָל אִם אֵין הַדָּבָר כֵּן, לֹא תַּחֲלֹץ וְלֹא תִּתְיַבֵּם עַד שֶׁיָּבֹאוּ עֵדִים:\nהָלַךְ בַּעְלָהּ וְצָרָתָהּ לִמְדִינַת הַיָּם, וּבָאוּ שְׁנַיִם וְאָמְרוּ לָהּ: מֵת \u0010c17\u0011 בַּעְלֵךְ, הֲרֵי זוֹ לֹא תַּחֲלֹץ וְלֹא תִּתְיַבֵּם עַד שֶׁתֵּדַע אִם יָלְדָה צָרָתָהּ אוֹ לֹא יָלְדָה. וְאִם הָיְתָה אֲסוּרָה לִכְהֻנָּה מִתְּחִלָּה, הֲרֵי זוֹ חוֹלֶצֶת לְאַחַר ט' חֳדָשִׁים:",[],["\u0003זרע ממזר\u0004. היינו בחבושי' בבית אסורים יחדיו דאל\"כ יש לחוש שמא זנתה עם אחר כמ\"ש בסעיף ט' וכ\"כ המ' ואגודה:","\u0003בנו מהשפחה\u0004. דקי\"ל הולד כמותה ולא נקרא זרעו ודעת י\"א משפחתו פוטר עיין דין זה ברמב\"ם פ\"ד ה' נחלות ובפ\"י ה\"ג ופ\"א ה' יבום ובטח\"ה סי' רע\"ט ובטור זה סימן ט\"ו וקמ\"ט ולדעת המחבר עיקר כרמב\"ם דס\"ל אפילו משפחתו מסתמא בועל לשם זנות לכן כאן ובסימן ט\"ו הביא דעת החולקים בלשון וי\"א ובח\"ה שם פסק נמי כרמב\"ם דס\"ל לענין ממון ירושה יש לחלק אם הוא בחזקת כשרות אז מוקמין חזקה שלו נגד חזקה שלה שהיא שפחה ונשאר מיגו דיכול ליתן הירושה למי שירצ' כמ\"ש רפ\"ד ה' נחלו' במגיד באריכות לכן פסק נמי בסימן קמ\"ט הבא על אשה דעלמא לא אמרי' דבעיל לשם קידושין, מיהו י\"ל דשם בסימן קמ\"ט כ\"ע מודי' דשם האיסור קל חיישינן שבעיל לשם זנות ועיין ב\"ח ודרישה:","\u0003אבל מד\"ס וכו'\u0004. עיין דינים הללו ברמב\"ם פי\"א ה' מילה ופ\"א ה' יבום ופב' ב' ה' רוצח ופ\"א ה' נחלו' ובפ\"א ה' אבל, ועיין במגיד פ\"א ה\"י לרמב\"ם דינים הללו חלוקים הם לפעמים סמכי' על גמרו שערות וצפרנים לבד אפילו הוא בן ח' בוודאי כגון לענין טלטול שבת אבל בשאר מקומות לא סמכינן על השערות אבל כלו חדשיו הוי ולד מעלי' מדאורייתא ומדרבנן אפילו לא שהה ל' יום ולא נגמרו השערו' ואם שהה ל' יום אפי' לא נגמרו שערות והוא בן ח' הוי נמי ולד מעלי' אף מדרבנן אלא באבל מקילין בשהה אף על גב דהרמב\"ם איירי כאן בספק אם הוא בן ח' או בן ט' לאו דווקא ה\"ה בוודאי בן ח' נמי סמכינן אם שהה שלשים יום אפי' לא גמרו שערות ואם גמרו שערות וציפורן לא סמכינן היינו מדרבנן אבל מדאורייתא אפי' הוא בן ח' ולא שהה אלא גמרו השערות וציפורן פוטר מחליצה ויבום ומה שפוטר מדאורייתא אם מת מיד כתב המגיד היינו בגמרו שערות וצפורן דאל\"כ הוי כנפל אפילו בספק אם כלו חדשיו וטור בסימן זה לא כתב כלום כשהו' בוודאי בן ח' אלא בספק כתב אם גמרו שערות וצפורן ושהה שלשים יום פוטר מיהו מדכתב בטי\"ד סימן שע\"ד לענין אבלות דמתאבלים אם שהה אפילו הוא בן ח' נשמע מזה דה\"ה דפוטר דהא הלכ' כמקיל באבל וראיי' לדבר דהרמב\"ם פוסק לענין רציחה בן ח' ושהה ל' יום נהרג עליו ובאבל פוסק דאין מתאבלין עליו א\"כ להטור באבל דמתאבלי' עליו מכ\"ש דפוטר מיהו לשיטת התוספות דהלכה כר' אבוהו בן ח' אינו פוטר אפילו שערות וציפורן ושהה ל' יום עד שהוא כ' שנים כי לפירוש התוס' איירי ר' אבהו לענין אם הוא בן קיימ' ולא כנ\"י שפי' דר\"א איירי לענין אם הוא גדול וכן בתשו' ריב\"ש סי' תמ\"ו כתב לרבנן בן ח' בודאי מהני גמרו השערו' וציפורן ושהה ל' יום ובספקו' אלו דצריכ' חלוצה הוי ח\"פ וצריכ' לחזו' ע\"כ האחי' עיין תשו' מהרשד\"ם ובתשו' בן ששון סימן כ\"ט וסוף דבריו שם קאי על תחלת דבריו ולא על מי שנשב' ובנ\"ש דף ע\"ח לא הבין יפה ולכאורה תמוה למה הוי חליצה פסול' ממ\"נ אי ולד מעלי' הוא א\"צ חליצה כלל ואי לאו ולד מעליא הוי אז הוא חליצה כשירה:","\u0003עד שיודע בוודאי שכלו לו חדשיו\u0004. ואם בעלה כאן א\"א לידע שכלו חדשיו כי שמא נתעברה אח\"כ ואם אינו בכאן י\"ל דחיישינן שמא בא אצלה ואפשר דחיישי' שמא בא ע\"י שם כמ\"ש בסי' ד':","\u0003גמורים\u0004. היינו לשיטת הרמב\"ם בענין ט' חדשי' כל חדש ל' יום ולא אמרי' שיפור' גרם ולרמב\"ן אמרי' שיפורא גרם אם נתעברה סוף חדש וילדה בתחל' חדש ט' הוי ולד קיימ' אף על גב דאינו אלא ז' חדשי' ושני ימים ורשב\"ץ שהבי' בהג\"ה ס\"ל נמי דבעינן חדשי' שלמים של ל' יום ולא אמרינן שיפורא גרם אלא ס\"ל יולדת לתשע' יולדת למקוטעין ולא בעינן החדש ט' במלואה:","\u0003וי\"א דווקא שגמרו וכו'\u0004. היינו בשהה ל' יום וגמרו והב\"י תמה על הטור מנ\"ל דין זה ובאמת לק\"מ כי כ\"כ כמה פוסקי' ועיין בנ\"י דרשב\"ג קאי על דברי רבי וצריך לגמרו ושהה, ולשיטת התו' והרא\"ש איירי רשב\"ג בין שהוא בודאי בן ח' ובין שהוא ספק בן ח' ש\"מ אפי' בספק צריך שהה ל' יום וגמרו, פסק בט\"ז אם הוא חי ל' יום ומת ולא בדקו אם גמרו שעריו וצפרניו סומכי' על דעה קמייתא שהוא בן קיימא דהא מדאורייתא פוטר משיצא חי לאויר העולם:","\u0003דאפי' אם נולד מת\u0004. דין זה צ\"ע ועיין תשובות בן לב ח\"ג דף מ\"א:","\u0003אינה נאמנת\u0004. ואם הוא אומר שכלו חדשיו נאמן תשובת רשב\"ץ והיא אינה נאמנת להקל אבל להחמיר שלא תתיבם נאמנת:","\u0003מותרת לבעלה\u0004. אף על גב תרי ותרי ונשאת לאחר קי\"ל תצא כמ\"ש בסי' מ\"ז משום דאיירי כאן בנגמר שערות דהא דין זה הוא תשו' הרא\"ש ולשיטתו בעינן ל' יום וגמרו שערות וכ\"כ ב\"ח מ\"ה אף לכת שני האומרים שלא חי ל' יום מ\"מ מדאוריית' ולד מעליא הוא כמ\"ש לעיל ואם לא גמרו אז לכת א' האומר שחי ל' יום מותרת לשיטת הרמב\"ם ולכת שני הוא ספק אף על פי שלא חי ולא גמרו שערות מ\"מ ספק הוא שמא כלו חדשיו יש לומר בכה\"ג לא תצא גם הרוב מסייע דרוב הנולדין של קיימא הם מיהו לדינ' בכה\"ג תצא דהא להרא\"ש לכל כת הוא ספק ולרמב\"ם איכא לספוקי לכת האומרים דלא היה חי ל' יום, ואם ע\"א מעיד או אשה לחברתה שכלו חדשיו עיין ס\"ק י\"א:","\u0003נאמן לפטור\u0004. הטעם הוא דנאמן במיגו דיכול ליתן לה גט אף על גב בעלמא קי\"ל דלא אמרינן מיגו נגד החזקה כאן לא הוי נגד חזקה דהא לענין בנים אין לו חזק' דיכול להיות דיש לו אחין ויש לו בנים ואיירי כאן דלא היה חזקה דאין לו בנים אלא לא היה מוחזק דיש לו בנים וכשאינו מוחזק בבנים לא דמי לחזקה דאין לו בנים כ\"כ הנ\"י, א\"כ במוחזק דאין לו בנים אין נאמן במיגו דהוי מיגו נגד חזק' אבל המגיד כתב בשם הרשב\"א אף במוחזק דאין לו בנים נאמן כי בנים בדידי' תליא והוא אמר יש לי בנים ועיין סימן שאח\"ז ותוס' כתבו פ' האומר לתירוץ אחרון בעת מיתתו אינו נאמן לומר יש לי בנים דאז לא שייך מיגו הנ\"ל די\"ל דאין לו כח ליתן גט, והרמב\"ם רפ\"ג ה\"ג משמע אפי' בעת מיתתו נאמן וכן הוא לדעת הר\"ן שלא כ' אלא תירוץ ראשון של תוס', ואם בתחלה אמר יש לי בנים לא היה כאן עדים אלא חזקה ואח\"כ באו עדים דיש לו אחי' לפי גיר' הב\"י מותרת והרא\"ש כ' נמי כן להדיא אלא שם איירי כשהיא בחזקת היתר משא\"כ כאן דמוחזק דיש לו אחים ואין מוחזק בבני' י\"ל אם באו עדים אח\"כ לא מהני מה שאמר כבר יש לי בנים מיהו לדעת הב\"י וב\"ח אף בכה\"ג היא פטורה מיבום ומחליצה:","\u0003וי\"א שאם יש עדים\u0004. כן כתב הטור בסי' זה ורי\"ו ולא מצינו מי חולק ע\"ז ומ\"ש הב\"י הרמב\"ם חולק ע\"ז ליתא כי הרמב\"ם לא איירי כשיש עדים וכן כתב בתשוב' רש\"ך ס\"ב ס\"ל ומ\"ש הב\"ח הפוסקים דס\"ל במוחזק דיש לו אחים ואמר אין לו אחים נאמן כמ\"ש בסימן של אח\"ז ס\"ל אף כשיש עדים דיש לו אחים נאמן לומר דיש לו בנים ליתא דהא הטור פסק בסימן זה בדין זה דאינו נאמן ובסי' שאח\"ז הביא פלוגת' במוחזקת דיש לו אחים ואמר דאין לו אחים וכן רי\"ו כתב אף לרבי דס\"ל נגד חזקה יש לו אחים נאמן לומר דאין לו אחים מכל מקום נגד עדים דיש לו אחים אינו נאמן לומר יש לי בנים וע\"כ צ\"ל כיון דאינו מוחזק בבנים ועדים מעידים דיש לו אחים הוי כאלו עדים מעידים דהיא זקוקה ליבם, וא\"ל א\"כ נגד החזקה דיש לו אחים נמי לא יהא נאמן כיון דאינו מוחזק דיש לו בנים הוי כאלו מוחזק דזקוקה ליבם א\"כ הוי כמיגו נגד חזקה וי\"ל מיגו נגד חזקה בעי' דלא אפשיט' היא ועוד כאן לכמה פוסקים אמרינן מיגו נגד חזקה הואיל ויכול לעשות מעשה כמ\"ש בסימן שאח\"ז לכן אף לדעת המחמירין ס\"ל דוקא כשהוא נגד חזקה ממש מחמירין כגון הוחזק דיש לו אחין ואמר אין לי אחים משא\"כ בכה\"ג אף על גב דמחמת דאין מוחזק בבנים הוי כאלו מוחזק דאין לו בנים לא מחמירין בזה, ולפי מ\"ש בסימן שאח\"ז יש בדין זה ד' אופנים חזקה יש לו אחים ואמר אין לי אחים היינו פלוגתא בטור בסימן שאח\"ז וחזקה אין לו בנים ואמר יש לי בנים למ\"ש להמגיד נאמן לכ\"ע ולנ\"י דמי לפלוגתא הנ\"ל, וחזקה דאין לו אחים ואמר יש לי בנים נאמן לכ\"ע, ועדים דיש לו אחים ואמר יש לי בנים למ\"ש לכ\"ע אינו נאמן:","\u0003אינו נאמן אח\"כ\u0004. אבל אם אמר קודם שבאו העדים נאמן טור וב\"י:","\u0003אמר בשעת קידושין וכו'\u0004. היינו במוחזק שיש לו אחים ואין מוחזק בבנים ואמר דיש לו בנים נאמן וא\"י לחזור ולי\"א דס\"ל דחוששין לדבריו משמע דווקא כשחזר בעת מיתתו אז י\"ל קושטא קאמר שלא יהא עון תלוי בו משא\"כ כשחוזר שלא בעת מיתתו:","\u0003ויש חולקים\u0004. הב\"י כתב דהרא\"ש הוא החולק מהא דכתב בתשובה אשה אינה נאמנ' להעיד לחברת' שכלו חדשי הולד א\"כ ה\"ה ע\"א אין נאמן כי בכ\"מ דע\"א נאמן ה\"ה אשה נאמנת להעיד לחברתה וכ\"כ בד\"מ והרמב\"ם דס\"ל ע\"א נאמן שניתן לבעלה בן א\"כ ס\"ל אשה נאמנת להעיד לחברתה שכלו חדשיו לכאורה קשה על הב\"י וד\"מ ל\"ל לדייק כן מתשובת הרא\"ש הנ\"ל ת\"ל הלא הרא\"ש ס\"ל כן להדיא דאין ע\"א נאמן להתיר היבמה לשוק כמ\"ש בפ' האשה וכמ\"ש בטור סי' קנ\"ח מכ\"ש שניתן לו בן דאינו נאמן דגרע טפי דאין עביד לגלויי כמ\"ש בהשגות הראב\"ד רפ\"ג, ומ\"ש בדרישה ניתן לו בן עביד לגלויי אישתמיט' ליה דברי הראב\"ד הנ\"ל וכן קשה על הטור בסי' קנ\"ח הביא פלוגתא אם ע\"א נאמן להתיר לשוק ובסי' זה סתם ופסק כרמב\"ם ע\"א נאמן לומר שניתן לו בן ובסי' קנ\"ח אישתמט' לב\"ח מ\"ש הטור בסי' זה וצ\"ל דאיירי בהלך הוא ואשתו למ\"י והעיד ע\"א שניתן לו בן אז ע\"א נאמן משום הרוב מסייע לעד דרוב נשים נתעברו ויולדות וכמ\"ש ר\"פ האשה בתרא מ\"ה נאמן כאן ול\"ד לדין דסי' קנ\"ח מיהו מה שדייק הב\"י מתשובות הנ\"ל שפיר דייק דהא שם ג\"כ הרוב מסייע שרוב נולדים הם של קיימא כמה שכתב בתשובות הרא\"ש כלל כ\"ב ומ\"מ פסק דאשה אינה נאמנת ה\"ה ע\"א אין נאמן, לפ\"ז מוכח לדעת הב\"י וד\"מ הנ\"ל דיש לחלק בין אם רוב מסייע' לעד לבין חזקה מסייע לעד דהא ס\"ל להרא\"ש ע\"א אין נאמן להעיד שמת בעלה ואח\"כ בנה אף על גב החזקה מסייעת לעד ואם אין חילוק בדבר אכתי היה להם להביא ראייה מתשו' זו:","\u0003זה העובר ממני\u0004. מרמב\"ם משמע אפי' לא דיימי מאחרים מ\"מ אין פוטר אף על גב לענין תרומה פסק דלא חיישינן שמא זנתה מאח' כתבתי בסי' ד' תרומה בזה\"ז דרבנן מ\"ה מקיל וכ\"כ ב\"ח אלא קשה ליה למה פסק בארוסה שנתעברה דשדינן הולד אחר הארוס ולא חיישינן שמא זינתה עם אחר משום דסבר בארוסה איכא איסור דאורייתא חשש ממזר מ\"ה קשה לי' כהנ\"ל ובאמת לק\"מ כי ספק ממזר מדרבנן הוא ואפשר דקשה ליה דהא הכל פסולים לה רק הארוס כשר למה היא נאמנת דהא דספק ממזר כשר מדאורייתא דווקא ברוב כשרים או מחצה על מחצה ולא ברוב פסולים מ\"ה תירץ דנאמנת הואיל הארוס זה היתר לה שדינן אחר ההיתר אלא בסימן ד' כתבתי אף ברוב פסולים נאמנת להכשיר מטעם דאכתי ספק הוא שמא הלכה היא לבועל וקבוע כמחצה על מחצה דמי וע\"ש מיה' מה שכתב הרמב\"ם בפנוי' שאמר' מממזר נתעברתי דאמרינן שמא עם אחר זנתה קשה לשיטת הרמב\"ם דס\"ל בשפח' ליכא א\"ד אבל דברי המחבר עולים יפה דס\"ל לחלק בין א\"ד לאיסור דרבנן ותרומה דרבנן היא לכן לא חיישי' שזנתה עם אחר וכאן איכא א\"ד חיישינן ובפנוי' כשאומרת מממזר נתעברתי איכא חשש דאוריי' לכמה פוסקים כשישא שפחה ובארוס' כשרוצה להכשיר לא חיישינן שמא זינתה עם אחר דהא להכשיר מדאוריי' נמי כשר ולדעת הנ\"י אפי' במיוחדת חיישינן שמא זנתה ג\"כ עם אחר, ולרשב\"א והרא\"ש כל שבא עליה וא\"י אם בא עליה אחר לא חיישינן שמא בא עליה אחר אפי' בא\"ד, ולהמגיד אם בא עלי' ולא דיימי מעלמא לא חיישי' שמא בא עלי' אחר ועיין סי' ד':\n\u0003וי\"א אפי' בזונה אחרת המיוחדת\u0004. מה שנרשם המ\"מ פ\"ג ליתא אלא הרא\"ש בתשו' כ\"כ דרמב\"ם מודה במיוחד' והרא\"ש לשיטתו כתבתי בסמוך:","\u0003אלא חולצת\u0004. משמע מרמב\"ם והטור אפי' ראוי' היא לכהן מ\"מ חולצ' וכן מוכח בש\"ס ר\"פ האשה דהקשה מסיפא ניתן לי בן ולא הקשה מרישא מבבא זו ש\"מ דחולצת אפי' היא כשרה לכהונה וא\"ל מאחר דחיישינן שמא משקרת א\"כ אכתי קשה אתה מצריכה כרוז לכהונה שמא יבורר דמת הבן אחר הבעל ולא היתה זקוקה ליבם וצ\"ל בכה\"ג באמת היא אסורה לכהן דאם יבורר דלא היתה זקוקה ליבם ואמר דזקוקה שווי' לנפשי' חתיכה דאסורה לכהונה ועיין סי' קנ\"ח אם ע\"א מעיד שמת בעלה ואח\"כ בנה ועיין בעל המאור פ' האשה דף תל\"ה אם נשמע שמתו שניהם בעלה ובנה תו היא אינה נאמנת לומר שמת בעלה ואח\"כ בנה וכן משמע מתוספו' והרא\"ש שם דכתבו דהיא נאמנת מכח מיגו דאי בעי' היתה שתקה ולא היתה אומר' שמת בנה רק אמרה מת בעלה ממילא אוקמינן הבן בחזקת חי ואם ע\"א יודע ממיתתם נתחבטו בזה גאוני ארץ הט\"ז סידר ע\"ז תשובה א' ודעתו להיתר ועיקר טעמו משום דאי הוי אמרו מת בעלי ואז היא בחזקת היתר ואפי' אמר ע\"א להיפך לא מהני להוציא אותה מחזקתה כמ\"ש בי\"ד סי' קכ\"ז למ\"ש ר\"ס קנ\"ח בשם תוס' והרא\"ש יש סתירה לזה:","\u0003בד\"א כשהיתה פסולה וכו'\u0004. כן אוקמ' בש\"ס מטעם דחיישינן שמא אמת דברי' ואינ' זקוקה ליבם ואתה מצריכ' כרוז לכהונה והרי\"ף והרא\"ש השמיטו סוגיא זו דאיירי דוקא כשהיא פסול' לכהונה או חבושין יחדיו משמע דס\"ל דלא קי\"ל כסוגיא זו אף על גב דבהלך עם צרתו כתבו דוקא כשהי' אסורה לכהונ' דשם הרוב מסייע דהיא פטור' מיבם דרוב נשים מתעברו' ויולדות ועדיין הוא חי משא\"כ כאן הוא מת ואין רוב מסייע דמת אחר הבעל והנה תוס' ר\"פ האשה כתבו דאיירי כאן דיש עדים דהעידו דמתו הבעל והבן מ\"ה היא אינה נאמנת דאל\"כ היא נאמנ' במיגו די\"ל ניתן לי בן ועדיין קיים אז נאמנת כיון דהרוב מסייע לה דהרוב נשים מתעברות ויולדות מיהו למ\"ש לעיל להרא\"ש אפי' ע\"א אין נאמן כ\"ש היא בעצמ' וכן להרמב\"ם דוקא ע\"א או אשה לחברת' אבל לא היא לעצמ' וכן י\"ל דתוס' כ\"כ דווקא למ\"ד דלא אזלינן אחר המיעו' אבל למסקנא דחיישינן למיעוט כמ\"ש בסמוך תו אינה נאמנת לומר ניתן לי בן דחיישינן למיעוט וא\"ל בניתן לי בן אז הרוב מסייע מ\"מ אינה נאמנת ולמה לא חיישינן שמא ילדה ואסורה ליבם אף על גב החזקה מסייעה דמותר' ליבם מ\"מ הרוב מכחיש החזקה כי היכ' לצרת' חיישינן שמא ילדה כן יש לחוש שמא ילדה היא ואסורה ליבם ויש ליישב:","\u0003ה\"ז לא תחלוץ וכו'\u0004. הטעם אף על גב רוב מתעברות ויולדו' א\"כ ע\"פ הרוב היא פטורה מיבם חיישינן למיעוט משום חזקה מסייע' למיעוט ולא תחלוץ מטעם דאתה מצריך כרוז לכהונה וכתב ב\"י בשם רי\"ו נסתפק הרא\"ש אם מהני כשנדרה אשה זו שלא תנשא לכהן, עיין רמב\"ם פ\"ג דלא חיישינן לצרתה במדינה אחרת הואיל ולא היה בעלה עמה:"]],["מִי שֶׁיֵּשׁ לוֹ אָח מֵאָבִיו, אֲפִלּוּ הוּא \u0010c0\u0011 מַמְזֵר אוֹ עוֹבֵד ע\" א, וַאֲפִלּוּ הוּא קָטָן, מִשֶּׁיָּצָא רֹאשׁוֹ וְרֻבּוֹ לַאֲוִיר הָעוֹלָם קֹדֶם שֶׁיָּמוּת אָחִיו, הֲרֵי זֶה זוֹקֵק \u0005(פי', קוֹשֵׁר, מֵעִנְיָן \"אֲסוּרִים בַּזִּקִים\")\u0006 \u0005(אִיּוֹב לו, ח)\u0006 אֶת אִשְׁתּוֹ לְיִבּוּם. אֲפִלּוּ הוּא גּוֹסֵס אוֹ פְּצוּעַ מַכּוֹת שֶׁאֵינוֹ יָכוֹל לִחְיוֹת מֵהֶם, לֹא תִּנָּשֵׂא כָּל זְמַן שֶׁהוּא חַי. אֲבָל אִם הוּא אָחִיו מֵאִמּוֹ, אוֹ שֶׁנּוֹלַד אַחַר מוֹתוֹ, יְבִמְתּוֹ מֻתֶּרֶת לַשּׁוּק. וְכֵן אִם הָיָה לוֹ אָח מֵהַשִּׁפְחָה אוֹ מֵהַנָּכְרִית, אֵינוֹ זוֹקֵק אֶת אִשְׁתּוֹ, אַף עַל פִּי שֶׁהָיְתָה לֵדָתוֹ בִּקְדֻשָּׁה, הוֹאִיל וְהוֹרָתוֹ הָיְתָה שֶׁלֹּא \u0010c1\u0011 בִּקְדֻשָּׁה:\nאֲפִלּוּ קָרוֹב, אוֹ אִשָּׁה, אוֹ עֶבֶד, אוֹ קָטָן שֶׁהוּא מַכִּיר וְנָבוֹן, נֶאֱמָנִים לוֹמַר: זֶה פְּלוֹנִי אֲחִי פְּלוֹנִי מֵאָבִיו, וְזוֹ הִיא יְבִמְתּוֹ, וְחוֹלְצִים אוֹ מְיַבְּמִים עַל פִּיהֶם:\nגֵּרִים שֶׁנִּתְגַּיְּרוּ וַעֲבָדִים שֶׁנִּשְׁתַּחְרְרוּ, אֵין לָהֶם אַחֲוָה כְּלָל, אֲפִלּוּ אֶחָד מֵהֶם הוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה וְלֵדָתוֹ בִּקְדֻשָּׁה, וְהַשֵּׁנִי הוֹרָתוֹ וְלֵדָתוֹ בִּקְדֻשָּׁה. וַאֲפִלּוּ הֵם תְּאוֹמִים וְנוֹלְדוּ בִּקְדֻשָּׁה, אֵין לָהֶם אַחֲוָה עַד שֶׁיִּהְיוּ שְׁנֵיהֶם הוֹרָתָם וְלֵדָתָם בִּקְדֻשָּׁה:\nנָפְלָה לִפְנֵי יָבָם מְשֻׁמָּד, יֵשׁ מִי שֶׁמַּתִּיר אִם הָיָה מְשֻׁמָּד כְּשֶׁנָּשְׂאָהּ אָחִיו; וְאֵין לִסְמֹךְ עָלָיו. \u0005 הַגָּה: \u0010c2\u0011 מִיהוּ, אִם עָבְרָה \u0006 \u0005 וְנִשֵּׂאת בְּלֹא חֲלִיצָה, \u0010c3\u0011 כִּי לֹא \u0006 \u0005 יָדְעָה שֶׁהָיָה לָהּ יָבָם, וְאַחַר כָּךְ נוֹדַע שֶׁיֵּשׁ לָהּ יָבָם מְשֻׁמָּד, לֹא תֵּצֵא \u0006 \u0005(מהר\"י מִינְץ סִי' י\"ב)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דַּוְקָא אִם חָלַץ לָהּ לְבַסוֹף \u0006 \u0005(מהרי\"ו סִי' נ\"ד וּבִנְיָמִין זְאֵב)\u0006. \u0005 הָיוּ לָהּ שְׁנֵי יְבָמִים, אֶחָד מְשֻׁמָּד וְהוּא הַגָּדוֹל, וְאֶחָד קָטָן וְהוּא יִשְׂרָאֵל, לֹא תַּחֲלֹץ אֶלָּא מִן הַיִּשְׂרָאֵל; \u0010c4\u0011 וַאֲפִלּוּ בְּדִיעֲבַד לֹא מְהַנֵּי מִן הַמְשֻׁמָּד \u0006 \u0005(כֵּן הֵשִׁיב מוהר\"ם וְכ\"כ מהרא\"י וּמַהֲרִי\"ק)\u0006. \u0005 אֲבָל אִם הוּא אָנוּס, מְהַנֵּי \u0006 \u0005 בְּדִיעֲבַד \u0006 \u0005(רִיבָ\"שׁ סִימָן א')\u0006. \u0005 וְהַמְקַדֵּשׁ אִשָּׁה וְיֵשׁ לוֹ אָח מְשֻׁמָּד, יָכוֹל לְקַדֵּשׁ \u0010c5\u0011 וּלְהַתְנוֹת בִּתְנַאי \u0006 \u0005 כָּפוּל שֶׁאִם תִּפֹּל לִפְנֵי הַמְשֻׁמָּד לְיִבּוּם שֶׁלֹּא תְּהֵא מְקֻדֶּשֶׁת \u0006 \u0005(מהרא\"י ברי\"ן)\u0006:\nאִם הַמֵּת הָיָה מְשֻׁמָּד, אִשְׁתּוֹ זְקוּקָה לְאָחִיו. \u0005 וְהוּא הַדִּין זַרְעוֹ שֶׁיֵּשׁ לוֹ מִיִּשְׂרְאֵלִית (ב\"י וְד\"ע)\u0006:\nלֹא הָיָה מֻחְזָק בְּאַחִים, וְאָמַר: יֵשׁ לִי אַחִים, אֵינוֹ נֶאֱמָן. בָּא אֶחָד וְאָמַר: אֲנִי אָחִיו, אֵינוֹ נֶאֱמָן; \u0010c6\u0011 וַאֲפִלּוּ עֵד אֶחָד \u0010c7\u0011 \u0005 אוֹ קָרוֹב \u0006 מֵעִיד עָלָיו שֶׁהוּא אָחִיו, אֵינוֹ נֶאֱמָן לְהוֹצִיאָהּ מֵחֶזְקָתָהּ:\nהָיָה מֻחְזָק בְּאַחִים, וְאָמַר בִּשְׁעַת מִיתָתוֹ: אֵין לִי אַחִים, \u0010c8\u0011 אֵינוֹ נֶאֱמָן. וְכֵן אִם אָמַר עַל מִי שֶׁהֻחְזַק אָחִיו, אֵין זֶה אָחִי, אֵינוֹ נֶאֱמָן:\nלֹא הָיָה מֻחְזָק בְּאַחִים, \u0010c9\u0011 וְיָצָא קוֹל שֶׁיֵּשׁ עֵדִים שֶׁיָּעִידוּ שֶׁיֵּשׁ לוֹ אַחִים, וְהָעֵדִים בִּמְדִינָה אַחֶרֶת, אֲפִלּוּ אָמַר הוּא בִּשְׁעַת מִיתָתוֹ: אֵין לִי אָח, הֲרֵי זוֹ חוֹשֶׁשֶׁת, וְתַמְתִּין עַד שֶׁיָּבֹאוּ עֵדִים שֶׁאָמְרוּ, וְיִשְׁאֲלוּ:\nאִשָּׁה שֶׁאֵין לְבַעְלָהּ בֵּן וְלֹא אָח, וַחֲמוֹתָהּ וְחָמִיהָ בִּמְדִינַת הַיָּם, וּמֵת בַּעְלָהּ, \u0010c10\u0011 מֻתֶּרֶת לִנָּשֵׂא; וְלֹא חַיְשִׁינָן שֶׁמָּא יָלְדָה חֲמוֹתָהּ זָכָר וְהִיא זְקוּקָה לוֹ. אֲבָל אִם יָצָאתָה חֲמוֹתָהּ מִכָּאן מְעֻבֶּרֶת, חוֹשְׁשִׁין שֶׁמָּא יָלְדָה זָכָר וְהִיא זְקוּקָה לוֹ:\nאִשָּׁה שֶׁמֵּת בַּעְלָהּ, וְהָיָה לוֹ בֵּן בִּמְדִינַת הַיָּם, הֲרֵי זוֹ מֻתֶּרֶת לְזָר, וְאֵין חוֹשְׁשִׁין שֶׁמָּא מֵת הַבֵּן, אֶלָּא הַעֲמֵד אוֹתָהּ עַל חֶזְקָתָהּ. \u0010c11\u0011 \u0005 יָבָם אָסוּר לָדוּר עִם חֲלוּצָתוֹ, אִם לִבּוֹ \u0006 \u0005 גַּס בָּהּ, כְּמוֹ אָרוּס וַאֲרוּסָתוֹ \u0006 \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן ר\"ט)\u0006; \u0005 וְדַוְקָא לְאַחַר שֶׁחָלַץ, אֲבָל קֹדֶם שֶׁחָלַץ, שָׁרֵי \u0006 \u0005(מַהֲרַ\"ם פַּדָּוואָה סִי' ז')\u0006:",[],["\u0003ממזר\u0004. כבר כתבתי ר\"ס הקודם דאיירי דהיו חבושי' בבית האסורי' יחדיו ועיין בהג\"מ ובש\"ג אצל המ' שכתבו בשם רש\"י דמביא ראיה מזה לסתור דעת הפוסקים דס\"ל יבם ממזר /מומר/ א\"צ חליצה דהא ממזר איסורו עולם וחולץ וב\"ח תמה למה לא הביאו ראייה מממזר ולא ראה פוסקים הנ\"ל ויש ליישב קושיא זו י\"ל דממז' שאני שהוא ישראל לכל דבריו ואחיו במצות כמ\"ש בב\"ח:","\u0003אפי' קרוב\u0004. בב\"ה איתא אפילו עד מפי עד וכל אות' שנאמנת לומר מת בעלה נאמנת כאן משמע אפי' עכו\"ם מסל\"ת נאמן מיהו י\"ל הואיל בשבוי' ע\"א ואשה וקרוב נאמנות מ\"מ עכו\"ם לדעת הרא\"ש אין נאמנין כן ה\"נ וכן דעת ב\"ח דעכו\"ם אין נאמן ובמ' משמע דוקא כשהוא מוחזק שהוא אחיו ולא משמע מדברי שאר פוסקים ועיין בהגמיי' ובמ' פ' מ\"ח הפסולים כשרים להעיד אפי' אינן מסל\"ת:","\u0003מיהו וכו'\u0004. הנה למ\"ש טור ובמ' פ' החולץ והמגיד פי\"א ה\"י והמהרי\"ק שורש קע\"ה משמע דווקא כשהיה מומר בעת הנישואין אז מקילין ודברי הרב בהג\"ה מ\"ש ומיהו קאי על דברי המחבר שהיה מומר בעת הנישואין אף על גב בעלמא קי\"ל מיתה מפל' וכאן בעת המיתה היה מומר וכן בהג\"מ פ' החולץ כתב בשם ר\"ח אפי' היה מומר אחר הנישואין נמי מקילין מטעם הנ\"ל מ\"מ נראה עיקר כרוב פוסקים הנ\"ל, וכן אם בקטנותו נאנס ונטמע בין הגוים הוי כאלו נתקדשה ואח\"כ המיר כי מעשה קטן לא חשוב מעשה כמ\"ש בת\"ה:","\u0003כי לא ידעה\u0004. ואפילו אם ידעה שיש לה יבם אלא סברה שמת מותרת לבעלה כמ\"ש בתשובות מהרי\"ו ועיין ב\"י סימן הנ\"ל ובעלמא כה\"ג דידעה שיש לה יבם תצא כמ\"ש בת\"ה ולקמן בהג\"ה:","\u0003אפי' בדיעבד לא מהני וכו'\u0004. כ\"כ בד\"מ ומחלק כן בין תשו' מהרי\"ק דפסק בדיעבד דלא מהני וכו' חליצת המומר לבין תשו' הריב\"ש דפסק בדיעבד מהני חליצת המומר דאיירי הריב\"ש באנוס אבל לא משמע שם דאיירי באנוס אלא בכל מומר איירי מטעם דהוא שייך בתור' גיטין וחליצה ואפשר מסברא דנפשי' מכריע כן להקל באונס מיהו מד\"מ לא משמע דמכריע מסבר' כן אלא דפי' דברי הריב\"ש כן:","\u0003ולהתנות בת\"כ\u0004. אף על גב בעלמא אמרינן אין תנאי בנשואין מ\"מ בכה\"ג התירו והיינו בעת הביא' מתנה כן דלאו מתנה בעת הקידושין ונישואין עדיין יש לחוש שמא בעת הביאה מקדש אותה בסתם ועיין סימן ל\"ח ועיין ב\"ח שהביא תשובת מהרא\"י ומדמה שם דין זה לתנאי' המבוארים בסימן ל\"ח ולפי תשובות הנ\"ל צ\"ל כמ\"ש דמתנה בעת הביאה אבל לכאורה אנ\"ל ול\"ד לשם בשלמא תנאי אשר הוא מסופק אם נתקיים התנאי שייך לומר שמקדש בכל אופן שלא יהא ביאתו זנות משא\"כ כאן דליכא חשש ביאת זנות ולא שייך לומר דלא נתקיים התנאי:","\u0003ואפי' ע\"א וכו'\u0004. עיין י\"ד סי' קכ\"ז שם פסק דבר דלא נתחזק לא להיתר ולא לאיסור נאמן ע\"א והכא כיון דלא הוחזק דיש לו אחים הוי כאלו מוחזק' דאינה זקוקה ליבם לכן אינו נאמן וכן איתא בש\"ס בכה\"ג היא בחזקת היתר ולהנ\"י שהבאתי בסי' הקודם דס\"ל אם אין מוחזק לבנים לא הוי כחזקה דאין לו בנים צריך ישוב דהא ס\"ל בכה\"ג לא הו' חזקה א\"כ למה אין ע\"א נאמן מיהו מרש\"י והר\"ן יש לדיין /לדייק/ כל שלא אמר יש לי בנים אף שלא אמר יש לי אחים והוא לא הוחזק באחי' ובנים ובא א' ואמר אני אחיו חוששין לדבריו וכ\"כ ב\"ח א\"כ מכ\"ש דע\"א יכול לאסור לפ\"ז י\"ל דהנ\"י ס\"ל באמת כן וס\"ל הני פוסקים כל כה\"ג לא הוי חזק' היתר לפ\"ז י\"ל דהם פליגי על וי\"א שהביא בסי' הקודם אף נגד עדים האומרים דיש לו אחים נאמן לומר יש לי בנים דהא טעם הפוסקים דס\"ל דאינו נאמן מטעם מאחר דאין מוחזק בבנים ועדים אומרים שיש לו אחים נעשה כודאי דהיא זקוקה ליבם:","\u0003או קרובים\u0004. כצ\"ל וכן הוא בד\"מ:","\u0003אינו נאמן\u0004. אף על גב דיש לו מיגו ליתן לה גט א\"א מיגו נגד החזק' ולכמה פוסקים נאמן הואיל בידו לעשות מעשה וליתן גט מיגו כזה אמרינן אף נגד החזקה ולרמב\"ן באומר סתם אין לי אחים לא הוי נגד החזקה די\"ל שהיה לו אחים ומתו אא\"כ שיאמר דלא היה לו אחים ובמוחזק דאין לו בנים ואמר יש לי בנים נאמן להמגיד כמ\"ש בסי' הקוד' והנ\"י שהבאתי שם לא ס\"ל הסבר' הואיל בידו לעשות מעשה גם לא ס\"ל סברת המגיד ביש לו בנים לכן צריך לתרץ במוחזק דיש לו אחים ואמר יש לו בנים נאמן משום דלא הוי נגד החזקה ומזה מוכח מ\"ש בסעיף הקודם ובכל זה במקום עיגון צ\"ע אם יש להקל ואם לא אתחזק באחים ואמר אין לי אחים וחזר לפני מותו ואמר יש לי אחים מותר' לכ\"ע אפי' לדעת הרמ\"ה שהבי' בסי' הקודם כשחוז' ואמר אין לי בנים שחולצת דשם אוקמי בש\"ס דאיירי במוחזק באחים ואינו מוחזק בבנים מ\"ה כשחזר ואמר אין לי בנים סביר' ליה לרמ\"ה דחולצת מה שאין כן כשאינו מוחזק וכן באחים מבואר בש\"ס דמתניתין איירי דלא הוחזק לן באחין תו אין נאמן בעת מיתתו לומר יש לי אחים מכ\"ש כשאומר אין לי אחים ומ\"ש ב\"ח להרמ\"ה חולצת כמה שסבר בסי' הקודם ל\"ד בסוגי':","\u0003ויצא קול\u0004. אפי' אמר אין לי אח ואח\"כ יצא קול חיישינן לקול ועיין במגיד לדעת הרמב\"ם אפי' קול דלא אתחזק בב\"ד חיישינן:","\u0003מותרת להנשא\u0004. משום היא בחזקת הית' לשוק ורוב מסייע נמי היתר לשוק דרוב מפלת ויולדת נקבות אבל אם יצאה מעוברת איתרע החזק' אדרבא קצת הוחזק' ליבם תוס' ונ\"י:","\u0003יבם אסור\u0004. עיין מ\"ש בסי' קי\"ט כל שהוא איסור אפי' אין בו מלקות אסור לדור במבוי מכ\"ש בחליצה דאיכא איסור לאו כמ\"ש בתו' ריש יבמות דף י\"א ועיין סי' קס\"ב מ\"ש ועיין תשו' מהר\"מ סי' קל\"א מ\"ש בענין זה ופי' גס בה היינו מכירין ברמיזות וקריצות וגייסי טובא:"]],["כְּשֵׁם שֶׁהָאִשָּׁה נֶאֱמֶנֶת לוֹמַר: מֵת בַּעְלִי, שֶׁתִּנָּשֵׂא; כָּךְ נֶאֱמֶנֶת לוֹמַר: מֵת בַּעְלִי, שֶׁתִּתְיַבֵּם, וְהַיָּבָם נִכְנָס לַנַּחֲלָה עַל פִּיהָ. \u0010c0\u0011 אֲבָל אֵינָהּ נֶאֱמֶנֶת לוֹמַר: מֵת יְבָמִי, שֶׁתִּנָּשֵׂא לַשּׁוּק. וְאֵין הָאִישׁ נֶאֱמָן לוֹמַר: מֵת אָחִי וַאֲיַבֵּם אֶת אִשְׁתּוֹ. לְפִיכָךְ, הָלְכָה הִיא וּבַעְלָהּ וִיבָמָהּ לִמְדִינַת הַיָּם, וּבָאָה וְאָמְרָה: מֵת בַּעְלִי וְאַחַר כָּךְ מֵת יְבָמִי, אוֹ מֵת יְבָמִי וְאַחַר כָּךְ מֵת בַּעְלִי, אֵינָהּ נֶאֱמֶנֶת:\nהָלְכָה הִיא וּבַעְלָהּ לִמְדִינַת הַיָּם לְבַד, וּבָאָה וְאָמְרָה: נִתַּן לִי יָבָם וָמֵת, בֵּין שֶׁאָמְרָה: מֵת בַּעְלִי וְאַחַר כָּךְ מֵת יְבָמִי, בֵּין שֶׁאָמְרָה: מֵת יְבָמִי וְאַחַר כָּךְ מֵת בַּעְלִי, נֶאֱמֶנֶת:\nנֶאֱמָן עֵד אֶחָד לְהָעִיד לִיבָמָה שֶׁמֵּת בַּעְלָהּ, וּמִתְיַבֶּמֶת עַל פִּיו; אוֹ שֶׁמֵּת יְבָמָהּ, שֶׁתִּנָּשֵׂא לַשּׁוּק; אוֹ לוֹמַר: מֵת בַּעֲלִיךְ וְאַחַר כָּךְ מֵת בְּנֵךְ; וַאֲפִלּוּ עֶבֶד אוֹ שִׁפְחָה אוֹ אִשָּׁה אוֹ כּוּתִי מֵסִיחַ לְפִי תֻּמּוֹ, אוֹ עֵד מִפִּי עֵד, נֶאֱמָן לְהָעִיד בְּמִיתַת הַיָּבָם כְּמוֹ שֶׁנֶּאֱמָן בְּמִיתַת הַבַּעַל, וְדִין עֵדוּת זוֹ כְּדִין אוֹתוֹ עֵדוּת לְעִנְיַן עֵדִים הַמַּכְחִישִׁים זֶה אֶת זֶה בְּמִיתַת הַיָּבָם לְכָל דָּבָר. \u0005 הַגָּה: \u0010c1\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין עֵד אֶחָד נֶאֱמָן לוֹמַר שֶׁמֵּת \u0006 \u0005 יְבָמָהּ, לְהַתִּירָהּ לְעָלְמָא: \u0010c2\u0011 \u0006\nחָמֵשׁ נָשִׁים שֶׁאֵינָן מְעִידוֹת זוֹ לָזוֹ שֶׁמֵּת בַּעְלָהּ, כָּךְ אֵינָן מְעִידוֹת שֶׁמֵּת יְבָמָהּ:\nשְׁתֵּי יְבָמוֹת שֶׁבָּאוּ מִמְּדִינַת הַיָּם, זוֹ אוֹמֶרֶת מֵת בַּעְלָהּ, וְזוֹ אוֹמֶרֶת מֵת בַּעְלָהּ, זוֹ אֲסוּרָה מִפְּנֵי בַּעְלָהּ שֶׁל זוֹ, וְזוֹ אֲסוּרָה מִפְּנֵי בַּעְלָהּ שֶׁל זוֹ, שֶׁאֵין יְבִמְתָּהּ נֶאֱמֶנֶת לְהָעִיד לָהּ שֶׁמֵּת יְבָמָהּ, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0010c3\u0011 הָיָה לְאַחַת מֵהֶן עֵד שֶׁמֵּת בַּעְלָהּ, זוֹ שֶׁיֵּשׁ לָהּ עֵד אֲסוּרָה מִפְּנֵי יְבָמָהּ, וְזוֹ שֶׁאֵין לָהּ עֵד מֻתֶּרֶת, שֶׁהֲרֵי הֵעִיד הָעֵד שֶׁמֵּת יְבָמָהּ, וְהִיא נֶאֱמֶנֶת לוֹמַר שֶׁמֵּת בַּעְלָהּ. הָיוּ לָזוֹ בָּנִים וְלָזוֹ אֵין בָּנִים, וְלִשְׁתֵּיהֶן אֵין עֵדִים, זוֹ שֶׁאֵין לָהּ בָּנִים אֲסוּרָה, וְזוֹ שֶׁיֵּשׁ לָהּ בָּנִים מֻתֶּרֶת:\nלֹא הָיוּ לָהֶם לֹא עֵדִים וְלֹא בָּנִים, וְהָיוּ כָּאן יָבָם אוֹ יְבָמִים וְיִבְּמוּ אוֹתָן, וּמֵתוּ גַּם הֵם בְּלֹא בָּנִים, וְאֵין לָהֶם אַחִים אֲחֵרִים, אֲסוּרוֹת לְהִנָּשֵׂא לְזָר כְּמוֹ שֶׁהָיוּ בִּתְחִלָּה. אֲבָל אִם הִנִּיחוּ אֵלּוּ בָּנִים, אוֹ שֶׁגֵּרְשׁוּם בְּגֵט, מֻתָּרוֹת לְהִנָּשֵׂא לְזָר:",[],["\u0003אבל אינה נאמנת לומר מת יבמי\u0004. הואיל הוא איסור לאו שמא הוא קל בעיני' רמב\"ם וגבי אין איש נאמן כתב עד שיעידו ב' עדים שאין ע\"א נאמן אלא משום התרת עגונה, ולכאורה נראה בזה\"ז דיש חרם ר\"ג שלא ישא אשה על אשתו אין ע\"א נאמן שמתה אשתו דהא דבר שנתחזק באיסור הוא ואין ע\"א נאמן כמ\"ש בי\"ד סימן קכ\"ז:","\u0003וי\"א דאין ע\"א נאמן\u0004. הנה כל הפוסקים מקילין בזה לבד הרא\"ש הוא המחמיר ועיין תשו' מהרי\"ק ותשו' מהר\"ם סי' ל\"ו וק\"ל ותשו' מהר\"ם פדו' סי' פ\"ד ותשו' ר\"י לבית הלוי סי' י\"ב כולם מסכימין בעת הדחק ועיגון יש להקל וכן עד מפי עד נאמן וכ\"כ בד\"מ וב\"ח ומכ\"ש כשיבא /כשיבם/ מומר אז הוי ס\"ס דרוב פוסקים ס\"ל ע\"א נאמן גם לכמה פוסקי' כשיבא /כשיבם/ מומר אינם נזקקים לו וב\"ח כתב אם ע\"א מעיד שניתן לו בן והיבם לפנינו יש להחמיר דלא שייך עיגון דהא היבם לפנינו והביא ראי' מדלא כתב הטור בסי' קנ\"ו דברי הרמב\"ם דמיקל גם שניתן לו בן ואישתמטא דברי הטור שם שהביא דברי הרמב\"ם גם קשה איך כתב להחמיר וליתן חליצ' הא יש לחוש שמא דברי העד אמת ואתה מצריך כרוז לכהונה וכשיש לה בן וע\"א מעיד דמת הבן ואח\"כ הבעל נאמן אף על פי שהוצי' אות' מחזקה מ\"מ להכניסה לרשות היבם נאמן ע\"א וכ\"כ התוס' והרא\"ש פ' האשה דף צ\"ד ועיין תשו' מהר\"י מינץ סימן י\"ד שכתב אפשר בזה\"ז שאין מייבמין אלא חולצ' היא בעצמ' נמי נאמנת שמת היבם ומכ\"ש ע\"א אף לדעת הרא\"ש מיהו אין מוכרח ועיין בסי' י\"ז מ\"ש בחמש נשים שאינן מעידות אם נאמנין בזה\"ז ועיין תשו' צ\"צ סי' פ\"ח ולהרא\"ש מת בעלה ואח\"כ מת בנה ג\"כ ע\"א אין נאמן:","\u0003חמש נשים\u0004. עיין בסי' י\"ז מי הן חמש נשים ושם מבואר בת בעלה א' מהן וכאן א\"א לומר בת בעלה דא\"כ אינה זקוקה ליבם וא\"ל בת בעלה הראשון ואח\"כ נשאת זקוקה ליבם דהא בת בעל' הראשון כשרה להעיד כמ\"ש בסי' י\"ז בשם הכ\"מ אלא ע\"כ דהיינו בת יבמה והיא בכלל בת בעלה וכ\"כ בתשו' צ\"צ שם וחמותו כאן היינו אם יבמה דווקא דהא איירי כאן שמת בעלה א\"כ אם חמותה דלאו אם יבמה כשירה להעיד מ\"מ צרתה לא איצטריך כאן דפשיטא אינה נאמנת דהא היא בעצמ' זקוקה ליבם:","\u0003היה לא' מהן עד\u0004. כ\"כ הרמב\"ם היינו לשיטת הפוסקים דע\"א נאמן ולשיטת הרא\"ש איירי בדאיכא ב' עדים וא\"ל להרא\"ש ל\"ל הטעם דצרה אינה מעידה לחברתה ת\"ל ע\"א אין נאמן וצ\"ל דה\"א הואיל ונאמנת על עצמה דמת בעלה נאמנת על חברתה קמ\"ל דא\"י להעיד על הצרה:"]],["הַזְּקוּקָה לְיָבָם שֶׁנִּתְקַדְּשָׁה לְאַחֵר בְּשׁוֹגֵג, \u0010c0\u0011 נוֹתֵן לָהּ הַזָּר \u0010c1\u0011 שֶׁקִּדְּשָׁהּ גֵּט, וִיבָמָהּ מְיַבֵּם אוֹ חוֹלֵץ. אִם הָיָה יְבָמָהּ כֹּהֵן, שֶׁאֵינוֹ יָכוֹל לִשָּׂא גְּרוּשָׁה, תֵּצֵא מֵהַזָּר בְּגֵט, כְּדֵי שֶׁלֹּא יְהֵא חוֹטֵא נִשְׂכָּר, וְחוֹלֵץ לָהּ יְבָמָהּ. \u0010c2\u0011 וְאִם חָזַר הַזָּר שֶׁגֵּרְשָׁהּ מֵהָאֵרוּסִין, וְנָשְׂאָהּ אַחַר שֶׁחָלַץ לָהּ יְבָמָהּ, אֵין מוֹצִיאִין אוֹתָהּ מִיָּדוֹ. \u0005 הַגָּה: \u0010c3\u0011 וְיֵשׁ אוֹמְרִים דְּאֲפִלּוּ חָזַר \u0006 \u0005 וּנְשָׂאָהּ, מוֹצִיאִין אוֹתָהּ מִיָּדוֹ, הוֹאִיל וְנִתְקַדְּשָׁה לוֹ \u0010c4\u0011 בְּאִסוּר. וְדַוְקָא אִם קִדְּשָׁהּ בְּמֵזִיד, אֲבָל אִם קִדְּשָׁהּ בְּשׁוֹגֵג, שֶׁלֹּא יָדְעוּ שֶׁהָיָה לָהּ יָבָם, אִם רוֹצֶה הַיָּבָם לְיַבֵּם, צָרִיךְ הַמְקַדֵּשׁ לְגָרְשָׁהּ; וְאִם רוֹצֶה הַיָּבָם לַחֲלֹץ, חוֹלֵץ לָהּ וְנִשֵּׂאת לַמְקַדֵּשׁ, וְצָרִיךְ לַחֲזֹר וּלְקַדֵּשׁ אוֹתָהּ אַחֵר שֶׁחָלַץ לָהּ יְבָמָהּ \u0006 \u0005(ר\"ת)\u0006; \u0005 וְכֵן נִרְאֶה לִי עִקָּר. וְיֵשׁ אוֹמְרִים דַּוְקָא בְּשׁוֹגֵג גָּמוּר, שֶׁלֹּא יָדְעוּ שֶׁיֵּשׁ כָּאן יָבָם. אֲבָל הָיָה כָּאן יָבָם, אֶלָּא שֶׁהָיָה סְבוּרָה שֶׁמֵּת, כִּי כֵּן יָצָא הַקּוֹל, \u0010c5\u0011 תֵּצֵא \u0006 \u0005 מִן הַמְקַדֵּשׁ \u0006 \u0005(ת\"ה סִי' רכ\"ב)\u0006: \u0010c6\u0011\nנִשֵּׂאת לְזָר, אֲפִלּוּ בְּשׁוֹגֵג, מוֹצִיאָהּ בְּגֵט, וַאֲפִלּוּ הָיוּ לוֹ בָּנִים מִמֶּנָּה; וְנֶאֶסְרָה עָלָיו וְעַל יְבָמָהּ, וְי\"ג דְּרָכִים שֶׁנִּתְבָּאֲרוּ בְּסִימָן י\"ז בָּהּ, אֶלָּא שֶׁאֵין הַוָּלָד מַמְזֵר. וְיֵשׁ אוֹמְרִים שֶׁהוּא מַמְזֵר מִדְּרַבָּנָן. וִיבָמָהּ חוֹלֵץ לָהּ, וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לַאֲחֵרִים \u0005 וְעַיֵּן לְעֵיל סִימָן קנ\"ז סָעִיף ד': \u0006\nשׁוֹמֶרֶת יָבָם שֶׁזִּנְּתָה, לֹא נֶאֶסְרָה עַל יְבָמָהּ, \u0010c7\u0011 אִם הוּא יִשְׂרָאֵל. \u0010c8\u0011 \u0005 וְיֵשׁ אוֹמְרִים דַּאֲסוּרָה לַבּוֹעֵל מִשּׁוּם \u0006 \u0005 קְנָסָא \u0006 \u0005(נ\"י פֶּרֶק הָאִשָּׁה)\u0006:\nנִתְיַבְּמָהּ בְּטָעוּת, כְּגוֹן שֶׁשָּׁמְעָה שֶׁמֵּת בַּעְלָהּ, וְאַחַר כָּךְ בָּא; אִם הָיְתָה נְשׂוּאָתוֹ, אֵינָהּ צְרִיכָה גֵּט מֵהַיָּבָם, \u0010c9\u0011 \u0005 וּמֻתֶּרֶת לְבַעְלָהּ. \u0006 וְאִם הָיְתָה אֲרוּסָתוֹ, צְרִיכָה גֵּט מֵהַיָּבָם \u0005 וַאֲסוּרָה לְבַעְלָהּ \u0006 \u0005(טוּר)\u0006: \u0010c10\u0011\nהַיָּבָם אָסוּר בִּקְרוֹבוֹת זְקוּקָתוֹ, אֲפִלּוּ מֵתָה קֹדֶם שֶׁיִּבֵּם אוֹ יַחֲלֹץ, בֵּין שֶׁהוּא יָבָם אֶחָד, בֵּין שֶׁהֵם שְׁנֵי יְבָמִים. \u0005 וַאֲפִלּוּ סָפֵק אִם זְקוּקָה אוֹ לֹא, אָזְלִינָן לְחֻמְרָא \u0006 \u0005(טוּר)\u0006. לְפִיכָךְ, אִם קִדֵּשׁ אֶחָד מֵהֶם אֲחוֹת זְקוּקָתוֹ, אָסוּר לוֹ לְכָנְסָהּ, מִפְּנֵי שֶׁהִיא כַּאֲחוֹת אֲרוּסָתוֹ, עַד שֶׁיְּיַבֵּם אָחִיו אוֹ יַחֲלֹץ לַזְּקוּקָה וְתִפְקַע \u0010c11\u0011 הַזִּקָּה. וְיֵשׁ אוֹמְרִים דְּדַוְקָא בְּקִדְּשָׁהּ, אֲבָל אִם כָּנְסָהּ, פָּקְעָה לָהּ זִקָּה וּמֻתָּר לָבֹא עָלֶיהָ קֹדֶם שֶׁיְּיַבֵּם אוֹ יַחֲלֹץ אָחִיו. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּעַכְשָׁו בַּזְּמַן הַזֶּה דְּאִכָּא חֵרֶם רַבֵּנוּ גֵּרְשֹׁם שֶׁלֹּא לָשֵׂאת שְׁתֵּי נָשִׁים, אִם נָפְלָה לְאֶחָד שׁוֹמֶרֶת יָבָם, אָסוּר לִשָּׂא אַחֶרֶת עַד שֶׁיַּחֲלֹץ לִיבִמְתּוֹ \u0006 \u0005(ר\"י מִינְץ)\u0006. \u0005 וְדַוְקָא שֶׁלֹּא הָיְתָה מְשֻׁדֶּכֶת לוֹ כְּבָר, אֲבָל אִם הָיְתָה מְשֻׁדֶּכֶת לוֹ כְּבָר, מֻתָּר לְכָנְסָהּ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דִּכְתֻבוֹת)\u0006:\nקִדֵּשׁ אִשָּׁה, וְאַחַר כָּךְ מֵת אָחִיו שֶׁהָיָה נָשׂוּי אֲחוֹתָהּ, כּוֹנֵס אֶת אִשְׁתּוֹ:\nקִדֵּשׁ אֲחוֹת זְקוּקָתוֹ, וְאַחַר כָּךְ מֵת אָחִיו שֶׁהָיְתָה גַּם כֵּן זְקוּקָה לוֹ, וְלֹא נִשְׁאֲרָה זְקוּקָה אֶלָּא לְזֶה, מוֹצִיא אֲרוּסָתוֹ בְּגֵט וְאֶת הַיְבָמָה בַּחֲלִיצָה; וְאִם מֵתָה אֲרוּסָתוֹ, \u0010c12\u0011 חוֹזֶרֶת הַיְבָמָה לְהֶתֵּרָהּ, רָצָה חוֹלֵץ רָצָה מְיַבֵּם:",[],["\u0003נותן לה הזר גט\u0004. לדעת המחבר אפי' אם קידש בשוגג אסורה למקדש אפי' אם ירצה היבם לחלוץ ובאמת לרוב הפוסקים מותרת למקדש וכן הרמב\"ן ורשב\"א והרא\"ש כתבו בשם ה\"ג דאיירי בקידש במזיד גם הרמב\"ם י\"ל דאיירי בקידש במזיד כי ס\"ל הסוגיא איירי במזיד מדתני שלא יהא חוטא נשכר כמ\"ש בתו' וכ' הוא מה שמפורש בש\"ס כדרכו תמיד וכן משמע ממגיד שהביא דעת הרמב\"ן ורשב\"א ולא כתב דרמב\"ם חולק עליהם, לכאורה קשה על המחבר שפוסק כאן דאסורה למקדש אחר החליצה ובס\"ס י\"ז פסק דמותרת למקדש ודין זה ילפינן משם דגזרינן אטו אשה שהלכה למ\"י כמ\"ש בתוספות וכל הפוסקים ולמה מחמיר כאן יותר וכן קשה על הדין שכתב הת\"ה אם היתה סבורה שמת תצא מן המקדש ושם מותרת לו וצ\"ל שוגג דכאן לאו ע\"פ עד אלא קול בעלמא ואם היה ע\"פ עד באמת מותרת למקדש:","\u0003גט\u0004. והא דצריכה גט מזר היינו מספק דמספקא לן לא תהיה אשת המת החוצה אם ללאו אתי ותופסין בה קידושין או לא יהיה בה הוי':","\u0003ואם חזר הזר\u0004. כ\"כ הרמב\"ם ספ\"ב והטור כתב בשם הרמב\"ם אם חזר הזר וקדשה וכו' וכתב דהרא\"ש חולק ע\"ז אבל גירס' שלנו כמ\"ש המחבר ונראה ה\"ה אם עדיין לא גירש ונשאת אחר שחלץ היבם ג\"כ אין מוציאין ממנו וכן משמע ממגיד:","\u0003וי\"א דאפילו חזר ונשא וכו'\u0004. באמת לא מצינו דיעה זו והטור שכתב הרא\"ש חולק על הרמב\"ם בדין זה לא כתב אלא לפי גירסתו ברמב\"ם כמ\"ש בסעי' הקודם אבל בחזר ונשאה לא מצינו מי שס\"ל דמוציאים אותה אלא הת\"ה סימן רכ\"ב מדייק כן מלשון הגמ' ואין מוכרח והב\"י וב\"ח חולקין עליו ע\"ש:","\u0003ודווקא אם קידשה במזיד\u0004. אתחילת סימן קאי אם קידש בשוגג מותר' למקדש ומשמע מכל הפוסקים אף אם הוא כהן אסורה לו מ\"מ אין כופין אותו לחלוץ אף שקידש זה בשוגג ולא כמשמעות הנ\"י ומ\"ש בהג\"ה אם רוצה היבם ליבם ל\"ד אפילו אסורה לו נמי הברירה בידו ואם חלץ ומסר מודעא על החליצה כופין אותה לחלוץ ומותרת למקדש תשובת ריב\"ש ועיין ב\"ח מה שמדייק מהרא\"ש ליתא אדרבה שם מבואר להדיא לר\"ת דווקא בשוגג מותרת גם מ\"ש לדעת ר\"ת אפילו קידש במזיד מותרת למקדש אנ\"ל דהא ראיית ר\"ת מן א\"א שנתקדשה דמותרת למקדש ושם איירי באמרו לה עדים דמת בעלה והיינו שוגג וכשיבם מומר עיין סימן קנ\"ז:","\u0003תצא\u0004. הב\"י חולק על הת\"ה וכן ב\"ח וס\"ל דהוי שוגגת כשסמכה את עצמה על הקול וט\"ז פסק לחומרא:","\u0003נשאת לזר\u0004. אפי' לא בא עליה ב\"י וכ\"מ וד\"מ ודווקא בידוע שיש לה יבם אבל מחמת קול שיש לה יבם לא תצא תשובת ריב\"ש ועיין קס\"ט סעיף נ\"ה שם איירי שחלץ לה אלא שהיא חלוצה פסולה וצריכה לכתחל' חליצה מכל אחים בזה מקילין אם נשאת קודם חליצה שניה לא תצא דרישה ואם ב' אומרים דיש לה יבם וב' אומרים דאין לה יבם כתבו הב\"י וד\"מ בשם רי\"ו אם באו תרי והתירו ע\"פ ואח\"כ באו שנים והכחישו לראשוני' לא תצא דהוי תרי ותרי ולכאורה תמוה איך כתבו כן בפשיטות דהא בסימן י\"ז ומ\"ז וסימן קנ\"ב מבואר תרי ותרי אין חילוק בין התירו אותה ואחר כך באו עדים או באו עדים קודם לזה לעולם אם נשא' לאחר תצא אא\"כ באומר ברי ונישא' לא' מעידיה אז לעולם לא תצא אפילו לא התירוה עדיין דלית הלכתא כרבי מנחם דמחלק בין התירו' קודם שבאו עדים השני' כמ\"ש בהרא\"ש פרק האשה שנתארמלה אף אם יש לרי\"ו בשם הרמ\"ה שיטה אחרת בזה מ\"מ לא קי\"ל כוותיה:","\u0003אם הוא ישראל\u0004. אבל לכהן אסורה דהא היא חייבי לאוין לאחר ועיין סימן ז' /ו'/ שם נתבאר דינים הללו:","\u0003וי\"א\u0004. כ\"כ הנ\"י אף על גב דהיא מותרת ליבם מ\"מ לבועל אסורה לכאורה קשה הא בת שבע היתה א\"א והיתה מותרת לדוד מחמת שהית' מותר' לבעלה כי דוד בא עליה באונס כמ\"ש פ\"ק דכתובות וכמ\"ש בסימן י\"א לכאורה נראה מכאן נמי ראיי' למ\"ש שם דעיקר כתירוץ בתרא שם בכתובות דהית' מותרת לדוד מחמת גט כריתות ודוחק דבדוד לא היה שייך קנס או דאותו זמן לא נתחדש דין זה עדיין כל זה דוחק הוא גם עכ\"פ נשמע בזמן הזה המאנס אשת ישראל אסור' לו ובש\"ג דף תל\"ד כתב אף ליבם אסור':","\u0003ומותרת לבעלה\u0004. כ\"כ הטור והמחבר השמיט בכוונה ע\"פ מ\"ש בב\"ה דווקא לפי' הרא\"ש באשה בעלמא שנשאת לאחר דאסורה לבעלה הטעם שמא יאמרו גירש זו ונשאת לזה או י\"ל באשת אחיו מותרת לבעלה דהא כאן אף אם גירש בעלה אסורה לאחיו, אבל לשאר פוסקים דאסורה לבעלה מחמת קנס דלא דייקא א\"כ באשת אחיו אסורה לבעלה וכבר הארכתי בזה בסימן ט\"ו ע\"ש:","\u0003היבם אסור בקרובו' זקוקתו\u0004. דקי\"ל יש זיקה אפילו בשני יבמים ומ\"ש בהג\"ה אפילו ספק היינו המ' כתב בא' שמת הוא ובנו ביום א' וספק איזה מת תחלה ועמד א' וחלץ לאשתו מספק ורצה ליקח אחותה ואסר לו הדבר ושם היה עובדא דכבר חלץ לזקוקתו ובד\"מ כתב ע\"ז אפש' ה\"ה אם לא חלץ נמי הדין כן וע\"פ הדברי' האלה כתב כאן הג\"ה זו:","\u0003וי\"א דווקא וכו'\u0004. כ\"כ התוס' והרא\"ש והמ' אלא הנ\"י כתב רפ\"ב בשם האחרוני' דחולקים ע\"ז דלא מהני מעשה דידי' עד שיעשה אחיו מעשה ועיין ס\"ס קע\"ה:","\u0003חוזרת היבמה להתירה\u0004. ולא אמרינן הואיל שנאסרה שעה א' בשעה שהיתה זקוקה לו אסורה לו עולמית וכמ\"ש אם מתה הזקוקה דארוסה מותרת לו:"]],["יְבָמָה, שְׁלשָׁה חֳדָשִׁים \u0005(הָרִאשׁוֹנִים)\u0006, נִזּוֹנֶת מִשֶּׁל בַּעְלָהּ \u0010c0\u0011 וּמַעֲשֵׂה יָדֶיהָ לַיָּבָם; מִכָּאן וְאֵילָךְ \u0010c1\u0011 אֵינָהּ נִזּוֹנֶת לֹא מִשֶּׁל בַּעַל וְלֹא מִשֶּׁל יָבָם. \u0010c2\u0011 עָמַד בְּדִין \u0005 לְאַחַר שְׁלשָׁה חֳדָשִׁים \u0006 \u0005(רִיבָ\"שׁ סִימָן ק\"ד)\u0006 וּתְבַעְתּוֹ לְיַבֵּם אוֹ לַחֲלֹץ \u0005 לִפְנֵי \u0010c3\u0011 בֵּית דִּין, \u0006 וְנִתְרַצָּה לְיַבֵּם וְאֵרְעוֹ אֹנֶס, שֶׁחָלָה אוֹ שֶׁהֻצְרַךְ לִבְרֹחַ מֵחֲמַת מָמוֹן אוֹ מֵחֲמַת מְרָדִין, חַיָּב בִּמְזוֹנוֹתֶיהָ בְּלֹא שְׁבוּעָה:\nהִנִּיחָהּ מְעֻבֶּרֶת, הֲרֵי זוֹ נִזּוֹנֶת עַד שֶׁתֵּלֵד. יָלְדָה וָלָד שֶׁל קְיָמָא, הֲרֵי זוֹ נִזּוֹנֶת כָּל יְמֵי אַלְמְנוּתָהּ, כִּשְׁאָר כָּל הַנָּשִׁים:\nנָפְלָה לִפְנֵי יָבָם קָטָן, \u0010c4\u0011 אֵין לָהּ מְזוֹנוֹת עַד שֶׁיִּגְדַּל. \u0005 הַגָּה: יָלְדָה סְפֵק נֵפֶל, שֶׁדִּינָהּ לַחֲלֹץ וְלֹא לְהִתְיַבֵּם, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קנ\"ו, \u0010c5\u0011 נוֹטֶלֶת כְּתֻבָּתָהּ \u0006 \u0005 מִיָּד \u0006 \u0005(הג\"מ)\u0006. \u0005 יֵשׁ אוֹמְרִים הָא דְּאֵינָהּ נִזּוֹנֶת מִשֶּׁל יָבָם קָטָן, הַיְנוּ מִנְּכָסָיו, וַאֲפִלּוּ נְדוּנְיָא שֶׁהִכְנִיסָה לְבַעְלָהּ וְהֶחֱזִיק בָּהּ; אֲבָל לֹא הֶחֱזִיק בַּנְּדוּנְיָא שֶׁלָּהּ, כְּגוֹן שֶׁעֲדַיִן מֻנַּחַת בְּיַד שָׁלִישׁ, נִזּוֹנֶת מִנְּדוּנְיָתָהּ, כָּל שֶׁכֵּן בְּמָקוֹם שֶׁהִיא אוֹמֶרֶת שֶׁיִּתְּנוּ הַנְּכָסִים לְיָדָהּ וְהִיא רוֹצָה לְקַיֵּם הַקֶּרֶן עַד שֶׁיִּגְדַּל הַנַּעַר וְלִזּוֹן מִן הָרֶוַח, שֶׁנּוֹתְנִין הַמָּעוֹת לְיָדָהּ \u0006 \u0005(שָׁם בְּשֵׁם הָרִי\"ף)\u0006:\nמַעֲשֵׂה יָדֶיהָ שֶׁלָּהּ לְעוֹלָם, אֲפִלּוּ הִיא נִזֹּנֶת. \u0005 וְדַוְקָא לְאַחַר שְׁלשָׁה חֳדָשִׁים \u0006 \u0005(ד\"ע)\u0006:\nנָפְלוּ לָהּ נְכָסִים בְּעוֹדָהּ שׁוֹמֶרֶת יָבָם, \u0010c6\u0011 מוֹכֶרֶת וְנוֹתֶנֶת, וְקַיָּם, שֶׁאֵין לַיָּבָם בָּהֶם כְּלוּם עַד שֶׁיִּכְנֹס. וַאֲפִלּוּ עָשָׂה בָּהּ מַאֲמָר. וְהוּא הַדִּין אִם נִשְׁאֶרֶת אַלְמָנָה מִן הָאֵרוּסִין, וְנָפְלוּ לָהּ בְּעוֹדָהּ אֲרוּסָה, שֶׁמּוֹכֶרֶת וְנוֹתֶנֶת, \u0010c7\u0011 וְקַיָּם, דְּלֹא עָדִיף יָבָם מִבַּעַל: \u0010c8\u0011\nאֵין לַיָּבָם פֵּרוֹת בִּנִכְסֵי מְלוֹג שֶׁל שׁוֹמֶרֶת יָבָם. וּבְנִכְסֵי צֹאן בַּרְזֶל שֶׁהִכְנִיסָה לְאָחִיו, אֵין לוֹ בְּפֵרוֹתֵיהֶם אֶלָּא מֶחֱצָה. וְיֵשׁ מִי שֶׁכָּתַב, שֶׁגַּם בָּהֶם אֵין לוֹ פֵּרוֹת כְּלָל, עַד שֶׁיִּכְנֹס. \u0005 הַגָּה: וְהָרִאשׁוֹן עִקָּר. וְיֵשׁ אוֹמְרִים דַּאֲפִלּו נִכְסֵי מְלוֹג שֶׁנָּפְלוּ לָהּ בְּעוֹדָהּ תַּחַת בַּעְלָהּ דִּינָן כְּנִכְסֵי צֹאן בַּרְזֶל, וְיַחֲלֹקוּ בַּפֵּרוֹת \u0006 \u0005(הָרַמְבַּ\"ן וְהָרַ\"ן פֶּרֶק הָאִשָּׁה)\u0006. \u0005 וְכֵן יַחֲלֹקוּ בִּירֻשָּׁתָהּ, אִם מֵתָה. וּבְמָקוֹם שֶׁהַפֵּרוֹת שֶׁלָּהּ, כָּךְ יְכוֹלָה לִמְכֹּר בַּקַּרְקַע כְּפִי חֶלְקָהּ \u0010c9\u0011 בַּפֵּרוֹת: \u0006\nמֵתָה כְּשֶׁהִיא שׁוֹמֶרֶת יָבָם, יוֹרְשֶׁיהָ יוֹרְשִׁין נִכְסֵי מְלוֹג שֶׁלָּהּ וַחֲצִי נִכְסֵי צֹאן בַּרְזֶל. \u0005 וְכֵן אִם נָתַן לָהּ הַיָּבָם \u0006 \u0005 מַתָּנָה, יוֹרְשֶׁיהָ יוֹרְשִׁין אוֹתָהּ \u0006 \u0005(מַהֲרַ\"ם פַּדָּוואָה סִימָן י\"ז)\u0006. וְיוֹרְשֵׁי הַבַּעַל יוֹרְשִׁים עִקַּר כְּתֻבָּה וְתוֹסֶפֶת וַחֲצִי נִכְסֵי צֹאן בַּרְזֶל, וְיוֹרְשֵׁי הַבַּעַל חַיָּבִים בִּקְבוּרָתָהּ. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּכָל נִכְסֵי צֹאן בַּרְזֶל שֶׁלָּהּ הֵם בְּחֶזְקַת יוֹרְשֵׁי הַבַּעַל, כְּמוֹ הַכְּתֻבָּה \u0006 \u0005(ר\"ת וְהָרֹא\"שׁ)\u0006, \u0005 וְאֵין מוֹצִיאִין מִיָּדָם אִם הֵם מֻחְזָקִים \u0006 \u0005(כ\"כ הָרַ\"ן בִּתְשׁוּבָה)\u0006. \u0010c10\u0011 \u0005 וְכָל זֶה בְּמָקוֹם וּבִזְמַן שֶׁאֵין כּוֹפִין לַחֲלֹץ, אֲבָל בְּמָקוֹם וּבִזְמַן שֶׁכּוֹפִין לַחֲלֹץ, אִם כֵּן לֹא הָיְתָה רְאוּיָה לְהִתְיַבֵּם, יֵשׁ אוֹמְרִים דְּאֵין הַנְּכָסִים בְּחֶזְקַת יָבָם, וּלְכָךְ אִם מֵתָה אֵינָהּ יוֹרְשָׁהּ; וּלְכָךְ, בִּמְדִינוֹת שֶׁכּוֹפִין לַחֲלֹץ, אֵינוֹ יוֹרְשָׁהּ \u0006 \u0005 לְדַעַת זֶה \u0006 \u0005(מהרי\"ק שֹׁרֶשׁ צ\"א)\u0006. \u0005 וּלְעִנְיַן מִי נִקְרָא יוֹרְשֵׁי הַבַּעַל, \u0010c11\u0011 צָרִיךְ עִיּוּן, כִּי יֵשׁ אוֹמְרִים שֶׁהַיָּבָם הוּא \u0006 \u0005 יוֹרֵשׁ אַף עַל גַּב דַּאֲבִיהֶם עֲדַיִן חַי, וְהוּא קוֹדֵם בִּירֻשַּׁת הַבַּעַל לְכָל יוֹצְאֵי יְרֵכוֹ \u0006 \u0005(מהרי\"ו סִימָן מ\"א וְהָרַ\"ן פֶּרֶק הָאִשָּׁה וּמַהֲרַ\"ם פַּדָּוואָה סִימָן י\"ז)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּהָאָב יוֹרֵשׁ, דְּמִיָּד שֶׁמֵּתָה הַיְבָמָה פָּקְעָה זִקַּת יְבָמִים, וְנָפְלָה הַיְרֻשָּׁה לִפְנֵי הַקּוֹדֵם בִּירֻשַּׁת הַבַּעַל \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ צ\"א)\u0006. \u0005 וְאַף עַל פִּי שֶׁהַסְּבָרָא נוֹתֶנֶת כַּסְּבָרָא הָאַחֲרוֹנָה, וְכֵן מַשְׁמַע קְצָת לְשׁוֹן \"יוֹרְשֵׁי הַבַּעַל\", אֲבָל סוּגְיַת הַגְּמָרָא וְהַיְרוּשַׁלְמִי פֶּרֶק הָאִשָּׁה שֶׁנָּפְלוּ מַשְׁמַע שֶׁהַיָּבָם יוֹרֵשׁ הַשּׁוֹמֶרֶת יָבָם, וְאִם כֵּן אֵין לָאָב חֵלֶק בִּירֻשָּׁתָהּ, וְכַסְּבָרָא הָרִאשׁוֹנָה. וְאִם הַיְבָמִים רַבִּים, עַיֵּן לְקַמָּן סִי' קס\"ה: \u0006\nרְאוּבֵן שֶׁמֵּת, וְלוֹ שְׁתֵּי נָשִׁים וְנִשְׁאֲרוּ זְקוּקוֹת לְיָבָם, וּמֵתָה אַחַת מֵהֶן, \u0010c12\u0011 אֵין לַיָּבָם שׁוּם טַעֲנָה בַּנְּכָסִים, לְפִי שֶׁהַשְּׁנִיָּה בְּפָנָיו. \u0005 הַגָּה: סְפֵק שׁוֹמֶרֶת יָבָם שֶׁמֵּתָה, אֵין יוֹרְשֵׁי הַבַּעַל יוֹרְשִׁין אוֹתָהּ, דְּהֵם סָפֵק וְיוֹרְשֶׁיהָ וַדַּאי \u0006 \u0005(ב\"י בְּשֵׁם הָרַשְׁבַּ\"ץ)\u0006, \u0005 וְאֵין סָפֵק מוֹצִיא מִידֵי וַדַּאי כְּדִלְקַמָּן סִימָן קס\"ג: \u0006",[],["\u0003ומ\"י ליבם\u0004. הטעם בג\"ח הראשוני' דינה כאלמנה ניזונת מיתומים דמ\"י ליתומים אבל לאחר ג\"ח דניזונת מיבם מחמת קנס אם תבעתו ליבם כמ\"ש בתוס' והרא\"ש אז אין מ\"י ליבם:","\u0003אינה ניזונת\u0004. ול\"ד לשאר אלמנה כל זמן שלא נשאת הוא כבוד לבעלה דאינה נשאת לאחר מחמת כבוד בעלה משא\"כ ש\"י דאגודה ביבם רש\"י:","\u0003עמד בדין אחר ג\"ח\u0004. משמע אם תבעו לדין תוך ג\"ח ונתרצה לייבם ונתעכב פה אחר ג\"ח ואחר כך ברח או חלה אין חייב במזונות ואין מוכרח בתשו' ריב\"ש אלא י\"ל דאיירי דברח מיד מ\"ה אין חיוב עליו כיון דא\"א לו לייבם תוך ג\"ח:","\u0003ונתרצה לייבם\u0004. כ\"כ התוס' והרא\"ש כיון דנתרצה ליבום הוי כאלו היא אשתו אבל אם נתרצה לחלוץ הוי /או/ שלא נתרצה כלל אין לה מזונות אף על גב דהטע' הוא משום דקנסו אותו ליתן לה מזונות מ\"מ דווקא כשמתרצה לייבם אז מחייב ליתן לה מזונות וכן מבואר בהרא\"ש דוקא כשמתרצה ליבם ומטעם קנס דהיה לו לייבם מיד אבל לדעת הרמב\"ם אפילו לא התרצה ליבום חייב במזונות וכ\"פ בתשובת ריב\"ש הנ\"ל ואם בורח במזיד י\"ל לכ\"ע חייב במזונות אפי' לא התרצה לייבם ואם לא ברח אלא נתעכב פה אין חייב במזונות אא\"כ שתבעו ליבם או ליתן לה מזונות ונתרצה ליבם, הרא\"ש:","\u0003אין לה מזונות\u0004. היינו אחר ג\"ח אבל ג\"ח הראשוני' יש לה מזונות מבעלה ועיין הג\"מ סוף כתובות:","\u0003נוטלת כתובתה מיד\u0004. אף על גב דאסורה להנשא מ\"מ נוטלת כתובה כמו נטבע במים שאל\"ס דאזלינן בתר הרוב דרוב נשי ילדו ולד מעליא:","\u0003מוכרת וכו'\u0004. היינו דלא הכניסה לו בתורת נצ\"ב דאם הכניסה לו מבואר אח\"כ:","\u0003דלא עדיף יבם מבעל\u0004. היינו אם מכרה דמכירתה קיימת בזה כתב דלא עדיף דהא בארוסה גם כן קיימת מכירתה אבל בענין שזו מוכרת לכתחלה גרע היבם מבעל:","\u0003אין ליבם פירות\u0004. משמע אפי' אם נפלו תחת הבעל אין לו פירות כיון דאינו חייב בפרקונ' ומ\"ש נצ\"ב שהכניס' לאחיו ל\"ד אלא מה שהכניסה ליבם בתורת נצ\"ב אוכל הפירות כמו היורש ועיין בטור:","\u0003מתה כשהיא ש\"י\u0004. עיין בש\"ס לפי אוקמת' דרבא דקי\"ל כוותי' איירי כל מתניתין דנפלו לה בעודה ש\"י וס\"ל לרמב\"ם אף אם נפלו לה בעת שהיתה נשואה לאחיו הדין כן ואין חילוק בדבר לעולם יורשי' יורשין נ\"מ ונצ\"ב חולקין ולשיטות הגאונים נצ\"ב לעולם שייך ליבם אפילו אם נפלו בעודה ש\"י והכניס' לו בתורת נצ\"ב ונ\"מ שנפלו לה בעוד' ש\"י יורשיה יורשין ואם נפלו תחת בעלה יורש היבם הכל וי\"א נצ\"ב כמ\"ש ונ\"מ שנפלו תחת הבעל יחלקו היבם ויורשי' ואם נפלו כשהיא ש\"י יורשי' יורשין והרב רמ\"א הביא בנ\"מ שני דעות והשמיט דעת הגאונים דשייכי לגמרי ליורשי הבעל ואפשר ס\"ל אפילו אם יורשי הבעל מוחזקים לא שייך לומר קים לי כהאי דשייך להם כיון דמוחזק למשפחתו, כמ\"ש בש\"ס לתירוץ עולא ורבה דזיקה כספק נשואה ולב\"ה שייך ליורשיה משום דמוחזק למשפחת' ומשמע דל\"ש אם הם מוחזקים או יורשי הבעל מוחזקים וכן משמע מתשובת הר\"ן שהביא הב\"י, מיהו לענין מחצה דשייך ליורשי הבעל הביא דעת הפוסקים אלו כי בזה י\"ל קים לי כהאי כי רוב פוסקי' חולקים על רמב\"ם דפוסק דשייך הכל ליורשי האשה ונצ\"ב לכ\"ע שייך ליורשי הבעל החצי וי\"א דשייך לגמרי לבעל, ובפירות כשהיא חי פליגי י\"א הפירות הוי כאלו נפל עכשיו זהו דעת הרמב\"ם ובעל המאור אפילו פירות נצ\"ב שנפלו תחת בעלה שייך לה וי\"א פירות נצ\"ב דינם כקרקע, אלא פירות נ\"מ אפילו נפלו תחת בעלה שייכים לה הואיל הוא אין חייב בפרקונה ורוב פוסקים ס\"ל אפילו פירות נ\"מ שייכים לו החצי שהוא עומד במקום הבעל אף על פי שאינו חייב בפרקונ' ומשמע שלוקח הפירות מיד אבל הרמב\"ן במלחמות ה' כתב דאין לוקח מיד הפירות והיא ג\"כ א\"י למוכרם אלא כשיכניס אותה אז לוקח הפירות, ועיין בר\"ן פ' האשה שנפלו מ\"ש בשם הרשב\"א ועיין בדרישה ועיין סימן קס\"ו ואפשר מ\"ש הרמב\"ם פכ\"ב מה\"א ואין ליבם פירות עד שיכניס כוונתו כמ\"ש הרמב\"ן אבל אחר שכונס יש לו הפירות ודין פירות כדין קרקע מה שיורש אלא כל הפוסקים לא פירשו כן דברי הרמב\"ם:","\u0003וכל זה במקום ובזמן וכו'\u0004. כ\"כ במהרי\"ק שורש צ\"א מיהו בשורש ק\"ב לא משמע כן אלא אף על גב דקי\"ל מצות חליצה קודמת לענין איסור מ\"מ ממונו לא מפקיעין ממנו ועיין תשובת מהר\"י לבית הלוי כלל ג' סימן י\"ט באריכות שפוסק דיורש אף למנהג דכופין לחלוץ ומיישב שם דברי מהרי\"ק בשני תשו' הנ\"ל וכ\"פ בתשו' מהרשד\"ם ועיין תשו' ש\"י סימן נ' ועס\"ס קס\"ה ולכאורה קשה ל\"ל הטעם הואיל וכופין ת\"ל אף במקום שאין כופין מ\"מ למ\"ד מ\"ח קודמת אז אין יורש אותה כמ\"ש לקמן סימן קס\"ה בהגהות למ\"ד מ\"ח קודם אף שאין כופין צריך ליתן לה כתובה מיד והוי כאלו כבר חלץ לה, ועוד קשה אף במקום שאין כופין מ\"מ לפי מנהג הקהילות שהביא בסימן הנ\"ל אינו נוטל מעזבון כלום לפי דעת האחרונים שהבאתי שם א\"כ למה יורש אותה ואין יורש את אחיו למ\"ש בסימן קס\"ג דרמ\"א לא ס\"ל כוותי' בזה שפיר עיין שם מ\"ש:","\u0003כי י\"א היבם הוא היורש\u0004. כ\"כ רש\"י פ' החולץ וכ\"כ בש\"ג פ' האשה שנפלו וכ\"כ בתשו' מהר\"י הנ\"ל ותשו' ש\"י הנ\"ל ועיין תשו' מהר\"א בן ששון סימן קצ\"ה שכתב בשם תשובת מהרי\"ו סימן מ\"א דאין האב יורש כלום וכל עזבון של המת יורשים האחים ואם יש כאן ב' אחים אף שא' בכור מ\"מ יד שניהם שוים אפילו בכתובה שלה מאחר שלא עשה שום מעש' ועיין בר\"ן פ' האשה שנפלו בסוגיא ההוא גברא דנפל ליה יבמה בפומבדיתא ועיין בד\"מ ועיין ס\"ס קס\"ה שם כתבתי לפי תיקון הקהילו' המבואר שם ליתא הדין של מהרי\"ו והמשך הגהות זו ה\"פ אף לדינא דש\"ס דאיתא פלוגתא מי היורש של יבמה שמתה אם האשה יורש או האחים ומשמע בש\"ס האחים יורשים כמ\"ש בתשו' מהרי\"ו דמדייק מש\"ס כן ובמקום שכופין לחלוץ אז אין האב והאחים יורשים אלא יורשיה:","\u0003אין ליבם שום טענה\u0004. ול\"ד לדין שכתבתי לעיל דכופין לחלוץ ומ\"מ יורש ממונה משום דשם אף על גב דמונעי' אותו ליבם משום איסור מ\"מ לענין ממון אוקמא אדין משא\"כ כאן דא\"א ליבם ואם מתו גם שניהם מ\"מ יורש השני' ולא הראשונה ואם א\"י איזה מתה ראשונה נראה דדומה למ\"ש בסמוך דהוי היורשים ודאי והיבם ספק:"]],["מִי שֶׁהָיוּ לוֹ נָשִׁים רַבּוֹת, וּמֵת, וְלוֹ אָח, בִּיאָתָהּ אוֹ חֲלִיצָתָהּ שֶׁל אַחַת מֵהֶם פּוֹטֶרֶת כֻּלָּן, וְאֵין הַיָּבָם יָכוֹל \u0010c0\u0011 לְיַבֵּם אֶלָּא אַחַת מֵהֶן:\nהָיוּ בָּהֶן פְּסוּלוֹת לִכְהֻנָּה, אִם בָּא לַחֲלֹץ אֵינוֹ חוֹלֵץ \u0010c1\u0011 אֶלָּא לַפְּסוּלָה וְלֹא לַכְּשֵׁרָה:\nהָיוּ לוֹ אַחִים רַבִּים, וְנָפְלוּ נְשׁוֹתָיו לִפְנֵיהֶם, אֶחָד מְיַבֵּם אוֹ חוֹלֵץ לְאַחַת מֵהַיְבָמוֹת, וְהֻתְּרוּ שְׁאָר הַצָּרוֹת:\nמִצְוָה עַל הַגָּדוֹל לְיַבֵּם \u0005 אוֹ \u0010c2\u0011 לַחֲלֹץ. \u0006 לֹא רָצָה \u0005 אוֹ שֶׁאִי אֶפְשָׁר לוֹ לַחֲלֹץ אוֹ לְיַבֵּם כְּגוֹן שֶׁהָיָה נָשׂוּי אֲחוֹתָהּ \u0006 \u0005(רִיבָ\"שׁ סִי' קנ\"ט)\u0006, חוֹזְרִין עַל כָּל הָאַחִים זֶה אַחַר זֶה \u0010c3\u0011 דֶּרֶךְ גְּדִילָתָן. לֹא רָצָה, חוֹזְרִים אֵצֶל הַגָּדוֹל וְאוֹמְרִים לוֹ: עָלֶיךָ הַמִּצְוָה, אוֹ חֲלֹץ אוֹ יַבֵּם. לֹא רָצָה לֹא לַחֲלֹץ וְלֹא לְיַבֵּם, כּוֹפִין אוֹתוֹ \u0010c4\u0011 לַחֲלֹץ וְאֵין כּוֹפִין אוֹתוֹ לְיַבֵּם. \u0005 הַגָּה: וַאֲפִלּוּ אִם נִשְׁבַּע הַגָּדוֹל שֶׁלֹּא לְיַבֵּם וְלֹא לַחֲלֹץ, כּוֹפִין אוֹתוֹ וְלֹא לַקָּטָן. וּמִכָּל מָקוֹם מַתִּירִין הַשְּׁבוּעָה לַגָּדוֹל, אַף עַל פִּי שֶׁאֵינָהּ חָלָה, מִשּׁוּם מַרְאִית הָעַיִן \u0006 \u0005(שָׁם בָּרִיבָ\"שׁ)\u0006:\nאָמַר הַגָּדוֹל: הַמְתִּינוּ עַד שֶׁיַּגְדִּיל אָחִי הַקָּטָן, אוֹ שֶׁהָיָה אָחִיו חֵרֵשׁ וְאָמַר: הַמְתִּינוּ עַד שֶׁיַּבְרִיא, אוֹ שֶׁהָיָה אָחִיו גָּדוֹל מִמֶּנּוּ \u0010c5\u0011 בִּמְדִינַת הַיָּם וְאָמַר: הַמְתִּינוּ עַד שֶׁיָּבֹא, אֵין שׁוֹמְעִין לוֹ:\nלֹא רָצָה הַגָּדוֹל לְיַבֵּם אֶלָּא לַחֲלֹץ, וְהַקָּטָן מִמֶּנּוּ רוֹצֶה לְיַבֵּם, בִּיאַת קָטָן עֲדִיפָא. אֲבָל אִם אֵין שְׁנֵיהֶם רוֹצִים לְיַבֵּם, אֶלָּא \u0010c6\u0011 לַחֲלֹץ, חֲלִיצַת הַגָּדוֹל עֲדִיפָא. \u0005 הַגָּה: וְעַיֵּן לְקַמָּן סִימָן קס\"ה דְּבַזְּמַן הַזֶּה מִצְוַת חֲלִיצָה קוֹדֶמֶת. וַאֲפִלּוּ לְמַאן דְּאָמַר יִבּוּם קוֹדֵם, אִם הִיא אֵינָהּ חֲפֵצָה בְּיִבּוּם רַק בַּחֲלִיצָה, חֲלִיצַת הַגָּדוֹל קוֹדֵם \u0006 \u0005(תה\"ד סִימָן ר\"כ)\u0006:\nאַף עַל פִּי שֶׁמִּצְוָה בַּגָּדוֹל לְיַבֵּם, אִם קָדַם הַקָּטָן וְיִבֵּם זָכָה. \u0005 הַגָּה: וְהוּא הַדִּין אִם חָלַץ לָהּ הַקָּטָן, מְהַנֵּי בְּדִיעֲבַד \u0006 \u0005(עַיֵּן שָׁם)\u0006. \u0005 אֲבָל לְכַתְּחִלָּה צְרִיכָה לְהַדֵּר אַחַר הַגָּדוֹל, וְלָתֵת לוֹ חֶלְקוֹ בַּמָּמוֹן, כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סִי' קס\"ה: \u0006\nהָיוּ לוֹ אַרְבָּעָה אַחִים, וּמֵתוּ, וְנָפְלוּ נְשׁוֹתֵיהֶם לְפָנָיו, אִם הוּא עָשִׁיר וְיָכוֹל לְזוּנָן, אִם יִרְצֶה לְיַבֵּם אֶת כֻּלָּם, מְיַבֵּם; וְאִם לָאו, חוֹלֵץ לְמִי שֶׁיִּרְצֶה מֵהֶן, וּמְיַבֵּם לְמִי שֶׁיִּרְצֶה מֵהֶן, אַחַת מִכָּל בַּיִת:\nיְבָמָה שֶׁנִּשְׁאֲרָה זְקוּקָה לִשְׁנֵי אַחִים, וְהַגָּדוֹל הוּא מֵאֲנוּסֵי הַזְּמַן, וְהַשֵּׁנִי יְהוּדִי, הַיְּהוּדִי קוֹדֵם לַחֲלֹץ. וְאִם קָדַם הָאַחֵר וְחָלַץ, הֻתְּרָה לַשּׁוּק. \u0005 וְעַיֵּן לְעֵיל סִימָן קנ\"ז סָעִיף ד': \u0006",[],["\u0003אלא אחת מהם\u0004. ואם חולץ לאחת לדעת הב\"י אין איסור לחלוץ לשניה אלא שא\"צ חליצה וב\"ח כתב דאיכא א\"ד לחלוץ לשניה דכתיב בית חלוץ הנעל בית א' הוא חולץ ולא ב' בתים ודייק כן מתוס' וליתא אלא כוונ' תוספות כיון דאין עולה לחליצה כלומר דא\"צ חליצה אין עולה ליבום היינו אסורה ליבם דהוי אשת אח שלא במקום מצוה ואישתמט' ליה הסוגיא ר\"פ ר\"ג האי חליצה פסולה אין אחרי' כלום מאי לגזור לגזר חליצה אחר גט אטו חליצה אחר חליצה כל כי הני תחלוץ ותיזיל ועיין סימן קס\"ז ובדרישה כתב לכתחלה אינו רשאי לחלוץ אלא לא' מהם שלא תאסר על כהן וכתב ב\"ח אם חלץ אף לשניה אסורה לכהונה מפני מראית עין שיאמרו שכנס חליצה:","\u0003אלא לפסול'\u0004. וכופין אותו לחלוץ לפסול' ואם עובר מנדין אותו ואם התרו למלקות מלקין אותו רי\"ו ד\"מ:","\u0003לא רצה\u0004. היינו שלא רצה ליבם ורוצ' לחלוץ מ\"מ חוזרים ע\"כ אחים שמא מייבם השני ויבום קטן עדיף וכן מוכח בש\"ס במקשן מאי לאו לא רצה לייבם אלא לחלוץ למ\"ד יבום קטן עדיף כן הוא האמת וכ\"כ הרמב\"ם לא רצה לייבם מחזירים וכולי וכ\"כ בנ\"י ולא כב\"ח:","\u0003דרך גדילתן\u0004. כ\"כ תוס' ושאר פוסקים ולא כרמב\"ם פ\"ב דס\"ל אחר שלא רצה הגדול הרי כולם שוים, ומבואר בהשגו' למ\"ד דהוי מורדת אם לא רצה לייבם אף בכה\"ג דגדול אין רוצה לייבם והשני רוצה והיא ממאנת בו ורוצה בשלישי היא מורדת וכן הוא דעת הרשב\"א כמ\"ש בהמגיד שם:","\u0003ואין כופין אותו\u0004. אפי' למ\"ד מצות יבום קודם אין כופין דאין אדם דר עם נחש בכפיפה:","\u0003במדינות הים\u0004. ה\"ה במדינה אחרת כל שחלוקה בלשון אחרת כמ\"ש לעיל סימן פ\"ה לאפוקי אם הוא במדינה זו ממתינים עליו עיין ב\"ח בסדר חליצה מעשה היה שהיתה היבמה עם יבם קטן בפריז והיבם גדול ס' מיל רחוק מפריז אפ\"ה כפה מהרי\"ץ מינץ את יבם קטן מזה ראייה דלאו בהרחקת הדרך תלוי מלתא אלא אם היבם בעיר אחרת והיבמ' עניה אין לה להשכיר שליח לשם להודיע ט\"ז:","\u0003חליצת הגדול עדיפא\u0004. מ\"מ אין כופין לגדול מאחר דהקטן רוצה לחלוץ רי\"ו בשם הרמ\"ה והטור לא כתב דכופין לגדול ואם לגדול אשה אז חליצת הקטן עדיף ועיין ב\"י סימן קס\"ה מ\"ש בשם הריטב\"א:"]],["הַכּוֹנֵס אֶת יְבִמְתּוֹ, נֶאֶסְרוּ צָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִים, \u0010c0\u0011 בַּעֲשֵׂה:\nהַחוֹלֵץ לִיבִמְתּוֹ, נֶאֶסְרָה הַחֲלוּצָה וְצָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִים, \u0010c1\u0011 בַּעֲשֵׂה:\nהַחוֹלֵץ לִיבִמְתּוֹ, אָסוּר מִדְּרַבָּנָן בִּקְרוֹבוֹתֶיהָ, אֲפִלּוּ בִּשְׁנִיּוֹת. וְכֵן הִיא אֲסוּרָה בִּקְרוֹבָיו. אֲבָל הָאַחִים מֻתָּרִים בְּכָל קְרוֹבוֹתֶיהָ. \u0005 וַאֲפִלּוּ לֹא חָלַץ לָהּ אֶלָּא \u0006 \u0005 מִסָּפֵק, אֲפִלּוּ הָכִי אָסוּר בְּכָל קְרוֹבוֹתֶיהָ \u0006 \u0005(מָרְדְּכַי רֵישׁ הַחוֹלֵץ)\u0006:\nמֻתָּר אָדָם לִשָּׂא אֲחוֹת צָרַת חֲלוּצָתוֹ וּשְׁאָר קְרוֹבוֹתֶיהָ: \u0010c2\u0011\nאָסוּר לִשָּׂא צָרַת קְרוֹבַת חֲלוּצָתוֹ:",[],["\u0003בעשה\u0004. כן הוא דעת רש\"י והרמב\"ם והעשה היא דכתיב אשר לא יבנה בית וילפינן בית א' הוא בונה ולא ב' בתים הוי לאו הבא מכלל עשה ולדעת התוס' עובר לאו אשר לא יבנה:","\u0003בעשה\u0004. לדעת תוס' עובר בלאו וכן מונה הרמב\"ן בכלל לאוין, ומ\"ש הטור והמחבר בעשה לכאורה תמוה איזה עשה הוא כי לא מצינו שום עשה בזה ולדעת הרמב\"ם אם חלץ א' מהן תו ליתא איסור דאוריית' בכולם רק מדרבנן אסורה ועיין במגיד:","\u0003אסור לישא צרת קרובת חלוצתו\u0004. שעשאו חכמים חלוצתו כגרושתו דאסורה אחותה, ואם אחותה נשאה לאחיו אז היא אסורה אף על גב דהיא אינה אסורה אלא מדרבנן אבל אם נשאה לאחר אז הצרה מותרת כן הוא לדעת תוס' והרא\"ש והנ\"י בשם הריטב\"א וכ\"כ בש\"ג:"]],["הַמְיַבֵּם אֶת יְבִמְתּוֹ, זוֹכֶה בִּנִכְסֵי הַמֵּת וְעוֹמֵד בִּמְקוֹמוֹ לִטֹּל חֶלְקוֹ בִּנִכְסֵי אֲבִיהֶם. \u0005 וַאֲפִלּוּ גֵּרְשָׁהּ אַחַר כָּךְ מִיָּד \u0006 \u0005(נ\"י פֶּרֶק הַחוֹלֵץ)\u0006, \u0005 וּבִלְבַד שֶׁהָיְתָה רְאוּיָה לוֹ לַיָּבָם. \u0006 וְדַוְקָא בַּמֻּחְזָק, כְּגוֹן שֶׁמֵּת אֲבִיהֶם וְאַחַר כָּךְ מֵת אָחִיו קֹדֶם שֶׁחָלְקוּ; אֲבָל לֹא בָּרָאוּי, כְּגוֹן אִם מֵת אָחִיו וְאַחַר כָּךְ אֲבִיהֶם. וַאֲפִלּוּ בַּמֻּחְזָק, אֵינוֹ נוֹטֵל אֶלָּא בְּגוּף הַנְּכָסִים, \u0010c0\u0011 אֲבָל אִם הִשְׁבִּיחוּ הַנְּכָסִים, אֵינוֹ נוֹטֵל חֵלֶק אָחִיו בְּאוֹתוֹ שֶׁבַח, אֲפִלּוּ אִם שִׁבְּחוֹ אַחַר יִבּוּם, קֹדֶם חֲלֻקָּה. \u0005 הַגָּה: \u0010c1\u0011 יֵשׁ אוֹמְרִים דְּכֹל שֶׁמִּקְּרֵי רָאוּי גַּבֵּי בְּכוֹר, מִקְּרֵי גַּם כֵּן רָאוּי אֵצֶל יָבָם \u0006 \u0005(רִיבָ\"שׁ ס' ת\"ע)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּיָבָם נוֹטֵל בְּמִלְוֶה וּבִשְׁאָר רָאוּי, רַק שֶׁאֵינוֹ נוֹטֵל בָּרָאוּי שֶׁל אָבִיו, אִם מֵת אַחַר אָחִיו \u0006 \u0005(מהרי\"ו סִי' מ\"א)\u0006; \u0005 וְהַסְּבָרָא רִאשׁוֹנָה נִרְאֶה עִקָּר: \u0006\nהַחוֹלֵץ לִיבִמְתּוֹ, הֲרֵי הוּא כְּאֶחָד מִשְּׁאָר הָאַחִים לַנַּחֲלָה. וְאִם הָאָב קַיָּם, הוּא יוֹרֵשׁ הַכֹּל; וְאִם מֵת, יַחֲלֹקוּ הָאַחִים בֵּינֵיהֶם. \u0005 הַגָּה: וַאֲפִלּוּ רָצָה לְיַבֵּם, אֶלָּא שֶׁהִיא לֹא רָצְתָה, וְחָלַץ לָהּ, אֵין לוֹ בַּנְּכָסִים רַק כִּשְׁאָר יוֹרֵשׁ \u0006 \u0005(ת\"ה \u0010c2\u0011 סִימָן ר\"כ)\u0006. \u0005 וַאֲפִלּוּ קֹדֶם שֶׁחָלַץ, אִם תָּפַס הָאָב וְאָמַר: קִים לִי כְּמַאן דְּאָמַר מִצְוַת חֲלִיצָה קֹדֶם וְעַל כָּרְחָן שֶׁל אַחִים יִצְטָרְכוּ לַחֲלֹץ, אֵין מוֹצִיאִין הַנְּכָסִים מִיָּדוֹ \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ ע\"ג וצ\"א)\u0006. \u0005 וְכָל זֶה מִדִּינָא, אֲבָל כְּבָר יֵשׁ תַּקָּנָה שֶׁהַחוֹלֵץ יֵשׁ לוֹ חֲצִי הַנְּכָסִים, וְעַיֵּן לְקַמָּן סִי' קס\"ה: \u0006\nיִבֵּם הַיָּבָם בְּתוֹךְ שְׁלשָׁה חֳדָשִׁים, וְיָלְדָה לְסוֹף תִּשְׁעָה חֳדָשִׁים, סָפֵק אִם הוּא בֶּן תִּשְׁעָה חֳדָשִׁים לָרִאשׁוֹן, אוֹ בֶּן שִׁבְעָה לַשֵּׁנִי, וְתוֹבֵעַ הַסָפֵק נִכְסֵי הַמֵּת, שֶׁאוֹמֵר שֶׁהוּא בְּנוֹ; וְהַיָּבָם אוֹמֵר: אֲנִי יוֹרְשׁוֹ כִּי אַתָּה בְּנִי, \u0010c3\u0011 יְחַלְּקוּ הַיָּבָם וְהַסָפֵק בֵּינֵיהֶם; אֲפִלּוּ אִם אֶחָד מֵהֶם מֻחְזָק, אֵין חוֹשְׁשִׁין לְחֶזְקָתוֹ. וְאִם מֵת הַסָפֵק קֹדֶם חֲלֻקָּה, יְחַלְּקוּ הַזָּקֵן וְהַיָּבָם. \u0010c4\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵין אֲבִי הַמֵּת קַיָּם, יִטֹּל הַיָּבָם הַכֹּל:\nסָפֵק וּבְנֵי יָבָם שֶׁבָּאוּ לַחֲלֹק בְּנִכְסֵי הַמֵּת, הוּא אוֹמֵר: אֲנִי בֶּן הַמֵּת וְאֶטֹּל הַכֹּל, וְהֵם אוֹמְרִים: אָחִינוּ אַתָּה וְאֵין לְךָ חֵלֶק אֶלָּא כְּאֶחָד מִמֶּנּוּ, \u0010c5\u0011 הַחֵלֶק שֶׁהֵם מוֹדִים לוֹ יִטֹּל, וְהַשְּׁאָר יַחֲלֹקוּ וְיִטֹּל הוּא חֲצִי וְהֵם חֲצִי. \u0010c6\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁכָּל הַנְּכָסִים חוֹלְקִים בְּשָׁוֶה, הוּא מֶחֱצָה וְהֵם מֶחֱצָה:\nסָפֵק וּבְנֵי יָבָם שֶׁבָּאוּ לַחֲלֹק בְּנִכְסֵי יָבָם, לְאַחַר שֶׁחָלַק הַיָּבָם בְּנִכְסֵי הַמֵּת, וְאוֹמֵר הַסָפֵק: אִם אֲחִיכֶם אֲנִי תְּנוּ לִי חֵלֶק וּמַה שֶּׁלָּקַחְתִּי מִנִּכְסֵי הַמֵּת עִם אֲבִיכֶם אֲחַזִיר וְנַחֲ הַכֹּל, וְאִם אֵינִי אֲחִיכֶם תַּחְזְרוּ לִי נִכְסֵי אָבִי שֶׁלָּקַח אֲבִיכֶם, \u0010c7\u0011 אֵין חוֹשְׁשִׁין לִדְבָרָיו:\nסָפֵק וְהַיָּבָם שֶׁבָּאוּ לַחֲלֹק בִּנִכְסֵי הַזָּקֵן, וְאוֹמֵר הַסָפֵק: אֲנִי בֶּן הַמֵּת וְיֵשׁ לִי לִטֹּל הַחֲצִי, \u0010c8\u0011 אֵין שׁוֹמְעִין לוֹ:\nסָפֵק וּבְנֵי יָבָם שֶׁבָּאוּ לַחֲלֹק בִּנִכְסֵי הַזָּקֵן, וְאוֹמֵר הַסָפֵק: אֲנִי בֶּן הַמֵּת וְיֵשׁ לִי לִטֹּל הַחֲצִי, וְהֵם אוֹמְרִים: אַתָּה אָחִינוּ וְאֵין לְךָ אֶלָּא הַשְּׁלִישׁ, הַחֲצִי שֶׁהוּא מוֹדֶה לָהֶם יִטְּלוּ, וְהַשְּׁלִישׁ שֶׁהֵם מוֹדִים לוֹ יִטֹּל, וְהַשְּׁתוּת הַנִּשְׁאַר יַחֲלֹקוּ, יִטֹּל הוּא חֶצְיוֹ וְהֵם חֶצְיוֹ:\nזָקֵן וְיָבָם בְּנִכְסֵי סָפֵק אוֹ \u0010c9\u0011 סָפֵק וְזָקֵן בִּנִכְסֵי יָבָם, חוֹלְקִים:",[],["\u0003אבל אם השביחו וכו'\u0004. היינו בנכסים של אביהם אין נוטל השבח אבל בנכסי אחיו נוטל השבח דהוא יורש אותו ואין חולק עם שום אדם עיין במגיד ספ\"ב ה' נחלות:","\u0003י\"א דכל שמקרי ראוי וכו'\u0004. היינו בתשו' ריב\"ש כתב כל שנקרא ראוי גבי בכור הוי ראוי גבי יבם וי\"א השני היינו תשובת מהרי\"ו לכאורה נראה דל\"פ כי כל דברי ריב\"ש קאי על נכסי אביהם דאין נוטל ראוי מנכסי אביהם כל שנקרא ראוי לגבי בכור לאפוקי נכסי מת י\"ל דמודה דיורש אפי' ראוי וכן משמע מדברי המגיד הנ\"ל אלא מרי\"ו נשמע פלוגתא אחרינא דס\"ל אפי' מת אביה' אחר מיתת אחיו הוי מוחזק ויורש אותו אלא אם מת אבי אביה' אז הוי ראוי בנכסי אבי אביהם וכ\"כ באגודה פ' החולץ בשם ראבי' אבל בנכסי המת לא ראינו פלוגת' אלא מדברי הטור סי' ס' נראה דס\"ל אפי' בנכסי אחיו אין נוטל בראוי וכן דייק בתשוב' מהר\"א בן ששון סימן ר\"ב ותשובות מהרש\"ך ס\"א סימן קפ\"ח ע\"ש:","\u0003אפי' קודם שחלץ\u0004. אם תפס האב היינו במקום שאין כופין לחלוץ ואין מוחי' ליבם מ\"מ התופס י\"ל קים לי כהני פוסקים דס\"ל מצות חליצה קודם והיינו ע\"כ האב רוצה לזכות המותר נכסי' מה שנשאר אחר גביות כתובה ונדוניא דהא לכתובה ונדוניא שלה אין לו שייכות לפ\"ז משמע מ\"ש בהג\"ה אבל כבר נהגו שהחולץ יש לו חצי הנכסים היינו המותר נכסים וכל האחרונים כתבו התקנה לא היה לו על המותרת רק על כתובה ונדוניא שלה ועיין סי' ק\"ס וסי' קס\"ה:","\u0003יחלקו היבם והספק\u0004. לדעת הרמב\"ם ושאר פוסקים אפי' אין הזקן קיים חולקין ולא הוי בכה\"ג היבם ודאי יורש דהא צריכין לעיין אם יש למת זרע והוא אין יורש את אחיו אא\"כ אם אין זרע לאחיו נמצא כשבא לירש את אחיו הוכרח הוא לטענה שהספק הוא בנו וטענ' זו א\"י לטעון בטענת ברי ול\"ד לספק ויבם בנכסי זקן שדוחה היבם להספק משום היבם הוא בנו ויורש ודאי אף אם הספק גם כן בן המת משא\"כ כאן שאין יורש של אחיו אלא במקום דליכא בן:","\u0003ויש מי שאומר\u0004. הוא דעת הרא\"ש והטור דס\"ל היבם ודאי יורש אפי' בלא יבום כיון שהו' אחיו ואין אביו קיים והספק א\"י אם הוא יורש משא\"כ כשהזקן קיים אז הוא אינו יורש את אחיו אלא בטענה שלא הניח זרע וטענה זו א\"י בבירור ול\"ד לזקן ויבם בנכסי המת אחר מיתת הספק דחולקין אף ע\"ג הזקן הוא יורש דהא הוא אביו משום דא\"א לו ליקח יותר מספק שהוא בא לירש אותו ונ\"מ מפלוגתא זו אם היבם מת והניח בנות ולא בנים והספק זה בא לטעון עמהם שהוא בן היבם ויורש הכל אז לשאר פוסקים טענתם שוה דהא הבנות אין יורשים אא\"כ היכ' דליכ' כאן בן א\"כ חולקין יחדיו כמו היבם והספק דחולקין אף על גב היבם הוא אחיו מ\"מ כיון דנצרך לטענה שהספק לאו בן של המת וטענה זו היא טענת ספק כן ה\"נ שהבנות צריכים לטעון שהוא לאו בן היבם וטענת ספק הוא אבל להרא\"ש הוי הבנות ודאי כמו היבם שהוא ודאי נגד ספק והש\"ג פוסק כרמב\"ם ושאר פוסקים והבנות והספק חולקין:","\u0003החלק שהם מודים\u0004. אף על גב להספק יש בודאי חלק א' לא חשיב כמוחזק בשאר נכסיו בשביל חלק א' כמ\"ש בח\"ה ה' נחלות ואף כשהספק מוחזק:","\u0003ויש מי שאומר\u0004. הוא דעת הרמב\"ם וא\"ל מ\"ש מספק ובני יבם בנכסי זקן דאין חולקין בשוה כמ\"ש בסעיף ז' משום כאן אם היה בא הספק עם אביה' לדין היה כ\"א נוטל מחצה אמרי' אף השתא לא נשתנ' דינם ויש להם זכות וכח אביהם ונוטלי' חלק אביהם כמה שהקשה הרא\"ש שם בדין ספק ובני יבם בנכסי זקן, משא\"כ בספק ובני יבם בנכסי זקן אז אם היה בא לדין עם היבם היה נדחה מכל וכל ועכשיו ע\"כ דינו נתחדש ונוטל חלק א' ואז כל דינו נתחדש ונוטל מה שמודים לו ובמה שהם מחולקים עמו חולקין ובש\"ע קטנים שנדפס בשנת תכ\"ג העמיד ויש מי שאומר בסעיף ה' והחליף מקומו בשאין מקומו ואפשר דקשי' קושיא הנ\"ל והעמיד הפלוגת' שם ולא דק מש\"ס ופוסקים דקי\"ל שם קם דינא:","\u0003אין חוששין לדבריו\u0004. דקי\"ל קם דינ' הדין שפסקו כבר קם ועכשיו י\"ל להיפוך דהוא בן מיתנא והיינו דוק' אחר שחלקו כבר בנכסי המת אבל אם עדיין לא חלקו י\"ל הספק ממ\"נ כן כתבו תוס' והנה לדעת הרי\"ף וראב\"ד ורמב\"ן דין זה הוא דין ברור די\"ל קם דינא וא\"י לומר הספק ממ\"נ או תתנו לי החלק שלקח אביכם או תתנו לי חלק בירושת אביכם ואפי' תפס הספק לא מהני אבל לדעת הרא\"ש והטור ספיקא דדינא הוא ואין מוציאין מיד היורשים אבל אם הספק תפס אין מוציא ג\"כ מידו מטעם ממ\"נ כהנ\"ל ועיין בח\"ה סימן שצ\"א שם יתבאר בס\"ד חלוקי דינים אלו, ונ\"מ עוד מפלוגתא זו שפסק בספק וזקן הבאים לדין בנכסי יבם אחר שחלק היבם עם הספק בנכסי המת וכאן אין שום א' מוחזק אז לדעת הרא\"ש יכול הספק לומר ממ\"נ אם בן המת אני שייך לי החלק שלקח היבם וכאן לא שייך לומר אין מוציאין דאין א' מוחזק א\"כ זוכה הספק הדין ולשיט' הרי\"ף לא זכה ספק כלום כי קם דינא ועיין בש\"ג ופסק שם שנוטל בתחלה החלק מה שנטל היבם בנכסי המת והמותר יחלקו הספק והזקן דהא הזקן צריך להודה לו שהוא בן המת ושייך לו אותו חלק ועיין בח\"ה סי' רס\"ח בהג\"ה שם מה שפסק בשם ת\"ה בשנים הקונים סחורה בחצרו' שלהם בדין אם קם דינא או הדר דינא:","\u0003אין שומעין לו\u0004. מאחר היבם הוא ודאי יורש מחמת שהוא בנו והוא ספק יורש ועיין סק\"ב:","\u0003ספק וזקן בנכסי יבם חולקין\u0004. כן הוא בש\"ס לשיטת הרמב\"ם שפיר כמו יבם וספק בנכסי מת כ\"א אומר שהוא היורש יחלקו אפילו היכא דאין הסבא חי אבל לשיטת הרא\"ש שם דוקא כשהסבא חי אז חולקין אבל אם אין הסבא חי הוי היבם ודאי שהוא אחיו בודאי והספק א\"י שמא בן של חי הוא לפ\"ז קשה כאן נמי הזקן ודאי דהא אביו הוא, בשלמא על שאר פוסקים ל\"ק מדין יבם שדוחה את הספק מנכסי הזקן דשם היבם הוא בנו כמ\"ש בסמוך ואפשר כאן אף הזקן בא בטענת ספק דהא אם רוצה לירש את היבם אומרים לו הרי זה ייבם אשת אחיו ש\"מ שאחיו לא הניח זרע א\"כ זה הספק בנו הוא והזקן הוכרח ע\"כ לטענה שיבום היה באיסור וא\"י בודאי והוי טענת ספק משא\"כ שם הוא להיפך שיבם יאמר דל היבום מ\"מ אני אחיו אף על גב כשבא הספק לירש את היבם אם /עם/ יורשיו נמי מסייע היבום להספק ואין יורש כלל היינו נגד יורשיו בודאי לא מהני סברא זו אבל לעשותו שוה להזקן מהני ועיין דרישה:"]],["הַיְבָמָה \u0010c0\u0011 לֹא תַּחֲלֹץ וְלֹא תִּתְיַבֵּם עַד שֶׁיִּהְיוּ תִּשְׁעִים יוֹם מִמִּיתַת הַבַּעַל, חוּץ מִיּוֹם הַמִּיתָה וְיוֹם הַיִּבּוּם אוֹ \u0010c1\u0011 הַחֲלִיצָה. וְאִם יִבֵּם אוֹ חָלַץ תּוֹךְ זְמַן זֶה, וְלֹא נִמְצֵאת מְעֻבֶּרֶת, הֲרֵי זוֹ נִפְטְרָה וְאֵינָהּ צְרִיכָה כְּלוּם; אֲבָל לֹא תִּנָּשֵׂא לְאַחֵר אַף עַל פִּי שֶׁחָלְצָה, עַד שֶׁיַּשְׁלִימוּ תִּשְׁעִים יוֹם לְמִיתַת הַבַּעַל. \u0010c2\u0011 וְאִם מֵת הַיָּבָם תּוֹךְ הַתִּשְׁעִים יוֹם אוֹ אַחֲרֵיהֶם, יֵשׁ אוֹמְרִים שֶׁצְּרִיכָה לְהַמְתִּין תִּשְׁעִים יוֹם אַחַר מִיתָתוֹ. וְאִם הָיוּ שְׁנֵי יְבָמִים וּמֵת אֶחָד מֵהֶם, מֻתֶּרֶת לְהִתְיַבֵּם לַשֵּׁנִי תּוֹךְ תִּשְׁעִים יוֹם לְמִיתָתוֹ שֶׁל זֶה. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דְּכָל שֶׁחָלְצָה תּוֹךְ ג' חֳדָשִׁים, בֵּין נִמְצֵאת מְעֻבֶּרֶת וְהִפִּילָה, אוֹ לֹא נִמְצֵאת מְעֻבֶּרֶת, הֲוָה לָהּ חֲלִיצָה פְּסוּלָה \u0010c3\u0011 וּצְרִיכָה חֲלִיצָה אַחֶרֶת מִכָּל \u0006 \u0005 הָאַחִין \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי סוֹף גִּטִּין)\u0006. \u0005 וְעַיֵּן לְקַמָּן סִימָן ק\"ע סָעִיף ה': \u0010c4\u0011 \u0006\nהַחוֹלֵץ לִיבִמְתּוֹ וְנִמְצֵאת מְעֻבֶּרֶת, וְיָלְדָה, אִם הַוָּלָד שֶׁל קְיָמָא אֵין הַחֲלִיצָה כְּלוּם, הוּא מֻתָּר בִּקְרוֹבוֹתֶיהָ, וְלֹא פְּסָלָהּ מֵהַכְּהֻנָּה, וְאִם הִפִּילָה אוֹ יָלְדָה \u0010c5\u0011 וְלֹא חָיָה שְׁלשִׁים יוֹם, צְרִיכָה חֲלִיצָה אַחֶרֶת, שֶׁחֲלִיצַת מְעֻבֶּרֶת לֹא שְׁמָהּ חֲלִיצָה, וְחוֹלֵץ לָהּ הוּא אוֹ אֶחָד מִשְּׁאָר אַחִין. \u0005 וְיֵשׁ אוֹמְרִים שֶׁלֹּא יַחֲלֹץ לָהּ הוּא \u0010c6\u0011 אֶלָּא אֶחָד מִשְּׁאָר הָאַחִין \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006:\nבִּיאַת מְעֻבֶּרֶת נַמֵּי לֹא שְׁמָהּ בִּיאָה. לְפִיכָךְ, הַכּוֹנֵס אוֹ חוֹלֵץ לִיבִמְתּוֹ תּוֹךְ שְׁלשָׁה חֳדָשִׁים, וְלָהּ צָרָה, לֹא תִּנָּשֵׂא עַד שֶׁתֵּלֵד זוֹ אוֹ שֶׁמָּא תַּפִּיל וְלֹא הָיְתָה הַבִּיאָה אוֹ הַחֲלִיצָה כְּלוּם, וְהַוָּלָד אֵינוֹ פּוֹטֵר עַד שֶׁיֵּצֵא לַאֲוִיר הָעוֹלָם:\nהַיְבָמָה לֹא תִּתְיַבֵּם בְּעֵת נִדָּתָהּ, אֲבָל חוֹלֶצֶת הִיא. וְאִם עָבַר וְיִבֵּם וּבָא עָלֶיהָ בְּעֵת נִדָּתָהּ, קְנָאָהּ:\nהַכּוֹנֵס אֶת יְבִמְתּוֹ וְנִמְצֵאת מְעֻבֶּרֶת, מַפְרִישִׁים אוֹתָם וּמַמְתִּינִים לָהּ, אִם הִפִּילָה יַחֲזֹר וִיקַיֵּם. \u0005 הַגָּה: \u0010c7\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁכְּנָסָהּ קֹדֶם שֶׁהֻכַּר הָעֻבָּר, אֲבָל אִם כְּנָסָהּ מִשֶּׁהֻכַּר הָעֻבָּר צָרִיךְ לְהוֹצִיאָהּ אַף עַל פִּי \u0006 \u0005 שֶׁהִפִּילָה \u0006 \u0005(נ\"י פֶּרֶק הַחוֹלֵץ)\u0006. \u0005 וּכְשֶׁמְּקַיְּמָהּ, צָרִיךְ לַחֲזֹר וְלִבְעֹל, דְּבִיאַת מְעֻבֶּרֶת לֹא שְׁמָהּ בִּיאָה \u0006 \u0005(ב\"י בְּשֵׁם רבי' יְרוּחָם)\u0006. \u0005 וְאִם רָצָה לְהוֹצִיאָהּ, \u0010c8\u0011 צְרִיכָה גֵּט וַחֲלִיצָה: \u0006\nוָלָד שֶׁלֹּא נִגְמְרוּ סִימָנָיו וְלֹא כָּלוּ חֳדָשָׁיו, קָרוּי נֵפֶל. וְאִם יָלְדָה וָלָד שֶׁנִּגְמְרוּ סִימָנָיו וְאֵין יָדוּעַ אִם כָּלוּ חֳדָשָׁיו, אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד, \u0010c9\u0011 הֲרֵי זֶה מוֹצִיאָהּ בְּגֵט וְחוֹלֵץ לָהּ, וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לַאֲחֵרִים. וְאִם נִתְקַיֵּם הַוָּלָד שְׁלֹשׁים יוֹם אַחַר שֶׁנּוֹלַד \u0005 אוֹ שֶׁכָּלוּ לוֹ חֳדָשָׁיו \u0006 \u0005(הַמ\"מ)\u0006, הֲרֵי זֶה וָלָד שֶׁל קְיָמָא, וְאֵינָהּ צְרִיכָה מִמֶּנּוּ גֵּט, מִפְּנֵי שֶׁהִיא עֶרְוָה עָלָיו:\nיָלְדָה וָלָד שֶׁל קְיָמָא לְאַחַר שִׁשָּׁה חֳדָשִׁים מִשֶּׁנִּתְיַבְּמָה, הֲרֵי זֶה הַוָּלָד סָפֵק אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אִם בֶּן שִׁבְעָה לָאַחֲרוֹן. לְפִיכָךְ, יוֹצִיא בְּגֵט, וְהַוָּלָד כָּשֵׁר. וְאִם בָּא עָלֶיהָ אַחַר שֶׁיָּלְדָה, וְנִתְעַבְּרָה וְיָלְדָה, אוֹתוֹ וָלָד סְפֵק מַמְזֵר:\nכָּל יְבָמָה שֶׁהִיא סָפֵק מִדִּבְרֵיהֶם אִם יֵשׁ עָלֶיהָ זִקַּת יָבָם אִם לָאו, כְּגוֹן יְבָמָה שֶׁיָּלְדָה וָלָד \u0010c10\u0011 שֶׁלֹּא נוֹדַע שֶׁכָּלוּ לוֹ חֳדָשָׁיו וּמֵת בְּתוֹךְ ל' יוֹם אוֹ בְּיוֹם ל', שֶׁדִּינָהּ שֶׁתַּחֲלֹץ מִסָפֵק מִדִּבְרֵיהֶם כְּמוֹ שֶׁנִּתְבָּאֵר, אִם הָלְכָה וְנִתְקַדְּשָׁה לְאַחֵר אוֹ נִשֵּׂאת קֹדֶם חֲלִיצָה, חוֹלֵץ לָהּ יְבָמָהּ וְתֵשֵׁב עִם בַּעְלָהּ. וְאִם נִתְקַדְּשָׁה לְכֹהֵן שֶׁהוּא אָסוּר בַּחֲלוּצָה, אֵינוֹ חוֹלֵץ לָהּ, שֶׁאֵין אוֹסְרִין עַל זֶה אִשְׁתּוֹ מִשּׁוּם \u0010c11\u0011 סְפֵק דִּבְרֵיהֶם. \u0005 וְהוּא הַדִּין אִם אֵין הַיָּבָם כָּאן, שֶׁלֹּא תֵּצֵא מִבַּעְלָהּ יִשְׂרָאֵל, וּמֻתֶּרֶת לוֹ בְּלֹא חֲלִיצָה הוֹאִיל וּכְבָר נְשָׂאָהּ \u0006 \u0005(ר\"י מִינְץ בִּתְשׁוּבָה)\u0006. גֵּרְשָׁהּ הַכֹּהֵן אוֹ מֵת, \u0010c12\u0011 הֲרֵי זוֹ חוֹלֶצֶת לְכַתְּחִלָּה, וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לַאֲחֵרִים:",[],["\u0003לא תחלוץ וכו'\u0004. אפי' בידוע דאינה מעוברת כיון דאינה עולה ליבום תוך ג\"ח דקי\"ל אפי' יבא אלי' ואמר דאינה מעוברת אסור' ליבם כמ\"ש בש\"ס פרק החולץ:","\u0003ואם יבם וכו'\u0004. משמע אם יבם תוך ג\"ח אין מפרישין אותה דוקא כשהיא מעובר' מפרישין אותה ולא בספק מעוברת:","\u0003ואם מת היבם צריכה להמתין וכו'\u0004. כ\"כ התוספות דיבמה יותר קרובה לביאה מארוסה וארוסה צריכה להמתין ג\"ח ואפשר בזמן הזה דכופין על חליצה א\"צ להמתין ג\"ח דהא אינה קרובה לביאה:","\u0003וצריכה חליצה אחרת מכל האחים\u0004. ואם אין אחים אחרים יחלוץ זה אחר ג\"ח שם בהג\"מ, ולמ\"ד חליצה פסולה חוזרת ע\"כ האחים אחר ג\"ח צריכה חליצה מכל האחים ומזה א\"צ כי חליצתו גרועה משל האחים ועיין סי' קע\"ה:","\u0003החולץ וכו'\u0004. ואם הפיל' פי' התוס' אפילו חלץ תוך ג\"ח ונמצאת מעוברת מ\"מ הוי חליצה לחומרא וה\"ה אם ניכר שהיא מעוברת נמי הוי חליצה לחומרא ע\"ש בתוס' ריש החולץ והא דקי\"ל חליצת מעוברת לא הוי חליצה היינו לקולא אבל לחומרא הוי חליצה ופסולה לכהן וכן אסורה להתייבם, וכתב הנ\"י אם נשאת לכהן מוציאין ממנו א\"כ מכ\"ש אם נשאת ליבם דמוציאין ממנו:","\u0003ולא חיה ל' יום\u0004. ולכאורה נראה אם מת הולד תוך ל' יום דאז מדאורייתא ולד מעליא הוא כמ\"ש בסימן קנ\"ו גם לרבנן דרשב\"ג ולד מעליא הוא י\"ל דסמכי' בזה על רבנן ואם נשאת לכהן לא תצא ממנו דאמרינן ולד מעליא הוא וחליצה שחלץ אין חליצה כלל כמה שסמכי' על רבנן אם נתקדש' לכהן בלא חליצה כמ\"ש בסעי' ז' כן ראוי לסמוך על רבנן כשחלץ לה אלא ראיתי בנ\"י דלא ס\"ל כן דהא במתניתי' פי' ולד שאינו קיימא היינו שמת תוך ל' ומ\"מ כתב אם נשאת לכהן תצא ש\"מ בזה לא סמכינן על רבנן, ואפשר משום דהוי תרתי לריעותא דכבר חלץ ולפטור אותה בלא חליצה אלא לפ\"ז אם מת היבם אז ליכא איסור משום זקוק' ליבם ואינו אלא חד ריעותא י\"ל דסמכי' על רבנן כמה דסמכינן בסעיף ז' בחד ריעותא, ואפשר דאין לדמות ריעותא זו לשם דאיכא כאן מראית עין דחלץ לה והשתא נשואה לכהן וגרע טפי:","\u0003אלא א' משאר האחין\u0004. כבר כתבתי ל\"ד א' מן האחי' אלא למ\"ד צריכה לחזור ע\"כ האחים צריכה חליצה מכל האחים ואפשר מ\"ש א' מן האחים היינו לכ\"ע אף למ\"ד חליצה פסולה א\"צ לחזור ע\"כ האחים מ\"מ יחלוץ א' מן האחים ולא זה שחלץ כבר כי חליצתו גרוע מחלוצת אחרים:","\u0003וי\"א דוקא וכו'\u0004. הנה בתוס' ריש החולץ מבואר דלא ס\"ל כן דהא פירשו מתני' ה\"ה אם חלץ והוכר דהיא מעוברת והא דקתני ונמצאת מעוברת משום סיפא נקיט דאם היתה מעוברת לא היה חייב קרבן ש\"מ אבל מה דתני בסיפ' וקיים אתי' שפיר אף הוכר דהיא מעוברת דאל\"כ ה\"ל לתרץ דתני משום יקיים אף על גב דקי\"ל אם נשא מעוברת חייב לגרש אפילו נדר ע\"ד רבים ואסורה איסור דאורייתא מחמת הנדר אפשר לומר גם שם אם הפילה מותרת לו או י\"ל דס\"ל לתוס' כאן משום מצות יבום אל יגרש שמא יהיה הולד נפל ויקיים מצות יבום לכן ימתין עד שיודע איך יהיה וי\"ל להיפך אף למ\"ד דאסורה לו אף אחר שהפילה י\"ל דוקא כאן דאיכא א\"ד ליבם אשת אחיו שלא במקום מצוה משא\"כ שם אפשר יש להקל:","\u0003צריכה גט וחליצה\u0004. היינו אם ירצה להוציאה קודם שבעל לשם יבום אחרי שהפילה צריכה גט משום ביאה דמעיקרא וחליצה משום הזיקה דקי\"ל ביאת מעוברת לחומרא הוי ביאה ולא לקולא, וכן אם ילדה ולד ומת בו ביום אז מדאורייתא ולד מעליא הוא כמ\"ש בסי' קנ\"ו אם כן אסורה להתיבם צריכה גט וחליצה מטעם הנ\"ל:","\u0003ה\"ז מוציאה בגט\u0004. והרמ\"ה ס\"ל דלא תצא כיון דספיקא הוא אם הולד קיימא וכאן השמיט המחבר דעתו כי הב\"י בספרו תמה עליו דראוי להחמיר הואיל וספק דאורייתא, וראיתי בב\"ה דתירץ וכתב דהוי ספקא דרבנן והא כתב הרמב\"ם ספ\"ב והיינו מש\"כ בש\"ע סס\"ז כל יבמה שהי' ספק מדבריהם אם יש עליו זיקה כגון שמת הולד תוך ל' יום וכו' אלמא ספק דרבנן הוא, ודברי תימא הוא בוודאי לענין אם נשאת לאחר הוי ספיקא דרבנן משום דאורייתא ולד מעליא הוא אף שמת מיד כמ\"ש בסימן קנ\"ו אבל אם נשאת ליבם אז הוי ספיקא דאורייתא ואפשר מ\"ה חזר ממ\"ש בב\"ה והשמיט דעתו בש\"ע:","\u0003שלא נודע אם כלו חדשיו\u0004. בר\"ס קנ\"ו כתבתי אפילו ודאי בן ח' וגמרו הסימנים הוי ולד מדאורייתא וכן כתב הנ\"י אם הוא בן ח' וגמרו סימנים בזה פליגי רבנן ורשב\"ג ובאשת כהן סמכי' על רבנן ומותרת לו והובא בד\"מ בפשיטות מיהו תוספות פרק הערל (יבמות דף פ') כתבו דרבנן פליגי בסתם ולדות ובבן ח', ובסתם ס\"ל לקולא אפילו תוך ל' יום הוי ולד מעליא ובן ח' ס\"ל אפילו בן ל' לא הוי ולד, ולא מצינו בש\"ס דגמרו סימנים עדיף משהה ל' יום אם כן אין לנו לסמוך על רבנן, גם מנ\"ל לרבנן מהני גמרו, גם לרשב\"ג לא נשמע גמרו אלא ל' יום מהני, ולרבנן יש לומר אפילו גמרו ושהה ל' יום לא מהני עד עשרים שנה כמ\"ש בתוספות שם אליבא דרב אבהו וכן הוא להדיא בתשובת ריב\"ש סי' תמ\"ו וכתב שם דיש בזה ג' מחלוקות כשהוא בודאי בן ח' לרבנן לא מהני אף שהה ואף גמרו לרשב\"ג מהני שהה אפילו לא גמרו א\"כ לשניהם אם נשאת לכהן צריכה חליצה דאין לנו לסמוך דהא איירי כאן דמת תוך ל' יום אלא שכתב שם לרבי מהני גמרו, וצ\"ע אם יש לומר דסמכינן על פירוש הנ\"י ואליבא דרבנן, ושאר חילוקי ודינא אימת הוא ולד מעליא עיין סימן קנ\"ו מ\"ש:","\u0003ספק דבריהם\u0004. אף ע\"ג דהשתא נשארה תחת בעלה בספק יבמה דאורייתא ואם היתה חולצת ונשארת תחת בעלה היתה עומדת בספק חליצה דרבנן מ\"מ הא עדיפא טפי דאי חלצה אמרי קמו רבנן בולד דנפל הוי ולהכי אצריכוה חליצה הרא\"ש:","\u0003ה\"ז חולצת\u0004. כ\"כ הרמב\"ם ספ\"ב ולא כש\"ג פרק החולץ דפסק דא\"צ חליצה מאחר דהיתה מותרת לכהן בלא חליצה:"]],["מִצְוַת יִבּוּם קוֹדֶמֶת לְמִצְוַת חֲלִיצָה. וְאִם אֵינָהּ רוֹצָה לְהִתְיַבֵּם לְשׁוּם אֶחָד מֵהָאַחִים, \u0005 אוֹ בַּגָּדוֹל כְּשֶׁרוֹצֶה לְיַבֵּם, \u0006 בְּלֹא טַעֲנָה מַסְפֶּקֶת, דִּינָהּ כְּמוֹרֶדֶת. וְיֵשׁ אוֹמְרִים שֶׁמִּצְוַת חֲלִיצָה קוֹדֶמֶת. \u0005 הַגָּה: וְאֵין לָהּ דִּין מוֹרֶדֶת אִם אֵינָהּ רוֹצָה \u0010c0\u0011 לְהִתְיַבֵּם. וּמִכָּל מָקוֹם אֵין כּוֹפִין אוֹתוֹ לַחֲלֹץ, אֶלָּא מַטְעִין אוֹתוֹ אִם יְכוֹלִין לְהַטְעוֹתוֹ, כְּגוֹן שֶׁאוֹמְרִים לוֹ: חֲלֹץ עַל מְנָת שֶׁתִּתֵּן לְךְ מָנֶה \u0006 \u0005(טוּר בְּשֵׁם ר\"ת וְהָרֹא\"שׁ)\u0006. \u0005 וְדַוְקָא אִם אֵינוֹ מֵאוֹתָן שֶׁכּוֹפִין לְהוֹצִיא גַּבֵּי בַּעַל, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קנ\"ד. וְאִם שְׁנֵיהֶם רוֹצִים בְּיִבּוּם, אֵין מַנִּיחִים אוֹתָם \u0010c1\u0011 לְיַבֵּם אֶלָּא אִם כֵּן נִכָּר וְיָדוּעַ שֶׁמְּכַוְּנִים לְשֵׁם \u0006 \u0005 מִצְוָה \u0006 \u0005(טוּר בְּשֵׁם ר\"ת)\u0006. \u0005 וְיֵשׁ אוֹמְרִים דְּאִם יֵשׁ לוֹ אִשָּׁה אַחֶרֶת, \u0010c2\u0011 \u0006 \u0005 שֶׁכּוֹפִין אוֹתוֹ וּמְנַדִּין אוֹתוֹ עַד שֶׁיַּחֲלֹץ \u0006 \u0005(טוּר בְּשֵׁם סְמַ\"ג)\u0006. \u0005 וְיֵשׁ אוֹמְרִים אֲפִלּוּ בְּלֹא אִשָּׁה אַחֶרֶת, אִם אֵינָם מְכַוְּנִים לְשֵׁם מִצְוָה, וְהִיא אֵינָהּ רוֹצָה לְהִתְיַבֵּם, וְאֵין יְכוֹלִים לְהַטְעוֹתוֹ, כּוֹפִין אוֹתוֹ לַחֲלֹץ. וְהַמִּנְהָג כַּסְּבָרָא הָרִאשׁוֹנָה, שֶׁאֵין כּוֹפִין לַחֲלִיצָה כְּלָל, אֲפִלּוּ יוֹדְעִין בּוֹ שֶׁנָּתַן עֵינָיו בַּמָּמוֹן \u0006 \u0005(מַהֲרַ\"ם פַּדָּוואָה סִימָן י\"ח)\u0006, \u0005 אֶלָּא מְפַשְּׁרִים בֵּינֵיהֶם כְּפִי תַּקָנוֹת הַקְּהִלּוֹת, כְּמוֹ שֶׁיִּתְבָּאֵר לְמַטָּה. וְכָל זֶה כְּשֶׁהוּא אוֹמֵר שֶׁרוֹצֶה לְהִתְיַבֵּם, וְאֶפְשָׁר לְהִתְיַבֵּם שֶׁאֵין חֲשַׁשׁ אִסוּר בְּיִבּוּמוֹ. אֲבָל אִם אוֹמֵר שֶׁאֵינוֹ רוֹצֶה לֹא לְיַבֵּם וְלֹא לַחֲלֹץ, כּוֹפִין אוֹתוֹ \u0006 \u0005(ב\"י בְּשֵׁם ר\"ת)\u0006. \u0005 וְדַוְקָא בְּבָאָה מֵחֲמַת טַעֲנָה, כְּדֶרֶךְ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קנ\"ד \u0006 \u0005(ת\"ה סִימָן ר\"כ)\u0006. \u0005 מִיהוּ, אִם אֶפְשָׁר לְהַטְעוֹתוֹ וְלוֹמַר לוֹ שֶׁיִּקַּח מָמוֹן הַרְבֵּה עַל הַחֲלִיצָה, מַטְעִינָן לֵהּ כְּדֵי שֶׁלֹּא נִצְטָרֵךְ לָכֹף \u0006 \u0005(נ\"י מ\"כ)\u0006. \u0005 וְיִזָּהֲרוּ שֶׁלֹּא יַשְׁלִישׁוּ הַמָּמוֹן בְּיָד שָׁלִישׁ, כִּי אָז לֹא יְכוֹלִין לוֹמַר לוֹ: מְשַׁטֶּה הָיִינוּ בְּךְ \u0006 \u0005(מָרְדְּכַי פ' הַחוֹלֵץ)\u0006. \u0005 וְעַיֵּן לְקַמָּן סִימָן קס\"ט סָעִיף נ': \u0006\nיְבָמָה שֶׁנָּדְרָה הֲנָאָה מִיְּבָמָהּ בְּחַיֵּי בַּעְלָהּ, אוֹ שֶׁנָּדְרָה הֲנָאָה מִכָּל הַיְּהוּדִים, \u0010c3\u0011 כּוֹפִין אוֹתוֹ שֶׁיַּחֲלֹץ לָהּ. וְאִם נָדְרָה לְאַחַר מִיתַת בַּעְלָהּ, מְבַקְּשִׁים מִמֶּנּוּ שֶׁיַּחֲלֹץ לָהּ. \u0010c4\u0011 וְכֵן אִם נִתְכַּוְּנָה בְּנִדְרָהּ אֲפִלּוּ בְּחַיֵּי בַּעְלָהּ, כְּדֵי שֶׁלֹּא יְיַבֵּם אוֹתָהּ, \u0010c5\u0011 מְבַקְּשִׁים מִמֶּנּוּ שֶׁיַּחֲלֹץ לָהּ. \u0005 הַגָּה: הָיָה יְבָמָהּ \u0006 \u0005 כֹּהֵן, וְהָלְכָה וְנִתְקַדְּשָׁה לְאַחֵר כְּדֵי שֶׁלֹּא יוּכַל לְיַבְּמָהּ, דִּינָהּ כְּאִלּוּ נָדְרָה הֲנָאָה מִמֶּנּוּ. \u0010c6\u0011 וּמִכָּל מָקוֹם אֵין כּוֹפִין אוֹתוֹ לַחֲלֹץ, הוֹאִיל וְהִיא גָּרְמָה שֶׁאֲסוּרָה לוֹ \u0006 \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִי' תת\"כ)\u0006, \u0010c7\u0011 \u0005 וְיֵשׁ אוֹמְרִים שֶׁאִם רָקְקָה לִפְנֵי הָאַחִים אוֹ כַּדּוֹמֶה לָזֶה, וְגָרְמָה שֶׁאֲסוּרָה לְיַבֵּם, אֵין לָהּ דִּין מוֹרֶדֶת הוֹאִיל וְאִי אֶפְשָׁר לָהּ לְיַבֵּם מֵעַכְשָׁו \u0006 \u0005(רַשְׁבָּ\"א אָלֶף ר\"ב)\u0006. \u0005 וּכְבָר נִתְבָּאֵר בְּסָמוּךְ שֶׁכָּל חִלּוּקִים אֵלּוּ לְמַאן דְּאָמַר מִצְוַת יִבּוּם קוֹדֵם, אֲבָל לְמַאן דְּאָמַר מִצְוַת חֲלִיצָה קוֹדֶמֶת, אֵין לָהּ דִּין מוֹרֶדֶת כְּלָל אִם אֵינָהּ רוֹצָה בְּיִבּוּם: \u0006\nיְבָמָה שֶׁתָּבְעָהּ הַיָּבָם לַחֲלֹץ, וְהִיא אֵינָהּ רוֹצָה אֶלָּא לִשָּׁאֵר עֲגוּנָה, אֵין שׁוֹמְעִין לָהּ, אֲפִלּוּ הָיָה הַיָּבָם נָשׂוּי. \u0010c8\u0011 \u0005 וְדִינָהּ כְּמוֹרֶדֶת, וְנִתְבָּאֵר דִּינָהּ סִימָן ע\"ז: \u0006\nכָּל יְבָמָה שֶׁדִּינָהּ שֶׁתַּחֲלֹץ וְלֹא תִּתְיַבֵּם, הֲרֵי זוֹ נוֹטֶלֶת כְּתֻבָּתָהּ \u0005 וְשָׂמִין לָהּ בְּגָדִים כְּמוֹ לְאַלְמָנָה \u0006 \u0005(רִיבָ\"שׁ סִי' ש\"כ)\u0006. וְכֵן אִם הָיָה יְבָמָהּ מֻכֶּה שְׁחִין אוֹ שְׁאָר מוּמֵי אֲנָשִׁים שֶׁנִּתְבָּאֲרוּ בְּסִימָן קנ\"ד, חוֹלֵץ לָהּ וְנוֹטֶלֶת כְּתֻבָּתָהּ. וַאֲפִלּוּ הָיוּ הַמּוּמִין הָהֵם בְּבַעְלָהּ, יְכוֹלָה הִיא לוֹמַר: לְאָחִיךָ הָיִיתִי יְכוֹלָה לְקַבֵּל וּלְךָ אֵינִי יְכוֹלָה לְקַבֵּל. \u0005 הַגָּה: וְהוּא הַדִּין לְמַאן דְּאָמַר מִצְוַת חֲלִיצָה קוֹדֶמֶת, אַף עַל פִּי שֶׁאֵין כּוֹפִין אוֹתוֹ לַחֲלֹץ, צָרִיךְ לִתֵּן לָהּ כְּתֻבָּתָהּ מִיָּד, שֶׁהֲרֵי דִּינָהּ כַּחֲלוּצָה \u0006 \u0005(תְּשׁוּבַת ר\"ד כֹּהֵן)\u0006. \u0005 וְכָל זֶה מִדִּינָא, \u0010c9\u0011 אֲבָל הַקְּהִלּוֹת \u0006 \u0005 תִּקְּנוּ תַּקָּנָה, אִם יִתְרַצּוּ הַיָּבָם וְהַיְבָמָה בַּחֲלִיצָה, יַחֲלֹקוּ כָּל הַנְּכָסִים שֶׁהִנִּיחַ, וַאֲפִלּוּ אֵין מַגִּיעַ הַחֵצִי לִכְדֵי כְּתֻבָּהּ, וּמְנַכִּין לָהּ מֵחֶלְקָהּ כָּל מַה שֶּׁבִּזְבְּזָה בְּחַיֵּי בַּעְלָהּ, וּצְרִיכָה לִשָּׁבַע, אִם לֹא שֶׁהִתְפַּשְּׁרוּ עַצְמָם בְּלֹא שְׁבוּעָה. וּמַה שֶּׁנָּתַן הוּא בְּמַתְּנַת שְׁכִיב מְרַע, אֵין מְנַכִּין לָהּ מֵחֶלְקָהּ כְּלוּם \u0006 \u0005(מָרְדְּכַי פֶּרֶק הַחוֹלֵץ)\u0006. \u0005 וְאוֹתוֹ הַחֵצִי שֶׁמַּגִּיעַ לְחֵלֶק יוֹרְשֵׁי הַבַּעַל, נוֹטֵל הַחוֹלֵץ, וְאֵין לָאָב וְלֹא לִשְׁאָר אַחִין חֵלֶק בּוֹ. וַאֲפִלּוּ תָּפְסוּ, מוֹצִיאִין מִיָּדָן. דְּעִקַּר הַתַּקָּנָה הָיְתָה כְּדֵי שֶׁיִּתְרַצּוּ בַּחֲלִיצָה, וְלָכֵן הַחוֹלֵץ עִקָּר בָּזֶה \u0006 \u0005(ת\"ה סִימָן ר\"כ)\u0006. \u0005 וַאֲפִלּוּ אִם רוֹצִין שְׁאָר הָאַחִין לַחֲלֹק עִם גְּדוֹל הָאַחִין, וְאוֹמְרִים שֶׁהֵם רוֹצִים לַחֲלֹץ, אֵין שׁוֹמְעִין לָהֶם אִם גְּדוֹל הָאַחִין רוֹצֶה לַחֲלֹץ. וְכָל זֶה שֶׁאֵין מַגִּיעִין חֲצִי הַנְּכָסִים לִכְדֵי כְּתֻבָּתָהּ, דְּוַדַּאי אֵינָהּ נוֹטֶלֶת יוֹתֵר מִכְּדֵי כְּתֻבָּתָהּ. וְיֵשׁ דֵּעוֹת אֲחֵרוֹת בְּעִנְיַן תַּקָּנוֹת הַקְּהִלּוֹת; עַל כֵּן נוֹהֲגִין לְהִתְפַּשֵּׁר בֵּינֵיהֶם, וַאֲפִלּוּ יֵשׁ לָהּ שְׁטָר חֲלִיצָה מִן הָאַחִין צְרִיכָה לְהִתְפַּשֵּׁר עִמָּהֶם בְּמָמוֹן, \u0010c10\u0011 אִם לֹא שֶׁפֵּרְשׁוּ בְּהֶדְיָא לַחֲלֹץ לָהּ \u0006 \u0005 בְּחִנָּם \u0006 \u0005(מַהֲרַ\"ם פַּדָּוואָה סִימָן י\"ז וְכ\"ג)\u0006:\nנוֹלְדוּ בָּהּ מוּמִין כְּשֶׁהִיא שׁוֹמֶרֶת יָבָם, אִם אֵינוֹ רוֹצֶה לְיַבֵּם חוֹלֵץ לָהּ וְנוֹתֵן לָהּ כְּתֻבָּה:",[],["\u0003ומ\"מ אין כופין אותו\u0004. דברי הרב רמ\"א סתומים הם דמשמע לדעת ר\"ת והרא\"ש אין כופין כלל וליתא אלא כשא\"י אם מתכוונת לשם מצוה כופין במילי אף על גב בנדרה הנאה ממנו קי\"ל כופין אותו אפי' בשוטים כמ\"ש בתוס' ושאר פוסקים כל היכא דתני בש\"ס כופין היינו בשוטים וקי\"ל גם כן בנשא אשה בעבירה כופין בשוטי', ש\"ה דאין ודאי איסור אלא חיישינן שמא אין כוונתו לשם מצוה ואם ידוע דאין כוונת' לשם מצוה כופין אפי' בשוטים להנך פוסקים דס\"ל מח\"ק וכ\"כ בתשובת מהר\"י לבית הלוי סי' ט' לדעת פוסקים אלו ג' חלוקי דינים הם, א' אם מתכוונ' בוודאי לשם מצוה מניחים אותם לייבם, ב' כל שא\"י אם כוונתה לש\"מ כופין במילי ולא בשוטים, ג' כל שידוע כוונת' שלא לש\"מ כופין בשוטים כ\"כ ב\"ח וכן מדויק בטור ולא כמשמעות בב\"י ובד\"מ דמשמע דס\"ל אפי' בידוע דאין מתכוונ' לש\"מ אין כופין בשוטי' וליתא ומנהג שלנו דאין כופין משום דחיישינן שמא הלכת' כהרי\"ף ורמב\"ם דס\"ל מ\"י קודם אפי' אם מתכוון שלא לשם מצוה, לפ\"ז אם יש לו אשה לכ\"ע כופין בשוטים אם ידוע כוונת' שלא לשם מצוה אפילו לדיעה קמיית' דהא הריב\"ש פסק בסימן ש\"ב אם יש לו אשה לכ\"ע מח\"ק, לפי זה מ\"ש בסמוך והמנהג כסבר' הראשונה שאין כופין לא קאי על הבבא דיש לו אשה אחרת דאז לכ\"ע מח\"ק וכופין אותו אלא דוקא כשאין לו אשה אחרת אז י\"ל דלמא הלכתא כהני פוסקים דס\"ל מ\"י קודם אפילו כוונתם שלא לשם מצוה, מיהו י\"ל אף בכה\"ג אין כופין דאף שמח\"ק מ\"מ יבום מצוה היא אפילו אין כוונתו לש\"מ אלא שמח\"ק וכשאין לו אשה אז מ\"י קודם אפי' אין כוונת' לש\"מ אבל לכוף אותו י\"ל אין כופין אותו כיון לשיטה זו אין עושה שום איסור אף על גב ביש לו אשה אחרת לכמה פוסקים אפילו אם א\"י כוונתו כופין אותו לחלוץ מחמת תקנת ר\"ג ומשמע אפי' בשוטי' מ\"מ י\"ל להפוסקים דפליגי עליהם וס\"ל דאין כופין ס\"ל אפי' בידוע כוונתם שלא לש\"מ אין כופין, ועיין תשו' מהר\"י לבית הלוי הנ\"ל ומשמע שם גם כן דאין כופין אף דיש לו אשה אחרת וידוע כוונתם שלא לש\"מ ולא פסק שם לכופו אלא בצירוף עוד טעמים אחרים, ועיין תשובות מהר\"ם מלובלין סי' ל\"ח:","\u0003אא\"כ ניכר וידוע שמכווני' לשם מצוה\u0004. ומכל מקום אין כופין אותו ליבם, תוספות:","\u0003כופין אותו\u0004. היינו אפילו בשוטים ב\"י בשם מ\"כ:","\u0003כופין אותו שיחלוץ\u0004. היינו אפילו בשוטים דהא מפורש בש\"ס דכופין אותו כמ\"ש בסי' קנ\"ד, ואם מצאה היתר לנדרה מותרת לו ולא אמרינן דאסורה הואיל בעת שנפלה לפניו היתה אסורה מחמת נדר ב\"י בשם הרשב\"ץ ועיין סימן קע\"ה דיני' הללו ואם היה לו אשה בעת שנפלה לפניו והיתה אסורה עליו מחמת תקנות ר\"ג יש לומר דגרע טפי דאין היתר לאיסור זה משא\"כ איסור נדר יכול להתיר ע\"ש:","\u0003וכן אם נתכוונה\u0004. כתב המגיד דכל שא\"י כוונתה אמרינן מסתמ' דעתה היתה בשביל היבם וכן מדויק לשון הטו' אכן מה שמדייק המגיד מרש\"י אין מוכרח ופי' אחר יש בסוגי' זו היינו פרש\"י ובעל המאו' ורשב\"א בתשובה כל שנדרה הנאה מן היהודי' בחיי בעלה אין היבם בכלל ומותרת ליבם לפ\"ז י\"ל דאין כופין אותו כשנדרה הנאה מכל היהודים מאחר לכמה פוסקים מותרת לו ודמה לדין רס\"ז דאין כופין לחלוץ אפילו כוונתו שלא לש\"מ הואיל ולכמה פוסקים מותרת לו אפילו בכונס לשם נוי:","\u0003מבקשים ממנו\u0004. ואם אינו רוצה דינה כמורדת כיון שהיא גרמא לאסור עליו אף על גב שאין תקנה לדבר מ\"מ דינה כמורדת בשני דיני' אלו דכוונת' היתה על היבם והמחבר כתב בסתם ומבקשים ממנו וסמך עצמו על רס\"ז כשהיא אינו רוצה להתייבם דדינ' כמורדת והיינו מ\"ש בסמוך בהגהות בשם י\"א דאין לה דין מורד' היינו הרשב\"א ס\"ל כן כל שאין תקנ' לדבר אין לה דין מורדת:","\u0003ומ\"מ אין כופין\u0004. מלת מ\"מ אין מובנת לי מהיכ' תיתי לכופו מאחר שהיא גרמה ואסרה את עצמה עליו:","\u0003וי\"א שאם רקק' וכו'\u0004. החידוש הוא לדעת הרשב\"א כל שאין תקנה לדבר אין דינה כמורדת קשה ל\"ל לכתוב דין חדש ולא כתב בקיצור בנתקדש' לאחר דאין דינ' כמורדת ועיין בלבוש שכתב ברקקה דוק' ס\"ל לרשב\"א דלא הוי מורדת דיש לומר דלא ידעה שאם תרוק אסור' ליבם משמע שנתקדשה דינה כמורדת:","\u0003ודינה כמורדת\u0004. הנה בטור וברמב\"ם לא כתבו דהיא מורדת אלא בפסקי מהרא\"י סימן רס\"ז פירש כן וכן הוא במגיד אפי' אם רצונה ליבם מכל מקום דינה כמורדת אף לשיטות הפוסקים דמי\"ק מכל מקום בדידי' תלי' רחמנ' אי בעי מיבם אי בעי חולץ, ואם אינו רוצה לחלוץ מחמת בושה או דקשה לה להיות שפילה ונכנעת לו דינה כמורדת שנותנת אמתלא לדבריה וצריך להחזיר לה הנדוני' כמה שכתב בסימן ע\"ו בהגהות ואם כוונת' בשביל ממון אז יהבינן הכל ליבם אפי' מה שהכניסה היא ונ\"מ שלה הם ועיין בד\"מ ועיין ת\"ה סימן ר\"ך ומזה ראיי' למ\"ש בסי' ע\"ז אפי' בטענות שקר לא הפסידה נ\"מ ומשמע אם היא רוצה ליתן חלקו ואינו רוצה לחלוץ הרשות בידה ועיין בב\"י בשם הרמב\"ם ותשוב' הר\"ן ועיין בזוהר פ' חקת משמע דמצוה דוק' בחליצה:","\u0003אבל הקהילו' תקנו וכו'\u0004. דין זה נובע ממ' פ' החולץ שהקהילות תקנו כדי שאל תעגן אותה דזימנין טובא שהוא חפץ ליבם והיא אינה רוצה ואין בידינו לכופ' כשיטת התוספ' גם לא רצו לפסוק דינה כמורדת דהא לשיטת תוס' מח\"ק ותבא לידי עיגון ותצא לתרבות רעה לכן תקנו לחלוק עמה וענין חלוקה עיין בתשו' ש\"י סי' ס\"ה ותשו' מהר\"ם סימן י' ותשו' מ\"ב סימן ק\"י דאין חולקין אלא שיעור כתובה ונצ\"ב חולקי' כמ\"ש בסמוך החולץ והחלוצה ואין לאב ושאר אחים חלק בזה והמותר אם יש אב נוטל האב ואם אין האב חולקין כל האחים והחולץ שוה בשוה ואין להחולץ שום קדימה אלא החצי מכתובה ועיין סי' קס\"ג מ\"ש דהרב רמ\"א לא ס\"ל כן ומבואר שם אם בכל זאת לא התרצה היבם לחלוץ אין לפחות מחלק האב והאחים ליתן לו דמה להם בעיגון היבמה והקהילות א\"י לתקן לפחות חלקן וצריכה היא לפייס אותו משלה, לפ\"ז נראה מה שפסק בתשובת מהרי\"ו והבאתי בסימן ק\"ס בשם מהר\"א בן ששון היכ' דיבמה מתה ויש ב' אחים יורשים כל העזבון של בעלה והיבם ליקח חצי מנצ\"ב ואין האב יורש כלום לית' לפי תיקון הקהילות דהא אין לבנים שום זכות בעזבון אלא בכתובה כשהיא חי ולמה ישתנה הדין אחר מותה אף על גב דנשתנה הדין לענין הכתובה שאני כתובה שהיא חלקה והיא מתה אבל מהיכי תיתי לומר דישתנה הדין לענין נצ\"ב ואפשר ליישב דאוקמי' על דינא דש\"ס כשחולץ מבואר בש\"ס דאבא יורש לכן אין לחולץ שום יתרון אלא בכתובה אבל כשמתה מבואר בש\"ס דהאחים יורשים אף על גב דלדידן אסורה ליבם מ\"מ לענין ממון דינו כיבם ויורשים הכל האחים, ובסי' ק\"ס הבאתי מ\"ש מהרי\"ק שורש צ\"א ובשורש ק\"ב ובתשו' מהר\"י לבית הלוי פסק כמ\"ש בשורש ק\"ב דלענין ממון דינם כיבם ולכאור' נ\"ל מכל תשובו' האחרונים הנ\"ל ומפסקי מהר\"י סימן רס\"ג ובת\"ה סי' ר\"כ דס\"ל כמ\"ש בשורש צ\"א דהא כאן הוא רוצה לייבם ואנוס בתקנת' של חז\"ל דאסור ליבם אין יורש כלום אלא מחלק כתובה הוא נוטל כדי שיחלוץ לה לש\"מ אך לענין ממון לא הוי כיבם נגד אביו ואחיו כה\"נ לענין יורשי האשה י\"ל דהוא אינו יורש אותה כיון דא\"י ליבם אותה ואפשר לחלק שם אין עושה שום דבר ומדין דש\"ס האחים יורשין אמרינן אף לדידן יורשי' הם כי לענין זה לא תקנו משא\"כ כשהוא חולץ אז מדינ' דש\"ס כשחולץ אינו יורש לכך אף לדידן אינו יורש, וע\"ש בת\"ה ובפסקיו מ\"ש בשם א\"ז ונ\"מ לדידן אם שניהם רוצים ליבם וכוונת' ידוע לש\"מ אלא שיש לו אשה וא\"י ליבם מחמת חר\"ג אז הוא נוטל הכתובה לגמרי ואין לה כלום, ול\"ד לשאר חולץ דחולקים שם איכ' איסור מצד יבום גופא אז דינו כחולץ אלא מצד התקנה הוא נוטל חצי' משא\"כ אם הוא אנוס מצד תקנות ר\"ג דלא שייך מידי יבום, ועיין בתשובת בן ששון סי' כ\"ט אם היא אסורה ליבם מחמת שהיא ספק אם הולד בן קיימא הוא נותנים לה הכתובה משלם ואין חולקת עמו, ומבואר שם בפסקים דחולקים כתובה ות\"כ והנדוניא וראיה שלו מלשון מהר\"ם שכתב בסתם ותנתן לה כל חצי ממון ולא פרט מידי דש\"מ הכל בכלל החלוקה אפילו הנדוניא, ולכאורה היה נ\"ל מזה גם נ\"מ בכלל החלוקה מדלא פרט מידי מיהו בד\"מ כתב בשם מהר\"י מינץ דהיא נוטלת נ\"מ בראש ואח\"כ חולקים, וצריך לומר דמהר\"ם לא היה צריך לפרוש נ\"מ כיון בידה הוא ותופס' מה שבידה משא\"כ נצ\"ב אף אם אחר מיתת בעלה בידה הם מכל מקום ידו כידה והוי כאלו בידו ג\"כ והיה לו לפרוט:","\u0003אם לא שפירשו בהדי' וכו'\u0004. ואם אח\"כ אומר שרצונו לייבם אותה אין כופין אותה לחלוץ כי שמא הלכה מי\"ק והוי כמתנה ע\"מ שכתב בתורה כן אית' בכמה תשובות וכ\"כ ב\"ח, ובתשובות מהר\"ש ד\"מ לא\"ה סי' ע\"א ובתשובות מהר\"א בן ששון סי' כ\"ח איתא מ\"מ יכולים לעשות הרחקה של ר\"ת שלא לדבר ושלא לישא וליתן עמו ולא שיאמרו שלא לדבר עמו עד שתחלוץ דאז הוי כפי' אלא לעשות הרחקה סתם שלא לדבר עמו ובזה יש לתרץ מה שקשה לכאורה מה מהני השטר חליצה לחלוץ בחנם דהא אף בלא שטר אם אומר שאינו רוצה לא לחלוץ ולא לייבם כופין אותו אלא כשאומר שרצונו לייבם אין כופין אותו ועכשיו ג\"כ אין כופין אותו אבל למ\"ש דעושין הרחקה הנ\"ל אז שפיר אם לא נתן ש\"ח ואומר שרצונו לייבם אין עושין לו שום כפי' אפילו הרחק' הנ\"ל והיינו שאין לו אשה אבל נתן ש\"ח עושין הרחקה הנ\"ל ואם נותן ש\"ח ולא כתב שיחלוץ בחנם אז י\"ל השטר נותן שא\"י לומר שרצונו לייבם אבל חליצה שיתן כוונתו כתקנו' הקהלו' מ\"ה צריך לכתוב שיחלוץ בחנם ודע מצות יבום כשרצונו לייבם רק לקיים המצות יבום ורוצה לגרש' מיד אחר ביאה הראשונה נמי בכלל מצות יבום אף ביבמה מן האירוסין דא\"א להתעבר ממנו מביאה הראשונה וליכ' כאן להקים שם אחיו מ\"מ מ\"י לא תלינן כלל בזה אלא אם ראוי' להקים שם אחיו שייך מ\"י לאפוקי איילונית וסריס דא\"י להקים שם אחיו כנ\"ל מדברי תוספות ביבמות דף ך' ועיין לקמן סי' קע\"ד מ\"ש אם מהני קנין סודר על החליצה:"]],["הַיְבָמָה הוֹלֶכֶת אַחַר הַיָּבָם בְּמָקוֹם שֶׁהוּא שָׁם, וּבֵית דִּין נוֹתְנִים לוֹ עֵצָה הַהוֹגֶנֶת לִשְׁנֵיהֶם, אִם לְיַבֵּם אוֹ לַחֲלֹץ. \u0005 הַגָּה: וְדַוְקָא שֶׁהַיָּבָם בִּמְקוֹם \u0006 \u0005 דִּירָתוֹ, וְהוּא בִּמְקוֹם בֵּית דִּין; אֲבָל אִם הָלַךְ לְמָקוֹם אַחֵר, \u0010c0\u0011 אֵין כּוֹפִין \u0006 \u0005 הַיְבָמָה לֵילֵךְ אַחֲרָיו \u0006 \u0005(נ\"י סוֹף פֶּרֶק זֶה בּוֹרֵר)\u0006. \u0005 וְכֵן אִם הוּא דָּר בֵּין הַכּוּתִים אוֹ בֵּין הֶדְיוֹטוֹת שֶׁאֵין יוֹדְעִין סֵדֶר חֲלִיצָה, אֵין לַדַּיָּנִין לֵילֵךְ אַחֲרָיו, אֶלָּא כּוֹפִין אוֹתוֹ לֵילֵךְ לִמְקוֹם וַעַד, וְיִפְטֹר יְבִמְתּוֹ \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פ' מִצְוַת חֲלִיצָה)\u0006:\nמִן הַתּוֹרָה אֵין צָרִיךְ לְקַדְּשָׁהּ, אֶלָּא בָּא עָלֶיהָ. וַחֲכָמִים תִּקְּנוּ שֶׁלֹּא יָבֹא עָלֶיהָ \u0010c1\u0011 עַד שֶׁיְּקַדְּשֶׁנָּה בִּפְנֵי עֵדִים, בְּכֶסֶף אוֹ בִּשְׁטָר, וְהוּא נִקְרָא מַאֲמָר. \u0005 הַגָּה: \u0010c2\u0011 וְאִם קִדְּשָׁהּ בִּשְׁטָר, נַמֵּי מִקְּרֵי \u0006 \u0005 מַאֲמָר \u0006 \u0005(מ\"מ פ\"ב)\u0006. \u0005 וַאֲפִלּוּ נָתַן לָהּ פְּרוּטָה וְאָמַר לָהּ: הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּזוֹ וּבְקִדּוּשֵׁי אָחִי, הֲרֵי זוֹ מְקֻדֶּשֶׁת, דְּהָוֵי כְּמִלְוֶה וּפְרוּטָה \u0006 \u0005(רִיבָ\"שׁ סִימָן קס\"ב)\u0006. \u0005 וּצְרִיכָה גַּם כֵּן חֻפָּה אַחַר קִדּוּשִׁין, כְּמוֹ שְׁאָר אִשָּׁה. וְיָכוֹל לַעֲשׂוֹת מַאֲמָר עַל יְדֵי שָׁלִיחַ, כְּמוֹ בִּשְׁאָר קִדּוּשִׁין \u0006 \u0005(שָׁם סִימָן א')\u0006. וְאִם בָּא עָלֶיהָ בְּלֹא מַאֲמָר, קָנָה, וְאֵין צָרִיךְ לַחֲזֹר וּלְקַדֵּשׁ, וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. \u0005 וְדַוְקָא שֶׁבָּא עָלֶיהָ בִּפְנֵי עֵדִים: \u0006\nאֵין עוֹשִׂין בָּהּ מַאֲמָר, אֶלָּא מִדַּעְתָּהּ. וּקְטַנָּה שֶׁנִּתְאַלְמְנָה מֵהָאֵרוּסִין, אֵין עוֹשִׂין בָּהּ מַאֲמָר אֶלָּא מִדַּעַת אָבִיהָ:\nכּוֹתֵב לָהּ \u0010c3\u0011 כְּתֻבָּה, וְאֵין נִכְסֵי הַיָּבָם מְשֻׁעְבָּדִים לָהּ, שֶׁכְּתֻבָּתָהּ עַל נִכְסֵי בַּעְלָהּ הָרִאשׁוֹן. וְאִם אֵין לָרִאשׁוֹן נְכָסִים, כְּתֻבָּתָהּ עַל נִכְסֵי הַיָּבָם:\nנוֹלַד לוֹ בֵּן מִמֶּנָּה, אֵין צָרִיךְ לִקְרוֹתוֹ עַל שֵׁם אָחִיו הַמֵּת:\nכְּתֻבַּת יְבָמִים צְרִיכָה שִׂרְטוּט, מִפְּנֵי הַפְּסוּקִים שֶׁכּוֹתְבִים בָּהּ. \u0005 וְעַיֵּן בַּטּוּר סִימָן זֶה טֹפֶס הַכְּתֻבָּה: \u0006\nהַבָּא עַל יְבִמְתּוֹ, בֵּין בְּשׁוֹגֵג, \u0010c4\u0011 בֵּין לְשֵׁם זְנוּת, בֵּין שֶׁאֲנָסוּהוּ כּוּתִים וְהִדְבִּיקוּהוּ בִּיבִמְתּוֹ בְּעַל כָּרְחוֹ עַל יְדֵי קשִׁי, בֵּין שֶׁהָיָה הוּא מֵזִיד וְהִיא שׁוֹגֶגֶת אוֹ אֲנוּסָה, בֵּין שֶׁהָיְתָה הִיא מְזִידָה וְהוּא שׁוֹגֵג אוֹ אָנוּס, בֵּין שֶׁהִיא עֵרָה אוֹ יְשֵׁנָה, קָנָה, \u0010c5\u0011 אֲפִלּוּ בְּהַעֲרָאָה:\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁנִּתְכַּוֵּן לְשֵׁם בִּיאָה בְּעָלְמָא, וַאֲפִלּוּ לֹא נִתְכַּוֵּן אֶלָּא לְבִיאַת בְּהֵמָה. אֲבָל אִם לֹא נִתְכַּוֵּן לְשֵׁם בִּיאָה כְּלָל, כְּגוֹן \u0010c6\u0011 שֶׁהוּא יָשֵׁן \u0010c7\u0011 אוֹ שִׁכּוֹר שֶׁאֵינוֹ מַכִּיר כְּלוּם, אוֹ שֶׁנִּתְכַּוֵּן לְהָטִיחַ בַּכֹּתֶל וְהֵטִיחַ בִּיבִמְתּוֹ, אוֹ שֶׁנִּתְקַשָּׁה לְאִשְׁתּוֹ וְנָפַל מִן הַגַּג וְנִתְקַע בִּיבִמְתּוֹ, לֹא קָנָה. וְכֵן אִם הִדְבִּיקוּהוּ בִּיבִמְתּוֹ בְּלֹא \u0010c8\u0011 קִשּׁוּי, אֶלָּא בְּאֵבֶר מֵת, לֹא קָנָה:\nבַּמֶּה דְּבָרִים אֲמוּרִים שֶׁבִּיאַת שׁוֹגֵג קָנָה, בִּיבִמְתּוֹ שֶׁנָּפְלָה לוֹ מִן הַנִּשּׂוּאִין. אֲבָל אִם נָפְלָה לוֹ \u0010c9\u0011 מֵהָאֵרוּסִין, יֵשׁ אוֹמְרִים שֶׁלֹּא קָנָה לְיוֹרְשָׁהּ וְלִטָּמֵא לָהּ וּלְהָפֵר נְדָרֶיהָ, וְיֵשׁ מִי שֶׁאוֹמֵר דְּהוּא הַדִּין לְהַעֲרָאָה. \u0005 יֵשׁ אוֹמְרִים שֶׁהַבָּא עַל יְבִמְתּוֹ \u0010c10\u0011 צָרִיךְ לְבָרֵךְ: \"אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל (בִּיאַת)\u0006 [בְעִילָת] יְבָמָה\" \u0005(טוּר בְּשֵׁם הָעִטּוּר)\u0006:",[],["\u0003אין כופין היבמה\u0004. ובנ\"י כתב אלא כופין אותו לבא אחריה משמע כיון שהלך ממקומו אין כופין אותו שיבא למקומו והיא תלך לשם אלא מוכרח לבא למקומה:","\u0003עד שיקדשנ' בכסף\u0004. ואומר לה התקדשי לי במאמר יבמין אף על גב דיהיב לה כסף מ\"מ לאו קידושין גמורים הם שהרי אשת אח היא והתורה לא התירת' אלא כסדר המצוה וביאה הוא דכתיב לכן בקדושי כסף או שטר עדיין לא קניא לה לגמרי ואם רוצה לפוטרה צריכה גט וחליצה וביאה קונה לגמרי ואין צריך חליצה עיין ברש\"י ומשמע מש\"ג אף אם קידש לפני עדים ובעיל לא נגמר הקנין אם לא היה היחוד לפני עדים דמצוה כך היא שיהא דווק' לפני עדים כמו החליצה שצריכה להיות לפני עדים ואם לא היה לפני עדים צריכה גט וחליצה אם רוצה לפוטרה כנ\"ל ממשמעות הש\"ג ע\"ש ריש דף תמ\"ה ומשמעות הג\"ה בסמוך לא משמע כן דהא כתב דין זה כשבא עליה בלא מאמר משמע אם עשה כבר מאמר אין צריך להיות לפני עדים וסבר דוק' כשבועל בלא מאמר דאז דינו כקדושין וצריך להיות דווק' לפני עדים משא\"כ אם כבר קידש אותה אין צריך עדים כמו באשה דעלמ' ולית' כי קדושין לא שייך בה ולעולם הביאה הקנין וצריכה להיות לפני עדים, לפ\"ז אם לא היה לפני עדים אין כאן קנין מדאוריית' אלא מדרבנן אף בקידש ובעל וי\"ל הגהו' בסמוך קאי על הבבא ואין צריך לקדש ע\"ז כתב דווק' שבא עליה בפני עדים אבל אם בא בלא עדים אז צריך לקדשה מאחר דאין כאן קידושין דאוריית', ולא חיישינן בזה שמא יאמרו דביאה לא קנה כיון דליכ' כאן קנין דאוריית' אלא מדרבנן לא חיישינן כולי האי בדבר דרבנן ול\"ד לקדושין ע\"י שליח דשם מקודשת מדאוריית' אלא בד\"מ לא משמע כן:","\u0003ואם קידשה בשטר וכו'\u0004. איני יודע מה חידש בזה דהא נכלל ג\"כ בדברי המחבר גם מ\"ש בד\"מ דין זה בשם המגיד ג\"כ תמוה דהא משמע כן בכל סוגיא אף על גב בבריית' דף צ\"ד תני כיצד במאמר נתן כסף כיצד בשטר וכו' מכל מקום כל המשניות עשה מאמר וכל סוגיא איירי הכל בין בכסף בין בשטר ואפשר דפי' המגיד דמקדש בש\"ח ועיין סי' כ\"ט מ\"ש עליו אם מקדש בש\"ח:","\u0003ואין נכסי היבם משועבדים\u0004. אף אחר שתקנו חז\"ל לקדש אותה כשאר אשה מ\"מ בענין הכתובה לא נשתנה הדין דכתובתה על נכסי בעל הראשון וכן מוכח לכאורה למאי דס\"ד להביא סיוע לר\"ה דאמר מקדש ואח\"כ בועל ממתניתא פר\"ג א\"כ קשה דסותר מתניתין זו למתניתין בכתובות דף פ' דתני שם בכתובו' על נכסי בעל הראשון גם הבריית' שהביא שם פר\"ג כיצד מאמר משמע נמי דס\"ל דמקדש בתחלה ומפרש כיצד מאמר ומ\"מ תניא ובלבד שתהא כתובה על נכסי בעל הראשון, וכן משמע מדברי הטור שכתב בסימן קס\"ח דכתובה על נכסי הראשון ואין לה משני כתובה אף למה שפוסק דמקדש בתחלה מ\"מ כתב דאין לה משני כתובה א\"ו אין חילוק בדבר לעולם אין לה כתובה מראשון וכן הוא בש\"ג דף תכ\"א ולא כב\"ח שכתב אחר שתקנו חז\"ל לקדש אותה כשאר אשה צריך לכתוב לה כתובה על מאה זהו' אפילו יש נכסים לראשון ויש לה מאתיים מראשון וק' משני וליתא, ולענין מזונות היבמה מבואר בתוספות ובהרא\"ש ס\"פ כ\"ש אפילו היכא דליתא כתובה משני מ\"מ יש לה מזונות אפילו אחר מותו, ועיין בר\"ן פ' האשה שנפלו שפסק ג\"כ דיבם אחר שכנס זוכה בפירות וחייב בפרקונה ועיין דרישה:","\u0003בין לשם זנות\u0004. אף לשיטת הפוסקים דסבירא להו מ\"ח קודם כאבא שאול דאמר הכונס לשם זנות לשם נוי כאלו נוגע בערוה מ\"מ בדיעבד קונה כ\"כ הנ\"י ולטעמו אזיל דכתב ר\"פ הע\"י אבא שאול מדרבנן קאמר דאסור לייבם לשם נוי מ\"ה ס\"ל בדיעבד קונה כיון מדאורייתא ליכא איסור, מיהו י\"ל אף אם היה מדאורייתא אסור לייבם לשם נוי או ד\"א מ\"מ קנה אותה ועיין סימן קע\"ד מ\"ש:","\u0003אפילו בהעראה\u0004. אף על גב דקי\"ל כל הבועל דעתו על גמר ביאה מ\"מ ביבמה די בהעראה אפילו אמר בפירוש דעתו על גמר ביאה קונה בהעראה כיון דריבה התורה העראה קונה לא בעינן דעתו דהא אפי' אם שניהם אנוסים קונה, כ\"כ הר\"ן פ\"ק דקידושין והנ\"י ר\"פ הע\"י והעראה קונה אפילו בביאה גרועה כלומר בשוגג או לשם זנות בהעראה מ\"מ קונה וכן קונה שלא כדרכה תוספות והטור, אף על גב להקים שם אחיו כתיב כתבו תוספות הקרא אתי למעט כשאין ראוים היבם והיבמה להקים פרט איילונית והסריס אבל כשראוים להקים אף בביאה זו א\"א להקים קונה:","\u0003שהוא ישן\u0004. והכל תלוי בו בבועל אבל אם כוונתו לשם ביאה אף שאין כוונתה לביאה כגון שהיא ישינה קונה כמ\"ש בסעיף הקודם אף על גב דאסור לבוא עליה כשהיא ישינה כמ\"ש בתוס' דנידה מ\"מ קונה וישן תיר ולא תיר קונה, ש\"ס:","\u0003או שיכור שאינו מכיר כלום\u0004. כלומר שהגיע לשכרותו של לוט, המגיד ועיין סימן מ\"ד:","\u0003אלא באבר מת\u0004. אפילו למ\"ד המשמש באבר מת חייב מ\"מ לא קנה דבעינן ביאה דרך הקמת שם, תוס' וגרע טפי מביאה שלא כדרכה כיון דמשמש בקושי אבר ראוי להקמת זרע במקומה משא\"כ באבר מת:","\u0003י\"א שלא קנה\u0004. הא שכתב דין זה בשם י\"א משום דהמחבר מדייק בספרו ב\"י מרמב\"ם דס\"ל דקונה לכל דבר חוץ מתרומה אפילו מן האירוסין לכן כתב בשם י\"א דלא קונה וס\"ל לעיקר דעת הרמב\"ם, מיהו דיוק של ב\"י אין מוכרח וע\"ש:","\u0003צריך לברך וכו'\u0004. עיין בטור בשם העיטור דמברך אחר הביאה ומשמע הטעם דחיישינן שמא תחזור היא ותמאן בו והוי ברכה לבטלה לפ\"ז יש לומר למה דקי\"ל דמברכין ברכת ארוסין קודם הקידושין ולא חיישינן שמא תחזור בו כן ה\"נ לא חיישינן שמא תחזור בו, ועיין סימן ס\"ג:"]],["קָטָן פָּחוֹת מִבֶּן תִּשְׁעָה, אֵין בִּיאָתוֹ כְּלוּם; וּמִבֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וְאֵילָךְ, בִּיאָתוֹ \u0010c0\u0011 קוֹנָה בִּיבִמְתּוֹ כַּמַּאֲמָר בַּגָּדוֹל. וּבְאִשָּׁה דְּעָלְמָא אֵינָהּ קוֹנָה כְּלָל; לְפִיכָךְ, נָשָׂא אִשָּׁה וּמֵת, פְּטוּרָה מֵהַחֲלִיצָה וּמֵהַיִּבּוּם:\nבֶּן ט' שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל יְבִמְתּוֹ, אֵינוֹ יָכוֹל לְפָטְרָהּ בְּגֵט, עַד שֶׁיַּגְדִּיל וְיָבֹא עָלֶיהָ אַחַר כָּךְ. וְאִם לֹא בָּא עָלֶיהָ אַחַר כָּךְ, וּבָא לְהוֹצִיאָהּ, צְרִיכָה גֵּט וַחֲלִיצָה. וְאִם בָּא עָלֶיהָ כְּשֶׁהוּא קָטָן, וּמֵת קֹדֶם שֶׁהִגְדִּיל, אוֹ מֵת אַחַר שֶׁהִגְדִּיל אֲבָל לֹא בָּא עָלֶיהָ מִשֶּׁהִגְדִּיל, \u0010c1\u0011 חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. וְאִם מִשֶּׁהִגְדִּיל נָשָׂא אַחֶרֶת, וְלֹא בָּא עַל הַיְבָמָה מִשֶּׁהִגְדִּיל, שְׁתֵּיהֶן חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת:\nקָטָן אֵינוֹ חוֹלֵץ, עַד שֶׁיִּהְיֶה בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד וְיִבְדְּקוּהוּ אָז וְיִמְצְאוּהוּ שֶׁהֵבִיא שְׁתֵּי שְׂעָרוֹת. אֲבָל אִם הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת קֹדֶם שֶׁהִגְדִּיל, אֵינוֹ נֶחְשָׁב גָּדוֹל עַל יָדָם, אֶלָּא אִם כֵּן יָבִיא שְׁתֵּי שְׂעָרוֹת אֲחֵרוֹת אַחַר שֶׁהִגְדִּיל. וּמִכָּל מָקוֹם, אִם מוֹצְאִים לוֹ שְׁתֵּי שְׂעָרוֹת אַחַר שֶׁהִגְדִּיל, לֹא חַיְשִׁינָן שֶׁמָּא אֵלּוּ הָיוּ בּוֹ מִקֹּדֶם:\nקְטַנָּה מִבַּת שָׁלשׁ שָׁנִים וְיוֹם אֶחָד וָמַעְלָה, בִּיאָתָהּ בִּיאָה לְכָל דָּבָר; וְאִם בָּא עָלֶיהָ יָבָם, \u0010c2\u0011 קְנָאָהּ; אֲבָל \u0010c3\u0011 אֵינָהּ חוֹלֶצֶת עַד שֶׁתְּהֵא בַּת י\"ב שָׁנָה וְיוֹם אֶחָד וּבְדָקוּהָ אַחַר כָּךְ וּמְצָאוּהָ שֶׁהֵבִיאָה ב' שְׂעָרוֹת:\nיָבָם קָטָן שֶׁבָּא עַל יְבָמָה קְטַנָּה, יִגְדְּלוּ זֶה עִם זֶה. וְאִם בָּא לְגָרְשָׁהּ קֹדֶם שֶׁיַּגְדִּיל, אֵינוֹ יָכוֹל, דְּגֵט קָטָן אֵינוֹ גֵּט:\nיְבָמָה שֶׁנִּתְיַבְּמָה, וְאָמְרָה בְּתוֹךְ ל' יוֹם: לֹא נִבְעַלְתִּי, אַף עַל פִּי שֶׁהוּא אוֹמֵר: בָּעַלְתִּי, וְגֵרְשָׁהּ, כּוֹפִין אוֹתוֹ שֶׁיַּחֲלֹץ לָהּ, הוֹאִיל וְקָדַם וְגֵרְשָׁהּ בְּגֵט. וְאִם עֲדַיִן לֹא גֵּרַשׁ, כּוֹפִין אוֹתוֹ שֶׁיִבְעֹל אוֹ יַחֲלֹץ וְיוֹצִיא בְּגֵט. \u0010c4\u0011 \u0005 וַאֲפִלּוּ מוֹדֶה לִדְבָרֶיהָ שֶׁלֹּא בָּעַל, צְרִיכָה גֵּט וַחֲלִיצָה, דְּכָל כְּנוּסָה בְּחֶזְקַת בְּעוּלָה \u0006 \u0005(הַמ\"מ פ\"ב)\u0006. \u0010c5\u0011 גֵּרְשָׁהּ לְאַחַר שְׁלשִׁים יוֹם, וְהִיא אוֹמֶרֶת: לֹא נִבְעַלְתִּי, מְבַקְּשִׁים מִמֶּנּוּ שֶׁיַּחֲלֹץ לָהּ. \u0010c6\u0011 וְאִם הוּא מוֹדֶה שֶׁלֹּא בָּעַל, כּוֹפִין אוֹתוֹ \u0010c7\u0011 לַחֲלֹץ. הִיא אוֹמֶרֶת: נִבְעַלְתִּי, וְהוּא אוֹמֵר: לֹא בָּעַלְתִּי, אֵינָהּ צְרִיכָה חֲלִיצָה, שֶׁאֵין זֶה נֶאֱמָן לְאָסְרָהּ עַל כָּל אָדָם אַחַר שֶׁכָּנְסָהּ. \u0005 וְיֵשׁ אוֹמְרִים דְּתוֹךְ ל' יוֹם הוּא נֶאֱמָן, וּצְרִיכָה חֲלִיצָה עִם הַגֵּט. \u0006 וְצָרָתָהּ, לְעוֹלָם מֻתֶּרֶת, אֲפִלּוּ הוּא וְהִיא אוֹמְרִים שֶׁלֹּא בָּעַל, וַאֲפִלּוּ בְּתוֹךְ ל' יוֹם. \u0005 וְיֵשׁ אוֹמְרִים דְּכָל ל' יוֹם \u0010c8\u0011 הוּא נֶאֱמָן לוֹמַר שֶׁלֹּא בָּעַל, לֶאֱסֹר הַצָּרָה \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006:",[],["\u0003קונה ביבמתו\u0004. כמאמר ומ\"מ זוכה בנכסי אחיו רש\"י פ' יוצא דופן ועיין סימן ק\"ע ס\"ק י\"א:","\u0003חולצת ולא מתייבמת\u0004. הטעם מבואר בש\"ס כיון דביאת קטן כמאמר אם כן עדיין נשאר עליה זיקה הראשונה והוי אשת ב' מתים ואסורה מדרבנן, גם צרתה אסור ליבם מדרבנן דאי מייבם הצרה וחולץ לזו יאמרו ב' יבמות מבית א' מקצתו בנוי ומקצתו חלוץ, לכן חולץ תרווייהו והכל מדרבנן, כי הדרוש ולא אשת ב' מתים אינו אלא אסמכתא ועיין תוס' פ' ד\"א דף ל\"ב וברמב\"ם ספ\"ו ומזה סתירה נמי למ\"ש ב\"ח בסימן קס\"א דאיכא א\"ד לחלוץ ב' יבמות מבית א' א\"כ איך חולץ כאן לשתיהן הא יש לחוש שיאמרו ב' יבמות מבית אחד חולצין לתרוייהו כמה דחיישינן שמא יאמרו מקצתו בנוי ומקצתו חלוץ:","\u0003קנאה\u0004. ויורש נכסי אחיו ויורש' ומטמאה לה:","\u0003אינה חולצת\u0004. אפילו בדיעבד אין חליצת קטנה חליצה, המגיד אבל מגרשה בקטנותה:","\u0003ואפי' מודה לדבריה\u0004. כ\"כ התוס' לפירוש ב' והמגיד דאמרי' אפילו ביבמה חזקה דבועל אותה מיד כשנסתר, לפ\"ז נראה דכופין על הגט אפילו לא קידש אותה וא\"צ גט משום הקדושין מ\"מ צריכה גט מחמת החזקה שבעיל אותה וכופין אותו משום חזקה כהנ\"ל וחליצה צריך ליתן הואיל תוך ל' יום הוא והיא אומרת לא נבעלתי:","\u0003גירשה לאחר ל' יום וכו'\u0004. דאז חזקה הנ\"ל מסייע לו גם אחר ל' יום לא מוקים נפשיה לכן מבקשים ממנו שיחלוץ ולשון בקשה שייך בחליצה משום דזלות לו שתריק בפניו תוספו' גם אם היתה יוצאת בגט לבד מותרת לחזור לו כ\"כ הנ\"י ולפי טעמים אלו צריך טעם מ\"ש הטור לשיטתו דמבקשים ממנו גט מאחר דחולץ מה מפסיד הוא ליתן גט ולמה אין כופין לגרשה, ויש לומר דכתב המגיד אם גירש ואחר כך שהה עמה אפילו לאחר ל' יום אמרינן מסתמא לא בעל אותה כיון דאיכא איסור לבעול מיהו הרי\"ף כתב דאיירי הסוגיא שנתן גט על הזיקה ואחר כך כנסה וכן משמע בתוספות, ועיין ב\"ח:","\u0003ואם הוא מודה שלא בעיל\u0004. ואח\"כ שהה עמה ואמר שבעל אח\"כ כופין אותו על החליצה כיון שהורע חזקתו והודה פ\"א שלא בעיל אחר ל' יום נ\"י בשם הריטב\"א:","\u0003היא אומרת נבעלתי וכו'\u0004. דאז החזקה הנ\"ל מסייע' לה מ\"ה אם גירש הוא אין נאמן לאוסרה אפילו תוך ל' יום וי\"א ס\"ל הואיל תוך ל' יום הוא ואפשר דמוקים נפשיה נאמן והטור כתב בזה לשיטתו דנאמן ואין כופין על הגט אם לא גירש עדיין משום דהוא נאמן תוך ל' יום דלא בעיל והיינו שלא קידש גם כן אותה ועיין ב\"ח ודרישה מיהו לדינא כופין על הגט וחליצה:","\u0003הוא נאמן\u0004. אבל אם אמר שבעיל והיא אומרת לא נבעלתי אינה נאמנת לאסור את צרתה כ\"כ הרא\"ש, מיהו תוס' כתבו דאסורה הצרה תוך ל' יום אם לא יודו שניהם שבעיל וב\"י הביא הגירסא דאסורה תוך ל' יום אף אם יודו שניהם שבעיל וכ\"כ בד\"מ ולכאורה נראה דט\"ס הוא וצ\"ל כמה דאיתא הגירסא שלפנינו בתוס' כל ששניהם מודים לכ\"ע לא חיישינן שמא לא בעיל, גם החומרא של תוס' הוא מפירוש הראשון של תוס' דאיירי הברייתא הוא אמר לא בעלתי והיא אומרת נבעלתי תוך ל' צריכה חליצה מזה למדו תוס' מאחר דהיא צריכה חליצה ממילא הצרה אסורה ושם איירי כשהיא אומרת לא נבעלתי א\"כ מנ\"ל לתוס' להחמיר כששניהם אומרים שבעיל גם לשיטת תוס' אף לאחר שלשים כששניהם אומרים לא בעיל צרתה אסורה וכן משמע בש\"ג שם:"]],["מִשֶּׁיִּבֵּם הַיָּבָם אֶת הַיְבָמָה, הֲרֵי הִיא כְּאִשְׁתּוֹ לְכָל דָּבָר, שֶׁיָּכוֹל לְהוֹצִיאָהּ בְּגֵט \u0010c0\u0011 וְיָכוֹל לְהַחֲזִירָהּ:\nגֵּרְשָׁהּ וְהֶחֱזִירָהּ קֹדֶם שֶׁפָּרַע לָהּ כְּתֻבָּתָהּ, דִּינָהּ כְּאִשָּׁה אַחֶרֶת שֶׁגֵּרְשָׁהּ וְהֶחֱזִירָהּ, שֶׁאֵין לָהּ אֶלָּא כְּתֻבָּה אַחַת:\nיְבָמָה, \u0010c1\u0011 כְּתֻבָּתָהּ עַל נִכְסֵי בַּעְלָהּ הָרִאשׁוֹן. \u0010c2\u0011 לְפִיכָךְ, אֵין הַיָּבָם רַשַּׁאי לִמְכֹּר כְּלוּם מִכָּל נִכְסֵי אָחִיו. וְאִם מָכַר אוֹ נָתַן מַתָּנָה, אוֹ חָלַק עִם אֶחָיו בִּנִכְסֵי הַמֵּת, בֵּין קֹדֶם יִבּוּם בֵּין אַחַר יִבּוּם, לֹא עָשָׂה כְּלוּם:\nהִנִּיחַ אָחִיו פֵּרוֹת מְחֻבָּרִים לַקַּרְקַע, יִמָּכְרוּ, וְיִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת:\nהִנִּיחַ פֵּרוֹת תְּלוּשִׁין אוֹ מִטַּלְטְלֵים, יִמָּכְרוּ, וְיִלָּקַח בָּהֶן קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת. וְהוּא הַדִּין אִם הִנִּיחַ מָעוֹת. וַאֲפִלּוּ אִם הָיָה הוּא חַיָּב לְאָחִיו \u0010c3\u0011 מָנֶה, מוֹצִיאִין מִיָּדוֹ וְיִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל \u0010c4\u0011 פֵּרוֹת. וְיֵשׁ אוֹמְרִים שֶׁבְּפֵרוֹת תְּלוּשִׁין וּמִטַּלְטְלֵין וּמָעוֹת, מִשְׁתַּמֵּשׁ בָּהֶם כְּמוֹ שֶׁיִּרְצֶה. וְאִם כָּתוּב בַּכְּתֻבָּה: מְטַלְטְלֵי אַגַּב מְקַרְקְעֵי, לְדִבְרֵי הַכֹּל יִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת. \u0005 הַגָּה: וּמִכָּל מָקוֹם, כָּל זְמַן שֶׁלֹּא כָּנְסָהּ, אֵין נוֹתְנִים הַנְּכָסִים לְיָדוֹ, אֶלָּא מוֹצִיאִין כָּל הַמִּטַּלְטְלִין וְהַמָּעוֹת מִיָּדוֹ לְיַד בֵּית דִּין אוֹ לְאַפּוֹטְרוֹפּוֹס, (אֲבָל)\u0006 הַקַּרְקָעוֹת הוּא אוֹכֵל פֵּרוֹת \u0005(ב\"י בְּשֵׁם הָרַשְׁבָּ\"א)\u0006:\nהַנְּכָסִים שֶׁבְּיַד הַיְבָמָה, מוֹצִיאִין אוֹתָם מִיָּדָהּ וְיִלָּקַח בָּהֶם קַרְקַע וְהוּא אוֹכֵל פֵּרוֹת:\nאֲפִלּוּ גֵּרְשָׁהּ וּכְנָסָהּ אַחַר כָּךְ סְתָם, אֵינוֹ יָכוֹל לִמְכֹּר מִנִּכְסֵי אָחִיו, אֶלָּא אִם כֵּן יַתְנֶה בְּשָׁעָה שֶׁמַּחֲזִירָהּ שֶׁכְּתֻבָּתָהּ עַל כָּל נְכָסָיו. וּבְלֹא גֵּרוּשִׁין, אִם מִתְרַצָּה לוֹ עַל מְנָת שֶׁיִּכְתֹּב לָהּ אַחֲרָיוּת כְּתֻבָּתָהּ עַל כָּל נְכָסָיו, יָכוֹל לִמְכֹּר:\nיְבָמָה שֶׁלֹּא הָיָה לָהּ כְּתֻבָּה, אוֹ שֶׁמָּחֲלָה כְּתֻבָּתָהּ, זָכָה בִּנִכְסֵי אָחִיו, וּמוֹכֵר וְנוֹתֵן כְּחֶפְצוֹ, \u0010c5\u0011 וּכְשֶׁיַּכְנִיסֶנָּה יִכְתֹּב לָהּ כְּתֻבָּה מָנֶה, וְיִהְיוּ כָּל נְכָסָיו אַחֲרָאִין לִכְתֻבָּתָהּ כִּשְׁאָר כָּל הַנָּשִׁים:\nיְבָמָה שֶׁלֹּא הָיָה לָהּ עַל בַּעְלָהּ כְּתֻבָּה, מִפְּנֵי שֶׁהִיא אֲסוּרָה עָלָיו, וְהִיא מֻתֶּרֶת לַיָּבָם, אִם רָצָה \u0010c6\u0011 כּוֹנֵס וְאֵין לָהּ כְּתֻבָּה, כְּדֶרֶךְ שֶׁלֹּא הָיָה לָהּ עַל בַּעְלָהּ. \u0005 וְדַוְקָא שֶׁלֹּא כָּתַב לָהּ, \u0010c7\u0011 אֲבָל אָסוּר לְהַשְׁהוֹתָהּ בְּלֹא כְּתֻבָּה \u0006 \u0005(הַמ\"מ פ\"ב)\u0006. וְדִינָהּ עִם יְבָמָהּ בָּתוֹסָפוֹת, כְּמוֹ שֶׁהָיָה לָהּ עַל בַּעְלָהּ. אֲבָל אִם לֹא כָּתַב לָהּ בַּעְלָהּ כְּתֻבָּה [אוֹ שֶׁמָכְרָה לוֹ], אוֹ שֶׁמָּחֲלָה לוֹ, צָרִיךְ הַיָּבָם לִכְתֹּב לָהּ כְּתֻבָּה כְּדֶרֶךְ כָּל הָאַלְמָנוֹת. \u0005 הַגָּה: וְכֵן אִם לֹא הָיוּ נְכָסִים לְבַעְלָהּ הָרִאשׁוֹן, יֵשׁ לָהּ כְּתֻבָּה מָנֶה מִשֵּׁנִי, כְּדִין אַלְמָנָה \u0006 \u0005(טוּר)\u0006. \u0005 הָיוּ לָהּ בָּנוֹת מִן הַיָּבָם, אִם יֵשׁ לָהּ כְּתֻבָּה עַל נִכְסֵי יָבָם, \u0010c8\u0011 גַּם הַבָּנוֹת נִזּוֹנוֹת מִן הָאַחִים. וְאִם אֵין לָהּ כְּתֻבָּה עַל נְכָסָיו, גַּם הַבָּנוֹת אֵינָן נִזּוֹנוֹת מִן הָאַחִין, מִכָּל מָקוֹם הָאַלְמָנָה נִזּוֹנֵית כָּל יְמֵי מֵגַר אַלְמְנוּתָהּ \u0006 \u0005(רַ\"ן פֶּרֶק נַעֲרָה)\u0006:",[],["\u0003ויכול להחזירה\u0004. דסד\"א השתא אסורה עליו מחמת איסור אשת אח קמ\"ל ש\"ס:","\u0003על נכסי בעלה הראשון\u0004. עיין בתוס' ובהר\"ן שכתבו מה נ\"מ בזה ששיעבוד על נכסיה ראשון דהא גם נכסי הראשון שלו הוא וכתבו נ\"מ דצריכה לטרוף מן משועבדים דראשון ולא בני חורין דשני ואם מכר השני ואח\"כ נשתדף נכסי הראשון א\"י לגבות משועבדים דשני א\"נ אם גירש השני וכבר חל לגבות כתובתה ואח\"כ נשתדף נכסי הראשון א\"י לגבות מב\"ח דשני תוס' פ' החולץ (יבמות דף ל\"ט) ונשמע מזה נשתדף אם /אם נשתדף/ נכסי הראשון בעוד' תחת השני יש לה כתובה משני אף על גב דבתחלת היבום לא היה לה כתובה צריך אח\"כ לכתוב לה כתובה דאסור לדור עמה בלא כתובה ועיין בנוסח כתובת יבמים בטור סימן קס\"ו דמשמע רק במזונות התחייב את עצמו היבם כתובות יבמים א\"כ אחרי שנשתדף נכסי הראשון צריך לחדש לה כתובה על שמו:","\u0003לפיכך אין היבם רשאי למכור\u0004. אף אם ירצה לכתוב לה כתובה על נכסיו יכולה לעכב תוס' פ' האשה שנפלו אף על גב דחז\"ל תקנו זאת לטובתו שתהא כתובתה על נכסי בעלה הראשון והשתא כשנצרך למכור מנכסי אחיו אי\"ל לא ניחא לי תקנ' חז\"ל מאחר דבתחילה כשייבם אותה לא כתב לה כתובה על נכסיו והסכים לתקנת חז\"ל תו אי\"ל לא ניחא לי כנ\"ל לפ\"ז אם בעת היבום מיד רוצה לכתוב לה כתובה על נכסיו אינה יכולה לעכב ורשאי למכור וצ\"ל לפ\"ז מ\"ש בסמוך דא\"י למכור קודם היבום היינו דוקא כשאינו רוצה לכתוב לה כתובה על נכסיו, מיהו מש\"ס לא משמע כן בעובדא דבעי אחוה למפסלי בגט והקנה לו אחיו חצי נכסי המת ואמר שם דל\"מ מעשיו ולא חילקו בין אם רוצה לכתוב כתובה על נכסיו ובין שאינו רוצה לכתוב כתובה ש\"מ דאין חילוק בדבר וא\"ל שם הטעם משום דאין בידו למכור דעדיין לא זכה בהם א\"כ קשה מה שאמר שם השתא יבם ואח\"כ חלק לא עשה לא כלום חלק ואח\"כ יבם מבעיא דהא ביבם כבר ולא כתב כתובה על נכסיו א\"י למכור הואיל כתובתה על נכסי הראשון וכשמחלק קודם היבום אפשר דיש תקנה דהא יכול לכתוב כתובה על נכסיו ולמה פשיטא הוא דל\"מ ומיהו בש\"ע י\"ל מ\"ש בסמוך ואם מכר קודם היבום לא עשה כלום היינו מטעם זה וכן משמע מרמב\"ם פכ\"ב מה\"א:","\u0003מוציאין מידו\u0004. אף על גב דאחיו אינו כאן אי\"ל לאו בעל דבר דידי את דמוציאין ממנה מדר\"נ שהוא חייב לה כתובה אף על גב דהוא יורש את אחיו מ\"מ א\"י למחול החוב לנפשי' וכמ\"ש בתוס' והרא\"ש והר\"ן שם ס\"פ האשה, ומזה נ\"ל לכאורה אם הניח אחיו כדי כתובה תו אין מוציאין ממנו החוב שחייב לאחיו דהא יכול לומר לאו ב\"ד דידי את ומדר\"נ לא שייך כאן מאחר דהניח כדי כתובה אף על גב דע\"פ הדין משועבד לה כל נכסי בעלה אף שהם שוים יותר מסך כתוב' מ\"מ להוציא מדר\"נ לא שייך מאחר דיש לגבות כתובתה:","\u0003וי\"א שפירות תלושים וכו'\u0004. כ\"כ הרמב\"ם שם הואיל מטלטלין לא נשתעבדו לכתובה אלא מחמת תקנות הגאונים אין כח בתקנה זו למונעו ולדעת הראב\"ד כל מטלטלין ומעות פירות תלושים ימכרו וילקח בהם קרקע אבל אם הוא חייב לאחיו אין מוציאין ממנו משום תרתי לא עבדינן שיהיו מטלטלין משועבדים לכתובה ולהוציא מדר\"נ, וכ\"כ בש\"ג שם וכן אם חולץ לה א\"י לגבות מחוב שלו אבל מחוב של אחר גובה דקי\"ל כתובה נגבית מן מלוה כמ\"ש בסימן ק', ולישב הקושיא לפי הטעם הנ\"ל דלא עבדינן תרתי א\"כ בחוב של אח' נמי תרתי נינהו להוציא מדר\"נ ולגבות מן מטלטלין עיין תוס' ס\"פ האשה דף פ\"ב:","\u0003וכשיכנסנה יכתוב לה כתובה\u0004. ואם לא כתב לה יש לה כתובה מתקנת חז\"ל כשאר נשים:","\u0003כונס ואין לה כתובה\u0004. ב\"ח מדייק דרמב\"ם גם הטור ס\"ל דאין איסור לדור עמה בלא כתובה ולא שייך בזו התקנה שאל תהא בעיניו קלה להוציא' מאחר שנשאה מתחלה לאסור לה תהא בעיניו קלה להוציא אף ע\"ג אם נשאת לאחר בודאי יש לה כתובה שאל תהא קלה בעיניו להוציא מ\"מ ביבם שבא מכח הראשון שהיה אסור לה אין לה כתובה ואף שפוסק לחומרא בהג\"ה דאסור לדור עמה בלא כתובה מ\"מ בדיעבד אם לא כתב לה אין עליו שום חיוב משא\"כ כשהיא מותרת ולא כתב לה כתובה יש לה כתובה מיבם מתיקון חז\"ל כשאר אשה:","\u0003אבל אסור להשהותה וכו'\u0004. בסמוך כתבתי לדעת הרמב\"ם והטור אין איסור ואם היא שני' ליבם ולא לבעל אית לה כתובה על נכסי בעלה, המגיד:","\u0003גם הבנות ניזונות\u0004. ואף אם הניח הראשון נכסים אין לבנות מזונות דהא הוא לא כתב לה אלא בנן נוקבין דיהוי לך מנאי ועיין תוס' פ' נ\"ש דף נ\"ג לפי' ראשון הבעי' קאי היכא דלית לה מראשון א\"כ אית לה משני ומבעי' ליה אם אלימא כמותה למהוי ת\"כ ככתובה לפ\"ז מאחר דעלת' בתיקו אין להבנו' מזונות משני אפי' אם כתובתה על השני וא\"י למה סתם בפשיטות נגד תוס' ואפשר תוס' איירי שלא כתב היבם כתובה על שמו אף על פי כשאין לה מראשון אית לה ממילא משני מ\"מ מבעי' בש\"ס בכה\"ג לענין ת\"כ של הבנות אם אלימא כת\"כ שלה ורמ\"א איירי אם יש לה כתובה מן נכסי יבם היינו שכתב לה כתובה אז דינה כשאר אשה:"]],["\u0003הלכות חליצה\u0004\nמִצְוַת חֲלִיצָה בְּג' דַּיָּנִים יִשְׂרְאֵלִים, וְשֶׁלֹּא יִהְיוּ קְרוֹבִים זֶה לָזֶה וְלֹא לַיָּבָם וְלַיְבָמָה. \u0005 וַאֲפִלּוּ שְׁנַיִם נְשׂוּאִין שְׁתֵּי בְּנוֹת אַחִין, לֹא יִהְיוּ זֶה עִם זֶה. אֲבָל שֵׁנִי בִּשְׁלִישִׁי, כָּשֵׁר \u0006 \u0005(ת\"ה סִימָן רכ\"ו)\u0006. וַאֲפִלּוּ הֵם הֶדְיוֹטוֹת, \u0010c0\u0011 רַק שֶׁיֵּדְעוּ לְהַקְרוֹת אֶת הַיָּבָם וְהַיְבָמָה. וְאִם חָלְצָה בִּפְנֵי עַמֵּי הָאָרֶץ שֶׁאֵינָם יוֹדְעִים לְהַקְרוֹת, כְּשֵׁרָה:\nנִמְצָא אֶחָד מֵהֶם \u0010c1\u0011 קָרוֹב אוֹ פָּסוּל, אוֹ גֵּר, פָּסוּל. \u0010c2\u0011 וַאֲפִלּוּ הָיָה אָבִיו גֵּר וְאִמּוֹ יִשְׂרְאֵלִית, פָּסוּל, עַד שֶׁיְּהֵא אָבִיו וְאִמּוֹ מִיִּשְׂרָאֵל. \u0005 וְיֵשׁ אוֹמְרִים שֶׁאִם אָבִיו מִיִּשְׂרָאֵל, כָּשֵׁר \u0006 \u0005(טוּר בְּשֵׁם סְמַ\"ג)\u0006. וּמִיהוּ, חֲלִיצָה פְּסוּלָה מִיהָא הָוְיָא לְפָסְלָהּ עַל הָאַחִים, אֲפִלּוּ בֵּינוֹ לְבֵינָהּ. \u0005 הַגָּה: יֵשׁ אוֹמְרִים דְּאָסוּר לִקַּח שָׂכָר מֵחֲלִיצָה, דְּהַנּוֹטֵל שָׂכָר לָדוּן דִּינָיו בְּטֵלִין \u0006 \u0005(ר\"י מִינְץ וּמהרא\"י)\u0006, \u0005 וְכֵן נִרְאֶה בְּעֵינַי. בַּחֲלִיצוֹת, יֵשׁ לִזָּהֵר שֶׁלֹּא יֵשֵׁב בִּשְׁלשָׁה דַּיָּנִים שֶׁיּוֹשְׁבִים לַחֲלֹץ מִי שֶׁנּוֹטֵל שָׂכָר, דַּהֲרֵי בָּעִינָן בֵּית דִּין כָּשֵׁר מִדְּאוֹרָיְתָא, וְעַיֵּן בְּחשֶׁן הַמִּשְׁפָּט סִימָן ט' אֵיזֶה שָׂכָר מֻתָּר לַדַּיָּן לְקַבֵּל. וַאֲפִלּוּ בָּזֶה נִרְאֶה לִי לְהַחֲמִיר אִם נוֹטֵל שָׂכָר מִן הַחֲלִיצָה, מִשּׁוּם מַרְאִית הָעַיִן, כְּמוֹ שֶׁמַּחֲמִירִין לְעִנְיַן קְרוֹבִים וּבִשְׁאָר דְּבָרִים לְעִנְיַן בֵּית דִּין שֶׁל חֲלִיצָה, יוֹתֵר מִבִּשְׁאָר בֵּית דִּין. וְרָאִיתִי וְשָׁמַעְתִּי שֶׁהָרַב נוֹטֵל שָׂכָר הַרְבֵּה מִן הַחֲלִיצָה, וְסוֹמֵךְ עַצְמוֹ בַּמֶּה שֶׁמּוֹכֵר לוֹ סַנְדָּל שֶׁל חֲלִיצָה; וְקֻלָּא גְּדוֹלָה הִיא בְּעֵינַי, וְשׁוֹמֵר נַפְשׁוֹ יִרְחַק מִזֶּה. וְלֹא דָּמֵי לְמַה שֶּׁעֵדֵי הַגֵּט נוֹטְלִין שָׂכָר מִטַּעַם שֶׁכָּתַבְתִּי לְעֵיל סִימָן ק\"ל, גַּם הָרַב הַמְסַדֵּר הַגֵּט כְּמוֹ שֶׁכָּתַבְתִּי לְעֵיל בְּסֵדֶר הַגֵּט סָעִיף ד', כִּי אוֹתָן הַטְּעָמִים אֵינָם שַׁיָּכִים בַּחֲלִיצָה \u0006 \u0005(הַכֹּל \u0010c3\u0011 דַּעַת עַצְמוֹ)\u0006:\nלְכַתְּחִלָּה מִצְוָה שֶׁיּוֹסִיפוּ שְׁנַיִם עַל הַג', וַאֲפִלּוּ הַשְּׁנַיִם הֵם עַמֵּי הָאָרֶץ. \u0005 חָלְצוּ בְּג' חֲלִיצָתָהּ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006. \u0005 וְאֵלּוּ הַשְּׁנַיִם שֶׁמּוֹסִיפִים, לֹא יִהְיוּ קְרוֹבִים \u0006 \u0005 וּפְסוּלִים; וְדַוְקָא לְכַתְּחִלָּה, אֲבָל בְּדִיעֲבַד כָּשֵׁר \u0006 \u0005(ב\"י)\u0006:\nצְרִיכִים \u0010c4\u0011 הַדַּיָּנִים לְכַתְּחִלָּה לִקְבֹּעַ מָקוֹם לוֹמַר: נֵלֵךְ לִמְקוֹם פְּלוֹנִי לַחֲלֹץ. \u0005 מִיהוּ, אִם חָלְצָה בְּלֹא קְבִיעוּת מָקוֹם, כָּשֵׁר \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006:\nיֵשׁ קֹבְעִים מָקוֹם בּוֹ בַּיּוֹם, וְיֵשׁ אוֹמְרִים לִקְבֹּעַ בַּיּוֹם שֶׁלְּפָנָיו:\nאֵין חֲלִיצָה כְּשֵׁרָה אֶלָּא בַּיּוֹם. חָלְצָה בַּלַּיְלָה, חֲלִיצָתָהּ פְּסוּלָה:\nאֵין חוֹלְצִין בְּשַׁבָּתוֹת וְלֹא בְּיָמִים טוֹבִים; וּמִיהוּ, בְּחֹל הַמּוֹעֵד, שַׁפִּיר דָּמֵי. \u0005 וְיֵשׁ אוֹמְרִים דְּאֵין לַחֲלֹץ בְּעֶרֶב שַׁבָּת וְעֶרֶב יוֹם טוֹב, וְכֵן נוֹהֲגִין: \u0006\nצָרִיךְ שֶׁיַּכִּירוּ שֶׁהוּא אֲחִי הַמֵּת, וְשֶׁהָיָה בְּעוֹלָמוֹ, וְזֹאת הִיא אֵשֶׁת הַמֵּת; וַאֲפִלּוּ אֵין כָּאן אֶלָּא עֵד אֶחָד שֶׁמֵּעִיד עֲלֵיהֶם, אוֹ אֲפִלּוּ קָרוֹב אוֹ אִשָּׁה אוֹ עֶבֶד אוֹ שִׁפְחָה אוֹ קָטָן שֶׁהוּא מַכִּיר וְנָבוֹן, נֶאֱמָן בְּכָךְ:\nצָרִיךְ שֶׁיֵּדְעוּ הַדַּיָּנִים שֶׁיֵּשׁ צ' יוֹם מִשֶּׁמֵּת הַבַּעַל, חוּץ מִיּוֹם שֶׁמֵּת בּוֹ וְיוֹם שֶׁחוֹלֶצֶת בּוֹ:\nצָרִיךְ שֶׁיֵּדְעוּ שֶׁהַיָּבָם \u0010c5\u0011 בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, וְהַיְבָמָה בַּת י\"ב שָׁנָה וְיוֹם אֶחָד, וְשֶׁהֵבִיאוּ שְׁתֵּי שְׂעָרוֹת אַחַר שֶׁהִגִּיעוּ לִזְמַנִּים אֵלּוּ. וְאִם יֵשׁ לַיְבָמָה \u0010c6\u0011 דַּדִּים גְּדוֹלִים, אֵין צָרִיךְ לִבְדֹּק אַחַר הַשְּׂעָרוֹת. וְכֵן אִם הַיָּבָם \u0010c7\u0011 נִתְמַלֵּא זְקָנוֹ, אֵין צָרִיךְ לִבְדֹּק אַחַר הַשְּׂעָרוֹת. וּמִשְׁפָּט שְׁתֵּי הַשְּׂעָרוֹת וּבְדִיקָתָן, נִתְבָּאֵר בְּסִימָן קנ\"ה \u0005(סָעִיף ט\"ו)\u0006:\nאֵין סוֹמְכִין בְּמִנְיַן הַשָּׁנִים לֹא עַל פִּי קְרוֹבִים וְלֹא עַל פִּי נָשִׁים, אֶלָּא עַל פִּי עֵדִים כְּשֵׁרִים לְהָעִיד. \u0010c8\u0011 וְיֵשׁ אוֹמְרִים שֶׁאִם הֻחְזַק בְּעֵינֵי הַשְּׁכֵנִים, שֶׁלֹּא עַל פִּי הָאָב, שֶׁבָּא לִכְלַל שָׁנִים, אוֹ שֶׁיָּצָא עָלָיו קוֹל שֶׁבָּא לִכְלַל שָׁנִים, נֶאֱמָנִים לְהַחֲזִיקָן בִּגְדוֹלִים, אִם בְּדָקוּם וּמָצְאוּ לָהֶם שְׁתֵּי שְׂעָרוֹת, \u0005 אֲבָל לֹא מְהַנֵּי שֶׁרָאוּ אוֹתוֹ שֶׁעָלָה לְסֵפֶר תּוֹרָה אוֹ שֶׁהָיָה שְׁלִיחַ צִבּוּר \u0006 \u0005(מָרְדְּכַי פֶּרֶק מִצְוַת חֲלִיצָה)\u0006. וַאֲפִלּוּ בְּלֹא חֶזְקַת הַשְּׁכֵנִים, אִם יֵשׁ לָהֶם רִבּוּי שְׂעָרוֹת, אוֹ שֶׁהֵם אֲרֻכּוֹת כְּמוֹ שֶׁרְגִילוֹת לְאִישׁ גָּדוֹל וּלְאִשָּׁה גְּדוֹלָה, חֲזָקָה שֶׁבָּאוּ לִכְלַל שָׁנִים, וְחוֹלְצִים. \u0010c9\u0011 וְעַל זֶה סוֹמְכִים שֶׁלֹּא לִבְדֹּק אִם יֵשׁ גֻּמּוֹת בַּשְּׂעָרוֹת, מֵאַחַר שֶׁיֵּשׁ רִבּוּי שְׂעָרוֹת אוֹ שֶׁהֵם אֲרֻכּוֹת. וְאִם הֵם גְּדוֹלִים בְּקוֹמָה, יֵשׁ לִסְמֹךְ שֶׁהֵם גְּדוֹלִים, אֲפִלּוּ לֹא הֵבִיאוּ כִּי אִם שְׁתֵּי שְׂעָרוֹת. \u0010c10\u0011 \u0005 וְאִם יֵשׁ לַיְבָמָה בָּנִים, הֲרֵי הֵם כְּסִימָנִים \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דִּיבָמוֹת)\u0006:\nיֵשְׁבוּ הַדַּיָּנִים כְּמוֹ שֶׁצְּרִיכִים לֵישֵׁב בְּדִין, וְיַעַמְדוּ לִפְנֵיהֶם הַיָּבָם וְהַיְבָמָה, \u0010c11\u0011 שֶׁמִּצְוַת חֲלִיצָה לְכַתְּחִלָּה, מְעֻמָּד. \u0005 הַגָּה: אֲבָל בְּדִיעֲבַד, אִם חָלְצָה מְיֻשָּׁב, כָּשֵׁר (טוּר)\u0006. וְכֵן חוֹלֶה שֶׁלֹּא יוּכַל לַעֲמֹד, יוּכַל לַחֲלֹץ מְיֻשָּׁב, דְּכָל דָּבָר שֶׁאֵין לוֹ תַּקָּנָה חָשׁוּב דִּיעֲבַד \u0005(פִּסְקֵי מהרא\"י סִימָן ק\"צ)\u0006. \u0005 וְעַיֵּן לְקַמָּן סָעִיף ס\"ד בְּפֵרוּשׁ סֵדֶר חֲלִיצָה: \u0006\nמֵאַחַר שֶׁמַּסְכִּים הַיָּבָם לַחֲלֹץ, יֹאמְרוּ לוֹ לְבַטֵּל כָּל מוֹדָעוֹת שֶׁמָּסַר, כְּמוֹ גַּבֵּי גֵּט; שֶׁאִם מָסַר מוֹדָעָא תְּחִלָּה, הַחֲלִיצָה פְּסוּלָה. \u0005 הַגָּה: וְכֵן אִם כָּפוּ אוֹתוֹ לַחֲלֹץ, דִּינוֹ כְּמוֹ בְּגֵט. וְעַיֵּן לְעֵיל סִימָן קל\"ד. וְאַף עַל גַּב דְּיֵשׁ אוֹמְרִים מִצְוַת חֲלִיצָה קוֹדֵם, וְאִם כֵּן כָּל כְּפִיָּה הִיא בַּדִּין, מִכָּל מָקוֹם אֵין לָכֹף אֶלָּא בְּמָקוֹם שֶׁנִּתְבָּאֵר סִימָן קס\"ה: \u0006\nלְכַתְּחִלָּה צָרִיךְ לָתֵת לַיָּבָם מִנְעַל הַחֲלִיצָה בְּמַתָּנָה. וְיֵשׁ אוֹמְרִים שֶׁיְּהַלֵּךְ בּוֹ מְעַט, כְּדֵי שֶׁיְּהֵא נִרְאֶה כְּשֶׁלּוֹ. \u0005 וְאִם לֹא נָתְנוּ לוֹ, כָּשֵׁר \u0006 \u0005(טוּר)\u0006:\nהַמִּנְעָל צָרִיךְ שֶׁיִּהְיֶה כֻּלּוֹ שֶׁל עוֹר. לְפִיכָךְ, צָרִיךְ לְתָפְרוֹ \u0005 כָּל תְּפִירוֹתָיו \u0006 בְּעוֹר לְכַתְּחִלָּה. \u0005 וְכֵן נוֹהֲגִין; \u0010c12\u0011 וְיֵשׁ פּוֹסְלִין אַף בְּדִיעֲבַד \u0006 \u0005(טוּר בְּשֵׁם הָרְמַ\"ה)\u0006. \u0005 דְּלֹא כְּיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה שֶׁכָּל הַמִּנְעָלִים תְּפוּרִין בְּפִשְׁתָּן צָרִיךְ לִהְיוֹת תָּפוּר בְּפִשְׁתָּן \u0006 \u0005(בְּסֵדֶר ר\"י מִינְץ בְּשֵׁם ר' שְׁמַרְיָה)\u0006. \u0010c13\u0011 אֲבָל רְצוּעוֹתָיו אֵין צָרִיךְ שֶׁיִּהְיוּ מֵעוֹר. \u0005 וְיֵשׁ אוֹמְרִים דְּגַם רְצוּעוֹתָיו מֵעוֹר \u0006 \u0005(נִמּוּקֵי יוֹסֵף)\u0006, \u0005 וְכֵן \u0006 \u0005 נוֹהֲגִין: \u0010c14\u0011 \u0006\nצָרִיךְ לְכַתְּחִלָּה שֶׁיְּהֵא הָעוֹר קָשֶׁה קְצָת, שֶׁיְּהֵא דּוֹמֶה קְצָת לְסַנְדָּל. וְיֵשׁ אוֹמְרִים שֶׁהַתְּפִירָה תִּהְיֶה מִבַּחוּץ. יֵשׁ אוֹמְרִים מִבִּפְנִים, כְּדֵי שֶׁיְּהֵא דּוֹמֶה לְסַנְדָּל. וְיֵשׁ אוֹמְרִים שֶׁלֹּא יְהֵא בֶּגֶד אוֹ עוֹר מִבִּפְנִים וְתָפְרוֹ בּוֹ. וְיֵשׁ אוֹמְרִים שֶׁעוֹשִים אוֹתוֹ מֵחֲתִיכָה אַחַת, כְּדֵי שֶׁיְּהֵא דּוֹמֶה גַּם בָּזֶה לְסַנְדָּל. \u0005 הַגָּה: אֲבָל נָהֲגוּ לַחֲלֹץ לְכַתְּחִלָּה בְּמִנְעָל שֶׁהוּא תָּפוּר מִבַּחוּץ, וְגַם שֶׁהוּא מִשְּׁנֵי חֲתִיכוֹת, דְּהַיְנוּ שֶׁהַתַּחְתּוֹן שֶׁלּוֹ שֶׁקּוֹרִין שׁול\"א הוּא חֲתִיכָה אַחֶרֶת. וְגַם הָרְצוּעוֹת הֵם חֲתִיכָה אַחֶרֶת תְּפוּרִין בּוֹ. וְיִזָּהֲרוּ שֶׁלֹּא תִּהְיֶה הָעוֹר שֶׁל הַסַּנְדָּל מְשׁוּחָה בְּשֶׁמֶן \u0006 \u0005 לְרַכְּכוֹ \u0006 \u0005(בִּסְדָרִים)\u0006:\nיֵשׁ אוֹמְרִים שֶׁלְּכַתְּחִלָּה עוֹשִׂין אוֹתוֹ מֵעוֹר בְּהֵמָה טְהוֹרָה. \u0005 גַּם הָרְצוּעוֹת וְהַקְּרָסִים שֶׁבּוֹ, גַּם רְצוּעוֹת הַתְּפִירָה \u0006 \u0005(כ\"כ בְּסֵדֶר ר\"י מַרְגָּלִיוֹת)\u0006, \u0005 וְכֵן נוֹהֲגִין: \u0010c15\u0011 \u0006\nיִהְיוּ בּוֹ שְׁתֵּי רְצוּעוֹת לְקָשְׁרוֹ בָּהֶם, אַחַת בְּצַד זֶה וְאַחַת בְּצַד זֶה. וְיֵשׁ אוֹמְרִים שֶׁרְצוּעוֹת אֵלּוּ יִהְיוּ לְבָנוֹת. \u0005 וְגַם רְצוּעוֹת הַתְּפִירָה יִהְיוּ לְבָנִים. אֲבָל הַשְׁאָר, הַכֹּל שָׁחוֹר מִבַּחוּץ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי דִּיבָמוֹת)\u0006, \u0005 וְכֵן נוֹהֲגִים. אֲבָל מִבִּפְנִים, אֵין לָחוּשׁ. וְאִם הֻשְׁחֲרוּ הָרְצוּעוֹת מֵחֲמַת זִקְנָה, אֵין לְהַקְפִּיד \u0006 \u0005(פִּסְקֵי מהרא\"י סִימָן ר\"ה)\u0006, \u0005 וְכֵן נוֹהֲגִין. וְיִהְיוּ הָרְצוּעוֹת אֲרֻכּוֹת, שֶׁיּוּכַל לִכְפֹּל כָּל אַחַת שְׁתֵּי פְּעָמִים \u0006 \u0005(כָּל בּוֹ)\u0006:\nיַעֲשׂוּ בּוֹ כְּמִין קֶשֶׁר, שֶׁקּוֹרִים חֻמַרְתָּא, בַּצַּד הָאֶחָד, שֶׁיִּכָּנֵס בַּנֶּקֶב שֶׁבַּצַּד הָאַחֵר כְּדֵי לְהַדְּקוֹ יָפֶה. וְיֵשׁ אוֹמְרִים שֶׁיַּעֲשׂוּ שְׁלשָׁה קְשָׁרִים בְּעִנְיָן זֶה, וּלְפָחוֹת שְׁתַּיִם. \u0005 הַגָּה: וְנוֹהֲגִים לַעֲשׂוֹת שְׁלשָׁה. וְלֹא יִהְיוּ הַקְּשָׁרִים מִן הַמִּנְעָל עַצְמוֹ, אֶלָּא רְצוּעָה אַחֶרֶת מְחֻבֶּרֶת בְּרֹאשׁ הַמִּנְעָל. וְכֵן יַעֲשֶׂה הַקְּרָסִים שֶׁבַּצַּד הַשֵּׁנִי \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006 \u0005 וְכֵן נוֹהֲגִין. וְיִתְפֹּר אֵלּוּ הַלּוּלָאוֹת וְהַקְּרָסִים \u0006 \u0005 מִבַּחוּץ, וְלֹא מִבִּפְנִים, וְכֵן נוֹהֲגִין: \u0006\nיֵשׁ אוֹמְרִים שֶׁלֹּא יִהְיֶה לוֹ לָשׁוֹן כְּמוֹ שֶׁרְגִילִים לַעֲשׂוֹת בְּמִנְעָלִים, \u0010c16\u0011 כְּדֵי שֶׁלֹּא יְהֵא מֵעַל דְּמֵעַל. \u0005 הַגָּה: יֵשׁ אוֹמְרִים לִתְפֹּר שָׂפָה סְבִיב הַמִּנְעָל לְמַעְלָה \u0006 \u0005(ר\"י מִינְ\"ץ בְּשֵׁם ראבי\"ה)\u0006, \u0005 וְלֹא נָהֲגוּ כֵּן. וְיִזָּהֵר לְתָפְרוֹ בִּתְפִירוֹת תְּכוּפוֹת זוֹ לָזוֹ \u0006 \u0005(בְּסֵדֶר ר\"י מַרְגָּלִיוֹת)\u0006. \u0005 וְעוֹשִׂין אָזְנֵי הַמִּנְעָל קְצָרִים, שֶׁלֹּא יִהְיוּ הַלּוּלָאוֹת וְהַקְּרָסִים עַל הַמִּנְעָל, רַק עַל הָרֶגֶל, שֶׁלֹּא יִהְיֶה מֵעַל דְּמֵעַל \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006:\nיְהֵא עָשׂוּי לְצוּרַת רֶגֶל יְמָנִית, וְיִנְעֲלוֹ בְּרַגְלוֹ הַיְמָנִית; וְיִהְיֶה לְמִדַּת רַגְלוֹ, שֶׁלֹּא יְהֵא גָּדוֹל עַד שֶׁאֵין רָאוּי לֵילֵךְ בּוֹ, וְלֹא יִהְיֶה קָטָן עַד שֶׁאֵינוֹ מְכַסֶה רֹב הָרֶגֶל. וְלֹא יִהְיֶה קָרוּעַ עַד שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ:\nחָלְצָה בְּסַנְדָּל שֶׁל עֵץ אוֹ שֶׁל שַׁעַם \u0010c17\u0011 שֶׁאֵינָם מְחֻפִּים עוֹר, אוֹ בְּרֶגֶל שְׂמֹאל, אוֹ שֶׁהָיָה מִנְעָל גָּדוֹל עַד שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ, אוֹ קָטָן שֶׁאֵינוֹ מְכַסֶה רֹב רַגְלוֹ, אוֹ קָרוּעַ שֶׁאֵינוֹ יָכוֹל לֵילֵךְ בּוֹ, אוֹ בְּסַנְדָּל \u0010c18\u0011 שֶׁאֵין לוֹ עָקֵב, אוֹ \u0010c19\u0011 בְּאַנְפִּלְיָא שֶׁל בֶּגֶד, חֲלִיצָתוֹ פְּסוּלָה. \u0010c20\u0011 \u0005 הָיָה שֶׁל עֵץ וּמְחֻפֶּה עוֹר, אוֹ שֶׁבֶּגֶד פִּשְׁתָּן תָּפוּר בִּפְנִים, אוֹ שֶׁחָלַץ בְּמִנְעָל שֶׁל שְׂמֹאל בְּיָמִין, כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006: \u0010c21\u0011\nמִנְעָל שֶׁל עוֹבְדֵי אֶלִילִים שֶׁמַּנִּיחִים אוֹתוֹ לְרַגְלֵי הַצּוּרָה וּמְהַלְּכִין אוֹתָהּ בּוֹ, לֹא תַּחֲלֹץ בּוֹ; וְאִם חָלְצָה, חֲלִיצָתָהּ כְּשֵׁרָה. אֲבָל בְּשֶׁל \u0010c22\u0011 תִּקְרֹבֶת עֲבוֹדָה זָרָה, אוֹ שֶׁל עִיר הַנִּדַּחַת, אוֹ שֶׁנַּעֲשֵׂית לְתַכְרִיכֵי הַמֵּת, אִם חָלְצָה, חֲלִיצָתָהּ פְּסוּלָה:\nשׁוֹלֵט בִּשְׁתֵּי רַגְלָיו, וְכֵן הִיא בִּשְׁתֵּי יָדֶיהָ, יַעֲשׂוּ בְּשֶׁל יָמִין. \u0005 וְאִם הִיא אִטֶּרֶת יָד, תַּעֲשֶׂה בְּיָמִין דִּידַהּ, שֶׁהוּא שְׂמֹאל כָּל אָדָם \u0006 \u0005(טוּר בְּשֵׁם י\"א)\u0006:\nאִטֵּר בְּרַגְלוֹ, \u0010c23\u0011 יֵשׁ אוֹמְרִים שֶׁחוֹלֵץ בִּשְׁתֵּיהֶם, בְּמִנְעָל שֶׁל יָמִין בְּיָמִין, וּבְמִנְעָל שֶׁל שְׂמֹאל בִּשְׂמֹאל. וְיֵשׁ מִי שֶׁנִּסְתַּפֵּק לוֹמַר שֶׁאֵין לוֹ תַּקָּנָה. \u0005 וְנָהֲגוּ כַּסְּבָרָא הָרִאשׁוֹנָה, וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף מ': \u0006\nיִנְעַל הַמִּנְעָל עַל רַגְלוֹ כְּשֶׁהוּא יָחֵף, וְלֹא עַל בָּתֵּי \u0010c24\u0011 שׁוֹקַיִם, שֶׁלֹּא יְהֵא מֵעַל דְּמֵעַל. וּמִטַּעַם זֶה יֵשׁ מְדַקְדְּקִים שֶׁלֹּא יְהֵא טִיט דָּבוּק בַּמִּנְעָל מִבִּפְנִים, וְגַם מִטַּעַם זֶה יֵשׁ מַצְרִיכִים לִרְחֹץ רַגְלוֹ הַיְמָנִית יָפֶה יָפֶה:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהַיָּבָם קוֹשֵׁר כְּנַף הַמִּכְנָסַיִם לְמַעְלָה מִשּׁוֹקוֹ, \u0005 כְּדֵי שֶׁיִּרְאוּ הַדַּיָּנִים הֵיטֵב שֶׁאֵין דָּבָר בֵּין רַגְלוֹ וּבֵין מִנְעָלוֹ \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006:\nיִנְעַל הַמִּנְעָל וְיִכְרֹךְ הָרְצוּעוֹת סָבִיב לַמִּנְעָל בְּרַגְלוֹ, וְיִקְשֹׁר שְׁנֵיהֶם יַחַד שְׁנֵי קְשָׁרִים זֶה עַל זֶה, \u0005 וְאַל יְהַדֵּק קֶשֶׁר הַשֵּׁנִי בְּחֹזֶק, כְּדֵי שֶׁתּוּכַל לְהַתִּירוֹ בְּיָמִין \u0006 \u0005(כֵּן עָשָׂה מַהֲרִי\"ל וְכֵן מַשְׁמַע בַּסְמַ\"ג)\u0006, וַעֲנִיבָה עֲלֵיהֶם. וְצָרִיךְ שֶׁיִּהְיֶה הַקֶּשֶׁר עַל בְּשַׂר שׁוֹקוֹ, וְלֹא עַל אָזְנֵי הַמִּנְעָל, לְכָךְ צָרִיךְ שֶׁיַּחְתֹּךְ בַּמִּנְעָל לְפָנָיו וּלְאַחֲרָיו כְּמוֹ פְּגִימָה, כְּדֵי שֶׁתְּהֵא הָרְצוּעָה הַחוֹזֶרֶת דְּבוּקָה מַמָּשׁ עַל רַגְלוֹ יָחֵף. וִיסַבֵּב הָרְצוּעוֹת פַּעֲמַיִם סָבִיב לַשּׁוֹק, עַד שֶׁיָּשׁוּבוּ רָאשֵׁי הָרְצוּעוֹת \u0005(עַל הַשּׁוֹק לְפָנִים)\u0006 \u0005 מִמַּעַל לְאָזְנֵי הַמִּנְעָל \u0006 \u0005(הַגָּהוֹת מָרְדְּכַי)\u0006, \u0010c25\u0011 עַל הַשּׁוֹק עָרֹם. וְיִהְיוּ הַקְּשָׁרִים עַל פְּנֵי הַשּׁוֹק וְלֹא מֵאֲחוֹרָיו. וְיַכְנִיס הַקְּשָׁרִים \u0005(שֶׁבְּאָזְנוֹ)\u0006 בַּנְּקָבִים שֶׁבְּאָזְנוֹ \u0010c26\u0011 הַשְּׁנִיָּה:\nמְלַמְּדִין אוֹתָהּ וְאֶת הַיָּבָם לִקְרוֹת, עַד שֶׁהוּא וְהִיא יִהְיוּ רְגִילִים, וְתִהְיֶה יְכוֹלָה לִקְרוֹת \"לֹא אָבָה\" \u0010c27\u0011 \u0005(דְּבָרִים כה, ז)\u0006 בִּנְשִׁימָה אַחַת. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁצָּרִיךְ גַּם כֵּן שֶׁהוּא יִהְיֶה יָכוֹל לוֹמַר: \"לֹא חָפַצְתִּי\" \u0005(דברים כה, ח)\u0006 בִּנְשִׁימָה אַחַת. וְיִקְרְאוּ אוֹתָהּ, וְהִיא מְעֻמָּד, בִּלְשׁוֹן \u0010c28\u0011 הַקֹּדֶשׁ: \"מֵאֵן יְבָמִי לְהָקִים לְאָחִיו שֵׁם בְּיִשְׂרָאֵל לֹא אָבָה יַבְּמִי\" \u0005(דְּבָרִים כה, ז)\u0006 וְיִקְרְאוּ אוֹתוֹ, וְהוּא מְעֻמָּד; לֹא חָפַצְתִּי לְקַחְתָּהּ \u0005(דְּבָרִים כה, ח)\u0006 \u0005 וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ שֶׁיְּדַקְדְּקוּ עִמָּהּ שֶׁהִיא תִּקְרָא: \"לֹא אָבָה יַבְּמִי\", בִּנְשִׁימָה אַחַת \u0006 \u0005(טוּר)\u0006. \u0005 וְכֵן הוּא הַמִּנְהָג. גַּם בְּ\"לֹא חָפַצְתִּי לְקַחְתָּהּ\". וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף ס\"ו: \u0006\nיַעֲמֹד אֵצֶל כֹּתֶל אוֹ אֵצֶל עַמּוּד וְיִשָּׁעֵן בּוֹ, וְיִדְחֹק רַגְלוֹ בַּקַּרְקַע, וְתַתִּיר קִשְׁרֵי הַמִּנְעָל, וְאַחַר כָּךְ הַקְּרָסִים, הַכֹּל בְּיָדָהּ הַיְמָנִית, וְתִתְפֹּס רַגְלוֹ בְּיָדָהּ הַשְּׂמָאלִית, וְתִהְיֶה שׁוֹמֶטֶת הַמִּנְעָל מִן הָעָקֵב בְּיָדָהּ הַיְמָנִית, וְתַחֲלֹץ כָּל הַמִּנְעָל גַּם בְּיָדָהּ הַיְמָנִית, וְכָל זֶה בְּלִי סִיּוּעַ יָד שְׂמָאלִית. וּבְכָל זֶה לֹא תִּהְיֶה יוֹשֶׁבֶת, וְלֹא עַל בִּרְכֶּיהָ, אֶלָּא תִּהְיֶה מְעֻמָּד, וְתָכֹף עַצְמָהּ. וּמַשְׁלֶכֶת הַמִּנְעָל לָאָרֶץ. \u0005 חָלְצָה בְּיָדָהּ הַשְּׂמָאלִית אוֹ בְּשִׁנֶּיהָ, כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006:\nגִּדֶּמֶת, חוֹלֶצֶת \u0010c29\u0011 בְּשִׁנֶּיהָ:\nיֵשׁ אוֹמְרִים, שֶׁאִם לֹא דָּחַק רַגְלוֹ בַּקַּרְקַע, חֲלִיצָתָהּ פְּסוּלָה:\nהִתִּיר הוּא הַקֶּשֶׁר, וְשָׁמְטָה הִיא הַמִּנְעָל מֵרַגְלוֹ; אוֹ שֶׁהִתִּירָה הִיא, וְשָׁמַט הוּא, חֲלִיצָתָהּ פְּסוּלָה. \u0005 הַגָּה: \u0010c30\u0011 וְיֵשׁ אוֹמְרִים דַּוְקָא שֶׁאֵינוֹ יָכוֹל לַהֲלֹךְ בּוֹ בְּלֹא קְשִׁירָה; אֲבָל אִם יָכוֹל לַהֲלֹךְ בּוֹ בְּלֹא קְשִׁירָה, וְחָלְצָה אוֹתוֹ, הַחֲלִיצָה כְּשֵׁרָה אַף עַל פִּי שֶׁהוּא הִתִּיר הַקֶּשֶׁר \u0006 \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006:\nהָיְתָה רַגְלוֹ עֲקֻמָּה לְאָחוֹר, אוֹ הֲפוּכָה עַל צִדָּהּ, אוֹ שֶׁמְּהַלֵּךְ עַל אֶצְבְּעוֹת רַגְלָיו, אֵינוֹ חוֹלֵץ:\nחָלְצָה מִן הָאַרְכֻּבָּה וּלְמַטָּה, חֲלִיצָתָהּ כְּשֵׁרָה. \u0010c31\u0011 מִן הָאַרְכֻּבָּה וּלְמַעְלָה, חֲלִיצָתָהּ פְּסוּלָה. וְיֵשׁ אוֹמְרִים דְּאַקְּשִׁירָה קָאֵי, שֶׁאִם הָיָה הַקֶּשֶׁר לְמַעְלָה מֵהָאַרְכֻּבָּה, פְּסוּלָה. אֲבָל אִם נִקְטְעָה רַגְלוֹ, אֲפִלּוּ מִן הָאַרְכֻּבָּה וּלְמַטָּה, \u0010c32\u0011 אֵינוֹ חוֹלֵץ. \u0005 וְעַל כֵּן לֹא יִהְיֶה הַמִּנְעָל אָרֹךְ עַד לְמַעְלָה מִן הָאַרְכֻּבָּה \u0006 \u0005(מָרְדְּכַי רֵישׁ מִצְוַת חֲלִיצָה)\u0006. \u0010c33\u0011 וְיֵשׁ אוֹמְרִים דִּבְנִקְטְעָה רַגְלוֹ מַיְרֵי, שֶׁאִם נִקְטְעָה לְמַטָּה מֵהָאַרְכֻּבָּה וְנִשְׁאַר כָּל כָּךְ מִשּׁוֹקוֹ שֶׁיָּכוֹל לְהַכְנִיס בּוֹ הַמִּנְעָל \u0010c34\u0011 וּלְקָשְׁרוֹ לְמַטָּה מֵהָאַרְכֻּבָּה, חוֹלֵץ: \u0010c35\u0011\nקָרְעָה הַמִּנְעָל מַעַל רַגְלוֹ, אוֹ שֶׁשְּׂרַפְתּוֹ, פְּסוּלָה:\nהָיָה לָבוּשׁ שְׁנֵי מִנְעָלִים, \u0010c36\u0011 וְחָלְצָה הָעֶלְיוֹן, אַף עַל פִּי שֶׁקָּרְעָה הַתַּחְתּוֹן עַד שֶׁנִּתְגַּלֵּית רַגְלוֹ, חֲלִיצָתָהּ פְּסוּלָה. \u0005 אֲבָל אִם חָלְצָה \u0006 \u0005 שְׁנֵיהֶם, חֲלִיצָתָהּ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006:\nתַּעֲמֹד נֶגֶד הַיָּבָם, וְתִירַק בָּאָרֶץ כְּנֶגֶד פְּנֵי הַיָּבָם, רֹק הַנִּרְאֶה לַדַּיָּנִים כְּשֶׁיֵּצֵא מִפִּיהָ \u0010c37\u0011 עַד שֶׁיַּגִּיעַ לִפְנֵי הַיָּבָם. וְאִם לֹא רָאוּ הַדַּיָּנִים כְּשֶׁיָּצָא הָרֹק מִפִּיהָ, \u0010c38\u0011 כְּשֵׁרָה:\nרָקְקָה וּקְלַטְתּוֹ הָרוּחַ קֹדֶם שֶׁהִגִּיעַ נֶגֶד פָּנָיו, כְּגוֹן שֶׁהִיא אֲרֻכָּה מִמֶּנּוּ, \u0010c39\u0011 צְרִיכָה לִירֹק פַּעַם אַחֶרֶת. אֲבָל לְאַחַר שֶׁהִגִּיעַ הָרֹק נֶגֶד פָּנָיו, אֲפִלּוּ לֹא הִגִּיעַ לָאָרֶץ, כְּשֵׁרָה. לְפִיכָךְ, אִם הוּא אָרֹךְ וְהִיא קְצָרָה, קָרֵינָן בֵּהּ שַׁפִּיר \"בְּפָנָיו\" \u0005(דְּבָרִים כה, ט)\u0006:\nיְבָמָה שֶׁרָקְקָה דָּם, \u0010c40\u0011 אֵינָהּ צְרִיכָה לִירֹק פַּעַם אַחֶרֶת. וְיֵשׁ אוֹמְרִים דְּדַוְקָא בְּמוֹצֶצֶת, מִשּׁוּם דְּאִי אֶפְשָׁר לָהּ בְּלֹא צִחְצוּחֵי רֹק:\nאָכְלָה שׁוּם אוֹ גַּרְגֵּר וְכַיּוֹצֵא בּוֹ, מִדְּבָרִים הַמַּרְבִּים \u0010c41\u0011 רֹק, וְהָיָה רֹק זָב מִפִּיהָ, אֵינוֹ כְּלוּם. וְנָהֲגוּ לְמָנְעָהּ מִלֶּאֱכֹל כְּלוּם. \u0005 וְכֵן לִשְׁתּוֹת, וּתְמַעֵט בְּדִבּוּר, כְּדֵי שֶׁיָּבֹא הָרֹק מֵעַצְמוֹ. גַּם לֹא תְּנַקֵּר שִׁנֶּיהָ, כְּדֵי שֶׁלֹּא תִּרֹק דָּם \u0006 \u0005(כ\"ז בִּסְדָרִים)\u0006:\nאַחַר כָּךְ מַקְרִין אוֹתָהּ מְעֻמָּד: \"כָּכָה יֵעָשֶׂה לָאִישׁ אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו, וְנִקְרָא שְׁמוֹ בְּיִשְׂרָאֵל בֵּית חֲלוּץ הַנָּעַל\" \u0005(דְּבָרִים כה, ט י)\u0006. וּמִצְוָה לְכָל הָעוֹמְדִים לוֹמַר: \"חֲלוּץ הַנַּעַל\", \u0010c42\u0011 שָׁלשׁ פְּעָמִים. וְיֵשׁ אוֹמְרִים שֶׁגַּם הַיְבָמָה תֹּאמַר כֵּן:\nנִמְצָא סֵדֶר הַחֲלִיצָה: קוֹרְאָה \"מֵאֵן יְבָמִי\" \u0005(דְּבָרִים כה, ז)\u0006, וְקוֹרֵא \"לֹא חָפַצְתִּי לְקַחְתָּהּ\" \u0005(דְּבָרִים כה, ח)\u0006, וְחוֹלֶצֶת, וְרוֹקֶקֶת, וְקוֹרְאָה \"כָּכָה יֵעָשֶׂה לָאִישׁ\" \u0005(דְּבָרִים כה, ט י)\u0006 וְאֵין הַסֵדֶר מְעַכֵּב. וְלֹא עוֹד, אֶלָּא אֲפִלּוּ לֹא קָרְאָה וְלֹא רָקְקָה, אֶלָּא שֶׁחָלְצָה בִּלְבַד, הַחֲלִיצָה כְּשֵׁרָה. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיוּ יְכוֹלִים לְדַבֵּר, שֶׁהֲרֵי הֵם רְאוּיִם לִקְרוֹת. אֲבָל אִלֵּם וְאִלֶּמֶת וּקְטַנָּה, אֵינָם חוֹלְצִין, וְאִם חָלְצוּ, חֲלִיצָתָן פְּסוּלָה; וְאֵינָהּ כְּשׁוֹטֶה וְקָטָן, שֶׁלֹּא עָשׂוּ כְּלוּם, שֶׁאֵינָהּ נִפְסֶלֶת לָאַחִים וִיכוֹלָה לְהִתְיַבֵּם לָהֶם אוֹ לוֹ. \u0010c43\u0011 וְיֵשׁ אוֹמְרִים דְּהוּא הַדִּין לַחֲלִיצַת חֵרֵשׁ וְחֵרֶשֶׁת שֶׁאֵינָהּ כְּלוּם. וְיֵשׁ אוֹמְרִים שֶׁחֲלִיצָתָן פְּסוּלָה, כְּמוֹ שֶׁל אִלֵּם וְאִלֶּמֶת:\nצָרִיךְ שֶׁיְּכַוְּנוּ הַיָּבָם וְהַיְבָמָה שֶׁתְּהֵא מֻתֶּרֶת לְזָר בַּחֲלִיצָה זוֹ. \u0010c44\u0011 נִתְכַּוֵּן הוּא וְלֹא הִיא, אוֹ הִיא וְלֹא הוּא, לֹא הֻתְּרָה; אֲבָל חֲלִיצָה פְּסוּלָה הִיא לְפָסְלָהּ עַל הָאַחִים. לְפִיכָךְ, יְבָמָה שֶׁגָּדְלָה בֵּין הָאַחִים, וְרָאִינוּ שֶׁחָלְצָה נַעֲלוֹ שֶׁל אֶחָד מֵהֶם, אֲסוּרָה לְהִתְיַבֵּם, שֶׁמָּא כִּוְּנוּ לְשֵׁם חֲלִיצָה; וּצְרִיכָה חֲלִיצָה כְּשֵׁרָה, לְהַתִּירָהּ לְזָר; אֲבָל כָּל זְמַן שֶׁלֹּא רָאִינוּ שֶׁחָלְצָה לְאֶחָד מֵהֶם, מֻתֶּרֶת לְהִתְיַבֵּם, וְאֵין חוֹשְׁשִׁין שֶׁמָּא חָלְצָה:\nוְכֵן אִם רָקְקָה לִפְנֵי הַיָּבָם \u0010c45\u0011 בִּפְנֵי בֵּית דִּין, נִפְסְלָה \u0010c46\u0011 מִלְּהִתְיַבֵּם. וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהָנֵי מִלֵּי כְּשֶׁרָקְקָה רֹק, אֲבָל אִם רָקְקָה דָּם, וְאֵין רֹק מְעֹרָב בּוֹ, אֵינָהּ נִפְסֶלֶת בְּכָךְ:\nיֵשׁ מִי שֶׁאוֹמֵר, שֶׁיֵּשׁ לִזָּהֵר שֶׁלֹּא תִּירֹק הַיְבָמָה לִפְנֵי הַיָּבָם קֹדֶם חֲלִיצָה, כְּדֵי שֶׁלֹּא תְּהֵא חֲלִיצָה פְּסוּלָה וּתְהֵא צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים:\nאִם קָרְאָה לְבַד, לֹא נִפְסְלָה בְּכָךְ \u0010c47\u0011 מִלְּהִתְיַבֵּם:\nהַסוּמָא, אֵינוֹ חוֹלֵץ לְכַתְּחִלָּה. וְאִם חָלַץ, חֲלִיצָתוֹ כְּשֵׁרָה. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם אֵין אָח אֶלָּא הוּא, חוֹלֶצֶת לְכַתְּחִלָּה, \u0005 כְּדֵי שֶׁלֹּא תִּתְעַגֵּן \u0006 \u0005(ב\"י מ\"כ)\u0006. \u0005 וְלֹא מִקְּרֵי סוּמָא, אֶלָּא בִּשְׁתֵּי עֵינָיו \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006:\nקְטַנָּה שֶׁחָלְצָה לְגָדוֹל, \u0010c48\u0011 חֲלִיצָתָהּ פְּסוּלָה וְנִפְסְלָה עַל כָּל הָאַחִים. \u0005 וּכְשֶׁתַּגְדִּיל, תַּחֲלֹץ מֵאֶחָד מֵהֶם, \u0010c49\u0011 וְאֵינָהּ צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים: \u0006\nחֲלִיצָה מֻטְעֵת, שֶׁאוֹמְרִים לוֹ: חֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לְךָ מָאתַיִם זוּז, הַחֲלִיצָה כְּשֵׁרָה, אֲפִלּוּ אֵינָהּ נוֹתֶנֶת לוֹ כְּלוּם, וַאֲפִלּוּ כָּפַל הַתְּנַאי. \u0005 וַאֲפִלּוּ אָמַר לָהּ בִּשְׁעַת הַחֲלִיצָה: \u0010c50\u0011 עַל מְנָת שֶׁלֹּא תִּנָּשְׂאִי לְאִישׁ, וְכָפַל תְּנָאוֹ, אֵינוֹ כְּלוּם \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל נ\"ב)\u0006. וְאַף עַל פִּי שֶׁהַחֲלִיצָה כְּשֵׁרָה אַף אִם לֹא תִּתֵּן לוֹ, מִכָּל מָקוֹם חַיֶּבֶת לִתֵּן לוֹ, כִּשְׁאָר שְׂכַר שָׂכִיר לַעֲשׂוֹת מְלַאכְתָּן. \u0010c51\u0011 אֲבָל אִם יֵשׁ טַעֲנָה שֶׁאֵינָהּ חֲפֵצָה בּוֹ מִפְּנֵי שֶׁאֵינוֹ הָגוּן לָהּ, וְהוּא חַיָּב לַחֲלֹץ אֶלָּא שֶׁאֵינוֹ רוֹצֶה, וְהִטְעוּהוּ שֶׁיַּחֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לוֹ מָאתַיִם זוּז, אֵינָהּ חַיֶּבֶת לִתֵּן לוֹ כְּלוּם. \u0010c52\u0011 \u0005 אֲבָל אִם נָתְנָה לוֹ הַמָּעוֹת אוֹ הִשְׁלִישָׁה לוֹ \u0006 \u0005 הַמָּעוֹת, אֵינָהּ יְכוֹלָה לַחֲזֹר \u0006 \u0005(תְּשׁוּבַת רַשְׁבָּ\"א אֶלֶף ר\"מ)\u0006. \u0005 וְעַיֵּן לְעֵיל רֵישׁ סִימָן קס\"ה: \u0006\nאָמְרוּ לוֹ: חֲלֹץ לָהּ וּבְכָךְ אַתָּה כּוֹנְסָהּ, אוֹ שֶׁאָמְרוּ לֵהּ: חֲלֹץ לָהּ שֶׁזּוֹ מִצְוָה הִיא וְאֵינָהּ מַפְסֶדֶת עָלֶיךָ כְּלוּם, וְאִם תִּרְצֶה אַחַר כָּךְ לְיַבֵּם, תְּיַבֵּם, וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ, אֵינָהּ חֲלִיצָה לְהַתִּירָהּ, כֵּיוָן שֶׁלֹּא נִתְכַּוֵּן לְהַתִּירָהּ, אֲבָל נִפְסְלָה בְּכָךְ מִלְּהִתְיַבֵּם, וְכוֹפִין אֲפִלּוּ בְּשׁוֹטִים לַחֲלֹץ לָהּ חֲלִיצָה כְּשֵׁרָה:\nאָמְרוּ לוֹ: הָאִשָּׁה הַזֹּאת אֵינָהּ רוֹצָה בְּךָ דֶּרֶךְ יִבּוּם, אֶלָּא חֲלֹץ לָהּ וַעֲקֹר זִקָּתָהּ הֵימֶנָּה וְהִיא נִשֵּׂאת לְךָ דֶּרֶךְ \u0010c53\u0011 נִשּׂוּאִין, יֵשׁ מִי שֶׁאוֹמֵר שֶׁחֲלִיצָתָהּ כְּשֵׁרָה:\nדִּין חֲלִיצָה מְעֻשֵּׂית עַל יְדֵי יִשְׂרָאֵל אוֹ עַל יְדֵי עכו\"ם, דִּינָהּ כְּדִין גֵּט מְעְשֶּׂה, שֶׁנִּתְבָּאֵר בְּסִימָן קל\"ד. \u0005 וְעַיֵּן לְעֵיל סִימָן זֶה סָעִיף י\"ג: \u0006\nֹ מָסַר מוֹדָעָא עַל הַחֲלִיצָה, אֵינָהּ חֲלִיצָה בְּטֵלָה, אֶלָּא \u0010c54\u0011 חֲלִיצָה פְּסוּלָה הִיא:\nחֲלִיצָה פְּסוּלָה פּוֹסֶלֶת עַל כֹּל הָאַחִים, וּפוֹסֶלֶת לִכְהֻנָּה, וְאוֹסֶרֶת עָלָיו כָּל קְרוֹבוֹתֶיהָ, וְאֵינָהּ נִשֵּׂאת לְזָר עַד שֶׁתַּחֲלֹץ חֲלִיצָה כְּשֵׁרָה. עָבְרָה וְנִשֵּׂאת לְזָר קֹדֶם שֶׁתַּחֲלֹץ, חוֹלֵץ לָהּ חֲלִיצָה כְּשֵׁרָה וְהִיא תַּחַת בַּעְלָהּ, וְאֵין מוֹצִיאִין אוֹתָהּ מִמֶּנּוּ, מִכָּל מָקוֹם מַפְרִישִׁין אוֹתָהּ מִבַּעְלָהּ עַד שֶׁיַּחֲלֹץ לָהּ הַיָּבָם:\nלְאַחַר שֶׁחָלְצָה, \u0010c55\u0011 כּוֹתְבִין לָהּ בֵּית דִּין שֶׁחָלְצָה בִּפְנֵיהֶם, גֵּט חֲלִיצָה. וְאִם לֹא כְּתָבוּהוּ לָהּ, כָּל שְׁנַיִם שֶׁרָאוּ הַחֲלִיצָה יְכוֹלִים לְכָתְבוֹ, אַף עַל פִּי שֶׁאֵינָם מַכִּירִים לֹא הַיָּבָם וְלֹא הַיְבָמָה; שֶׁבֵּית דִּין לֹא חָלְצוּ בִּפְנֵיהֶם אִם לֹא הָיוּ מַכִּירִים. וּצְרִיכִין לְשַׂרְטְטוֹ, מִפְּנֵי מִקְרָאוֹת שֶׁבּוֹ. \u0005 וְעַיֵּן לְקַמָּן בְּפֵרוּשׁ הַסֵּדֶר סָעִיף ל\"ה: \u0006 \u0005(אָמַר הַמַּגִּיהַּ גַּם פֹּה בְּסֵדֶר חֲלִיצָה כָּל מָקוֹם שֶׁלֹּא נִזְכַּר בַּהַגָּהוֹת שֵׁם אוֹמְרָהּ, סְתָמָן כְּפֵרוּשָׁן שֶׁהֵם לְקוּחִים מֵהַסְדָרִים וּבִפְרָט מִסֵדֶר מהר\"י מַרְגָּלִיוֹת)\u0006:",[],["\u0003רק שידעו להקרות\u0004. עיין בפירוש סדר החליצה שהביא שם דעת הנ\"י שצריכין להיות דיינין אבל מומחין א\"צ להיות גם מ\"ש אם א\"י להקרות כשר ע\"ש פירושו:","\u0003קרוב\u0004. הטעם משום חליצה נקרא דין לכן קרוב פסול אף על גב בדין מהני אם קבלו בעלי הדינין הקרובים כאן לא מהני עיין בת\"ה סימן רכ\"ז:","\u0003ואפי' היה אביו גר\u0004. וקי\"ל בעלמא הורתו ולידתו בקדושה ישראל מעליא הוא מ\"מ כאן בחליצה צריכין להיות הדיינים שחולצת בפניהם שיהיה אביהם מישראל ולא מהני בדיינים הורתו ולידתו בקדושה דילפינן מקרא בישראל דהקפידה התורה שיהא אביהם מישראל ולא מהני בזה הורתן ולידתן בקדושה ועיין תוס' פ' מ\"ח דף ק\"א ובכתובות דף מ\"ד:","\u0003מצוה ושיוסיפו שנים\u0004. הטעם כדי לפרסם ופרש\"י ונ\"י לפ\"א לפרסם שתהא חלוצה ואסורה לכהן לפ\"ז אם היא גרושה כבר אין צריך חמשה אבל לפי' השני צריך ה' כדי דליתי אנשי ולקפצו עליה ובאלו שנים אין קפידא אם נוטלין שכר הרבה ד\"מ, וכן אם הם קרוביו קורבה שאין פסול ע\"פ הדין אלא מצד חומרא כמ\"ש בסי' ס\"ח ובנ\"י כ' אם הזמינו ג' לב\"ד בפי' וקראו שנים למילוי אז אפי' גרים אפי' פסולים כשרים באלו שנים והא דפוסל בש\"ס לרב ושמואל שהיו בן גר למילוי שנים היינו דשם כל החמשה היה עושה חיבור א' שאין זה כבודו של ר\"ש להקצות מן השלשה וכ\"כ בא\"ז דאין קפידא בשנים הנוספים אם אינם כשרים והיינו נמי בכה\"ג לפי המנהג דאין עושין חיבור א' ואלו שנים יושבין נמשכין מן הג' אז אין קפידא כלל ובזה מיושב מה שהקשה בת\"ה סי' רכ\"ו על הא\"ז מעובדא רב ושמואל בזה ניחא דל\"פ כלל הפוסקים ומה שמדייקי' מרמב\"ם וטור דס\"ל דיש קפידא באלו שנים שאל יהיו קרובים היינו דס\"ל כל החמשה יושבין בכנופי' חדא כדמשמע שם שלא כתבו דיושבין רחוק מן הג', גם מה שמדייק הת\"ה מן הגמיי' אין מוכרח וגר שאמו מישראל פסול לכתחלה להיות תוך שנים כשעושין כנופי' אחת כמ\"ש בש\"ס בעובדא רב שמואל בר יהודא ובדיעבד כשר הואיל ואלו שנים רק כדי לפרסם הדבר:","\u0003לקבוע מקום\u0004. עיין בפי' ס\"ח ועיין ב\"ח ואין קובעין בשבת מאחר דצריך קביעות הוי כמכין משבת לחול ועיין בד\"מ וקביעות מקום היינו משום פרסום לכן צריך להיות בגובה שבעיר ואם יש פרסום בלא זה עיין בתשובת ר\"י לבית הלוי סי' יו\"ד:","\u0003בן ג' שנים ויום א'\u0004. עיין סי' קנ\"ה שם כתבתי באריכות דינים הללו:","\u0003דדים גדולים\u0004. כתב בד\"מ בשם המרדכי דכתב בשם התרומה בדיקה זו צריך להיות ע\"י אנשים ובדיקה אם יש לה ריבוי שערות בודקים ע\"י נשים וכ\"כ ב\"ח בשם הסמ\"ק בדיקות דדים צריך להיות ע\"י אנשים אא\"כ הוחזקה גדולה בשנים אז בודקים ע\"י נשים כי החזקה מסייע מסתמא אחר יב\"ש הביאה סימנים א\"כ בדיקת שערות הוא אפי' לא הוחזקה בשנים והקשה הד\"מ א\"כ למה מהני בדיקות נשים ותירוץ משום דהוא מילתא דעבידא לגלויי לא משקרי והא אין נשים נאמנים על ב' שערות כשלא הוחזקה בשנים ולא אמרי' מלתא דעבידא לגלויי משום בשני שערות לאו מלתא דעבידא לגלויי הוא כ\"כ דהא מהאי טעמא כ' בה\"ת דאין ממאנין בזמן הזה דאין אנו בקיאין לבדוק כל הגוף אם יש לה שערות מיהו קשה דדין נמי הוא מלתא דעבידא לגלויי וא\"ל דדין לא עדיף מב' שערות דדין מהני משום א\"א לבוא סימן עליון בלא תחתון מ\"ה כשהיא לא הוחזקה בשנים אין בודקים נשים א\"כ מה מהני בדיקת אנשים וצ\"ל דד\"מ לא תירץ זאת אלא לסברת המ' דס\"ל באמת בדיקת דדין הוא ע\"פ נשים, ולבה\"ת דס\"ל דל\"מ ע\"פ נשים צ\"ע למה מהני רבוי שערות ע\"פ נשים:","\u0003נתמלא זקנו\u0004. עיין בב\"י בח\"ה ר\"ס ל\"ה:","\u0003שאם הוחזק או שיצא קול וכו'\u0004. נאמנים להחזיקן כגדולים היינו אפי' על בדיקת נשים סמכינן בחזקה פשיטא סמכינן על בדיקת נשים מה לי חזקה הנ\"ל או חזקה זו ויש לדחות דשם מיהו על שנים יש עדים וכן קול מהני כמו חזקה סמכינן עליהן:","\u0003וע\"ז סומכין שלא לבדוק וכו'\u0004. עיין סי' קנ\"ה שכתב הטור בשם הבע\"ת דאין אנו בקיאין לבדוק גומות א\"כ לפ\"ז לכאורה קשה כל בדיקות אחר השערות אפי' ע\"י אנשים ל\"מ דקי\"ל שערות בלא גומא ל\"מ ואין אנו בקיאין וכן הק' ב\"ח וע\"ש מ\"ש ולדידי' לא נתיישב לפסק הלכה מנ\"ל למיקל נגד דעת הבה\"ת וכן הטור הביא דעתו בפשיטות בלי שום חולק אבל לכאורה נ\"ל דלק\"מ בודאי על בדיקות גומות כשאין שערות בכל הגוף אין אנו בקיאין מ\"ה החמיר שם שלא תמאן אבל לבדוק אם יש גומא תחת השערות פשיטא בקיאין אנו בבדיקה זו וכן משמע מלשון המחבר שכתב ע\"ז סומכין שלא לבדוק משמע דאנו יכולים לבדוק, שוב ראיתי גם בט\"ז בסימן קנ\"ה כתב כן:","\u0003ואם יש ליבמה בנים\u0004. עיין סי' קנ\"ה שם הבאתי סוגי' פ\"ק דיבמות לרב ספרא בנים הם כסימנים אפי' אם הולידה בקטנותה הרי הם כסימנים אחר יב\"ש כן ס\"ל להג\"מ זה ולא כתשובת מ\"ב סימן ו' ע\"ש והרמב\"ם פוסק כר\"ס לפ\"ז שפיר פסק זה מיהו מהרי\"ף והרא\"ש משמע דס\"ל כרב זביד דאין בנים בלא סימנים היינו דאין בנים מצוי' בלא סימנים לפ\"ז לא מהני לענין חליצה ותימה על הרב רמ\"א דפוסק בפשיטות כהג\"מ וכבר כתבתי בסי' קנ\"ה דדוקא אחר יב\"ש מהני בנים לרמב\"ם:","\u0003שמצות חליצה מעומד\u0004. משום דדמיא לדין ואם יבם חלש או זקן נותנין לו מקל בידו לסמוך עליו, ולרמב\"ם ונ\"י בשם הרבה פוסקים אפילו לכתחלה חליצת המנעל מות' בישיבה וא\"ל להני פוסקים דס\"ל לכתחלה מצוה בעמידה הוא וס\"ל גם כן הא דאמר אמימר צריך למדחסי כרעיה היינו צריך לכתחלה ובדיעבד אין עיכוב אם כן מה מקשה שם על אמימר מברייתא בין עומד ובין יושב וס\"ד כשיושב לא מדחי' כרעיה ומה ק\"ל הא יש לומר הברייתא איירי בדיעבד וכן הקשה בנ\"י, וצ\"ל דס\"ל ע\"כ הברייתא איירי לכתחלה מדקתני בין עומד אם כן ע\"כ מה דתני בברייתא יושב ומוטה נמי לכתחלה וס\"ד כשמוט' לא מדחסי כרעיה וא\"ל איך ס\"ד יושב לכתחלה דהא מצות חליצה לכתחלה מעומד ויש לומר דסבר אף על גב לכתחלה בעינן שיעמדו היינו משום דהוי כדין וצריכים שיעמדו מחמת שהיא גובאת כתובה הוי כדין, אבל משום מצות חליצ' אפי' לכתחלה מותר וכן אם הדיינין עמדו כשר דחד טעם הוא:","\u0003ויש פוסלין\u0004. כ\"כ הרמב\"ם פ\"ד וטור בשם הרמ\"ה ולדעת הרא\"ש כשר וכתב הטעם משום הדרוש מתחש שצריך להיות משל עור אינו אלא אסמכתא, וא\"ל לפ\"ז למה אנפלאות של בגד פסול וצ\"ל דס\"ל כתוס' שכתבו שם אנפלאות לא חשיב מנעל כיון דאין רגילין לעשות מבגד ותליא הכל אם דרך לעשות מנעל כזה ודרוש תחש אינו אלא אסמכתא ושל עץ פסול גם כן מטעם דאין דרך לעשות מנעל של עץ כמ\"ש בתוס' שם, ורש\"י פי' למ\"ד אנפלאות כשר לא דייק הקרא תחש ש\"מ דס\"ל גם כן כי\"א אלו, ותוס' שם משמע נמי דס\"ל דרוש תחש לאו אסמכתא היא אלא צריך ישוב למה כתבו בפלוגתא בקב הקיטע ובאנפלאות דרבנן פסלו משום דאין דרך לעשות מנעל כזה ת\"ל דס\"ל הדרוש תחש דרוש גמור הוא וצ\"ל כמ\"ש בסמוך כשעשוי מצמר דבא מעור אין ממועט מתחש בזה ניחא מ\"ש באנפלאות מיהו מ\"ש בקב הקיטע דהיינו עץ כתבו הטעם דדרך עשוי מנעל ולא כתבו הטעם דר\"מ אינו מדייק תחש, ואפשר מדמוכרחי' לפרש באנפלאות משום דאין דרך לעשות מנעל משום דאין ממועט מתחש תו א\"צ לפרש בקב הקיטע לר\"מ דאינו מדייק תחש דהא אף דאינו מדייק תחש מ\"מ כיון דאין דרך לעשות ממנם /מהם/ מנעל למה כשר אלא ע\"כ צ\"ל טעם הנ\"ל ולפסק הלכה עיקר כי\"א אלו דהם דעת רש\"י ותוס' ורמב\"ם ורמ\"ה והרשב\"א כמ\"ש המגיד בשמו וכ\"פ הש\"ג לפ\"ז גם מ\"ש הטור אם חלץ במוק כשר היינו לטעמו מה שדרך לעשות מנעל כשר ותחש לאו דרשה גמורה היא אבל להפוסקים הנ\"ל דרשה גמורה היא אז אף במוק פסול מיהו י\"ל אף על גב תחש דרשה גמורה היא מ\"מ מוק העשוי מצמר הבא מעור אינו ממועט מתחש אף על גב העשוי משער פסול מ\"מ מוק כשר דאפשר דנקרא מנעל והעשוי משער לא נקרא מנעל אלא קורק' ולרש\"י ורשב\"א דפירשו אנפלאות של בגד ממועט מתחש אף על גב דעשוי מצמר הבא מעור כמו שער א\"כ קשה בסוגיא דבעיי' ליה הוא של עור ותרסיותיו של שער מהו א\"ל מי לא קרינא ביה תחש א\"ל א\"ה כולי נמי ההוא קורקא ואם בגד של צמר ממועט מתחש א\"כ שער נמי ול\"ל הטעם ההוא קורקא נקרא ולמה לא ממעט מתחש וי\"ל:","\u0003אבל רצועותיו א\"צ שיהיה מעור\u0004. כ\"כ הטור והב\"י הבין דהטור חולק על הנ\"י דכתב דלא מכשירין ברצועות אלא של שער שבא מעור ולא שאר מינים, ולהטור כשר אפילו בשאר מינים וכן ס\"ל לרמ\"א וי\"א שהביא דס\"ל גם רצועותיו מעור היינו דבר הבא מעור ואין מוכרח לומר כן אלא י\"ל דל\"פ אלא כוונת הטור דא\"צ להיות של עור אלא של שער הואיל שהוא בא מן העור כשר וכ\"כ ב\"ח ונראה דמוכח כן מש\"ס דאי ס\"ד אם הרצועות אפי' של שאר מינים כשר א\"כ קרא תחש לא קאי אלא על גוף הסנדל א\"כ מה הקשה שם א\"ה כולו של שער נמי מנ\"ל של שער נקר' תחש דלמ' של שער לא נקר' תחש אלא דלא אכפת לן אם הרצועות של שאר מינים, ומנעל של שער פסול כי של שער לא נקר' מנעל וכן אם הרוב מנעל של שער פסול כמ\"ש בש\"ג ואם התפירה של שער י\"ל ג\"כ דפסול כמ\"ש בש\"ג שם הטעם של פשתן פסול משום הכל הולך אחר המעמיד א\"כ הוי כאלו כולו של שער מיהו י\"ל דכשר דאף אם כולו של שער הוי כאלו הוא של עור אלא דפסול משום דלא נקרא נעל אבל אם היא של עור אלא התפירות הם של שער נקרא נעל וכשר ואם המנעל הוא שיכול להלוך בלא קשירה אז נראה לכ\"ע כשר אם הרצועות הם של שאר מינין כמ\"ש לקמן בשם הרא\"ש וע\"ש:","\u0003צריך לכתחילה שיהא עור קשה\u0004. הטעם פלוגת' משום דאית' בש\"ס אין חולצין במנעל לכתחלה ובזה\"ז דאין שכיח סנדל ואז ע\"פ הדין היה מותר לחלוץ במנעל אלא הפוסקים כתבו אף בזה\"ז לכתחילה טוב לעשות בסנדל ואית' כמה פירושי' מה בין מנעל לסנדל ומזה יצא כל הדיעות שהבי' כאן, אלא מה שהבי' כאן בשם י\"א שהתפירה תהיה בפנים א\"י מי הי\"א דהא הסמ\"ג וסמ\"ק כתבו להדי' סנדל תפירות מבחוץ:","\u0003יהיו בו ב' רצועות\u0004. ואם המנעל הוא שיכול להלוך בלא קשירה אז כשר החליצה אפילו שאין בו רצועות וקשרים כ\"כ הרא\"ש ועיין ס\"ק כ\"ה:","\u0003כדי שלא יהא מעל דמעל\u0004. היינו לכתחילה המצוה כך אבל בדיעבד אין חשש מאחר דחולץ שניהם כמ\"ש בסעיף ל\"ז כ\"כ הב\"י ובש\"ס משמע אף לכתחלה אין חשש משום מעל דמעל דאל\"כ למה לא אמר במנעל אין חולצין לכתחלה מטעם מעל דמעל כמ\"ש בש\"ס דלמא פנתא מעל וארקת' מעל דמעל, ועיין ב\"ח ופרישה אפילו לכתחלה אין כאן חשש אלא דרך חומר' בעלמ' כתבו הפוסקים כן:","\u0003שאינם מחופים עור\u0004. כבר כתבתי ה\"ה של מוק אם אין מחופה עור פסול וכ\"כ בדרישה וב\"ח אלא בד\"מ לא משמע כן אבל עיקר כמ\"ש וכ\"כ רי\"ו מוק פסול:","\u0003שאין לו עקב\u0004. כתב הנ\"י כל דבר המעכב הרגל במנעל נקר' עקב שצריך שאל יוצי' הרגל חוץ למנעל:","\u0003באנפליא של בגד חליצתו פסולה\u0004. עיין פ' כל הגט שם פליגי ר' אליעזר ושמואל, ולשמואל כל מקום דתני חליצה פסולה אסורה היא לאחין ולר\"א באנפלאות וקטן אינו חליצה כלל ומותרת לאחין אף על גב ברקקה לבד פסולה לאחין מ\"מ ברקק' וחלצה אנפלאות גרע טפי כמ\"ש במ', אבל באנפלאות החליצה בטילה, ורמב\"ם פוסק כר\"א והמחבר השמיט כאן דעת הרמב\"ם ובסעיף ג' בקטן פסק דאינה חליצה כלל ואינה נפסלת מאחין משום לפי גירסת תוס' פ' כל הגט איתא בפ' מ\"ח דף ק\"ה אמר שמואל חליצת קטן לרבנן אינה חליצה כלל ש\"מ דיש חילוק בין אנפלאו' לקטן, כי באנפלאות לא אמר שמואל דחולקין בזה ר\"מ ורבנן אם פסולה אז בטל לגמרי כן הוא דעת המחבר וכן פסק הרשב\"א כשמואל וכן משמע בתשוב' ריב\"ש שהביא בכ\"מ פ\"ד מה' יבום, ובזה מיושב תמיה' ב\"ח ורמב\"ם פוסק כר\"א באלו שניהם אין פוסלת כלל, אלא על המגיד קשה למה טרח להמציא טעם לדברי הרמב\"ם ולא כתב הטעם דפוסק כר\"א:","\u0003היה של עץ וכו'\u0004. כשרה משמע דוקא בדיעבד כשר וכן משמע בש\"ס וברמב\"ם וכן הוא להדיא בנ\"י וצריך ישוב על הרא\"ש דהביא כרש\"י סנדל התפור בפשתן היינו בגד פשתן תפור בפנים והקשה דלא גרע מסנדל של עץ ומחופה בעור מה קושיא דהא לפירוש הרא\"ש סנדל התפור בפשתן בדיעבד כשר א\"כ דילמא ג\"כ לפרש\"י אם תפור בפנים בגד פשתן באמת בדיעבד כשר ולא גרע מסנדל של עץ ומחופה בעור וצ\"ל משום דרש\"י פירש דאין חולצים בסנדל התפור דכתיב נעל ובפלוגתא דר\"מ בקב הקיטע מוכח לרש\"י דס\"ל דרשה דנעל לאו אסמכתא הוא ודרשה גמורה היא כמ\"ש בס\"ק י' משמע לרש\"י אף בדיעבד פסול מ\"ה הקשה מ\"ש למה גרע מסנדל של עץ, שוב ראיתי בב\"ח סעיף ז' מיישב בע\"א ודין זה מחופה בעור נלמד מאוקימתא דאבוה דשמואל כמ\"ש שם דף ק\"ג וא\"י למה כ' המגיד דלמדו מאוקימתא דאביי ע\"ש:","\u0003מנעל של ע\"א\u0004. עיין בתו' שם אם הוא ע\"א של ישראל או עכו\"ם והפקיר ובא ליד ישראל אז הוי כע\"א של ישראל ואין לו ביטול ומכתת שיעורי' אלא איירי בע\"א של עכו\"ם והפקיר וכוונתו שלא לקנות המנעל או ע\"ז של גוי ולא הפקיר אז לא קנה הישראל ב\"ח, לפ\"ז אסור לחלוץ בו מטעם שאין שלו המנעל ולר\"ת איירי בע\"א של עכו\"ם ובטלו:","\u0003תקרובת\u0004. פי' המגיד אם המנעל הוא תקרובת ליכא איסור דקי\"ל דאין תקרובת אלא המשתפך כעין פנים אלא איירי שזבח הבהמה לפני ע\"א ועשה מעורה מנעל וכן הוא בש\"ס פ' ר\"י ובכל הפוסקים כמ\"ש בי\"ד סי' קל\"ט, וצריך לדחוק בלשון רש\"י לכוין כוונתו ג\"כ מ\"ש שהקריב ומסרהו לע\"א קאי על הבהמה ולא על המנעל:","\u0003י\"א שחולץ בשתיהם\u0004. אף על גב דכתב בסמוך אם היא אטרת דחולצת בימין דידה מ\"מ ביבם מחמירין משום דאי' גזירה שוה דצריך דוקא ימין ממש ובפי' חליצה כ' לחלוץ בשני רגליו בפעם א' תחלוץ ביד א' מרגל א' ובידה שניה מרגל שני דאם תחלוץ זה אח\"ז הוי חליצה פסולה, וב\"ח כ' דמנהג הוא לחלוץ זה אח\"ז ויכוונו היבם והיבמה לחלוץ בזה שע\"פ הדין הוא לחלוץ:","\u0003שלא יהא מעל דמעל\u0004. ובדיעבד הוי חליצה פסולה ואם חולץ גם הבתי שוקיים כשר כ\"כ הרא\"ש וכן מוכח בש\"ס אבל מה שמדקדק לרחוץ רגליו לבדוק שלא יהא שום דבר דבק במנעלו אינו אלא חומרא בעלמא לכתחלה:","\u0003על השוק ערום\u0004. וז\"ל הלבוש ויכרוך הרצועות סביב הרגל ג\"כ מן הארכובה ולמטה היינו במקום שמנעל פתוח מאחורי הרגל שתי חורים ובין החורים הוא שלם יכרוך הארוכות בין הלולאות עד שיגיע באחורי הרגל בחור עליון ויניחם ג\"כ שם מכוונות זה אצל זה ואח\"כ יכרוך הרצועות פעם ג' סביב הרגל ועד שיגיעו למעלה מן הלולאות על גב הרגל שקורין בל\"א שינביי\"ן דעל שינביי\"ן נמי מעל רגלו נקרא, ועיין פרישה הטעם משום שבמקום שפוגעים בו שני הרצועות האריכות מלפניו ולאחריו כופלין אותו זה ע\"ז מחשב כקשר מ\"ה צריך שיהיה אותו הכפילה במקום בשר שוקו אבל מה שמשם והלאה מונח הרצועה על עור המנעל אין קפידא דאינו דומה לקשר כלל:","\u0003מלמדין אותה וכו'\u0004. לימוד זה קאי על הקרא כולו שתהיה רגילה לקרות ואח\"כ קאמר ותהיה יכולה לקרות ולא אבה בנשימה אחת אפילו לא קראה בנשימה א' דקי\"ל כל הראוי לבילה אין בילה מעכבת ויש מי שאומר הוסיף דהוא ג\"כ יהיה רגיל לקרות לא חפצתי אלא בפי' החליצה ס\"ק ס\"ו מדייק הרמב\"ם דכתב מלמדין אותה ואת היבם וכו' דקאי על לא חפצתי לפ\"ז א\"י מה מוסיף היש מי שאומר:","\u0003בנשימה אחת\u0004. ולא יפסיק בין תיבת לא לתיבת אבה דלא אתי למימר לא קאי על תחלת הקרא דאמרה מאן יבמי להקים לאחיו שם בישראל לא כלו' לא מאן אלא אבה יבמי, ולי\"א דצ\"ל ג' תיבות בנשימה אחת שלא תאמר לא אבה זאת היינו המיאון אלא יבמי אף על גב קריאה לא מעכב היינו כשלא קראו כלל משא\"כ בכה\"ג דאתי למטעי גרע טפי ולדעת הרי\"ף ורמב\"ם נראה הא דקריאה אין מעכב היינו כשראוי לקרות כדין אבל אם א\"י לקרות בנשימה אחת ולא קראה מעכב וב\"ח מדייק דא\"צ ליתן ריווח בין האלפי\"ן של לא אבה ואם הוא ערל שפתים ולא יכול לדבר מותר לחלוץ הואיל ואנו יודעין שלשונו כך הוא מהרי\"ק סי' ט\"ו:","\u0003מאן יבמי וכו'\u0004. וכתב בתשובת הרא\"ש והרשב\"א והטור אפי' אם היא מאלו שחולצות ולא מתיבמות או שהוא חפץ לייבם ולא היא מ\"מ קרינן מאן יבמי מאחר לסוף מתרצה לחלוץ:","\u0003י\"א שאם לא דחק וכו'\u0004. כ\"כ הטור בשם הרי\"ף ורמב\"ם דס\"ל המצוה כך הוא שצריך לדחוק רגליו מ\"ה ל\"ש כאן למימר הואיל וראוי לדחוק כשר דהא אכתי לא עביד המצוה והוי כאלו לא חלץ כלל ופסול אף שראוי לחליצה וכ\"כ רי\"ו וכן בש\"ג שם פוסל אם לא דחק רגלו בקרקע:","\u0003וי\"א דוקא שא\"י להלוך\u0004. כבר כתבתי לעיל בשם הרא\"ש דס\"ל כל שיכול להלוך במנעל אין עיכוב בקשירות וכן בסמוך אם קושר למעלה מארכובה כשר לדידיה אם יכול להלוך במנעל ובאמת לא מצינו שום פוסק אשר חולק עליו אף שסתמו דבריהם י\"ל לדינא מודים לדבריו:","\u0003מן הארכוב' ולמעלה\u0004. היינו מה שבין השוק לקוליות ולא מה שבין הארכובה הנמכר עם הראש והשוק וכל השוק נקרא מעל רגלו:","\u0003אינו חולץ\u0004. למ\"ש בכ\"מ וב\"י לדעת הרי\"ף ורמב\"ם לא הוי חליצה כלל ואין פוסלת מיהו לא נ\"מ לדינא דהא לכמה פוסקים חולצין בנקטע רגלו א\"כ בודאי פוסלת:","\u0003וי\"א דבנקטעה רגלו\u0004. איירי אף על גב רגלו עקומה קי\"ל חליצה פסולה משום דשם גרע טפי מאחר דרגל הפוך א\"כ השוק לא נקרא מעל רגלו משא\"כ כשהיה רגל ישרה אז נקרא השוק מעל רגלו מ\"ה אף בנחתך ממנו עדיין נקרא השוק מעל רגלו כ\"כ רש\"י לפ\"ז אם נברא כך ג\"כ חליצה פסולה, מיהו למ\"ש הרא\"ש בשם הראב\"ד הטעם ברגל הפוך כשחולץ הוא חולץ מעל כף רגלו ולא מעל רגלו א\"כ קוטם אף שהוא נברא כך כשר החליצה וכתב הרשב\"א כשנקטעה ליבם רגלו צריך לדחוק בשוקו בקרקע וכן הוא בתוס':","\u0003ולקשרו למטה מארכובה\u0004. אבל אם הקשרים למעלה מארכובתו פסול לפירוש הירושלמי המחלק בין אם הקשרים למטה מארכובה לבין אם הקשרים למעלה מארכובה איירי שנחתך הרגל אבל אם הרגל שלם ומנעל טוב לו ויכול להלוך בו, אז אפילו אם הקשרים למעלה מארכובה כשר ונראה לפ\"ז אפי' אם נחתך הרגל ונשאר משוקו שיכול לנעול מנעול ויכול לקיים כך בשוקו בלי קשירה אף אם קושר למעלה מארכובה כשר כמו אם רגלו שם אלא איירי בענין שנשאר משוקו דבר קטן שא\"י לעמוד בלא קשירה, ועיין תשובת מהר\"א בן ששון סימן קמ\"ב קמ\"ג ביבם שעקום ומהלך בצד רגליו ולפעמים דוחה עקבו בארץ דחולץ ועמ\"ש בשם מהרשד\"מ מאן דמסגי אלחתא חולץ אם אין אח אחר ועיין תשובת רש\"ך ח\"ב סימן נ\"ב דק\"ל בשמיטת רוב עקב הוי חליצה לכן אם נקרע הנעל בצד עקב אף על פי שיכול להלוך בו חליצה פסולה ועיין נ\"י ר\"פ מ\"ח:","\u0003קרעה המנעל וכו'\u0004. פסולה דכתיב וחלצה ואם קרעה כשיעור חליצה כגון רוב עקב אף שחלצה אח\"כ המנעל ל\"מ ועיין תשובת רש\"ך הנ\"ל:","\u0003וחלצה העליון\u0004. הנה לגירס' שלנו מבואר אם חלצה העליון וקם התחתון אז הוי מעל דמעל ולכאורה נראה מעל דמעל הוי חליצה פסולה ופוסלת לכן מ\"ש הרא\"ש והביא בהג\"ה בסמוך אם חולצת שניהם כשירים נראה דאיירי בחולצת שניהם יחדיו בפ\"א דאל\"כ בחולצת העליון הוי מעל דמעל והוי ח\"פ וצריכה לחזור על כל האחים ואם קרע' העליון מ\"מ קם ומחמת הקריעה יכולה לשלוף התחתון לא אפשטה הבעיי' והוי חליצה פסולה ומשמע אפי' קרעה לעליון רוב עקב או רוב המנעל שא\"י להלוך בו מ\"מ כיון דקם וליכא גילוי רגלו קמבעי' ליה דהא אף בנקרע רוב המנעל קי\"ל דהוי חליצה ופוסלת אם כן בכה\"ג יש לומר דהוי כאלו יש כאן מנעל העליון ועיין תשובה הנ\"ל ולרמב\"ם האבעיי' בש\"ס בחלצה העליון וקרעתה לתחתון א\"כ הוי חליצה גילוי כרעא ואפי' עשתה הכל בפ\"א נראה מ\"מ מבעיי' ליה כיון דחליצה היה בעליון, מיהו אם קרעת' לעליון לגמרי וחלצה התחתון הוי חליצה מעלייתא, וכתב המגיד וב\"י דהיה לרמב\"ם גירס' אחרת מיהו באמת יש ללמוד מגירס' שלנו ג\"כ הדין של הרמב\"ם:","\u0003עד שיגיע לפני היבם\u0004. ובתוס' אית' מצוה מן המובחר עד שיגיע לארץ:","\u0003כשרה\u0004. אף אם לא רקקה כלל כשרה אלא קמ\"ל דלא תימא שתרוק עוד אלא די ברקיק' זו, ונראה אף לענין לפסול מן האחין היינו דלא עשתה שום דבר רק רקקה לפני ב\"ד ולא ראו פסולה מן האחין, ותוס' כתבו שם בברייתא החולצת מן הסומא כשרה והקשו מהיכא ס\"ד למעוטי סומא ותירצו מדכתיב לעיני הזקנים וה\"א ה\"ה לעיני היבם א\"נ דכתיב וירקה בפניו הוי כמו לעיני קמ\"ל וב\"ח דייק מדברי תוס' דס\"ל אם הדייני' לא ראו הרוק פסול דהא כתיב לעיני הזקנים ול\"ד כי בוודאי לכ\"ע דרשת דרבא דדיינים צריכים לראות הרוק אינו אלא אסמכתא דהא וירקה קאי על בפניו ולא קאי אלעיל לעיני הזקנים וכוונת התוס' בתירוץ הראשון דה\"א מדכתיב לעיני הזקנים החליצת המנעל ה\"א ה\"ה לעיני היבם ופסול מחמת דלא ראו חליצת המנעל קמ\"ל ולתירוץ ב' ה\"א מדכתיב בפניו הוי כאלו כתיב וירק' לעיניו ואי הוי כתיב וירקה לעיניו פשיטא מעכב אבל בהדיינים דלא כתיב בהו שירקה לעיניהם פשיטא אין עיכוב וא\"ל לתוס' מהיכא ס\"ד לפסול כשהוא סומא מחמת שלא ראה הרקיקה דהא קי\"ל רקיקה אין מעכב וצ\"ל דצריך להיות ראוי לבילה וראוי לראות הרוק ומשמע מתוס' אלו דס\"ל אם היבם סומא אין חולץ לכתחלה ועיין בסעיף מ\"ח מבואר שם לדעת הרמב\"ם וראב\"ד היבם ג\"כ צריך לראות הרוק וכן משמע בתוס' אלו:","\u0003צריכה לרוק\u0004. פ\"א בש\"ס איתא לא עשה ולא כלום וכ\"כ הרמב\"ם משמע דאין פוסל כלל בכה\"ג וכ\"ש בש\"ג ברקקה מחמת שאכלה שום או שאר דברים שמרבים רוק דהני ג\"כ לא עשה ולא כלום דאין פוסל אבל למ\"ש רי\"ו אם נתפזרו והלכו להם כשרה נראה דפוסל מיהו אפילו לא הלכו:","\u0003א\"צ לרוק פ\"א\u0004. כ\"כ הראב\"ד והרא\"ש במקום חליצה א\"צ לרוק פ\"א ומה שקאמר בש\"ס דוקא במוצצת מהני היינו אם רקקה שלא במקום חליצה לענין שתהיה פסולה על האחין כמ\"ש בסעיף מ\"ה וי\"א דוקא במוצצת כ\"כ הרמב\"ם, ואם רקקה בלא מוצצת ולא שותת לא מהני כ\"כ הרשב\"א:","\u0003והיה רוק זב\u0004. כ\"כ הרמב\"ם ומשמע דוקא בזב אבל אם לא זב אפילו לא מוצצת מהני ולא משמע כן משאר פוסקים אלא כיון שהרוק בא מחמת דבר אחר לא הוי רקיקה אפי' לא זב, מיהו במוצצת י\"ל ג\"כ מהני לכ\"ע וכתב בש\"ג אם רקקה מחמת דבר אחר לא הוי רקיקה כלל ולא נפסלת על האחים:","\u0003ג\"פ\u0004. חלוץ הנעל כאבל חלוץ הנעל כמנודה חלוץ הנעל כמורד במצות סיני:","\u0003וי\"א דה\"ה לחליצת חרש\u0004. כן הוא דעת הרמב\"ם דחרש דינו כקטן בכל מקום ועיין במגיד שכתב באריכות ליישב הסוגיא לפי' הרמב\"ם דהא אין ממעט שמאל אלא חליצת קטן דאינו כלום משמע חליצת חרש פוסלת, ועיין בתוס' שכתבו וחרש וחרשת אינן פסולים מחמת דלאו בני דיעה נינהו כיון דהב\"ד עומד ע\"ג ומורה להם וכן קי\"ל בגט אם כתבו וגדול עומד עליהם כשר ואינן פסולים אלא משום דאינן באמר ואמרה לכן דינן כאלם ואלמת ופוסל חליצתם, אבל בדבר שאין הב\"ד עומד ע\"ג ומורה להם אין מעשיו כלום, ובקטן אפי' עומדים ע\"ג אינו כלום איש כתוב בפרשה וכן בשוטה ולא מהני אפי' עומדים ע\"ג כמ\"ש בתוס', ולרמב\"ם בחליצה אפי' עע\"ג לא מהני מעשיו ואין פוסלת כלל ואין להקשות למה בגט אם עומדים ע\"ג מהני לכן פוסק שם אם חש\"ו כתבו התורף והב\"ד עמדו ע\"ג כשר מדאורייתא כמ\"ש בסי' קכ\"ג דאל\"כ היה לו לגזור טופס אטו תורף אם התורף פסול מדאורייתא אלא וודאי בגט כשר מדאוריית' וי\"ל משום דלא נפישי מילי כמו בחליצה גם בגט מוכח דכותב לשמה דהא כותב שמו ושמה וכ\"כ תוספות:","\u0003נתכוין הוא ולא היא וכו'\u0004. עיין בהרא\"ש שם דהקשה למה דקי\"ל יבמה שרקקה תחלוץ למה דחקו בש\"ס למצוא דרך שתהא היבמה אסורה ליבם למה לא אמרו לה שתרוק לפניהם ואז אסורה ליבם, ותירץ משום עובדא דש\"ס היה שהיבם רצה לייבם ואין כוונתו לחלוץ מ\"ה אף אם רקקה לא תפסול את עצמה עליו והביא ראייה מחליצת המנעל לא' מן האחי' דחשש הוא שמא נתכוונו שניהם אבל אם א' לא נתכוין ליכא חשש ומשמע לכאורה מדמדמה שני דינים אלו להדדי ורקיקה איירי בב\"ד א\"כ ה\"ה אם חלצה בב\"ד המנעל ותו לא עשתה כלום נמי בעינן דוקא כשנתכוונו שניהם ונראה מדבריו שם ע\"כ לא אמר בש\"ס אם נתכוין א' מהם הוי חליצה לחומר' אלא דוק' בחליצה גמור' כמ\"ש בש\"ס חלוץ ובכך אתה כונסה והוי חליצה גמורה אלא הוא לא נתכוין אז ק\"ל דהוי חליצה לחומרא אבל בחליצת מנעל לבד או רקיקה אפי' בב\"ד אם נתכוין א' מהם והשני בוודאי לא נתכוין לא הוי חליצה כלל ומותרת לאחים, אלא כשאין ידוע לנו חיישינן שמא כיוונו שניהם ובזה שפיר הגירסא בטור שמא כיוונו לשם חליצה מ\"ה בעובדא דש\"ס הנ\"ל אף אם היתה רקקה לפני ב\"ד וכיוונה היא לחליצה לא הוי חליצה כלל ומותרת לאחים, וכן נראה מפי' תוס' בסוגיא זו דחיישינן שמא כיוונו שניהם וקושי' המקשן והתני' בין התכוון הוא ובין התכוונה היא חליצה פסולה עד שנתכוונו שניהם פירושו עד שידוע לנו שכיוונו שניהם וכאן חיישינן שמא כיוונו ע\"ז תירץ התרצן לחומרא חיישינן שמא כיוונו אבל להתיר לעלמא אינה מותרת עד שידוע לנו שכיוונו ואיירי כל הסוגיא בחשש שמא כוונו שניהם אבל אם ידוע לנו דאחד מהם לא כיוון מותרת לאחים ועיין מ\"ש ב\"ח על הטור ול\"ד אבל למ\"ש בנ\"י איירי הסוגיא דחיישי' שמא כיוונה היא והקשה והתניא עד שנתכוונו שניהם ותירץ לחומר' חיישינן אפי' אם כיוון א' מהם הוי חליצה לחומר' אף דא\"י לנו שאחד מהם התכוין חיישי' שמא אחד כיוון א\"כ אפילו אחד מהם בוודאי לא נתכוון מ\"מ בחליצת המנעל פסולה לאחים אפילו שלא בב\"ד וליישב קושית הרא\"ש למה לא אמרו לה שתרוק ותתכוון לחליצ' ותהא אסורה ליבם יש לומר דס\"ל ברקיקה לא מהני כוונת א' מהם אלא בחליצת מנעל אז חששו חז\"ל דפסולה לאחים אלא לפ\"ז קשה למה ליה להוכיח שם דרקיק' מה שרוקקת בין האחים לא מהני אפי' למפסל דהא אף בב\"ד לא מהני בכוונת א' מהם ומכ\"ש בין האחים וע\"כ בין האחים ליכא חשש שמא כיוונו שניהם דהא כל שקל' וטרי' בש\"ס שמא כיוונה היא אבל על כוונת שניהם ליכא חשש כלל, ודברי הרי\"ף ורמב\"ם פ\"ד דגיטין למ\"ש הנ\"י שכתבו חיישינן שמא נתכוונו, ומ\"ש המחבר שמא כיוונו לשם חליצה משמע דוקא כשיש חשש דכיוונו שניהם נראה שכתב שלא בדקדוק נמצא למדין אם חלצה המנעל שלא בפני ב\"ד וא' מהם לא כוון לחליצה קמפלגי פוסקים הנ\"ל ואם רקקה בב\"ד והוא לא נתכוין להרא\"ש לא מהני כלל ואפשר דשאר פוסקים ג\"כ מודים לזה, ואם חלצה מנעל בב\"ד בלא כוונה כתבתי לדעת הרא\"ש ג\"כ לא מהני אא\"כ במקום חליצה גמורה, מיהו זאת יש לדחות קצת ולומר דכוונת הרא\"ש לדמו' רקיקה בב\"ד בלא נתכוון אחד מהם לחליצת מנעל שלא בב\"ד בלא נתכוון אחד מהם אבל חליצת מנעל בב\"ד אפי' בלא כוונה פוסל:","\u0003בפני ב\"ד\u0004. הטעם הוא משו' רקיקה לית' אלא בסוף יאמרו דכבר חלץ לה מ\"ה דוקא אם רקק' בפני ב\"ד נפסלה מלהתייבם ואם נתכוונו שניהם י\"ל דנפסלה לדעת הרא\"ש ושאר פוסקים אפי' בנתכוונה היא י\"ל דנפסלה וכ\"כ בד\"מ בהגהות פרישה:","\u0003ויש מי שאומר\u0004. דה\"מ בשרקקה רוק לכאורה תמוה דמשמע הפוסקים חולקים ע\"ז ואינו דהא כאן איירי לענין אם היא פסולה לאחים ופשיטא לדעת הפוסקים היינו י\"א בסעיף מ' דס\"ל אפי' במקום חליצה אם לא מצצה לא מהני פשיטא אינה אסורה לאחין ברקקה דם ולא מצצה אפי' לדיעה קמייתא שם הא מבואר לשיטת הר\"ש /הרא\"ש/ דאבוה דשמואל איירי דוקא לעניין פסול לאחים אז בעינן מעורב רוק משא\"כ במקום חליצה אפי' ברקקה דם א\"צ לרוק פעם אחרת א\"כ בדין זה ליכא פלוגתא כלל:","\u0003הסומ' אינו חולץ\u0004. דעת הרמב\"ם וראב\"ד צריך היבם לראות הרוק מ\"ה לכתחלה אינו חולץ אלא לדעת הראב\"ד אם אין אח אלא הוא הוי כדיעבד מאחר שאין תקנה לדבר כמ\"ש בהג\"ה סעיף י\"ב, וצריך ישוב למה בעי שא\"י לעמוד פוסק בפשיטו' דחולץ מיושב וכאן הביא דעת הראב\"ד בשם יש מי שאומר ואפשר בחולה א\"י לייבם ג\"כ וכאן אפשר לייבם ומ\"ש ואם חלץ כשרה כתב המגיד הטעם משום דקי\"ל רקיקה אין מעכב ואין נראה דהא בעינן ראוי לבילה כמ\"ש לעיל בענין קריאה אלא נראה משום דרוש זה דצריך לראות הרוק אינו אלא אסמכתא בעלמא דהא כתיב וירקה בפניו ולא כתיב לעיניו ובפניו היינו נגד פניו אף שהוא אינו רואה עיין בנ\"י ס\"פ מ\"ח דכתב סומא חולץ לכתחלה דא\"צ לראות הרקיקה ונראה בעניין ראיית הרקיקה יש להחמיר לכתחלה וכן אם יש אח אחר יחלוץ האחר ואם אין לו אח אחר יחלוץ זה כדעת הראב\"ד:","\u0003חליצתה פסולה\u0004. הנה במתני' זו יש גירס' מוחלפת לפי גירס' שלנו תנא קטנה שחלצ' תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה ודייקו תו' מזה כיון דתני פסולה למה תנא תחלוץ משתגדיל אלא דלא תימא חליצה פסולה מדרבנן להכי תנא תחלוץ משתגדיל יתור לשון לאשמעי' דחליצת קטנה אין כלום כמו חליצת קטן ומזה נשמע למה דקי\"ל בחליצת קטן אין פוסלת כן היא בחליצת קטנה אף על גב דאתמר בש\"ס וחכמים אומרי' איש כתיב בפרשה ולא מקשינן אשה לאיש מ\"מ לפסק הלכה לא קי\"ל כחכמי' לפי המסקנא דרבא אמר שם הלכתא עד שתביא שתי שערות היינו דלא קי\"ל כחכמים בזה וכן הוא בסמ\"ג דף קל\"ז ע\"א והרא\"ש תופס גירס' זו לעיקר מ\"ה מוכח מדבריו דחליצת קטנה אין כלום ואין פוסלת והיינו מ\"ש הטור בשם הרא\"ש דהשוה חליצת קטנה לקטן והיינו נמי כוונת הב\"י לדייק מתו' הנ\"ל דס\"ל חליצת קטנה אינה פוסלת, אף על גב דתוס' כתבו כן לדברי ר\"מ דס\"ל אף חליצת קטן פוסלת מ\"מ מהר\"מ נשמע לחכמים דקי\"ל כוותייהו בזה דחליצת קטן אין פוסל א\"כ בקטנה נמי אין פוסלת דהא נשמע מיתור מתני' דהיקש זה דמקשינן קטנה לקטן הוא מדאורייתא בזה נחו שקטו כל תמיהו' ב\"ח ודרישה על הב\"י וניחא נמי מ\"ש הטור בשם הרא\"ש, והב\"י נמי הבין כן אלא תמיהתו דלא מצינו כן בהרא\"ש מבואר ולהרי\"ף הגירס' אם לא חלצה משתגדיל כשרה ולחכמים דאומרים דלא מקשינן איש לאשה אז אפי' לכתחלה חולצין לקטנה, ומה שמסיים שם והלכתא עד שתבוא שתי שערות היינו לכתחלה ורמב\"ם שכתב חליצתה פסולה נראה דתפס גירס' שלנו ולא כמגיד וליישב קושית תוס' למאי תנא תחלוץ משתגדיל י\"ל בענין אחר אף על גב דהיקש מזה מדרבנן מ\"מ צריכה חליצה אחרת משתגדיל לפ\"ז יש בזה ג' דיעות לשיטת התוס' לחכמי' אין חליצה כלל ואינה פוסלת, ולהרי\"ף בדיעבד כשרה, ולהרמב\"ם פוסלת וצריכה חליצה אחרת אבל מ\"ש המגיד אף לגירסת הרי\"ף למסקנא שם והלכתא עד שתביא ב' שערות היינו אף בדיעבד פוסל' נראה דוחק גדול הוא מאחר לר\"מ ולרבנן חליצה כשרה ואיך יפסוק רבא לא כמאן ועל רמב\"ם לכאור' קשה דפוסק בחרש וחרשת דחליצת' אינה כלום ואין פוסלת וכ' המגיד הטעם משום דקי\"ל בכל התורה חש\"ו שווים מ\"ה אף בחליצה שוים ואין פוסלת כמו בחליצת קטן א\"כ למה חליצת קטנה פוסלת ואי ההיקש אשה לאיש רק מדרבנן א\"כ אף חליצת חרשת פוסלת, צ\"ל איירי בקטנה דיש לה דעת ואז הפסול מדכתיב איש בפרשה ולא קטן אפי' יש לו דעת והיקש אשה לאיש אינו אלא מדרבנן מ\"ה פוסלת משא\"כ חרש וחרשת ושוטה דאין להם דעת מ\"ה אין פוסלים חליצת' כמ\"ש הרמב\"ם שם דין י\"ג בחרש וחרשת שאינן בני דעת, וקטן אפי' יש לו דעת אינו פוסל דתורה מיעטו מדכתיב איש שוב ראיתי בת\"ה סי' רכ\"ה שכתב ג\"כ דגירס' הרמב\"ם כגירסא שלנו:","\u0003וא\"צ לחזור ע\"כ האחין\u0004. הטעם מבואר בת\"ה הואיל לפי גירס' שלנו חליצתה אינו כלום ואין פוסלת א\"כ לא הוי חליצתה פסולה ולגירס' הרי\"ף חליצת קטנה כשירה אף לכתחלה רק טוב לחלוץ משתגדיל מ\"ה א\"צ לחזור ע\"כ האחים כיון ע\"פ הדין חליצה כשרה היא אלא לדעת הרמב\"ם חליצה פסולה היא ודבר דרבנן אזלינן אחר הפוסקים:","\u0003ע\"מ שלא תנשאי\u0004. וא\"ל אף על גב מדין תנאי לא הוי כדבסמוך מכל מקום כיון שהוא סבר שהתנאי קיים נמצא שלא התכוון להתירה וכל שלא התכוון להתירה לא הותר' וי\"ל הוא סובר שהחליצ' זו מתירת' להנשא ולכך התכוון ואינה נאסרת לפי דעתו אלא לפי תנאי והתנאי באמת בטל כיון דא\"י להיות ע\"י שליח כמ\"ש בשם בדק הבית:","\u0003אבל אם יש טענה וכו'\u0004. כתב בד\"מ בשם א\"ז דוק' במקום שיבום קודם והוא הטעתו שיחלוץ לה צריכה ליתן שכרו אבל במקום שחליצ' קודם ואינו רוצה אז אפי' שכר טירח' אין לו, לפ\"ז אם יש לו אשה אז לכ\"ע מ\"ח קודם אין לו אפי' שכר טירח' כמ\"ש בסימן קס\"ה לכאורה נראה לפי פלוגתת הפוסקים אם מצות יבום קודם או מ\"ח כמ\"ש שם א\"כ מחמת הספק הדין לחלוץ א\"כ לעולם אין לו כלום אפי' שכרו דהא לעולם צריך לחלוץ אלא מדברי הטור והמחבר לא משמע כן דהא הביאו פלוגת' זו בסימן קס\"ה מכל מקום כותבין כאן דוק' כשיש לה טענה שצריך לחלוץ משמע אבל משום פסיק' דדינ' דצריך לחלוץ יכול לומר קום לי כהני פוסקים דמ\"י קודם וצריך ליתן שכרו:","\u0003אבל אם נתנה לו מעות\u0004. אבל אם חייבה את עצמה בשטר או בקנין אין מוציאין מיד האשה תשובות רשב\"א שם אף על גב דקי\"ל אם נתן כתב לחבירו א\"י לפטור את עצמו בטענת השטאה כמ\"ש בת\"ה סימן פ\"א ש\"ה דהא ידוע לנו העסק דחייב זה לחלוץ בחנם ומהיכ' תיתי לומר דיתחייב את עצמו בחנם משא\"כ שם דאמרי' מסתמ' אמת הוא שחייב לו כאשר נתן לו כת\"י עליו:","\u0003יש מי שאומר שחליצתה כשרה\u0004. כתב המגיד הרמב\"ם שכתב חלוץ לה שזו מצוה היא וכו' כמ\"ש בסעי' הקודם חולק על זה והמחבר ס\"ל דזה עדיף דאמרי' לו בפי' שיעקור הזיקה משא\"כ שם שסובר בזה יכול לכנוס גם מ\"ש לו ואם תרצה לייבם תייבם עדיין הזיקה קיימת:","\u0003חליצה פסולה הוא\u0004. אף על גב בגט אם מוסר מודעה אז הגט בטל ואין פוסל כלל כמ\"ש בסימן קל\"ד מ\"מ חליצה פוסלת ועיין הטעם בתשובת ריב\"ש סימן תפ\"ב והובא בכ\"מ פ\"ד:","\u0003כותבין לה ב\"ד\u0004. עיין מ\"ש בסי' קל\"ה וכתב זה צריכין לקיים לכ\"ע אף מי שסובר בגט א\"צ קיום משום חומר' שהחמרת בסופו משא\"כ כאן עיין תשובות ריב\"ש:"]],["הַיְבָמָה שֶׁנָּתַן לָהּ הַיָּבָם גֵּט כְּרִיתֻת, פְּסָלָהּ וּפָסַל צָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִים, \u0010c0\u0011 מִדִּבְרֵיהֶם. וְכָל גֵּט שֶׁפּוֹסֵל אִשְׁתּוֹ מְהַכְּהֻנָּה, פּוֹסֵל יְבִמְתּוֹ מֵהַיִּבּוּם; וְאֵינָהּ מֻתֶּרֶת לְזָר, עַד שֶׁיַּחֲלֹץ לָהּ:\nוְכֵן הַמַּאֲמָר \u0005(פי', יְבָמָה נִקְנֵית מִדְּאוֹרָיְתָא בְּבִיאָה, לֹא זוּלַת, וַחֲכָמִים תִּקְנוּ שֶׁיְּקַדְּשֶׁנָּהּ תְּחִלָּה, וְזֶהוּ הַנִּקְרָא מַאֲמָר, פֵּרוּשׁ מַאֲמַר חֲכָמִים)\u0006, אֵינוֹ קוֹנֶה בָּהּ קִנְיָן גָּמוּר; שֶׁאִם בָּא לְהוֹצִיאָהּ אַחַר הַמַּאֲמָר, צְרִיכָה גֵּט לַמַּאֲמָר, וַחֲלִיצָה לְהַפְקִיעַ הַזִּקָּה:\nמֵאַחַר שֶׁאֵין מַאֲמָר קוֹנֶה קִנְיָן גָּמוּר, וְלֹא גֵּט דּוֹחֶה דְּחִיָּה גְּמוּרָה, לְפִיכָךְ, מוֹעִיל הַמַּעֲשֶׂה שֶׁנַּעֲשָׂה אַחַר כָּךְ, הֵן גֵּט אַחַר גֵּט, הֵן מַאֲמָר אַחַר מַאֲמָר, אוֹ גֵּט וַחֲלִיצָה וּבִיאָה אַחַר הַמַּאֲמָר, אוֹ מַאֲמָר וּבִיאָה וַחֲלִיצָה אַחַר גֵּט, בֵּין בְּיָבָם אֶחָד וּשְׁתֵּי יְבָמוֹת, בֵּין בִּיבָמָה אַחַת וּשְׁנֵי יְבָמִים, בֵּין בִּשְׁתֵּי יְבָמוֹת וּשְׁנֵי יְבָמִים:\nכֵּיצַד, יָבָם שֶׁנָּתַן גֵּט לִיבִמְתּוֹ, וְחָזַר וְנָתַן גֵּט לְצָרָתָהּ, \u0010c1\u0011 נֶאֱסַר בִּקְרוֹבוֹת שְׁתֵּיהֶן. אוֹ שְׁנֵי יְבָמִין שֶׁנָּתְנוּ שְׁנֵיהֶם גֵּט לִיבָמָה אַחַת, זֶה אַחַר זֶה, שְׁנֵיהֶם נֶאֶסְרוּ בִּקְרוֹבוֹתֶיהָ. אוֹ שְׁנֵי יְבָמִים וּשְׁתֵּי יְבָמוֹת, כָּל אֶחָד נָתַן גֵּט לְאַחַת, כָּל אֶחָד נֶאֱסַר בַּקְּרוֹבוֹת שֶׁל אוֹתָהּ שֶׁנָּתַן לָהּ גֵּט:\nכְּשֶׁבָּאִים לְהוֹצִיאָהּ, לְמַאן דְּאָמַר חֲלִיצָה פְּסוּלָה צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים, בִּשְׁנֵי יְבָמִים וִיבָמָה אַחַת צְרִיכָה חֲלִיצָה מִכָּל אֶחָד וְאֶחָד. \u0010c2\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, דְּהוּא הַדִּין בְּיָבָם אֶחָד וּשְׁתֵּי יְבָמוֹת, וְנָתַן גֵּט לִשְׁתֵּיהֶן, שֶׁצָּרִיךְ לַחֲלֹץ לִשְׁתֵּיהֶן. וּלְמַאן דְּאָמַר חֲלִיצָה פְּסוּלָה אֵינָהּ צְרִיכָה לַחֲזֹר עַל כָּל הָאַחִים, אֲפִלּוּ בִּשְׁנֵי יְבָמִים וִיבָמָה אַחַת, דַּי בַּחֲלִיצָה אַחַת. \u0005 הַגָּה: וְלָזֶה הִסְכִּים הָרֹא\"שׁ זַ\"ל. \u0010c3\u0011 וְהָא דַּחֲלִיצָה פְּסוּלָה צְרִיכָה לַחֲזֹר, הַיְנוּ שֶׁהָיְתָה זְקוּקָה לְגַמְרֵי, וְנִפְסְלָה, שֶׁנִּקְלְשָׁה הַזִּיקָה. אֲבָל חֲלִיצָה פְּסוּלָה מֵעִקָּרָא, אֵינָהּ צְרִיכָה לַחֲזֹר: \u0006\nוְכֵן יֵשׁ מַאֲמָר אַחַר מַאֲמָר, שֶׁאִם עָשָׂה מַאֲמָר בְּזוֹ וְאַחַר כָּךְ בְּזוֹ, אוֹ אַחִים עָשׂוּ מַאֲמָר בָּהּ אוֹ בַּחֲבֶרְתָּהּ, כָּל אַחַת צְרִיכָה גֵּט לַמַּאֲמָר, \u0010c4\u0011 וַחֲלִיצָה לְאַחַת מֵהֶם לִפְטֹר אֶת שְׁתֵּיהֶן. וְכֵן אִם עָשָׂה מַאֲמָר בְּזוֹ, וְאַחַר כָּךְ נָתַן גֵּט, אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אוֹ שֶׁבָּא עַל צָרָתָהּ, אוֹ שֶׁאַחַר הַמַּאֲמָר שֶׁלּוֹ נָתַן לָהּ אָחִיו גֵּט, אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אוֹ שֶׁבָּא עָלֶיהָ אוֹ עַל צָרָתָהּ, מוֹעִיל מַה שֶּׁנַּעֲשָׂה אַחַר מַאֲמָר לֶאֱסֹר בַּעֲלַת הַמַּאֲמָר, וְלֵאָסֵר \u0005(בִּקְרוֹבוֹתֶיהָ)\u0006 [בַּקְּרוֹבוֹת] בַּמַּעֲשֶׂה שֶּׁנַּעֲשָׂה אַחַר הַמַּאֲמָר, וּלְהַצְרִיךְ גֵּט לַמַּאֲמָר וּבִיאָה שֶּׁנַּעֲשָׂה אַחֲרָיו:\nוְזֶה תַּקָּנָתָם: עָשָׂה בָּהּ מַאֲמָר \u0010c5\u0011 וְנָתַן לָהּ גֵּט, צְרִיכָה חֲלִיצָה. עָשָׂה מַאֲמָר וְחָלַץ, צְרִיכָה גֵּט. עָשָׂה מַאֲמָר בָּזוֹ וְנָתַן גֵּט לָזוֹ, נוֹתֵן גֵּט לְבַעֲלַת הַמַּאֲמָר, וְהוּא אוֹ אָחִיו חוֹלְצִים לְאַחַת מֵהֶן, וְתִפָּטֵר הָאַחֶרֶת. \u0010c6\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁשְּׁתֵּיהֶן צְרִיכוֹת חֲלִיצָה:\nעָשָׂה מַאֲמָר בָּזוֹ, וּבָעַל הוּא אוֹ אָחִיו לָזוֹ, בַּעֲלַת הַמַּאֲמָר צְרִיכָה גֵּט, וְכֵן הַשְּׁנִיָּה צְרִיכָה גֵּט, וְצָרִיךְ לַחֲלֹץ לְאַחַת מֵהֶן:\nוְכֵן אִם נָתַן לָהּ גֵּט, וְאַחַר כָּךְ בָּא עָלֶיהָ אוֹ עָשָׂה בָּהּ מַאֲמָר אוֹ בַּחֲבֶרְתָּהּ, אוֹ שֶׁחָלַץ לַחֲבֶרְתָּהּ, אוֹ שֶׁאַחַר הַגֵּט שֶׁלּוֹ עָשָׂה בָּהּ אָחִיו מַאֲמָר אוֹ בָּא עָלֶיהָ, אוֹ חָלַץ לָהּ אוֹ לַחֲבֶרְתָּהּ, מוֹעִיל מַה שֶּׁנַּעֲשָׂה אַחַר הַגֵּט לֵאָסֵר בִּקְרוֹבוֹתֶיהָ וּלְהַצְרִיךְ גֵּט לַמַּאֲמָר שֶּׁנַּעֲשָׂה אַחֲרָיו:\nוְזֶה תַּקָּנָתָם: נָתַן לָהּ גֵּט וְאַחַר כָּךְ בָּא עָלֶיהָ אוֹ עָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט וַחֲלִיצָה:\nנָתַן לָהּ גֵּט, וְאַחַר כָּךְ בָּא הוּא אוֹ אָחִיו עַל צָרָתָהּ, אוֹ שֶׁעָשׂוּ בָּהּ מַאֲמָר, זוֹ שֶׁבָּא עָלֶיהָ אוֹ שֶׁעָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט, וְצָרִיךְ חֲלִיצָה לְאַחַת מֵהֶן לִפְטֹר שְׁתֵּיהֶן:\nהַבְּעִילָה קוֹנָה קִנְיָן גָּמוּר, וְכֵן הַחֲלִיצָה דּוֹחָה דְּחִיָּה גְּמוּרָה. \u0010c7\u0011 לְפִיכָךְ, אֵין הַמַּעֲשֶׂה שֶׁנַּעֲשָׂה אַחֲרֵיהֶם, מוֹעִיל, לֹא לִפְסֹל אֶת זוֹ וְלֹא לֵאָסֵר בִּקְרוֹבוֹתֶיהָ. כֵּיצַד, בָּא עַל יְבִמְתּוֹ, וְחָזַר הוּא אוֹ אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ, אֵין אוֹתָהּ חֲלִיצָה כְּלוּם. וְכֵן אִם אָחִיו חָזַר וְנָתַן גֵּט לָהּ אוֹ לְצָרָתָהּ, אֵינוֹ כְּלוּם. וְכֵן אִם חָזַר וְעָשָׂה בָּהּ מַאֲמָר אוֹ בָּעַל, אֵינוֹ כְּלוּם. אֲבָל אִם בָּא הוּא אוֹ אָחִיו עַל צָרָתָהּ, אוֹ עָשָׂה בָּהּ מַאֲמָר, צְרִיכָה גֵּט:\nוְכֵן אִם חָלַץ לִיבִמְתּוֹ, וְחָזַר הוּא אוֹ אָחִיו וְחָלְצוּ לְצָרָתָהּ, אֵין אוֹתָהּ חֲלִיצָה כְּלוּם לֵאָסֵר בִּקְרוֹבוֹתֶיהָ. אוֹ שְׁנֵי יְבָמִים שֶׁחָלְצוּ לִיבָמָה אַחַת, זֶה אַחַר זֶה, אֵין חֲלִיצָה אַחֲרוֹנָה כְּלוּם, וּמֻתָּר בִּקְרוֹבוֹתֶיהָ. אֲבָל אִם אַחַר שֶׁחָלַץ לִיבִמְתּוֹ, בָּעַל, אוֹ קִדֵּשׁ הוּא אוֹ אָחִיו אוֹתָהּ אוֹ צָרָתָהּ, תָּפְסֵי לְהוּ קִדּוּשִׁין בָּהֶם וּצְרִיכָה גֵּט, בֵּין קִדְּשָׁהּ לְשֵׁם אִשּׁוּת כְּגוֹן שֶׁקִּדְּשָׁהּ סְתָם, \u0010c8\u0011 בֵּין לְשֵׁם יַבְמוּת כְּגוֹן שֶׁאָמַר לָהּ: הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי לְזִקַּת יְבָמִים:\nהָא דְּאֵין מַעֲשֶׂה מוֹעִיל אַחַר בִּיאָה, דַוְקָא בְּבִיאָה כְּשֵׁרָה שֶׁלֹּא קָדַם לָהּ מַעֲשֶׂה אַחֵר. \u0010c9\u0011 אֲבָל בִּיאָה פְּסוּלָה, כְּגוֹן שֶׁנָּתַן גֵּט לָזוֹ וּבָעַל אֶת זוֹ, אוֹ עָשָׂה מַאֲמָר בָּזוֹ וּבָעַל אֶת זוֹ, מוֹעִיל מַעֲשֶׂה שֶׁיַּעֲשׂוּ אַחֲרֶיהָ, שֶׁאִם יַחֲלֹץ הוּא אוֹ אָחִיו לַשְּׁלִישִׁית, יֵאָסְרוּ בִּקְרוֹבוֹתֶיהָ, וְגַם הִיא לֹא סָגֵי לָהּ בְּגֵט, דְּאַכַּתִּי נִשְׁאָר בָּהּ זִקָּה. אֲבָל חֲלִיצָה, אֲפִלּוּ הִיא פְּסוּלָה, שֶׁקָּדַם לָהּ מַעֲשֶׂה אַחֵר, כְּגוֹן שֶׁנָּתַן גֵּט לָזוֹ אוֹ מַאֲמָר בָּזוֹ, וְאַחַר כָּךְ חָלַץ לָהּ אוֹ לְצָרָתָהּ, אֲפִלּוּ הָכִי אֵין מוֹעִיל אַחֲרֶיהָ, אִם חָזַר הוּא אוֹ אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ; אֲבָל אִם בָּעַל אוֹ קִדֵּשׁ, תָּפְסוּ בָּהּ:\nעָשָׂה מַאֲמָר בִּיבִמְתּוֹ וְאַחַר כָּךְ נָתַן לָהּ גֵּט לְזִקָּתָהּ, פָּסְלָה עָלָיו וְעַל כָּל הָאַחִין, וּצְרִיכָה גֵּט לְמַאֲמָרָהּ וַחֲלִיצָה לְזִקָּתָהּ. \u0005 וְאִם נָתַן לָהּ גֵּט סְתָם, הָוֵי כְּאִלּוּ פֵּרַשׁ לְזִקָּתָהּ. \u0006 נָתַן לָהּ גֵּט לְמַאֲמָרָהּ וְלֹא לְזִקָּתָהּ, נִשְׁאֲרָה זְקוּקָה כְּמוֹ שֶׁהָיְתָה, וְאֵינָהּ מֻתֶּרֶת אֶלָּא לִשְׁאָר אַחִים, אֲבָל הַמְגָרֵשׁ אָסוּר בָּהּ. \u0010c10\u0011 וְיֵשׁ אוֹמְרִים שֶׁמֻּתֶּרֶת אַף לַמְגָרֵשׁ:\nבִּיאַת בֶּן תִּשְׁעָה כְּמַאֲמָר בְּגָדוֹל. לְפִיכָךְ, בָּא עַל הַיְבָמָה, פְּסָלָהּ עַל כָּל הָאַחִים. וְאִם אַחַר שֶׁבָּא עָלֶיהָ חָזַר אָחִיו הַגָּדוֹל וּבָא עָלֶיהָ אוֹ עַל צָרָתָהּ, אוֹ עָשָׂה מַאֲמָר אוֹ נָתַן גֵּט אוֹ חָלַץ לָהּ אוֹ לְצָרָתָהּ, פְּסָלָהּ עַל הַקָּטָן. וְכֵן אִם חָזַר הַקָּטָן וּבָא עַל צָרָתָהּ, אוֹ שֶׁאָחִיו בֶּן ט' בָּא עָלֶיהָ אוֹ עַל צָרָתָהּ, פְּסָלָהּ עָלָיו כְּדִין מַאֲמָר אַחַר מַאֲמָר. וְכֵן אִם עָשָׂה הַגָּדוֹל מַאֲמָר בִּיבָמָה, וְחָזַר אָחִיו בֶּן ט' וּבָא עָלֶיהָ אוֹ עַל צָרָתָהּ, פְּסָלָהּ כְּדִין מַאֲמָר אַחַר מַאֲמָר. \u0010c11\u0011 וּמַאֲמָר שֶׁל בֶּן ט' אֵינוֹ חָשׁוּב כְּמַאֲמַר הַגָּדוֹל, וְאֵינוֹ מוֹעִיל אֶלָּא בִּתְחִלָּה, אֲבָל לֹא בַּסוֹף. כֵּיצַד, עָשָׂה קָטָן מַאֲמָר, מוֹעִיל לְפָסְלָהּ עַל הָאַחִים. אֲבָל אִם עָשָׂה הַגָּדוֹל מַאֲמָר, וְחָזַר בֶּן ט' וְעָשָׂה מַאֲמָר בָּהּ אוֹ בְּצָרָתָהּ, אֵינוֹ מוֹעִיל לְפָסְלָהּ עַל הָאָח הַגָּדוֹל. אֲבָל מַאֲמָרוֹ שֶׁל בֶּן ט', אַחַר מַאֲמָר בֶּן ט', אִכָּא לִמֵימַר שֶׁמּוֹעִיל, כֵּיוָן שֶׁמַּאֲמַר הָרִאשׁוֹן מִבֶּן ט'. וְגֵט וַחֲלִיצָה, אֵין לַקָּטָן כְּלָל, לֹא בִּתְחִלָּה וְלֹא בַּסוֹף:\nגָּדוֹל שֶׁעָשָׂה מַאֲמָר בִּיבָמָה אוֹ נָתַן לָהּ גֵּט וְלָהּ צָרָה, כְּשֶׁבָּא לַחֲלֹץ לְאַחַת מֵהֶן וּלְהַתִּירָן, אֵין חֲלִיצַת בַּעֲלַת הַגֵּט אוֹ בַּעֲלַת הַמַּאֲמָר פּוֹטֶרֶת הַצָּרָה. אֲבָל חֲלִיצַת הַצָּרָה פּוֹטֶרֶת לְבַעֲלַת הַגֵּט לְגַמְרֵי, וּלְבַעֲלַת הַמַּאֲמָר מֵחֲלִיצָה, וּצְרִיכָה עוֹד גֵּט לְמַאֲמָרָהּ. וְאִם עָשָׂה מַאֲמָר בָּזוֹ וְנָתַן גֵּט לָזוֹ, חוֹלֵץ לְאֵיזוֹ שֶׁיִּרְצֶה וּפוֹטֵר הַשְּׁנִיָּה, כְּמוֹ שֶׁנִּתְבָּאֵר:\nמִי שֶׁנָּפְלוּ לְפָנָיו שְׁתֵּי יְבָמוֹת מִבַּיִת אֶחָד, הָאַחַת שְׁנִיָּה לְיָבָם וְאַחֶרֶת \u0005 מֻתֶּרֶת, \u0006 כְּשֶׁהוּא מְיַבֵּם מְיַבֵּם לָאַחֶרֶת, כְּשֶׁהוּא חוֹלֵץ \u0010c12\u0011 חוֹלֵץ לַשְּׁנִיָּה. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאִם חָלַץ לַאֲסוּרָה, לֹא הֻתְּרָה צָרָתָהּ; חָלַץ לַצָּרָה, הֻתְּרָה הָאֲסוּרָה:\nיְבָמוֹת רַבּוֹת הַבָּאוֹת מִבַּיִת אֶחָד, כֵּיוָן שֶׁנִּבְעֲלָה אַחַת מֵהֶן בְּעִילָה כְּשֵׁרָה, אוֹ נֶחְלְצָה חֲלִיצָה מְעֻלָּה, הֻתְּרוּ הַכֹּל וְנִסְתַּלְּקָה זִקַּת הַיָּבָּם מֵעֲלֵיהֶן. וְאִם נִבְעֲלָה אַחַת מֵהֶן בְּעִילָה פְּסוּלָה, אוֹ נָתַן לָהּ מַאֲמָר פָּסוּל, נֶאֶסְרוּ כֻּלָּם לְיִבּוּם, וּצְרִיכָה גֵּט זוֹ שֶׁנִּבְעֲלָה אוֹ שֶׁנָּתַן לָהּ מַאֲמָר, \u0010c13\u0011 וּצְרִיכָה כָּל אַחַת מֵהֶן חֲלִיצָה לְהַתִּירָהּ לְזָר, שֶׁאֵין זִקַּת הַיִּבּוּם מִסְתַּלֶּקֶת בִּבְעִילָה פְּחוּתָה. נֶחְלְצָה אַחַת מֵהֶן חֲלִיצָה פְּחוּתָה, הֻתְּרָה לְהִנָּשֵׂא לְזָר אוֹתָהּ שֶׁנֶּחְלְצָה, אֲבָל צָרָתָהּ אֲסוּרָה עַד שֶׁתַּחֲלֹץ גַּם הִיא, אוֹ עַד שֶׁיַּחְלְצוּ כָּל הָאַחִים לָרִאשׁוֹנָה שֶׁנֶּחְלְצָה הַחֲלִיצָה הַפְּחוּתָה, שֶׁאֵין חֲלִיצָה פְּחוּתָה מְסַלֶּקֶת זִקַּת יִבּוּם מִבַּיִת זֶה, עַד שֶׁתַּחֲזֹר עַל כָּל הָאַחִים, אוֹ עַד שֶׁתַּחֲלֹץ כָּל אַחַת מֵהֶן. זֶהוּ דַּעַת הָרַמְבַּ\"ם \u0005(ח\"ב קי\"ח ב')\u0006, וְנֶחְלְקוּ עָלָיו \u0005 כְּמוֹ שֶׁהוּא מְפֹרָשׁ בְּדִבְרֵי הַטּוּר: \u0006\nשְׁנֵי יְבָמִים שֶׁיִּבְּמוּ שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד, וְלֹא נוֹדַע מִי יִבֵּם תְּחִלָּה, שְׁנֵיהֶם יוֹצִיאוּ בְּגֵט, וְיֻתְּרוּ לְזָרִים, וַאֲסוּרוֹת לִיְבָמִים. לְפִיכָךְ, רְאוּבֵן שֶׁהָיוּ לוֹ שְׁתֵּי נָשִׁים, אַחַת בְּעַכּוֹ וְאַחַת בְּצוֹר, וְשִׁמְעוֹן וְלֵוִי אֶחָיו, הָאֶחָד בְּעַכּוֹ וְהָאֶחָד בְּצוֹר, וְשָׁמְעוּ שֶׁמֵּת רְאוּבֵן לֹא יְיַבֵּם אֶחָד מֵהֶם עַד שֶׁיֵּדַע מֶה עָשָׂה אָחִיו. \u0010c14\u0011 קָדַם אֶחָד מֵהֶם וְיִבֵּם, אֵין מוֹצִיאִין מִיָּדוֹ עַד שֶׁיִּוָּדַע שֶׁאָחִיו יִבֵּם תְּחִלָּה:",[],["\u0003מדבריהם\u0004. הטעם מבואר בש\"ס מדהגט וקידושין מהני בעלמא חיישינן דיאמרו הואיל הגט לא מהני ומותרת ליבם ה\"ה אחר החליצ' מותרת ליבם אף על גב דהגט לא מהני אלא מדרבנן מ\"מ עשאו בכל הגט אפי' גט דלא מהני באשה בעלמא רק פוסל לכהונה מ\"מ מהני ביבמה דאסורה ליבם וכן מאמר דמהני בעלמא יאמרו מדמאמר לא מהני ומותר לישא השניה כן מותרת השניה אחר הביאה ואתי למבעל אחר הביאה והוה ליה בונה שני בתים ועיין לקמן:","\u0003נאסר בקרובות שתיהן\u0004. הנה ליש מי שאומר שהביא בסעיף ה' בשתי יבמות לא נפטרה הצרה בחליצה פסולה כזו שנתן גט לראשונה וצריך לחלוץ אף לשניה אם כן ממילא אסור בקרובות שתיהן אפילו לא תפס הגט בשניה אלא נ\"מ אף אם לא חלץ לשניה:","\u0003ויש מי שאומר\u0004. מקור דין זה נובע מסוגיא ר\"פ ד' אחים דאיתא שם בעלת מאמר ובעלת גט כי הדדי נינהו ופרש\"י שחליצת א' מהן פוטרת חברתה כיון שהן שוין דבעלת מאמר צריכה נמי גט וכתבו תוספות והרא\"ש דאתי' סוגי' זו כשמואל ואליבי' תירוץ הראשון בסוגי' הקודמות לזו ובג' אחיות הנופלות לפני ב' האחים זו אחר זו דס\"ל לשמואל א' חולץ לאחת והשני לשניה ולשלישית חולץ א' מהם אף על פי שהיא חליצה פסולה א\"צ לחזור על כל האחים ולפי תירוץ זה אין חילוק בין היבמה ובין צרתה א\"כ נשמע נמי בצרתה אם שניהם שוין פוטרת א' לחברתה כשם שיבמה שלישית נפטרה בחליצה א' אעפ\"י שאסורה עליו משום אחות חלוצתו מ\"מ פוטר כיון שאחיו ג\"כ שוה לו באיסור ש\"מ כל ששוים פוטר זא\"ז ולרב כשם דס\"ל דשלישית צריכה חליצה מכל א' כן ה\"נ אם נתן גט לשתי יבמות צריכה כל אחת חליצה ורש\"י לא פירש בסוגי' זו תלי' בפלוגתת רב ושמואל הנ\"ל מזה דייק הטור דס\"ל לרש\"י בשתי יבמות עדיף אף לרב א\"צ חליצה כל אחת וכן משמע מדבריו ר\"פ ר\"ג מאמר בזו ומאמר בזו ע\"ש ולזה נתכוון הטור מ\"ש בדין זה בשם רש\"י דחולק על יש מי שאומר שהבי' כאן וא\"צ דחיק' הב\"ח ע\"ש, והנה בסמוך סעיף ז' הבי' ג\"כ דיעה זו בשם יש מי שאומר ותימ' עליו אף דיש לדייק מרש\"י כהנ\"ל מ\"מ מדברי תו' והרא\"ש משמע דאתי' כשמואל אבל לרב לא עדיף חליצה פסולה זו בשתי יבמות מחליצה פסולה שני יבמים וצריכים כולם חליצה וכן הוא לדעת רש\"י שהבי' הרא\"ש וגם למ\"ש בסעיף י\"ט מבואר אף להרמב\"ם ס\"ל כן ושם נתבאר בס\"ד:","\u0003והא דחליצה פסולה\u0004. כ\"כ בד\"מ בשם א\"ז, וכבר כתבתי כן בשם תוס' ועיין בת\"ה סימן רכ\"ה קטנה שחלצה בטעות אחר שהגדילה א\"צ לחזור על כל האחים דחליצת קטנה אינה חליצה כלל וכו' ש\"מ כל מה דאינה חליצה מדאורייתא לא קלשה הזיקה וא\"צ לחזור ע\"כ האחים:","\u0003וחליצה לאחת מהן\u0004. גם כאן לטעמיה אזיל כמ\"ש בסעיף הקודם דס\"ל יבם א' וב' יבמות ונתן גט לכ\"א די בחליצה לאחת מהן כן ה\"נ אם עשה מאמר בזו ובזו צריכה כ\"א גט מ\"מ די בחליצה א' וכן אם עשה הוא מאמר בא' ואחיו בשניה צריכה כ\"א גט ודי בחליצה אחת לא' משתיהן, היינו אם הוא נותן חליצה חולץ לשניה מה שאחיו גירש אז זו נפטרה בחליצה זו מאחר שזה לא גירש אותה ועדיף חליצתו בה מחליצת אחיו ושני' גם כן פטורה מחמת חליצה זו, ואם הוא עשה מאמר בזו ואחיו עשה ג\"כ בזו באמת צריכה חליצה מכל א' כמ\"ש בסעיף הקודם ולא כתב כאן אלא חליצה לאחת מהן מאלו יבמות שנתנו לה הגט:","\u0003ונתן לה הגט\u0004. אפילו נתן לה גט סתם א\"צ גט אחר והוי גט למאמר ולזיקה ומ\"ש בהגהות סעיף ט\"ו לא כתב אלא לענין אם נאסרת לשאר אחים ועיין תוס' ריש פר\"ג:","\u0003ויש מי שאומר\u0004. כאן הביא דיעה זו ובכמה סעיפים סותם ופסק דחליצת א' מהן פוטרת את חברתה:","\u0003לפיכך אין המעשה וכו' מועיל\u0004. בביאה שפיר לא מהני בה שום מעשה אף על גב דמהני בצרתה, אבל בחליצה מהני אף בה דאם קידש או בעיל וע\"כ צ\"ל מ\"ש אין המעשה מועיל סמך אמ\"ש כיצד כלומר המעשה המבואר אין מועיל אבל ביאה וקידושין מועיל ואסור בקרוביה של צרתה אם בא עליה דהא צריכה גט ממנו, וכ\"כ בפרישה סעיף כ\"ב ולא כמ\"ש בדרישה וקידושין בצרתה אחר שבעיל את זו אם אמר בזיקת יבמים דינו כמו קידושין אחר שחלץ והכל דין א' כמ\"ש בסעיף י\"ג ואם קידש סתם קידושין דאורייתא כי אז פרח הזיקה ועיין בסמוך:","\u0003בין לשם יבמות\u0004. עיין בהרא\"ש והנה לדעת הרי\"ף ורמב\"ם והרא\"ש וכן דעת הרמב\"ן במלחמות ה' אפילו חלץ חליצה כשירה ואמר מקודשת לי בזיק' יבמה תפסו בה קידושין כי היכי דתקנו חז\"ל דקדושין ביבמה תופסים כך קדושין אלו אחר החליצה תופסים בה אף שהוא סבר שהיא יבמתו ובאמת היא אחר החליצה לאו יבמתו מ\"מ קידושין תופסין בה מדרבנן אלא החילוק הוא אם קדשה בסתם או לשם אישות אז הוי קידושין דאורייתא אף על פי שהיא אסור' עליו בלאו כמ\"ש בסי' קס\"ב מ\"מ מדאורייתא הוי קידושין גמורים אבל אם קידש בזיקת יבמי' אפי' אם חלץ חליצה פסולה לפי מה דקי\"ל חליצה פסולה פוטרת תו ליכא קידושין דאוריית' ועיין בש\"ג שם ס\"פ ר\"ג ונראה אף למ\"ד חליצה פסולה צריכה לחזור ע\"כ האחים אם חלץ לה ח\"פ ויש כאן שאר אחים וקידש אותה בזיקת יבמים החולץ אף שעדיין יש עליה זיקה וצריכה חליצ' משאר אחים מ\"מ קדושין אינן תופסים מדאורייתא:","\u0003אבל ביאה פסולה וכו'\u0004. היינו חז\"ל עשאו זאת דמהני אחר ביאה פסולה דאי ביאה אחר הגט גזירה משום ביאה אחר חליצה כלומר אם יקנה הביאה אחר הגט קניה גמורה אתי למבעל לכתחלה אחר החליצ' ואם ביאה אחר המאמר גזרי' אטו ביאה אחר ביאה כלומר אתי למבעל צרה זו אחר שייבם אחת מהן אבל החליצה אף שהוא ח\"פ ליכא למגזר כלום ועיין בש\"ס:","\u0003וי\"א שמותרת אף למגרש\u0004. וא\"ל לפ\"ז למה תני מאמר בזו ומאמר בזו צריכה גט כ\"א וחליצה ואסור לייבם, למה לא יתן גט למאמר בפירוש ואז מותרת לו וגם לדיעה קמייתא קשה יתן גט למאמר לאחת ולייבם השני תירצו תוס' פד\"א דף ל\"ב לכתחלה אין לעשות כן דגזרנן גט למאמרו אטו גט לזיקתו ודוקא בדיעבד קאמר הכי דאם גירש למאמרו הותרה:","\u0003ומאמר של בן ט' וכו'\u0004. באמת לא מצינו שום טעם למה מאמר של קטן מהני לפי הטעם ר\"פ ר\"ג שהבאתי רס\"ז דמאמר מהני בגדול הטעם דגזרינן הואיל ומאמר היינו קידושין מהני בעלמא וביבמה לא מהני יאמר אף הביאה לא מהני א\"כ בקטן דאינו קונה לא שייך גזירה זו והנה פ\"ק דקדושין דף י\"ט איתא שם דרש\"י ותוס' מחולקים בקטן הבא על יבמתו לרש\"י קונה אותה מדאורייתא לכל מילי רק הבא עליה אין חייב משום א\"א לפ\"ז י\"ל דאיכ' נמי צד איסור דאוריית' אם בא עליה אחיו אחר שבא עליה הקטן משום איסור אשת אחיו והוי כמו החולץ בא עליה בזה שפיר הגזירה מדקדושין וביאה של קטן בעלמא אינו כלום יאמרו ביבמה ג\"כ אינו כלום ויבא עליה אחיו אבל לשיטת התוס' דס\"ל דביאה של קטן ביבמה מדרבנן כמו מאמר דגדול א\"כ מנ\"ל לגזור אטו ביאה כיון אחר הביאה ג\"כ אין איסור, ועיין במגיד פ\"ה הביא ג\"כ פלוגתא זו וצ\"ע, וליורשה ולטמא לה תלי' נמי בפלוגת' זו כמ\"ש שם לפ\"ז אפשר מ\"ש רש\"י בנדה דזוכה בנכסי אחיו והבאתי ר\"ס קס\"ז י\"ל רש\"י לטעמיה דס\"ל דהוי קנין גמור אבל לשיטת שאר פוסקים אינו זוכה בשום דבר מדין עד שיגדיל:","\u0003חולץ לשניה\u0004. כ\"כ המגיד פ\"ז בשם ה\"ג אף על גב דקי\"ל חליצה פסולה אינה פוטרת צרתה היינו דוקא שנאסרה עליו בזיקה כגון שעשה בה מאמר או נתן לה גט אבל כשאסורה עליו מתחלתן חליצה כשרה היא וכ\"כ תוספ' ר\"פ ד\"א והיינו כמ\"ש בהגהות רס\"ז וכ\"פ הש\"ג ויש מי שאומר הוא דעת הרמב\"ם והטור וכן משמע מרש\"י ר\"פ ד\"א דס\"ל דשוה לדין בעלת גט ובעלת מאמר, אלא דקשה לפ\"ז מבריית' פ\"ב דף כ' דתני איסור מצוה ואיסור קדושה חלץ לה נפטר צרתה, וב\"ח כתב דבריית' זו איירי מדאוריית' פוטרת אלא מדרבנן תקנו דח\"פ אין פוטרת ול\"ד דהא איסור מצוה ואיסור קדושה תנא וא' מהם היינו שניות א\"כ אף מדרבנן פוטר ואפשר ליישב למ\"ש שם לצדדים אתמר בא עליה קאי על איסור מצוה שהוא מדרבנן וחלץ לה קאי על איסור קדושה וי\"ל דאיירי דצרתה גם כן אסורה כמותה מ\"ה באיסור מצוה שהיא מדרבנן מ\"מ פוטר בביאה כשהיא וצרתה שוין כמ\"ש ר\"ס קע\"א ובאיסור קדושה פוטרת מדאוריית' בחליצה והנה לפוסקים דס\"ל בצרות כשהם שוים באיסור פוטרת זא\"ז כמ\"ש רס\"ז י\"ל הברייתא איירי כשהצרה ג\"כ איסור מצוה וכ\"כ המגיד אלא לפי פירושו לדעת הרמב\"ם דס\"ל אף כשצרות שוים מ\"מ אין פוטרת זא\"ז קשה לו ליישב וע\"ש ובסמוך יתבאר זאת ועל המחבר תימא שהביא דעת הרמב\"ם בשם יש מי שאומר ש\"מ עיקר כדיעה קמייתא ובסימן קע\"ד סותם ופוסק כרמב\"ם גם על רמ\"א קשה שכתב בסימן קס\"ז בענין חליצה פסולה דוקא שהיתה זקוקה ונפסלה והיינו כדיעה קמייתא ושם בר\"ס קע\"ד לא הגיה כלום:","\u0003וצריכה כ\"א מהן חליצה\u0004. כ\"כ המגיד עיקר הגירס' ברמב\"ם כך היא ובטור הביא דברי הרמב\"ם ושם כתב וצריכה אחת מהן חליצה גם לא כתב בסוף דבריו עד שתחלוץ כל א' ודוחק לומר שדולג מדברי הרמב\"ם מה שחולק על הטור בענין אם הצרות שוים פוטרת זא\"ז בחליצה של אחת מהן, ולפי הגירסא בטור ס\"ל לרמב\"ם נמי כשהן שוים פוטרת זא\"ז ומ\"ש וצריכה אחת מהן חליצה היינו א' מצרות ולא זו שנבעלה ביאה פסולה או נתן לה מאמר פסול, ואם נחלצה א' משאר צרות אז כולם פטורות כי זו שנבעלה פשיטא פטורה דהא חליצתה גרוע מחליצה זו ושאר צרות שוים לזו ופטורה כמו בעלת מאמר ובעלת גט לפ\"ז ל\"ק נמי הברייתא איסור מצוה ואיסור קדושה נפטרה צרתה כמ\"ש בסעיף הקודם לפ\"ז אם נפלו לפניו ב' אחיות מב' בתים ולכ\"א צרה א' אם חלץ לאחיות לא נפטרו הצרות שום אחת מצרות לא נפטרה כגון אם חלץ לאה בראשון והוי ח\"פ משום דהיא אחות זקוקה מ\"ה לא נפטרה הצרה, ואם אח\"כ חלץ לרחל שהיא אחות חליצתו לא נפטרה הצרה דלא שוה רחל עם הצרה אף על גב דהצרה ג\"כ אסורה משום צרות קרובת חליצתו מ\"מ קרובת חליצתו גרע, כן הוא לפי תירוץ רב אשי דקי\"ל כוותיה אף על גב לפי תירוץ התחיל ולא התחיל מוכח דשוים נינהו מ\"מ לתירוץ רב אשי חליצת רחל גרועה טפי ועיין בהרא\"ש שם אבל לפי הגירסא שכתב כאן והיינו גירסת המגיד ס\"ל לרמב\"ם ח\"פ אינה פוטרת צרתה אפי' כשהן שוין בפסול מ\"ה צריכה כ\"א חליצה והיינו שאר צרות ועליהן כתב כ\"א ולא דיבר כאן מזו שנפסלה בגט או במאמר שזו בוודאי נפטרה בחליצת אחרת ולא כהבנת המגיד מ\"ש צריכה כ\"א והיינו זו שנפסלה וכ\"א משאר צרות ותמה על הרמב\"ם למה לא נפטרה זו בחליצת שאר צרות כמו חלץ לצרה נפטרה בעלת הגט דאמר שמואל, וא\"ל לפ\"ז על המחבר שסתם ופסק כמה פעמים בסימן זה דח\"פ פוטרת צרתה כשהן שוין וכאן הביא דעת הרמב\"ם דצריכה כ\"א חליצה, וי\"ל דסמך את עצמו על מה שמסיים ונחלקו עליו וס\"ל עיקר כדעת החולקי' אלא הביא דברי הרמב\"ם דנשמע מדבריו כמה דינים דח\"פ פוטרת לזו וגם אם חלצו כל האחים לזו פוטרת את אחרת ועיין במגיד שכתב בשם הרמב\"ן והרשב\"א דחולקים עליו בזה ואף לפי גירסא זו י\"ל הברייתא איסור מצוה ואיסור קדושה דס\"ל לרמב\"ם אף על גב ח\"פ אין פוטרת את צרתה אפילו בשוין מ\"מ באיסור שבכה\"ג איסור מצוה ואיסור קדושה שאסור מתחלתה ולא נפקעה הזיקה פוטרת את צרתה כשהן שוין, וכשהיא פטורה בח\"פ איתא בסוגיא שני תירוצים לתירוץ א' אפילו לכתחלה לא מהדרין אחר חליצה כשרה כגון אם כבר חלץ ראובן לאחת וזו אחות חליצתו ויש כאן אחר מ\"מ חולץ ראובן לזו וכ\"פ הרי\"ף אבל לדעת הראב\"ד והרא\"ש דכל מה שאפשר לחלוץ חליצה כשרה מהדרין אחר חליצה כשירה אפילו למפטר נפשיה לפ\"ז אם א' מאחין נתן גט מהדרין שיחלוץ אחר ולא הוא אף על פי שהוא שליח דכולם לענין איסור דכולם אסורין לייבם מחמת גיטו, ולכאורה נראה לדעת הרא\"ש אפילו בדיעבד לא נפטרה היא מאחר דאפשר לחלוץ מאח השני דהא הוא תופס עיקר התירוץ הראשון חולץ לכולם היינו אמצעית ולההיא שינויא לא מפליגין בין מפטר נפשה למפטר צרה אם כן כשם אם חלץ לבעלת גט לא נפטרה הצרה אף בדיעבד כן הוא אם חלץ אח אחד שחליצתו פסולה טפי משני לא נפטרה זו כמ\"ש שם מפורש בתוס' ובהרא\"ש מ\"ה כתבו לפי תירוץ זה כל ששווים פטורה זו בחליצת זו וכן באחים אם הם שווים ש\"מ אם אין שוין אפילו בדיעבד לא נפטרה ולכאורה קשה על הטור שכתב בשם הראב\"ד לכתחלה מהדרין אחר חליצה כשרה לפטור את עצמה ובדיעבד מה דעבד עבד וכתב ולזה הסכים הרא\"ש ולכאורה לא משמע כן אף שהביא הרא\"ש דברי הראב\"ד מ\"מ לפסק הלכה לפי מה שפסק הרא\"ש בתירוץ קמא לפי דאתי אליביה דרב אשי כמ\"ש בתוספות משמע דס\"ל אף בדיעבד לא נפטרה, ואפשר דס\"ל כמ\"ש ברי\"ו דקי\"ל כתרי תירוצים בש\"ס לכתחילה מהדרין אחר חליצת כשירה כתירוץ הראשון ובדיעבד מהני ח\"פ כתירוץ שני דמחלק בין למפטר נפשיה ובין למפטר צרה ועיין ב\"ח שהביא דברי רי\"ו ג\"כ מיהו לישנא דהרא\"ש מ\"ש הלכך האי שינויא עיקר לא נתיישב לפ\"ז, עיין בהרא\"ש שכתב שתים הראשונים אי נפלו בבת אחת זה חולץ לאחת וזה חולץ לאחת, וטעמו משום ח\"פ א\"צ חזר' ע\"כ אחין מ\"ה הראשונה אף על גב דאסורה משום אחות זקוקתו מ\"מ א\"צ חזרה ע\"כ אחים והשניה אסורה לראשון משום אחות חלוצתו ולשני אסורה משום אחות זקוקתו יותר טוב שיחלוץ השני אף שאסורה עליו משום אחות זקוקתו, ומ\"ש אי נפלו בבת אחת לרבותא כ\"כ ומכ\"ש אי נפלו זא\"ז ואפשר צריך להיות הגירסא אפי' נפלו בבת אחת, וראיתי בב\"ח מגי' אי לא נפלו בבת א' ולכאורה נראה כמ\"ש דיותר עדיף שיחלוץ זה שאסורה עליו משום זיקא דהא לזה שחלץ אסורה משום אחות חלוצה ובאמת עדיין הן זקוקים לו ואסורה משום אחות זקוקה:","\u0003קדם א' מהם\u0004. עיין ברמב\"ם פ\"ה מסיים וכתב רצה א' לחלוץ קודם שידע מה עשה אחיו אין מונעים אותו והמחבר דילג משום דהקשה עליו בכ\"מ ובבדק הבית דיש לחוש שמא כבר ייבם אחיו ואם כן החליצה אינו ואתה מצריכה כרוז לכהונה כמ\"ש באשה שהלך בעלה וצרתה למ\"י וכמ\"ש בס\"ס ק\"מ ובאמת על קושיא זו י\"ל דאין חשש שייב' אחיו דהא אסור לייבם עד שנדע מיבמה שניה אלא זאת קשה שמא חלץ אחיו ולמ\"ש שם לק\"מ ועיין ב\"ח ודרישה, והב\"י כתב בשם תשובת הגאונים בשני יבמים שייבמו שתי יבמות דצריכין לגרש וצריך לחלוץ אחת דיש לחוש שמא א' עשה בה מאמר ואח\"כ בא אחיו על השניה והוי ביאה אחר מאמר, ואף שבעל המאמר בא אח\"כ על הראשונה מכל מקום ביאתו פסולה:"]],["מִי שֶׁהָיָה נָשׂוּי יְתוֹמָה קְטַנָּה \u0005 שֶׁהִשִּׂיאוּהָ אָחִיהָ וְאִמָּהּ, שֶׁאֵין קִדּוּשֶׁיהָ רַק מִדְּרַבָּנָן, \u0006 וְחֵרֶשֶׁת, וּמֵת, וְנָפְלוּ לִפְנֵי אָחִיו \u0010c0\u0011 לְיִבּוּם, אֵין בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת צָרָתָהּ. וְכֵיצַד תַּקָּנָתָם, מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וְכוֹנֵס אֶת הַחֵרֶשֶׁת. וְאִם רָצָה לְגָרְשָׁהּ, כּוֹתֵב לָהּ גֵּט אַחַר שֶׁיָּבֹא עָלֶיהָ, וּמֻתֶּרֶת לְזָר:\nהָיוּ שְׁתֵּיהֶן חֵרְשׁוֹת אוֹ קְטַנּוֹת, \u0010c1\u0011 בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת צָרָתָהּ:\nהָיְתָה אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה, בִּיאַת גְּדוֹלָה אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת הַקְּטַנָּה, וְאֵין בִּיאַת הַקְּטַנָּה פּוֹטֶרֶת אֶת הַגְּדוֹלָה:\nאַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, בִּיאַת הַפִּקַּחַת אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת אֶת הַחֵרֶשֶׁת, וְאֵין בִּיאַת הַחֵרֶשֶׁת פּוֹטֶרֶת אֶת הַפִּקַּחַת:\nהָיוּ שְׁתֵּיהֶן קְטַנּוֹת, וּבָא הַיָּבָם עַל אַחַת מֵהֶן, וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַשְּׁנִיָּה, \u0010c2\u0011 לֹא פָּסַל הָרִאשׁוֹנָה עָלָיו, אֲבָל אָסוּר לוֹ לְקַיֵּם הַשְּׁנִיָּה, אֶלָּא מְלַמְּדִין אוֹתָהּ שֶׁתְּמָאֵן, וִיקַיֵּם הָרִאשׁוֹנָה:\nוְכֵן אִם הָיוּ שְׁתֵּיהֶן חֵרְשׁוֹת, אֵין בִּיאַת הַשְּׁנִיָּה פּוֹסֶלֶת הָרִאשׁוֹנָה, וְהַשְּׁנִיָּה אֲסוּרָה לוֹ וְיוֹצִיאֶנָּה בְּגֵט:\nקְטַנָּה וְחֵרֶשֶׁת, שֶׁבָּא הַיָּבָם תְּחִלָּה עַל הַקְּטַנָּה, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת, \u0010c3\u0011 לֹא פָּסַל אֶת הַקְּטַנָּה, וְהַחֵרֶשֶׁת צְרִיכָה גֵּט, שֶׁבִּיאַת הַקְּטַנָּה מְעֻלָּה מִבִּיאַת הַחֵרֶשֶׁת, שֶׁהַקְּטַנָּה רְאוּיָה לְאַחַר זְמַן. לְפִיכָךְ, יְקַיֵּם הַקְּטַנָּה שֶׁנִּבְעֲלָה תְּחִלָּה:\nבָּא עַל הַחֵרֶשֶׁת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה, פָּסַל אֶת הַחֵרֶשֶׁת. וּמְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וְיוֹצִיא הַחֵרֶשֶׁת בְּגֵט. \u0005 זֶהוּ דַּעַת הָרַמְבַּ\"ם, אֲבָל אֲחֵרִים חוֹלְקִים עָלָיו כַּמְפֹרָשׁ בַּטּוּר וּבְנִמּוּקֵי יוֹסֵף פֶּרֶק בֵּית שַׁמַּאי: \u0006\nאַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, בָּא הַיָּבָם עַל הַפִּקַּחַת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת, לֹא פָּסַל הַפִּקַּחַת, וְהַחֵרֶשֶׁת צְרִיכָה גֵּט. בָּא הַיָּבָם עַל הַחֵרֶשֶׁת, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַפִּקַּחַת, פָּסַל אֶת הַחֵרֶשֶׁת; הַחֵרֶשֶׁת יוֹצְאָה בְּגֵט, וְהַפִּקַּחַת בְּגֵט וַחֲלִיצָה:\nאַחַת גְּדוֹלָה וְאַחַת קְטַנָּה, בָּא עַל הַגְּדוֹלָה, וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה, לֹא פָּסַל הַגְּדוֹלָה, וּמְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ. בָּא עַל הַקְּטַנָּה, וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַגְּדוֹלָה, מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן בּוֹ, וִיקַיֵּם הַגְּדוֹלָה:",[],["\u0003אין ביאת אחת מהן פוטרת\u0004. מפורש בש\"ס קטנה ספק קנויה וחרשת קנויה ומשויירת לכן אין חליצה אחת פוטרת את חברתה בין אם נפלו מפקח ובין אם נפלו מחרש והסכימו רוב הפוסקים מלמדין הקטנה שתמאן בו ואם לא תרצה למאן אז לכ\"ע מייבם את החרשת ויוציא אותה בגט ותמתין לקטנה עד שתגדיל וחולצת ואם ייבם את הקטנה אז אין תקנה לחרש כי א\"י לייבם אותה מאחר שכבר ייבם א' מבית זה והיא אין בת חליצה ועיין בש\"ג פ' ב\"ש:","\u0003ביאת א'\u0004. כלומר בקטנות וחרשות אין פוטרת צרות בחליצה אפי' הצרה שוה לה אבל בביאה פוטרת כששוה לה:","\u0003לא פסל הראשונה\u0004. ממ\"נ אם קנויה היא אם כן קנה הראשונה תו לא פסלה השניה את הראשונה כמו בגדולה אם בא על אחת תו ביאת השניה לא פסלת, ואם אינה קנויה א\"כ הוי כאלו שתיהם נכריות ומקיים הראשונה ולא את השניה שמא הראשונה קנויה היא והשניה צריכה מיאון דהא הביאה מהני בה וכן בשתיהן חרשת נמי אין השניה פוסלת את הראשונה אלא הביאה מהני בה וצריכה גט:","\u0003לא פסל את הקטנה\u0004. כן הוא הגירסא במתני' לשיטת הרי\"ף והרמב\"ם והטעם משום ממ\"נ הנ\"ל, אבל בא על החרשת ואח\"כ על הקטנה פוסלת את החרשת כי החרשת קנוי' ואינה קנויה והקטנה שמא קנויה הוא ואז קנויה היא לגמרי ופוסלת את החרשת וסבירא לי' לרמב\"ם דאז אסור בשתיהן מאחר בעת הביאה של הקטנה היתה החרשת פסולה עליו תו לא מהני מיאון דקטנה לקיים את החרשת כיון דבחרשת ליכא מצות יבום גמור משא\"כ כשבא על הגדולה אחר שבא על הקטנה מלמדין לקטנה שתמאן ומותר בגדול' כיון שמקיים בגדולה מצות יבום:"]],["\u0010c0\u0011 סְרִיס חַמָּה \u0005(פֵּרוּשׁ, שֶׁנִּסְתָּרֵס עַל יְדֵי קַדַּחַת, עָרוּךְ)\u0006, וְאַיְלוֹנִית \u0005(פֵּרוּשׁ אַיְלוֹנִית, שֶׁיֵּשׁ לָהּ טֶבַע זָכָר, כְּלוֹמַר שֶׁאֵינָהּ יוֹלֶדֶת, וְאַיְלוֹנִית נִגְזַר מֵאַיִל שֶׁהוּא זְכַר הַצֹאן)\u0006, אֵינָם בְּנֵי חֲלִיצָה וְיִבּוּם. לְפִיכָךְ, אַיְלוֹנִית וַדָּאִית שֶׁחָלְצָה, לֹא נִפְסְלָה לִכְהֻנָּה. וְכֵן סְרִיס חַמָּה שֶׁחָלַץ, אוֹ שֶׁחָלְצוּ לְאִשְׁתּוֹ, אֵינוֹ כְּלוּם. \u0005 הַגָּה: הָיָה סְפֵק סָרִיס, חוֹלֵץ. וְלֹא מַחְזְקִינָן לֵהּ בְּוַדַּאי סָרִיס, אֶלָּא אִם רָאוּ בּוֹ, שֶׁנּוֹלַד, \u0010c1\u0011 אֶחָד מִסִּימָנֵי סָרִיס, כְּגוֹן שֶׁהֵטִיל מַיִם וְלֹא עָשָׂה כִּפָּה; אֲבָל בְּלָאו הָכִי יֵשׁ לָחוּשׁ שֶׁנִּתְקַלְקֵל אַחַר לֵדָתוֹ, וְצָרִיךְ לַחֲלֹץ \u0006 \u0005(רִיבָ\"שׁ סִימָן תע\"ד)\u0006. הָיָה לְאַיְלוֹנִית וַדָּאִית, צָרָה, \u0010c2\u0011 מֻתֶּרֶת לְהִתְיַבֵּם:\nסְפֵק אַיְלוֹנִית, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת.\nסְרִיס אָדָם \u0005 פֵּרוּשׁ, שֶׁנִּסְתָּרֵס וְנֶחְתַּךְ בִּידֵי אָדָם)\u0006, שֶׁהָיָה לוֹ שְׁעַת הַכּשֶׁר, חוֹלְצִין לְאִשְׁתּוֹ אוֹ מְיַבְּמִין, וְהוּא חוֹלֵץ וְאֵינוֹ מְיַבֵּם, מִפְּנֵי שֶׁפָּסוּל לָבֹא בַּקָּהָל. וְאִם עָבַר וּבָא עָלֶיהָ, קָנָה, וּמוֹצִיא בְּגֵט. \u0005 וְאִם הָיָה יְבִמְתּוֹ גִּיֹּרֶת אוֹ שְׁאָר אִשָּׁה הַמֻּתֶּרֶת לִפְצוּעַ דַּכָּא, מֻתָּר לְיַבְּמָהּ \u0006 \u0005(נ\"י פ' הֶעָרֵל)\u0006:\nאֵלּוּ הֵם סִימָנֵי אַיְלוֹנִית: כָּל שֶׁאֵין לָהּ דַּדִּים, וּמִתְקַשָּׁה בִּשְׁעַת תַּשְׁמִישׁ, וְאֵין לָהּ שִׁפּוּלֵי מֵעַיִם כַּנָּשִׁים, וְקוֹלָהּ עָבֶה, וְאֵינָהּ נִכֶּרֶת בֵּין אִישׁ לְאִשָּׁה. \u0005 וְיֵשׁ אוֹמְרִים דִּבְאֶחָד מֵאֵלֶּה נִקְרֵאת אַיְלוֹנִית \u0006 \u0005(טוּר)\u0006:\nאֵלּוּ הֵם \u0010c3\u0011 סִימָנֵי סְרִיס חַמָּה: כָּל שֶׁאֵין לוֹ זָקָן, וּשְׂעָרוֹ לָקוּי, וּבְשָׂרוֹ מַחֲלִיק, וּכְשֶׁמֵּטִיל מַיִם אֵינוֹ עוֹשֶׂה כִּפָּה, וְשִׁכְבַת זַרְעוֹ דֵּיהָא, וְאֵין מֵימֵי רַגְלָיו מַחֲמִיצִין, וְרוֹחֵץ בִּימוֹת הַגְּשָׁמִים וְאֵין בְּשָׂרוֹ מַעֲלֶה הֶבֶל, וְקוֹלוֹ לָקוּי, וְאֵינוֹ נִכָּר בֵּין אִישׁ לְאִשָּׁה. \u0005 הַגָּה: הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת בִּזְקָנוֹ, אֵינוֹ סָרִיס אֶלָּא \u0010c4\u0011 עַד שֶׁיִּהְיוּ לוֹ כָּל הַסִּימָנִים הַלָּלוּ \u0006 \u0005(טוּר)\u0006. \u0005 אֲבָל אִם לֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת בִּזְקָנוֹ, אֲפִלּוּ אֵין בּוֹ \u0010c5\u0011 רַק אֶחָד מֵהַסִּימָנִים הַלָּלוּ, הָוֵי סָרִיס \u0006 \u0005(הַמ\"מ פ\"ה דְּאִשּׁוּת וְכֵן מַשְׁמַע בְּטוּר)\u0006. \u0005 הָיוּ לוֹ שְׁתֵּי שְׂעָרוֹת בִּשְׁאָר הַגּוּף, אֵינוֹ סָרִיס, אַף עַל פִּי שֶׁיֵּשׁ לוֹ כָּל הַסִּימָנִין הַלָּלוּ \u0006 \u0005(טוּר)\u0006: \u0010c6\u0011\nבְּנֵי כַּמָּה שָׁנִים יִהְיוּ לְשֶׁיִּהְיוּ נִדּוֹנִים כְּאַיְלוֹנִית וְסָרִיס עַל פִּי סִימָנִים הַלָּלוּ, נִתְבָּאֲרוּ בְּהָרַמְבַּ\"ם פֶּרֶק שֵׁנִי מֵהִלְכוֹת אִשּׁוּת, וּבְסִימָן קנ\"ה. \u0005 הַגָּה: סָעִיף י\"ג לְעִנְיַן אַיְלוֹנִית, וְהוּא הַדִּין לְסָרִיס. וְיֵשׁ אוֹמְרִים דְּאֵין לָדוּן עַכְשָׁו דִּין סְרִיס וַדַּאי, דְּחַיְשִׁינָן שֶׁמָּא הָיָה לוֹ שְׂעָרוֹת וְנָשְׁרוּ, אוֹ שֶׁהָיוּ לוֹ גֻּמּוֹת, וְאֵין אָנוּ בְּקִיאִין \u0006 \u0005(עַיֵּן בָּרִיבָ\"שׁ סִימָן תע\"ד)\u0006, \u0005 כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קנ\"ה לְעִנְיַן מֵאוּן. לָכֵן דַּיְנִינָן לֵהּ בִּסְפֵק סָרִיס, וְחוֹלֵץ, \u0010c7\u0011 וְכֵן רָאוּי לְהוֹרוֹת: \u0010c8\u0011 \u0006\nמִי שֶׁחָתְכוּ אוֹ נִתְּקוּ אוֹ מֵעֲכוּ גִּידָיו אוֹ בֵּיצָיו, בִּידֵי אָדָם, נִקְרָא סְרִיס אָדָם; וּכְשֶׁיִּהְיֶה בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד, נִקְרָא גָּדוֹל, שֶׁאֵין זֶה מֵבִיא סִימָנִים לָעוֹלָם:\nאַנְדְּרוֹגֵינוֹס, אֵינוֹ בַּר חֲלִיצָה וְיִבּוּם. \u0010c9\u0011 וְיֵשׁ אוֹמְרִים שֶׁדִּינוֹ כְּזָכָר לְכָל דָּבָר:\nטֻמְטוּם, חוֹלֵץ וְלֹא מְיַבֵּם, מִפְּנֵי שֶׁהוּא סָפֵק. וְאִם נִקְרַע, וְנִמְצָא זָכָר, רָצָה חוֹלֵץ, רָצָה \u0010c10\u0011 מְיַבֵּם. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁהוּא סָפֵק, \u0010c11\u0011 וּלְחֻמְרָא:\nהַזָּקֵן בְּיוֹתֵר, שֶׁתָּשׁ כֹּחוֹ וְכָשַׁל, דִּינוֹ כִּסְרִיס אָדָם לְעִנְיַן חֲלִיצָה וְיִבּוּם, אֶלָּא שֶׁאִם בָּא עַל יְבִמְתּוֹ מֻתָּר לְקַיְּמָהּ:\nהַחֵרֶשֶׁת וְהַשּׁוֹטָה וְהַקְּטַנָּה, מִתְיַבְּמוֹת וְלֹא חוֹלְצוֹת. וְאִם רָצָה הַיָּבָם \u0010c12\u0011 לְגָרֵשׁ הַחֵרֶשֶׁת בְּגֵט אַחַר שֶׁיִּבְעֹל אוֹתָהּ, הֲרֵי זֶה מְגָרֵשׁ:\nחֵרֵשׁ שׁוֹטֶה וְקָטָן, אֵינָם בְּנֵי חֲלִיצָה, אֲבָל \u0010c13\u0011 מְיַבְּמִין. וְהַחֵרֵשׁ, אִם נָפְלָה לוֹ מֵאָחִיו פִּקֵּחַ, אֵינוֹ יָכוֹל לְהוֹצִיא לְעוֹלָם. אֲבָל אִם נָפְלָה לוֹ מֵאָחִיו חֵרֵשׁ, יָכוֹל לְהוֹצִיא בְּגֵט אַחַר שֶׁיִּבְעֹל. וְהַקָּטָן, יוֹצִיא בְּגֵט, אִם בָּא עָלֶיהָ לְאַחַר שֶׁהִגְדִּיל; וְאִם לָאו, צְרִיכָה גֵּט לְמַאֲמָרוֹ וַחֲלִיצָה לְזִיקָתוֹ:\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, נְשׂוּאִים לִשְׁתֵּי נָשִׁים פִּקְחוֹת, מֵת חֵרֵשׁ בַּעַל הַפִּקַּחַת, אָחִיו הַפִּקֵּחַ רָצָה חוֹלֵץ רָצָה מְיַבֵּם. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו הַחֵרֵשׁ אֵינוֹ יָכוֹל לַחֲלֹץ, וְכוֹנֵס, וְאֵינוֹ מוֹצִיא לְעוֹלָם:\nשְׁתֵּי אַחִים פִּקְחִים נְשׂוּאִים שְׁתֵּי נָשִׁים, אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, מֵת פִּקֵּחַ בַּעַל הַחֵרֶשֶׁת, אֵין הַחֵרֶשֶׁת בַּת חֲלִיצָה, אֶלָּא כּוֹנֵס, וְאִם רָצָה אַחַר כָּךְ לְהוֹצִיא בְּגֵט, יוֹצִיא. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו, רָצָה חוֹלֵץ, רָצָה מְיַבֵּם:\nשְׁנֵי אַחִים, אֶחָד חֵרֵשׁ וְאֶחָד פִּקֵּחַ, נְשׂוּאִים לִשְׁתֵּי נָשִׁים, אַחַת חֵרֶשֶׁת וְאַחַת פִּקַּחַת, פִּקֵּחַ לְפִקַּחַת, וְחֵרֵשׁ לְחֵרֶשֶׁת, מֵת חֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אָחִיו הַפִּקֵּחַ כּוֹנֵס, וְאִם רָצָה אַחַר כָּךְ, יוֹצִיא בְּגֵט. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, אָחִיו הַחֵרֵשׁ כּוֹנֵס, וְאֵינוֹ מוֹצִיא לְעוֹלָם. הַסוּמָא, מְיַבֵּם, \u0005 הַגָּה: וְאֵינוֹ חוֹלֵץ; וְאִם חָלַץ, חֲלִיצָתוֹ כְּשֵׁרָה \u0006 \u0005(טוּר)\u0006. \u0005 וְנִרְאֶה לִי, שֶׁאִם אֵין כָּאן אָח, אֶלָּא הוּא, חוֹלֵץ לְכַתְּחִלָּה, מֵאַחַר שֶׁאִי אֶפְשָׁר בְּעִנְיָן אַחֵר. וְע\"ל סִימָן קמ\"ט בְּפֵרוּשׁ הַחֲלִיצָה סָעִיף ס\"ד: \u0006\nאֵשֶׁת קָטָן וְאֵשֶׁת הַשּׁוֹטֶה, פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. אֲבָל אֵשֶׁת הַחֵרֵשׁ, וְהַזְּקֵנָה, וְהָעֲקָרָה, הֲרֵי הֵם כִּשְׁאָר כָּל הַנָּשִׁים, וְחוֹלֶצֶת אוֹ מִתְיַבֶּמֶת:",[],["\u0003סריס חמה ואיילונית\u0004. התורה מיעטו מחליצה ויבום ה\"ה אף אם בא על יבמתו אינו פוטר משאר אחים דאינו עולה ליבום אצלו גם א\"צ גט ממנו דאסורה עליו בכרת אשת אח שלא במקום מצוה משא\"כ סריס אדם שהיה לו שעת הכושר וראוי ליבום וחליצה אלא הוא מחייבי לאוין שהוא פצוע דכא מ\"ה אם בא עליה קנאה כמ\"ש בסוגיא דף כ':","\u0003א' מסימני סריס\u0004. משמע אפילו שאר סימן הניכר בקטנותו כגון שאין מימי רגליו מחמיצין סמכינן נמי שהוא סריס ממעי אמו, ומה שאמר אביי שאין עושה כיפה לאו דוקא ויתבאר בסמוך:","\u0003ספק איילונית\u0004. היינו הסימן איילוני' שיש בה אין היכר יפה כמ\"ש בב\"י סי' מ\"ד וכתב ב\"ח ספק איילונית אפילו לא הכיר בה בעלה שהיא ספק איילונית מ\"מ צריכ' חליצה:","\u0003סימני סריס\u0004. בזה לכ\"ע באחד מסימנים נקרא סריס אלא אם יש לו שתי שערות בזקנו כמו שכתוב בהג\"ה:","\u0003עד שיהיו לו כל הסימנים\u0004. וא\"ל איך אפש' שיהא לו סימנים דהא יש לו זקן תרצו התוס' דלא נקרא זקן אא\"כ נתמלא זקנו וכן הסכימו כל הפוסקים לא כראב\"ד דס\"ל כשיש לו ב' שערות בזקן תו לא נקרא סריס והנה כוונת תוספות מ\"ש יש לו זקן היינו נתמלא זקנו כלומר אם נתמלא זקנו תו א\"א לומר שיהא לו כל הסימני סריס אם כן לאו סריס הוא, אבל י\"ל מ\"מ אין לו דין גדול אלא קטן הוא עד רוב שנותיו לכן אין מובן לי מ\"ש הב\"י ר\"ס קס\"ט במה שכתב הטור שם אם נתמלא זקנו א\"צ לבדוק יותר כתב שלמד מתוס' הנ\"ל ובאמת מתוס' הנ\"ל לא משמע כלום אלא כוונתם ב' שערות בזקן לא נקרא יש לו זקן ושייך לומר שיהא לו כל סימני סריס:","\u0003רק א' מסימנים הללו\u0004. כלומר אם אין ב' שערות בכל הגוף ובזקן ויש לו עוד סימן א' מהני סימנים מחזיקין אותו לסריס כן הוא דעת הרמב\"ם וכן הוא בטור מיהו תוס' וראב\"ד ס\"ל בזה סימן לבד שאין לו ב' שערות כלל מחזיקין לסריס וא\"צ שום סימן אחר, ומה שכתב הריב\"ש בתשו' סי' תע\"ד דהרא\"ש מפרש גם כן כהראב\"ד א\"י מנ\"ל ואפשר ט\"ס שם, ולכאורה קשה איך אפשר בסי' זה לבד מחזיקין לסריס איך קאמר ר' יוחנן אפ' באחד מהם היינו שאין ב' שערות דהא ע\"כ צריך להיות שאין עושה כיפה כי בזה ניכר שלא נתרפא בינו לבינו וכה\"ג הקשה שם אליבא דמ\"ד עד שיהיו כולם ותירצו כיון שניכר מיד שאינו עושה כיפה ושאר סימנים ניכרים כ\"א בזמנו הוכיח הראשון על האחרים שממעי אמו הוא לקוי א\"כ אליבא דר' יוחנן קשה קושיא זו ואם תאמר דאיירי בילדותו לא היה עושה כיפה ואחר כן עושה כיפה משנתגדל אלא שאין לו ב' שערות א\"כ נעשה שינוי אצלו ואכתי יש לחוש שמא הבריא בנתיים כקושיית הש\"ס וצ\"ל דס\"ל אף בכה\"ג לא חיישינן שמא הבריא מאחר דנולד בו סי' אחר והוי לקוי בתחלה וסוף, שוב מצאתי קושיא זו בחדושי הלכות ע\"ש ותירץ דר\"י לא איירי לענין סריס חמה אלא הסימן מהני שהוא סריס:","\u0003בני כמה שנים\u0004. עיין תשובת ריב\"ש סימן שפ\"ד והובא בב\"י ומדבריו נלמד הכלל אף על פי שיש לו סימני סריס קודם עשרים שנה אמרינן עדיין קטן הוא עד שהוא בן עשרים ואז הוא סריס, ואם הוא בן כ' ולא הביא סימני סריס ויש לו ב' שערות לא דיינינן ליה כסריס אף על פי שנולדו בו סימני סריס אחר כך כיון שהביא שתי שערות קודם סימני סריס כן הוא הגירסא בריב\"ש ובב\"י איתא טעות, וכן הביא בב\"ח הגירסא, ואם קדמו סימני סריס אפילו אח\"כ הביא ב' שערות מחזיקין לסריס ואם אין לו ס\"ס ולא שתי שערות הרי הוא קטן עד רוב שנותיו ואז הרי הוא סריס אפילו אין לו ס\"ס, ואם קודם רוב שנותיו הביא ב' שערות ואחר כך ס\"ס הרי הוא גדול מיום הבאת ב' שערות, ואם הביא ס\"ס ואחר כך ב' שערות הרי הוא סריס ועיין ב\"ח:","\u0003וכן ראוי להורות\u0004. וצ\"ל אפילו הטיל מים ואינו עושה כיפה מיום שנולד מ\"מ חיישינן שמא נשרו אף על גב שנולד בו ס\"ס קודם מ\"מ אם הביא ב' שערות קודם עשרים הוא גדול, ומ\"ש בסעיף א' דצריך לחלוץ היכא דלא בדקו אם עושה כיפה היינו אפילו לבקיאין מיהו משמע ב' שערות בזקן דוקא שערות ולא גומות:","\u0003מי שחתכו וכו'\u0004. היינו שחתכו קודם שנבדקו אם עושה כיפה אבל בוודאי אם לא עשה כיפה לא יצא מידי ספיקא:","\u0003וי\"א שדינו כזכר\u0004. כ\"כ הטור בשם התוס' והרא\"ש ובספרו ב\"י השיג ע\"ז דלא כתבו לענין חליצה ויבום מאחר שאין מוליד אם כן דינו כסריס חמה דהא לא היה לו מעולם שעת הכושר וכן השיג מהרש\"ל ועיין דרישה וב\"ח, ורי\"ו כתב בשם הרמ\"ה אנדרוגינוס חולץ וחולצין לאשתו ואם כנס כהן אין מוציאין דספק חליצה לא גזרו רבנן גם עליו קשה מברייתא שהביאו הרי\"ף והרא\"ש אשת אנדרוגינוס פטורה מחליצה, מיהו גם הנ\"י פירש במשניות דתני אנדרוגינוס נושא היינו שאשתו צריכה חליצה, לפ\"ז לפסק תוס' דקי\"ל כמתניתין דזכר הוא א\"כ צריכה חליצה ולא כברייתא הנ\"ל, ולדינא נראה דחולץ וחולצין כמ\"ש הרמ\"ה:","\u0003ויש מי שאומר\u0004. היינו הרא\"ש פוסק כר' יוסי דאמר שמא נקרע וימצא סריס חמה היינו אף אם יהיה זכר ספק לנו שמא סריס הוא אפי' בלא סימני סריס ועיין בכורות דף מ\"ב:","\u0003הזקן ביותר וכולי\u0004. מדאוריית' ראוי לייבם שהרי כמה זקינים מולידי' אלא מדרבנן אסור לכתחלה לייבם אף על גב זקנה מותרת לייבם לכתחלה כמ\"ש בס\"ס משום זקנה יותר ראוי לביאה מזקן ועיין בד\"מ:","\u0003לגרש החרשת\u0004. בטור כתב סתם לגרש והיינו קטנה ואביה חי אז יצאת בגט כשאביה מקבל הגט כמו שכתב בסי' קמ\"א, ושוטה היינו דיכולה לשמור את גיטה אז מגורשת מדאורייתא גם אם יכולה לשמור את עצמה ומ\"מ היא שוטה אז מגורשת אבל מעשי' שהוא חלצה לאו מעשה הוא:","\u0003והחרש אם נפלה לו וכו'\u0004. הנה ברמב\"ם פ\"ו לא חילק בזה אלא סתם דבריו שבעילתו עושה אותה א\"א גמורה וב\"י וכ\"מ כתבו דע\"כ הרמב\"ם איירי כשנפלה מאחיו פקח כמה שמחלק בפ\"ב מה\"ג, והנה לירושלמי שכתב דחרש א\"י להוציא בגט אלא בקידשה ולא בעיל כמ\"ש בב\"י סימן קכ\"א, לפ\"ז מיושב שפיר דברי הרמב\"ם ומיהו הנ\"י כתב דלא מצינו שום פוסק שס\"ל חילוק של הירושלמי גם לשון הרמב\"ם היה דחוק אם ס\"ל כירושלמי:"]],["הַיְבָמָה שֶׁהִיא עֶרְוָה לַיָּבָם בְּאִסוּר כָּרֵת, \u0010c0\u0011 חוּץ מִן הַנִּדָּה, אֵינָהּ זְקוּקָה לַיָּבָם, וּמֻתֶּרֶת לְזָר בְּלֹא חֲלִיצָה, וְכֵן צָרוֹתֶיהָ פְּטוּרוֹת מִן הַחֲלִיצָה וּמֵהַיִּבּוּם. וְאִם הָיָה לוֹ אָח אַחֵר, וְאַחַת מִצָּרוֹתֶיהָ נִתְיַבְּמָה לְאוֹתוֹ אָח, וְלוֹ נָשִׁים אֲחֵרוֹת, וּמֵת, כֻּלָּן פְּטוּרוֹת מֵחֲלִיצָה וּמִן הַיִּבּוּם. וְאִם הָיָה לוֹ עוֹד אָח אַחֵר, וְאַחַת מֵהַנָּשִׁים אֵלּוּ נִתְיַבְּמָה לוֹ, וְלוֹ נָשִׁים אֲחֵרוֹת, וּמֵת, כֻּלָּן פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִבּוּם. וְכֵן עַד עוֹלָם:\nאֲבָל אִם אַחַת מִכָּל הָעֲרָיוֹת נְשׂוּאָה לְזָר שֶׁאֵינוֹ אָחִיו, וּמֵת, מֻתָּר לִשָּׂא צָרָתָהּ: \u0010c1\u0011\nיְבָמָה שֶׁהִיא סְפֵק עֶרְוָה עַל בַּעְלָהּ, אוֹ סְפֵק עֶרְוָה עַל הַיָּבָם, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. לְפִיכָךְ, מִי שֶׁקִּדֵּשׁ אִשָּׁה בִּסְפֵק קִדּוּשִׁין, וְאַחַר כָּךְ מֵת אָחִיו שֶׁהָיָה נוֹשֵׂא אֲחוֹתָהּ, וְנָפְלָה לוֹ לְיִבּוּם, שֶׁהִיא סְפֵק אֲחוֹת אִשְׁתּוֹ, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וּמוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט מִסָפֵק, וּשְׁתֵּיהֶן אֲסוּרוֹת עָלָיו; יְבִמְתּוֹ, מִפְּנֵי שֶׁהִיא סְפֵק עֶרְוָה; וַאֲרוּסָתוֹ, מִפְּנֵי \u0010c2\u0011 שֶׁהִיא סְפֵק קְרוֹבַת חֲלוּצָתוֹ:\nהָיְתָה הַיְבָמָה בְּאִסוּר עֶרְוָה עַל הַבַּעַל, אֵינָהּ אִשְׁתּוֹ. וְאִם הָיָה לָהּ צָרָה, חוֹלֶצֶת \u0010c3\u0011 אוֹ מִתְיַבֶּמֶת. וְזוֹ שֶׁהָיְתָה לַבַּעַל בְּאִסוּר עֶרְוָה, הִיא לַיָּבָם כְּמוֹ אִשָּׁה דְּעָלְמָא, וּמֻתָּר בָּהּ:\nהָיְתָה הַיְבָמָה סְפֵק עֶרְוָה עַל הַבַּעַל, אוֹ חוֹלֶצֶת אוֹ \u0010c4\u0011 מִתְיַבֶּמֶת:\nיְבָמָה שֶׁהִיא סְפֵק עֶרְוָה לַיָּבָם, וְהָיָה לְאָחִיו בָּהּ סְפֵק קִדּוּשִׁין אוֹ סְפֵק גֵּרוּשִׁין, וְלוֹ אִשָּׁה אַחֶרֶת, אוֹתָהּ הַצָּרָה חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nהָיָה אָחִיו נָשׂוּי אִשָּׁה שֶׁהִיא עֶרְוָה לַיָּבָם, וְלוֹ עוֹד אִשָּׁה אַחֶרֶת, וְאַחַר כָּךְ מֵתָה הָעֶרְוָה בְּחַיֵּי בַּעְלָהּ, אוֹ \u0010c5\u0011 גֵּרְשָׁהּ, אוֹ שֶׁהָיְתָה קְטַנָּה \u0010c6\u0011 וּמֵאֲנָה בּוֹ, וְאַחַר כָּךְ מֵת, מֻתֶּרֶת צָרָתָהּ לְהִתְיַבֵּם. אֲבָל אִם לֹא מֵאֲנָה בּוֹ בְּחַיָּיו, וּמֵאֲנָה בּוֹ אַחַר מוֹתוֹ, צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nסָפֵק אִם אוֹתָהּ שֶׁהִיא עֶרְוָה לַיָּבָם מֵתָה בְּחַיֵּי הַבַּעַל אוֹ אַחַר מוֹתוֹ, צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nיְבָמָה שֶׁהִיא עֶרְוָה לַיָּבָם וְהִיא \u0010c7\u0011 אַיְלוֹנִית, אֲפִלּוּ הִכִּיר בָּהּ בַּעְלָהּ, הֲרֵי הִיא כְּמִי שֶׁאֵינָהּ, וְצָרָתָהּ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. וְאִם יִבֵּם הַצָּרָה מִפְּנֵי שֶׁהָיָה סָבוּר שֶׁהָעֶרְוָה אַיְלוֹנִית, וְאַחַר כָּךְ נִמְצֵאת שֶׁאֵינָהּ אַיְלוֹנִית, תֵּצֵא מִיבָמָהּ \u0010c8\u0011 בְּלֹא גֵּט, וְהַוָּלָד מַמְזֵר:\nנִשֵּׂאת הַצָּרָה לְזָר, מִפְּנֵי שֶׁהָיְתָה סְבוּרָה שֶׁאֵין הָעֶרְוָה אַיְלוֹנִית, וְאַחַר כָּךְ נִמְצֵאת אַיְלוֹנִית, תֵּצֵא מֵהַבַּעַל בְּגֵט, וּבַחֲלִיצָה מֵהַיָּבָם לְהַתִּירָהּ. וְאִם מִתְּחִלָּה לֹא נִשֵּׂאת לְזָר, אֶלָּא נִתְקַדְּשָׁה לוֹ בִּלְבַד, מֻתֶּרֶת לַיָּבָם:\nמִי שֶׁזִּנְּתָה אִשְׁתּוֹ תַּחְתָּיו בְּעֵדִים וּבְרָצוֹן, וּמֵת בְּלֹא זֶרַע, וְנָפְלָה לִפְנֵי אָחִיו, \u0010c9\u0011 דִּינָהּ כְּדִין עֶרְוָה, וְהִיא וְצָרָתָהּ פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִּבּוּם, אֲבָל אִם \u0010c10\u0011 סָפֵק זִנְּתָה אִם לָאו, הִיא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ, אוֹ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת. \u0005 הַגָּה: וְיֵשׁ אוֹמְרִים דַּאֲפִלּו זִנְּתָה וַדַּאי, צְרִיכָה חֲלִיצָה \u0006 \u0005(הַשָּׂגוֹת הָרַאֲבַ\"ד)\u0006, \u0005 וְהוּא הַדִּין לְצָרָתָהּ, \u0010c11\u0011 \u0006 \u0005 וְיֵשׁ לְהַחֲמִיר. וְלָכֵן, מִי שֶׁיֵּשׁ לוֹ אִשָּׁה שֶׁהֵמִירָה, אַף עַל גַּב דְּוַדַּאי זִנְּתָה, צָרָתָהּ צְרִיכָה חֲלִיצָה \u0006 \u0005(מָרְדְּכַי רֵישׁ יְבָמוֹת וְכ\"כ מהרא\"י סִימָן רי\"ט)\u0006. \u0010c12\u0011 \u0005 אִשָּׁה שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם, וְנִשֵּׂאת, וְאַחַר כָּךְ בָּא הַבַּעַל וּמֵת, צָרָתָהּ מֻתֶּרֶת לְהִתְיַבֵּם, וְאֵינָהּ כְּצָרַת סוֹטָה \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פֶּרֶק הָאִשָּׁה)\u0006: \u0010c13\u0011\nאֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ, הֲרֵי הִיא אֵשֶׁת אָח שֶׁלֹּא בִּמְקוֹם מִצְוָה, וּפוֹטֶרֶת צָרָתָהּ. כֵּיצַד, רְאוּבֵן שֶׁמֵּת, וְנָפְלָה אִשְׁתּוֹ לִפְנֵי שִׁמְעוֹן אָחִיו, וְאַחַר כָּךְ נוֹלַד לֵוִי אָחִיו, בֵּין שֶׁנּוֹלַד קֹדֶם שֶׁיִּבֵּם שִׁמְעוֹן אֵשֶׁת רְאוּבֵן, בֵּין שֶׁנּוֹלַד אַחַר שֶׁיִּבְּמָה, וּמֵת שִׁמְעוֹן, אֲסוּרָה עַל לֵוִי לְעוֹלָם. וְאִם הָיָה לְשִׁמְעוֹן אִשָּׁה אַחֶרֶת, גַּם הִיא פְּטוּרָה מֵחֲלִיצָה וּמֵהַיִּבּוּם, וּפוֹטֶרֶת צָרָתָהּ וְצָרַת צָרָתָהּ עַד סוֹף הָעוֹלָם, כְּדִין צָרַת עֶרְוָה. וְאִם מֵת שִׁמְעוֹן, אֲפִלּוּ קֹדֶם שֶׁעָשָׂה בָּהּ מַאֲמָר, אֵשֶׁת שִׁמְעוֹן חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, מִשּׁוּם דְּכֵיוָן דְּקַיְמָא לָן יֵשׁ זִקָּה, אֲפִלּוּ לֹא עָשָׂה מַאֲמָר \u0010c14\u0011 הֲוָה לֵהּ כְּצָרַת אֵשֶׁת אָחִיו שֶׁלֹּא הָיָה בְּעוֹלָמוֹ:\nקְטַנָּה \u0010c15\u0011 שֶׁהָיְתָה נְשׂוּאָה לְאָחִיו מֵאִמּוֹ [לַאֲחִי אִמּוֹ] שֶׁהִיא שְׁנִיָּה לוֹ, וּמֵת, וְנִשְׁאַר וּנְשָׂאָה אָחִיו מֵאָבִיו, וּמֵת, וְנָפְלָה לְפָנָיו לְיִבּוּם וְעוֹדֶנָּה קְטַנָּה, אֵין אוֹמְרִים תְּמָאֵן, לַעֲקֹר נִשּׂוּאִין הָרִאשׁוֹנִים, כְּדֵי שֶׁתִּתְיַבֵּם, אֶלָּא צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, שֶׁאַף הִיא חוֹלֶצֶת אִם תְּמָאֵן:\nקְטַנָּה שֶׁאֵינָהּ עֶרְוָה עָלָיו, וּמֵת, וּמֵאֲנָה הַקְּטַנָּה בַּיָּבָם, \u0010c16\u0011 אֲסוּרָה לוֹ וּמֻתֶּרֶת לְזָר בְּלֹא חֲלִיצָה, \u0010c17\u0011 אִם אֵין שָׁם אַחִים אֲחֵרִים. וְדַוְקָא הִיא, \u0010c18\u0011 אֲבָל צָרָתָהּ מֻתֶּרֶת לוֹ, וַאֲפִלּוּ הִיא מֻתֶּרֶת לִשְׁאָר אַחִים שֶׁלֹּא מֵאֲנָה בָּהֶם:\nהָיוּ לְאָחִיו בְּאִשְׁתּוֹ סְפֵק גֵּרוּשִׁין, וְנָפְלָה לְפָנָיו \u0010c19\u0011 לְיִבּוּם, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. אֲבָל אִם הָיָה לְאָחִיו סְפֵק קִדּוּשִׁין, הֲרֵי זוֹ יְכוֹלָה \u0010c20\u0011 לְהִתְיַבֵּם:\nהַמְגָרֵשׁ אִשְׁתּוֹ גְּדוֹלָה, אוֹ קְטַנָּה שֶׁהִשִּׂיאוּהָ אָחֶיהָ, וְהֶחֱזִירָהּ, וּמֵת, וְנָפְלָה לִפְנֵי יָבָם, מֻתֶּרֶת לוֹ. אֲבָל קְטַנָּה שֶׁהִשִּׂיאָה אָבִיהָ, וְנִתְגָּרְשָׁה בְּקַטְנוּתָהּ עַל יְדֵי אָבִיהָ, וְהֶחֱזִירָהּ וָמֵת בְּעוֹדָהּ קְטַנָּה, \u0010c21\u0011 אֲסוּרָה לְיָבָם. וְכֵן הַדִּין בִּמְגָרֵשׁ הַפִּקַּחַת, וְנִתְחָרְשָׁה, וְהֶחֱזִירָהּ, וּמֵת, וְהִיא חֵרֶשֶׁת; וּבֵין בָּזוֹ וּבֵין בָּזוֹ, \u0010c22\u0011 צָרָתָהּ מֻתֶּרֶת לְהִתְיַבֵּם:\nהֶחֱזִירָהּ כְּשֶׁהִיא קְטַנָּה אוֹ חֵרֶשֶׁת, וְגָדְלָה וְנִתְפַּקְּחָה אֶצְלוֹ, וּמֵת, מֻתֶּרֶת לְהִתְיַבֵּם. וְאֵין צָרִיךְ לוֹמַר אִם הֶחֱזִירָהּ אַחַר שֶׁגָּדְלָה אוֹ נִתְפַּקְּחָה:",[],["\u0003חוץ מן הנדה\u0004. הטעם מבואר בתוס' והרא\"ש ריש יבמות דלא דמי לעריות שאסורה ליבם מחמת קורבה ומותרת לאחר משא\"כ נדה שאסורה לכל גם עומדת לטבילה:","\u0003יבמה שהיא ספק ערוה על בעלה או ספק ערוה וכו'\u0004. כצ\"ל וכן הוא ברמב\"ם והטור תמה ע\"ז למה היא אסורה לייבם דהא ממ\"נ מותרת דאם היא ערוה לבעל הוי כאלו אינה אשתו ומותרת ליבם ואם היא אינה ערוה לבעל א\"כ היא זקוק' ליבם ובכ\"מ כתב דיש למחוק האלף של או וצ\"ל וספק ערוה על היבם היינו שהיה ספק ערוה על היבם ועל הבעל לכן אסורה ליבם ומ\"מ אין מיושב שפיר דאכתי קשה ל\"ל דהיא לשניהם ספק ערוה ת\"ל דאם היא ליבם לבד ספק ערו' נמי אסורה לייבם ובמ' כתב ומפרש דברי הרמב\"ם דקאי על הצרה, ואנ\"ל דהא לא אדכר כלום צרה, ולכאורה נ\"ל דאיירי ג\"כ דאסורה לבעלה מספק כמו הספק דאסורה ליבם ובשני בבות אסורה ליבם מספק או מחמת קידושין שלו או מחמת קידושי אחיו היינו שבעלה קידש אחת מספק קדושין ואח\"כ נשא אחותה א\"כ היא ספק ערוה לבעלה ואסורה ליבם דשמא קידושין של אחותה קידושין מעלייתא הם א\"כ אחותה זקוקה לו והיא אחות זקוקתו:","\u0003שהיא ספק קרובת חלוצתו\u0004. אף על גב אחות חליצתו מדברי סופרים א\"כ הוי ספק דרבנן אפ\"ה קנסו רבנן וגזרו באחות חליצה אטו אחות גרושה דאורייתא לפיכך אלמוה לגזרותם להוציא אפי' על הספק אפילו בדיעבד כ\"כ הנ\"י פ\"ב במתני' מי שקידש ולא כב\"ח שכתב לכתחילה אסור מיהו אם קדם וכנס אין מוצאין אלא אף בדיעבד אם כנס מוציאין ממנו ותימא על הב\"ח שהביא בסי' קט\"ו דברי הנ\"י וכאן אשתמט' מיניה:","\u0003או מתייבמת\u0004. מאחר שהיא ערוה לבעל ואין קידושין תופסין בה א\"כ לא הוי צרה שלה צרתה ואין חילוק בין עריות אפילו נשא אחיו את אחותו שהיא ג\"כ אחות היבם מ\"מ הצרה מותרת ליבם והגירסא במיימ' ישנים באחותו שחולץ לצרה ואסורה ליבם ט\"ס הוא כאשר הגיה הכ\"מ ובחנם טרח ב\"ח וכתב מה שכתב ואישתמטא מיניה דברי הכ\"מ:","\u0003יבמה שהיא ספק ערוה ליבם וכו'\u0004. כצ\"ל היינו שקידש אחיו ספק קידושין לבת אחיו אף על גב שצרתה עומדת בחזקת היתר ליבם מ\"מ מחמת קידושי ספק של זו אסורה ליבם וצריכה חליצה וכן אם כבר היה נשואה לו בת אחיו וצרה א\"כ הצרה בחזקת היתר לשוק עומדת מ\"מ מחמת גירושי ספק של בת אחיו אסורה זו לשוק בלא חליצה, וספק קידושין או גירושין היינו בזרק לה קידושין או גירושין וספק קרוב לו או לה הוי ספק דאורייתא ואם ב' עדים אומרים קרוב לה וב' עדים אומרים קרוב לו אז הוי ספיקא דרבנן כי מדאורייתא אוקמא תרי בהדי תרי ואוקמה אחזק' א\"כ בקידושין מותרת ליבם מדאורייתא, וכן בגירושין מותרת לשוק מדאורייתא ועיין בתוספות פד\"א, וכן אם ע\"א אמר קרוב לה וע\"א אמר קרוב לו הוי ספיקא דרבנן ועיין סימן קל\"ט שם מבואר דקי\"ל אפי' קרוב לה הוי ספיקא דדינא אם מגורשת מחמת קרוב לה וכן גט שאין בו זמן או כתב הבעל בכת\"י ואין עליו עדים וכן בכת' בכת\"י וחתום ע\"א הוי נמי בכלל ספק גירושין והיינו מדאורייתא מגורשת אלא מדרבנן פסול הגט, ובקידושין אין פסול כלל כשאין בו זמן וכן בכת\"י ואין עליו עדים כתב הרא\"ש דפסול הוא משום זמן שמא יקדים הזמן ובקדושין כשר:","\u0003או שהיתה קטנה\u0004. אף שאביה חי אשכחן מיאון כגון שאביה השיא אותה ונתגרשה כשהיתה קטנה שוב אין לאביה רשות בה והלכה ונשאת ש\"ס:","\u0003ומיאנה בו\u0004. וכן אם לא מיאנה הואיל והיא קטנה וקידושי' מדרבנן לכן צרתה חולצת ואסורה ליבם, מתני' ריש יבמות אלא קמ\"ל אפי' מיאנה מ\"מ צרתה אסור' ליבם הואיל ונראה בשעת נפילה כצרת בתו:","\u0003אפי' הכיר בה\u0004. דכי אסר רחמנא צרת ערוה במקום מצוה הוא דאסרה וכיון דאיילונית היא דבלאו ערוה נמי לא חזי ליבום הוי צרתה צרת ערוה שלא במקום מצוה רש\"י פ\"ק דיבמות ולענין אשת אחיו שהיא איילונית ולא הכיר בה ואין ערוה על היבם אם היא מותרת ליבם נראה דתליא בפלוגתא המבואר בסימן מ\"ד להני פוסקים דס\"ל כשלא הכיר בה א\"צ גט אז מותרת לו דהוי כאלו אינה אשת אחיו, אבל להפוסקים דס\"ל דצריכה גט מדרבנן א\"כ אסורה לו דהוי כאשת אח שלא במקום מצוה:","\u0003בלא גט\u0004. מאחר דהיא אשת אח שלא במקום מצוה והיא מחייבי כריתות אין קידושין תופסין בה אף על גב בחלץ לאחת תופסין קדושין בשניה ולא אמרינן דהיא מחייבי כריתות דשם כתיב אשר לא יבנה ניתק מכרת ללאו תוס' פ\"ק דיבמות והגירסא ברמב\"ם תצא בגט ט\"ס ועיין בהגהו' דריש' שדחק את עצמו ליישב קושיא זאת למה בחלץ לאחת מהן קידושין תופסין בשניה:","\u0003דינה כדין ערוה\u0004. מ\"ט טומאה כתיב בה ונסתרה והיא נטמאה ובעריות כתיב אל תטמאו בכל אלה מ\"ה דינה כערוה וצרתה היא צרת ערוה ופטורה מן החליצה ויבום ובנ\"י הניח בצ\"ע אשת כהן שנאנסה אם צריכה חליצה, ולכאורה תמוה הא איתא בש\"ס להדיא פ' הע\"י דף נ\"ה אשת כהן שנאנסה בעלה לוקה עליה משום טומאה דכתיב אחרי אשר הוטמא' היינו שנבעלה ובאשת כהן הוי אונס כרצון נשמע אף באונס טומאה כתיב בה א\"כ היא וצרתה פטורים מן החליצה כמו זנות ברצון וצל\"ע, שוב ראיתי גם ב\"ח הרגיש בזה, ואפשר דס\"ל דוקא לחומרא הוי אונס בכהן כרצון בישראל ולא לקולא כמ\"ש בתוס' ולענין ספק זינתה עיין ר\"ס י\"א מבואר אפי' אם נאסרה בקינוי וסתיר' מ\"מ קידושין של הנחשד תופסין בה וכן אפי' אם זינתה ברצון בעדים תופסין קידושי הבועל:","\u0003ספק זינתה\u0004. עיין בתו' סוטה דף ה' כתבו ספק סוטה לא אימעיט אלא גבי איסורא דבעל וקמ\"ל קרא כיון דבא מכח נשואי אחיו הרי הוא במקום בעל דאסורה לו ליבם אבל חליצה בעי ש\"מ דאינה אסורה ליבם אלא היכא דאסורה לבעלה:","\u0003ויש להחמיר\u0004. עיין ב\"ח שכתב או היא או צרת' צריכ' חליצה ולא שייך למימר חליצה פסולה כאן כמ\"ש בתוס' דף י\"א בד\"ה או היא ע\"כ, ודבריו תמוהים ע\"כ לא כתבו תוס' שם אלא באיסור דלא קלשה הזיקה אבל בסוטה קלשה הזיקה פשיטא שייך לומר חליצ' פסולה וכ\"כ תוס' להדיא ר\"פ ד\"א ע\"ש לכן נראה בחליצת הסוטה לא נפטר' הצרה:","\u0003אשה שהלך בעלה וכו'\u0004. בד\"מ כ\"כ בשם ש\"ג וא\"י מה חידש בזה הא ש\"ס ערוכה היא פ\"ק דף י\"א אמינא אנא סוטה דאורייתא ואת אמרת לי סוטה דרבנן ע\"ש בפרש\"י ואפש' דקמ\"ל שמותרת לכתחלה ליבם ובש\"ס ה\"א בדיעבד קאמר וע\"ש בתוס' ד\"ה ר\"ש אומר:","\u0003אשת אחיו שלא היה בעולמו\u0004. דכתיב כי ישבו אחים יחדיו שהית' להם ישיבה אחת בעולם א\"כ אם לא היה להם ישיבה אחת בעולם לא שריא רחמנא והיא מחייבי' כריתות עליו לכן אפי' צרתה אסורה ופטורה מחליצ' ויבום אף על גב דנפלה השתא מאח שהי' לו ישיבה אחת בעולם עמו מ\"מ אסור' לו מחמת אחיו הראשון:","\u0003הוה לי' כצרת א\"א שלא היה בעולמו\u0004. וכן הוא במתני' רפ\"ב וא\"ל למה לא תני טעם משום דהיא צרת בעלת זיקת שני יבמין משום כיון מצד ראובן בעלה הראשון אין לה זיקה עליו שהיא א\"א שלא היה בעולמו, א\"כ משום זיקת שני יבמין אינה אסורה אלא מדרבנן ומשום צרת א\"א שלא הי' בעולמו אסור מדאורייתא ועיין בש\"ג רפ\"ב כתב הא דקי\"ל יש זיקה היינו מדברי סופרים יש זיקה, ועיין בש\"ס דף כ\"ז ע\"ב ובתוס' שם מ\"ש בשם ר\"ת ועיין ס\"ס קע\"ד כתבתי אי לא עביד מאמר אינה אסורה משום צרת שני זיקות:","\u0003שהית' נשואה לאחיו מאמו\u0004. כן הוא בטור וקמ\"ל אף על גב דהיא אינה אסורה עליו מדאורייתא אלא שני' היא מחמת בעלה הראשון מ\"מ א\"י למאן השתא ולעקור נישואין קמאי כיון בעת הנפילה היתה נראית כאשת אחי אמו שהיא שני' לו ומכ\"ש כשהית' אשת אחיו מאמו דאז אסורה לו מדאורייתא וצרת' לעולם צריכה חליצה ואין נפטרת מחמת קטנה שהיא ערוה עליו דהא נישואי קטנה רק מדרבנן וקטנה זו אם ממאנת בנשואין הראשונים אז מדאורייתא עוקרת נישואין הראשונים וכאלו היא לבד אשת אחיו מאביו אלא מדרבנן היא אסורה מחמת נישואין הראשונים וצריכ' חליצה ואם אינה ממאנת אפי' בנשואין הראשונים אז אם התה אשת אחי אמו שהיא שניה לו צריכה חליצה ואם יש לה צרה היא נפטרת בחליצת הצרה ואם היא אשת אחיו מאמו א\"צ חליצה:","\u0003אסורה לו\u0004. ולא אמרי' דעקר' נישואין הראשוני' והרי היא נכרית משום דנראה כאשת אחיו כיון דלא מיאנה בבעל':","\u0003אם אין שם אחים אחרים\u0004. כ\"כ הרי\"ף והרא\"ש דאם יש אחים אחרים חולצין או מייבמין אף על גב דקי\"ל ממאנ' לזיקה ועוקרת נישואין הראשונים מ\"מ כה\"ג לא עקרה אלא מזה אבל משאר אחים נשאר הזיק' ועי' בהמאור ובמלחמות ה', מיהו נראה לשיטת הרמב\"ם מותרת לאחיו לאו מתורת הזיק' אלא עוקרת הזיקה והוי כאלו לא הית' אשת אחיהם ומותרת להם דהא הוא פוסק פי\"א מה\"ג מיאנ' ביבם מותרת לקרובי המת אלא לאביו אסורה ולמד זאת מדמותרת לאחים כמ\"ש בהמגיד שם וכך משמע שם מלשון הרמב\"ם ואי מותרת לאחים היינו זיקה אצלם אין ראי' מהיתר אחים להיתר שאר קרוביו כדמדחה הרמב\"ן באמת סברת הרמב\"ם וכתב לאחים מותרת מחמת הזיקה אבל לקרובי המת אסורה א\"ו צ\"ל הרמב\"ם ס\"ל דמותרת לאחים לאו משום זיקה אלא כשעוקרת הזיקה תו לא הוי אשת אחיהם ומותרת להם אף על גב דאסורה ליבם א\"כ נשמע נמי דמותרת לשאר קרובים לפ\"ז תימא על המחבר בסי' קנ\"ה סי\"א הביא פלוגתתם אם מותרת לשאר קרובים ומשמע שם דס\"ל עיקר כרמב\"ם דמותרת לשאר קרוביו א\"כ מוכח דליתא הזיק' וא\"צ חליצה וכאן סתם ופסק כשיטת הפוסקים דצריכה חליצ' משאר אחים:","\u0003אבל צרת' מותרת\u0004. כשם שהיא מותרת לשאר אחים משום דלא עבידא בה מעשה והיא אמר' לא ריענא בזה אבל לשאר אחים ריענא, כך צרתה מותרת, אלא לכאורה קשה מאחר דהיא אסור' א\"כ הממאנת כערוה עליו מחמת אשת אח שלא במקום מצוה, אם כן למה לא אסורה הצרה כמו בצרת איילונית וסוטה, וכעין זה הקשה תוספ' דף י\"ב, וצריך לומר דממאנת בעצמה על פי הדין מותרת מאחר דעקרה נישואין הראשונים ולא הוי כאשת אחיו א\"כ צרתה לא גרע מצרת חייבי לאוין או שניות דמותרת ליבם כמ\"ש בסי' א\"ז:","\u0003חולצת ולא מתייבמת\u0004. שהיא ספק גרושת אחיו שהיא בכרת משא\"כ בספק קידושין מותרת ממ\"נ:","\u0003המגרש וכו'\u0004. אף על גב בעת שגירש אחיו היתה אסורה לו משום גרושת אחיו מ\"מ כיון דלא היתה אסורה עליו בעת הזיקה לא אמרינן כיון דאסורה שעה א' אסורה לעולם וכן הדין בקטנה שהשיאוה אמה ואחיה, מיהו כשהשיאה אביה עדיין שם גרושה עליה כיון דחזרתה לאו חזרה גמורה דהא הגט הי' ע\"י אביה וחזרתה ע\"י עצמה כי אביה אין רשות עליה כיון דנתגרש' אחר הנשואין ועיין סי' קנ\"ה שהביא בהגהות וי\"א אם נשאת קטנה שלא לדעת אמה ואחיה א\"צ מיאון ש\"מ דלאו נשואין כלל הם נראה לכאורה שהשיאוה אמה ואחיה ונתגרשה תו א\"י אמה ואחיה להנשא לה דלא עדיפים מאביה א\"כ חזרת' לאו כלום הוא ושם גירושין עליה מיהו י\"ל בכה\"ג לכ\"ע נישואין שלה מהני מאחר דאין לאמה ואחיה שום רשות עליה מהני מעשיה גם י\"ל אמה ואחיה יכולים להנשא אותה אף שכבר השיאו אותה ונתגרשה דהא בהשיאוה אביה ונתגרשה יכולים אמה ואחיה להנשא ואביה א\"י להנשא אותה כמ\"ש בטור סימן מ\"ג:","\u0003אסורה ליבם\u0004. וכתב הרמב\"ם דא\"צ חליצה ולא יבום מיהו הרא\"ש והטור כתבו דצריכ' חליצה וכן הוא לשיטת הראב\"ד ובעל המאור והיא פטורה בחליצת הצרה והצרה אינה נפטרת בחליצת היתומה:","\u0003צרתה מותרת להתייבם\u0004. כ\"כ רוב הפוסקים אף על גב דהיא צרת ערוה דהא היתומה היא כגרושת אחיו ולרמב\"ם דינה ממש כגרושת אחיו מ\"ה א\"צ חליצה מ\"מ צרתה מותרת להתייב' ובעלמא קי\"ל צרת ערוה של קטנה חולצת ולא מתייבמת עיין בהרא\"ש שתירץ שאני ערוה זו שיש לה היתר לעצמה אם גדלה אצלו ועיין במלחמות ה':"]],["יְבָמָה שֶׁהִיא אֲסוּרָה לַיָּבָם, בְּלָאו אוֹ בַּעֲשֵׂה אוֹ בְּאִסוּר שְׁנִיּוֹת דְּרַבָּנָן, הִיא \u0010c0\u0011 חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ אוֹ חוֹלֶצֶת \u0010c1\u0011 אוֹ מִתְיַבֶּמֶת; וְאֵין חֲלִיצָתָהּ פּוֹטֶרֶת צָרָתָהּ, אֲבָל חֲלִיצַת צָרָתָהּ פּוֹטֶרֶת אוֹתָהּ. וְאִם עָבַר וּבָא עָלֶיהָ, \u0010c2\u0011 קְנָאָהּ, וְנִפְטֶרֶת צָרָתָהּ. וְאִם רָצָה לְהוֹצִיאָהּ, מוֹצִיאָהּ בְּגֵט:\nהָיְתָה אֲסוּרָה לְבַעְלָהּ בְּאִסוּר לָאו אוֹ עֲשֵׂה אוֹ אִסוּר דְּרַבָּנָן, וּמֻתֶּרֶת לְיָבָם, יְכוֹלָה לְהִתְיַבֵּם; חוּץ מִמַּחֲזִיר גְּרוּשָׁתוֹ מִשֶּׁנִּשֵּׂאת, וּמֵת, \u0010c3\u0011 שֶׁהִיא חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת, וְצָרָתָהּ אוֹ חוֹלֶצֶת אוֹ מִתְיַבֶּמֶת:\nאֲחוֹת חֲלוּצָה, אֲסוּרָה מִדְּרַבָּנָן. לְפִיכָךְ, נָפְלָה לִפְנֵי יָבָם, חוֹלֶצֶת \u0010c4\u0011 וְלֹא מִתְיַבֶּמֶת. וְכֵן צָרָתָהּ אֲסוּרָה מִדְּרַבָּנָן, וְחוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nמִי שֶׁיֵּשׁ עָלֶיהָ \u0010c5\u0011 זִקַּת שְׁנֵי יְבָמִים, \u0010c6\u0011 הִיא אוֹ צָרָתָהּ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת. כֵּיצַד, שְׁלשָׁה אַחִים נְשׂוּאִים שְׁלשָׁה נָכְרִיּוֹת, וּמֵת אֶחָד מֵהֶם וְעָשָׂה בָּהּ אֶחָד מֵהַנִּשְׁאָרִים מַאֲמָר בִּיבִמְתּוֹ, וּמֵת קֹדֶם שֶׁכָּנְסָהּ, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nנָתַן לָהּ גֵּט, וּפֵרַשׁ שֶׁהוּא לְמַאֲמָרוֹ, הֲרֵי בָּטֵל הַמַּאֲמָר שֶׁעָשָׂה, וְאֵין עָלֶיהָ אֶלָּא זִקַּת יָבָם אֶחָד, וּמִתְיַבֶּמֶת. אֲבָל אִם נָתַן לָהּ הַגֵּט סְתָם, אֲסוּרָה לְהִתְיַבֵּם:\nקָטָן שֶׁבָּא עַל יְבִמְתּוֹ, וּמֵת, חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת; שֶׁאֵין בִּיאָתוֹ קוֹנָה קִנְיָן גָּמוּר, וְיֵשׁ עָלֶיהָ זִקַּת שְׁנֵי יְבָמִים:\nמִי שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין שֶׁנִּתְקַדְּשָׁה לִרְאוּבֵן, וְנִשְׁתַּחְרְרָה, וְקִדְּשָׁהּ שִׁמְעוֹן אָחִיו, וּמֵתוּ שְׁנֵיהֶם, וְנָפְלָה לִפְנֵי לֵוִי אֲחִיהֶם, מִתְיַבֶּמֶת לוֹ, שֶׁאֵינָהּ אֵשֶׁת שְׁנֵי מֵתִים; שֶׁאִם קִדּוּשֵׁי רְאוּבֵן קִדּוּשִׁין אֵין קִדּוּשֵׁי שִׁמְעוֹן כְּלוּם; וְאִם קִדּוּשֵׁי שִׁמְעוֹן קִדּוּשִׁין, אֵין קִדּוּשֵׁי רְאוּבֵן כְּלוּם:",[],["\u0003חולצת ולא מתייבמ'\u0004. עיין בסוגיא דף ך' מדאוריית' חזיא ליבום דקי\"ל עשה דיבום דוחה ל\"ת של הלאו לכן אם בא עליה פוטרת את צרתה אלא חז\"ל גזרו ביאה הראשונ' אטו ביאה שניה שאין מצות יבום אלא בביאה הראשונ' וכתבו תוס' ל\"ד אלא אפילו גמר הביאה נמי אסור כי היבמה נקנית בתחלת הביא' וכתבו תוס' שם מדביאה הראשונ' מותרת ביבם אפילו מן הארוסין אף על גב דקי\"ל אין אשה מתעבר' מביאה ראשונ' ש\"מ דלא בעינן שתהי' ראוי' להקמת שם אלא כשהם ראוים להקמת שם לאפוקי איילונית וסריס, מכאן נראה ה\"ה אם רוצה רק לבעול פ\"א ולגרש אותה מיד ג\"כ מותר, ומה קשה מכאן למ\"ש בסי' ק\"ע כתבתי שם וע\"ש ואם היא אלמנה מן הנשואין ובא עלי' כ\"ג לא נפטרה צרתה דאין עשה דוחה את ל\"ת ועשה של אלמנה לכ\"ג שם ורמב\"ם שם:","\u0003או מתייבמו'\u0004. כ\"כ הטור והנ\"י והש\"ג שאין צרתה פטורה אלא מערוה שהיא חייבי כריתות או ח\"מ כדנפקא לן מאחות אשה דכתב בה לצרור וכן הוא בירושלמי:","\u0003קנאה ונפטרת צרתה\u0004. כמ\"ש בס\"ק א' הטעם, ולכאור' תימא ע\"פ סוגיא שם משום דעשה דוחה ל\"ת מ\"ה חזי' לביאה וקונה אותה בביאה ונפטרה צרתה ונדחה שם תירוץ של רבא דאמר דלא דחי' עשה את ל\"ת מאחר דיכול לקיים שניהם העשה ואת ל\"ת וליתן חליצה ונדחה שם מטעם דקיי\"ל חליצה במקום יבום לאו מצוה היא, א\"כ להני פוסקים דפסקו מצות חליצה קודם כמ\"ש בסימן קס\"ה א\"כ אין העשה דוחה את הל\"ת כמימרא דרבא דהא מצות חליצה יותר מצוה א\"כ תירוץ של רבא עיקר לפ\"ז לא דחי' את הל\"ת ולא נפטרה הצרה דלא קיימא לביאה כקושי' הש\"ס שם, וצ\"ל מצות חליצה קודם דרבנן אבל מדאורייתא מצות יבום לכ\"ע קודם ודחי' את הל\"ת וכן הוא בנ\"י כמה שהבאתי לעיל, אלא צריך ישוב הש\"ס דף ל\"ט דמשמע דפליגי אם איכא א\"ד דהא חכמים דפליגי על אבא שאול למדו מקרא יבמה יבא עליה ואם א\"ש מדרבנן קאמר איך מייתו רבנן קרא מדאורייתא, וי\"ל רבנן ס\"ל אפי' אם נושא לשם דבר אחר ליכא איסור דאורייתא מ\"ה אם נושא סתם וא\"י אם נושא לשם ד\"א לא גזרי' דרבנן לכן הביאו קרא יבמה יבא עליה כלו' כיון דאורייתא ליכא איסור לא גזרי חז\"ל בנושא סתם, ואבא שאול ס\"ל אם נושא לשם ד\"א איכא א\"ד מ\"ה ס\"ל אם נושא סתם אסור והא דקאמר מח\"ק היינו כיון דמח\"ק מ\"ה גזרו חז\"ל אם א\"י אם נושא לשם ד\"א דאל ישא אותה כנ\"ל למ\"ש הנ\"י עוד מוכח בסוגיא זו כל שאינה עולה ליבום מדאורייתא אינה פוטרת את צרתה בביא' שלה וגם אתה עצמה אינה פוטרת בביאה זו דהא הקשה שם מבריי' אם בא עליה הפצוע קנאה ושם לא איירי דיש לה צרה ולכאור' קשה למה כתב הרמב\"ם פ\"ו אם בא על אלמנה מן נשואין לא נפטרה הצרה ת\"ל היא עצמה ג\"כ אינה פטורה ויש ליישב:","\u0003שהיא חולצת ולא מתייבמ'\u0004. וכתב המגיד אם נפלה לפניו מחזיר גרושתו וצרת' נפטר' הצרה בחליצה של זו ולא בביאת' ומדמה דין של זו לאלמנ' לכ\"ג והב\"י והכ\"מ הקשו עליו איך מדמ' אלמנ' לכ\"ג בשלמ' אלמנ' לכ\"ג איכא עשה ול\"ת אבל מ\"ג ליכא אלא לאו עוד הקשה למה הצרה נפטרה בחליצה של זו דהא בעלמא ס\"ל להרמב\"ם כשהיא מחייבי לאוין לא נפטרה הצרה בחליצה של זו, ונראה לי דכוונת המגיד הוא משום מ\"ג אסורה ליבם מק\"ו אם היא אסור' לבעלה שמותר לה להיבם שאסור לה לא כ\"ש ופרש\"י ריש סוטה דף ו' אם נאסרה למותר מחמת הנישואים של אחר מכ\"ש שנאסרה להיבם דאל יתייבם אותה לפ\"ז היא גרוע טפי מחייבי לאוין דקי\"ל מדאורייתא חזיא לביאה אלא רבנן גזרו ביאה הראשונ' אטו ביאה שני' וזו מדאורייתא לא חזיא משום דילפינן מק\"ו שאל יתייבם אותה אבל חייבי לאוין לא כתיב הלאו ביבום ומדאורייתא הוי לן למימר דאתי עשה דיבום ודחה הלאו, אבל מ\"ג מק\"ו ילפינן דאסורה ליבום א\"כ מדאורייתא אסורה ליבום תו ליכא למימר דעשה דוחה הלאו א\"כ הק\"ו למאי אתי דהא ליבם אסורה אם לא במקום מצוה ואתי הק\"ו דאסורה במקום מצוה מ\"ה דמי' לאלמנ' לכ\"ג דהיא ג\"כ מדאורייתא לא חזי' ליבם משום דאיכא עשה ול\"ת ואתי' מדרב גידל דצריכ' חליצה מדכתב ועלתה יבמתו השערה כן הוא במ\"ג דלא חזי ליבום וצריכה חליצה מ\"ה נפטרה הצרה משום דהתור' כתב בפירוש דעלתה לחליצ' וכן אלמנה לכ\"ג נפטרה הצרה, ולא כט\"ז שהאריך להקשות על המגיד והבין דמ\"ג לא גרע מחייבי לאוין וחזי' מדאורייתא ליבום אלא חז\"ל גזרו ביאה הראשונה אטו ביאה שניה וליתא אלא הק\"ו אתי' דלא חזי' לביאה וכל הסוגיא ושקל' וטרי' של ר' יוחנן במ\"ג א\"צ לומר הטעם דגזרינן ביאה הראשונה אטו ביאה שניה אלא מק\"ו ילפינן דלא חזי' לביאה, ועיין ב\"ח כתב ג\"כ הא דנפטרה הצרה מחליצה של זו משום דאתי' מקרא ועלתה יבמתו השערה מיהו מתוס' דף כ\"ו לא משמע כן דהא הקשו על פירש\"י שם דחליצה פסולה היא כל שא\"י לייבם למה חליצת מחזיר גרושתו פוטרת את צרתה ש\"מ דלא ס\"ל הסברא מדרבתה התורה לחליצה פוטרת את צרתה, מיהו לדינא לא נ\"מ וי\"ל לכ\"ע פוטרת את צרתה מדתירץ שם דף י\"א מחזיר גרושתו וצרתה או היא או צרתה חולצת ש\"מ דצרתה נפטר' בחליצה של זו דהא אף קודם שעלתה המסקנא דצרתה ראויה ליבם מ\"מ חליצת מ\"ג גרוע עכ\"פ מחליצ' צרתה אף על פי דצרה ג\"כ אסורה להיבם ותני' דנפטר' בחליצה של זו נראה לסברת המגיד נפטרה מטעם דרבתה התורה לחליצה כמ\"ש ולתוס' הטעם כיון דלא קלשה הזיק' כמ\"ש בסי' ק\"ע:","\u0003ולא מתייבמ'\u0004. אף על גב צרות חייבי לאוין מתייבמו' וזו אסורה רק מדרבנן ולא מתייבמת משום דשוי' חז\"ל חלוצה כגרוש' ואחותה שהיא ערוה והוי צרת ערוה ועיין תוס' שם דף מ\"א, וכתב הב\"י ה\"ה צרת חלוצתו מד\"ס ולכאורה אין הבנה לזה, וצ\"ל דאיירי שאחיו נשא החליצה באיסור ואסור' ג\"כ מטעם הנ\"ל שכתבו תוספות דעשאו חז\"ל כאלו נשא גרושת אחיו באיסור ואסרו הצרות גם י\"ל לדעת הרמב\"ם קאמר ועיין סי' קס\"ב, ולכאור' נרא' אם עבר ונשא חלוצה ונפל' לפני זה צריכ' היא עוד השתא חליצה מזה מחמת נישואין את זה דהא קדושין של זה תפסי בה:","\u0003זיקת שני יבמי'\u0004. עיין בתוספת וברמב\"ם כל זה אינו אלא מדרבנן ולאו דרשה גמור' היא אלא אסמכתא:","\u0003והיא וצרתה חולצת\u0004. כצ\"ל ומ\"ש בש\"ע או צרתה ט\"ס הוא והטעם מבואר בש\"ס דאם מייבם לתרוויי' אמרו ב' יבמות הבאים מבית א' מתייבמות ואם מייבם אחת ויחלוץ לאחת חיישינן שמא יחלוץ ברישא והדר מייבם לכן דוקא אם עשה מאמר בא' אז אסורות שתיהן ליבם אבל אם לא עשה מאמר אינם אסורות משום צרת זיקות שני יבמים כיון דזיקת ב' יבמי' רק מדרבנן לא אסרי' מחמת זיקה כ\"כ רש\"י דף ל' ועיין פריש':"]],["יְבָמָה שֶׁאֵינָהּ רְאוּיָה לְהִתְיַבֵּם בִּשְׁעַת נְפִילָה, מִשּׁוּם אִסוּר עֶרְוָה, אֲסוּרָה עוֹלָמִית, אֲפִלּוּ אִם יִפְקַע הָאִסוּר. כְּגוֹן שְׁנֵי אַחִים שֶׁנְּשׂוּאִים שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מֵהֶם, וְנָפְלָה אִשְׁתּוֹ לִפְנֵי הַשֵּׁנִי שֶׁנָּשׂוּי אֲחוֹתָהּ, אֲפִלּוּ אִם תָּמוּת אִשְׁתּוֹ אַחַר כָּךְ, שֶׁפָּקַע אִסוּר אֲחוֹת אִשָּׁה, אֲפִלּוּ הָכִי אֲסוּרָה. וַאֲפִלּוּ נָפְלָה לְפָנָיו פַּעַם אַחֶרֶת אַחֲרֵי מוֹת אִשְׁתּוֹ, כְּגוֹן שֶׁהָיָה לָהֶם אָח שְׁלִישִׁי שֶׁלֹּא הָיְתָה עֶרְוָה עָלָיו, וּכְּנָסָהּ, וּמֵתָה אִשְׁתּוֹ שֶׁל זֶה שֶׁהָיָה נָשׂוּי אֲחוֹתָהּ, וּמֵת הַשְּׁלִישִׁי שֶׁכְּנָסָהּ, וְחָזַר וְנָפְלָה לְפָנָיו, אֲסוּרָה לוֹ. \u0010c0\u0011 לָא שְׁנָא מֵתָה אִשְׁתּוֹ קֹדֶם שֶׁכָּנַס הַשְּׁלִישִׁי, לֹא שְׁנָא מֵתָה אַחַר שֶׁכָּנַס, אַף עַל פִּי שֶׁלֹּא הָיְתָה אֲסוּרָה עָלָיו בִּשְׁעַת נְפִילָה אַחֲרוֹנָה, אֲפִלּוּ הָכִי אֲסוּרָה לוֹ הִיא וְצָרָתָהּ, כְּגוֹן שֶׁהָיָה אִשָּׁה אַחֶרֶת לָאָח הַשְּׁלִישִׁי, כֵּיוָן שֶׁהָיְתָה אֲסוּרָה לוֹ בִּשְׁעַת נְפִילָה רִאשׁוֹנָה. אֲבָל אִם הָיְתָה מֻתֶּרֶת לוֹ בִּשְׁעַת נְפִילָה, אֲפִלּוּ אִם תֵּאָסֵר אַחַר כָּךְ, אִם פָּקַע הָאִסוּר, חוֹזֶרֶת לְהֶתֵּרָהּ. כֵּיצַד, שְׁלשָׁה אַחִים שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מֵהֶם, וְנִזְקְקָה אִשְׁתּוֹ לַשְּׁלִישִׁי שֶׁאֵינוֹ נָשׂוּי אֲחוֹתָהּ, וְלֹא הִסְפִּיק לְכָנְסָהּ עַד שֶׁמֵּת הָאָח הַשֵּׁנִי שֶׁהָיָה נָשׂוּי הָאַחֶרֶת, וַהֲרֵי שְׁתֵּיהֶן אֲסוּרוֹת עָלָיו, מֵתָה הָאַחֲרוֹנָה, חָזְרָה הָרִאשׁוֹנָה לְהֶתֵּרָהּ, כֵּיוָן שֶׁהָיְתָה מֻתֶּרֶת בִּשְׁעַת נְפִילָה, אַף עַל פִּי שֶׁנֶּאֶסְרָה בֵּינְתַיִם. אֲבָל אִם מֵתָה הָרִאשׁוֹנָה, לֹא הֻתְּרָה הָאַחֲרוֹנָה, כֵּיוָן שֶׁהָיְתָה אֲסוּרָה בִּשְׁעַת נְפִילָה. וְכֵן אִם הָיוּ שָׁם עוֹד אַחִים, וְקָדַם אֶחָד מֵהֶם \u0010c1\u0011 וְחָלַץ לָאַחֲרוֹנָה, אוֹ שֶׁהָיְתָה הָרִאשׁוֹנָה אֲסוּרָה לְאֶחָד מֵהָאַחִים, וְיִבֵּם אֶת הָאַחֲרוֹנָה, שֶׁהֲרֵי מֻתֶּרֶת לוֹ, \u0010c2\u0011 הֻתְּרָה הָרִאשׁוֹנָה לִשְׁאָר אַחִים, שֶׁהֲרֵי הָאַחֲרוֹנָה שֶׁאָסְרָה אוֹתָהּ, חָלְצָה אוֹ נִתְיַבְּמָהּ לַמֻּתָּר לָהּ. אֲבָל אִם הָאַחֲרוֹנָה אֲסוּרָה לְאֶחָד מֵהֶם מִשּׁוּם עֶרְוָה, הֲרֵי הוּא מֻתָּר לְיַבֵּם הָרִאשׁוֹנָה, וּשְׁאָר הָאַחִים אֲסוּרִים בִּשְׁתֵּיהֶן, וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת:\nשְׁנַיִם מֵהָאַחִים נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת, וּמֵתוּ שְׁנֵיהֶם, \u0010c3\u0011 וְלֹא נוֹדַע אֵיזֶה מֵהֶם מֵת רִאשׁוֹן, הוֹאִיל וְאִי אֶפְשָׁר לְיַבֵּם שְׁתֵּיהֶן, וַהֲרֵי זִקָּה נָפְלָה עַל שְׁתֵּיהֶן, חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. וַאֲפִלּוּ הָיְתָה אַחַת מֵהֶם אֲסוּרָה עַל הַיָּבָם מִשּׁוּם שְׁנִיָּה אוֹ מֵחַיָּבֵי עֲשֵׂה אוֹ מֵחַיָּבֵי לָאוִין, הֲרֵי אֵלּוּ חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. אֲבָל אִם הָיְתָה אַחַת מֵהֶם עֶרְוָה עָלָיו, הֲרֵי אֲחוֹתָהּ מֻתֶּרֶת לוֹ, רָצָה חוֹלֵץ רָצָה מְיַבֵּם, שֶׁהֲרֵי לֹא נָפְלָה זִקָּתוֹ עַל שְׁתֵּיהֶן, שֶׁאֵין זִקָּה עַל הֶעֶרְוָה:\nאַרְבַּע אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת, וּמֵתוּ הַנְּשׂוּאִים אֶת הָאֲחָיוֹת, אוֹ בָּזֶה אַחַר זֶה, קֹדֶם שֶׁהִסְפִּיקוּ לְיַבֵּם לָרִאשׁוֹנָה, שְׁתֵּיהֶן חוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת, שֶׁאִי אֶפְשָׁר לְשׁוּם אַחַת מֵהֶן לְהִתְיַבֵּם, מִשּׁוּם אִסוּר אֲחוֹת זְקוּקָה. וְאִם קָדְמוּ וְכָנְסוּ כָּל אֶחָד אַחַת מֵהָאֲחָיוֹת, מוֹצִיאִים אוֹתָן מֵהֶם; \u0010c4\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאֵין מוֹצִיאִין:\nהָיְתָה אַחַת מֵהֶם אֲסוּרָה לְאֶחָד מֵהַיְבָמִין מִשּׁוּם אִסוּר עֶרְוָה, מֻתָּר בַּשְּׁנִיָּה, שֶׁהֲרֵי אֵין הָעֶרְוָה זְקוּקָה לוֹ, וְנִמְצָא שֶׁאֵין זְקוּקָה לוֹ אֶלָּא אַחַת; וְהַשֵּׁנִי, אָסוּר בִּשְׁתֵּיהֶם:\nהָיְתָה אַחַת מֵהֶן אֲסוּרָה לְזֶה מִשּׁוּם עֶרְוָה, וְהַשְּׁנִיָּה אֲסוּרָה לַשֵּׁנִי מִשּׁוּם עֶרְוָה, הָאֲסוּרָה לְזֶה מֻתֶּרֶת לְזֶה, שֶׁכָּל אֶחָד אֵין זְקוּקָה לוֹ אֶלָּא אַחַת. אֲבָל אִם אֵין אֲסוּרוֹת עֲלֵיהֶם אֶלָּא בְּאִסוּר לָאו אוֹ עֲשֵׂה, לֹא נִדְחֵית הַזִּיקָה מֵהֶם, וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִין שְׁתֵּי אֲחָיוֹת, וּמֵת אֶחָד מִבַּעֲלֵי הָאֲחָיוֹת, וְאַחַר כָּךְ מֵת בַּעַל אֲחוֹת הַשְּׁנִיָּה, וְנָפְלָה גַּם הָאָחוֹת הַשְּׁנִיָּה לִפְנֵי הָאָח הַשְּׁלִישִׁי, שְׁתֵּיהֶן אֲסוּרוֹת עָלָיו, שֶׁהֵן צָרוֹת זוֹ לָזוֹ בְּזִקָּה, וְחוֹלְצוֹת וְלֹא מִתְיַבְּמוֹת. וְאִם עָשָׂה מַאֲמָר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ נָפְלָה אֲחוֹתָהּ לְפָנָיו, יוֹצִיא בַּעֲלַת הַמַּאֲמָר בְּגֵט וַחֲלִיצָה, וְהָאַחֲרוֹנָה בַּחֲלִיצָה:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וְאֶחָד נָשׂוּי נָכְרִית, מֵת נָשׂוּי נָכְרִית, וְכָנַס אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ, וּמֵת, הָרִאשׁוֹנָה יוֹצֵאת מִשּׁוּם אֲחוֹת אִשָּׁה, וְהַשְּׁנִיָּה מִשּׁוּם צָרָתָהּ. וְאִם לֹא כְּנָסָהּ, בֵּין שֶׁעָשָׂה מַאֲמָר בַּנָּכְרִית, \u0010c5\u0011 בֵּין שֶׁלֹּא עָשָׂה בָּהּ מַאֲמָר, הֲרֵי זוֹ חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:\nשְׁלשָׁה אַחִים, שְׁנַיִם מֵהֶם נְשׂוּאִים שְׁתֵּי אֲחָיוֹת, וְאֶחָד נָשׂוּי נָכְרִית, גֵּרַשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אִשְׁתּוֹ, וּמֵת נָשׂוּי נָכְרִית, וּכְּנָסָהּ הַמְגָרֵשׁ, וּמֵת, מֻתֶּרֶת לָאָח הַנִּשְׁאַר. \u0010c6\u0011 אֲבָל אִם מֵת נָשׂוּי נָּכְרִית קֹדֶם שֶׁגֵּרַשׁ אֶחָד מִבַּעֲלֵי אֲחָיוֹת אֶת אִשְׁתּוֹ, \u0010c7\u0011 אֲפִלּוּ אִם לֹא כָּנַס נָּכְרִית וָמֵת, אֲסוּרָה לָאָח הַנִּשְׁאַר, מִפְּנֵי שֶׁהָיְתָה צָרַת עֶרְוָה בְּזִקָּה, אֲפִלּוּ אִם גֵּרַשׁ הָעֶרְוָה קֹדֶם שֶׁמֵּת. \u0005 וְהוּא הַדִּין אִם הָיָה נָשׂוּי נָכְרִית, וְיֵשׁ לוֹ בָּנִים, \u0010c8\u0011 אֲסוּרָה לוֹ מִשּׁוּם זִקַּת אֵשֶׁת אָחִיו שֶׁיֵּשׁ לוֹ בָּנִים \u0006 \u0005(הַגָּהוֹת אַלְפָסִי פ' ד' אַחִין)\u0006. אֲבָל אִם כָּנַס בַּעַל \u0005(הָאֲחָיוֹת)\u0006 [הָאָחוֹת] אֶת הַנָּכְרִית, וְגֵרַשׁ הָעֶרְוָה, וּמֵת, לָא שְׁנָא גֵּרַשׁ קֹדֶם שֶׁכָּנַס הָעֶרְוָה, לָא שְׁנָא אַחַר כָּךְ, מֻתֶּרֶת הַנָּכְרִית לָאָח הַנִּשְׁאַר:\nשְׁנֵי אַחִים פִּקְחִים נְשׂוּאִין שְׁתֵּי אֲחָיוֹת קְטַנּוֹת אוֹ חֵרְשׁוֹת, וּמֵת אֶחָד מֵהֶם, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה, שֶׁהֲרֵי נִשּׂוּאֵי שְׁתֵּיהֶן שָׁווֹת:\nהָיְתָה אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת; מֵת בַּעַל הַחֵרֶשֶׁת, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה; מֵת בַּעַל הַפִּקַּחַת, בַּעַל הַחֵרֶשֶׁת מוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט, וְאֶת אֵשֶׁת אָחִיו בַּחֲלִיצָה:\nהָיְתָה אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה; מֵת בַּעַל הַקְּטַנָּה, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה; מֵת בַּעַל הַגְּדוֹלָה, \u0010c9\u0011 מְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן בְּבַעְלָהּ, וִייַבֵּם הַגְּדוֹלָה:\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת פִּקְחוֹת, אוֹ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְהַפִּקַּחַת נְשׂוּאָה לְפִקֵּחַ, מֵת חֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אוֹ חֵרֵשׁ בַּעַל הַפִּקַּחַת, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה. מֵת פִּקֵּחַ בַּעַל הַפִּקַּחַת, הַחֵרֵשׁ בַּעַל הַחֵרֶשֶׁת, אוֹ בַּעַל הַפִּקַּחַת, מוֹצִיא אֶת אִשְׁתּוֹ בְּגֵט, וְאֵשֶׁת אָחִיו אֲסוּרָה לָעוֹלָם:\nשְׁנֵי אַחִים חֵרְשִׁים נְשׂוּאִים לִשְׁתֵּי אֲחָיוֹת פִּקְחוֹת אוֹ חֵרְשׁוֹת, אוֹ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְכֵן שְׁתֵּי אֲחָיוֹת חֵרְשׁוֹת נְשוּאוֹת לִשְׁנֵי אַחִים פִּקְחִים אוֹ חֵרְשִׁים אוֹ אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, וּמֵת אֶחָד מֵהֶם, תֵּצֵא מִשּׁוּם אֲחוֹת אִשָּׁה. וְאִם הָיוּ נָכְרִיּוֹת, יַכְנִיסוּ; וְאִם אַחַר כָּךְ יִרְצוּ לְהוֹצִיא בְּגֵט, יוֹצִיאוּ:\nשְׁנֵי אַחִים, אֶחָד פִּקֵּחַ וְאֶחָד חֵרֵשׁ, וְהַחֵרֵשׁ נָשׂוּי שְׁתֵּי נָשִׁים פִּקְחוֹת, וְאַחַת מֵהֶן עֶרְוָה עַל הַפִּקֵּחַ, וּמֵת הַחֵרֵשׁ, שְׁתֵּיהֶן פְּטוּרוֹת מֵהַחֲלִיצָה וּמֵהַיִּבּוּם. הָיוּ שְׁנֵיהֶם פִּקְחִים, וְאֶחָד מֵהֶם נָשׂוּי שְׁתֵּי נָשִׁים, אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת, וְהַחֵרֶשֶׁת הִיא עֶרְוָה עַל אָחִיו, הַשְּׁנִיָּה הַפִּקַּחַת חוֹלֶצֶת וְלֹא מִתְיַבֶּמֶת:",[],["\u0003ל\"ש מתה אשתו קודם שכנסה השלישי\u0004. אז הוי תרתי לטובה דזו אינה נדחה מהאי בית לגמרי דהא ראויה לנשוי נכרית גם בהאי נפילה אתחזי' לזה מ\"מ אסורה ש\"ס וצרתה ג\"כ אין חילוק בין אם נשא נכרית קודם שייבם את זו או אח\"כ מיהו מ\"ש הרמב\"ם דנכרית אסורה לזה כשייבם את זו נראה ל\"ד קאמר אף אם לא ייבם מ\"מ בזיקה היתה אשתו צרה לזו:","\u0003וחלץ לאחרונה\u0004. דוקא בדיעבד אבל לכתחל' חיישינן שמא יחלוץ להראשונ' ש\"ס והנה לפירוש הרמב\"ם והטור חיישינן שמא זה יחלוץ לראשונ' אבל אם חלץ כבר לא חיישינן שמא בעלמא יחלוץ לראשונ' ועיין בתוס' שם דפירשו ג\"כ אליבא דרש\"י כן, מיהו אם הראשונה אסורה לזה שכתבו ג\"כ לשון בדיעבד משמע נמי לכתחלה אסורה מטעם דאיכא למיחש שמא אתי לייבם את השניה קודם לזה ליתא אלא אף לכתחלה מותרת כמ\"ש שם דפריך וליקו החתן ליבם הך דאינה חמותה תחלה ותהוי חמותה לגבי אידך כיבמה שהותרה וכו' ש\"מ אף לכתחלה מותרת משום דל\"ד הנך חששות זה לזה דשם חשש בזה דאתי שיחלוץ להראשונה אבל לא חיישינן שאח השני אתי לייבם קודם לזה:","\u0003הותרה הראשונה\u0004. ומה שסתם ופסק כאן אם חלץ לאחרונה מותרת הראשונה היינו למ\"ד חליצה פסולה א\"צ לחזור על כל האחים, אבל למ\"ד ח\"פ צריך לחזור על כל האחים נמצא צריכה כ\"א חליצה מכל האחים דהא חליצתה פסולה היא מחמת שהיא אחות זקוקתו א\"כ א\"א לומר שמותרת הראשונה וכ\"כ תוס' שם ד\"ה איתיבי:","\u0003ולא נודע איזה מהם מת ראשון וכו'\u0004. כתב המגיד בזה ג\"כ אם קדמו וכנסו מוציאין מידם ותימא דהא בש\"ס מבואר משני אין מוציאין די\"ל הראשון ייבם השניה והשני הראשונה מייבם והוי יבמה שהותרה ונאסרה וחזרה והותרה וכן קשה בסמוך מ\"ש ומתו הנשואין האחיות או בזא\"ז וכו' מוציאים אותם מהם דהא לפי הסוגיא משמע דקי\"ל א\"א לצמצם א\"כ באמת לא מתו בפעם אחת אלא א' ולא נודע איזה מת ראשון א\"כ אין מוציאין משני ואנן קי\"ל אי אפשר לצמצם עיין בהרא\"ש פ\"ב דבכורות וכמ\"ש בי\"ד שי\"ח מסוגיא זו משמע אם בא אחד וייבם לשניה מותרת הראשונה לשני דהוי יבמה שהותרה ונאסרה וחזרה והותרה לכן אין מוציאין משני אף בספק משום די\"ל הראשון כנס השני' והוא הראשונה מכ\"ש אם הראשון ייבם השניה בודאי מיהו כל הפוסקים כתבו ואם חלץ לשניה הותרה הראשונה משמע אבל בייבם את השניה לא הותרה הראשונה, ודוקא בדיעבד אין מוציאין משני אבל לא הותרה הראשונ' לכתחלה:","\u0003ויש מי שאומר שאין מוציאין\u0004. כ\"כ הטור ועיין ב\"ח שכתב טעות סופר הוא ומה שרוצה ליישב אליבא דר' יוסי הגלילי דס\"ל אפש' לצמצם אלא דלא ידעינן הי נפלה בראשונה וכו' ע\"ש תמוה הוא לר\"י הגלילי שייך לומר אני כנסתי הראשונה מאחר שניהם בפ\"א נאסרים גם הא קי\"ל כרבנן דס\"ל א\"א לצמצם כמ\"ש בסמוך:","\u0003בין שלא עשה בה מאמר\u0004. משום היא בזיקת צרת אחות אשתו וה\"ה להיפוך שמת א' מבעלי אחיות ואח\"כ מת הנשוי נכרית:","\u0003אבל אם מת נשוי נכרית וכו'\u0004. דאז היא זקוקה לשניהם והיא בזיק' צרת אחות אשתו ומ\"מ כל זמן ששניהם בחיים מותר אחד מהן לייבם ואין איסור משום צרת אחות אשתו אא\"כ אם מת א' משנים אלו ונפלו זו ואשתו שהיא אחות אשת החי אסורה זו כמ\"ש בתוס' והרא\"ש:","\u0003אפי' אם לא כנס וכו'\u0004. הנה יש כאן מקום להאריך וראיתי בדרישה וב\"ח מאריכים בזה ואכתוב בקיצור אם מת הנשוי נכרית ולא גירש אחד מבעלי אחיות את אשתו ומת אחד מהם לכ\"ע אסורה כיון דנשארת זקוקה ולכ\"א היא בזיקת צרת אחות אשתו ואם מת הנשוי נכרית ואח\"כ גירש א' מהם אשתו אז לדעת רש\"י אם מת זה שגירש מותרת הנכרית דקי\"ל מיתה מפלת כמה דקי\"ל אם כנס הערוה ונכרי' וגירש הערוה מותרת הנכרית כן הוא דעת הראב\"ד ורשב\"א וכו' וכ\"פ הש\"ג מיהו להרי\"ף והרמב\"ם והרא\"ש אסורה אף על גב דקי\"ל בעלמא מיתה מפלת מ\"מ הכא גרע טפי מטעם המבואר בהרי\"ף דגזרינן דאתי לייבם הנכרית אף אם לא יגרש הערוה כיון דאין אסורה לו אלא מחמת הזיק' וכ\"כ הרמב\"ם טעם זה ועוד טעם אחר כיון דהנכרית בשעת נפילה באיסור זיקה קא נפלה קמיה לא מהני בה גירושין ויש כאן מקום לומר דוקא בלא כנס הנכרית אז אסורה אבל בכנס ואח\"כ גירש הערוה מותרת דאז לא שייך הגזירה הנ\"ל וכ\"כ בדרישה ומגיה בטור מ\"ש ואפילו אם לא כינס צ\"ל אם לא כינס וי\"ל הטור ס\"ל כסברא זו ולא כהרא\"ש דאוסר אפילו בכונס לפ\"ז שפיר הסוגיא בפ\"ק דהקשה אפילו כנס ולבסוף גירש ורמינהו וכו' טעמא גירש ואח\"כ כנס אבל כנס ואח\"כ גירש לא משום כאן כנס ג\"כ מותר לכן הקשה ל\"ל שגירש קודם שמת אחיו וכנס אח\"כ ת\"ל אפילו אם מת אחיו וכנס וגירש או בגירשה וכנס מותר מיהו המגיד כתב בשם הראב\"ד והרשב\"א ורמב\"ן וכן הוא מפרש דברי הרמב\"ם בכנס פשיטא דאסור' והסוגיא י\"ל באמת לפי סברת רב אשי במת הנשוי נכרית ואח\"כ גירש א' מבעלי אחיות אסורה וס\"ל דהכא גרע מטעמים שכתב הרי\"ף תו א\"צ התירוצים של ר' ירמיה ורבא בפ\"ק דף י\"ג ואפשר לדחוק ולפרש מ\"ש הטור והמחבר בסמוך אבל אם כנס בעל האחיות וכו' לא קאי על ד\"ז אם מייבם הנכרית אלא דין בעלמא קאמר אם ב\"א יש להם ב\"א וכנס א' נכרית וגירש את אחות א\"א מותר הנכרית והיינו כקושי' הרי\"ף ומחלק בין דין שכונס דרך יבום ובין הכונס שלא דרך יבום וגירש מותרת הנכרית ולכאורה נראה דמוכח כן דכנס אסור דאי אמרת כנס עדיף א\"כ למה לש\"ס למימר אליבא דרב' זו היא למעוטי מת בלא גירש דלמא מודה רבא אם מת וגירש אסור אף על גב דס\"ל מית' מפלת מ\"מ איכא למגזר כהנ\"ל משא\"כ בשאר ערוה שכנס עם נכרית והא דצריך לתרץ בפ\"ק לא זו אף זו ולא תירץ כאן גרע טפי משום גזירה משום קושיית המקשן היא בכנס אז גם כאן מותר למה תנא גירש ואח\"כ מת וכנס הא מת ואח\"כ כנס וגירש ג\"כ מותר:","\u0003אסורה לו וכו'\u0004. נראה דס\"ל הטעם דאסורה הנכרית לאחי' אף על גב דהיא צרת אחות אשתו בזיקה ואינה אסורה אלא אחר מיתת אחיו השני משום בחייהם אמרינן דאינה זקוקה להם אלא מחמת אחיו הראשון ומותרת אבל אחר מיתת השני והיתה זקוקה לו מחזי כאלו אח השלישי נושא אותה מחמת אח השני והיא היתה בזיקת צרת אחות אשתו כן ה\"נ דמחזי כאלו היה נושא אשת אחיו דיש לו בנים:","\u0003מלמדין את הקטנה שתמאן\u0004. ואם לא מיאנה והגדילה ל\"ש בא עליה לאחר שהגדילה ל\"ש לא בא עליה מוציא את אשתו ואת א\"א בחליצה דקי\"ל יש זיקה כ\"כ רי\"ו בשם הרמ\"ה וא\"ל הא דאית' פד\"א דף כ\"ט למעוטי דר\"י דאמר בדין זה דמוציא את אשתו ואת יבמתו משום דאתי' למ\"ד אין זיקה אבל למה דקי\"ל יש זיקה הלכתא כר\"י אם היא אינה רוצה למאן, ומ\"ש אפילו בא עליה לאחר שהגדילה לא פקעה זיקה של יבמתו עיין מ\"ש בש\"ס קנ\"ט בשם תוס' דלא ס\"ל כן ועיין ב\"ח מאריך בזה והביא פרש\"י דף י\"ח דדין של ר\"ג שאמר בפלוגתא זו תמתין עד שתגדיל ותצא הגדולה משום אחות אשתו אתי אפילו למ\"ד יש זיקה, ופסק אם אין רצונה למאן עבדינן כר\"ג, מיהו נראה לכאורה אף אם אתי' דין של ר\"ג אפי' למ\"ד יש זיקה מ\"מ הא אוקמא בפרק ב\"ש (יבמות דף ק\"ט) דר\"ג סבר המקדש אחות זקוקה נפטרת היבמה ואנן קי\"ל דלא נפטרה והנ\"י כתב בשם כמה פוסקים אפילו נשא אותה לא מהני לכן עיקר כפסק רי\"ו ולא מטעמי' משום יש זיקה אלא מטעם דלא נפטרה היבמה ומכ\"ש דאסור לומר לכתחלה שיעשה מעשה בקטנה כדי לדחות את הגדולה, וא\"ל אף אם תמאן הקטנ' איך מותרת הגדול' הא בעת הנפילה היתה נראית כאחות ומ\"ש מצרת בתו ממאנת דלא מהני מיאון בתו כיון שהיתה נראית בעת הנפילה כצרת בתו עיין תוס' פד\"א שם שתירצו כיון שהיא ממאנת בעוד בעלה חי עוקרת לגמרי הנשואין ועדיף ממאנת לאחר שמת בעלה:"]],["מִי שֶׁקִּדֵּשׁ אַחַת מִשְּׁתֵּי אֲחָיוֹת, וְאֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ, אֲפִלּוּ לֹא הֻכְּרוּ מֵעוֹלָם, שֶׁלֹּא נִתְּנוּ לְבִיאָה, הֲווֹ קִדּוּשִׁין וְצָרִיךְ גֵּט לְכָל אַחַת וְאַחַת. מֵת, וְלוֹ אָח, חוֹלֵץ לִשְׁתֵּיהֶן. הָיוּ לוֹ שְׁנֵי אַחִים, אֶחָד חוֹלֵץ וְאֶחָד מְיַבֵּם לַשְּׁנִיָּה. קָדְמוּ שְׁנֵי הָאַחִים וְכָנְסוּ אֶת \u0010c0\u0011 שְׁתֵּיהֶן, אֵין מוֹצִיאִים אוֹתָן מִיָּדָם. וְאִם נִמְלְכוּ בְּבֵית דִּין וְאָמְרוּ לָהֶם שֶׁיַּחֲלֹץ הָאֶחָד וִיְיַבֵּם הַשֵּׁנִי, וְהָלְכוּ שְׁנֵיהֶם וְיִבְּמוּ, יוֹצִיאוּ:\nמִי שֶׁעָבַר וְיִבֵּם וַדַּאי אֲחוֹת זְקוּקָתוֹ, \u0010c1\u0011 יוֹצִיא:\nשְׁנַיִם שֶׁקִּדְּשׁוּ שְׁתֵּי אֲחָיוֹת, זֶה אֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ וְזֶה אֵינוֹ יוֹדֵעַ אֵיזוֹ קִדֵּשׁ, וּמֵתוּ, לְזֶה אָח וּלְזֶה אָח, כָּל אֶחָד חוֹלֵץ לִשְׁתֵּיהֶן; וְאֵין שׁוּם אֶחָד מֵהֶם יָכוֹל לְיַבֵּם. לְזֶה אֶחָד וּלְזֶה שְׁנַיִם; הַיָּחִיד חוֹלֵץ לִשְׁתֵּיהֶן; וְהַשְּׁנַיִם, אֶחָד חוֹלֵץ לְאַחַת תְּחִלָּה, וְאַחַר כָּךְ יְיַבֵּם הַשֵּׁנִי לַשְּׁנִיָּה. וְאִם קָדְמוּ הַשְּׁנַיִם וְכָנְסוּ אַחַר שֶׁחָלַץ הַיָּחִיד, אֵין מוֹצִיאִים מִיָּדָם, אֲפִלּוּ שְׁנֵיהֶם כֹּהֲנִים. הָיוּ לְזֶה שְׁנֵי אַחִים וּלְזֶה שְׁנֵי אַחִים, אָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת, וְאָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת, וְאַחַר כָּךְ הָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה, וָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה. אִם קָדְמוּ שְׁנֵי הָאַחִים שֶׁל הָאֶחָד וְחָלְצוּ לִשְׁתֵּיהֶן, לֹא יְיַבְּמוּ הַשְּׁנֵי אַחִים הָאֲחֵרִים שֶׁל הַשֵּׁנִי לִשְׁתֵּיהֶן, אֶלָּא אֶחָד חוֹלֵץ וְאֶחָד מְיַבֵּם לַשְּׁנִיָּה. קָדְמוּ הַשְּׁנַיִם הָאַחֲרוֹנִים וְכָנְסוּ אַחַר שֶׁחָלְצוּ הַשְּׁנַיִם הָרִאשׁוֹנִים, אֵין מוֹצִיאִין מִיָּדָם:\nמִי שֶׁהָלַךְ בַּעְלָהּ לִמְדִינַת הַיָּם, וְשָׁמְעוּ שֶׁמֵּת, וְנִשֵּׂאת, וְאַחַר כָּךְ בָּא בַּעְלָהּ, וּמֵתוּ שְׁנֵיהֶם, לְזֶה אָח וּלְזֶה אָח, אָחִיו שֶׁל זֶה וְשֶׁל זֶה \u0010c2\u0011 חוֹלְצִים וְלֹא מְיַבְּמִים. \u0005 וְדִין צָרָתָהּ, עַיֵּן לְעֵיל סִי' קע\"ג סָעִיף י\"א: \u0006\nהָאִשָּׁה שֶׁהָיוּ לָהּ בָּנִים וּלְכַלָּתָהּ בָּנִים, וְיָלְדוּ הִיא וְכַלָּתָהּ שְׁנֵי זְכָרִים בְּמַחֲבוֹא, וְנִתְעָרְבוּ הַבָּנִים, וְגָדְלוּ הַתַּעֲרוֹבוֹת וְנָשְׂאוּ נָשִׁים, וּמֵתוּ; בְּנֵי הַכַּלָּה חוֹלְצִין לִשְׁתֵּיהֶן תְּחִלָּה, וְלֹא מְיַבְּמִין; וּבְנֵי הַזְּקֵנָה, אַחַר חֲלִיצַת בְּנֵי הַכַּלָּה, חוֹלְצִין אוֹ מְיַבְּמִין:\nמֵתוּ הַבָּנִים הַוַּדָּאִים שֶׁל הַזְּקֵנָה וְהַכַּלָּה, וְהַסְפֵקוֹת קַיָּמִים; הַסְפֵקוֹת לִנְשֵׁי בְּנֵי הַזְּקֵנָה חוֹלְצִין וְלֹא מְיַבְּמִין; וְלִנְשֵׁי בְּנֵי הַכַּלָּה, אֶחָד מֵהַסְפֵקוֹת חוֹלֵץ לָהּ תְּחִלָּה, וְהַשֵּׁנִי מְיַבֵּם:\nמִי שֶׁלֹּא שָׁהֲתָה אַחַר בַּעְלָהּ ג' חֳדָשִׁים, וְנִשֵּׂאת וְיָלְדָה, וְאֵין יָדוּעַ אִם הוּא בֶּן תִּשְׁעָה לָרִאשׁוֹן אוֹ בֶּן שִׁבְעָה לָאַחֲרוֹן, וְהָיוּ לָהּ בָּנִים מֵהָרִאשׁוֹן וּמֵהַשֵּׁנִי, וְגָדַל הַסָפֵק וְנָשָׂא אִשָּׁה וָמֵת; בָּנֶיהָ מֵהָרִאשׁוֹן וּמֵהַשֵּׁנִי חוֹלְצִים וְלֹא מְיַבְּמִים; וְכֵן הַסָפֵק, לִנְשׁוֹתֵיהֶם חוֹלֵץ וְלֹא מְיַבֵּם. הָיוּ לָרִאשׁוֹן וְלַשֵּׁנִי, לְכָל אֶחָד, בֵּן מֵאִשָּׁה אַחֶרֶת, וּמֵתוּ, זֶה הַסָפֵק חוֹלֵץ אוֹ מְיַבֵּם לִנְשׁוֹתֵיהֶם. מֵת הַסָפֵק, אֶחָד מִשְּׁנֵי הַבָּנִים הַוַּדָּאִים חוֹלֵץ לָהּ תְּחִלָּה, וְהַשֵּׁנִי מְיַבֵּם:\nחָמֵשּׁ נָשִׁים שֶׁהָיָה לְכָל אַחַת בֵּן יָדוּעַ, וְיָלְדוּ כֻּלָּן בְּמַחֲבוֹא, כָּל אַחַת זָכָר, נִתְעָרְבוּ חֲמִשָּׁה הַוְּלָדוֹת וְנָשְׂאוּ נָשִׁים, וּמֵתוּ, וְנָפְלוּ נְשׁוֹתֵיהֶם לִפְנֵי חֲמִשָּׁה הַבָּנִים הַוַּדָּאִים, אַרְבָּעָה מֵהַוַּדָּאִים יַחְלְצוּ לְאַחַת, וְאַחַר כָּךְ יִשָּׂאֶנָּה הַחֲמִישִׁי. וְכֵן עוֹשִׂים לְכָל אַחַת וְאַחַת. וְאִם מֵת אֶחָד מֵהַבָּנִים הַוַּדָּאִים, אַרְבָּעָה הַסְפֵקוֹת יַחְלְצוּ לָהּ, וְאֶחָד יְיַבֵּם. הָיוּ קְצָת הַוַּדָּאִים כֹּהֲנִים, הַכֹּהֲנִים חוֹלְצִים וְלֹא מְיַבְּמִים, וְשֶׁאֵינָם כֹּהֲנִים מְיַבְּמִים. הָיוּ לִקְצָת הַוַּדָּאִים שֶׁיֵּשׁ לָהֶם בְּאֵלּוּ הַסְפֵקוֹת אַחִים מֵהָאֵם שֶׁלֹּא מֵהָאָב, וְגַם יֵשׁ לוֹ בָּהֶם אַחִים מֵהָאָב, \u0005(אַחִים מִן הָאֵם חוֹלְצִין, אַחִים מִן הָאָב מְיַבְּמִין מִקְצָתָן כֹּהֲנִים וּמִקְצָתָן אַחִים מִן הָאֵם, אֵלּוּ וָאֵלּוּ)\u0006 חוֹלְצִים וְלֹא מְיַבְּמִים:",[],["\u0003אין מוציאין אותם מידן\u0004. משום דכ\"א יאמר אני כנסתי את היבמה ואת\"ל שלא כנס היבמה מ\"מ אחר שכנס השני פקע הזיקה ומדייק הרא\"ש דוקא כשכל א' י\"ל אני כנסתי היבמה אבל המייבם אחות זקוקתו יוציא אף לדעת תוס' דס\"ל אם כנס לחופה אל יוציא כמ\"ש בס\"ס קנ\"ט דשם בתחלה קידש אותה ולא בא עליה באיסור ואפשר לומר אפי' אם ליתא כאן אלא אח א' וכנס לאחת ולא חלץ לשני' לא יוציא די\"ל ג\"כ דידי כנסתי ואף את\"ל דלא כנס דידיה מ\"מ פקע הזיקה כיון שכנס אחותה אף על גב שכנס באיסור מ\"מ י\"ל בכה\"ג די\"ל שכנס היבמה לא יוציא מיהו למה שדייק הנ\"י במתניתין דלא תנא באח א' אם כנס לא יוציא היינו שחלץ לא' וכנס לא' לא יוציא דשמא כנס היבמה א\"כ חליצה זו לאו כלום דהא חלץ לשאינה יבמתו מזה דייק אף בכה\"ג יוציא אף על פי שהיא ספק אחות חלוצתו מ\"מ גזרו חז\"ל בחליצה כמו בגרושתו מזה נראה אם כנס בלא חליצה יוציא דאל\"כ אכתי קשה למה לא תנא אם כנס אל יוציא ונראה מכ\"ש אם כנס אחת ואח\"כ חלץ דיוציא דאל\"כ אכתי קשה למה לא תנא אל יוציא גם כאן בתחלה באיסור כנס, ואפשר השתא נמי איסור והכניס' היא אינה יבמתו א\"כ היא אחות חלוצתו ומ\"ש ב\"ח בזה אנ\"ל:","\u0003יוציא\u0004. הטעם הוא כמ\"ש בסק\"א כיון שעבר ועשה איסור מזה מוכח מ\"ש בסימן הקודם בסעיף ג' בשם הטור אין מוציאים ליתא כמ\"ש בב\"ח שם דהא הכא כתב להדיא עבר וייבם יוציא אף על גב בפרישה מחלק ביניהם אנ\"ל ואפילו אם הסכימו שניהם שייבם כ\"א אחת מ\"מ באיסור כנס ול\"ד לדינים שבכאן שנאמר בהם אל יוציא משום דיש לומר שמא דידי כנסתי:","\u0003חולצים ולא מייבמים\u0004. אחיו של הראשון חולץ מדאורייתא ואין מייבם מדרבנן דהא היא כאנוסה, ואחיו של שני חולץ מדרבנן ואין מייבם לא מדאורייתא ולא מדרבנן:"]],["\u0010c0\u0011 הַמְפַתֶּה בְּתוּלַת יִשְׂרָאֵל \u0005 עַד שֶׁלֹּא תִּבָּגֵר, וְהִיא מִבַּת שְׁלשָׁה וְאֵילָךְ \u0006 \u0005(טוּר הָרֹא\"שׁ)\u0006, מְשַׁלֵּם בֹּשֶת וּפְגָם וּקְנָס. \u0010c1\u0011 וְאִם אֲנָסָהּ, מְשַׁלֵּם עוֹד צַעַר. \u0005 וְאִם נְשָׂאָהּ הַמְפַתֶּה, אֵינוֹ צָרִיךְ לִתֵּן קְנָס \u0006 \u0005(טוּר)\u0006:\nאוֹנֵס וּמְפַתֶּה, דָּנִין אוֹתָהּ בִּשְׁלשָׁה דַּיָּנִים, וּבִלְבַד שֶׁיִּהְיוּ סְמוּכִים בְּאֶרֶץ יִשְׂרָאֵל. וְהָאִדָּנָא שֶׁאֵין סְמוּכִים, מְנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס אֶת חֲבֵרוֹ; וְכַד יָהִיב לֵהּ שִׁעוּר מַאי דְּחָזֵי לְמֵיהַב, שָׁרִינָן לֵהּ. \u0005 וְהַבַּת, כָּל זְמַן שֶׁהִיא בִּרְשׁוּת אָבִיהָ, הַכֹּל לְאָבִיהָ \u0006 \u0005(גַּם זֶה שָׁם)\u0006. \u0005 וְעַיֵּן בְּטוּר סִימָן זֶה שֶׁהֶאֱרִיךְ בְּדִינִים אֵלּוּ, וְהָרַב הַמְחַבֵּר קִצֵּר בָּהֶם, שֶׁאֵינָם שְׁכִיחִין: \u0006\nהָאוֹנֵס אֶת הַבְּתוּלָה, חַיָּב לִשָּׂא אוֹתָהּ, וּבִלְבַד שֶׁהִיא וְאָבִיהָ יִהְיוּ מְרֻצִּים, אֲפִלּוּ הִיא חִגֶּרֶת אוֹ סוּמָא, וְאֵינוֹ רַשַּׁאי לְהוֹצִיאָהּ לְעוֹלָם אֶלָּא לִרְצוֹנָהּ. לְפִיכָךְ, אֵינוֹ צָרִיךְ לִכְתֹּב לָהּ כְּתֻבָּה. וְאִם עָבַר וְהוֹצִיאָהּ, כּוֹפִין אוֹתוֹ לְהַחֲזִירָהּ:\nהָיְתָה אֲסוּרָה לוֹ, \u0010c2\u0011 אֲפִלּוּ אִסוּר דְּרַבָּנָן, אֵינוֹ רַשַּׁאי לִשָּׂא אוֹתָהּ. וְכֵן אִם נְשָׂאָהּ וּמָצָא בָּהּ \u0010c3\u0011 עֶרְוַת דָּבָר, \u0010c4\u0011 יְגָרְשֶׁנָּה. \u0005 הַגָּה: יָצָא עָלֶיהָ שֵׁם רַע, כְּגוֹן שֶׁבָּאוּ שְׁנַיִם וְהֵעִידוּ עָלֶיהָ שֶׁתְּבָעָתוֹ לִזְנוּת, אֵין לָהּ קְנָס. אֲבָל מִשּׁוּם קוֹל בְּעָלְמָא עַל שֵׁם רַע שֶׁיָּצָא עָלֶיהָ, לֹא הִפְסִידָה הַקְּנָס \u0006 \u0005(טוּר)\u0006. \u0005 בָּא עָלֶיהָ \u0010c5\u0011 בְּאֹנֶס וְאַחַר כָּךְ פִּתָּה אוֹתָהּ, מִקְּרֵי מְאָנֵס, אַף עַל גַּב דְּאַחַר כָּךְ נִתְרַצֵּית לוֹ \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קכ\"ט)\u0006:\nהַנִּטְעָן עַל הַפְּנוּיָה, יֵשׁ אוֹמְרִים שֶׁלֹּא לִכְנֹס מִשּׁוּם לְזוּת שְׂפָתַיִם, שֶׁנִּרְאֶה שֶׁמַּחֲזִיקִים הַקּוֹל. וְיֵשׁ אוֹמְרִים שֶׁמִּצְוָה לִכְנֹס. \u0005 הַגָּה: וְהַסְּבָרָא רִאשׁוֹנָה עִקָּר. וּבְמָקוֹם שֶׁיֵּשׁ לָחוּשׁ שֶׁלֹּא תֵּצֵא לְתַרְבּוּת רָעָה, מֻתָּר לְכָנְסָהּ. וְכָל זֶה בְּקוֹל בְּעָלְמָא, אֲבָל אִם וַדַּאי בָּא עָלֶיהָ, מִצְוָה לְכָנְסָהּ, אֲבָל \u0010c6\u0011 אֵין כּוֹפִין עַל כָּךְ \u0006 \u0005(שָׁם)\u0006. \u0005 וְאִם נִטְעֶנֶת מִשְּׁנַיִם, מֵרִאשׁוֹן אֵינוֹ אֶלָּא קוֹל בְּעָלְמָא, וְהַשֵּׁנִי הוֹסִיף בִּפְגָמָהּ, הַשֵּׁנִי מִצְוָה לְכָנְסָהּ. וְאִם נִטְעֶנֶת מִשְּׁנֵיהֶם בְּשָׁוֶה, הָאֶחָד נָשׂוּי וְהַשֵּׁנִי אֵינוֹ נָשׂוּי, מִצְוָה עַל שֶׁאֵינוֹ נָשׂוּי לְכָנְסָהּ \u0006 \u0005(ג\"ז שָׁם)\u0006. \u0005 וְעַיֵּן לְעֵיל סִי' כ\"ב אִם הִיא נֶאֱמֶנֶת עָלָיו. \u0010c7\u0011 זוֹנָה \u0006 \u0005 שֶׁתָּבְעָה לְאֶחָד שֶׁנָּדַר לָהּ דָּבָר בְּאֶתְנָנָהּ, וְהוּא כּוֹפֵר, צָרִיךְ לִשָּׁבַע כְּמוֹ בִּשְׁאָר תְּבִיעוֹת \u0006 \u0005(רִיבָ\"שׁ סִי' מ\"א)\u0006. \u0005 זֶהוּ שֶׁחִיְּבָה תּוֹרָה לְאוֹנֵס וּמְפַתֶּה מָמוֹן, הַיְנוּ אִם כְּבָר נַעֲשָׂה הַמַּעֲשֶׂה בְּמִקְרֶה, אֲבָל אָסוּר לָאָב לִתֵּן בִּתּוֹ לִזְנוּת, וְעַל זֶה נֶאֱמַר: \"אַל תְּחַלֵּל אֶת בִּתְּךְ לְהַזְנוֹתָהּ\" \u0010c8\u0011 \u0006 \u0005(וַיִּקְרָא יט, כט)\u0006 \u0005 וְכָל הַמְּכִינָה עַצְמָהּ לִזְנוּת, בֵּין מִדַּעְתָּהּ בֵּין מִדַּעַת אָבִיהָ, הֲרֵי זוֹ קְדֵשָׁה, וְאֵין חִלּוּק בָּזֶה בֵּין בְּתוּלָה לִבְעוּלָהּ \u0006 \u0005(טוּר בְּשֵׁם הָרַמְבַּ\"ם)\u0006. \u0005 וְרַשָּׁאִין הַבֵּית דִּין לִקְנֹס הַזּוֹנוֹת, כְּדֵי לַעֲשׂוֹת גָּדֵר. וּמַעֲשֶׂה בְּאַחַת שֶׁזָּנְתָה עִם הַכּוּתִי, וְחָתְכוּ אֶת חָטְמָהּ, כְּדֵי לְנַוְּלָהּ \u0006 \u0005(תְּשׁוּבַת הָרֹא\"שׁ כְּלָל י\"ח)\u0006:",[],["\u0003המפתה וכו'\u0004. קנס איתא דוקא בבתולה ולו תהיה לאשה משמע נמי דוקא בבתולה אבל בושת משמע ברמב\"ם אפילו בבעולה דהא כתב באו עליה שנים אחד כדרכה והשני שלא כדרכה חייב השני בבושת אף על גב דכבר היא בעולה מראשון ומפותה דקרא איירי כשמפתה לשם אישות כמ\"ש בקידושין דף מ\"ו ובמהרי\"ק שורש קכ\"ט ומ\"מ יכולה למאן וא\"צ לישא אותה ופטור ג\"כ מקנס ובושת ופגם כשהיא יתומה ולא אמרי' מחילה בטעות דנתרצה את עצמה כדי שישא אחותה ע\"ש במהרי\"ק:","\u0003ואם אנסה\u0004. עיין ברמב\"ם ובטור אם ראו עדים מרחוק שבעל אותה וא\"י אם אנוסה היא או מפותה אמרינן בשדה מסתמא אנוסה היא ובעיר מסתמא מפותה היא והט\"ז רוצה ליישב דברי הרמב\"ם דאיירי דליכא כאן העדים שראו הביאה ולא אמרינן בכה\"ג מודה בקנס פטור כיון דמודה מחמת ביעתותא כראב\"ש בפרק מרובה (בבא קמא דף ע\"ה) והלכתא כוותי' דשמואל ס\"ל כוותי' וע\"ש וליתא כי שמואל אינו מחלק בין ביעתות' אלא יבואו העדים ויעידו אלא רב מתרץ כן אנא דאמרי לראב\"ש והלכה כרב לענין מודה ואח\"כ באו עדים כמו שכתב הרמב\"ם פ\"ג מה\"ג ובפלוגת' זו מחמת ביעתותא מסתמ' הלכה כת\"ק דפטור משום הכי לא מחלק הרמב\"ם שם:","\u0003איסור דרבנן\u0004. אשה אסור' ממועט מקרא ולו תהי' לאשה אשה הראיי' לו ואם אסורה מדרבנן אף על גב מדאורייתא אשה ראויה היא מ\"מ מדכתיב ושמרתם את משמרתי מצאו חכמים מקום לאסור שניו' שפיר י\"ל דממועט מקרא ולו תהי' לאשה ובלאו הכי כיון דכל מילי דרבנן אסמכינהו אלאו לא תסיר שפיר א\"ל דשניה ממועט מקרא ולו תהי' לאשה ב\"י:","\u0003ערות דבר\u0004. היינו ערוה ממש ולאו ערות דבר כמ\"ש בסי' קי\"ט אפי' דבר בלא ערוה אלא כאן דוקא ערוה, פרישה:","\u0003יגרשנ'\u0004. כ\"כ הרמב\"ם פ\"א ומשמע דצריך לגרשה ובטור אית' יכול לגרשה משמע אם אין רוצה לגרשה לא כפינן ליה ועיין ב\"ח:","\u0003ואח\"כ פתה אותה\u0004. הן בביא' אם היתה בתחל' באונס ואח\"כ ברצון הן אם פ\"א בא עלי' באונס ואח\"כ ברצון חייב מחמת ביאה הראשונה אף על גב דנתרצית אח\"כ:","\u0003אין כופין על כך\u0004. דקי\"ל מפותה בין היא ובין הוא יכולים לעכב ואם נטען שאנס אות' דאז הוא א\"י לעכב מ\"מ אין כופין אותו כיון דאינו אלא חשד אבל אם בוודאי בא עליה כופין אותו בזה יש חילוק בין אונס למפת':","\u0003זונה שתבעה לאחד\u0004. ואם נדר לזונה שהי' לו חייבי מיתות ב\"ד אז פטור לשלם ע\"פ הדין מ\"מ אין יוצא ידי שמים עד שישלם לה ואם תפסה אין מוציאין ממנה רש\"י פ' האומנים:","\u0003וכל המכינ' עצמה וכו'\u0004. לכאור' סותר למ\"ש בסי' ט\"ז דכאן משמע דוקא כשהוא מוכנת לזנות עם כל אדם הוי קדשה ועיין מ\"ש שם:"]],["הַמְקַנֵּא אֶת אִשְׁתּוֹ, וְנִסְתְּרָה, וְאֵינוֹ יוֹדֵעַ אִם נִטְמֵאָה, \u0010c0\u0011 אֲסוּרָה לוֹ. וּבִלְבַד שֶׁיְּהֵא הַקִּנּוּי וְהַסְתִירָה כָּרָאוּי, וְאָז הִפְסִידָה כְּתֻבָּתָהּ, אֲפִלּוּ מֵת קֹדֶם שֶׁגֵּרְשָׁהּ:\nכֵּיצַד הַקִּנּוּי, אוֹמֵר לָהּ בִּפְנֵי שְׁנַיִם: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, \u0010c1\u0011 אֲפִלּוּ אִם הוּא אָבִיהָ אוֹ אָחִיהָ אוֹ כּוּתִי אוֹ שָׁחוּף \u0005 פֵּרוּשׁ, שֶׁאֵינוֹ מִתְקַשֶּׁה \u0006 \u0005(טוּר)\u0006, וְהוּא שֶׁיְּהֵא גָּדוֹל. אֲבָל אִם אָמַר לָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי, \u0005 וְהוּא \u0006 קָטָן אוֹ בְּהֵמָה, לָא הָוֵי קִנּוּי. וּמְקַנֵּא לָהּ בֵּין אִם הִיא אֲרוּסָה בֵּין אִם הִיא נְשׂוּאָה אוֹ זְקוּקָה לְיָבָם:\nקְטַנָּה שֶׁהִשִּׂיאָהּ אָבִיהָ וְזִנְּתָה לִרְצוֹנָהּ, \u0010c2\u0011 יֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֲסוּרָה לְבַעְלָהּ. לְפִיכָךְ מְקַנְּאִין לָהּ, כְּדֵי לְהַפְסִידָהּ כְּתֻבָּתָהּ. וְיֵשׁ מִי שֶׁאוֹמֵר, שֶׁאֵינוֹ נֶאֱסֶרֶת עַל בַּעְלָהּ, אֶלָּא אִם כֵּן הוּא כֹּהֵן. \u0005 הַגָּה: גְּדוֹלָה שֶׁזָּנְתָה בְּשׁוֹגֵג, שֶׁסָּבְרָה שֶׁבַּעְלָהּ הוּא, וְהוּא אַחֵר, מֻתֶּרֶת לְבַעְלָהּ יִשְׂרָאֵל \u0006 \u0005(הָרַמְבַּ\"ם פכ\"ד דְּאִשּׁוּת)\u0006. \u0005 אֲבָל \u0010c3\u0011 זָנְתָה שֶׁסָּבְרָה שֶׁמֻּתָּר \u0006 \u0005 לִזְנוֹת, הָוֵי כִּמְזִידָה וַאֲסוּרָה לְבַעְלָהּ יִשְׂרָאֵל \u0006 \u0005(מַהֲרִי\"ק שֹׁרֶשׁ קס\"ז)\u0006. \u0005 אִשָּׁה שֶׁנִּתְיַחֲדָה עִם אֲנָשִׁים בַּדֶּרֶךְ, וּבָאָה וְאָמְרָה: נִתְיַחַדְתִּי וְנֶאֱנַסְתִּי, יֵשׁ אוֹמְרִים דְּנֶאֱמֶנֶת, בְּמִגּוֹ דְּאָמְרָה: לֹא נִבְעַלְתִּי, וְיֵשׁ אוֹמְרִים דְּאָבְדָה מִגּוֹ שֶׁלָּהּ, הוֹאִיל וְנִתְיַחֲדָה שֶׁלֹּא כַּדִּין \u0006 \u0005(שְׁנֵי הַדֵּעוֹת בְּמָרְדְּכַי פֶּרֶק שֵׁנִי דִּכְתֻבּוֹת)\u0006:\nכֵּיצַד הִיא הַסְתִירָה, שֶׁנִּסְתְּרָה בִּפְנֵי עֵדִים עִם אוֹתוֹ פְּלוֹנִי שֶׁקִּנֵּא לָהּ, וְשָׁהֲתָה כְּדֵי טֻמְאָה, שֶׁהִיא כְּדֵי לִצְלוֹת בֵּיצָה וּלְגָמְעָהּ:\nקִנֵּא לָהּ מִשְּׁנַיִם, שֶׁאָמַר לָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי וּפְלוֹנִי, וְנִסְתְּרָה עִם שְׁנֵיהֶם כְּאֶחָד, אֲפִלּוּ הֵם שְׁנֵי אַחִים [אַחֶיהָ], אוֹ אָבִיהָ וְאָחִיהָ, אֲסוּרָה:\nאָמַר לָהּ בִּפְנֵי שְׁנַיִם: אַל תְּדַבְּרִי עִם אִישׁ פְּלוֹנִי, אֵין זֶה קִנּוּי; אֲפִלּוּ נִסְתְּרָה עִמּוֹ וְשָׁהֲתָה עִמּוֹ כְּדֵי טֻמְאָה, מֻתֶּרֶת. וְכֵן אִם אָמַר לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, וְדִבְּרָה עִמּוֹ בִּפְנֵי עֵדִים, \u0010c4\u0011 מֻתֶּרֶת. וְכֵן אִם נִסְתְּרָה בִּפְנֵי עֵדִים וְשָׁהֲתָה כְּדֵי טֻמְאָה עִמּוֹ, וְלֹא קִנֵּא לָהּ בִּפְנֵי עֵדִים, מֻתֶּרֶת, שֶׁאֵין אוֹסְרִים עַל \u0010c5\u0011 הַיִּחוּד אֲפִלּוּ נִסְתְּרוּ יַחַד עַל דַּעַת עֶרְוָה, אֶלָּא אִם כֵּן קִנֵּא לָהּ תְּחִלָּה בִּפְנֵי שְׁנַיִם. וּמִכָּל מָקוֹם לֹא תִּתְיַחֵד אִשָּׁה עִם אֲנָשִׁים, כְּמוֹ שֶׁנִּתְבָּאֵר \u0005 לְעֵיל סִימָן כ\"ב: \u0006\nלֹא יֹאמַר אָדָם לְאִשְׁתּוֹ, וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ: אַל תִּסָתְרִי עִם פְּלוֹנִי, דִלְמָא קַיְמָא לָן כְּרַבִּי יוֹסִי בְּרַבִּי יְהוּדָה דְּאָמַר: קִנֵּא לָהּ בֵּינוֹ לְבֵינָהּ הָוֵי קִנּוּי, \u0005 הַגָּה: וְעַכְשָׁו אֵין לָנוּ מֵי סוֹטָה, וְאִם נִסְתְּרָה אַחַר הַקִּנּוּי, אֲסוּרָה לוֹ לְעוֹלָם \u0006 \u0005(טוּר בְּשֵׁם סְמַ\"ג)\u0006. \u0005 וְאִם שָׁכַח וְקִנֵּא לָהּ, יִמְחַל לָהּ מִיָּד עַל הַקִּנּוּי \u0006 \u0005(א\"ז)\u0006, \u0005 כְּמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סִימָן זֶה סָעִיף י\"ב: \u0006\nבָּא עֵד אֶחָד וְהֵעִיד לוֹ שֶׁנִּסְתְּרָה עִם אוֹתוֹ שֶׁקִּנֵּא לָהּ, וְשָׁהֲתָה כְּדֵי \u0010c6\u0011 טֻמְאָה, אִם הוּא נֶאֱמָן בְּעֵינָיו וְדַעְתּוֹ סוֹמֶכֶת עָלָיו, יוֹצִיא וְיִתֵּן כְּתֻבָּה. וְאִם לָאו, מֻתֶּרֶת לוֹ. וְאִם הוּא בְּעַצְמוֹ רָאָה שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה עִמּוֹ כְּדֵי טֻמְאָה, הֲרֵי זוֹ אֲסוּרָה עָלָיו וְיוֹצִיא וְיִתֵּן כְּתֻבָּה. \u0005 וְאֵין חִלּוּק לְעִנְיַן סְתִירָה שֶׁאַחַר קִנּוּי בֵּין בַּעְלָהּ בָּעִיר וּפֶתַח פָּתוּחַ לִרְשׁוּת הָרַבִּים אוֹ לֹא \u0006 \u0005(עַיֵּן בְּמהרא\"י סִי' רמ\"ד)\u0006 \u0005 וְעַיֵּן לְעֵיל סִי' כ\"ב: \u0006\nלֹא קִנֵּא לָהּ, וּבָא עֵד אֶחָד וְאָמַר לוֹ: \u0010c7\u0011 זִנְּתָה, וְהִיא שׁוֹתֶקֶת, אִם הוּא נֶאֱמָן בְּעֵינָיו וְדַעְתּוֹ סוֹמֶכֶת עָלָיו כִּשְׁנַיִם, יוֹצִיא וְיִתֵּן כְּתֻבָּה; וְאִם לָאו, מֻתֶּרֶת לוֹ. \u0005 הַגָּה: וְהוּא הַדִּין אִם הִיא עַצְמָהּ אוֹמֶרֶת לוֹ שֶׁזָּנְתָה, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן קט\"ו סָעִיף ו'. וְיֵשׁ אוֹמְרִים, דְּבַזְּמַן הַזֶּה שֶׁיֵּשׁ חֵרֶם רַבֵּנוּ גֵּרְשֹׁם שֶׁלֹּא לְגָרֵשׁ אִשָּׁה בְּעַל כָּרְחָהּ, אֵינוֹ נֶאֱמָן לוֹמַר שֶׁמַּאֲמִינָה אוֹ שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד \u0006 \u0005(הַגָּהוֹת מַיְמוֹנִי פכ\"ד וּמַהֲרִי\"ק שֹׁרֶשׁ ק\"י בְּשֵׁם י\"א)\u0006, \u0005 דְּחַיְשִׁינָן שֶׁמָּא עֵינָיו נָתַן בְּאַחֶרֶת, וְאוֹמֵר שֶׁמַּאֲמִינָהּ אַף עַל פִּי שֶׁאֵינוֹ מַאֲמִין; \u0010c8\u0011 וּמְנַדִּין אוֹתוֹ עַל שֶׁאוֹמֵר שֶׁמַּאֲמִינָהּ וְגָרַם לְבַטֵּל חֵרֶם רַבֵּנוּ גֵּרְשׁוֹם. וְהוּא הַדִּין בְּכָל מָקוֹם שֶׁלֹּא יוּכַל לְגָרֵשׁ בְּלֹא דַּעַת הָאִשָּׁה. וְיֵשׁ אוֹמְרִים דְּכוֹפִין אוֹתוֹ וּמְשַׁמֵּשׁ עִמָּהּ \u0006 \u0005(מָרְדְּכַי פֶּרֶק הָאוֹמֵר)\u0006, \u0005 אַף עַל פִּי שֶׁאוֹמֵר שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד, מֵאַחַר שֶׁהָאִשָּׁה אֵינָהּ מוֹדָה, אוֹ אֲפִלּוּ אָמְרָה בְּעַצְמָהּ: טְמֵאָה אֲנִי לְךְ, וְחָזְרָה וְנָתְנָה אֲמַתְלָא לִדְבָרֶיהָ הָרִאשׁוֹנִים, כֵּן נִרְאֶה לִי עַל פִּי סְבָרָא זוֹ. אֲבָל יֵשׁ חוֹלְקִים וּסְבִירָא לְהוּ דְּאַף בַּזְּמַן הַזֶּה, נֶאֱמָן \u0006 \u0005(שָׁם בַּמַהֲרִי\"ק, וְכֵן מַשְׁמַע מֵהָרַמְבַּ\"ם פכ\"ד)\u0006. \u0005 וְאִם הָיָה לוֹ קֶטֶט עִמָּהּ, אֵינוֹ נֶאֱמָן לוֹמַר שֶׁמַּאֲמִין לְדִבְרֵי הָעֵד, דְּוַדַּאי מֵחֲמַת שִׂנְאָה אוֹמֵר כֵּן \u0006 \u0005(שָׁם בַּמַּהֲרִי\"ק)\u0006. \u0005 וְעַיֵּן לְעֵיל סִימָן קט\"ו סָעִיף ז': \u0006\nמִי שֶׁהוֹצִיא קוֹל עַל אִשְׁתּוֹ, שֶׁזִּנְּתָה, וְאָמַר שֶׁנִּתְבָּרֵר לוֹ הַדָּבָר, וְאַחַר כָּךְ אָמַר אֵינוֹ אֱמֶת, אֶלָּא שֶׁמֵּחֲמַת הַכַּעַס שֶׁהִכְעִיסַתּוּ הוֹצִיא קוֹל זֶה; אִם נוֹתֵן אֲמַתְלָא לִדְבָרָיו, מֻתֶּרֶת; וְאִם לָאו, אֲסוּרָה לוֹ:\nשָׁמַע הָעָם מְרַנְּנִים אַחַר \u0010c9\u0011 הַקִּנּוּי, וְהַסְתִירָה בְּלֹא שְׁנֵי עֵדִים, עַד שֶׁהַנָּשִׁים נוֹשְׂאוֹת וְנוֹתְנוֹת בָּהּ שֶׁזִּנְּתָה מֵהָאִישׁ שֶׁקִּנֵּא לָהּ, אֲסוּרָה לוֹ, וְיוֹצִיאֶנָּה וְיִתֵּן כְּתֻבָּה:\nבַּעַל שֶׁמָּחַל עַל קִנּוּי, קֹדֶם סְתִירָה, קִנּוּיוֹ מָחוּל וּכְאִלּוּ לֹא קִנֵּא לָהּ. אֲבָל לְאַחַר סְתִירָה, אֵין קִנּוּיוֹ מָחוּל. גֵּרְשָׁהּ, הֲרֵי זֶה כְּאִלּוּ מָחַל לָהּ; וְאִם הֶחֱזִירָהּ, צָרִיךְ לְקַנֹּאת לָהּ פַּעַם אַחֶרֶת:\nמִי שֶׁנִּתְחָרֵשׁ בַּעְלָהּ אוֹ נִשְׁתַּטָּה, אוֹ הָיָה בִּמְדִינָה אַחֶרֶת, אוֹ שֶׁהָיָה חָבוּשׁ בְּבֵית הָאֲסוּרִים, וְשָׁמְעוּ בֵּית דִּין מְרַנְּנִים אַחֲרֶיהָ, קוֹרְאִים וְאוֹמְרִים לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי. וְאִם בָּאוּ עֵדִים אַחַר כָּךְ שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה כְּדֵי טֻמְאָה, אוֹסְרִים אוֹתָהּ עַל בַּעְלָהּ לְעוֹלָם, וְקוֹרְעִים כְּתֻבָּתָהּ. וּכְשֶׁיָּבֹא בַּעְלָהּ אוֹ יַבְרִיא אוֹ יֵצֵא מִבֵּית הָאֲסוּרִים, יִתֵּן לָהּ גֵּט: \u0010c10\u0011\nבָּא עֵד אֶחָד וְהֵעִיד שֶׁנִּטְמְאָה מֵאוֹתוֹ שֶׁקִּנֵּא לָהּ, תֵּצֵא בְּלֹא \u0010c11\u0011 כְּתֻבָּה. אֲפִלּוּ אִם עֵד הַטֻּמְאָה הוּא אֶחָד מֵעֵדֵי הַסְתִירָה, וַאֲפִלּוּ עֶבֶד אוֹ שִׁפְחָה אוֹ אִשָּׁה אוֹ קָרוֹב, כָּשֵׁר לְעֵדוּת:\nחָמֵשׁ נָשִׁים שֶׁשּׂוֹנְאוֹת אוֹתָהּ, נֶאֱמָנוֹת עָלֶיהָ לוֹמַר שֶׁנִּטְמֵאת אַחַר הַקִּנּוּי לְאָסְרָהּ עַל בַּעְלָהּ, אֲבָל לֹא לְהַפְסִידָהּ כְּתֻבָּתָהּ:\nמוֹצִיאִים עַל יְדֵי עֵדֵי טֻמְאָה, אֲפִלּוּ לֹא רָאוּ כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת, מֵאַחַר שֶׁרָאוּ אוֹתָם דְּבוּקִים זֶה בָּזֶה וְנוֹהֲגִים כְּדֶרֶךְ הַמְנָאֲפִים:\nכָּל אִשָּׁה שֶׁנֶּאֶסְרָה עַל בַּעְלָהּ עַל יְדֵי קִנּוּי וּסְתִירָה, אֲסוּרָה גַּם לְאוֹתוֹ שֶׁנֶּאֶסְרָה בִּשְׁבִילוֹ. וְאִם עָבַר וּנְשָׂאָהּ, מוֹצִיאִין אוֹתָהּ מִתַּחְתָּיו בְּגֵט, אֲפִלּוּ הָיוּ לָהּ כַּמָּה בָּנִים מִמֶּנּוּ. אֲבָל אִם לֹא קָדַם קִנּוּי, וּבָאוּ עֵדִים שֶׁנִּסְתְּרָה עִם אִישׁ זֶה, וּבָאוּ וּמָצְאוּ דָּבָר מְכֹעָר, נִתְבָּאֵר בְּסִי' י\" א:\nכָּל אִשָּׁה שֶׁבָּאוּ שְׁנֵי עֵדִים וְהֵעִידוּ שֶׁזִּנְּתָה עִם זֶה כְּשֶׁהָיְתָה תַּחַת בַּעְלָהּ, הֲרֵי זוֹ תֵּצֵא מִזֶּה, וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ מִמֶּנּוּ כַּמָּה בָּנִים:\nיֵשׁ אוֹמְרִים שֶׁאֵשֶׁת אִישׁ שֶׁזִּנְּתָה עִם כּוּתִי וְגֵרְשָׁהּ בַּעְלָהּ, וְנִתְגַּיֵּר הַכּוּתִי, שֶׁמֻּתֶּרֶת לַגֵּר הַזֶּה, \u0010c12\u0011 דְּלֹא שַׁיָּךְ לְמֵימַר \"אֶחָד לַבּוֹעֵל\" בְּבִיאַת הַכּוּתִי. \u0005 הַגָּה: וּמִכָּל מָקוֹם מִי שֶׁזִּנָּה עִם אֲחוֹת אִשְׁתּוֹ, וְגֵרְשָׁהּ בַּעְלָהּ, אֲסוּרָה לַבּוֹעֵל אַחַר מִיתַת אִשְׁתּוֹ. אַף עַל גַּב דִּבְלָאו הָכִי הָיְתָה אֲסוּרָה לוֹ כְּשֶׁזִּנְּתָה עִמּוֹ \u0006 \u0005(פִּסְקֵי מהרא\"י סִי' כ\"ט)\u0006:\nאֵשֶׁת אִישׁ שֶׁטּוֹעֶנֶת עַל אִישׁ אֶחָד שֶׁהוּא רוֹדֵף אַחֲרֶיהָ, וְהוּא מַכְחִישָׁהּ, אֵין לְהַאֲמִינָהּ כְּדֵי לְיַסְרוֹ; אֲבָל יִגְזְרוּ עָלָיו נִדּוּי, שֶׁלֹּא יְדַבֵּר עִמָּהּ כְּלָל, וְשֶׁלֹּא יָדוּרוּ בִּשְׁכוּנָה אַחַת. וְאִם הוּא מֻחְזָק בְּעֵינֵיהֶם לְחָשׁוּד עַל הָעֲרָיוֹת, רָאוּי לִגְעֹר בּוֹ בִּנְזִיפָה וּלְאַיֵּם עָלָיו שֶׁאִם לֹא יִתְנַהֵג כַּשּׁוּרָה יַבְדִּילוּהוּ מִבֵּינֵיהֶם לְרָעָה וְיִדְחוּהוּ בִּשְׁתֵּי יָדַיִם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵנוּ זַ\"ל: מַלְקִין עַל לֹא טוֹבָה הַשְּׁמוּעָה, וּכְמוֹ שֶׁכָּתַב הָרַמְבַּ\"ם בְּפֶרֶק כ\"ד מִסַנְהֶדְרִין:\nמִצְוַת חֲכָמִים עַל בְּנֵי יִשְׂרָאֵל \u0010c13\u0011 לְקַנְּאוֹת לִנְשׁוֹתֵיהֶם. וְכָל מִי שֶׁאֵינוֹ מַקְפִּיד עַל אִשְׁתּוֹ וְעַל בָּנָיו וּבְנֵי בֵּיתוֹ וּמַזְהִירָם וּפוֹקֵד דַּרְכֵיהֶם תָּמִיד עַד שֶׁיֵּדַע שֶׁהֵם שְׁלֵמִים מִכָּל חֵטְא וְעָוֹן, הֲרֵי זֶה חוֹטֵא, שֶׁנֶּאֱמַר: \"וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא\" \u0005(אִיּוֹב ה, כד)\u0006. וְכָל הַמְקַנֵּא אֶת אִשְׁתּוֹ נִכְנְסָה בּוֹ רוּחַ טָהֳרָה. וְלֹא יְקַנֵּא לָהּ מִתּוֹךְ שְׂחוֹק, וְלֹא מִתּוֹךְ שִׂיחָה, וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ, וְלֹא מִתּוֹךְ מְרִיבָה, וְלֹא לְהָטִיל עָלֶיהָ אֵימָה. וְאִם עָבַר וְקִנֵּא לָהּ בִּפְנֵי עֵדִים מִתּוֹךְ אֶחָד מִכָּל הַדְּבָרִים הָאֵלּוּ, הֲרֵי זֶה קִנּוּי:\nאֵין רָאוּי לִקְפֹּץ וּלְקַנְּאָהּ בִּפְנֵי עֵדִים תְּחִלָּה. וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ לָא יֹאמַר לָהּ: אַל תִּסָתְרִי עִם אִישׁ פְּלוֹנִי, כְּמוֹ שֶׁנִּתְבָּאֵר. אֶלָּא מוֹכִיחַ אוֹתָהּ בֵּינוֹ לְבֵינָהּ, בְּנַחַת וּבְדֶרֶךְ טָהֳרָה וְאַזְהָרָה, כְּדֵי לְהָסִיר הַמִּכְשׁוֹל וּלְהַדְרִיכָהּ בְּדֶרֶךְ יְשָׁרָה:",[],["\u0003אסורה לו\u0004. ואסור להתייחד עמה תשו' הרא\"ש כלל ל\"ב ועיין סי' קי\"ז:","\u0003אפילו אם הוא אביה\u0004. אף על גב יחוד מותר עם אביה מ\"מ כשמקנא לה אסור להתייחד עמו:","\u0003יש מי שאומר שאסורה לבעלה\u0004. היינו דעת הרמב\"ם וס\"ל כשהשיאה אמה ואחיה אז לא הוי קידושין מדאורייתא וכאלו זנתה כשהיא פנויה ומותרת אפילו לכהן משא\"כ כשאביה השיאה אז הוי נשואי' דאורייתא ואסורה לבעלה ישראל, ויש מי שאומר השני כן ס\"ל לרוב הפוסקים וכן הוא דעת תוס' וס\"ל פיתוי דקטנה הוי כאונס ומותרת לבעלה ישראל ואסורה לבעלה כהן ואם בא עליה באונס והבועל הוא ישראל ובעלה כהן עיין בסי' י\"א מ\"ש ועיין סימן קצ\"ט:","\u0003שסברה שמותר לזנות\u0004. דלא כתיב ומעלה מעל בה' אלא ומעלה בו מעל כל שהיא מתכוונת למעול בו אסורה ובזה מיושב דלא תקשה הא אומר מותר הוי כשוגג ועיין בט\"ז בי\"ד סי' צ\"ט, ואם זינתה ברצון כדי להציל נפשות כעובדת אסתר לאחשורוש אסורה לבעלה כיון שביאה היה ברצון שם במהרי\"ק וכן אם סבורה דלא היה קדושין מה שא' נתן לה טבעת לקידושין ועיין תשו' הרשב\"א ועיין ב\"י ס\"ס ק':","\u0003וכן אם נסתרה בפני עדים וכו'\u0004. לכאורה נשמע מבבא קמייתא כשאמר אל תדברי ונסתרה אלא די\"ל שם גילה דעתו דאין לו קפידא בסתירה:","\u0003אפילו נסתרה יחד ע\"ד ערוה\u0004. עיין מ\"ש סי' ז' סעיף י\"א בהג\"ה דפוסק אם נתייחדה לשם זנות יש להחמיר:","\u0003אם הוא נאמן בעיניו\u0004. כאן לא כתב והיא שותקת משמע אילו במכחשתו צריך להוצי' כיון דהיה קינוי ועיין פרישה:","\u0003והיא שותקת\u0004. כן הוא גירסת הב\"י ועיין סימן קט\"ז ולדעת מהרש\"ל כשהיא שותקת אפילו א\"נ בעיניו כשנים חייב להוציא' כיון דהיא שותקת אלא גירסתו והוא הבעל שותק אז אם הוא נאמן כתרי בעיניו חייב הוציאה ואם הוא אומר מנ\"ל זאת וכיוצא בו אין חייב להוציאה אלא משום לזות שפתיים עיין ב\"ח ודרישה בסימן זה ובסימן קט\"ו:","\u0003ומנדין אותו וכו'\u0004. עיין במהרי\"ק שורש ק\"י הביא ב' דיעות בזה אם מנדין אותו לדעת תוס' מנדין אותו כי הוא נאמן לומר שמאמין לדברי העד א\"כ גורם לבטל תקנות ר\"ג מ\"ה מנדין אותו אבל לדעת הפוסקי' שהביא הרב רמ\"א דאין נאמן לומר דמאמין לדברי העד א\"י מנ\"ל דמנדין אותו מאחר דליכא כאן עקירת תקנת ר\"ג:","\u0003והסתירה בלא שני עדים\u0004. כ\"כ בכ\"מ ע\"כ הסתירה לא היה בעדים דאל\"כ כבר מבואר ברמב\"ם כשהקינוי וסתירה היה בעדים תצא בלא כתובה אלא ודאי דאיירי דלא היה עדים אלא שמע מנשים הנושאות ונותנות בה ואז לא הוי כעדים על הסתירה אלא הואיל ודבר מכוער הוא תצא ויתן לה הכתובה וכן הוא לפרש\"י שם, ובתו' שם י\"ל לפי קושי' שלהם דמים לא בדקו כשנושאים ונותנים נשים בה אז א\"צ ליתן לה הכתובה לפ\"ז בזה\"ז פשיטא דפטור הוא ליתן לה הכתובה מיהו לפי תירוצים שלהם י\"ל דס\"ל נמי כרש\"י:","\u0003בא ע\"א והעיד וכו'\u0004. הואיל ויש רגלים לדבר דהיה כבר קינוי בעדים וסתירה בעדים מ\"ה ע\"א נאמן ודוקא כשמעיד שזינתה עם זה שקינא לה גם משמע מרש\"י דוקא שמעיד שזינתה באותו פעם כשנסתרה עמו ע\"פ ב' עדים, מיהו קשה למה לי עדות העד ת\"ל אם קינא ונסתרה אסורה לבעלה ואין לה כתובה בשלמא בש\"ס לק\"מ דקמ\"ל דאינה שותה אלא לפסק הש\"ע קשה מה נ\"מ מעדותו וע' ברמב\"ם ובטור דכתבו אם אחר שהעיד ע\"א שנטמאה בא ע\"א ומכחישו לא משגיחין בו דע\"א בסוטה נאמן כתרי ואין ע\"א נאמן נגד שני עדים ולכאורה קשה דהא כתב הרמב\"ם פי\"ב מה\"ג והטור בסי' י\"ז דוקא כשמעיד העד ופסקו הב\"ד על פיו אז הוי כתרי אבל כל זמן שלא פסקו על פיו לא אמרינן דהו' כתרי וכ\"כ תוס' בסוגי' דאיירי דפסקו הב\"ד ע\"פ עדותו א\"כ למה כתבו הם מיד אחר שהעיד הוי כתרי אפי' לא פסקו ע\"פ, שוב ראיתי בתוס' פ\"ב דכתובות כתבו היכא דע\"א מדאורייתא נאמן הוי כתרי אפי' לא פסקו הב\"ד ע\"פ אבל היכא דנאמן מדרבנן אז לא הוי כתרי אא\"כ פסקו על פיו בזה שפיר מ\"ש הרמב\"ם והטור כי הם ס\"ל ג\"כ כתוס' אלו ובי\"ד סי' קכ\"ז מחלק בש\"ך מסברא דעצמו כן, וע' מ\"ש ס\"ס י\"ד:","\u0003אפי' אם עד הטומאה הוא א' מעידי הסתירה\u0004. וה\"א לומר כיון שראה שנסתרו יחדיו לא דקדק היטב אם בעיל אותה וסבר בודאי בעיל קמ\"ל כ\"כ ב\"ח גם י\"ל דה\"ק אפי' אם הוא אחד מעידי סתירה ואמר שאותו פעם בעיל אותה ועד השני לא אמר שראה הביאה מיהו אינו מכחיש אותו אלא אמר שלא ראה ולא שם על לבו לראות כ\"כ אבל אם מכחיש אותו אף על גב שהיה הסתירה בודאי לא הפסידה הכתובה:","\u0003דלא שייך למימר אחד לבועל\u0004. הואיל ואסור לה בל\"ז ולא שייך בו קידושין אא\"כ אחר שנתגייר ואז הוי כגוף אחר אבל אם בא על אחות אשתו ראוי היא לו אחר שתמות אשתו שם בפסקי מהרא\"י:","\u0003לקנאות לנשותיהם\u0004. לאו קינוי ממש קאמר אלא להוכיח אותה ויזהר אותה שאל תסתיר עם אנשים בזה שפיר דלא תקשי ממ\"ש בסעיף ז' ועיין פרישה:"]]]};
